pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space nonlinearly (worst between 1 and ~20).
        let pr = post_residual as f64;
        score += 40.0 * (1.0 - (pr / 30.0)).exp() * (30.0 / pr).min(3.0);
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let tightness = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 25.0 + 30.0 * tightness;
        } else {
            // Post-residual too small for next item: dead-space risk.
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mild bias against proliferating bins early in the stream.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for tighter bins overall.
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is small and unlikely to fit future items.
    if post_residual > 0 {
        let dead_threshold = 20.0f64;
        if (post_residual as f64) <= dead_threshold {
            // The smaller (but nonzero) the gap, the worse: quadratic blowup.
            let deadness = (dead_threshold - post_residual as f64 + 1.0).powi(2);
            score += 3.0 * deadness;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids wasted capacity elsewhere).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * next_fit_quality;
    }
    // If next item will NOT fit in the residual, the gap is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first),
    // keeping large-residual bins available for large future items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // New-bin candidate handling: empty bin gets a base cost so it only wins
    // when all open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening fresh bins is less useful; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the minimum item size are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits the residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize residual that cannot host the next item but is still large-ish
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: more open bins -> prefer reusing existing bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score = 50.0 - fit_quality * 20.0 + open_bins_count as f64 * 0.2;
        if post_residual == 0 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: how well the leftover decomposes
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals that few item sizes can use
    // Items are 1..100; a residual r is usable by items of size <= r.
    // Penalize residuals in "hard" bands: just above common item sizes.
    let dead = if pr > 0 && pr < 20 { 40.0 } else if pr > 50 && pr < 60 { 10.0 } else { 0.0 };
    score += dead;

    // Modulo-class logic: residuals that are multiples of 10 (or 25) are
    // more reusable under typical discrete size streams.
    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily (perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after pairing
            let pr2 = post_residual - next_item_size;
            score -= 30.0 + (pr2 as f64).min(50.0) * 0.5;
            if pr2 % 10 == 0 { score -= 8.0; }
        } else {
            // next item won't fit here: penalize if gap is small (wasted near-fit)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when current fit is poor or mean residual is low.
    if bin_residual == bin_capacity {
        // base score for a fresh bin = post_residual (100). Calibrate against
        // typical open-bin scores: prefer new bin when mean residual is small
        // or item is large relative to mean residual.
        let pressure = (item_size as f64) / mean_residual.max(1.0);
        score -= 25.0 + pressure * 30.0 + (open_bins_count as f64) * 2.0;
        // late in stream, prefer closing out open bins rather than spawning
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        score += progress * 20.0;
    }

    // Mild preference to fill bins with low residual among open bins
    score -= (bin_residual as f64) * 0.05;

    // Fractional coupling: prefer post_residual near small capacity fractions
    if (frac - 0.1).abs() < 0.05 || (frac - 0.2).abs() < 0.05 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized,
    // since they can never host any realistic item.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }
    // Perfect fit: post_residual == 0 -> strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual >= 13 {
        // Usable residual: mild reward proportional to usefulness of the gap.
        score -= 10.0;
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * pressure * (1.0 - fill_ratio);

    // Lookahead: if next item fits in the post residual, reward; if not,
    // penalize leaving a gap that wastes space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is already "tight" -> favor completing it.
    let residual_dev = mean_residual - bin_residual as f64;
    score += residual_dev * 0.3;

    // New-bin candidate: default mild preference early, penalized when many
    // bins are open or the item fits well elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * pressure + 15.0 * fill_ratio;
    }

    // Stream progression: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // typical items (<= ~10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open or item is large
        // relative to mean residual (poor fit elsewhere).
        score -= pressure * 8.0;
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
    } else {
        score += pressure * 2.0;
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit the post-residual but could fit this bin now,
    // slightly penalize leaving a blocking gap.
    if next_item_size > post_residual as u32 && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny sliver: worst dead space
        } else if post_residual < item_size.min(20) {
            score += 25.0; // gap smaller than typical future item
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure from many open bins: favor filling existing bins.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: only attractive when item fits poorly everywhere else,
    // i.e. when this empty-bin call has large residual and mean residual is low.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: slightly above a good fit in an open bin
        score = (bin_capacity - item_size) as f64 + 8.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0; // open bins are too full; new bin is fine
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // lookahead: if next item is large, fresh bin gives flexibility
        if next_item_size > 40 {
            score -= 6.0;
        }
    } else {
        // Lookahead synergy: leaving exactly next_item_size is ideal.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 18.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10 typical)
    // can ever use are pure waste. Penalize tiny unusable gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item
    // would leave a large dead gap in every existing bin, or too many bins
    // are already open with high mean residual (fragmentation pressure).
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual < 10 { 80.0 } else { 0.0 };
        let pressure = open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        score = 40.0 + gap_penalty - pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; mildly penalize wasting the gap
        score += 5.0;
    }

    // Early stream: be slightly conservative, keep bins balanced
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold anything useful are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // If the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // creates unusable gap for the lookahead item
    }

    // Slight preference for tighter bins relative to the fleet mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect pairing: this item + next item exactly fill residual.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: empty bin is a fallback; make it mildly
    // attractive only when existing bins fit poorly or are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress - 3.0 * congestion;
        // Never open a new bin when a last-chance fit exists elsewhere.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    }

    // Mild preference for bins below mean residual (spreads load evenly).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Late in stream: consolidate aggressively, avoid waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead);
    } else if dead <= 5.0 && dead > 0.0 {
        score += 40.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Post-residual that exactly fits the lookahead item is valuable.
    if next_item_size > 0 && post_residual as u32 >= next_item_size && (post_residual as u32 - next_item_size) < 10 {
        score -= 12.0;
    }
    // Post-residual too small for anything (min size 1) already covered; too small for next item adds pressure mildly.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones.
    let pressure = open_bins_count as f64 / 20.0;
    score -= pressure * (bin_residual as f64 - item_size as f64).max(0.0) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we only open when existing fits are bad,
    // unless open bin count is very low and item is large.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.5;
        if item_size > 70 && open_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable, punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        score -= 15.0 / post_residual as f64;
    }

    // Lookahead: bonus if the leftover gap can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if the next item would NOT fit in this bin but WOULD fit a fresh bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate a new bin for better long-run fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure discount.
        score = score.max(0.0) + 45.0 - pressure * 1.5;
    } else {
        score -= pressure * 0.6;
    }

    // Nudge toward bins with residuals near the item size (tight fits).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Prefer bins whose residual deviates from the fleet mean (specialization).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // exactly fills the post_residual (perfect chaining).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect two-item chain: near-perfect fill.
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tightly it fits.
            let tightness = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 300.0 * tightness;
        } else {
            // Next item does not fit: penalize dead space that blocks chaining.
            let waste = (nxt - post) / bin_capacity as f64;
            score += 150.0 * waste;
        }
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 80.0 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the tightest one (post_residual already does this),
        // but add a mild penalty to avoid spreading items across many bins.
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when the item is large relative to
    // typical residuals and no good chaining exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mean_tight = mean_residual / bin_capacity as f64;
        // Open a new bin if item is big and open bins are already loose.
        let attractiveness = fill_ratio * (1.0 - mean_tight);
        score = 150.0 - 120.0 * attractiveness + 20.0 * fill_ratio;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // New bin can also chain the next item.
            score -= 60.0;
        }
    }

    // Mild late-stream pressure to consolidate rather than open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 6.0 * (next_item_size as f64 - dead);
        }
        // Small unusable slivers are worse than medium gaps
        if dead < 10.0 {
            score += 8.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score += 22.0 + 10.0 * (1.0 - progress) + 3.0 * pressure;
        // If item is large relative to capacity and mean residual is low, new bin less bad
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Prefer bins with residual below the mean (consolidate fullness)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Time horizon: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: residual after placement near zero is great.
    let tightness = if post_residual == 0 {
        -60.0
    } else {
        -25.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3)
    };
    score += tightness;

    // Penalize leaving dead space that no plausible future item can use.
    // Items are 1..=100; a residual below ~10 is nearly dead.
    if post_residual > 0 && post_residual < 12 {
        score += 15.0 * (12.0 - post_residual as f64);
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // reward proportionally to how well next item fits
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Give empty bins a mild penalty so tight fits in existing
    // bins win, but allow it when mean residual is high (open bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Early in stream: keep bins open (penalty). Late: more willing to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = 10.0 + 25.0 * progress + 30.0 * fragmentation;
        score += openness;
    } else {
        // Slight penalty for bins already heavily fragmented relative to mean
        if (bin_residual as f64) > mean_residual + 0.5 * bin_capacity as f64 {
            score += 5.0;
        }
        // Reward consolidating into bins with small residuals (avoid many half bins)
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Global pressure: many open bins with high mean residual -> prefer filling
    // existing bins aggressively (subtract to favor them).
    if open_bins_count > 2 {
        score -= 0.5 * mean_residual.min(50.0) / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // leftover after next item would be post_residual - next_item_size
            let after_next = (post_residual - next_item_size) as f64;
            // penalize residual that next item cannot use well
            score += after_next * 0.3;
            if after_next < 10.0 {
                score -= 50.0; // near-perfect chain
            }
        } else {
            // next item cannot fit in this bin's leftover: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    } else {
        // last item: just minimize post_residual
        score += 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Compare against mean residual: bins tighter than mean are precious, prefer filling loose bins
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.2;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 5.0;

    // Penalize creating tiny unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let avg_fragmentation = mean_residual / bin_capacity as f64;
        // base cost of a fresh bin
        let mut new_bin_score = 70.0;
        // if open bins are very fragmented, new bin becomes attractive
        new_bin_score -= avg_fragmentation * 120.0;
        // fewer fitting bins -> new bin more acceptable
        if fitting_bins_count <= 1 {
            new_bin_score -= 60.0;
        }
        // lookahead: a new bin can always host the next item
        if next_item_size > 0 {
            new_bin_score -= 20.0;
        }
        // early in stream, new bins are cheaper (more future items to amortize)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score -= (1.0 - progress) * 15.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: big discount
        if diff == 0.0 {
            score -= 50.0 + 20.0 * (1.0 - progress);
        } else if next_item_size <= post_residual {
            // next item could still fit here later: mild discount scaled by closeness
            score -= 10.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item cannot fit in post_residual: penalize dead space
            score += 5.0 + 0.3 * diff;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Reward tight fits relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, offset slightly when many bins open and residuals fragmented
        score += 40.0;
        score -= 2.0 * open_bins_count as f64 * (1.0 - progress);
        if post_residual as f64 > mean_residual + 10.0 {
            score += 10.0;
        }
    }

    // Prefer bins with small residual overall (best-fit flavor)
    score += 0.1 * (bin_residual as f64 - post_residual as f64) * 0.0;

    // Mild penalty for leaving residuals in the awkward 1..10 dead zone
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that is too small to be useful for typical items,
    // with a non-linear (quadratic-ish) ramp on small positive residuals.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead_penalty = if pr < 10.0 {
            (10.0 - pr) * (10.0 - pr) * 0.5
        } else {
            0.0
        };
        score += dead_penalty;
    }

    // Lookahead (k=2): if the next item cannot fit in the post residual,
    // this placement may force a new bin next step. Penalize proportionally
    // to how "close" the next item is to fitting.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 2.0;
            // Extra penalty if this is the only fitting bin (last chance):
            // wasting its residual on a non-exact fit is costly.
            if fitting_bins_count == 1 {
                score += gap * 3.0;
            }
        } else {
            // Reward placements that leave room for the lookahead item.
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time-horizon coupling: early in the stream, be conservative and keep
    // bins flexible; later, be greedier about tight fits.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= progress * 10.0;

    // Global state: when many bins are open with high mean residual,
    // slightly favor filling existing bins rather than opening new ones.
    score -= (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate handling: brand-new empty bin has bin_residual == bin_capacity.
    // Its raw post_residual (100 - item_size) is usually large, but add an explicit
    // opening cost that shrinks as the stream progresses (late stream: consolidate).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        // But if no open bin fits well (post_residual of this bin is small means
        // item is large), opening may be fine: soften cost when item is big.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with less residual before placement (tighter bins first),
    // keeping diversity across bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as u32 == next_item_size {
            score -= 400.0; // chain: item now, next item fills bin perfectly
        } else if post_residual as u32 > next_item_size {
            // next item fits after this one: reward closeness of the double-fill
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would NOT fit: penalize dead space created
            score += 60.0 + 0.5 * diff;
        }
    }

    // Compare post_residual to mean residual: prefer bins left tighter than average.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (post_residual would be huge, i.e. item tiny relative to empty bin).
    if bin_residual == bin_capacity {
        score += 250.0
            - 0.5 * item_size as f64
            - 10.0 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Late-stream tightness: waste matters more as stream progresses.
    score += 0.3 * (post_residual as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically small gaps) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // Penalize if the leftover gap can't fit the next item but is nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin
    // only when fit is poor; few open bins -> discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if it avoids large dead space elsewhere.
        score -= 5.0 + 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        score += 10.0 * (1.0 - progress); // early on, opening bins is fine
    } else {
        // Existing bin: mild penalty scaled by how crowded the bin set is.
        score += (open_bins_count as f64) * 0.3;
    }

    // Prefer bins with residual close to item (tight fit) vs. wasteful large-bin use.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 5.0;

    // Align with mean residual: using bins below mean residual consolidates.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near match: next item fits into post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to lookahead item
        score += 8.0;
    }

    // Tight fit reward (small post residual overall)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins with residual far above mean (fragmentation risk)
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: penalize unless current bins are mostly full / crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let fullness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 12.0 - crowding * 0.5 - fullness * 10.0;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0; // nothing fits anyway, new bin good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but dead space below a small-item threshold is wasted.
    let small_threshold = cap * 0.2;
    if (post_residual as f64) < small_threshold {
        score -= (small_threshold - post_residual as f64) * 0.8;
    }

    // Harmonic class of post_residual: modulo classes of 10 (classic capacity fractions).
    let pr = post_residual as i64;
    let cls = pr % 10;
    // Residuals in classes {0,1,2,9} are near-perfect or near-useless; treat differently.
    if cls == 0 {
        score -= 12.0; // perfect packing
    } else if cls >= 7 {
        score += 6.0; // sliver residuals unlikely to be filled
    }

