    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair: item + next item fills bin
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // prefer bins where next item leaves minimal slack
            score -= 20.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportional to leftover
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Exact fit of current item is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Compare residual against mean residual across open bins.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.5 * mean_gap; // prefer bins tighter than average (below-mean residual)

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate (empty bin) unless few bins fit the item or item is large.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.5 };
        score += 15.0 * pressure;
        if fitting_bins_count == 1 {
            score -= 20.0; // allow new bin only as last resort fallback
        }
        if item_size > bin_capacity / 2 {
            score -= 8.0; // large items may warrant fresh bins
        }
    }

    // Early in stream: keep bins tight, discourage spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate aggression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        let perfect_chain = if gap == 0.0 { 1.0 } else { 1.0 / (1.0 + gap / 20.0) };
        score -= 10.0 * perfect_chain;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: mild penalty for leaving awkward residue.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates far below the mean (hoarding space).
    let dev = (mean_residual - bin_residual as f64).abs();
    score += 0.05 * dev;

    // Reward spreading load when many bins are open (avoid fragmenting few bins).
    if open_bins_count > 1 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // New-bin candidate logic: an empty bin should only win when the item is
    // large relative to any open-bin fit, or the resulting residual is tiny.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses
        // (early on, opening bins builds capacity for future items).
        let mut new_bin_cost = 18.0 - 10.0 * progress;
        // If the item is huge, a fresh bin is often the right call.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_cost -= 8.0;
        }
        // If nothing else fits well (many bins but poor fits), new bin is fine.
        score += new_bin_cost;
    }

    // Late in the stream, prioritize closing bins perfectly (zero residual).
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post residual), scaled by stream progress.
    let mut score = x * (1.0 + 2.0 * progress);

    // Non-linear polynomial coupling: dead-space penalty grows super-linearly,
    // modulated by progress (late stream => punish wasted space harder).
    let dead = (1.0 - x).powi(2); // large when post residual small (good fit)
    score -= 3.0 * progress * dead;

    // Quartic smooth term favoring residuals that match next item's needs.
    let nx = next_item_size as f64 / cap;
    let match_term = 1.0 - ((x - nx) / 0.5).powi(2);
    score -= 1.5 * match_term.max(-1.0) * (1.0 - progress);

    // Last-chance bonus: smooth reward when few fitting bins exist.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 2.0 * scarcity * (1.0 - x);

    // Penalize opening new bins when open bins are underutilized (smooth).
    let util = mean_residual / cap;
    score += 0.5 * util * (1.0 - x).abs();

    // Mild regularization toward mid residuals early in stream.
    score += 0.3 * (x - 0.5).powi(4) * (1.0 - progress);

    // Smooth new-bin candidate handling: empty bin gets slight penalty
    // unless residuals across bins are all poor.
    if bin_residual == bin_capacity {
        score += 0.8 * (1.0 - util) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 20.
    // Small residues (1..=9) are "poison" classes -> heavy penalty; larger residues are reusable.
    let post = post_residual as i64;
    let class = post % 20;
    if post > 0 {
        match class {
            0 => score -= 25.0,                       // perfect harmonic slot
            1..=9 => score += (10 - class) as f64 * 3.0, // dead-space poison
            10..=19 => score -= (class - 9) as f64 * 2.0, // good half-bin slots
            _ => {}
        }
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 40.0;
        } else if next_item_size < post_residual as u32 {
            let nxt = next_item_size as f64;
            let pr = post as f64;
            // reward if next item leaves another harmonic residue
            let nxt_post = pr - nxt;
            if (nxt_post as i64) % 20 == 0 {
                score -= 15.0;
            } else if nxt_post < 10.0 {
                score += 8.0;
            }
            score += nxt * 0.1; // mild preference to save large slots for large items
        } else {
            // next item cannot fit here: bin is closed anyway, mild reward for tight packing
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it's chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 2.0;
        // late in stream, opening new bins is less costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Prefer bins below mean residual (balance exploitation of emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Integer-division threshold: reward placing into bins where item fills >= 3/4 of residual.
    let q = post_residual / (bin_residual / 4).max(1);
    if q >= 3 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful later. Small gaps (<= 20) are near-wasted space.
    if post_residual > 0 && post_residual <= 20 {
        score += 25.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score += 10.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly fits the next item (lookahead k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize if post_residual is small but cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 25 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins (especially the new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (10.0 + 15.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += pressure + 20.0;
    } else {
        // Existing bins get a mild discount under pressure.
        score -= pressure * 0.3;
    }

    // Prefer bins whose residual deviates below the mean (tighter bins).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.2;
    } else {
        score += (res_f - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact/near match between post_residual
    // and the next item's size (chains a perfect follow-up placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward closeness to exact match.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 40.0; // perfect chain bonus
            }
        } else {
            // Next item won't fit here: penalize leaving a large unusable gap.
            score += 0.5 * (post_residual as f64) + 20.0;
        }
    }

    // Penalize bins whose post_residual is far below the mean residual
    // (converting a useful bin into a near-dead one).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: mildly discourage opening a new bin unless the item
    // is large (packing big items fresh is often good).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 0.2 * item_size as f64 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // post_residual below the minimum item size is pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // partial fit of next item: mild reward proportional to how well it uses leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * usage;
        } else {
            // next item cannot use this bin's leftover: slight penalty for hoarding space
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // as the stream progresses (less future to amortize a bin over).
    if bin_residual == bin_capacity {
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 60.0 * horizon;

        // Opening a new bin is attractive when no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        // With many open bins, prefer consolidating rather than opening more.
        score += 2.5 * open_bins_count as f64;
    }

    // Global pressure: high mean residual means space is abundant; be pickier
    // about which bin receives the item (favor best-fit via post_residual already).
    let mr = mean_residual / bin_capacity as f64;
    score += 12.0 * mr * (post_residual as f64 / bin_capacity as f64);

    // Late-stream consolidation: as the stream ends, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits; non-linear penalty for both large and awkward mid residuals
    let mut score = pr as f64;
    score += 40.0 * (1.0 - x) * x * 4.0; // hump penalizing mid-range residuals smoothly
    score -= 30.0 * (1.0 - x).powi(3);   // reward near-full bins (small post residual)

    // Stream-progress coupling: as stream advances, demand tighter packing (polynomial in t)
    let progress_pressure = t * t * (3.0 - 2.0 * t);
    score += 25.0 * progress_pressure * x;

    // Lookahead coupling: penalize if post residual can't hold next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        score -= 45.0 * fits_next * (nx / cap);
        score += 20.0 * (1.0 - fits_next) * (nx / cap) * (1.0 + t);
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + t);
    }

    // Fragmentation pressure: penalize when bin residual deviates from mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 15.0 * dev * (0.5 + t);

    // New-bin candidate: make it mildly unattractive unless open bins are scarce
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * t + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into nice
    // fractions of capacity are more reusable than "dead" residues.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual is an exact division of capacity (100, 50, 25, 20, 10...)
    if bin_capacity % post_residual.max(1) == 0 {
        score -= 12.0;
    }
    // Class 2: post_residual is a multiple of a small harmonic unit (10, 20, 25)
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Penalize odd / prime-ish dead residues
    if post_residual % 10 != 0 && post_residual > 0 {
        score += 3.0;
    }
    // Tiny unusable slivers are dead space
    if post_residual < 10 {
        score += 18.0;
    }

    // Perfect fit: enormous reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // harmonic match: next item divides post_residual evenly
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
            // penalize leaving a residue that next item can only poorly fill
            let nxt_res = post_residual - next_item_size;
            if nxt_res < 10 && nxt_res > 0 {
                score += 10.0;
            }
            score += (nxt / cap) * 5.0;
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when existing bins fit badly
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 30.0;
        // large items prefer fresh bins
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // if few fitting bins and mean residual is small, opening is fine
        if fitting_bins_count == 0 || (mean_residual < (item_size as f64) * 0.5) {
            score -= 20.0;
        }
        // early in stream, be liberal with opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins whose residual is far below mean (tighter bins first)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Fractional capacity threshold: bins over half full are attractive targets
    if bin_residual <= bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold typical items are "dead space".
    // Penalize them super-linearly once they fall below a usability threshold.
    let dead_threshold = 20.0f64; // below this, a gap is likely unusable
    if (post_residual as f64) < dead_threshold {
        // steep quadratic penalty pushing this bin to the bottom of the ranking
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits (post_residual close to 0 is good only if it
    // is exactly consumed; otherwise small-but-nonzero gaps are the worst).
    if post_residual == 0 {
        score -= 25.0; // perfect fill, ideal
    }

    // --- Tightness reward: fraction of the bin's space used by this item ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // --- Open-bin pressure: prefer reusing existing bins over opening new ones ---
    // When many bins are open, gently bias toward placing in an existing bin.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Opening a new bin is penalized proportionally to how many bins are
        // already open, but relaxed when the fit into existing bins is poor
        // (i.e., this placement would leave a big dead gap elsewhere anyway).
        score += 12.0 + (open_bins_count as f64) * 1.5;
        // If no other bin fits well (few fitting bins), soften the penalty so
        // a fresh bin can win when it avoids dead space.
        if fitting_bins_count <= 1 {
            score -= 8.0;
        }
        // Late in the stream, opening new bins matters less (fewer future items
        // to fill them), so relax the penalty as the stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 6.0;
    }

    // --- Lookahead coupling: if the next item fits into this bin's post
    // residual, reward the placement (chaining good pairs together). ---
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 10.0;
    }
    // If the next item would NOT fit in the resulting gap and the gap is
    // small, this bin becomes a dead-end: extra penalty.
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 && (post_residual as f64) < dead_threshold {
        score += 10.0;
    }

    // --- Mean residual coupling: bins whose residual deviates strongly below
    // the mean are already tight; placing here keeps fragmentation localized. ---
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && !new_bin_candidate {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();

        // Perfect chain match: strong reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 35.0 - diff * 4.0;
        } else if diff <= 15.0 {
            score -= 12.0 - diff * 0.5;
        } else {
            // Post-residual too far from next item: penalize wasted space.
            score += (diff - 15.0) * 0.4;
        }

        // If next item cannot fit in this bin's post-residual but fits
        // elsewhere, mild penalty; if this would be the only fitting bin,
        // avoid burning it on a bad chain.
        if post < next {
            score += 8.0;
            if fitting_bins_count == 1 {
                score -= 10.0; // last chance: placement here still preferred
            }
        }
    } else {
        // Last item: minimize post residual as hard as possible.
        score += (post_residual as f64) * 0.5;
    }

    // Prefer bins tighter than the mean residual (good fits).
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap < 0.0 {
        score -= (-mean_gap).min(20.0) * 0.6;
    } else {
        score += mean_gap * 0.3;
    }

    // Last-chance bin bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let mut best_open_fit = f64::INFINITY;
        // Approximate: use mean_residual as proxy for open-bin post residuals.
        best_open_fit = mean_residual - item_size as f64;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 20.0; // chain potential justifies a fresh bin
        }
        if best_open_fit < 10.0 {
            score += 15.0; // open bins likely fine; discourage new bin
        } else {
            score -= 10.0; // poor fits elsewhere: open a new bin
        }
        // Early stream: keep bins consolidated; late stream: allow spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Mild pressure to fill existing bins when many are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Time horizon: early stream -> explore (favor new bins slightly), late -> consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: strongly reward bins where the NEXT item also fits in the leftover.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        // exact chain fit is gold
        let chain_tightness = 1.0 - (post - next_item_size as f64) / cap;
        score -= 8.0 + 10.0 * chain_tightness;
    } else if next_item_size > 0 {
        // leftover too small for next item: penalize proportionally to dead space
        let waste = post / cap;
        score += 6.0 * waste * (0.5 + 0.5 * t);
    }

    // Reward tight fits (small post_residual relative to item size)
    score -= 4.0 * fit_frac * (1.0 - post / cap);

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the item is large
    // or the stream is early (exploration) or open bins are already very full on average.
    if bin_residual == bin_capacity {
        let exploration = (1.0 - t) * 4.0;
        let crowding = (open_bins_count as f64 / 20.0).min(1.0);
        let avg_fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let penalty = 12.0 - exploration - 4.0 * crowding - 6.0 * avg_fullness - 5.0 * fit_frac;
        score += penalty.max(0.5);
    } else {
        // Mildly prefer bins with residual close to item (harmonic-like affinity)
        let affinity = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
        score -= 2.0 * affinity;
        // Prefer bins below mean residual (use up emptier bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Late stream: discourage leaving many tiny residuals scattered
    if t > 0.7 && post > 0.0 && post < 10.0 {
        score -= 2.0; // near-perfect closure
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Base: quadratic penalty on post residual (dead space)
    let mut score = pr * (1.0 + 0.9 * fit * fit);

    // Smooth non-linear coupling with stream progress: late in stream, dead space matters more
    let late = progress * progress;
    score += 25.0 * late * fit * (1.0 - fit);

    // Reward tight fits via smooth saturating term
    let tightness = 1.0 - fit;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + late);
    }

    // Lookahead coupling: favor bins whose post residual could host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Deterrent against spreading: penalize bins near mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.15 * open_bins_count as f64 * (1.0 - late);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: prefer it when post_residual forms a "harmonic" slot
    // (divides capacity cleanly), otherwise penalize.
    if bin_residual == bin_capacity {
        if bin_capacity % item_size.max(1) == 0 {
            score -= 40.0; // perfect division: bin fully usable
        } else if post_residual < 10 {
            score += 25.0; // tiny dead space on a fresh bin is terrible
        } else {
            score += 5.0;
        }
        // Late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        return score;
    }

    // Harmonic class of post_residual: modular arithmetic on capacity fractions.
    let pr = post_residual;
    // Dead-space classes: residuals that no plausible item (1..=100) fits well.
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 5 {
        score += 30.0; // unusable sliver
    } else if bin_capacity % pr == 0 {
        score -= 25.0; // harmonic residual: fillable by repeated equal items
    } else if pr % 10 == 0 {
        score -= 15.0; // decade-aligned residual
    } else if pr < 20 {
        score += 12.0; // awkward small residual
    }

    // Integer-division thresholds: how many mid-size items (>=20) still fit.
    let slots_mid = pr / 20;
    score -= slots_mid as f64 * 4.0;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
            // harmonic pair: item + next divides capacity
            if (item_size + next_item_size) <= bin_capacity
                && bin_capacity % (item_size + next_item_size).max(1) == 0
            {
                score -= 20.0;
            }
        } else {
            score += 8.0; // next item won't fit here regardless
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Tightness reward: fraction of capacity consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Many open bins: encourage consolidation into emptier bins.
    if open_bins_count > 3 {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..100 range)
    // are effectively unusable -> heavy penalty proportional to how "dead" the gap is.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item * 10 {
        score += 1000.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize small-but-maybe-usable gaps less harshly, but still discourage waste.
    if post_residual > 0 && post_residual <= 15 {
        score += 20.0;
    }

    // Reward tight fits (post_residual near zero but still valid).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing ones,
    // penalize the new-bin candidate more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 5.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it before a new bin is opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // Penalize if post_residual is just barely too small for next item (dead space ahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first),
    // keeping looser bins available for larger future items.
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits comfortably in leftover space
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(30.0); // best when slack is small
    }
    // Next item would NOT fit: penalize proportionally to wasted potential
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.4;
    }

    // Compare against mean residual: bins with residual below mean are
    // "tighter" -> prefer filling them (lower score)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate: only attractive when no tight fit exists;
    // penalize opening a new bin early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 8.0 + 15.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin still fits the next item fine
        }
    }

    // Small bonus for very tight fits (low post residual relative to item)
    score -= (item_size as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residuals.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight);

    // Lookahead coupling: penalize if the NEXT item also fits in the post residual
    // (we'd want to keep more room structured), reward if next item cannot fit
    // here but fits in current residual minus a sliver of waste.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item could also go here: mild penalty for over-consuming this bin
            score += 8.0 + 0.15 * next_item_size as f64;
        } else if next_item_size <= bin_residual {
            // This bin takes current item, next item goes elsewhere: fine
            score -= 5.0;
        }
        // If next item fits EXACTLY in post residual, prefer leaving it for next step
        if next_item_size == post_residual {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    // or the item is huge relative to mean residual (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit_elsewhere = (item_size as f64) > mean_residual + 15.0;
        score += 40.0;
        if poor_fit_elsewhere {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, consolidate rather than open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 && !poor_fit_elsewhere {
            score += 30.0;
        }
        let _ = crowded;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into bins below mean residual (fill the emptiest-relative bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else if (bin_residual as f64) > mean_residual * 1.5 {
        score += 4.0;
    }

    // Penalize dead space that no future item (min size 1..10) can use
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * (1.0 - norm_pr);
    score += 6.0 * poly;

    // Penalize tiny dead space more as stream progresses (wasted capacity)
    let dead = (norm_pr - 0.5).abs();
    score += 4.0 * dead * dead * (0.5 + t);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_ratio = nx / pr.max(1.0);
            score -= 8.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Prefer tighter bins relative to mean residual
    score -= 2.0 * (mean_residual - bin_residual as f64) / cap;

    // Mild penalty for opening a new bin when open bins exist and fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity quarters.
    let quarter = (bin_capacity / 4).max(1);
    let half = (bin_capacity / 2).max(1);
    let mod_q = (post_residual % quarter) as f64;
    let mod_h = (post_residual % half) as f64;

    // Penalize post residuals that fall into "dead zone" classes:
    // small nonzero leftovers (1..quarter) are hard to reuse.
    if post_residual > 0 && post_residual < quarter {
        score += (quarter - post_residual) as f64 * 1.5;
    }
    // Perfect harmonic classes: post_residual == 0, half, quarter multiples get rewards.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % half == 0 {
        score -= 20.0;
    } else if post_residual % quarter == 0 {
        score -= 10.0;
    } else {
        // penalize by distance to nearest harmonic class boundary
        let dist = mod_q.min(quarter as f64 - mod_q);
        score += dist * 0.8;
        // secondary class: half-modulo alignment
        let dist_h = mod_h.min(half as f64 - mod_h);
        score += dist_h * 0.3;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility: next item leaves another harmonic class
            let next_post = post_residual - next_item_size;
            if next_post % quarter == 0 {
                score -= 25.0;
            } else {
                score += (next_post % quarter) as f64 * 0.5;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by leftover
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, opened only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // early stream: opening bins is cheaper (builds diversity)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
    }

    // Prefer tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score += (post_residual as f64 / item_size as f64) * 3.0;
    }

    // Congestion control: many open bins with high mean residual -> prefer reusing full bins.
    if open_bins_count > 0 {
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the minimum item (1) are already
    // counted by base score, but gaps that can't fit the NEXT item are extra bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward tight fits / exact fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are open (consolidation pressure) or the item fits existing space well.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // If a future large item is coming, keep big residuals intact mildly.
        if next_item_size >= item_size {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing) slightly.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Late in stream, be greedier: minimize post residual harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

