    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Penalize leaving post-residual that no future small item can use (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 40.0;
    }

    // Compare post residual against mean residual: waste relative to average.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is attractive if the item leaves a large gap in any open bin.
        if post_residual >= 50 {
            score -= 20.0;
        }
    }

    // Prefer tighter fits overall: quadratic penalty on large post residual.
    score += (post_residual as f64).powi(2) / (4.0 * bin_capacity as f64);

    // Late in the stream, be conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Tightness reward: strongly prefer bins where the item nearly fills the residual.
