    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus (zero waste).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small gap still usable by tiny items
    }
    if post_residual > 50 {
