        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 5.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }
    // Many alternatives: mild penalty to encourage spreading / keeping good bins free.
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling: opening a bin is expensive; make the empty bin
    // attractive only when the item is large or no good fit exists elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early (more future to amortize) and for large items.
        let new_bin_bonus = 20.0 * (1.0 - progress) + 0.5 * item;
        score -= new_bin_bonus;
        // But if decent fitting bins exist and item is small, discourage opening.
        if fitting_bins_count > 0 && item < 40.0 {
            score += 25.0;
        }
        // Late in stream, opening new bins wastes capacity: penalize.
        if progress > 0.7 {
            score += 30.0 * progress;
        }
    }

    // Global state coupling: if mean residual is high, prefer consuming the largest gaps
    // (i.e., bins with residual well above mean) to consolidate space.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Slight preference for bins with more residual when many bins are open (reduce bin count).
    score -= 0.05 * (open_bins_count as f64) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual (tight fits preferred)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer leaving moderately large residuals (flexibility).
    // Late: strongly prefer tight packing (small post_residual).
    let flex = x * (1.0 - x) * 4.0; // peaks at x=0.5
    let tight = 1.0 - x * x;        // rewards small residuals
    let coupling = (1.0 - progress) * flex * 12.0 - progress * tight * 10.0;
    score += coupling;

    // Smooth penalty for large residual waste, amplified with progress.
    score += progress * x * x * 25.0;

    // Lookahead: reward if next item fits into post residual (smooth polynomial).
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap) / cap;
        let fits = ((pr - next_item_size as f64).max(0.0)) / cap;
        let reward = if next_item_size as f64 <= pr { 1.0 - fits } else { 0.0 };
        score -= reward * nx * 15.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Mild penalty when many bins are open and this one is far above mean residual.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * (open_bins_count as f64) * 2.0;

    // New-bin candidate: neutral-ish baseline with smooth progress-dependent preference.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * progress) - (1.0 - progress) * 5.0;
        if fitting_bins_count <= 1 {
            score += 30.0; // don't open new bin if it's the only fitting open bin scenario
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify residual into capacity-fraction buckets.
    // Residuals in classes [0..10], [11..25], [26..50], [51..100] have different usefulness.
    let post = post_residual;
    let class = if post == 0 { 0 } else if post <= 10 { 1 } else if post <= 25 { 2 } else if post <= 50 { 3 } else { 4 };

    // Perfect fit: strongly reward zero / tiny residual.
    if post == 0 {
        score -= 1000.0;
    } else if post <= 5 {
        score -= 60.0 + (5 - post) as f64 * 8.0;
    }

    // Penalize residuals in the "dead zone": too small for typical next items (>=10).
    if post > 0 && post < 10 {
        score += 40.0;
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes are more reusable.
    let reusable = (post % 10 == 0 && post > 0)
        || (post >= 20 && post % 20 == 0)
        || (post >= 25 && post % 25 == 0)
        || (post >= 50 && post % 50 == 0);
    if reusable {
        score -= 12.0;
    }

    // Integer-division thresholds: how many 10-unit chunks remain.
    let chunks = post / 10;
    score -= chunks as f64 * 2.0;

    // Lookahead coupling: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 500.0;
        } else if next_item_size < post {
            let nxt_post = post - next_item_size;
            if nxt_post < 10 {
                score -= 30.0; // lookahead would nearly fill this bin
            }
            score -= (nxt_post / 10) as f64 * 3.0;
        } else {
            // next item can't use this bin's residual: penalize large leftover less if class is big
            if class >= 3 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
        // If many open bins with high mean residual, new bin is less attractive.
        score += open_bins_count as f64 * 0.5;
        score += (mean_residual / bin_capacity as f64) * 20.0;
    } else {
        // Reward filling bins that are already mostly full (waste-minimization).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fill_ratio * 10.0;
    }

    // Mean-residual harmony: prefer bins whose residual is close to the mean (keeps balance),
    // unless it's a last-chance situation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward very tight fits (waste near zero).
    if post_residual <= 2 {
        score -= 30.0;
    }

    // Nonlinear penalty on moderate dead space that is unlikely to be reused
    // given the typical item range (1..100, unknown distribution).
    let gap = post_residual as f64;
    score += 0.15 * gap * gap / bin_capacity as f64;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the gap -> dead space penalty.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize relative to how many bins are already open
        // and how fragmented existing bins are (mean_residual).
        score += 10.0 + bin_pressure * 2.0;
        if mean_residual >= item_size as f64 {
            score += 5.0; // existing bins could absorb this item reasonably well
        }
    } else {
        // Reward placing into open bins, more so when mean residual is high (fragmented).
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect_chain = post_residual == next_item_size;
        let next_fits = next_item_size <= post_residual;

        if perfect_chain {
            score -= 60.0; // exact 2-step chain: ideal
        } else if next_fits {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize tight leftovers that strand space
            score += 8.0 + gap * 0.15;
        }
    }

    // Prefer tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize dead space: post_residual below the smallest possible item (1) is fine,
    // but leftovers too small for typical items are waste.
    if post_residual < 10 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly awful.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Coupling with mean residual: bins deviating far below mean residual are
    // already well-filled; reward pushing them closer to full.
    let dev = mean_residual - post_residual as f64;
    score += 0.10 * dev; // post_residual below mean (well-packed) gets bonus

    // Early in the stream, be willing to open new bins to keep flexibility;
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early, penalize later (consolidation).
        score += 15.0 * progress;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0; // fresh bin chains well with next item
        }
    } else {
        score -= 5.0 * progress; // favor existing bins more as stream advances
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly: small post_residual is exponentially better.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Lookahead: if the next item can exactly fill the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: penalize, worse for large dead zones.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 20.0 + 30.0 * pressure;
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        new_bin_penalty += 15.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        new_bin_penalty += 6.0 * fitting_bins_count as f64;
        score += new_bin_penalty;
    } else {
        // Slight preference for bins with residuals below the mean (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Encourage keeping the open-bin population stable relative to stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 2.0 + 20.0 * progress {
        score -= 2.0; // reward filling existing bins when too many are open
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let p = progress;
    let poly = pr * pr * (0.5 * p * p - 0.3 * p + 0.1);
    score += poly * 0.02;

    // Reward tight fits more strongly as stream progresses
    let tight = 1.0 - pr / bin_capacity as f64;
    score -= tight * tight * (1.0 + p) * 10.0;

    // Penalize dead space relative to mean residual (smooth coupling)
    score += (pr - mean_residual).abs() * (0.5 + p);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - p);
    }

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - pr / (pr + nxt));
        } else {
            score += (nxt - pr) * 0.3;
        }
    }

    // Discourage spreading across too many bins late in stream
    score += open_bins_count as f64 * 0.05 * p;

    // Slight bias against opening new bin when others fit
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - tight) + 3.0 * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual in {0} -> perfect fit, huge reward.
    // Class 1: post_residual <= 10 -> nearly perfect, big reward.
    // Class 2: post_residual divisible into many common item sizes -> good.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 40.0;
    } else {
        // Harmonic divisibility bonus: count how many "attractor" sizes (1..=20 grid)
        // divide evenly into the residual. More divisors => residual is reusable.
        let mut divisors = 0u32;
        for d in 1..=20u32 {
            if pr % d == 0 {
                divisors += 1;
            }
        }
        score -= (divisors as f64) * 2.0;

        // Integer-division threshold: residual that can hold the lookahead item is valuable.
        if next_item_size > 0 && pr >= next_item_size {
            score -= 25.0;
            // Extra bonus if it fits exactly twice (harmonic pairing).
            if pr / next_item_size >= 2 {
                score -= 8.0;
            }
        } else if next_item_size > 0 {
            // Dead space relative to the lookahead: penalize.
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Modulo arithmetic on residual against capacity fractions (harmonic classes of C).
    // Residuals that are exact fractions of capacity (50, 25, 20, 10) are classic-friendly.
    let harmonic = [50u32, 25, 20, 10, 33, 34, 66, 67];
    for h in harmonic {
        if pr == h {
            score -= 6.0;
        }
    }

    // Penalize creating small unusable slivers (1..=9) when many bins remain open.
    if pr >= 1 && pr <= 9 && open_bins_count > 2 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline slightly above good fits,
    // but attractive when current bin would leave a terrible remainder.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild pull toward bins whose residual is close to the item (tight fits).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // Prefer bins below mean residual (more roomy bins kept for bigger future items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is small (but nonzero) is worse than a large residual,
    // because nothing (items >= 1, typically >= 10) will ever fit there.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: strongly reward consuming the bin exactly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a residual that exactly accommodates the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            // Mild penalty if post_residual is only barely above next item (near-miss gap).
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score += 6.0 * (1.0 - slack as f64 / 10.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills;
    // few open bins -> allow some slack.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean residual (tighter bins first),
    // penalize dipping into unusually large-residual bins when many bins are open.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Early in the stream, tolerate opening bins more freely; late in the stream,
    // squeeze existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // New-bin candidate handling: an empty bin should only win when the best
    // available fit is bad. Give it a moderate baseline so it loses to good fits
    // (perfect fits, last-chance bins) but beats heavily dead-space-penalized ones.
    if bin_residual == bin_capacity {
        score -= 10.0;
        // If the current item is large relative to capacity, opening fresh is safer.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 8.0;
        }
        // If lookahead won't fit alongside in a fresh bin anyway, prefer fresh bin.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect chain fit: post residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here: reward closeness of the chain fit.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize proportionally to waste.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    } else {
        // Last item: pure waste minimization, reward tight fits.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean residual coupling: bins tighter than average are good targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening a new bin unless current placements would create large waste.
    if bin_residual == bin_capacity {
        let waste_pressure = (post_residual as f64) / bin_capacity as f64;
        score += 15.0 + 20.0 * (1.0 - waste_pressure);
        if next_item_size > 0 && post_residual == next_item_size {
            score += 50.0; // don't open new bin when an open bin chains perfectly
        }
    }

    // Slight late-stream tightening: as stream progresses, prefer tighter fits harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny slivers are fine-ish, nearly perfect fit
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0; // dead zone: smallest items are ~10, awkward gap
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins are open, encourage consolidation into fuller bins.
    if open_bins_count > 2 {
        let consolidation = (bin_residual as f64 - mean_residual).max(0.0);
        score -= 0.15 * consolidation * (open_bins_count as f64).ln();
    }

    // Penalize bins that are much emptier than the mean early on (keep large
    // residual bins available for large future items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let emptiness = (mean_residual - bin_residual as f64).max(0.0);
    score += emptiness * (1.2 - 0.8 * progress);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are already quite full on average.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let new_bin_bonus = 10.0 + 60.0 * mean_fullness * mean_fullness;
        score -= new_bin_bonus;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        score -= 20.0 * progress;
        // If several bins fit, opening a new one is usually wasteful.
        if fitting_bins_count > 2 {
            score += 30.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (exactness).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize large residuals, with non-linear growth
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth progress coupling: later in stream, tighter packing preferred
    let prog_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 20.0 * prog_coupling * x * (1.0 - x);

    // Penalize post-residual that matches next item poorly (wasted potential)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let mismatch = (x - nx).abs();
        score += 10.0 * mismatch * mismatch * (1.0 + progress);
        // Reward if next item fits exactly-ish
        let fit_bonus = (1.0 - (x - nx).abs() / cap).max(0.0);
        score -= 8.0 * fit_bonus * fit_bonus;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: discourage spreading, favor filling existing ones
    let density = open_bins_count as f64;
    score += 0.5 * density * x;

    // Deviation from mean residual: prefer bins near/below mean (balanced fill)
    score += 0.3 * (pr - mean_residual).abs();

    // Item size effect: big items into tight bins is good
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= 5.0 * tightness * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions) ---
    // Residuals that fall into "useful" harmonic classes (multiples of common
    // item sizes / capacity fractions) are more likely to be filled later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic classes: quarters, fifths, tenths of capacity.
    let quarter = (post_residual % (bin_capacity / 4)) as f64;
    let fifth = (post_residual % (bin_capacity / 5)) as f64;
    let tenth = (post_residual % (bin_capacity / 10)) as f64;
    // Reward alignment with capacity fractions (subtract when residual sits
    // exactly on a harmonic boundary).
    if quarter == 0.0 { score -= 12.0; }
    if fifth == 0.0 { score -= 8.0; }
    if tenth == 0.0 { score -= 5.0; }

    // Penalize residuals in "dead" classes: tiny but nonzero slivers that no
    // item (min size 1, but typical >= 10) can use. Dead-space bands.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 6.0; // exactly fits a small item class
    }

    // Integer-division threshold coupling: how many "average" items fit after.
    let avg_item = 40.0f64;
    let fits_after = (pr / avg_item).floor();
    score -= fits_after * 4.0; // more future capacity is good

    // --- Tight fit reward: waste ratio ---
    let waste = pr / cap;
    score -= (1.0 - waste) * 30.0; // prefer bins that become nearly full

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            // Next item fits here too: strong reward, scaled by how snugly.
            score -= 25.0 + 15.0 * (1.0 - (pr - n) / cap);
            // Harmonic bonus: next_item_size divides post_residual nicely
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit after this placement; penalize if it WOULD
            // have fit the current residual (we destroyed a viable slot).
            if n <= bin_residual as f64 {
                score += 18.0;
            }
            // Mild penalty growing with how far off the fit is.
            score += ((n - pr) / cap).min(1.0) * 10.0;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; avoid opening a new bin unless
        // placement creates terrible dead space.
        if post_residual >= 10 || post_residual == 0 {
            score -= 40.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline; prefer it only late in the stream
        // when open bins are numerous and fragmented, or when no good fit exists.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55;
        score += (open_bins_count as f64).min(20.0) * 2.0;
        score -= progress * 15.0;
        // If item leaves a harmonic residual in a fresh bin, slightly favor.
        if (item_size % (bin_capacity / 4)) == 0 { score -= 6.0; }
        // If existing bins are fragmented (high mean residual spread), opening
        // a new bin is cheap.
        score -= (mean_residual / cap).max(0.0) * 10.0;
        // If next item is large and current item is small, opening fresh bin
        // keeps large-item capacity alive.
        if next_item_size > 60 && item_size < 30 { score -= 12.0; }
    }

    // --- Global state adjustments ---
    // When many bins are open, prefer consolidating (low post_residual).
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 8.0;
    // Mean residual coupling: if mean residual is high, filling tight is valuable.
    score -= (mean_residual / cap).clamp(0.0, 1.0) * (1.0 - waste) * 10.0;

    // Small progression-driven sharpening of tight-fit preference.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - waste) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the minimum item size are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits the residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize residual that cannot host the next item but is still large-ish
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: more open bins -> prefer reusing existing bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score = 50.0 - fit_quality * 20.0 + open_bins_count as f64 * 0.2;
        if post_residual == 0 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: exact match with next item -> two perfect fits.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 900.0;
    }
    // Next item fits exactly half of remaining space (two-item chain).
    else if next_item_size > 0 && post_residual == 2 * next_item_size {
        score -= 300.0;
    }

    // Dead space: post_residual too small for the next item -> penalize.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 80.0 + 0.5 * post_residual as f64;
    }

    // Penalize tiny unusable remnants (dead space for any realistic item).
    if post_residual < 10 {
        score += 60.0;
    }

    // Reward bins whose residual is below mean (tight packing), penalize loose bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize mildly, but less when few bins fit the item
    // or the stream is early (leave room for future large items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 500.0 - 200.0 * (1.0 - progress) - 50.0 * (fitting_bins_count as f64).min(5.0);
        // If next item is large and this item is large too, new bin is safer.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 250.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fit_ratio = pr / cap;

    // Smooth non-linear base: penalize residual with cubic-quartic shaping
    let mut score = pr * (1.0 + 0.9 * fit_ratio * fit_ratio - 0.4 * fit_ratio.powi(3));

    // Stream-progress coupling: early on tolerate residual, late punish it harder
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Interaction between post-residual and mean residual across open bins
    let mr = mean_residual / cap;
    score += 0.6 * pr * mr;

    // Next-item lookahead: reward residual that can still hold the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = (pr - n) / cap;
        if fits_next >= 0.0 {
            score -= 4.0 * (1.0 + fits_next) * (1.0 - progress);
        } else {
            score += 2.0 * (-fits_next) * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Slight preference to keep bin count low
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).exp() - 1.0;
        score += 6.0 + 5.0 * tightness * (1.0 - progress) + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into buckets.
    // Residuals divisible by 10 are "harmonic" (likely reusable by typical items).
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 4.0;
    } else if post_residual < 10 {
        // Unusable dead space below minimum item size: heavy penalty.
        score += 12.0;
    } else {
        // Non-harmonic mid-range dead space penalized by distance to nearest class.
        let dist = (post_residual % 10).min(10 - post_residual % 10);
        score += dist as f64 * 0.6;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 3.0;

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (next_item_size as f64 / bin_capacity as f64) * 4.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving a large stranded residual.
        score += (post_residual as f64 / bin_capacity as f64) * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins
    // would end up with poor residuals; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 {
            score -= 6.0; // open bins are nearly full, prefer new bin
        } else {
            score += 6.0 + open_bins_count as f64 * 0.3; // keep packing existing bins
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post_residual as f64).abs().min(10.0) * 0.2;

    // Integer-division threshold: bins whose residual is in [30, 50) are prime
    // targets for medium items; bonus scaled by item size class.
    let item_class = item_size / 20;
    let residual_class = post_residual / 25;
    if item_class == residual_class && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual is "dead" if it is too small to hold even the smallest
    // plausible future item (assume items can be as small as 1, so focus
    // on gaps that are tiny relative to typical item scale).
    let dead_threshold = 10.0_f64.min(item_size as f64 * 0.25);
    if (post_residual as f64) < dead_threshold {
        score += 50.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits strongly (waste ~ 0).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Fit tightness: prefer bins where the item fills a large fraction
    // of the available residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 10.0;
    }

    // Open bins pressure: when many bins are open, avoid spreading;
    // favor filling existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (creates a perfect follow-up fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but not perfectly: mild reward proportional to tightness.
        let tight = next_item_size as f64 / post_residual as f64;
        score -= tight * 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover gap: penalize dead space more.
        score += (post_residual as f64) * 0.5;
    }

    // New-bin candidate handling: an empty bin (bin_residual == bin_capacity)
    // should only win when existing fits are poor. Give it a moderate
    // baseline cost so it loses against good fits but wins against
    // dead-space-heavy placements.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheaper; later, avoid sprawl.
        score += progress * 20.0;
    }

    // Mild tie-breaker toward bins below mean residual (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
