pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Penalize dead space relative to capacity (non-linear).
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac;

    // Lookahead: reward residuals that can pair with the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: mild penalty scaled by waste.
        let waste_frac = next_item_size as f64 / post_residual as f64;
        score += 10.0 * waste_frac.min(3.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Crowding: when many bins are open, prefer filling existing ones.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 8.0 * (crowding - 0.5).max(0.0);

    // Prefer bins with residuals close to the mean (balance the pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be pickier about wasteful placements.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: baseline attractiveness that shrinks as the stream
    // progresses or when many bins are already open.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 30.0 * (1.0 - progress) + 5.0 * (fitting_bins_count as f64);
        score += new_bin_bonus;
        // Only open a new bin if the item is large and would leave a useful
        // residual in a fresh bin.
        if item_size < bin_capacity / 4 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr;
    score += 20.0 * pr_norm * pr_norm;

    // Dead-space penalty: residuals too small for typical items are wasted
    let dead = if pr < 10.0 { (10.0 - pr) * 3.0 } else { 0.0 };
    score += dead;

    // Tight-fit reward: post-residual close to next item size
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        score -= 15.0 * (-gap / 20.0) * (-gap / 20.0);
        // Perfect chain: next item exactly fills
        if (pr - nxt).abs() < 1.0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Stream progress coupling: later in the stream, waste matters more
    score *= 1.0 + 0.5 * progress * pr_norm;

    // New-bin candidate: mildly discourage opening bins unless residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * progress) + open_bins_count as f64 * 2.0;
        // Allow new bin when open bins have poor average fit
        let fit_gap = (mean_residual - item_size as f64).abs();
        if fit_gap > 25.0 && fitting_bins_count > 2 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity split into 5 classes.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1
    let class = (post_residual / (bin_capacity / 5).max(1)) as f64; // 0..5

    // Reward residuals that fall into "harmonic" slots (multiples of common item sizes)
    let harmonics = [10u32, 20, 25, 33, 50];
    let mut harm_bonus = 0.0;
    for h in harmonics.iter() {
        if post_residual % h == 0 && post_residual > 0 {
            harm_bonus += 4.0 * (h as f64) / 10.0;
        }
    }
    score -= harm_bonus;

    // Penalize dead space: residuals below the smallest item class are unusable
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }
    // Mid-range dead zones (hard to fill later)
    if post_residual >= 11 && post_residual <= 19 {
        score += 8.0;
    }
    if post_residual >= 41 && post_residual <= 49 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 15.0 + 10.0 * fit_quality;
    } else if next_item_size > post_residual {
        score += 6.0; // next item won't chain here
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        } else if mean_residual < item_size as f64 * 1.1 {
            score -= 12.0; // open bins nearly full, fresh bin is good
        } else {
            score += 10.0 + 15.0 * (1.0 - progress) - pressure.min(10.0);
        }
    }

    // Class-based tie-break: prefer residuals in coarse harmonic classes
    score -= class * 1.5;

    // Slight preference for tighter fits overall
    score += 0.05 * (bin_residual - item_size) as f64;

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible future item are pure waste. Penalize them hard.
    let min_useful = 1u32.min(bin_capacity); // smallest item is 1
    if post_residual < min_useful.max(next_item_size.min(100)) && post_residual > 0 {
        // gap too small for the lookahead item (or fully dead if next=0)
        score += 12.0 + post_residual as f64 * 0.5;
    }

    // Reward near-perfect fits aggressively (post_residual close to 0).
    if post_residual == 0 {
        score -= 25.0; // perfect fill: zero waste
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness ratio: favor bins where the item occupies a large fraction
    // of the residual, i.e. small post_residual relative to bin_residual.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening a new bin is cheaper so be less picky.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // New-bin candidate handling: only attractive when item is large and
    // current fits are poor (large post_residual everywhere).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        let poor_fits = post_residual as f64 > mean_residual + 10.0;
        if large_item && poor_fits {
            score -= 20.0; // fresh bin is genuinely better
        } else {
            score += 18.0; // default: prefer existing bins
        }
    }

    // Lookahead coupling: if the next item could exactly fill this bin's
    // post_residual, big bonus for saving that perfect slot... conversely,
    // if post_residual matches next_item_size, this bin is valuable for it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Mild mean-residual alignment: prefer bins whose residual is below
    // average (they are "dying" anyway; consolidate waste there).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-step chain: next item exactly fills remaining space
        if (post_residual as i64 - next_item_size as i64).abs() == 0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: mild reward scaled by tightness of fit
            let slack = post - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to how much it misses
            let miss = nxt - post;
            score += 8.0 * (miss / bin_capacity as f64);
        }

        // Coupling with mean residual: bins already below average residual are precious
        let post_f = post_residual as f64;
        if post_f < mean_residual {
            score -= 6.0 * (mean_residual - post_f) / bin_capacity as f64;
        } else {
            score += 4.0 * (post_f - mean_residual) / bin_capacity as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize tiny dead space (< 10) that is likely unusable, unless exact next-fit
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    // Empty bin residual == capacity; discourage hijacking when open bins fit tightly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Slight preference for new bins early, penalty later (bin consolidation)
        score -= 5.0 * (1.0 - progress);
        // If several bins fit, discourage opening a new one
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If the next item is large and this item is small, a fresh bin is fine
        if next_item_size >= 70 && item_size <= 40 {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual, with non-linear penalty on dead space.
    let mut score = post + 0.8 * (post / cap).powi(3) * cap;

    // Smooth quadratic coupling of post_residual with stream progress:
    // later in the stream, dead space matters more (less chance to fill it).
    let tightness = (post / cap).powi(2);
    score += 30.0 * tightness * (0.5 + progress);

    // Reward near-exact fills (small post_residual gets extra subtractive bonus).
    score -= 12.0 * (-post / (0.15 * cap)).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity (poor fits elsewhere) or late in the stream with fragmented bins.
    if bin_residual == bin_capacity {
        let large_item_bonus = 20.0 * (item / cap).powi(2);
        let fragmentation = (mean_residual / cap - item / cap).max(0.0);
        score = cap * 0.75 + large_item_bonus + 40.0 * fragmentation * (1.0 - progress)
            - 15.0 * progress;
        // If the next item could combine with this one in a fresh bin, favor opening.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (tight fit).
    score -= 6.0 * (-((resid - item) / (0.2 * cap)).powi(2));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space (capacity fraction classes).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Classify post_residual into harmonic bands: [0], (0,0.1], (0.1,0.25], (0.25,0.5], (0.5,1]
    let band: u32 = if post_residual == 0 {
        0
    } else if frac <= 0.1 {
        1
    } else if frac <= 0.25 {
        2
    } else if frac <= 0.5 {
        3
    } else {
        4
    };

    // Dead space penalty: tiny residuals are nearly unusable (items >= 10 normally).
    if band == 1 {
        score += 8.0;
    } else if band == 2 {
        score += 3.0;
    } else if band == 3 {
        score -= 2.0;
    } else if band == 4 {
        score -= 4.0;
    }
    if post_residual == 0 {
        score -= 12.0; // perfect fit is best
    }

    // Integer-division threshold classes on post_residual (harmonic buckets of size 10).
    let bucket = post_residual / 10;
    score -= (bucket % 3) as f64 * 1.5;

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains into this bin: strong reward.
            score -= 6.0;
            // Extra reward when next item nearly fills what's left (mod-5 harmony).
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 4.0;
            }
        } else {
            // This placement strands the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin is a safe fallback but wasteful
    // if a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 10.0;
        // Early in the stream, opening bins is cheap (more items to come to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If many bins are open and mean residual is small, prefer new bin.
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 12.0;
        }
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 4.0;
        }
    }

    // Mild pressure to keep bin count low: reward using already-open bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual that is tiny (but nonzero) is worse than a moderate gap,
    // since it can likely never be reused (items are 1..100).
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Quadratic penalty concentrated on very small residuals.
        score += (20.0 / (dead + 1.0)) * (1.0 - dead / bin_capacity as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Tightness reward: the larger the fraction of the bin we consume, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, prefer reusing existing bins
    // over opening new ones; when few bins are open, a new bin is cheaper.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins are already open
        // and when the item fits comfortably into some existing bin.
        score += 15.0 + open_bins_count as f64 * 3.0;
        // But if the item is large relative to mean residual of open bins,
        // opening a new bin is less bad.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item would fit exactly into the post
    // residual, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to how well it uses the gap.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this gap: penalize leaving a gap the lookahead wastes.
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Late in the stream, closing bins tightly matters more (less future to reuse gaps).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 * 0.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Next item fits with small leftover => strong bonus
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize leaving medium dead space
            score += 0.35 * post_residual as f64;
        }
    }

    // Penalize dead space relative to mean residual (fragmentation avoidance)
    if mean_residual > 0.0 {
        score += 0.5 * ((post_residual as f64 - mean_residual).abs());
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 130.0 - 90.0 * tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Mild bonus for tight fits overall
    score -= 30.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Slight exploration pressure late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post residual very small but nonzero waste avoided).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover remains usable for the lookahead item
            score -= 15.0 + 0.25 * next_item_size as f64;
            // extra reward if next item then fits almost perfectly
            let pr2 = post_residual - next_item_size;
            if pr2 <= 5 {
                score -= 25.0;
            }
        } else {
            // dead space relative to lookahead: penalize proportionally
            let dead = next_item_size as f64 - post_residual as f64;
            score += 0.6 * dead;
        }
    }

    // Penalize creating tiny unusable fragments (dead space < typical minimum item 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer filling fuller (more loaded) bins first: bins with small residual get priority.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream: consolidate aggressively, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with stream progress and item smallness.
        let mut new_bin_score = 60.0 + 120.0 * progress;
        if item_size < 30 {
            new_bin_score += 25.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // large items that may pair well in a fresh bin: soften new-bin cost
            new_bin_score -= 20.0;
        }
        score += new_bin_score;
    } else {
        // Early stream: allow spreading into multiple bins to enable later tight packing.
        if progress < 0.3 && post_residual >= 40 {
            score -= 10.0;
        }
        // Encourage using bins that would otherwise stay underutilized.
        if bin_residual as f64 > mean_residual + 20.0 {
            score -= 8.0;
        }
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * progress * progress * 0.3;
    score += 40.0 * poly;
    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 60.0 * tightness * tightness * (0.4 + 0.6 * progress);
    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dev = (pr - mean_residual) / cap;
    score += 25.0 * dev * dev;
    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64 / cap;
        let fit_gap = (pr - next_item_size as f64) / cap;
        score -= 30.0 * n * (1.0 - fit_gap.abs()) * (1.0 - progress);
    }
    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 + progress);
    }
    // Mild penalty for spreading across many open bins
    score += 2.0 * (open_bins_count as f64).sqrt();
    // New-bin candidate: make it attractive only when the item is large relative to capacity
    if bin_residual == bin_capacity {
        score -= 20.0 * norm_item * (1.0 - progress);
        score += 15.0 * norm_pr * (1.0 - norm_item) * (0.5 + progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (harmonic classes of post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Dead-space penalty: post_residual too small for the smallest possible item
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Modulo/harmonic class of post_residual relative to capacity quarters
    let quarter = bin_capacity / 4;
    let pr = post_residual as f64;
    let rem = (post_residual % quarter) as f64;
    score -= (quarter as f64 - rem) * 0.15;

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0;
            // even better if next-next fit is also tight
            let nr = post_residual - next_item_size;
            if nr <= 10 { score -= 20.0; }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // but allow fresh bin if item is large and few bins are open
        if item_size > bin_capacity / 2 && open_bins_count <= 2 {
            score -= 100.0;
        }
    }

    // Prefer filling bins that are already relatively full
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.05 * (1.0 + progress);

    // Pull toward mean residual: avoid outliers creating fragmented space
    score += (pr - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // unusable dead space (min item size ~10)
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 30 {
            score += 8.0;
        } else {
            score -= 10.0; // large leftover remains flexible
        }
    } else {
        score -= 80.0; // perfect fit: strongly reward closing a bin exactly
    }

    // Reward tight fits (high fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: discourage spreading across many bins.
    score += 4.0 * open_bins_count as f64;

    // Relative residual alignment: prefer bins whose residual is close to item size.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * diff;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item can use the post residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // leftover blocks the known next item
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progression.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 + 20.0 * (1.0 - progress);
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size well
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 50.0 - slack.min(50.0);
        // exact match for the next item is excellent
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize dead space proportionally
        score += (next_item_size as f64) * 0.5;
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer tighter bins relative to the mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Late in stream: discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 60.0 + 80.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual)
    score -= (item_size as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Penalize dead space that can't fit typical future items
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powi(3);
        score += dead * 60.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            let slack = post_residual - next_item_size;
            score -= 12.0;
            score -= (slack as f64 / bin_capacity as f64) * 8.0;
        } else {
            // Penalize blocking the next item proportionally to overflow
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.35;
        }
        // If next item is huge, avoid wasting a tight bin now
        if next_item_size >= 70 && post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Last item: fill as much as possible
        score -= 25.0;
    }

    // Time horizon: early on, be more willing to open new bins (explore)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // New-bin candidate: bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins would leave very awkward residuals
        let awkward = if post_residual > 0 && post_residual < 20 { 25.0 } else { 0.0 };
        score = post_residual as f64 + awkward - 18.0 * (1.0 - progress) + progress * 8.0;
        // If many open bins with big mean residual, discourage new bin
        score += (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
        // If only one fitting bin and it's tight, new bin is fine
        if fitting_bins_count == 1 { score -= 10.0; }
    } else {
        // Late in stream: consolidate into existing bins
        score += progress * 6.0;
        // Discourage spreading across many open bins
        score += open_bins_count as f64 * 0.3;
        // Reward bins tighter than average (efficient usage)
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        - 30.0 * pr_norm * pr_norm * pr_norm;

    // Smooth interaction: dead-space penalty grows with stream progress
    score += 25.0 * pr_norm * pr_norm * (progress - 0.5).abs();

    // Lookahead coupling: penalize if post_residual cannot fit next item
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let gap = nis - pr;
        if gap > 0.0 {
            score += 0.6 * gap * (1.0 + progress);
        } else {
            score -= 0.4 * (-gap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Mild preference for bins tighter than the mean residual
    score += 0.15 * (pr - mean_residual);

    // Slight new-bin avoidance as bins accumulate
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10.
    let class = (post_residual / 10) as f64;
    // Dead-space penalty: residuals below 10 are nearly unusable.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Non-linear reward for small post residuals (good fit).
    score -= 30.0 / (1.0 + class);

    // Modulo coupling: residual that is a multiple of common small item sizes
    // (5, 10, 20, 25) is more likely to be filled later.
    let r = post_residual;
    if r % 10 == 0 {
        score -= 6.0;
    } else if r % 5 == 0 {
        score -= 3.0;
    } else if r % 25 == 0 {
        score -= 5.0;
    } else {
        score += 2.0; // awkward residual
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 10.0 / (1.0 + (slack_after_next / 10) as f64);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 12.0 + 20.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold anything useful are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 1.5;

    // If the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // creates unusable gap for the lookahead item
    }

    // Slight preference for tighter bins relative to the fleet mean.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit wins, but weight it moderately.
    score = post_residual as f64 * 1.0;

    if next_item_size > 0 {
        // 2-step lookahead: reward if post_residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how well it matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.35;
        } else {
            // next item does NOT fit: penalize small dead space that nothing can use
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 45.0 * (10.0 - waste);
            } else {
                score += waste * 0.15;
            }
        }
        // Also consider residual after hypothetically placing next item
        if post_residual >= next_item_size {
            let r2 = post_residual - next_item_size;
            if r2 == 0 { score -= 15.0; }
        }
    } else {
        // Last item: just minimize waste
        score += post_residual as f64 * 0.2;
    }

    // Relative to mean residual: prefer bins that stay near/above mean
    // (avoid creating isolated tiny residuals while others hold slack).
    let pr = post_residual as f64;
    if pr < mean_residual * 0.35 {
        score += (mean_residual * 0.35 - pr) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when the item is large and would
    // leave a well-balanced residual, or when no open bin fits well.
    if bin_residual == bin_capacity {
        let is_new = bin_residual == bin_capacity;
        if is_new {
            // penalize opening new bins mildly; lookahead decides
            score += 30.0;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 35.0; // fresh bin supports the chain well
            }
            if item_size >= 70 {
                score -= 20.0; // big items fine in fresh bins
            }
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize bins whose post_residual cannot host the next item,
    // but reward bins that can host it snugly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) < ni {
            score += 12.0 * (ni - post_residual as f64) / 100.0;
        } else {
            let slack = post_residual as f64 - ni;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize leaving small unusable fragments (dead space traps).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Global state coupling: with many open bins, favor consolidation
    // (prefer filling existing bins over opening new ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early stream.
        score += 20.0 + 15.0 * (open_bins_count as f64 / (open_bins_count + 4) as f64)
            + 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * (open_bins_count as f64 / (open_bins_count + 4) as f64);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already tight — reward using it; if far above mean, it is loose — mild penalty.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Late in the stream, be greedier: weight tightness more strongly.
    score += 10.0 * progress * fit_ratio;

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a convex penalty on waste.
    let mut score = post + 0.35 * (post * post) / cap;

    // Smooth polynomial coupling of waste with stream progress:
    // early on, waste is cheap (many items left to fill gaps); late, waste is costly.
    let waste_penalty = 0.8 * progress + 1.2 * progress * progress;
    score += waste_penalty * (post / cap);

    // Reward bins whose residual is "consumed well" relative to the mean.
    let mean_gap = (mean_residual - post) / cap;
    score -= 0.5 * mean_gap;

    // Lookahead: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (post - nxt).abs();
        if post >= nxt {
            score -= 0.6 * (1.0 - fit_gap / cap);
        } else {
            score += 0.3 * fit_gap / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.5;
    } else if fitting_bins_count > 1 {
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: make it moderately attractive early, less so late,
    // and only when the current fit is poor (smooth interaction, no hard cutoffs).
    if bin_residual == bin_capacity {
        let poor_fit = (post / cap); // for empty bin, post = cap - item_size
        let attractiveness = 1.5 - 2.0 * progress - 1.5 * poor_fit * (1.0 - progress);
        score += attractiveness;
    }

    // Mild penalty for bin sprawl.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does the
    // leftover fall into? Bands: (0], (0,10], (10,25], (25,50], (50,100]
    let tiny = post_residual == 0;
    let small = post_residual > 0 && post_residual <= 10;
    let medium = post_residual > 10 && post_residual <= 25;
    let large = post_residual > 25 && post_residual <= 50;
    let huge = post_residual > 50;

    // Dead space penalty: tiny leftover is perfect (reward), small leftover is
    // nearly unusable (penalize), medium is semi-usable, large/huge are fine.
    if tiny {
        score -= 60.0;
    } else if small {
        score += 45.0;
    } else if medium {
        score += 8.0;
    } else if large {
        score -= 5.0;
    } else if huge {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Harmonic class of the gap created for the next item.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 80.0;
            } else if gap <= 10 {
                score += 30.0;
            } else if gap <= 25 {
                score -= 10.0;
            } else {
                score -= 20.0;
            }
        } else {
            // Next item cannot use this bin's leftover; leftover becomes dead
            // space unless it is large enough to matter later.
            if small {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, especially
    // with a clean post-residual class.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
        if medium || large {
            score -= 15.0;
        }
    }

    // New-bin candidate: opening a new bin is only attractive when every open
    // bin would leave a tiny unusable leftover, or when the stream is early and
    // there is slack.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a bin.
        score += 70.0;
        // Early stream: cheaper to open bins (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 40.0 * (1.0 - progress);
        // Many open bins with large mean residual: discourage new bin.
        score += 0.3 * open_bins_count as f64;
        if mean_residual > 50.0 {
            score += 20.0;
        }
        // If this is a last-chance situation, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    }

    // Mild preference for filling fuller bins (best-fit flavor) modulated by
    // the harmonic class of the current residual.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Modulo-style tiebreak on post_residual: leftovers that are multiples of
    // common item sizes (10/20/25/50) are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 || post_residual % 25 == 0 {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are dead space.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fit, zero waste
    } else if post_residual <= 10 {
        // unusable-ish sliver: heavy penalty scaled by how tiny the gap is
        score += (11 - post_residual) as f64 * 60.0;
    } else if post_residual <= 20 {
        score += (21 - post_residual) as f64 * 8.0;
    } else {
        // larger residual is reusable; mild reward proportional to size
        score -= post_residual as f64 * 0.15;
    }

    // Dead space relative to capacity: penalize wasting more than half the bin
    if post_residual as f64 > bin_capacity as f64 * 0.5 {
        score += (post_residual as f64 - bin_capacity as f64 * 0.5) * 1.5;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item fits
    // very poorly everywhere else (large residual mismatch) or many bins are open.
    if bin_residual == bin_capacity {
        // baseline penalty that grows with open bin pressure
        score += 80.0 + open_bins_count as f64 * 4.0;
        // lookahead: if the next item is small it can use leftover space elsewhere,
        // so opening a new bin is less attractive
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 40.0;
        }
    } else {
        // Reward placing into bins whose residual is close to mean (consolidation),
        // penalize draining bins far below the mean (fragmentation).
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.3;

        // Lookahead synergy: if the next item exactly consumes the post residual,
        // reward heavily.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item can't use this gap -> dead space risk
            score += post_residual as f64 * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight fills.
    score += open_bins_count as f64 * 0.5 + post_residual as f64 * (open_bins_count as f64 / 20.0);

    // Late in the stream, minimize leftover waste more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // matches the next item (perfect chaining), penalize leftovers that are
    // just barely too small for the next item (dead space).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strong bonus.
        score -= 25.0 * (1.0 - diff / (bin_capacity as f64 * 0.5)).max(-1.0);
        if post_residual < next_item_size {
            // Leftover can't host the next item: dead-space penalty scaled by
            // how much of the leftover is wasted relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Compare against mean residual: bins tighter than average are more
    // valuable to fill; loose bins should absorb this item.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.15 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make opening a new bin attractive only when the current item leaves a
    // large, unusable remainder in existing bins. Penalize new bins mildly
    // otherwise to encourage packing into open bins.
    if bin_residual == bin_capacity {
        // Slight structural preference for a fresh bin when the item is large
        // relative to capacity (large items pair poorly with partial fills).
        let frac = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 12.0 * frac;
        // If many bins already fit the item, discourage opening yet another.
        if fitting_bins_count > 1 {
            score += 6.0 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // Early in the stream, allow more bins (future flexibility); late in the
    // stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    // Small tie-break: prefer bins with lower residual (tighter bins) when
    // everything else is close.
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post-residuals that are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if next item can fit the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 10.0;
        }
        // Bonus if next item exactly matches post-residual.
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // New-bin candidate logic: empty bin gets a baseline cost so it's chosen only
    // when placements in open bins would be poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Later in the stream, be more reluctant to open new bins if many are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress * (open_bins_count as f64 / 10.0);
        // But if next item is large and current item small, a fresh bin may be fine.
        if next_item_size >= item_size && item_size <= 30 {
            score -= 12.0;
        }
    }

    // Global state: penalize placing into bins whose residual deviates badly from mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer bins with larger residuals when item is large (avoids fragmentation).
    if item_size > 50 {
        score -= 0.1 * bin_residual as f64;
    }

    // Mild time-horizon adjustment: early on, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap; // how full bin becomes

    // Reward tight fits more strongly as stream progresses (smooth polynomial coupling)
    let tightness = (item_size as f64 / cap).powi(2);
    score -= (1.0 + 3.0 * progress) * tightness * cap * 0.35;

    // Penalize leaving awkward mid-range residuals (dead space), penalty grows with progress
    let pr = post_residual as f64;
    let awkward = 4.0 * (pr / cap) * (1.0 - pr / cap); // peaks at half-empty
    score += awkward * cap * (0.10 + 0.35 * progress);

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 && post_residual > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let slack = pr - next;
            score -= (1.0 - slack / cap) * (8.0 + 12.0 * progress);
        } else {
            score += (next - pr) / cap * (10.0 + 10.0 * progress);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 2.0 * progress);

    // Deviation from mean residual: prefer bins near mean to keep residuals balanced
    score += ((pr - mean_residual) / cap).abs() * (5.0 + 5.0 * progress);

    // New-bin candidate: make it attractive only early or when post_residual would be very large
    if bin_residual == bin_capacity {
        let early = (1.0 - progress).powi(2);
        let waste = pr / cap;
        score += 20.0 * progress - 25.0 * early - 30.0 * waste * waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which "slot" of capacity it falls into.
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor(); // 0..8 capacity-fraction classes

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space classes (0 < post < 10) are nearly useless: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic modulo structure: leftovers divisible by common item sizes (10,20,25,50)
    // are reusable by future items. Reward such "harmonic" residuals.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 25 == 0 { score -= 8.0; }
        if post_residual % 50 == 0 { score -= 6.0; }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use leftover: penalize proportionally to wasted class
            score += class * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins tighter than average (best-fit style correction).
    score -= (mean_residual - post) * 0.5;

    // Late in the stream, consolidate harder: reward filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0 * (1.0 - post / cap);

    // New empty bin candidate: make it only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when current fit is poor.
        let poor_fit = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
        score += 55.0 - poor_fit + (open_bins_count as f64) * 2.0;
    }

    // Integer-division threshold: large post_residual chunks (>= half capacity) are fine.
    if post_residual >= bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10) can
    // realistically use are heavily penalized with a non-linear ramp.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    }
    // Mid-range gaps (11..25) are only usable by small items; mild penalty.
    if post_residual > 10 && post_residual <= 25 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 6.0;

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (i.e., penalize the new-bin candidate and low-fill bins less relevant here).
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward;
    // if post-residual is too small for next item but next item fits elsewhere, neutral.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 2.0; // dead space relative to lookahead item
        }
    }

    // Progress-aware scaling: early in the stream, keep bins compact for future flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate calibration: empty bin has large post_residual; make it
    // attractive only when the current bin would leave a very bad gap.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 + open_bins_count as f64 * 0.35;
        if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals the next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual (good 2-step lookahead)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.25;
    }
    // Next item does NOT fit: post residual becomes dead space unless small
    else if next_item_size > 0 {
        score += 10.0 + post_residual as f64 * 0.15;
    }

    // Compare against mean residual of open bins: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit decently
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 35.0 + waste * 0.3 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    }

    // Small absolute dead space is fine regardless
    if post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post-residual non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        score += (pr / 20.0).powi(2) * 3.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving large dead space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into existing space (reward filling this bin).
    if open_bins_count > 0 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fill_ratio * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be picky (penalize mediocre fits);
    // late in the stream, just get items placed anywhere that fits.
    let t = step_index as f64 / total_items.max(1) as f64;
    let pickiness = 1.0 - t;
    score += 20.0 * pickiness * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when the item
    // is huge relative to capacity or no open bin is decent.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 55.0 - 40.0 * big_item + 30.0 * desperation - 20.0 * t;
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity - item_size) as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (lower is better), with non-linear shaping.
    let mut score = pr;

    // Smooth non-linear penalty on large dead space: quadratic-quadratic coupling.
    score += 18.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits: sigmoid-like term centered on small post_residual.
    let tightness = (-norm_pr * 8.0).exp() - 1.0;
    score -= 12.0 * tightness;

    // Lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 10.0 * (-gap * 10.0).exp();
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (concentrate waste in fewer bins) via smooth interaction.
    let dev = (mean_residual - pr) / cap;
    score += 6.0 * dev * (0.5 + progress);

    // Slight preference toward filling fuller bins as stream progresses.
    score -= 5.0 * progress * (item_size as f64 / cap);

    // New-bin candidate: make it moderately attractive only when post_residual
    // of existing bins would be very large; smooth logistic gate.
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-(norm_pr - 0.5) * 10.0).exp());
        score += 8.0 * gate - 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact or near-exact fills are ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Harmonic class of post_residual: dead space in low residue classes
    // is harder to fill (small items only). Penalize awkward residues.
    let r_mod = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        // Dead space smaller than the minimum item size is pure waste.
        score += 60.0;
    } else if r_mod != 0 && post_residual < 20 {
        score += 25.0;
    }

    // Large residual bins are valuable; penalize burning a big residual
    // on a small item (wasteful coupling).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.4 && bin_residual > 50 {
        score += 30.0 * (1.0 - fill_ratio);
    } else if fill_ratio >= 0.7 {
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    // among open bins, or when this is a very early step.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 120.0; // no open bin fits: new bin is necessary
        } else {
            score += 50.0; // discourage opening new bins when alternatives exist
        }
    }

    // Lookahead coupling: if the next item can exactly fill this bin's
    // post-residual, reward saving that space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 5 {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item won't fit here; residual risks becoming dead space.
            score += 15.0;
        }
    }

    // Mean residual coupling: if open bins are already slack, avoid
    // adding another slack bin.
    if mean_residual > 40.0 && post_residual > 40 {
        score += 20.0;
    }

    // Late-stream consolidation: as the stream progresses, prefer
    // compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 25.0 * progress * fill_ratio;

    // Many open bins: encourage closing them out via tight fits.
    if open_bins_count > 5 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are wasted. Penalize unusable gaps quadratically.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 200.0 * (dead_threshold - post_residual as f64).powi(2);
    } else {
        // Reward tight fits: the smaller the usable leftover, the better.
        score -= 15.0 / (post_residual as f64).ln();
    }

    // Penalize large leftover gaps that will likely become dead space anyway:
    // a residual in the "awkward zone" (just above dead threshold) is bad.
    if post_residual > 10 && post_residual < 25 {
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading items across many bins,
    // but relax pressure late in the stream when closing bins matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 - 2.0 * progress).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is ideal; reward it heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // If next item cannot fit in the leftover, leftover risks becoming dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0 * (post_residual as f64 / dead_threshold).min(3.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit (i.e., mean residual is very tight).
    if bin_residual == bin_capacity {
        score += 50.0 + mean_residual * 0.5;
        // Late in the stream, prefer filling existing bins even more.
        score += 100.0 * progress;
    } else {
        // Perfect fit into an existing bin is the gold standard.
        if post_residual == 0 {
            score -= 150.0;
        }
        // Reward using bins whose residual is close to the item (efficient usage).
        score -= 0.3 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual exactly matches
    // the next item size (perfect 2-chain), with graded partial rewards.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // graded reward decaying quadratically with the leftover gap
            score -= 120.0 * (1.0 - gap / bin_capacity as f64).powi(2);
        } else {
            // next item won't fit: penalize proportionally to how much
            // post_residual is "wasted" relative to the next item
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins far below mean residual are scarce
    // resources; reward filling them, penalize filling already-loose bins.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.35 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large (poor fit everywhere is plausible) late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 90.0 - 50.0 * progress - 30.0 * tightness;
        // but a fresh bin pairs perfectly with the next item
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= item_size as i64 {
            score -= 40.0;
        }
    }

    // Mild preference for tight fits overall (small post_residual relative
    // to capacity) to reduce fragmentation.
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Penalize creating small unusable dead space (< smallest item 1, but generally small gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted residual
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 0.0 {
        let consolidation = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * consolidation * (1.0 - progress);
    }

    // Prefer reusing existing bins when many are open
    if bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New bin candidate: penalize unless current options are poor
        score += 20.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open new bin
        }
    }

    // Time horizon: late in stream, avoid leaving scattered residuals
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= poly * 40.0 * (0.5 + progress);

    // Penalize large dead space more strongly as stream progresses
    score += (x * x * x) * 25.0 * progress;

    // Reward tight fits (small post_residual) smoothly
    score -= (1.0 - x) * (1.0 - x) * 15.0;

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving space usable by next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let usable = if pr >= n { 1.0 } else { 0.0 };
        let gap = (pr - n).abs() / cap;
        score -= usable * 10.0 * (1.0 - gap);
        score += (1.0 - usable) * 5.0;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.3 * progress;

    // Deviation from mean residual: prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Reward exact-harmonic residuals (residual divisible into nice classes).
    let gcd_like = |a: i64, b: i64| -> i64 { let mut a = a; let mut b = b; while b != 0 { let t = a % b; a = b; b = t; } a };
    let g = if cap > 0 { gcd_like(pr.max(0), cap) } else { 1 };
    if g >= 5 { score -= 6.0; }           // residual is a clean fraction of capacity
    if pr % 10 == 0 && pr > 0 { score -= 4.0; } // decimal-harmonic class

    // Penalize tiny dead space: post_residual in awkward small classes.
    if pr > 0 && pr < 10 { score += 25.0; }
    if pr >= 10 && pr < 20 { score += 8.0; }

    // Harmonic coupling with next item: does the next item land on the same class?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n == pr { score -= 20.0; }                 // perfect next fit
        else if pr > n && (pr - n) % 10 == 0 { score -= 12.0; } // leaves harmonic remainder
        else if n > pr { score += 15.0; }             // next item won't fit here
        // Integer-division threshold: quotient of residual by next item size
        let q = if n > 0 { pr / n } else { 0 };
        score -= q as f64 * 3.0;
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: make it unattractive unless residual pressure is high.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        // But if all open bins leave bad harmonic classes, allow opening.
        if mean_residual < 15.0 { score -= 40.0; }
    }

    // Mild stream-phase regularization.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.05 * phase;

    // Prefer tight fills relative to capacity fraction.
    score -= (1.0 - post_residual as f64 / cap_f) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the minimum
    // item (1..10 range) are unusable dead space -> strong penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    }
    // Gaps below the next item's size are dead space w.r.t. lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Perfect or near-perfect fills are highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills
    // and only open new bins when fits are poor.
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded
        // (low mean residual) or the fit would leave a bad gap.
        let bad_fit = if post_residual < 10 && post_residual > 0 { 1.0 } else { 0.0 };
        score += 30.0 + pressure * 10.0 - mean_residual * 0.8 - bad_fit * 45.0;
    } else {
        // Reward using existing bins more when many are open.
        score -= pressure * 4.0;
        // Prefer bins whose residual is close to the item (tight fit).
        score += (bin_residual - item_size) as f64 * 0.1;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    } else {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match: small gap between post_residual and next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (-gap / 12.0).exp();
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: penalize proportionally to waste
        let shortfall = (next_item_size - post_residual) as f64;
        score += 8.0 * (1.0 - (-shortfall / 25.0).exp());
    }

    // Relative to mean residual: prefer filling bins that are tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize tiny dead space (< 10) that likely becomes unusable
    if post_residual < 10 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score = bin_capacity as f64 - 20.0 + 30.0 * desperation;
        // late in stream, avoid opening bins wastefully
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Penalize small dead space that can never be reused by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else {
            score += 4.0;
        }
        // Perfect chain: post residual exactly matches next item.
        if post_residual as u32 == next_item_size {
            score -= 12.0;
        }
    }

    // Global pressure: when many bins are open relative to stream length,
    // discourage opening new bins (penalize the empty-bin candidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64 / 20.0) * (1.0 - progress * 0.5);
        score += 15.0 + pressure;
        // Opening a new bin is acceptable if mean residual is very low
        // (existing bins are nearly full).
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with below-average residual (consolidate waste).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Early stream: be slightly conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 0.9 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space is costlier -> amplify small residuals penalty
    let coupling = progress * (1.0 - progress * 0.5);
    score -= 25.0 * coupling * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (1.0 - progress);
        } else {
            score += 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for very fragmented residual (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 0.15 * open_bins_count as f64 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead-space penalty: residuals that are too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic class buckets via integer division on post_residual.
    let class = post_residual / 10; // 0..10 classes
    match class {
        0 => score += 15.0,   // 0-9: nearly dead
        1 => score += 5.0,    // 10-19
        2 => score -= 3.0,    // 20-29: useful for small items
        3 => score -= 6.0,    // 30-39
        4 => score -= 8.0,    // 40-49: sweet spot
        5 => score -= 9.0,    // 50-59: sweet spot
        6 => score -= 7.0,    // 60-69
        7 => score -= 4.0,    // 70-79
        8 => score -= 2.0,    // 80-89
        _ => {}               // 90+: fresh-ish bin
    }

    // Modulo-10 resonance: residuals divisible by 10 pair well with
    // typical item sizes; odd leftovers are awkward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 10 != 0 && post_residual < 20 {
        score += 3.0;
    }

    // Lookahead coupling: reward exact fit for next item, penalize near-miss.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic decay of chain value with slack
            score -= 20.0 / (1.0 + slack / 10.0);
            // modulo class mismatch penalty
            if post_residual % 10 != next_item_size % 10 {
                score += 2.0;
            }
        } else {
            // next item cannot fit here; residual is a commitment
            score += 5.0 + (nxt - post) / 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when existing bins are tight
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        // fresh bin baseline: mildly attractive when many bins are open and tight
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 10.0 * progress + 0.15 * mean_residual - 2.0 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 10.0; // big items like a fresh bin
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual < 20 {
            score -= 5.0;
        }
    }

    // Small global tie-breaker toward balanced residuals.
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that few items can use.
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (tighter bins get used first).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Late-stream tightening: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
