    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        // More open bins => prefer reusing; fewer fitting bins => new bin more attractive
        let reuse_bias = (open_bins_count as f64).ln().max(0.0) * 10.0;
        let fit_scarcity = if fitting_bins_count <= 1 { 40.0 } else { 0.0 };
        score += base_penalty + reuse_bias - fit_scarcity;
