        // discourage hoarding bins when few exist
        if open_bins_count < 3 {
            score -= 6.0;
        }
    }

    // Global pressure: many open bins -> prefer consolidating into fullest bins
    if open_bins_count > 5 {
        score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: late in stream, be greedy about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with quadratic shaping
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, waste is cheap (bins will be reused); late, waste is costly.
    let waste_penalty = norm_pr * norm_pr * (1.0 + 3.0 * progress * progress);
    score += waste_penalty * cap;

    // Reward using an existing bin relative to open-bin pressure (smooth sigmoid-like)
    let open_pressure = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).tanh();
    score -= 5.0 * open_pressure * (1.0 - norm_pr);

    // Last-chance bin: strongly favor filling it (smooth exponential urgency)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - norm_pr).exp();
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 8.0 * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item, scaled by progress
        score += 4.0 * progress * (1.0 - norm_pr);
    }

    // Mild preference for bins with below-average residual (concentrate filling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ---- New-bin candidate ----
    if bin_residual == bin_capacity {
        let mut s = 120.0 - item_size as f64;
        // No existing bin can host the item: opening is mandatory.
        if fitting_bins_count == 0 {
            s -= 500.0;
        }
        // If the lookahead item pairs well with the leftover of this fresh bin, encourage opening.
        if next_item_size > 0 {
            let pair_left = bin_capacity.saturating_sub(item_size + next_item_size);
            if pair_left == 0 {
                s -= 150.0;
            } else if (bin_capacity - item_size) >= next_item_size {
                s -= 40.0 - (pair_left as f64) * 0.3;
            }
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        s += progress * 15.0;
        return s;
    }

    let mut score = post_residual as f64;

    // Perfect fit: close the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // ---- Lookahead coupling: does next_item_size land in the leftover? ----
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_left = post_residual - next_item_size;
        if pair_left == 0 {
            score -= 400.0; // two-step exact chain
        } else {
            score -= 60.0 - (pair_left as f64) * 0.4;
        }
    } else if next_item_size > 0 {
        // leftover can't host next item: dead space unless tiny
        if post_residual < 10 {
            score -= 10.0; // negligible residue is fine
        } else {
            score += (post_residual as f64) * 0.25; // penalize stranded space
        }
    }

    // ---- Harmonic class logic on post_residual (mod-10 residue classes) ----
    // Residues divisible by 10 or 5 are "harmonic" (more likely reusable by
    // common item sizes); odd/prime residues are stranded more often.
    let class = post_residual % 10;
    let harmonic_bonus: f64 = match class {
        0 => -20.0,
        5 => -10.0,
        2 | 4 | 6 | 8 => -3.0,
        _ => 4.0, // odd residues: penalty
    };
    score += harmonic_bonus;

    // Integer-division threshold: leftover in the top quarter of capacity is
    // still valuable space; leftover in the bottom quarter is near-dead.
    let quarter = bin_capacity / 4;
    if post_residual >= 3 * quarter {
        score -= 15.0;
    } else if post_residual <= quarter {
        score += 8.0;
    }

    // ---- Scarcity: last-chance bin ----
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // ---- Global context ----
    // If mean residual is high, prefer bins that reduce dispersion.
    score -= (mean_residual - post_residual as f64).abs() * 0.1;
    // Many open bins: reward tightening.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small nonzero gaps are nearly unusable later.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr <= 10.0 {
            score += 40.0 * (1.0 - pr / 10.0); // worst: 1..10 units left
        } else if pr <= 20.0 {
            score += 12.0 * (1.0 - (pr - 10.0) / 10.0);
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Reward residual that can still hold the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage creating another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (better consolidation).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches the next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 80.0 / (1.0 + gap);
        // exact 2-step match: bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // penalize dead space smaller than any plausible next item
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Tightness reward: smaller post_residual relative to capacity is better
    score -= 0.3 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: this is the only bin that fits; strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with below-average residual (denser bins) slightly
    score += 0.2 * (post_residual as f64 - mean_residual);

    // New empty bin candidate: penalize so it's only chosen when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 200.0;
        // but if no open bin fits (this is the only fitting candidate), reduce penalty
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fit_ratio * fit_ratio;
    }

    // Penalize post_residual that is too small to ever be useful again
    // (dead space below the minimum item size is pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Next item won't fit here; mild penalty proportional to overflow.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer filling bins that are already relatively full (larger item_size
    // relative to residual), reducing fragmentation across many bins.
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 25.0 * fill_frac;

    // Global state: when many bins are open with high mean residual,
    // discourage opening new bins / spreading waste.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are underutilized.
        score += 40.0 + 0.5 * mean_residual;
        // Early in the stream, opening bins is cheap; late, it is not.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        if open_bins_count > 0 {
            score += 5.0 * (open_bins_count as f64).ln();
        }
    } else {
        // Reward using existing bins more when many are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild time-varying exploration pressure: later in the stream, tighten
    // packing (penalize loose fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Tightness of fit: reward filling the bin densely (non-linear in fill fraction)
    let fill = item / cap;
    let tightness = (fill * fill) * (1.0 - progress);
    score -= 30.0 * tightness * (res / cap);

    // Penalize small dead space quadratically: residuals that are hard to reuse
    let dead = post / cap;
    if post > 0.0 {
        score += 12.0 * dead * dead * (1.0 + progress);
    }

    // Lookahead coupling: bonus if next item fits exactly in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 20.0 * (1.0 - gap / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (gap / cap) * progress;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Prefer bins with residual below mean residual (consolidate space)
    score += 3.0 * (post - mean_residual) / cap;

    // New-bin candidate: make it unattractive unless no open bin fits well
    if bin_residual == bin_capacity {
        let scarcity = if open_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            1.0
        };
        score += 15.0 + 40.0 * (1.0 - progress) * scarcity + 10.0 * (1.0 - scarcity);
    }

    // Mild preference for more crowded bins early on
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead-space penalty: leftover in (0, smallest plausible item] is wasted.
    if pr > 0.0 && pr < 10.0 {
        score += 40.0 * (10.0 - pr) / 10.0;
    }

    // Perfect-fit harmonic classes reward exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: can next item fit into the harmonic class left behind?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            // Next item fits: reward tighter residual match.
            score -= 25.0 * (1.0 - (pr - ni) / cap);
        } else {
            // Next item cannot use this bin: leftover likely becomes dead space.
            score += 12.0 * (ni - pr) / cap;
            // If leftover is in a "hard" class (small, unusable), penalize more.
            if pr < quarter {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins over emptier ones (mean-residual contrast).
    if open_bins_count > 0 {
        score += 0.5 * (mean_residual - pr) / cap * 10.0;
    }

    // Discourage opening new bins early in the stream unless residual is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New-bin candidate: baseline near quarter-capacity leftover value.
        score = quarter + 20.0 * (1.0 - progress);
        // If no open bin fits well, allow new bin more readily.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size as f64 > quarter {
            score -= 8.0;
        }
    }

    // Integer-division threshold: residual in [0,eighth) is high-risk dead space.
    if post_residual > 0 && (post_residual as f64) < eighth {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..100 interface, but treat < 10 as likely dead space)
    // are heavily penalized with a super-linear ramp.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Medium dead space (10..30) is also risky if it can't hold the lookahead item.
    if post_residual >= 10 && post_residual < 30 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 12.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual as f64 <= item_size as f64 * 0.1 {
        score -= 15.0;
    }

    // Reward fitting the lookahead item into the leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when open-bin pressure is
    // low or this bin would fit the next item well; otherwise discourage it.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        let lookahead_good = next_item_size > 0 && next_item_size <= 50;
        score += 5.0 + pressure * 10.0;
        if lookahead_good {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Open-bins pressure: mildly discourage spreading across many bins when
    // mean residual is already large (bins are mostly empty).
    if mean_residual > 60.0 && bin_residual != bin_capacity {
        score += 4.0;
    }

    // Late-stream tightening: as the stream ends, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect two-step fit: place here
        } else if post_residual as f64 > next {
            // next item could still fit here afterwards: mild bonus scaled by tightness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit after placement: penalize dead space creation
            score += 10.0 + 0.5 * diff;
        }
    }

    // Prefer bins tighter than the mean residual (good packing), penalize loose bins
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin candidate unless current bins are nearly exhausted
    if bin_residual == bin_capacity {
        let avg_tight = mean_residual / bin_capacity as f64;
        if avg_tight > 0.35 {
            score += 80.0; // keep using open bins
        } else {
            score -= 15.0; // open bins too full, new bin reasonable
        }
    }

    // Late in the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that cannot fit the next item's minimum size.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // stranded residual
        } else if post_residual >= next_item_size {
            // Reward leaving room exactly usable by next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-gap / 25.0).exp();
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many options: prefer the tightest, mild penalty to break ties toward small residuals.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when fits are poor or many bins are open.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let fit_quality = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        // Penalize opening a new bin generally; reduce penalty late in stream.
        let horizon = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * (1.0 - 0.5 * horizon);
        // But if this item would leave tiny waste anywhere, opening is fine.
        score -= 15.0 * fit_quality;
    }

    // Prefer filling bins with large residuals when mean residual is high (fragmentation risk).
    let frag_pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 6.0 * frag_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with residuals near common item sizes (modular fit).
    for s in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
        if post_residual == s {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post_residual (waste), softened as stream progresses
    let mut score = pr * (1.0 + 0.5 * norm_pr) - 8.0 * progress * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (small post_residual) with smooth coupling to item size
    score -= 6.0 * norm_item * (1.0 - norm_pr).powi(2);

    // Penalize bins whose residual diverges from mean (fragmentation pressure)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { (pr / nx).max(0.0) };
        score -= 5.0 * fit_next * (1.0 - progress);
        // Penalize leaving residual just barely too small for next item (dead space)
        if pr < nx && pr > 0.0 {
            score += 4.0 * (nx - pr) / cap * (1.0 - progress);
        }
    }

    // New-bin candidate: prefer opening fresh bins early, penalize later
    if bin_residual == bin_capacity {
        score += 4.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Class 0: post_residual is a multiple of 20 (harmonious leftover, easy to fill later)
    let harmonic = (post_residual % 20) == 0;
    if harmonic {
        score -= 6.0;
    }

    // Penalize large awkward residuals in coarse bands (integer division thresholds).
    let band = post_residual / 15; // 0..6
    score -= band as f64 * 1.5;

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 12.0; // perfect two-item packing
            } else if slack <= 10 {
                score -= 7.0;
            } else {
                score -= 3.0 * (1.0 - slack as f64 / cap);
            }
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 4.0 * (1.0 - post / cap);
        }
    } else {
        // last item: just minimize residual
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Prefer bins below mean residual (fill emptier bins first keeps spread balanced).
    score += 0.05 * (post - mean_residual);

    // New-bin candidate handling: opening a new bin is only attractive if no open bin
    // fits well. For the empty-bin call (residual == capacity), make it costly unless
    // it enables a perfect packing of item + next item.
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0
            && item_size + next_item_size <= bin_capacity
            && (bin_capacity - item_size - next_item_size) % 20 == 0;
        if perfect {
            score -= 10.0;
        } else {
            score += 10.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Slight progression bias: late in the stream, tighten up (prefer tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are waste.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space: cannot host the next item. Penalize quadratically,
            // stronger the closer the gap is to being "almost useful".
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 + 0.35 * gap * gap;
        } else {
            // Reward residuals that can still host the lookahead item.
            score -= 8.0;
            // Extra reward for hosting next item snugly (tight chain packing).
            let snug = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - snug / bin_capacity as f64);
        }
    }

    // Reward tight fit of the current item (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, opening a new bin (empty candidate) is cheaper.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure so it loses to good fits
        // but wins when open bins would create dead space.
        score += 18.0 + 2.5 * pressure;
        // Early in the stream, new bins are more acceptable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Reusing an open bin relieves pressure slightly.
        score -= 1.5 * pressure.sqrt();
    }

    // Discourage bins whose residual deviates badly from the mean residual
    // (keeps residual distribution balanced, avoids stranded tiny gaps).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild penalty for leaving residuals in the "hard to fill" zone (1..=next_item_size-1
    // already covered); also penalize mid-range awkward gaps like 10..30 when no lookahead.
    if next_item_size == 0 && post_residual > 0 && post_residual < 30 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => strong reward
        if diff == 0.0 {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to tightness
            score -= 6.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving awkward space
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize residuals far above the mean residual (wasteful fill)
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish score; only attractive when fits are poor
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55
            + (post_residual as f64 - mean_residual) * 0.3
            - if next_item_size > 0 && post_residual >= next_item_size { 5.0 } else { 0.0 };
        if fitting_bins_count <= 1 {
            score += 15.0; // discourage new bin when an existing bin is a last chance
        }
    }

    // Slight preference for tighter fills as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: dead space below ~20 is nearly unusable.
    if post_residual < 20 {
        score -= 60.0 * (20.0 - post_residual as f64) / 20.0;
    }
    // Penalize mid-range wasted space (awkward residuals 20..40).
    if post_residual >= 20 && post_residual <= 40 {
        score += 12.0;
    }

    // Lookahead coupling: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 80.0;
        } else if (diff as u32) <= 10 {
            score -= 30.0 * (1.0 - diff as f64 / 10.0);
        } else {
            // next item won't fit here: mild penalty scaled by wasted potential
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }
    // Many fitting bins: prefer the tightest anyway; slight crowding pressure.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: when many bins are open with high mean residual,
    // discourage spreading; when few bins open, filling them is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score -= 10.0 * progress; // late in stream, prefer consolidating into existing bins

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_options = if mean_residual > 0.0 && (item_size as f64) > mean_residual + 25.0 { 1.0 } else { 0.0 };
        let early = (1.0 - progress) * 0.3;
        let reward = 35.0 * desperation + 25.0 * poor_options + 40.0 * early
            + if next_item_size > 0 && next_item_size >= 50 { 15.0 } else { 0.0 };
        score -= reward;
        // baseline new bin has full residual; keep it slightly worse than a perfect fit
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: penalize wasted space, amplified non-linearly as post-residual grows
    let mut score = prn * prn * cap;

    // Smooth coupling: waste hurts more as the stream progresses (less future to amortize)
    score += 12.0 * prn * prn * progress;

    // Reward tight fits (fit_ratio near 1) with a smooth quadratic bonus
    score -= 6.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Penalize large residual relative to mean residual of open bins (imbalance)
    score += 0.4 * (pr - mean_residual).abs();

    // Lookahead: reward leaving residual that fits the next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.15 * diff;
        score -= 3.0 * (1.0 - diff / cap).max(0.0);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * prn;

    // New-bin candidate: prefer it only when existing fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - fit_ratio) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (<= 10) are near-perfect; larger leftovers
    // in coarse bands of 20 are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class bonus by integer division of post_residual into bands of 20
        let band = post_residual / 20; // 0..=5
        score -= (5 - band) as f64 * 15.0;

        // Tiny leftover (<=10) is excellent: reward strongly
        if post_residual <= 10 {
            score -= 40.0;
        }

        // Dead-space penalty scaled by fraction of capacity wasted
        score += 0.5 * (pr * pr) / cap;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: big reward, stronger the tighter the fit
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 60.0 + 40.0 * tightness;
        } else {
            // next item does not fit: penalize, worse if gap is large
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // if no open bin fits well. Penalize new bin unless item is large
    // relative to a fresh capacity.
    if bin_residual == bin_capacity {
        // fresh bin: baseline score ~ item_size leaves residual = cap - item
        // penalize mildly so decent open bins win, but allow it when
        // existing residuals are poor (mean residual low means bins are full)
        score += 30.0 + 0.2 * mean_residual;
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Many open bins with high mean residual: prefer consolidating into
    // bins with residual close to the mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (below min item size 1..10)
    // are pure waste; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Dead space that cannot fit the lookahead item is likely waste too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0 * (next_item_size - post_residual as u32).min(30) as f64 / 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 15.0 / (1.0 + tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // (avoid opening new ones); penalize the new-bin candidate implicitly via residual
    // but also add pressure when open_bins_count is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 8.0 + 0.6 * pressure;
    } else {
        // Existing bin: small consolidation reward.
        score -= 0.25 * pressure;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: bins far below mean residual hold more future room;
    // mildly prefer bins whose residual is below mean (already partially filled well).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference to keep large residual bins for large future items.
    if next_item_size > 0 && post_residual < next_item_size as u32 && bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        let next = next_item_size as f64;
        // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
        let match_diff = (post_residual as f64 - next).abs();
        score -= 40.0 * (1.0 - match_diff / bin_capacity as f64).max(0.0);
        // Also reward next item fitting exactly after this placement chain (post_residual >= next)
        if post_residual as f64 >= next {
            score -= 10.0 + 0.2 * (post_residual as f64 - next);
        } else {
            // dead space that next item cannot use
            score += 0.15 * (next - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Tight fits are good: small post_residual relative to capacity
    score -= 0.1 * (bin_capacity as f64 - post_residual as f64);

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded
    if is_new_bin {
        let crowd = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        score += 30.0 - 20.0 * crowd - pressure * (1.0 - progress);
        // opening a new bin is fine if item is large and fits nothing else well
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins near the end
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear squash.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual in [1, 9] is nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow: mild penalty scaled by overflow
            let over = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 10.0 * over;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only when many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if open_bins_count > 4 {
        score += 0.15 * dev;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits
    // more) since there is room to wait for better fits; later, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: an empty bin has post_residual = C - item.
    // Prefer filling existing bins unless the item is large relative to capacity
    // and the fit into open bins would be loose.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more as stream progresses (fewer
        // chances to fill it) and when many bins are already open.
        score += 20.0 + 0.5 * open_bins_count as f64 + 30.0 * progress;
        // But if the item is huge, a fresh bin is actually fine.
        if item_size >= 70 {
            score -= 25.0;
        }
    }

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (spread items); later, demand tight packing.
    let tightness = 1.0 + 2.0 * t * t;
    score *= tightness;

    // Smooth dead-space penalty: quadratic bowl penalizing small-but-nonzero residuals
    // (unusable slivers) while rewarding exact fills (post_residual == 0).
    let dead = if pr > 0.0 {
        let inv = 1.0 / norm_pr.max(1e-6);
        -inv.min(50.0) // reward near-fills smoothly
    } else {
        -30.0 // perfect fit bonus
    };
    score += dead * (0.5 + 0.5 * t);

    // Lookahead coupling: reward residuals that can host the next item, penalize
    // residuals just barely missing it (quadratic smooth interaction).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let lookahead = if gap >= 0.0 { -8.0 } else { 4.0 * (gap / 20.0).powi(2) };
        score += lookahead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for proliferating bins relative to mean residual spread.
    score += 0.05 * (open_bins_count as f64).sqrt() * (1.0 - norm_pr);

    // New-bin candidate: only attractive when open bins fit poorly (high mean residual usage mismatch).
    if bin_residual == bin_capacity {
        score = score.max(0.0) + cap * 0.5 + (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: residual divisible into nice chunk sizes (divisors of capacity).
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, extremely desirable
    } else if pr <= 10 {
        -8.0 // tiny dead space, nearly full bin
    } else if pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0 {
        -6.0 // harmonic residual: likely to be filled by future items
    } else if pr % 5 == 0 {
        -2.0
    } else {
        6.0 // non-harmonic dead space penalty
    };
    score += harmonic_bonus;

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Even better if it fits harmonically (small slack left after next item)
            let slack = pr - next_item_size;
            let lookahead_reward = if slack == 0 {
                -25.0
            } else if slack <= 10 {
                -12.0
            } else {
                -4.0
            };
            score += lookahead_reward;
        } else {
            // next item cannot use this bin's leftover: penalize leftover more
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate base cost so we
    // only open when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // If many open bins have large mean residual, opening new bins is fine
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits)
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 10.0;

    // Slight preference for bins below mean residual (consolidate emptier bins)
    score += ((post_residual as f64) - mean_residual) * 0.1;

    // Integer-division threshold on post_residual: buckets of usable space
    let bucket = pr / 20; // 0..5
    score += match bucket {
        0 => -5.0,
        1 => 0.0,
        2 => 2.0,
        3 => 4.0,
        _ => 5.0,
    };

    // Stream progression: later in stream, be more aggressive about filling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero residuals are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }
    // Penalize wasting space when lookahead cannot use the gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage new bins and
    // prefer filling existing ones; with few bins, opening is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate score.
        score = 15.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 40.0 / (1.0 + slack as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here: penalize proportionally to wasted lookahead
        let miss = next_item_size - post_residual;
        score += 0.5 * miss as f64;
    }

    // Penalize unusable dead space (residual too small for typical items)
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 0.8 * (25 - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (tight packing) so high-residual bins stay flexible
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: mildly penalize so it wins only when open bins are bad fits
    if bin_residual == bin_capacity {
        score += 25.0;
        // If lookahead matches perfectly in a fresh bin, allow opening it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, allow more bins for flexibility; late, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (1.0 - tightness) * 12.0;

    // Penalize dead space that is too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the resulting residual, reward strongly.
    if next_item_size > 0 {
        let next_fits = (next_item_size as u32) <= post_residual;
        if next_fits {
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 + (slack_after_next as f64) * 0.15;
        } else {
            // Penalize if next item is nearly the residual (wasted opportunity) or residual too small.
            let gap = (next_item_size as f64) - (post_residual as f64);
            if gap > 0.0 && gap < 15.0 {
                score += 6.0;
            }
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_slack = mean_residual / (open_bins_count.max(1) as f64);
        let pressure = (avg_slack / bin_capacity as f64) * (1.0 - progress);
        score += 20.0 * pressure + 5.0;
        // But late in the stream, new bins are cheap since leftovers don't matter much.
        if progress > 0.9 {
            score -= 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog_sq = progress * progress;

    // Squared post-residual penalty grows over the stream (dead space hurts more later).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0 * (0.5 + prog_sq);

    // New-bin candidate: penalize opening a new bin, especially when good fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + 0.15 * open_bins_count as f64;
        // If this bin would leave large unusable space, discourage more.
        score += (waste / bin_capacity as f64).powi(2) * 20.0;
        // Lookahead: if next item fits in the leftover of a fresh bin, soften penalty.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 12.0;
        }
    } else {
        // Reward tight fits (small post_residual) with a smooth non-linear bonus.
        let tight = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= tight.powi(3) * 18.0 * (0.5 + prog_sq);

        // Last-chance bin: strongly reward using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Lookahead synergy: bonus if next item fits the post residual exactly-ish.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 10.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            // Penalize leaving a sliver that the next item cannot use.
            score += (post_residual as f64 / bin_capacity as f64) * 8.0;
        }

        // Prefer bins whose residual is close to the mean residual (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += (dev / bin_capacity as f64) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "friendly" residue classes (multiples of common item sizes) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post-residuals are good, but tiny unusable slivers (<10) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // penalize dead sliver
    }

    // Modulo-10 harmonic classes: leftovers divisible by 10 pair well with
    // typical item sizes (sizes are multiples of 10 in classic streams).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Odd harmonic classes are harder to fill later.
    if post_residual % 10 != 0 && post_residual % 5 == 0 {
        score -= 4.0;
    }
    if post_residual % 2 == 1 {
        score += 3.0;
    }

    // Integer-division thresholds on post_residual: bucket the leftover.
    let bucket = post_residual / 10; // 0..10 buckets
    score -= bucket as f64 * 1.5; // larger usable leftovers mildly favored

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            if chain_waste < 10 {
                score -= 60.0;
            } else {
                score -= (20.0 - chain_waste.min(40) as f64) * 0.5;
            }
            // Harmonic class match between leftover and next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 25.0;
            }
        }
        // If next item cannot fit in this leftover regardless, leftover is terminal:
        // prefer minimizing it now.
        if next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + (bin_residual - item_size.min(bin_residual)) as f64 * 0.2;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / cap;
        score = cap * 0.5 + 60.0 * crowding - 40.0 * progress;
        // Opening a new bin is fine if all open bins have small residuals.
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
    }

    // Mild preference to spread load when many bins are open.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - post / cap);

    // Early stream: favor tight fits to build good structure.
    if total_items > 0 && step_index < total_items / 4 {
        score += post * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus: reward tight packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Penalize post_residual that cannot fit the lookahead item when the
    // lookahead item could have fit the pre-placement residual.
    if next_item_size > 0 {
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 15.0; // destroyed a chance to pair items
        }
        if post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 8.0; // post gap still usable by lookahead
        }
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    // (large residual gap between item and current residuals) or many bins open.
    if bin_residual == bin_capacity {
        let gap = mean_residual - item_size as f64;
        if gap < 0.0 {
            // item barely fits existing bins; new bin is fine
            score -= 10.0;
        } else {
            score += gap * 0.5 + 5.0;
        }
        score += open_bins_count as f64 * 0.5;
    }

    // Favor bins whose residual is close to the item (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Progress-based slight tightening: as stream nears end, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual)
    score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted gap
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
        // Perfect chain: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // last item: just minimize post_residual
        score = post_residual as f64;
    }

    // Relative to mean residual: bins below mean residual are "tighter" -> good targets
    let residual_f = bin_residual as f64;
    let dev = (residual_f - mean_residual) / bin_capacity as f64;
    score += 25.0 * dev;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if next item is large and no bin fits well, new bin is more attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Mild penalty for leaving dead space that no plausible item (>=1) can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual) with a non-linear term.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tightness * 60.0;

    // Perfect or near-perfect fill gets a large bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small to fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: penalize leaving residual that the next item cannot use,
    // reward leaving residual that the next item fits nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64;
            score -= (1.0 - next_tight / bin_capacity as f64) * 12.0;
        } else {
            // leftover useless for next item
            score += (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
    } else {
        // Last item: maximize fill aggressively.
        score -= 10.0;
    }

    // Prefer filling already-open bins over opening new ones;
    // stronger pressure when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by stream progress and open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 12.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Reward using an existing bin slightly more when few bins are open.
        score -= 4.0 / (1.0 + open_bins_count as f64);
    }

    // Coupling with global mean residual: if this bin's post-residual is far
    // below the mean residual, it's a good consolidation.
    let diff = mean_residual - post_residual as f64;
    score += 0.15 * diff;

    // Mild time-horizon modulation: early on, be conservative about tight fits
    // that strand space; late in stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (small post_residual), normalized non-linearly.
    let mut score = (pr / cap).powi(2) * 60.0 + pr * 0.35;

    // Smooth interaction: as stream progresses, penalize large residuals more strongly
    // (waste compounds over time), but early on allow slack for future items.
    score += (pr / cap).powi(3) * 80.0 * progress;

    // Reward placements that leave room for the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score -= 12.0 * (-gap / 25.0) * (1.0 - progress);
        // Penalize if post_residual is positive but too small for next item (dead space)
        let dead = (ni - pr) / cap;
        if dead > 0.0 {
            score += dead * 40.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening new bins when good fits exist,
    // but allow it when mean residual across open bins is small (all bins nearly full).
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 15.0 + 45.0 * (1.0 - mean_norm).powi(2) * (1.0 - progress);
        score -= 10.0 * mean_norm;
        // If item is large, opening fresh bin is safer (smooth term)
        score -= (it / cap) * 10.0;
    } else {
        // Mild reward for consolidating into bins that are already partially filled
        score -= (1.0 - bin_residual as f64 / cap) * 5.0;
    }

    // Penalize bins that will be left with tiny unusable slivers (< ~10), smoothly.
    let sliver = (10.0 - pr).max(0.0) / 10.0;
    score += sliver * sliver * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice"
    // (small, or exactly matching common item-size classes).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    } else if post_residual < 10 {
        score -= 25.0; // tiny dead space, nearly perfect
    } else {
        // Modulo-10 harmonic class: residual divisible by 10 is reusable
        // by the widest range of item sizes.
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 5 == 0 {
            score -= 5.0;
        }
        // Penalize awkward residuals (prime-ish / odd classes)
        if post_residual % 10 != 0 && post_residual % 5 != 0 {
            score += 6.0;
        }
    }

    // Integer-division thresholds: how many mid-size items (>=20) still fit?
    let mid_slots = post_residual / 20;
    score -= 8.0 * mid_slots as f64;

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: exact or near-exact pairing with next item
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 35.0;
            } else if gap < 10 {
                score -= 18.0;
            } else if gap % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot class
            let overshoot = next_item_size - post_residual;
            score += 3.0 + (overshoot / 10) as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline; only attractive when
    // open bins are nearly full on average.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9 + (mean_residual / bin_capacity as f64) * 15.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, opening is fine
        }
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 50.0;
        }
    } else {
        // Prefer bins whose residual is closest to item consumption (tight fit)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
        // Slight preference for bins below mean residual (consolidating waste)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late-stream consolidation: as stream progresses, discourage spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is golden
    } else {
        // Non-linear penalty: squaring relative dead space
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * frac * frac;
    }

    // Reward tight fits relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bins pressure: discourage spreading across many bins
    score += 1.5 * open_bins_count as f64;

    // Prefer bins with residual close to mean (harmonic packing)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Late in stream: be more conservative, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress; // penalize opening new bin, more late
