pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the leftover
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item still fits in the leftover: mild reward proportional to closeness
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize dead space: residuals too small for the smallest possible item (1)
    // but too small to be useful relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual across open bins: prefer bins that are
    // tighter than average (below mean residual) to consolidate fill
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.35 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. penalize opening a new bin when other bins exist and fit
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && open_bins_count > 0 {
            score += 45.0;
        } else {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidation matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty per number of open bins to discourage sprawl
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits into the post_residual (chaining),
    // penalize if post_residual is a small dead zone next item can't use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            // Dead space that the next item cannot use.
            let waste = post_residual as f64;
            score += 0.25 * waste;
        }
        // If next item fits exactly, big bonus.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless
    // open bins are heavily fragmented or it's early with many items left.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Opening a new bin is more attractive early and when mean residual is low.
        let open_bonus = 60.0 * (1.0 - fragmentation) * (1.0 - progress);
        score = 120.0 + open_bonus - 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty for spreading across too many open bins when residuals are high.
    if open_bins_count > 2 && bin_residual != bin_capacity {
        score += 0.5 * (open_bins_count as f64) * (1.0 - mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, with a smooth non-linear (quadratic) waste term
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Stream progress coupling: early on, prefer tight fits less aggressively;
    // later, dead space becomes costlier (polynomial ramp)
    let urgency = progress * progress;
    score *= 1.0 + 1.5 * urgency * pr_norm;

    // Perfect fit reward (smooth exponential-like via polynomial)
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_tightness * fit_tightness;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual pairs well with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 20.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap).max(0.0);
    }

    // Penalize bins far below mean residual (fragmentation risk), smooth coupling
    score += 0.15 * (mean_residual - pr).abs();

    // Mild new-bin penalty so we only open when truly beneficial
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" small classes are rewarded (waste is bounded).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0 + (10 - pr) as f64; // near-perfect
    } else if pr % 10 == 0 {
        score -= 12.0; // round class: likely reusable by future items
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else {
        // odd residuals: penalize proportional to distance from lower multiple of 5
        let r5 = pr % 5;
        score += r5 as f64 * 2.0;
    }

    // Integer-division threshold on post_residual: large dead space is bad,
    // unless it can host the lookahead item exactly.
    if pr >= 40 {
        score += (pr / 20) as f64 * 3.0;
    }
    if next_item_size > 0 && next_item_size <= pr {
        // lookahead fits: reward tighter when leftover after lookahead is small
        let l2 = pr - next_item_size;
        score -= 10.0 + (pr as f64 - l2 as f64) * 0.05;
        if l2 % 10 == 0 { score -= 5.0; }
    } else if next_item_size > pr && next_item_size > 0 {
        // lookahead cannot use this bin's leftover: mild penalty scaled by gap class
        let gap = next_item_size - pr;
        score += (gap / 10) as f64 * 2.0;
    }

    // Capacity fraction coupling: prefer filling a large fraction of the bin.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 20.0;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        let base = 30.0
            + open_bins_count as f64 * 2.0
            + (mean_residual / cap) * 10.0;
        // if lookahead is huge, a fresh bin may be fine
        let adj = if next_item_size > 70 { -10.0 } else { 0.0 };
        score += base + adj;
    }

    // Stream progression: later in the stream, tighten up (avoid sprawl).
    let t = step_index as f64 / total_items.max(1) as f64;
    score += t * 5.0 - (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    let min_item = 1u32;
    let dead_threshold = 10u32; // below smallest useful gap
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual < 25 {
        // small gaps may still fit small items from unknown distribution
        score += 5.0;
    }

    // Reward tight fits (post_residual near zero but not dead).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize bins with already-large residuals relative to mean (spread load).
    if (bin_residual as f64) > mean_residual + 5.0 {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones over new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 5 {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 4.0;
        }
    }

    // New-bin candidate handling: empty bin starts at high baseline so it's
    // only chosen when no open bin scores better.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 1.5;
        // early in stream, opening bins is cheaper
        if progress < 0.2 {
            score -= 20.0;
        }
    }

    score
}

