    }

    // New-bin candidate handling: opening a bin should be discouraged when
    // decent fits exist, but allowed when the item barely fits anywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are open
        // and the mean residual available across them.
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 20.0 + 5.0 * open_bins_count as f64;
        score -= 10.0 * (1.0 - fragmentation); // if existing bins are full-ish, new bin is fine
        if item_size >= 60 {
