    score -= (1.0 - post_residual as f64 / cap) * 4.0;

    // Perfect-fill bonus via harmonic classes: post_residual in {0, 10, 20, 25, 50}
    // are "usable" residuals that future items (10..80 grid) commonly match.
    let harmonic: [u32; 5] = [0, 10, 20, 25, 50];
    if harmonic.contains(&post_residual) {
        score -= 6.0;
    }
    // Penalize dead-space residuals (small odd leftovers that nothing fits).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Mid-range awkward residuals: modulo classes that rarely match item sizes.
    if post_residual >= 11 && post_residual <= 19 && post_residual % 5 != 0 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // exact match is ideal
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is fine early, costly when many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.5 + open_bins_count as f64 * 2.0 + progress * 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    } else {
        // Slight preference for bins below mean residual (balance load).
        score += (post_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linearly).
    let dead_threshold = 10.0_f64.min((bin_capacity / 2) as f64);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward residuals that still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // Creating a gap that cannot hold the next item: penalize, but
            // less harshly if the gap is at least reusable for typical items.
            score += 2.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; make new bins less attractive.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow, unless the
        // item fits no open bin well (last-chance handled below).
        score += 6.0 + 2.0 * open_pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // Existing bin: mild reward for using already-open capacity.
        score -= 1.0 + 0.5 * open_pressure;
    }

    // Last-chance bin: strongly favor filling the only bin that fits,
    // avoiding a new bin for a near-fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual < 15 {
        score -= 10.0;
    }

    // Prefer bins whose residual is close to the item (tight fits) relative
    // to the mean residual across open bins.
    let tightness = (mean_residual - bin_residual as f64).abs();
    score += tightness * 0.05;

