    score -= 0.3 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Progress scaling: later in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Discourage opening new bins when many bins are already open with slack.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 unknown, use 10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // reward leaving space usable by the next item, scaled by how well it matches
            let slack = post_residual - next_item_size;
            score -= 15.0 / (1.0 + slack as f64);
        } else {
            // next item cannot use leftover: mild penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item of stream: minimize waste aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Time horizon: early on, be conservative (prefer filling existing bins);
    // later, allow opening bins when residuals are fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Global fragmentation: if mean residual is high and this bin is above average,
    // prefer filling it; if below average, mildly penalize.
    if mean_residual > 0.0 {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.1;
        // Many open bins with high mean residual -> encourage consolidation
        if open_bins_count > 4 && mean_residual > 20.0 {
            score -= 3.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual of typical open bins or no good alternative exists.
    if bin_residual == bin_capacity {
        let item_f = item_size as f64;
        let waste = bin_capacity as f64 - item_f;
        score = waste * 0.6 + 10.0;
        // If this is a last-chance situation, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins for small items.
        if progress > 0.8 && item_f < 50.0 {
            score += 15.0;
        }
        // Large items pack well into fresh bins.
        if item_f >= 70.0 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer small post-residual, with quadratic sharpening.
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth polynomial coupling with stream progress:
    // early on, mild penalty on large residuals; later, tighten harder.
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score -= 6.0 * prog_term * (post / cap);
    score += 8.0 * progress * progress * (post / cap);

    // Penalize waste relative to mean residual of open bins (smooth coupling).
    score += 0.3 * (post - mean_residual).abs() / cap;

    // Lookahead: reward leaving space that fits the next item (smooth, cubic).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_margin = (post - nxt) / cap;
        if fit_margin >= 0.0 {
            score -= 5.0 * fit_margin * (1.0 - fit_margin) * (1.0 + 2.0 * progress);
        } else {
            score += 2.5 * (-fit_margin) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (residual / cap);
    }

    // New-bin candidate: penalize mildly early, more strongly later,
    // unless it would create a very usable large residual for future items.
    if bin_residual == bin_capacity {
        let base_penalty = 10.0 + 20.0 * progress;
        let usefulness = (post / cap).powi(3); // large residual => small penalty relief
        score += base_penalty - 12.0 * usefulness * (1.0 - progress);
        // Discard new-bin option if an existing bin gives near-perfect fit.
        if item_size as f64 / cap > 0.85 {
            score += 25.0;
        }
    }

    // Small tie-breaker: prefer filling bins with less residual overall.
    score += 0.05 * (residual / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead-space penalty via capacity fractions ---
    let pr = post_residual;
    if pr > 0 {
        // Class 1: tiny slivers (<=10) are almost unusable -> heavy penalty
        if pr <= 10 {
            score += 45.0;
        }
        // Class 2: small-but-usable pockets (11..=20) get a mild penalty
        else if pr <= 20 {
            score += 12.0;
        }
        // Class 3: "harmonic window" — residuals matching common item-size
        // modular bands (multiples of 10, or 25/50/75 quarters) are gold
        else {
            let mod10 = pr % 10 == 0;
            let mod25 = pr % 25 == 0;
            if mod10 {
                score -= 18.0;
            }
            if mod25 {
                score -= 14.0;
            }
            // Integer-division threshold: pr/20 classes
            let k = pr / 20; // 1..=5 for pr<=100
            score -= (k as f64) * 2.5;
        }
        // Fractional dead-space quadratic: unusable fraction of capacity
        let frac = pr as f64 / cap;
        score += 30.0 * frac * frac;
    }

    // Perfect fit: absolute harmony
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Lookahead coupling: does the next item fit the post residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward chain fits, more so when the chain leaves a harmonic residual
        score -= 20.0;
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
        score -= 10.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: this residual becomes dead space
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // --- Last-chance logic: unique fitting bin, avoid forcing a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, discouraged late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 70.0 * progress + 0.4 * open_bins_count as f64;
        // If nothing else fits this item well, allow new bin
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If next item is large, a fresh bin is attractive
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual tracks the mean ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Tie-break: prefer filling more of the bin (best-fit core)
    score += 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any post_residual that is too small to hold the smallest plausible item
    // (sizes can be as small as 1, but tiny gaps are statistically near-useless)
    // is "dead space": penalize it harshly, scaling with how close to unusable it is.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    }
    // Small-but-nonzero gaps (11..=20) are mildly wasteful too.
    else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly into the post-residual, this placement sets up
    // a perfect follow-up: heavy reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // If the next item fits into the post residual at all, mild reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If the next item would NOT fit into post_residual, this bin is likely to be
    // closed out with dead space: penalize proportionally to the leftover.
    else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0 + 0.5 * post_residual as f64;
    }

    // --- Last-chance pressure ---
    // If this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin (avoids wasting residual capacity elsewhere).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // --- Open-bin pressure ---
    // With many open bins, prefer consolidating into existing bins to keep
    // residual mass concentrated; with few bins, spreading is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress) * 0.3;

    // --- Mean-residual coupling ---
    // If this bin's residual is far below the mean, it's already fragmented;
    // filling it out is good (its post_residual contributes less future value).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 0.2 * (mean_residual - bin_res_f);
    }

    // --- New-bin candidate handling ---
    // The empty-bin candidate has bin_residual == bin_capacity. Only prefer it
    // when the item would leave a large residual in an existing bin anyway,
    // or when no existing bin fits well. Give the new bin a moderate baseline
    // penalty so existing bins win ties, but a bonus when it enables a clean start.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= bin_capacity * 3 / 4 {
            score -= 40.0; // big item: fresh bin is natural
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 20.0; // next item is big too, fresh bin still useful
        }
    }

    // Slight preference for tighter bins overall (smaller residual before placement).
    score += 0.1 * bin_res_f / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not zero-dead-space obsession.
    score = score * 0.6;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead coupling with next_item_size ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            // The next item can also fit here: strong reward, best when it's an exact match.
            let match_quality = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 18.0 + 22.0 * match_quality * match_quality;
        } else {
            // Post residual cannot host the next item: penalize proportional to wasted potential.
            let waste_frac = (nxt - post) / bin_capacity as f64;
            score += 14.0 * waste_frac;
            // Very small unusable remnants are dead space: extra penalty.
            if post < 10 {
                score += 8.0 * (1.0 - post / 10.0);
            }
        }
        // If the current bin residual exactly matches the next item and we place tightly,
        // that's a chained perfect fit.
        if bin_residual == item_size + next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score -= 10.0;
    }

    // ---- Relative-to-mean-residual term ----
    // Prefer bins whose residual is below the mean (i.e., filling fuller bins first),
    // which consolidates space into fewer bins.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        score += 10.0 * rel;
    }

    // ---- Last-chance bonus: only one bin fits the item ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // must use this bin or open a new one
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is generally bad unless it's early in the stream
        // (building a diverse portfolio of bins) or the item is large.
        let mut new_bin_penalty = 35.0;
        // Early stream: allow more bins to be opened for future flexibility.
        new_bin_penalty -= 25.0 * (1.0 - progress);
        // Large items relative to capacity: a fresh bin is more acceptable.
        new_bin_penalty -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins are already open, discourage opening yet another.
        new_bin_penalty += 1.5 * open_bins_count as f64;
        // If the next item is large, a fresh bin may serve it well.
        if next_item_size > 0 && next_item_size >= 50 {
            new_bin_penalty -= 12.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Slight reward for using existing bins generally.
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    // Reward tight fits (small post_residual) more aggressively over time
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tight * tight * (0.5 + progress);
    // Lookahead: if the next item fits into the leftover space, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use
        score += 0.15 * post_residual as f64;
    }
    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }
    // Penalize opening new bins when plenty of open bins still have room
    if is_new_bin {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 20.0 + 2.0 * crowding;
        // late in the stream, new bins are cheaper than spreading residual
        score -= 15.0 * progress;
    }
    // Mild preference for bins below mean residual (balance load)
    if !is_new_bin {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: residual decayed by progress pressure
    let pr_norm = pr / cap;
    let tightness = 1.0 - pr_norm; // how full the bin becomes
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 8.0;

    // Reward near-perfect fits smoothly (post_residual small)
    score -= (1.0 - pr_norm).powi(4) * 6.0;

    // Penalize dead space relative to mean residual, scaled by progress
    score += (pr - mean_residual).max(0.0) * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item can use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 4.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: small unusable residuals (below min item size 1,
    // but practically below common item sizes) are wasteful.
    if post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 45.0;
    }

    // Modulo classes on post_residual relative to capacity: residuals that are
    // "harmonically compatible" with typical future items are less penalized.
    let pr = post_residual;
    let class_bonus: f64 = match pr % 10 {
        0 => -18.0,  // round residual: composable with decade-sized items
        5 => -8.0,   // half-decade: still composable
        2 | 8 => -3.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Integer-division thresholds: how many "average chunks" remain.
    let chunks = pr / 25;
    score -= chunks as f64 * 6.0; // more usable capacity => better bin

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score += 25.0; // would create new dead space after chain
            } else {
                score -= 30.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
            }
        } else {
            // next item cannot use this residual: residual must hold value for later
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: opening a new bin wastes (capacity - item_size) now;
    // penalize unless current fit is very poor or many bins already open.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.5 + 40.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
        if post_residual >= 50 {
            score -= 20.0; // roomy new bin fine early
        }
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Mild preference toward bins below mean residual (keep tight bins tight,
    // spread load): equalize residuals.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Reward filling bins that are already mostly full (low residual).
    score += 0.25 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Harsh penalty for unusable dead space: gaps too small for typical items
    if post > 0.0 && post < 10.0 {
        score += 50.0 - 5.0 * post; // tiny gaps are worst
    } else if post == 0.0 {
        score -= 30.0; // perfect fit strongly rewarded
    }

    // Reward good utilization relative to capacity
    score -= 20.0 * (1.0 - post / cap);

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the resulting residual, bonus
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0;
    } else if next_item_size > 0 && post > 0.0 {
        // next item won't fit: residual is likely dead space
        score += 4.0 * (post / cap);
    }

    // Progress pressure: late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post / cap);

    // Prefer bins below mean residual (keeps residuals balanced)
    score += 0.1 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how snugly it fits
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item will NOT fit in this bin's leftover: penalize
            let overshoot = next_item_size - post_residual;
            score += 30.0 + 0.5 * overshoot as f64;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates usefully
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening a new bin when good fits exist elsewhere
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 500.0;
        }
    }

    // Late-stream consolidation: prefer tight packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize residual scale
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    let fit_frac = item_size as f64 / cap;

    // Strongly reward tight fits: post_residual near zero is best.
    // Non-linear coupling: squared post residual punishes large dead space.
    score += 2.0 * post_frac * post_frac * cap;

    // "Perfect fit" bonus: residual becomes a size that a typical small item could use,
    // or exactly zero.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward this bin
    // (chain packing); if not, penalize proportionally to wasted potential.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 6.0;
        } else {
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.08 * gap;
        }
    }

    // Last-chance dynamics: if this is the only bin that can fit the item, heavily favor
    // using it rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * fit_frac;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing bins
    // fit poorly (large post residual relative to item) or many bins are already open
    // with fragmented space.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: slightly worse than a decent fit.
        score = 0.55 * cap + 0.25 * (post_residual as f64);
        // Early in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 12.0 * (1.0 - progress);
        // If open bins are fragmented (high mean residual spread vs item), new bin gains appeal.
        if mean_residual > 1.5 * item_size as f64 {
            score -= 6.0;
        }
        // If no other bin fits well, new bin is competitive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Global pressure: many open bins with small mean residual -> encourage filling
    // existing bins harder (penalize leaving moderate residual).
    if open_bins_count > 3 {
        let pressure = (open_bins_count as f64).ln();
        score += pressure * post_frac * 3.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the item (good fit),
    // penalize bins far larger than needed.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * residual_gap;

    // Small time-horizon modulation: late in the stream, tighten packing (punish slack).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_frac * 4.0;

    // Mild diversification term using mean residual to avoid pathological herding.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling: squared normalized post-residual scaled by progress
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize residuals that cannot fit the lookahead item (dead space for next item)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (1.0 - pr / nx.max(1.0)) * (0.4 + 0.6 * progress);
        } else {
            // smooth reward when next item could still fit
            score -= 3.0 * (1.0 - pr / cap) * (nx / cap);
        }
    }

    // Last-chance bin before opening a new bin: strong smooth bonus
    if fitting_bins_count == 1 {
        score -= 10.0 + 4.0 * progress;
    } else {
        // mild penalty when many bins compete (prefer consolidating)
        score += 0.35 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Coupling with mean residual: prefer bins near the mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / (1.0 + progress);

    // New-bin candidate: penalize so it only wins when open bins fit badly
    if bin_residual == bin_capacity {
        score += 7.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: exact division classes of capacity
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fit: strongly reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead-space harmonic classes: leftovers that nothing (min size 1..100) can use well
    // Class A: pr in [1,9] -> tiny unusable crumbs, mildly bad
    if pr >= 1 && pr <= 9 {
        score += 8.0;
    }
    // Class B: pr divisible by 10 -> usable by common item sizes, reward
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    // Class C: pr divisible by 25 or 50 -> very reusable
    if pr % 25 == 0 && pr > 0 {
        score -= 20.0;
    }

    // Exact match: leftover equals next item size -> reserve for lookahead
    if next_item_size > 0 && pr == next_item_size {
        score -= 60.0;
    }
    // Leftover can fit next item (good chaining), scaled by how snug
    if next_item_size > 0 && pr >= next_item_size {
        let snug = 1.0 - ((pr - next_item_size) as f64) / cap;
        score -= 15.0 + 25.0 * snug;
    } else if next_item_size > 0 && pr < next_item_size {
        // leftover too small for lookahead: penalize proportional to wasted fraction
        score += 10.0 * (1.0 - prf / cap);
    }

    // Fractional fill of the bin: reward high fill ratio
    let fill = (bin_capacity - pr) as f64 / cap;
    score -= 40.0 * fill * fill;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only open new bin when current fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = cap as f64 * 0.55;
        // open new bin if existing fits leave large dead space
        if pr > 0 && pr < 15 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // many open bins with high mean residual: prefer reusing them
        score += (open_bins_count as f64).ln().max(0.0) * 4.0 + mean_residual * 0.05;
    }

    // Mild penalty for spreading when few bins can fit (fragmentation risk)
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // by future items (sizes 1..=100, but small gaps < ~15 are near-worthless)
    // are heavily penalized, quadratically.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 12.0 + 40.0;
    }

    // Reward tight fits: post_residual close to 0 (but not creating dead space)
    if post_residual <= 10 && post_residual >= 1 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it, else we open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mildly encourage filling existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= pressure * 3.0;
    } else {
        // New-bin candidate: base penalty that grows with open bins count,
        // relaxed when the item is large (big items fit anywhere equally).
        score += 25.0 + pressure * 6.0;
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual at all -> dead space likely.
        score += 15.0;
    }

    // Progress: later in the stream, be more conservative about new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., more filled bins) to concentrate waste.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If next item could still fit after this placement, mild reward.
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Dead space: post-residual too small for next item.
            score += 8.0;
        }
    }

    // Tight fits preferred: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Prefer bins with residual below the mean residual (compact bins).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when reasonable open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if next item is large and this item creates near-perfect chain, soften.
        if next_item_size > 0 && next_item_size <= bin_capacity && (bin_capacity - item_size) as i64 - next_item_size as i64 >= 0 {
            score -= 5.0;
        }
    }

    // Early in stream: be slightly more willing to open bins to build diversity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best, but dead space
    // that can never fit a future item is extra costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let waste = (post_residual as f64 / bin_capacity as f64).powf(2.0 + 2.0 * progress);
    score += 30.0 * waste;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot follow here; penalize proportionally.
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins are
    // fragmented (mean residual low relative to item) or late in stream.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let threshold = 0.55 - 0.25 * progress;
        if fragmentation < threshold && open_bins_count > 0 {
            score += 80.0 * (threshold - fragmentation) * 2.0;
        } else {
            score -= 15.0 + 20.0 * progress;
        }
    }

    // Prefer filling bins that are already mostly full (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Mild penalty for spreading across too many open bins early on.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post_residual (tight fit), with non-linear shaping
    let mut score = pr;

    // Non-linear coupling: quadratic dead-space penalty grows with stream progress
    let dead = (pr / cap).powi(2);
    score += dead * 30.0 * (0.4 + 0.6 * progress);

    // Quartic term: heavily penalize residuals that are too small to ever be useful
    // (smooth via sigmoid-like coupling rather than piecewise constants)
    let usable = pr / cap;
    let uselessness = 1.0 / (1.0 + (usable * 8.0 - 2.0).exp()); // ~1 when pr tiny
    score += uselessness * 25.0;

    // Reward if the next item fits into post_residual (smooth lookahead bonus)
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        let fit_next = 1.0 / (1.0 + gap / (cap * 0.15));
        let exact_next = (pr - nxt).max(0.0);
        score -= fit_next * 12.0;
        score -= (1.0 / (1.0 + exact_next / cap)) * 8.0 * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: empty bin has pr = cap - item.
    // Prefer keeping residual flexibility early, but accept new bins late
    // when existing bins would leave very small residuals.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5 && (bin_residual == bin_capacity);
    if is_new_bin {
        // Mild penalty early (avoid bin proliferation), shrinking with progress
        score += 10.0 * (1.0 - progress).powi(2);
        // Bonus if a new bin yields a residual that fits the next item
        if nxt > 0.0 && pr >= nxt {
            score -= 6.0;
        }
    }

    // Slight pressure to balance residuals across open bins
    score += ((pr - mean_residual) / cap).abs() * 3.0;

    // Smooth open-bin count damping: many open bins -> prefer consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    // Small noise-free tie-breaker on item size coupling
    score += (item / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue
    // classes modulo 10 (typical item granularity) to detect "dead" space.
    let post_class = post_residual % 10;
    // Leftovers in classes 1..=9 (non-decade) are harder to fill; penalize
    // proportionally to how far from a decade boundary they sit.
    if post_residual > 0 && post_residual < bin_capacity {
        let deadness = if post_class == 0 { 0.0 } else {
            // distance to nearest decade, normalized
            let d = post_class.min(10 - post_class) as f64;
            d / 10.0
        };
        score += deadness * 18.0;
    }

    // Integer-division threshold: post_residual bucketed by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.05 {
        score -= 25.0; // near-perfect fit, excellent closure
    } else if frac <= 0.10 {
        score -= 15.0;
    } else if frac <= 0.25 {
        score -= 5.0;
    } else if frac > 0.5 {
        score += 12.0; // half-empty bin after placement: wasteful
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic check: does the pair leave a decade-aligned remainder?
        let pair_left = post_residual - next_item_size;
        if pair_left % 10 == 0 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: mild penalty, stronger if
        // the leftover is large (bad chaining potential)
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has large residual.
    if bin_residual == bin_capacity {
        // Prefer reusing an existing bin unless the fit there is terrible.
        // Base cost of opening a new bin:
        score += 30.0;
        // If the item is large (harmonic class: big items pair well together),
        // opening a fresh bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // If the next item is also large, a fresh bin can host both.
        if next_item_size > bin_capacity / 2 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
        // If no open bin fits well (this call implies competition), the
        // comparison itself decides; keep the penalty moderate.
        // Slight bonus late in the stream to consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild preference for filling bins that are already relatively full
    // (best-fit reinforcement via mean residual deviation).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < 10 {
            // Gap smaller than any plausible item -> dead space.
            score += 60.0;
        } else {
            // Fraction of future items that could still fit the gap (unknown
            // distribution, so gauge by gap size relative to capacity).
            let usability = (post_residual as f64 / bin_capacity as f64).powi(3);
            score += (1.0 - usability) * 40.0;
        }
        let _ = min_item;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward leaving a gap that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mean residual coupling: placing into a bin below mean residual tightens
    // the residual distribution (good), placing above mean is penalized.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Early in the stream, tolerate opening new bins slightly more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 8.0;

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large or existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 35.0 * large_item;
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
    score -= 60.0 * (1.0 - diff / bin_capacity as f64).powi(4);

    // Strong reward if next item fits perfectly in the post-residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Reward when next item fits at all (chainable bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Penalize large dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Penalize tiny unusable leftovers (dead space below min plausible item).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: score as wasted capacity if item fits in an open bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Opening a new bin is only attractive if existing bins fit poorly
            // (large post_residual elsewhere). Base penalty keeps it behind decent fits.
            score = bin_capacity as f64 - 25.0;
        } else {
            score = bin_capacity as f64;
        }
        // Encourage new bin when next item is large and would waste current bins.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Slight preference for filling bins more tightly as stream progresses.
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins that are already partially filled (compactness).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // Penalize dead space that no future item (sizes 1..=100) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead coupling: penalize if the next item no longer fits this bin
    // after placement, but reward if next item fits exactly in the leftover.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 30.0 - gap as f64 * 0.5;
        } else {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * progress;
    }

    // Prefer bins whose residual is below mean (tighter bins get used first),
    // keeping looser bins flexible for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Mild penalty for accumulating too many open bins.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for filling bins with small residual relative to capacity.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 - progress);
        // Reward leaving exactly enough room for the next item
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 15.0 * fit_next * norm_next * (1.0 - progress);
    }

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many bins relative to mean residual
    let mean_norm = mean_residual / cap;
    score += 5.0 * (norm_pr - mean_norm).abs() * (open_bins_count as f64).sqrt() / (1.0 + progress);

    // New-bin candidate: penalize slightly less when item is large or stream is early
    if bin_residual == bin_capacity {
        score += 8.0 - 12.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // residue class (divisible by small capacities) are rewarded.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -80.0 // perfect fit
    } else if pr % 10 == 0 {
        -20.0
    } else if pr % 5 == 0 {
        -10.0
    } else if pr <= 10 {
        25.0 // tiny dead space
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds: leftover big enough for the next item is good.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 12.0; // next item won't fit here
        }
        // Exact pairing: post_residual + next_item == residual means a perfect 2-pack
        if pr == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 40.0
            + 0.5 * (open_bins_count as f64)
            - 0.4 * mean_residual
            + if pr % 10 == 0 { -5.0 } else { 0.0 };
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild pressure to prefer fuller bins overall.
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // Harmonic modulation: small periodic term on residual capacity fraction.
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += 3.0 * (frac * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        }
        // Penalize creating a gap just below the next item size (near-miss).
        if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 15.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless
    // the fit is good; mild penalty scaled by count.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the dead space is egregious.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual < 10 && post_residual > 0 {
            score += 45.0; // but still avoid trapping dead space
        }
    }

    // New-bin candidate: neutral-ish score so it's chosen only when all
    // open bins have poor fits. Slightly prefer reusing when residual
    // utilization is high.
    if bin_residual == bin_capacity {
        score = 40.0 + 0.5 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual - next_item_size) as f64;
        // Strong reward for tight 2-step fit (post_residual leaves just enough for next item).
        score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
        // Perfect chaining bonus: next item exactly fills remaining space.
        if match_gap == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: dead space penalty scaled by waste.
        let dead = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
        score += 0.5 * dead;
    }

    // Reward bins tighter than the average residual (good packing targets).
    score -= 0.4 * (mean_residual - bin_residual as f64).max(0.0);

    // Penalize bins looser than average slightly (avoid scattering across loose bins).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in the stream, avoid opening new bins; favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 40.0 * progress;
        // But if no open bin fits well (post_residual large dead space), new bin is fine.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 12.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Small bonus for very tight fills overall.
    if post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: square the post residual.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Progress horizon: early in the stream, keep bins flexible (penalize very low residuals);
    // late in the stream, squeeze hard (reward low residuals further).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 {
        let dead_weight = 1.0 - progress;
        score += dead_weight * (post_residual as f64).ln().max(0.0) * 4.0;
    } else {
        score -= 30.0 + 20.0 * progress; // perfect fill, more valuable late
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily;
    // if next item cannot fit, mild penalty proportional to wasted lookahead opportunity.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 - gap * 0.3; // exact lookahead chain fit is best
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
    }

    // New-bin candidate handling: opening a new bin is costly, but attractive when
    // all existing fits are poor (high post residual) or many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64).min(1.0)
        } else {
            0.0
        };
        let base_cost = 40.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        score = base_cost * (1.0 - 0.6 * poor_fit_pressure) + 0.5 * item_size as f64;
        // Late in the stream, closing out with a fresh bin is cheaper.
        score -= 20.0 * progress;
    }

    // Global fragmentation signal: if mean residual is high, prefer bins that
    // reduce dispersion (post residual near mean residual is "normal", far above is bad).
    if bin_residual != bin_capacity {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.15 * (1.0 - progress);
    }

    // Small coupling: reward placing large items into large-residual bins.
    score -= (item_size as f64) * (bin_residual as f64) / (bin_capacity as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, residual space is more valuable -> penalize waste harder.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress * progress;
    score += 30.0 * coupling;

    // Reward tight fits (small post_residual) with a saturating bonus.
    let tightness = (-norm_pr * 6.0).exp();
    score -= 25.0 * tightness * (1.0 + 0.5 * progress);

    // Lookahead: if the next item exactly fills the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64 / cap;
            score += 10.0 * leftover * leftover;
        } else {
            // next item can't use this residual anyway; slight penalty for stranded space
            score += 5.0 * norm_pr;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Discourage spreading across many bins when mean residual is already low.
    let mean_norm = mean_residual / cap;
    score += 8.0 * mean_norm * (open_bins_count as f64).ln();

    // New-bin candidate (empty bin): penalize unless it's genuinely attractive,
    // e.g., early stream or item is large relative to capacity.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 60.0
            - 20.0 * (item_size as f64 / cap)
            - 25.0 * (1.0 - progress);
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // New-bin candidate handling: strongly penalize opening a new bin when
    // any open bin can fit; only attractive when nothing fits (forced) or
    // the stream is early and we want to preserve large residuals.
    if bin_residual == bin_capacity {
        let mut nb = cap + 25.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            nb = -1000.0; // forced: no open bin fits
        } else if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            nb -= 10.0; // open bins are getting tight; a fresh one has value
        }
        return nb;
    }

    // Base: minimize wasted space, mildly superlinear.
    let mut score = pr + 0.04 * pr.powf(1.35);

    // Harmonic classes: reward post_residuals that are "clean" multiples of
    // the capacity decile (likely to be exactly filled by future items),
    // penalize awkward off-class remainders.
    let class = post_residual % 10;
    score += class as f64 * 0.35;
    if post_residual % 25 == 0 {
        score -= 2.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Lookahead coupling (k=2): reward leaving room for the next item,
    // penalize leaving a residual the next item cannot use.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 6.0 + 4.0 * (pr - ni) / cap;
        } else {
            score += 2.0 + 3.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, use it
    // rather than fragmenting elsewhere or opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Late-stream tightening: as the stream progresses, prefer tighter fits
    // and avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Deviation from mean residual: bins far below the mean residual are
    // already fragmented; slightly discourage dumping into them.
    score += 0.15 * (mean_residual - pr).abs().sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items >= 1, but practically small gaps under ~15 are near-useless).
    if post_residual > 0 && post_residual < 15 {
        score += 40.0; // unusable dead space penalty
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else if post_residual < 25 {
        score += 12.0; // marginal gap
    }

    // Reward tight fits relative to residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: only attractive when open bins would leave
    // large dead space anyway
    if bin_residual == bin_capacity {
        score += 20.0; // default penalty for opening a new bin
        if fitting_bins_count == 0 || post_residual as f64 > mean_residual {
            score -= 45.0; // opening is reasonable when fits are poor
        }
    }

    // Progression: become more conservative late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: baseline slightly above average so it's only chosen
    // when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 * 0.85 + (post_residual as f64) * 0.10;
    }

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly filled by next item
        } else if next_item_size <= post_residual {
            // next item still fits; prefer small leftover after that chain
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use the leftover: penalize dead space proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.25;
        }
    }

    // Tight fits are good: small post_residual relative to item size.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Prefer bins whose residual is close to the item (best-fit core).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // Relative to mean residual: bins with residual near mean are neutral,
    // much larger residuals are "wasteful" hosts for small items.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 4.0;
    } else if bin_residual as f64 > mean_residual + 20.0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferating open bins when a tight fit exists.
    if open_bins_count > 3 && post_residual <= 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits strongly.
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    score += 0.3 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Lookahead: reward if next item fits into post_residual (chaining), penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer filling existing ones.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Mean residual alignment: prefer bins whose residual is near the mean (keeps flexibility).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // Time horizon: early on, be more willing to open new bins (penalize less);
    // late in the stream, strongly prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that grows with progress and shrinks with item size.
        score += 15.0 + 25.0 * progress - 0.1 * item_size as f64;
        if fitting_bins_count == 0 { score -= 100.0; }
        // If item is large relative to mean residual, opening a new bin is fine.
        if item_size as f64 > mean_residual { score -= 10.0; }
    } else {
        // Existing bin bonus grows late in the stream.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual, but discount large residuals late (dead space matters less when stream ends).
    let mut score = post * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling of fill ratio with progress.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Reward tight fits: small post_residual relative to mean residual.
    score -= 6.0 * (mean_residual - post).abs() / cap;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt).abs() / cap);
        } else {
            // next item won't fit here: mild penalty proportional to wasted match
            score += 3.0 * (nxt / cap) * (1.0 - fill);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so if good fits exist or early in stream.
    if bin_residual == bin_capacity {
        let penalty = 20.0 + 15.0 * (1.0 - progress) + 4.0 * open_bins_count as f64;
        score += penalty;
        // But if item is large relative to capacity and fits nowhere tightly, soften.
        score -= 10.0 * (item / cap) * (1.0 - progress);
    }

    // Smooth non-linear interaction: quadratic in post_residual normalized.
    let post_norm = post / cap;
    score += 15.0 * post_norm * post_norm * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    } else {
        // Penalize residuals in "dead zones" that few item sizes (1..100) can reuse.
        let dead = match post_residual {
            1..=10 => 0.0,
            11..=33 => 0.4,
            34..=50 => 0.8,
            51..=66 => 0.5,
            _ => 0.2,
        };
        score += dead * (post_residual as f64);
    }

    // Modulo-class coupling: residual reusable by next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward, especially if near-exact.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 40.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot follow here: mild penalty scaled by tightness.
            score += 10.0 + 20.0 * (next_item_size as f64 / cap);
        }
        // Harmonic divisibility: residual divisible into chunks of next size.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer filling bins with low residual relative to the fleet mean.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early stream: encourage compacting into few bins; late stream: allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (open_bins_count as f64).sqrt();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 + 50.0 * (1.0 - item_size as f64 / cap) };
        score += pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size is 1, but tiny gaps < 8 are statistically hard to fill)
    // are heavily penalized dead space.
    if post_residual > 0 && post_residual < 8 {
        score += 60.0 * (1.0 - post_residual as f64 / 8.0);
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to capacity.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: this residual becomes dead space.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight fit exists; discourage opening new bins when
    // existing bins are still fairly empty on average.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are crowded.
        let crowding = mean_residual / bin_capacity as f64;
        score += 20.0 + 50.0 * (1.0 - crowding);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Slight preference for filling emptier bins first.
        score += (bin_residual as f64 - mean_residual).clamp(-20.0, 20.0) * 0.3;
    }

    // Late in the stream, prioritize closing bins out (favor smallest residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post-residual smaller than next item: the leftover is dead space for the lookahead,
    // penalize proportionally to how close it is to a perfect match (near-miss frustration).
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Post-residual larger than next item: still fine, small bonus for leaving usable room.
    else if next_item_size > 0 {
        score -= 0.1 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize creating tiny unusable residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred.
        score += 30.0;
        // But if the item fits perfectly in a fresh bin, opening is great.
        if item_size == bin_capacity {
            score -= 2000.0;
        }
        // If few bins fit and residual after placing is small, opening looks better.
        if next_item_size > 0 && (bin_capacity - item_size) <= next_item_size {
            score -= 60.0;
        }
        // Late in the stream, avoid proliferating bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins: discourage opening yet another.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual quadratically.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 30.0;

    // Reward filling bins deeply: fraction of capacity consumed by this item.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when item is large (nearly fills fresh bin)
    // or when existing bins are all very full (mean residual tiny).
    if bin_residual == bin_capacity {
        let waste_if_new = bin_capacity as f64 - item_size as f64;
        score += waste_if_new * 1.2;                 // base penalty for opening a new bin
        if next_item_size > 0 && post_residual > 0 {
            // Penalize if leftover space of new bin can't host the next item anyway
            if post_residual < next_item_size {
                score += 25.0;
            } else {
                score -= 10.0; // leftover is reusable, soften penalty
            }
        }
        // If all open bins are nearly full, opening a new bin is fine
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: penalize leaving residual that can't fit the lookahead item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 8.0; // keeps future options open
            } else if post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.6;
            }
        }
        // Penalize bins whose residual deviates badly from mean (fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Time-horizon modulation: early in stream, be more conservative with tight fits
    // (keep flexibility); late in stream, commit to tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.3;

    // Mild bonus for spreading load when many bins are open (avoid extreme imbalance)
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = pr / cap;

    // Base: reward tight fit (low post_residual), with non-linear penalty on wasted space
    let mut score = pr as f64;
    score += 18.0 * post_norm * post_norm * cap; // superlinear dead-space penalty

    // Smooth stream-progress coupling: later in stream, prefer filling existing bins tighter
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score *= progress_coupling;

    // Reward using bins with large residual when item is large (avoid fragmenting)
    let residual_term = (bin_residual as f64 / cap) * (1.0 - fit_ratio);
    score -= 12.0 * residual_term * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (-gap / 12.0).exp();
        score -= 20.0 * kernel;
    }

    // Mild penalty when bin residual deviates from mean residual (prefer homogenizing residuals)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // Prefer not opening new bins when many are open and item fits well
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 8.0 * openness * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into buckets.
    let pr = post_residual as u32;
    let class = match pr {
        0 => 0.0,
        1..=5 => 1.0,
        6..=10 => 2.0,
        11..=20 => 3.0,
        21..=30 => 4.0,
        31..=50 => 5.0,
        _ => 6.0,
    };
    score += class * 8.0;

    // Perfect fits are gold.
    if pr == 0 {
        score -= 200.0;
    }
    // Residuals that a "small" future item could still use are decent.
    if pr >= 1 && pr <= 30 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: penalize leaving mid-sized dead space
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Modulo arithmetic on capacity fractions: penalize residuals that are
    // awkward fractions of capacity (unusable slivers).
    let pr_mod = pr % 10;
    if pr > 0 && pr_mod != 0 && pr_mod < 3 {
        score += 12.0; // sliver like 1-2 units is dead space
    }
    // Integer division thresholds: residual >= half capacity is a "live" bin.
    if pr >= bin_capacity / 2 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits
    // would be terrible (large item, huge leftover).
    if bin_residual == bin_capacity {
        // neutral base for a new bin, with mild pressure to reuse bins early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 30.0 * progress + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can host the next item perfectly if item is big
            if item_size + next_item_size <= bin_capacity {
                score -= 20.0;
            }
        }
    }

    // Fractional capacity alignment: reward placing items so residual stays
    // on nice multiples (harmonic classes of 5).
    if pr % 5 == 0 && pr > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10 typical)
    // can ever use are pure waste. Penalize tiny unusable gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item
    // would leave a large dead gap in every existing bin, or too many bins
    // are already open with high mean residual (fragmentation pressure).
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual < 10 { 80.0 } else { 0.0 };
        let pressure = open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        score = 40.0 + gap_penalty - pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; mildly penalize wasting the gap
        score += 5.0;
    }

    // Early stream: be slightly conservative, keep bins balanced
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is almost consumed.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect/near-perfect fit bonus (post_residual becomes dead space otherwise).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, the more exact the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.4;
        } else {
            // Next item won't fit here: penalize proportionally to the overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.35 * overshoot;
        }
    }

    // Compare against mean residual: bins below mean residual are "rich" targets.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual as f64 > 0.6 * (bin_capacity as f64) {
            score += 15.0; // wasteful placement, soften the last-chance bonus
        }
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only when
    // no open bin gives a decent fit (post_residual small enough).
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // fresh bin can chain the next item too
        }
    }

    // Early stream: be slightly more willing to open bins (build diversity of residuals).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual is good, but extremely small
    // post_residual (1..=3) is a perfect seal — reward it extra.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    } else if post_residual <= 10 {
        // awkward sliver: mildly penalize
        score += 4.0;
    }

    // Prefer bins whose residual tightly matches the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item can fit into the post-residual, this bin
    // stays useful — reward. If next item would be wasted on this bin's
    // remainder, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64));
        } else {
            score += 2.0;
        }
    }

    // Time horizon: late in the stream, avoid opening new bins (waste);
    // early, allow exploration of fresh bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, costly late.
        let mut new_bin_score = 35.0 + 40.0 * progress;
        // If many open bins with slack, opening new bins is wasteful.
        new_bin_score += (open_bins_count as f64).sqrt() * 3.0;
        // If mean residual is high, existing bins have room — penalize new bin.
        new_bin_score += mean_residual * 0.2;
        // Small items open bins cheaply (more future packing room).
        new_bin_score -= (100 - item_size.min(100)) as f64 * 0.15;
        return new_bin_score;
    }

    // Prefer bins below mean residual (tighter bins) when many bins are open.
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0) * -1.0;

    // Slight penalty for scattering across many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling: progress reshapes the effective cost of residual space.
    let shape = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= shape;

    // Penalize large residuals more strongly as the stream matures (dead space is less reusable).
    let norm_pr = pr / cap;
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a quadratic bonus.
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward residual that can host the next item, penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            let gap = (nxt - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: discourage spreading, prefer consolidation into fuller bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Mean residual context: placing into a bin below-average residual wastes spread.
    if mean_residual > 0.0 {
        score += 3.0 * (pr - mean_residual) / cap;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residues modulo 10 ---
    let class = post_residual % 10;
    // Dead space in "waste-prone" classes (small nonzero residues are hard to fill)
    if class > 0 && class < 5 {
        score += 12.0 * (1.0 - class as f64 / 5.0);
    } else if class >= 5 {
        score -= 3.0; // half-capacity-aligned residuals are reusable
    }
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    }

    // Integer-division thresholds: how many size-10 slots fit post_residual
    let slots = post_residual / 10;
    score -= 4.0 * slots as f64;

    // Exact harmonic alignment: post_residual divisible by common item classes
    if post_residual % 20 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 5.0; }
    if post_residual % 50 == 0 { score -= 6.0; }

    // Coupling with lookahead item: reward residuals that can host next item exactly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_class = next_item_size % 10;
            if post_residual % 10 == next_class {
                score -= 15.0; // exact class match for next item
            }
            if next_item_size % 10 == 0 && post_residual % 10 == 0 {
                score -= 7.0; // both decade-aligned
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing good fits,
    // but allow opening when all fits would be terrible (large post_residual waste)
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * mean_residual;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: tighten standards late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Congestion: many open bins -> prefer filling existing ones
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // a future item (min item size 1, but practically tiny gaps are waste)
    // are heavily penalized. A "dead zone" gap is one below the smallest
    // plausible item; treat gaps < 12 as near-waste, with escalating penalty.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 12 {
        score += 30.0 + (12.0 - pr) * 4.0;
    } else if post_residual >= 12 && post_residual < 25 {
        // Awkward mid gap: mildly penalized since fewer items fit cleanly.
        score += 8.0 * (1.0 - pr / 25.0);
    }

    // Reward perfect / near-perfect fits (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this gap: penalize leaving a gap sized
            // just below the next item (frustrating near-miss dead space).
            let miss = post_residual as f64 - next_item_size as f64;
            if miss > -20.0 && miss < 0.0 {
                score += 2.0 * (-miss);
            }
        }
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins adds fixed overhead.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // Candidate new bin: baseline equals capacity residual; add pressure
        // so it is chosen only when all existing fits are poor. Give it a
        // clean residual structure (no dead-space penalty applies naturally).
        score += pressure + 15.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Reward placing into bins whose residual is below the mean
        // (draining low-residual bins first keeps a few large gaps).
        let gap = mean_residual - bin_residual as f64;
        if gap > 0.0 {
            score -= 3.0 * gap.min(20.0);
        }
        score -= pressure * 0.5;
    }

    // Stream progression: late in the stream, avoid opening new bins at all
    // costs since leftover bins are pure waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // dead space that next item cannot use
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight fit relative to capacity
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Penalize large post_residual relative to mean residual (wasteful fit)
    if mean_residual > 0.0 {
        score += 0.3 * (post_residual as f64 - mean_residual).abs();
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer keeping many open bins consolidated when few remain
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // New-bin candidate penalty: discourage opening a new bin unless it is clearly better
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small dead space that is unlikely to fit future items (10..80 typical, but keep generic).
    if post_residual > 0 {
        let dead = post_residual as f64;
        // dead space below a plausible minimum item size is nearly unusable
        let min_item = 1.0f64.min(dead.max(1.0)); // generic lower bound
        let unusable = (min_item / dead.max(1.0)) * (1.0 - dead / bin_capacity as f64);
        score += 6.0 * unusable;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // next item still fits: mild bonus proportional to how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving residual just below next_item_size
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 5.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // When many bins fit the item, prefer the one with least residual (already captured),
    // but add a slight penalty for wasting very large residual bins on tiny items.
    if fitting_bins_count > 2 && (item_size as f64) < bin_residual as f64 * 0.35 {
        score += 4.0;
    }

    // Global state: penalize opening new bins when open bins have large mean residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_free = mean_residual.max(0.0);
        // New bin base cost grows with progress (later waste is worse) and with mean residual.
        score += 15.0 + 30.0 * progress + 0.35 * avg_free;
        // If a single fitting bin exists, new bin is almost always worse.
        if fitting_bins_count >= 1 {
            score += 12.0;
        }
        // Early stream with few bins: new bins are cheaper to open.
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    } else {
        // Slight preference for filling bins with larger residuals first (best-fit-like),
        // modulated by how many bins are open.
        score += (bin_residual as f64) * 0.02 * (open_bins_count as f64).sqrt();
    }

    // Time-horizon modulation: late in the stream, prioritize compacting residuals harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic in post_residual — strongly penalize large leftover space,
    // mildly reward near-zero leftovers (tight fit).
    let mut score = pr * pr / cap + 0.35 * pr;

    // Non-linear coupling with stream progress: later in the stream,
    // leftover space becomes costlier (less time to fill it).
    let late = progress * progress;
    score += 2.0 * late * pr;

    // Reward filling bins deeply relative to their current residual.
    let fill_ratio = it / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Coupling post_residual with mean residual: prefer bins whose post_residual
    // is below the mean (consolidating space into fewer bins).
    let rel = (pr - mean_residual) / cap;
    score += 4.0 * rel * rel.abs().sqrt();

    // Lookahead: if next item fits the post residual, reward this placement;
    // if post residual is too small for the next item, penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 1.5 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early/mid stream
    // and when many bins are already open but underutilized.
    if bin_residual == bin_capacity {
        let underuse = (mean_residual / cap).clamp(0.0, 1.0);
        score = 8.0 + 10.0 * (1.0 - progress) + 6.0 * underuse * open_bins_count as f64;
        // Allow opening a new bin when the item is large and nothing fits well.
        if it / cap > 0.7 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 5 bands (0-9,10-19,...,40-100)
    let class = post_residual / 10;
    // Dead-space penalty: residuals below 10 are nearly unusable for items >=10
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill is excellent
    }
    // Mid-range residuals (10..30) are the most valuable to preserve: penalize consuming them
    score += match class {
        0 => -20.0,
        1 => 6.0,
        2 => 4.0,
        3 => -2.0,
        _ => 0.0,
    };

    // Lookahead coupling: reward if next item fits in post_residual (chain packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.1 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to lookahead
        score += 0.05 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation)
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 3.0;

    // Early stream: be slightly greedy toward tight fits; late stream: conserve space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    // New-bin candidate: only attractive when no open bin is a decent fit
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            score += 15.0 + mean_residual * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // A residual is "dead" if no plausible future item (1..=100) fits well.
        // Penalize residuals below the smallest useful item threshold.
        if post_residual < 10 {
            score += 50.0 + (10.0 - pr) * 10.0; // tiny gap: near-wasted space
        } else if post_residual <= 20 {
            score += 20.0 + (20.0 - pr) * 2.0;  // small gap: only tiny items fit
        }
        // Smooth quadratic penalty on small residuals generally
        score += 0.05 * (100.0 - pr).min(60.0);
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to item size
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Open bins pressure: penalize placements that keep many bins open
    // unless the fit is very good (post_residual small).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (1.0 - tightness);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        score -= 15.0 * (1.0 - after as f64 / 100.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here after placement: mild penalty
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (concentrate packing into fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so it's only
    // chosen when all open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But if no open bin fits, this is the only option anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match bonus: post_residual slightly above next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-gap / 8.0).exp();
    }

    // Penalize leaving dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Reward tight fits (small post residual) generally.
    score -= 20.0 * (-(post_residual as f64) / 15.0).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin's fit is poor.
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - item_size as f64;
        score += 50.0;
        // Opening a new bin is attractive when it would preserve a large, reusable residual elsewhere is impossible —
        // i.e., when the current placement leaves a very small useless residual.
        if post_residual < 10 {
            score -= 70.0;
        }
        // Discourage new bins when many bins are already open and mean residual is high.
        score += 0.3 * open_bins_count as f64 + 0.2 * mean_residual;
        // Slightly favor new bin late in stream if residual waste would be large.
        score -= 0.1 * waste;
    }

    // Mild bonus for placing into bins whose residual is close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // unusable gap for the next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.9 * gap.sqrt();
        } else {
            // reward leaving room that the next item can still use
            score -= 4.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation into fewest bins.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, prefer spreading (keep flexibility);
    // late in the stream, prefer aggressive consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual across open bins is large,
    // prefer placements that reduce it (i.e., this bin's residual below mean).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 6.0 * dev;

    // New-bin candidate handling: empty bin gets a dynamic penalty that shrinks
    // when the current fit is poor or lookahead suggests a better pairing.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 12.0;
        // Open a new bin if placing here would strand the lookahead item badly.
        if next_item_size > 0 && post_residual < next_item_size {
            new_bin_penalty -= 14.0;
        }
        // Late in stream: closing out bins is fine, keep new bins costly.
        new_bin_penalty += 8.0 * progress;
        // Few open bins -> cheaper to open new ones early on.
        new_bin_penalty -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        score += new_bin_penalty;
    }

    // Small extra reward for exact/near-exact closure of a bin.
    if post_residual <= 5 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.5 * progress) - 0.6 * norm_pr * (1.0 - norm_pr) * (1.0 + 2.0 * progress);

    // Penalize very tight fits slightly less as stream progresses (use residual space now).
    let tightness = 1.0 - norm_pr;
    score -= 4.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (1.0 - next_item_size as f64 / pr.max(1.0));
        } else {
            score += 3.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last fitting bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: baseline cost, grows with progress pressure to consolidate.
    if bin_residual == bin_capacity {
        score += 15.0 - 8.0 * progress + 0.3 * open_bins_count as f64;
    }

    // Mild mean-residual alignment term.
    score += 0.2 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot band" does the leftover fall into?
    let quarter = bin_capacity / 4;               // 25
    let band = post_residual / quarter;           // 0..=4 integer division class
    let rem = post_residual % quarter;            // intra-band position

    // Reward very tight fits (small post_residual) but punish unusable slivers (<10).
    if post_residual == 0 {
        score -= 40.0;                            // perfect fit: best possible
    } else if post_residual < 10 {
        score += 25.0;                            // dead sliver, unusable for any item
    }

    // Band-based preference: leftover in the "half-capacity" band is most reusable.
    let band_bonus: [f64; 5] = [0.0, -12.0, -20.0, -6.0, 0.0];
    score += band_bonus[(band as usize).min(4)];

    // Modulo coupling: leftover that is congruent to a typical item size class is valuable.
    let next = next_item_size;
    if next > 0 {
        if post_residual >= next {
            // Next item fits exactly or near-exactly into the leftover -> strong reward.
            let gap = post_residual - next;
            if gap == 0 {
                score -= 30.0;
            } else if gap < 10 {
                score -= 18.0;
            } else {
                score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Leftover too small for the lookahead item: penalize proportionally.
            score += 6.0 + 0.15 * (next - post_residual) as f64;
        }
        // Harmonic pairing: post_residual % next small => good two-item chain potential.
        if next > 0 && post_residual % next.max(1) == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin offers
    // a decent fit (residual much larger than item) or when many bins are open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Large items (> half capacity) justify a new bin; small items should reuse.
        if tightness > 0.5 {
            score -= 10.0 + 20.0 * (tightness - 0.5);
        } else {
            score += 12.0 - 20.0 * tightness;
        }
        // Crowding pressure: many open bins -> opening another is worse.
        score += 2.0 * open_bins_count as f64;
        // Late in the stream, consolidation matters more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 8.0;
        }
    }

    // Deviation from mean residual: bins far below mean residual are nearly full;
    // prefer filling them off to close them out.
    let dev = mean_residual - post_residual as f64;
    score += 0.1 * dev;

    // Small tie-breaker noise from deterministic harmonic hash.
    let h = ((post_residual as usize).wrapping_mul(2654435761)
             ^ (item_size as usize).wrapping_mul(40503)
             ^ step_index.wrapping_mul(97)) % 7;
    score += h as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1,
    // but practically tiny gaps are useless) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item can't fit, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual < next_item_size {
            score += 12.0;
        } else {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones; new-bin candidate gets penalized.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (balanced packing), penalize outliers.
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // Late in the stream, tighten up: dead space matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits tightly (within small slack).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-slack / 8.0).exp();
    }

    // Penalize leaving residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.4 * dead;
    }

    // Compare post_residual against mean residual of open bins: keep balance.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize very tight fits that leave unusable slivers (unless perfect match).
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // Mild preference for filling bins more completely early vs late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit shaping: reward tight fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot host typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 4.0 * chain_tight;
        } else {
            // Wasted opportunity if we leave a gap just below the next item.
            let gap_waste = (post_residual as f64 - next_item_size as f64).abs();
            if post_residual < next_item_size {
                score += 3.0 * (post_residual as f64 / next_item_size as f64);
            } else {
                score += 0.0;
            }
            let _ = gap_waste;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the fit is poor or open-bin residuals are already fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = item_size as f64 / bin_capacity as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 30.0
            - 15.0 * poor_fit
            + 0.5 * open_bins_count as f64
            + 2.0 * fragmentation
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // allow escape hatch when no good open bin exists
        }
    }

    // Mild preference to consolidate into bins below mean residual (balance).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Late-stream pressure: fewer bins favored, tighten packing near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: prefer small post-residual, with a non-linear convex penalty
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, moderate residuals are tolerated; late, chase tight fits harder.
    let progress_coupling = pr * (0.6 * progress + 1.4 * progress * progress);
    score += progress_coupling;

    // Reward tight fits (post residual near zero) with smooth bell-shaped bonus
    let tightness = (-norm_pr * norm_pr * 18.0).exp();
    score -= 12.0 * tightness * (1.0 + progress);

    // Smooth reward when this is the last fitting bin (avoid opening a new bin)
    let last_chance = 1.0 / (fit * fit);
    score -= 8.0 * last_chance;

    // Penalize opening a new bin when decent fits exist among open bins
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let decent_fit_exists = ((fit > 1.5) as f64) * (1.0 - is_new_bin);
    score += is_new_bin * (14.0 + 10.0 * progress) * (0.4 + 0.6 * decent_fit_exists.max(0.0));

    // If the next item could use the post-residual, reward leaving a useful gap
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap_utility = ((pr - nxt).abs() / cap);
        score -= 6.0 * (-gap_utility * gap_utility * 10.0).exp() * (1.0 - progress * 0.5);
    } else {
        // Last item: strongly prefer minimal waste
        score += 0.5 * pr;
    }

    // Mild coupling with mean residual: prefer bins whose residual is close to this bin's
    let res_dispersion = (pr - mean_residual).abs() / cap;
    score += 3.0 * res_dispersion * res_dispersion;

    // Slight preference to fill already-open bins as count grows
    score -= 0.4 * open.ln().max(0.0) * (1.0 - is_new_bin);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by capacity fractions (integer division thresholds)
    let item_class = item_size / 25; // 0: tiny(1-24), 1: small(25-49), 2: medium(50-74), 3: large(75-100)
    let next_class = next_item_size / 25;
    let item_mod = item_size % 25;
    let next_mod = next_item_size % 25;

    // Post-residual harmonic class: how well does the leftover align with future capacity fractions
    let post_class = post_residual / 25;
    let post_mod = post_residual % 25;

    // Reward residuals that are exactly divisible into harmonic chunks (usable dead space)
    if post_mod == 0 && post_residual > 0 {
        score -= 12.0 * post_class as f64;
    }
    // Penalize awkward residuals: small unusable slivers (1..=9)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward more when the leftover after the next item is again harmonically clean
        let npr = post_residual - next_item_size;
        if npr % 25 == 0 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
        // Extra reward if next item is in the same harmonic class (chaining)
        if next_class == item_class {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize mildly, more if residual is a near-miss sliver
        let miss = next_item_size - post_residual;
        if miss <= 5 {
            score += 10.0 + miss as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
        // But not if it creates a tiny dead sliver
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Many fitting bins: mild penalty to prefer tighter consolidation elsewhere
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate handling (bin_residual == bin_capacity): make it attractive
    // only when no open bin fits well; otherwise keep open bins preferred.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.5; // 50.0 neutral baseline
        score = base
            + (item_mod as f64) * 0.1
            - if fitting_bins_count == 0 { 0.0 } else { 15.0 }
            // Favor opening a new bin when many open bins are already nearly full
            + (mean_residual / bin_capacity as f64) * 10.0
            // Late in the stream, prefer reusing open bins slightly more
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
        // Large items start fresh bins happily (clean harmonic packing)
        if item_class == 3 {
            score -= 6.0;
        }
    }

    // Global tightness bonus: filling a bin whose residual is far below mean = good consolidation
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    // Small tie-breaker on post_residual modulo classes for determinism
    score + (post_mod as f64) * 0.01
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-maybe-usable gaps get a milder penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward very tight fits (waste < 5) strongly.
    if post_residual < 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item nearly fits (within 10), small reward.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 10 {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a new bin, more strongly when other
    // bins can fit the item, and when few bins are open.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).min(10.0);
        score += 30.0 + 6.0 * open_pressure;
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(3.0);
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly prefer using it over opening a new bin.
        score -= 40.0;
    }

    // Mild pressure to prefer filling bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // Slight preference for bins below mean residual (keep residuals balanced).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: item fills bin, next item fills remainder.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial lookahead credit: next item still fits after this placement.
        score -= 12.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space the next item cannot use.
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).abs();
    }

    // Reward tight fits relative to capacity.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with residuals far above mean are wasteful targets.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if residual capacity is huge (item tiny) or
    // no open bin fits well; penalize spreading load across many bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 0.5 + open_bins_count as f64 * 3.0 - 20.0 * progress;
        if item_size >= 60 {
            score += 30.0; // large items should go into existing bins with room
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by fill ratio of the item into the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Lookahead: reward if the next item also fits into the post residual (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * next_item_size as f64;
    }
    // Penalize leaving a residual that is too small to be useful for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Penalize creating small dead space that likely becomes waste.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a good future fit
    // or current open bins are nearly full / item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let mut nb = 50.0;
        // Opening is attractive when open bins have little room (mean residual small)
        // and the item is big; discount as the stream progresses.
        nb -= 0.6 * open_avg;
        nb -= 0.3 * item_size as f64;
        nb -= 20.0 * progress;
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            nb -= 10.0;
        }
        score = score.max(0.0) + nb;
    }

    // Mild preference for bins with less residual among ties.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer tight fits (small post_residual), with polynomial shaping.
    let base = x * x * (3.0 - 2.0 * x) * 100.0 + pr;

    // Smooth progress coupling: later in the stream, tolerate residual decay more strongly.
    let progress_coupling = base * (1.0 + 0.5 * progress * (1.0 - progress) * 4.0);

    // Dead-space penalty: residual too small for typical future items is wasted.
    let dead = if pr > 0.0 && next_item_size > 0 && (next_item_size as f64) > pr {
        (next_item_size as f64 - pr) * 0.3
    } else {
        0.0
    };

    // Lookahead synergy: reward if next item fits the resulting residual (smooth coupling).
    let lookahead_reward = if next_item_size > 0 {
        let fits = ((next_item_size as f64) <= pr) as i32 as f64;
        -fits * (pr - next_item_size as f64) * 0.4
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Congestion: many open bins with high mean residual -> prefer filling existing bins.
    let congestion = -0.05 * mean_residual * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a new bin unless the item is huge and nothing fits well.
    let new_bin_penalty = if bin_residual == bin_capacity {
        20.0 + 30.0 * (1.0 - item_size as f64 / cap) + 10.0 * (1.0 - progress)
    } else {
        0.0
    };

    progress_coupling + dead + lookahead_reward + last_chance + congestion + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residuals into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0.0 .. 1.0

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space harmonic classes: residuals in (0,10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands of C).
    let band = post_residual / 25; // 0..4
    score -= band as f64 * 15.0;

    // Reward bins whose residual matches the NEXT item's harmonic class:
    // if next item fits exactly into post_residual, this is a great chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let nr = post_residual - next_item_size;
            if nr < 10 {
                score -= 150.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item cannot use this residual -> residual value decays
            score += 25.0;
        }
    }

    // Modulo arithmetic: residuals congruent to common item sizes mod 10
    // are more likely reusable by future items drawn from typical distributions.
    let m = post_residual % 10;
    if m == 0 {
        score -= 30.0;
    } else if m >= 5 {
        score -= 5.0;
    } else {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred...
        score += 350.0;
        // ...but if many open bins and mean residual is large and fragmented,
        // opening fresh space can pay off.
        if open_bins_count > 3 && mean_residual > 0.35 * cap && frac >= 1.0 {
            score -= 300.0;
        }
        // Late in the stream, prefer compacting into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    // Mild tie-break: prefer bins already below mean residual (tighter packing).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Residuals that can still host typical items are mildly rewarded.
        score -= 5.0;
    }

    // Reward bins whose residual tightly matches the item (small waste ratio).
    let waste_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * waste_ratio;

    // Open-bins pressure: with many bins open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // If many bins fit, mild tie-breaking toward lower residual usage.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: favor bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 + 8.0 * mean_residual / bin_capacity as f64;
        score = 105.0 + pressure - (progress * 10.0);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= (bin_capacity as f64 / post_residual as f64) * 5.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves slack — mild penalty proportional to slack
            let slack_after_next = post_residual - next_item_size;
            score -= 50.0 - slack_after_next as f64 * 0.5;
        } else {
            // next item won't fit here — penalize small post_residuals that waste space
            let wasted = post_residual as f64;
            score += wasted * 0.3;
        }
    }

    // Compare post_residual against mean residual of open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.4;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless lookahead suggests synergy
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0;
        }
        if open_bins_count == 0 {
            score -= 150.0;
        }
    }

    // Late in stream: prefer tighter packing (smaller residuals matter more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // good chaining, but small residual left for next is even better
            let chain_tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 + 12.0 * chain_tight;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement kills the ability to chain; mild penalty scaled by wasted gap
            score += 6.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_pressure = mean_residual / cap; // high = lots of slack around
        // base cost of a fresh bin
        score += 30.0;
        // if open bins have plenty of residual on average, opening new bin is wasteful
        score += 25.0 * avg_pressure;
        // early in the stream, prefer consolidation into existing bins
        score += 10.0 * (1.0 - progress);
        // if nothing fits anywhere else, this call is the fallback: relief via fitting count
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // big items justify a fresh bin more than tiny items
        score -= 8.0 * (item_size as f64 / cap);
    } else {
        // Prefer bins whose residual is closest to the item (best fit flavor),
        // and slightly prefer bins with below-average residual (keep slack bins for later).
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score += 5.0 * (1.0 - tightness);
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    // Dead-space penalty: residual too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 20.0 * pr_norm * pr_norm * (0.5 + t);
    score -= 12.0 * pr_norm * (1.0 - t) * (1.0 - t);
    score += 8.0 * pr_norm * pr_norm * pr_norm * (1.0 + t * t);

    // Reward tight fits more as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 15.0 * (0.3 + 0.7 * t);

    // Penalize opening new bins early / reward consolidation late
    score += 6.0 * (1.0 - t) * (open_bins_count as f64 / 10.0).min(1.0);

    // Last-chance bonus: avoid wasting the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * t);
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Mild mean-residual coupling
    score += 3.0 * (mean_residual / cap - pr_norm).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fractions
    let pr = post_residual as u32;
    let class = pr % 10; // fine harmonic class
    let coarse = (pr / 10) % 10; // decade class

    // Reward residuals that are "harmonically small" (near-perfect packing)
    // Perfect fit: post_residual == 0 -> big reward
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 12.0;
    }

    // Penalize dead space in awkward harmonic classes (7,8,9 mod 10 are hard to fill)
    if class >= 7 && class <= 9 {
        score += 8.0 + 2.0 * (class as f64 - 6.0);
    }
    // Reward classes that pair well with small items (1..=3 mod 10)
    if class >= 1 && class <= 3 {
        score -= 4.0;
    }

    // Coarse class: residual in (0,20] is nearly dead; residual in (30,60] is versatile
    if pr <= 20 && pr > 0 {
        score += 6.0;
    }
    if pr > 30 && pr <= 60 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let nxt = next_item_size as f64;
            // harmonic match quality: how close next item brings residual to a class boundary
            let post2 = pr - next_item_size;
            let frac2 = (post2 as f64) / cap;
            score -= 10.0 * (1.0 - frac2);
            if post2 % 10 == 0 {
                score -= 8.0; // lands on a decade boundary: reusable class
            }
            if post2 == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: penalize slightly more for big leftover classes
            score += 3.0 + (pr as f64) * 0.02;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only if current fit is bad
    if bin_residual == bin_capacity {
        // base penalty so new bins are opened only when justified
        score = 55.0 - 0.15 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin may be wise
        }
        if item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // mild reward for keeping bins consolidated
        score -= 0.05 * (open_bins_count as f64);
    }

    // Progress-adaptive tightness: later in stream, favor tighter fits more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Deviation from mean residual: prefer bins below mean (tighter bins fill first)
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0) - 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving residual that can fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading (penalize new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 0.15 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins close to the mean (balanced packing).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // usable for next item: mild bonus scaled by tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 50.0 * tightness;
        } else {
            // next item cannot fit here: penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(80.0) * 2.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strong preference to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins can fit, especially early/mid stream.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 * (1.0 - 0.5 * progress);
    }

    // Slight penalty for large post_residual (wasted space).
    score += post_residual as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever fit a future item (min size 1..100 unknown, use ~10 as conservative anchor).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual > 50 {
        // Large leftover is flexible; mild reward.
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here after placement; slight penalty unless bin is nearly full anyway.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation (prefer filling existing bins over new ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += consolidation * (bin_residual == bin_capacity) as i32 as f64 * 15.0;

    // New-bin candidate adjustment: attractive if mean residual across open bins is small (fragmented state).
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        score -= 12.0 * (1.0 - mean_frac);
        // But penalize opening new bins early in the stream.
        score += 10.0 * (1.0 - progress);
        // If current bin leaves a big awkward gap and next item is large, new bin is good.
        if next_item_size > post_residual && post_residual > 0 {
            score -= 6.0;
        }
    } else {
        // Existing bin: reward being below mean residual (filling emptier bins first balances).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]
    let mut score = pr;

    // Smooth non-linear waste term: penalize mid-range dead space most.
    let waste_curve = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += 18.0 * waste_curve * waste_curve;

    // Tight fits rewarded more as stream progresses (consolidation pressure).
    score -= (1.0 - x).powi(3) * (6.0 + 10.0 * progress);

    // Large residual (e.g. brand-new bin) mildly penalized; decays late in stream.
    score += x.powi(2) * (14.0 - 8.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead coupling: bonus if next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - (nxt / cap));
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Deviation from mean residual: prefer bins near the mean to preserve spread.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight penalty for proliferation of open bins early on.
    score += (open_bins_count as f64).ln().max(0.0) * (1.5 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
