    } else if frac <= 0.20 {
        score -= 150.0; // small dead space, still attractive
    } else if frac <= 0.35 {
        score -= 40.0;
    } else if frac <= 0.50 {
        score += 20.0; // half-empty bin: mediocre
    } else {
