    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10s) or leave 1..=5 slack are "harmonic" and good.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 30.0; // aligns with 10-grid item sizes
        }
        if pr % 25 == 0 {
            score -= 25.0;
        }
        if pr <= 5 {
            score -= 80.0; // near-perfect fill
        } else if pr < 10 {
            score -= 50.0; // dead space too small for any item (min size 1..10)
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.8;
        } else {
            // next item cannot use this residual: penalize leaving medium gaps
            if pr >= 10 && pr < next_item_size {
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are bad fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // more open bins with low mean residual -> opening new bin is worse
        score += open_bins_count as f64 * 5.0;
        score += (mean_residual / 10.0).min(60.0);
        // early stream: prefer consolidating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 40.0;
        // if next item is huge, a fresh bin may be valuable later
        if next_item_size >= 70 {
            score -= 30.0;
        }
    }

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }
    // Reward using last-chance bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open bins pressure: mildly favor filling existing bins
    score += 0.05 * open_bins_count as f64;

    // Lookahead: avoid leaving a gap that next item can't use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Prefer bins tighter than the mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let next_fits = next_item_size <= post_residual;
        if next_fits {
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            // Strong reward for perfect 2-item fill; taper with leftover slack.
            score -= 40.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Penalize residual that the next item cannot use (likely dead space).
            score += 0.25 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Prefer bins with low residual relative to mean (tighter packing).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discard near-empty usage unless it's a fresh bin candidate.
    if bin_residual == bin_capacity {
        // New bin baseline: slightly worse than a good existing fit.
        score += 5.0;
        // Late in the stream, opening new bins is less wasteful (fewer future regrets).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Penalize leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: bonus if next item fits exactly in post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty for wasting the space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, just fill bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.35;

    // Global residual pressure: if mean residual is high, prefer bins below mean
    // (consolidate), to reduce fragmentation.
    if bin_residual as f64 > mean_residual {
        score += 2.5;
    } else {
        score -= 1.5;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate: make empty bin moderately attractive only when the
    // item is large relative to capacity or no good fits exist; otherwise
    // existing bins win.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 10.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, non-linearly coupled with stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth polynomial penalty on normalized post residual (favor tight fits).
    score += 20.0 * pr_norm * pr_norm * (1.0 + progress);

    // Reward using bins that are the last chance to fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 8.0 * (1.0 - (diff / cap).min(1.0));
        } else {
            score += 6.0;
        }
    }

    // Coupling with mean residual: penalize bins far from the mean (fragmentation).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: keep it attractive early, penalize late in the stream.
    if bin_residual == bin_capacity {
        score = pr * (1.2 - 0.5 * progress) + 5.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual) with a non-linear squash.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Harmonic classes: partition post_residual into modulo bands of capacity/10.
    // Small dead-space classes (0..=9) are heavily penalized as unusable.
    let class = post_residual % 10;
    match class {
        0 => score -= 8.0,                       // perfect harmonic fill
        1..=4 => score += 6.0,                   // tiny dead space, worst reuse
        5..=9 => score += 1.5,                   // moderate dead space
        _ => {}
    }

    // Integer-division threshold: post_residual in [1,9] is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 + 8.0 * fit_quality;
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item cannot chain here; penalize proportionally to leftover waste.
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when all open bins are crowded
    // or the current item leaves a very poor residual in any existing bin.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let poor_fit_everywhere = fitting_bins_count == 0 || (post_residual as f64) < 5.0;
        if crowded < 2.0 && !poor_fit_everywhere {
            score += 40.0; // keep using existing bins early
        } else {
            score -= 5.0;  // fresh bin is reasonable when bins are full/tight
        }
    }

    // Mild stream-phase modulation: late in the stream, consolidate harder.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * phase * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps below the minimum item size (1) less, but any gap
    // smaller than a plausible item is wasted capacity.
    if post_residual > 0 && post_residual < item_size.min(bin_capacity / 2) {
        // gap too small for a similar item later: quadratic dead-space penalty
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 0.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + fit_ratio);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bins pressure: discourage spreading across many bins when few fit
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.4 * progress);

    // Prefer bins whose residual is already below average (consolidate waste)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // chosen only when placements elsewhere would create severe dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * progress;
        // If next item is large and this item is small, opening a fresh bin
        // preserves flexibility.
        if next_item_size > 0 && next_item_size > item_size && post_residual < next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the lookahead item
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Post residual can fit next item with a bit of room: good chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Post residual too small for next item: dead space penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Perfect closure of the bin.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Tiny unusable dead space is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare against mean residual: filling below-average-residual bins is efficient.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize so we only open when no reasonable fit exists.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 120.0; // forced new bin
        }
    }

    // Late in stream: prefer tighter packing / bin closure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64; // in (0,1]
    score -= fit_ratio * 12.0;

    // Penalize wasted residual quadratically, normalized by capacity.
    let waste = (post_residual as f64) / bin_capacity as f64;
    score += waste * waste * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.25 * next_item_size as f64;
    }
    // If next item does not fit but would fit the current residual better, slight penalty.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // in existing bins or many bins are already open with low mean residual.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0;
        let scarcity_bonus = if fitting_bins_count <= 1 { 14.0 } else { 0.0 };
        let spread = mean_residual - (bin_capacity as f64 - item_size as f64);
        let spread_bonus = if spread > 0.0 { spread.min(20.0) } else { -spread.abs().min(5.0) };
        let time_factor = (step_index as f64 / total_items.max(1) as f64) * 4.0;
        score += base_penalty - scarcity_bonus - spread_bonus + time_factor;
    } else {
        // Prefer bins whose residual deviates from the mean in a useful way
        // (use a bin with less residual than average to consolidate space).
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.02;

    // Early in the stream, be slightly more conservative about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual (tight packing), with non-linear emphasis
    let mut score = post + (post / cap).powi(3) * cap * 0.5;

    // Penalize dead space that no future item can plausibly fill (items >= 1)
    let dead = post - post.fract(); // keep smooth
    score += (dead / cap) * (dead / cap) * 30.0 * (1.0 - progress);

    // Reward near-exact fills (post_residual close to 0)
    score -= (-post / (item + 1.0)).exp() * 8.0;

    // Lookahead: penalize if next item cannot fit in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) / cap;
        } else {
            score -= 4.0 * (1.0 - (nxt / post)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins first)
    score += (post - mean_residual) * 0.3;

    // As stream progresses, be more conservative with open bins
    score *= 1.0 + 0.2 * progress * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral-ish baseline; discourage early, allow when open bins are tight
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 10.0 * (1.0 - progress) - mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "unusable" residue classes (small slivers that few items can fill).
    let pr = post_residual;
    if pr > 0 {
        // Small sliver classes (1..10) are nearly dead space: penalize strongly.
        if pr < 10 {
            score += 60.0;
        } else {
            // Usability of residual: quantize into capacity-fraction classes.
            let frac = pr as f64 / cap; // in (0,1)
            // Harmonic weighting: prefer residuals that are clean fractions
            // (1/2, 1/3, 1/4 of capacity) since future items modulo these
            // classes fit well.
            let half = (pr as i64 - (cap as i64) / 2).abs();
            let third = (pr as i64 - (cap as i64) / 3).abs();
            let quarter = (pr as i64 - (cap as i64) / 4).abs();
            let harmony = half.min(third).min(quarter) as f64;
            score += harmony * 0.8;
            // Modulo-10 class smoothness: residuals divisible by 10 are
            // friendlier to the 1..100 integer item space.
            if pr % 10 == 0 {
                score -= 8.0;
            }
            // Dead-space decay: residual below typical small item (<=20) is risky.
            if pr <= 20 {
                score += (20 - pr) as f64 * 2.0;
            }
            let _ = frac;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportionally to tightness of the chain.
            score -= 40.0 * (next_item_size as f64 / pr as f64);
            // Harmonic chain: next leaves again a class-friendly residual.
            let nn = pr - next_item_size;
            if nn % 10 == 0 && nn > 0 {
                score -= 10.0;
            }
        } else {
            // Next item will NOT fit here: this residual becomes terminal;
            // penalize more if residual is small (true dead space).
            if pr < next_item_size && pr < 30 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin wastes (bin_residual)
    // space in the current bin. Only attractive if current residual is
    // already a near-dead sliver and the item is large.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // But if the item is huge and nothing tight exists, opening fresh
        // keeps large residual usable: discount when item > 2/3 capacity.
        if item_size as f64 > 2.0 * cap / 3.0 {
            score -= 60.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 * progress;
        // Many open bins with slack mean we should reuse rather than open.
        if mean_residual > item_size as f64 {
            score += 50.0;
        }
    }

    // Mild preference for tighter existing bins (best-fit flavor) scaled by
    // how many alternatives exist.
    score += 0.15 * (fitting_bins_count as f64);

    // Prefer filling bins when many bins are open (bin consolidation).
    score += 0.5 * (open_bins_count as f64) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to ever fit the minimum item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small gaps are only marginally useful; add graded penalty.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // unless the fit is exceptional.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 25.0 + open_bins_count as f64 * 4.0;
        // But if the next item is large and this item is small, a fresh bin is attractive.
        if next_item_size > 60 && item_size <= 30 {
            score -= 30.0;
        }
    } else {
        // Mild reward for using existing bins, scaled by congestion.
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Prefer bins with residuals near the mean (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Late in the stream, be more conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins whose post-residual can exactly fit the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: item now + next item fills bin exactly
        } else if post_residual > next_item_size {
            // slack left after next item would also fit; prefer tight leftover
            let leftover = (post_residual - next_item_size) as f64;
            score -= 30.0 - leftover * 0.4;
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Penalize large unusable dead space relative to smallest possible item (1..100 now).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.05;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, be more conservative: consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open or item is huge.
        score += 25.0 - (open_bins_count as f64) * 1.5 + (item_size as f64) * 0.1;
        score += progress * 15.0; // discourage opening new bins late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: less leftover waste => lower score
    let mut score = post;

    // Reward tight fits: the closer the fill ratio to capacity, the better
    let fill_ratio = (bin_residual - post_residual as u32) as f64 / cap;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that can never fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post as f64 / 20.0);
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual as u32 {
        let exact = (post_residual as u32 - next_item_size) as f64;
        score -= 18.0 * (1.0 - exact / 40.0).max(0.0);
    } else if next_item_size > post_residual as u32 {
        // next item won't fit here; slight penalty for blocking useful space
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Many open bins => encourage consolidation (prefer existing bins)
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Time horizon: early in stream, be more willing to open new bins
    // (keeps flexibility); late in stream, consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        // New-bin candidate: base cost of opening a bin, discounted early
        score += 55.0 - 25.0 * (1.0 - progress);
        // Opening a new bin is attractive if no open bin leaves a good fit
        // (post_residual of new bin = cap - item, naturally large, so add
        // a term comparing against mean residual of open bins)
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Late stream: reward using existing bins even harder
        score -= 15.0 * progress;
        // Reward bins whose residual is close to mean (keeps bin profile uniform)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, penalize wasted space non-linearly.
    let mut score = pr * (1.0 + 0.9 * fill * fill);

    // Smooth progress coupling: later in stream, dead space matters more.
    let prog_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 14.0 * prog_coupling * pr / cap;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * fill;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Lookahead: penalize if post_residual can't fit next item when it otherwise could.
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = ni - pr;
        if gap > 0.0 {
            score += 0.25 * gap * (1.0 + prog_coupling);
        } else {
            score -= 0.15 * (-gap) * fill;
        }
    }

    // Mean residual context: prefer bins near mean residual (avoid fragmentation skew).
    score += 0.08 * (pr - mean_residual).abs();

    // New-bin candidate handling: make empty bin mildly attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        score = cap * (1.15 - 0.35 * prog_coupling) - 6.0 * (1.0 - fill);
        if fitting_bins_count <= 1 {
            score += 25.0; // don't open new bin if it's the only fitting one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward exact harmonic fits: post_residual divisible by common size classes
    let mut harmonic_bonus = 0.0;
    for &m in [10u32, 20, 25, 50].iter() {
        if post_residual % m == 0 && post_residual > 0 {
            harmonic_bonus += 4.0;
        }
    }
    score -= harmonic_bonus;

    // Penalize dead space: residuals too small for the smallest item (1..10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            // next item cannot fit here; penalize leaving mid-range residual
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Fraction-of-capacity classes: prefer residuals in low quarters (tight packs)
    let frac = pr / cap;
    if frac <= 0.25 {
        score -= 5.0 * (0.25 - frac);
    } else if frac > 0.75 {
        score += 4.0 * (frac - 0.75);
    }

    // New-bin candidate: only attractive when current residuals are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins mildly; worse when many bins already fit item
        score += 8.0 + 2.0 * fitting_bins_count as f64;
        // but if item is huge relative to typical residual, new bin helps
        if (item_size as f64) > mean_residual {
            score -= 6.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Slight preference for bins tighter than average
    score -= (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but small gaps under ~10 are almost surely dead) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    if item_size > 0 {
        score += (post_residual as f64 / item_size as f64) * 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // creates likely dead space for the next item
    }

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // over opening new ones (penalize the new-bin candidate).
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: empty bin (residual == capacity) gets a penalty that
    // grows with open bins count, unless the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // But if next item is large and this item is small, new bin may be wise:
        if next_item_size > 0 && next_item_size > post_residual && item_size < 30 {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: bins far below mean residual have more room to
    // absorb future items; prefer them slightly.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Slight stream-progression bias: later in the stream, be more conservative
    // about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post_residual exactly matches the next item size (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_bonus = if post_residual == next_item_size {
            30.0 // perfect chain: next item fills this bin exactly
        } else {
            let r = post_residual as f64;
            let n = next_item_size as f64;
            15.0 * (1.0 - ((r - n) / r).abs())
        };
        score -= match_bonus;
    }

    // Penalize post_residual too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.5;
    }

    // Relative-to-mean coupling: bins tighter than average are more precious; prefer filling them.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (residual_f - mean_residual) / mean_residual;
        score += rel * 5.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize leaving large unusable gaps (post_residual below min item size 1..10 typical).
    if residual_f > 0.0 && residual_f < 10.0 {
        score += (10.0 - residual_f) * 2.0;
    }

    // Early in stream: slightly favor consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 0.3;

    // New-bin candidate: make it unattractive unless it enables a perfect next-item fit.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0;
        let chain_reward = if next_item_size > 0 && post_residual >= next_item_size {
            20.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64))
        } else {
            0.0
        };
        score += base_penalty - chain_reward;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for likely future items (min size 1..~40 band)
    if post_residual > 0 && post_residual < 12 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_bonus = -18.0 + 20.0 * item_frac;
        // late in stream, prefer consolidating into open bins
        new_bin_bonus += 10.0 * progress;
        // many open bins with slack: discourage new bin
        new_bin_bonus += 0.05 * open_bins_count as f64;
        // if next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            new_bin_bonus -= 8.0;
        }
        score -= new_bin_bonus;
    } else {
        // Prefer bins whose residual is closest to item (best-fit flavor)
        let gap = (bin_residual - item_size) as f64;
        score += 0.10 * gap;
        // Prefer bins with below-average residual (fill the emptiest-tightest first)
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer bins with small post-residual, damped non-linearly.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth progress coupling: later in stream, dead space is costlier.
    score += 12.0 * norm_post * norm_post * progress;

    // Reward tight fits (small post residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_next = if next_item_size as u32 <= post_residual { 1.0 } else { 0.0 };
        score -= 8.0 * fit_next * (1.0 - gap / cap).max(0.0);
        // Penalize if next item is large and this bin wastes space.
        score += 3.0 * (next_item_size as f64 / cap) * norm_post;
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless residuals of open bins are all poor.
    if bin_residual == bin_capacity {
        let mean_bad = (mean_residual - item_size as f64).max(0.0) / cap;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 25.0 - 18.0 * mean_bad * scarcity;
        score += 5.0 * progress;
    } else {
        // Mild preference for bins deviating below mean residual (consolidation).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify by capacity fraction.
    // Residuals that are "harmonically useful" (multiples of common item sizes)
    // should be rewarded; tiny dead space penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize small dead space (< 10) heavily: unusable for min item size 1? keep mild.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward residuals that are multiples of 50, 25, 20, 10 (harmonic classes).
    if post_residual % 50 == 0 && post_residual > 0 { score -= 12.0; }
    else if post_residual % 25 == 0 && post_residual > 0 { score -= 7.0; }
    else if post_residual % 20 == 0 && post_residual > 0 { score -= 5.0; }
    else if post_residual % 10 == 0 && post_residual > 0 { score -= 3.0; }

    // Integer-division threshold on post_residual: quarter/half classes.
    if post_residual > bin_capacity / 2 { score -= 8.0; }
    else if post_residual > bin_capacity / 4 { score -= 2.0; }
    else if post_residual > 0 { score += 2.0; }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 25.0; }
        else if next_item_size <= post_residual {
            score -= 6.0;
            // harmonic match: next item leaves again a multiple-of-10 residual
            if (post_residual - next_item_size) % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted potential
            score += 3.0 * (next_item_size as f64 - pr).min(20.0) / 10.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-mean residual (tighter bins) for balance.
    score -= (mean_residual - pr) * 0.3;

    // New-bin candidate: default moderate score; make it attractive only when
    // the item is large relative to residual (poor fit everywhere) or late stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_fit = (item_size as f64) / cap;
        // New bin attractive when item is big (leaves harmonic half-space) or many bins open
        score = 20.0 - 15.0 * tight_fit - 5.0 * progress;
        if item_size % 50 == 0 { score -= 5.0; }
        if fitting_bins_count > 0 {
            // an open bin exists that fits: make new bin slightly worse so it's only
            // chosen when fit quality elsewhere is bad (handled by penalties above)
            score += 4.0;
        }
    }

    // Mild preference for fuller bins overall (waste minimization).
    score += (bin_residual as f64 - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are dead space. Penalize heavily, but forgive
    // a perfect (zero) fit.
    if post_residual > 0 {
        // Dead-space zone: gap smaller than the smallest plausible item (10)
        // is nearly unusable -> quadratic penalty.
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual <= 25 {
            // Small gaps (10..25) are only usable by small items; moderate penalty.
            score += 8.0;
        }
        // Nonzero leftover generally slightly worse than an exact fit.
        score += 4.0;
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Exact-fill lookahead: if the next item exactly consumes the post_residual,
    // this is a chain fill -> strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item fits in the leftover, mild reward for keeping usable space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If next item cannot fit into the leftover, the gap risks becoming dead
    // space -> penalty scaled by how far off it is.
    if next_item_size > post_residual {
        score += 5.0 * ((next_item_size - post_residual) as f64).min(20.0);
    }

    // Open-bins pressure: when many bins are open, discourage spreading items
    // across bins; prefer filling existing bins (favor low post_residual bins).
    let bins_pressure = (open_bins_count as f64) * 0.15;
    score += bins_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin moderately attractive so it
    // beats very poor fits, but lose against reasonable fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; subtract pressure when few bins open.
        score = 45.0 - 0.5 * (open_bins_count as f64);
        // Late in the stream, opening new bins is less useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Existing bin with a good fit (small post_residual) should beat the
        // new-bin baseline: give a bonus for tight fits.
        if post_residual <= 15 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: when the average open-bin residual is large,
    // there is slack in the system -> slightly prefer tight placements here
    // to keep the mean from ballooning.
    score += 0.05 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item closure
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    }

    // Prefer bins whose residual is already small (tight packing)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins have decent residual
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Early in stream: slightly favor opening bins to build diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (best-fit core).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize very small dead space asymmetrically: residuals of 1..=9 are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 - post_residual as f64;
    }

    // Lookahead: reward if next item fits exactly into post_residual (perfect chain),
    // penalize if post_residual is stranded relative to next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
            score -= 5.0 * (1.0 - chain);
        } else {
            // post_residual too small for next item: dead space unless residual tiny.
            score += 2.5 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits badly everywhere (large post_residual) or few bins are open early on.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 10.0 - 4.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening new bins is wasteful.
        open_cost += 0.06 * mean_residual;
        // If many bins are open, slight extra reluctance.
        open_cost += 0.15 * open_bins_count as f64;
        score += open_cost;
    }

    // Mild penalty for placing into a bin whose residual is far above mean
    // (keeps residual distribution balanced for future items).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.02 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * pr_norm * pr_norm;

    // Smooth coupling: prefer tight fits as stream progresses
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (1.0 - slack) * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 10.0 * pr_norm;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 15.0 * progress;
    }

    // Mean residual coupling: penalize bins deviating from fleet average
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 5 classes.
    let class = (post_residual * 5) / bin_capacity; // 0..4 integer class
    match class {
        0 => score -= 40.0,                 // nearly full: excellent
        1 => score -= 12.0,                 // small gap, still useful
        2 => { score += 3.0; }              // medium gap
        3 => { score += 8.0; }              // large gap
        _ => { score += 0.0; }              // fresh bin
    }

    // Dead-space penalty: leftover that no plausible item (1..=100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo coupling: leftover divisible by common item sizes is reusable.
    let pr = post_residual;
    if pr >= 10 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0) * 0.5;
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0; // exact harmonic subdivision
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // penalize new bin when existing bins are well filled
        score += 45.0 * avg_fill + 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size <= item_size && item_size * 2 <= bin_capacity {
            score -= 15.0; // room for a companion item in fresh bin
        }
    }

    // Slight preference for tighter bins among equals.
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // Any residual below the minimum item size (1) is impossible, but gaps
    // that are too small for the *next* item are likely dead space too.
    if next_item_size > 0 && post_residual < next_item_size {
        // Gap cannot host the lookahead item: escalate penalty nonlinearly.
        let gap = post_residual as f64;
        score += 12.0 + 0.5 * gap; // small gaps get proportionally larger penalty
        if post_residual < 10 {
            // Very tiny gap: near-certain dead space.
            score += 25.0;
        }
    }

    // Reward tight fits (small post_residual) beyond the linear baseline.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when several are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large or the current fit is poor. An empty bin has huge residual, so
    // it needs an explicit handicap to avoid being chosen casually.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if item is large (would leave a big gap elsewhere), opening a
        // new bin is reasonable — soften the handicap.
        if item_size > bin_capacity * 3 / 4 {
            score -= 12.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: if average residual across open bins is already
    // low, this bin's placement is precious; reward using it well.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) more aggressively.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste_after_pair = post_residual - next_item_size;
        score -= 18.0 + 0.35 * (waste_after_pair as f64).min(50.0);
    } else if next_item_size > 0 {
        // Penalize creating dead space that the next item cannot use.
        score += 8.0 + 0.25 * (post_residual as f64);
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score += 0.30 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * (bin_capacity as f64 - post_residual as f64);
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (open_bins_count as f64 / (open_bins_count.max(1) as f64).sqrt());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placements where the lookahead item also fits (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * (next_item_size as f64);
    }

    // Penalize dead space that is too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins with small residuals relative to the mean (tight packing).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a bin when other bins fit,
    // unless the item is large and residuals are mostly small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let open_pressure = if fitting_bins_count > 0 { 20.0 } else { -10.0 };
        score += open_pressure + 15.0 * (1.0 - item_frac) * (0.5 + progress);
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr_norm.powf(1.5);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals slightly; late, penalize them more
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) - pr_norm * progress;
    score += coupling;

    // Dead-space penalty: residuals too small for typical future items are wasted
    let dead = ((pr_norm - 0.35) * (pr_norm - 0.35) * 4.0 - 0.5).max(0.0);
    score += dead * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.8;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 0.25 * (1.0 - pr_norm);
    }

    // Slight preference for compacting into fuller bins (low residual before placement)
    score += 0.1 * (bin_residual as f64 / cap) * (1.0 - progress);

    // Mild penalty when many bins are already open, discouraging further sprawl
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with smooth tilt based on progress
    if bin_residual == bin_capacity {
        score = 0.55 + 0.4 * progress - 0.2 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" integer-division classes are rewarded (less dead space).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quarters of capacity: post_residual in [0,25) is excellent,
    // [25,50) acceptable, [50,75) wasteful, [75,100) very wasteful.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    let quarter_penalty: f64 = match quarter {
        0 => -30.0,
        1 => -10.0,
        2 => 5.0,
        _ => 20.0,
    };
    score += quarter_penalty;

    // Modulo-10 harmonic class: small absolute dead space matters more
    // than fractional waste; reward near-zero residues.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else if mod10 <= 3 {
        score -= 4.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot fit the post-residual
    // (creates a bin that likely stays dead), reward if it fits snugly.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0;
        } else {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 35.0; // chain fit: perfect follow-up
            } else if slack < 10 {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make an empty bin attractive only when the item
    // is large relative to capacity or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = (item_size as f64 / cap) * 40.0;
        let crowding = (open_bins_count as f64 * 1.5).min(30.0);
        score = cap - large_item_bonus - crowding * progress + (cap - item_size as f64) * 0.3;
    }

    // Slight preference for tighter (smaller-residual) bins overall.
    score += (bin_residual as f64 - pr) * 0.05;

    // Tie-break with mean residual: prefer bins below the mean residual
    // (more filled than average).
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; the worst zone is tiny gaps (1..=8) that nothing useful fits.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0; // unusable dead space penalty
    } else if post_residual >= 9 && post_residual <= 15 {
        score += 25.0; // nearly dead space: only tiny items fit
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure is the ideal outcome
    }

    // Tight-fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 20.0 * fill_ratio;
    } else if fill_ratio < 0.35 {
        score += 10.0; // wasteful placement into a large bin
    }

    // New-bin candidate handling: an empty bin has huge post_residual already;
    // add pressure so it only wins when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 70 {
            score -= 25.0;
        }
    }

    // Open-bin pressure: discourage spawning many half-empty bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: avoid leaving a residual that cannot host the next item
    // while the current placement was loose.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 8 {
        score -= 15.0; // sets up a perfect closure next step
    }

    // Mild preference for balancing residuals across bins.
    if (bin_residual as f64 - mean_residual).abs() > 40.0 {
        score += 6.0;
    }

    // Late-stream tightening: as the stream ends, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits snugly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - slack * 0.35; // tight 2-step fit strongly favored
        if slack < 5.0 {
            score -= 8.0; // near-perfect chain bonus
        }
    }

    // Penalize dead space that next item cannot use, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size == 0 || post_residual < next_item_size {
        score += 6.0 + 10.0 * progress;
    }

    // Compare post_residual to mean residual: avoid creating outlier small residuals
    // unless it enables the 2-step chain.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 {
        score += 4.0;
    } else if pr > mean_residual * 1.5 {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current item leaves a large usable residual
    // and open bins are already fragmented.
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < item_size as f64 * 1.2;
        if !fragmented && post_residual >= 20 {
            score += 15.0; // prefer existing bins when they fit reasonably
        } else {
            score -= 5.0; // open new bin when fits are poor
        }
    }

    // Prefer tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.05;
    score += item_size as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use leftover space: mild penalty scaled by waste.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer filling bins with large residuals when many bins are open
    // (consolidation pressure grows with open_bins_count).
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 0.15 * pressure * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        1.0
    };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 35.0 * progress;
        // Discourage opening a new bin for small items.
        score += 0.4 * (bin_capacity - item_size) as f64;
    } else {
        // Existing bins get progressively more attractive over time.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post residual with stream progress
    let poly = x.powi(3) - 1.6 * x.powi(2) + 0.9 * x;
    let score = post
        + poly * (1.0 + 2.0 * progress)
        + 0.35 * (mean_residual - post)
        - 6.0 * (1.0 - progress) * (1.0 - x)
        + 5.0 * progress * x.powi(2)
        + if fitting_bins_count == 1 { -8.0 } else { 0.0 }
        + if next_item_size > 0 && (next_item_size as f64) <= x * cap { -4.0 * (next_item_size as f64 / cap) } else { 2.0 };
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 4 quarters.
    // Residuals in the lowest quarter (0..=25) are "dead space" -> penalize mildly less
    // than mid-range leftovers which are hard to pair. Penalize mid leftovers more.
    let q = post_residual / (bin_capacity / 4).max(1);
    match q {
        0 => score += 0.0,                       // tiny leftover, near-perfect fit
        1 => score += 6.0,                       // awkward small-mid leftover
        2 => score += 10.0,                      // mid leftover, hard to fill
        _ => score += 3.0,                       // large leftover still reusable
    }

    // Exact-fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic pairing: if next_item_size divides into post_residual exactly,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 4.0;
        }
    }
    // Penalize if next item cannot fit in the post residual (chain broken).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only chosen
    // when open bins are genuinely bad options.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is cheaper (less time to waste residual).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        return score;
    }

    // Prefer tighter bins: closeness of item to residual (high fill ratio) rewarded.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Deviation from mean residual: bins far below mean are "tight" and precious;
    // using them for a loose fit is wasteful.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    // Harmonic class of item size via modulo 10: sizes that are complements to common
    // residuals (multiples of 10) pack more cleanly.
    if item_size % 10 == 0 {
        score -= 2.0;
    }

    // Integer-division threshold: if post_residual lands in [10, 20] (smallest useful
    // class), it's a decent terminal state; if it lands in (20, 30) it's the worst class.
    if post_residual > 20 && post_residual < 30 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead);
    } else if dead <= 5.0 && dead > 0.0 {
        score += 40.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Post-residual that exactly fits the lookahead item is valuable.
    if next_item_size > 0 && post_residual as u32 >= next_item_size && (post_residual as u32 - next_item_size) < 10 {
        score -= 12.0;
    }
    // Post-residual too small for anything (min size 1) already covered; too small for next item adds pressure mildly.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones.
    let pressure = open_bins_count as f64 / 20.0;
    score -= pressure * (bin_residual as f64 - item_size as f64).max(0.0) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we only open when existing fits are bad,
    // unless open bin count is very low and item is large.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.5;
        if item_size > 70 && open_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: if the next item exactly fills the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits too: reward proportionally to how well it fills again
            let second_post = post_residual - next_item_size;
            score -= 20.0 * (1.0 - second_post as f64 / bin_capacity as f64);
        } else {
            // next item does not fit: penalize if post_residual becomes dead space
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(30.0) * 0.4;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leaving less than average residual is desirable (compact packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 1 {
        score += 40.0;
    }
    // But allow a new bin when item is large and would leave tiny dead space elsewhere... handled by tight-fit term.

    // Late-stream compaction: as stream progresses, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize large dead space nonlinearly; dead space under ~10 is nearly useless
    let dead = post_residual as f64;
    if dead < 10.0 {
        score += 25.0 * (10.0 - dead);
    } else {
        score += 0.05 * dead * dead / 10.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size as u32;
        score -= 8.0 + 0.3 * slack_after_next as f64;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Crowding: with many open bins, prefer filling existing ones over opening new
    let crowd = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is usable
        score += 15.0 + 2.0 * crowd;
        if mean_residual >= item_size as f64 {
            score += 10.0 + mean_residual * 0.1;
        }
        // Late in stream, opening new bins is cheaper; soften the penalty
        score -= 10.0 * progress;
    } else {
        // Existing bin: mild bonus scaled by how many bins compete for this item
        score -= 1.5 * (fitting_bins_count as f64).min(5.0);
    }

    // Global balance: prefer bins near the mean residual (spread work evenly)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Base: prefer small post-residual (tight fit), normalized.
    let mut score = pr / cap;

    // Non-linear penalty for awkward dead space: mid-range residuals are worst.
    let prn = pr / cap;
    score += 0.35 * prn * (1.0 - prn) * 4.0;

    // Smooth polynomial coupling of post_residual with stream progress.
    let t = progress;
    let coupling = prn * prn * (1.0 - t) - prn * t * t;
    score += 0.5 * coupling;

    // Reward filling bins tightly as stream advances.
    score -= 0.3 * (1.0 - prn) * (1.0 - prn) * t;

    // Last-chance bonus: strongly favor this bin if it is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Prefer bins below mean residual (more usable leftovers elsewhere).
    score += 0.15 * (pr - mean_residual) / cap;

    // Lookahead: if next item fits exactly in post-residual, reward heavily.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 0.8;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Dead space that cannot fit the next item is penalized smoothly.
        let waste = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 0.4 * waste;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.01 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits nonlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= (1.0 - pr / cap) * 20.0;

    // Perfect / near-perfect fit bonus via modulo classes on post_residual.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        // Dead-space penalty grows for residuals in "unusable" classes.
        // Residuals < 10 are dead (min item size); residuals in (10,20) are risky.
        if post_residual < 10 {
            score += 40.0;
        }
        let cls = post_residual % 10;
        if cls != 0 {
            score += cls as f64 * 0.5; // penalize non-round residual classes
        }
    }

    // Harmonic class coupling: does post_residual match next_item_size exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3;
            // Integer-division threshold: can next item also leave a small residual?
            if post_residual / next_item_size.max(1) >= 1 && post_residual % next_item_size.max(1) <= 5 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here anyway: mild penalty proportional to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer zero residual.
        score += pr * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should win only when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 35.0;
        // If existing bins are tight/fragmented, opening fresh is attractive.
        if mean_residual < (cap - item_size as f64) * 0.35 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // Large item with poor fit prospects elsewhere: open new bin.
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
    }

    // Mild pressure against bin sprawl.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual coupling: if this bin is far from mean, slight penalty.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for any item are wasted.
    // Since items are 1..=100, a post_residual < 10 is nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 35.0;
    }
    // Penalize leaving a residual that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).sqrt() * 1.5 * (1.0 - progress);

    // New-bin candidate (empty bin): neutral baseline, slightly worse than a good fit,
    // but better than dumping into a bin creating dead space.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 1 {
            score += 30.0; // never open a new bin when an existing one is the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect/near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // small slack after next item => good 2-step chain
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize leaving residuals that are likely dead space (small but nonzero)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 30.0;
    }

    // Compare against mean residual: prefer bins whose residual is tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize unless current bin would leave very poor residual
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive if no good fit exists;
        // make it costly by default
        score += 250.0;
        // but if lookahead item is huge and this item leaves bad residual elsewhere,
        // slightly reduce the penalty for a fresh bin
        if next_item_size >= 60 {
            score -= 60.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 60.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // If next item is small enough to fit post_residual exactly, extra reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // Dead-space penalty: post_residual that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Time horizon: late in the stream, prefer using existing bins (avoid new bins).
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: penalize opening new bins, more so late in stream
        // or when open bins exist and fit is reasonable.
        score += 25.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Global state coupling: if mean residual is high, spread load into emptier bins.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Many open bins: discourage opening yet another, encourage consolidation.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly scaled
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, dead space becomes more costly
    let dead_space_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 20.0 * dead_space_penalty;

    // Reward using a bin when it is the last fitting option (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Penalize bins whose residual is far from mean residual (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            // next item won't fit here: slight penalty proportional to wasted potential
            score += 4.0 * (nxt - pr) / cap;
        }
    } else {
        // last item: just minimize post_residual
        score += 0.0;
    }

    // Mild penalty for spreading across many open bins when post_residual is large
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate handling: empty bin has high post_residual; add fixed offset
    // so it's only chosen when all fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes
    // class 0: perfect fit (post_residual == 0)
    // class 1: tiny gap (<= 10) — nearly perfect
    // class 2: medium gap (11..=30)
    // class 3: large gap (> 30)
    let post_class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 30 { 2 }
        else { 3 };

    // Modulo-based harmonic penalty: gaps that are multiples of 4 or 5
    // are more likely to be filled by future items (common size granularity).
    let gap_mod_bonus = if post_residual > 0 {
        let m4 = (post_residual % 4 == 0) as f64;
        let m5 = (post_residual % 5 == 0) as f64;
        let m10 = (post_residual % 10 == 0) as f64;
        2.0 * m4 + 2.5 * m5 + 3.0 * m10
    } else { 0.0 };

    // Integer-division thresholds on post_residual: quantize into 20-wide bands
    let band = post_residual / 20;
    let band_penalty = match band {
        0 => 0.0,
        1 => 2.0,
        2 => 5.0,
        3 => 9.0,
        4 => 14.0,
        _ => 20.0,
    };

    score += band_penalty;
    score -= gap_mod_bonus;

    // Reward perfect/near-perfect fits strongly
    match post_class {
        0 => score -= 50.0,
        1 => score -= 20.0,
        2 => score -= 5.0,
        _ => {}
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation), unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_class <= 1 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for large items that leave a
        // "harmonically clean" residual (multiple of 10), since future items
        // of round sizes fit well. Penalize opening new bins when many bins
        // are already open and mean residual is high (waste).
        let clean = (post_residual % 10 == 0) as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0;                 // base cost of a fresh bin
        score -= 10.0 * clean;         // clean split reward
        score -= 8.0 * (1.0 - progress); // early stream: new bins cheap
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this bin becomes a two-item chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
            // next item cannot use this gap; penalize large stranded gaps more
            score += (post_residual as f64) * 0.05;
        }
    }

    // Mild preference for tighter bins among comparable options
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: if the next item cannot use the leftover, penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Open-bin pressure: with few bins open, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
        // Opening a new bin is acceptable only if this is the last fitting bin
        // and the current fit would leave bad dead space.
        if fitting_bins_count == 1 && post_residual < 15 {
            score -= 30.0;
        }
    } else {
        // Slight preference for reusing bins with the smallest residual (best fit).
        score += 0.05 * (bin_residual as f64);
        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mild pull toward bins with residual close to the item size (good coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: exact fill is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // next item exactly fills this bin afterwards
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // tighter match => better; nonlinear decay
            score -= 200.0 * (1.0 - gap / bin_capacity as f64).powi(2);
        } else {
            // next item cannot fit here; penalize dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals
    // near the mean (keeps the pool of usable bins balanced).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * diff;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize large unusable dead space (< typical small item) harder late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + 100.0 * progress;
    }

    // Mild penalty for spreading across many bins: encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Slight preference for tighter fits overall (relative fill ratio).
    score -= 20.0 * (item_size as f64 / bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: penalize leaving residual too small for the next item (dead space),
    // but only partially, since the next item may fit elsewhere.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        } else {
            // Reward bins that can also accommodate the next item (chaining).
            score -= 2.0;
        }
        // Perfect chain: next item exactly fills the post residual.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Prefer tight fits: small post_residual relative to item size is good,
    // but tiny unusable slivers (< 10) are dead space — penalize them.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // New empty bin candidate: penalize mildly to prefer filling open bins,
    // but relax the penalty for large items late in the stream.
    if bin_residual == bin_capacity {
        let mut penalty = 12.0;
        if item_size > bin_capacity / 2 {
            penalty *= 1.0 - 0.4 * t;
        }
        // If open bins are mostly full (low mean residual), opening a new bin is fine.
        penalty *= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += penalty;
    }

    // Slight preference for bins with above-mean residual when stream is early,
    // preserving tight bins for small items; reversed late in the stream.
    let mean_term = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += mean_term * (1.0 - 2.0 * t) * 4.0;

    // Mild crowding penalty: with many open bins, prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let prog_poly = progress * progress * (3.0 - 2.0 * progress);
    score += 12.0 * (norm_pr * norm_pr) * (1.0 + prog_poly);
    score -= 18.0 * norm_item * norm_pr * (1.0 - prog_poly);
    score += 8.0 * (norm_pr - 0.5) * (norm_pr - 0.5) * prog_poly;

    // Lookahead fit reward (smooth cubic in next item size)
    if next_item_size > 0 {
        let fit_next = (bin_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score -= 15.0 * fit_next * (1.0 - norm_next * norm_next);
    }

    // Last-chance bonus: smooth in fitting_bins_count
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - prog_poly * 0.5);
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild spread penalty vs mean residual
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: prefer it only when residuals of open bins are poor
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - norm_item) * prog_poly;
        score += 20.0 * (1.0 - prog_poly);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste falls into capacity-fraction buckets
    let frac = post_residual as f64 / cap;
    // Integer-division thresholds: dead-space class in units of 10
    let dead_class = post_residual / 10;
    let dead_bonus = (dead_class * dead_class) as f64;

    // Penalize residual that is too small to fit the smallest plausible item (1..100 stream)
    if post_residual > 0 {
        // unusable-ish residual: cannot fit next item
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // sweet spots: residual that matches common item sizes (harmonic classes)
        let harmonic = (post_residual % 25 == 0) as f64 * 6.0
            + (post_residual % 20 == 0) as f64 * 4.0
            + (post_residual % 10 == 0) as f64 * 2.0;
        score -= harmonic;
    } else {
        // perfect fill is ideal
        score -= 25.0;
    }

    // Non-linear dead-space penalty scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += dead_bonus * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: open a fresh bin when the fit would leave a bad class
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // but if the current bin would leave a large dead class, new bin is attractive
        if post_residual > 0 && post_residual < next_item_size.max(1) {
            score -= 20.0;
        }
        // early stream: cheaper to open bins (more flexibility later)
        score -= 20.0 * (1.0 - progress);
        // many open bins: discourage spreading
        score += open_bins_count as f64 * 0.5;
    } else {
        // prefer tighter bins (smaller residual before placement)
        score += bin_residual as f64 * 0.05;
        // align with mean residual: bins below mean are more "used up", favor them
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Lookahead coupling: reward leaving exactly room for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small gaps that likely cannot host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 && next_item_size > post_residual {
        score += 25.0;
    }

    // Penalize post_residual that cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(80) {
        score += 12.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits (small waste relative to capacity).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate gets penalized when open bins already exist.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 8.0; // future big item may prefer a fresh bin, slight relief
        }
    }

    // Mild global pressure: keep mean residual spread reasonable.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Slight preference to fill bins earlier in the stream.
    score += 0.02 * (step_index as f64 / total_items.max(1) as f64) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Aggressive 2-step lookahead: perfect match if next item fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // Next item can't fit here: penalize leaving residual that invites bad fits.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // Last item: prefer minimal residual.
        score += 5.0;
    }

    // Relative to mean residual: bins tighter than average get preference.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, avoid opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild penalty for accumulating many open bins with large residuals.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving residual that is too small for the smallest possible item
    // (dead space), scaled by how dead it is.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Next item won't fit here: mild penalty proportional to overflow gap.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    score += open_bins_count as f64 * 0.3;

    // Compare against mean residual: bins with less residual than average are
    // good targets (use up the cramped bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Time horizon: early in the stream, be slightly more conservative about
    // filling bins tightly (more items to come); late, be aggressive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // New-bin candidate: neutral-ish baseline, but prefer it only when no open
    // bin offers a decent fit (post residual would be huge). Make the empty bin
    // attractive when the best-fit residual is very large via a mild penalty
    // that open bins with small residuals can overcome.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.15;
        // Opening a new bin is more acceptable when many bins are open and
        // residuals are large (fragmentation is high anyway).
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Smooth polynomial coupling of post_residual with stream progress
    score += norm_pr * norm_pr * (40.0 + 60.0 * t);
    // Reward tight fits (small post_residual), stronger late in stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 50.0 * t * t);
    // Penalize dead space relative to mean residual
    score += (pr - mean_residual).max(0.0) * 0.3 * (0.5 + t);
    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }
    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05;
    // New-bin candidate: penalize unless residual would be very small or item large
    if bin_residual == bin_capacity {
        let tight = (item_size as f64 / cap - 0.9).max(0.0);
        score += 15.0 - 60.0 * tight;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 10.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 define "dead space classes".
    // Residues that are hard to fill (1..9 small leftovers) are penalized super-linearly.
    let pr = post_residual as i64;
    let class = pr % 10;
    let dead_penalty = match class {
        0 => 0.0,                       // perfectly divisible leftover, reusable
        1..=3 => 6.0 + 2.0 * class as f64, // tiny unusable slivers
        4..=6 => 1.0,                   // moderately reusable
        _ => 3.0,                       // 7..9 awkward zone
    };
    // Scale dead-space penalty by how late in the stream we are (endgame matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += dead_penalty * (0.5 + 1.5 * progress);

    // Integer-division threshold: does the post residual still fit a "harmonic block"
    // of the capacity? Blocks of 10, 20, 25, 50 are classic packing-friendly sizes.
    let blocks: [(u32, f64); 5] = [(10, 4.0), (20, 9.0), (25, 11.0), (50, 25.0), (100, 60.0)];
    for &(b, w) in blocks.iter() {
        if post_residual >= b && b <= bin_capacity {
            score -= w;
        }
    }

    // Lookahead coupling: reward leaving exactly enough room for the next item,
    // penalize leaving almost-but-not-quite room (worst case: wasted near-fit).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64 - n).abs() < 1.0 {
            score -= 30.0; // perfect pairing
        } else if post_residual >= next_item_size {
            score -= 8.0;  // next item still fits here
        } else {
            let overflow = n - post_residual as f64;
            // near-miss penalty: leftover that the next item *almost* fits into
            score += 4.0 + 0.6 * overflow.min(30.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, prefer tighter fit via post_residual (already core term)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits terribly everywhere else. Give the fresh bin a mild handicap unless
    // mean residuals are bloated (fragmentation high) late in the stream.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        if frag > 0.6 && progress > 0.4 {
            score -= 10.0 * frag; // fragmented state: fresh bin is attractive
        } else {
            score += 18.0; // default: prefer existing bins
        }
    }

    // Mild preference for bins below mean residual (consolidating emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Super-linear tail: large residuals are cheap, tiny residuals expensive.
    let r = post_residual as f64 / cap;
    if r > 0.0 && r < 0.1 {
        score += 15.0 * (0.1 - r) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space". Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0; // only fits very small items
    } else if post_residual <= 40 {
        score -= 6.0; // decent gap, mildly reward
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 12.0; // next item fits snugly afterwards
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // next item won't fit here; residual likely wasted
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.15 * (post_residual as f64);
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Compare against mean residual: choosing a bin far below mean residual
    // concentrates packing; choosing an outlier-large-residual bin wastes it.
    if bin_residual as f64 > mean_residual * 1.3 && bin_residual != bin_capacity {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., the fit here would create big dead space) or few bins are open.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > 35.0;
        if bad_fit || open_bins_count == 0 || (fitting_bins_count == 0) {
            score -= 30.0;
        } else {
            score += 35.0 + 1.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match bonus (strong).
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: mild bonus scaled by closeness.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize dead space.
            score += 0.35 * diff;
        }
    }

    // Penalize residuals far above mean residual (fragmentation risk).
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when it enables a perfect 2-step chain,
    // otherwise discourage spreading across bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        } else {
            score += 15.0;
        }
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is good, but penalize dead space
    // that is too small to fit a future item (below typical minimum item size).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 2.5; // wasted sliver
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Penalize placements that strand space slightly above next item size
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 8.0 {
                score += gap * 1.2;
            }
        }
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation)
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (3.0 + 4.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate handling: prefer opening a new bin when residual is
    // fragmented (mean residual low) or late in stream with large next item.
    if bin_residual == bin_capacity {
        let mut new_bin_score = score + 12.0; // default mild reluctance to open new bins
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // must open
        }
        if mean_residual < item_size as f64 && fitting_bins_count > 0 {
            new_bin_score -= 5.0; // open bins are too fragmented anyway
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && progress > 0.3 {
            new_bin_score -= 6.0;
        }
        // Late in stream, keep consolidating
        new_bin_score += progress * 4.0;
        return new_bin_score;
    }

    // Mild tie-break: prefer bins whose residual deviates from mean (specialization)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post residual (tight fit)
    let mut score = pr as f64;

    // Smooth polynomial coupling: reward tight fits more as stream progresses
    let tightness = (1.0 - norm_pr).powi(2);
    score -= 40.0 * tightness * (0.5 + progress);

    // Penalize large dead space non-linearly, weighted by stream progress
    score += 30.0 * norm_pr.powi(2) * (1.0 + progress);

    // Interaction: post_residual vs mean residual — avoid outliers vs fleet average
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into post residual (smooth ramp)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - slack).powi(2);
    } else if next_item_size > 0 {
        // penalize blocking the next item
        score += 8.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Mild preference for consolidating into fewer bins early on
    score += 0.5 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    // New-bin candidate: make empty bins less attractive unless residual after would be large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 10.0 * progress * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class bins: 0 = perfect fit, 1 = tiny dead space, 2 = half-class, 3 = large dead space.
    let class = if pr == 0 { 0u32 }
        else if frac < 0.1 { 1 }
        else if frac < 0.35 { 2 }
        else if frac < 0.6 { 3 }
        else { 4 };

    score += match class {
        0 => -60.0,                     // perfect fit is gold
        1 => -15.0,                     // near-perfect
        2 => 5.0,                       // mildly wasteful
        3 => 18.0,                      // dead space zone
        _ => 30.0,                      // huge residual left
    };

    // Modulo arithmetic on post_residual relative to small item sizes (10..=20):
    // residual that is an exact multiple of a common small size is reusable.
    let reusable = (10..=20).any(|s| pr > 0 && pr % s == 0);
    if reusable { score -= 12.0; }

    // Harmonic coupling with next item: reward residuals that exactly fit the lookahead.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size <= 40 {
            // lookahead item won't fit here anyway; slight penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, penalize when open bins are still roomy.
    if bin_residual == bin_capacity {
        score = 55.0
            + mean_residual * 0.6
            + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing lookahead with fresh bin may pay off
        }
    }

    // Stream progression: early on, be pickier about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).powi(2);
        // Perfect chain: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // Near-perfect: next item leaves small residue
        if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 20.0;
        }
    }

    // Penalize creating unusable dead space (too small for min item size 1..=100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // dead space below minimum item size
    }

    // Penalize large post_residual relative to mean residual (wasteful fit)
    let pr = post_residual as f64;
    if pr > mean_residual + 20.0 {
        score += (pr - mean_residual - 20.0) * 0.5;
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer fresh bin when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening a new bin mildly; escalate with number of open bins
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if lookahead suggests fresh bin chains perfectly (item + next item fill capacity)
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 100.0;
        }
        // late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Tight fit reward
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Mild penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins with small post_residual
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Penalize dead space that likely cannot be reused (post residual below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits in post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // bonus for near-exact two-item packing
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is usually bad unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in stream, opening bins is cheaper (exploration)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 45.0 * (1.0 - progress);
        // If many bins are open and residuals are fragmented, opening fresh is fine
        if open_bins_count as f64 > 8.0 && mean_residual < 25.0 {
            score -= 20.0;
        }
        // If next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate small residuals)
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let item_frac = item_size as f64 / cap;

    // Base: penalize post residual, non-linearly
    let mut score = norm_post.powf(1.5 + progress);

    // Smooth coupling: waste relative to mean residual across stream progress
    let waste = (pr as f64 - mean_residual) / cap;
    score += 0.8 * waste * (0.5 + progress);

    // Reward tight fits: smooth bell around near-full bins
    let tight = 1.0 - norm_post;
    score -= 1.5 * tight * tight * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor this bin if it is the only fit
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - norm_post);
    }

    // Lookahead coupling: penalize if post residual can't fit next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score += (1.0 - fits_next) * (next_item_size as f64 / cap) * (1.0 + progress);
        // reward if post residual still accommodates next item comfortably
        score -= 0.5 * fits_next * (1.0 - (pr - next_item_size as f64) / cap).abs();
    }

    // Slight penalty for opening new bins late in stream when alternatives exist
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (0.5 + 1.5 * progress * progress) * (1.0 - item_frac);

    // Mild pressure to consolidate: fewer open bins relative to progress preferred
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "nice" fractions
    // of capacity (multiples of 10, 20, 25) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        60.0 // perfect fit, strongly favored
    } else if pr % 25 == 0 {
        18.0
    } else if pr % 20 == 0 {
        14.0
    } else if pr % 10 == 0 {
        10.0
    } else if pr % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Dead space penalty: tiny unusable residues (1..=5) are wasted capacity.
    if pr > 0 && pr <= 5 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly
    // or nearly; penalize residues that strand just below the next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 22.0;
            } else if slack <= 5 {
                score -= 12.0;
            } else if slack <= 15 {
                score -= 6.0;
            }
        } else {
            // post-residual is smaller than next item: it becomes dead space
            // until another item fits; slight penalty scaled by gap.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bins are tight
    // or very fragmented; otherwise penalize so we prefer filling open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).abs()
        } else {
            0.0
        };
        // Open a new bin when mean residual is small (bins nearly full) or
        // late in the stream with many bins already open.
        let openness = fragmentation * 0.5 + progress * 0.3;
        score += 55.0 - openness * 70.0;
        // A new bin always has post_residual = capacity - item; that raw value
        // is already large, so add a modest extra guard against premature opens.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Mild preference for keeping residual near harmonic mid-caps (50/33/25)
    // via integer division thresholds on post_residual.
    let third = bin_capacity / 3;
    if pr >= third && pr < third * 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is small and unlikely to fit future items.
    if post_residual > 0 {
        let dead_threshold = 20.0f64;
        if (post_residual as f64) <= dead_threshold {
            // The smaller (but nonzero) the gap, the worse: quadratic blowup.
            let deadness = (dead_threshold - post_residual as f64 + 1.0).powi(2);
            score += 3.0 * deadness;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids wasted capacity elsewhere).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * next_fit_quality;
    }
    // If next item will NOT fit in the residual, the gap is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first),
    // keeping large-residual bins available for large future items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // New-bin candidate handling: empty bin gets a base cost so it only wins
    // when all open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening fresh bins is less useful; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);

        // Reward if next item fits exactly into post residual (perfect chain).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that the next item cannot use at all.
        if next_item_size > post_residual && post_residual > 0 {
            let waste = post_residual as f64;
            score += 0.3 * waste;
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 20.0;
    }

    // Compare post residual against mean residual: leaving less than mean is good (tight fit).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize creating small unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless it creates dead space).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Mild penalty for opening a new bin when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
    }

    // Progress-based tiebreak: early in the stream, be more conservative about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward;
    // if next item would leave this bin useless anyway, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor tight fits more);
    // late in the stream, accept looser fits to avoid opening extra bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress;

    // Many open bins: prefer consolidating into existing bins over opening new ones.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: if this bin's residual is far below mean, it is a
    // small leftover bin; using it up is good. If far above mean, mild penalty.
    let resid_f = bin_residual as f64;
    let dev = resid_f - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or there are no open bins.
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.6 && post_residual > 20;
        if open_bins_count > 0 && !bad_fit {
            score += 45.0;
        } else if open_bins_count == 0 {
            score -= 20.0;
        }
        // Late in stream, new bin is cheaper.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear waste penalty: dead space quadratically bad, worse late in stream
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with saturating non-linearity
    score -= 20.0 * (1.0 - (norm_pr * 3.0).tanh()) * (1.0 - progress * 0.5);

    // If next item fits exactly into the post residual, reward heavily (smooth coupling)
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = (pr - nx).abs() / cap;
        score -= 10.0 * (-gap * 8.0);
        // penalize leaving space that is almost-but-not-quite usable
        score += 6.0 * (nx / cap) * (pr / cap) * (1.0 - (-gap * 6.0));
    }

    // Last chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.3);
    }

    // Coupling with mean residual: prefer bins close to the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild pressure on open-bin count: many open bins -> prefer filling existing ones
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate should rarely win: it has the largest post_residual already,
    // but add explicit penalty that shrinks when item is huge relative to capacity
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - it / cap) + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible by common item sizes (10/20/25/50) are worth keeping.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, always best
    } else {
        // Integer-division harmonic classes on post_residual
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Dead-space penalty: tiny unusable leftovers
        if pr < 10 { score += 60.0; }
        else if pr < 20 { score += 25.0; }

        // Can the lookahead item fit exactly in the leftover? Reward that.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 40.0;
            } else if next_item_size <= pr {
                // next item fits but leaves another leftover: penalize by leftover size
                let npr = pr - next_item_size;
                score += (npr as f64) * 0.5;
                if npr < 10 { score += 15.0; }
                if npr % 10 == 0 { score -= 3.0; }
            } else {
                // next item cannot use this residual: mild penalty scaled by gap
                score += ((next_item_size - pr) as f64) * 0.1;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless residual is hopeless dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 || post_residual == 0 {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: an empty bin has high raw post_residual (=capacity - item),
    // which already scores high; add a mild bias so we only open new bins when
    // existing bins have poor fits. Bias shrinks as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - 0.5 * progress);
        // Opening a new bin is more attractive when many open bins are nearly full
        if mean_residual < 15.0 { score -= 10.0; }
    }

    // Prefer filling bins whose residual is below the mean (tightening packing)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Modulo coupling between item size and capacity classes: items in "large"
    // classes (>50) should go into tightest bins.
    if item_size > 50 {
        score += (post_residual as f64) * 0.3;
    } else if item_size <= 20 {
        score -= (post_residual as f64) * 0.1; // small items tolerate leftover
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger usable gaps are progressively less harmful.
        score -= 0.25 * (post_residual as f64).sqrt();
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.6 * pressure * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit, penalize wasted capacity slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.15 * (post_residual - next_item_size) as f64;
        }
    }

    // New-bin candidate handling: empty bin gets a mild default so it only
    // wins when existing bins score poorly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream with many open bins, prefer reusing bins.
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when post_residual exactly/mostly matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual as f64 - nxt);
            // Reward proportional to how well next item fills the leftover space.
            let match_quality = 1.0 - (gap / bin_capacity as f64);
            score -= 12.0 * match_quality * match_quality;
            // Perfect chain fit (post_residual == next_item_size): huge reward.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit in leftover: penalize dead space relative to next item size.
            let overflow = nxt - post_residual as f64;
            score += 0.15 * overflow;
        }
    } else {
        // Last item: just prefer minimal waste.
        score -= 5.0;
    }

    // Penalize large post_residual relative to mean residual (creating outlier dead space).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.08 * dev;
    } else {
        score -= 0.04 * (-dev);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Neutral-ish base for new bin; slight penalty so tight fits win.
        score += 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // New bin can chain-fit the next item too: attractive for large items.
            score -= 8.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post-residual disproportionately.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: bonus if the next item fits exactly / well into post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual unusable by next item: mild penalty scaled by waste.
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation (prefer filling existing bins over opening new).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // Global residual pressure: if mean residual is low, conserve space in fuller bins.
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let desperation = if fitting_bins_count <= 1 { 0.0 } else { (fitting_bins_count as f64).ln() };
        score += 55.0 + 12.0 * desperation - 30.0 * (1.0 - progress);
        // Early stream: opening bins is cheap and diversifies capacity.
        if progress < 0.15 {
            score -= 35.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: tighten packing later in the stream
    score *= 1.0 + 0.5 * progress * (1.0 - norm_pr);

    // Reward exact-ish fits via cubic decay of wasted space
    score -= (cap - pr) as f64 * 0.15 * (1.0 - norm_pr).powi(3);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if next item fits poorly into resulting residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 5.0 * (nx - pr) / cap;
        } else {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Discard tight bins when many open bins exist and mean residual is high
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // New-bin candidate: mild penalty so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands in "reusable" classes
    // (multiples of small harmonics) are more valuable to keep.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals divisible by common small harmonics (likely to fit future items).
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        else if pr % 4 == 0 { score -= 3.0; }
        // Penalize awkward odd residuals far from any harmonic class.
        if pr % 2 == 1 { score += 2.5; }
        // Dead-space penalty: residuals below the minimum plausible item size are useless,
        // except the perfect-fill case.
        if pr < 10 && pr > 0 { score += 30.0; }
    } else {
        // Perfect fill is ideal.
        score -= 60.0;
    }

    // Integer-division threshold on post_residual: classify fill quality.
    let fill_class = pr / 25; // 0..=4
    score += fill_class as f64 * 4.0;

    // Lookahead coupling: reward this bin if its post-residual can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 10.0 + (pr - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        // Creates blocking dead space for the lookahead item.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, scaled by how well
    // existing bins could absorb the item and how full the stream context is.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 20.0 * progress;
        // Opening a new bin is more attractive if the item is large (hard to place later).
        if item_size >= 60 { score -= 25.0; }
        // And if open bins are already crowded on average.
        if mean_residual < item_size as f64 { score -= 15.0; }
    }

    // Mild preference for bins with low residual overall (tighter packing).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small leftover gaps are unusable for future items (min size 1..100 unknown,
    // but treat gaps below ~15 as likely dead space)
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 8.0;
    }

    // Prefer tight fits generally: reward small post_residual relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses
        score += 40.0 + open_bins_count as f64 * 5.0 + progress * 30.0;
        // But if no open bin fits well (large post_residual elsewhere), new bin is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Using existing bins reduces open-bin pressure slightly
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; leftover becomes dead space for the lookahead
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Slight preference for filling bins with small residuals (consolidation)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
