        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Prefer bins with more open bins available (diversity control)
    if open_bins_count > 6 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but reward perfect fits extra.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space that cannot fit even the smallest plausible item.
        if post_residual < 10 {
            score += 8.0; // awkward sliver
        }
        // If the lookahead item fits in the post-residual, big reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else if next_item_size > 0 {
            // Lookahead won't chain: penalize proportionally to leftover.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.05 * pressure;

    // Time horizon: early in stream, opening new bins is cheap; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate score: base at capacity, adjusted by progress and mean residual.
        score = bin_capacity as f64 - 20.0 * progress - 0.3 * mean_residual;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 3.0;
        }
    } else {
        // Late stream: extra reward for using existing bins.
        score -= 10.0 * progress;
    }

    // Slight preference for bins whose residual deviates favorably from the mean.
    score -= 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Late in the stream, tight fits (small post_residual) are prized more.
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Smooth cubic term: penalize mid-range dead space super-linearly as stream advances.
    score += 0.8 * norm_pr * norm_pr * norm_pr * cap * (0.3 + progress);

    // Perfect fit reward (post_residual near zero or exactly usable).
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when mean residual is large
    // (existing bins have plenty of room), less when open bins are nearly full.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.35 * mean_residual - 5.0 * progress;
    }

    // Lookahead: reward leaving post_residual that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (nx / cap)) * (1.0 - progress);
        } else if post_residual > 0 {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Slight preference for bins tighter than average.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is far more costly in low
    // classes (tiny slivers that nothing can ever fit). Penalize slivers hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 3.0;
    }

    // Perfect fit reward (harmonic class 0 of capacity).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // fraction of post_residual consumed by next item
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * frac;
        } else {
            // next item cannot use this residual: dead-space penalty scaled
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity and open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // Opening a bin is penalized by default; discounted when bins are
        // fragmented (high mean residual = poorly usable) and item is large.
        score += 25.0 - 20.0 * pressure - 15.0 * fragmentation;
        // Late in the stream, opening fresh bins is cheaper (less future risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    }

    // Prefer tighter existing bins: compare residual to mean residual.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
