    }

    // Lookahead: if next item would fit into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover gap likely wasted relative to next item
        score += 3.0;
    }

    // New-bin candidate handling: discourage opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 1.5;
        if fitting_bins_count > 0 {
            score += 25.0 + pressure;
        } else {
            score += pressure * 0.2; // last resort: opening is fine
        }
    }

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.3;

    // Progression: later in the stream, be slightly more tolerant of residual waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Prefer bins whose residual is close to the mean (avoid outliers).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

