    }

    // Penalize large dead space creation (waste)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 120.0 - bad_fit * 200.0 - progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(6);

    // Penalize dead space that is too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fits almost perfectly afterwards.
            let two_step = post_residual - next_item_size;
            if two_step < 5 {
                score -= 10.0;
            }
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += 8.0;
        }
    } else {
        // Near the end of the stream: maximize packing density aggressively.
        score -= 15.0;
    }

    // Time-horizon modulation: early on, be conservative about wasting bins;
    // later, prefer filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * tightness;
    score -= 10.0 * (1.0 - progress) * tightness;

    // Discourage opening new bins when many bins are already open with slack.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins are crowded.
        let crowd = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 18.0 + 6.0 * open_bins_count as f64 - 10.0 * crowd;
        // If next item is large, a fresh bin is safer.
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    // Prefer bins with residual below mean (concentrate usage).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = r * (1.0 + 0.5 * norm_r * norm_r);

    // Smooth polynomial coupling of waste with stream progress:
    // early on, tolerate loose fits (bins may still fill); late, penalize waste strongly
    let waste_penalty = norm_r * norm_r * (1.0 + 3.0 * t * t) * cap * 0.05;
    score += waste_penalty;

    // Reward using nearly-full bins via smooth interaction with mean residual
    let mean_norm = mean_residual / cap;
    score -= 8.0 * (1.0 - norm_r) * (1.0 - norm_r) * (0.5 + t);

    // Encourage consolidation when many bins are open
    let ob = open_bins_count as f64;
    score += 0.02 * ob * norm_r * (1.0 + t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    } else {
        // mild penalty when many alternatives exist, scaled by fit quality
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0) * norm_r;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        let diff = (r - next_item_size as f64).abs();
        let fit_bonus = (1.0 - diff / cap).max(0.0);
        score -= 10.0 * fit_bonus * fit_bonus * (1.0 + t);
        // penalize leaving residual slightly larger than next item (dead space trap)
        if r > next_item_size as f64 && diff < 10.0 {
            score += 5.0 * (1.0 - diff / 10.0);
        }
    }

    // New-bin candidate: empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * t + 0.1 * ob;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible into common
    // fractions of capacity are more reusable (100, 50, 25, 20, 10 classes).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: heavily reward
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -15.0
    } else if pr % 20 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead space: tiny leftovers that few item sizes can use.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does the leftover match the next item well?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt {
            let slack = pr as f64 - nxt;
            // reward leftovers that fit the next item with little waste
            score -= 12.0 * (1.0 - slack / cap).max(0.0);
            // harmonic match: leftover is an exact multiple of next size
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's leftover at all
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline slightly above good fits.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.1;
        // open new bins more readily early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // don't open a new bin if an open bin gives a near-perfect fit
        if post_residual <= 5 {
            score += 40.0;
        }
    }

    // Prefer packing into bins whose residual is far below the mean
    // (consolidating space, keeping large residuals available).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for fuller bins overall (non-linear tightness reward)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tightness * tightness;

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

