    let dead_zone = (bin_capacity / 4) as f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 0.8;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= tightness * 25.0;
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // bin remains usable for lookahead item
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // next item cannot use this residual: dead space unless residual is tiny
        if post_residual >= 1 {
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (0.5 + progress);

    // Favor bins with residuals near the mean (balance residuals)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // New-bin candidate handling: empty bin starts at high baseline; only chosen
    // when no open bin offers a decent fit (i.e., all post_residuals would be bad).
    if bin_residual == bin_capacity {
        score = dead_zone + 30.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
