    if is_new_bin {
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        let crowded = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * 8.0;
        let mean_full = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 10.0 - big_item_bonus - crowded * mean_full;
        // Late in the stream, opening fresh bins is cheaper than fragmentation.
        score -= 4.0 * t;
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > bin_capacity / 2 {
