        let fit_gap = (bin_residual - item_size) as f64;
        score += fit_gap * 0.05;
        // Slight preference for bins already below mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Mild tie-breaking toward fewer open bins.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
