    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Penalize when this bin's residual deviates far below mean (fragmentation)
    score += 3.0 * ((mean_residual - pr) / cap).abs();

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly when open bins could still serve future items
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score = cap + 10.0 * (1.0 - progress) - 15.0 * openness * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 5 bands of 20.
    let band = post_residual / 20;
    let band_bonus = match band {
        0 => -14.0,  // almost full bin: excellent, strong reward
        1 => -7.0,   // good fit zone
        2 => 0.0,    // neutral mid zone
        3 => 5.0,    // wasteful zone
        _ => 9.0,    // nearly empty bin used for a small item: penalize
    };
    score += band_bonus;

    // Fine harmonic class: post_residual modulo 10 — tiny residues are dead space.
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 6.0; // perfect divisibility: residue is reusable
    } else if rem10 <= 2 {
        score += 4.0; // dead sliver
    } else {
        score += rem10 as f64 * 0.6;
    }

    // Coupling with next item: does the residue admit the lookahead item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 12.0; // lookahead fits exactly: perfect chain
            } else if slack <= 5 {
                score -= 8.0;  // near-perfect chain
            } else {
                score -= (10.0 * next_item_size as f64) / (post_residual as f64 + 1.0);
            }
        } else {
            // Lookahead cannot use the residue: residue becomes dead weight.
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(40.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: keep fresh bins attractive only when open bins are tight.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / ((step_index + 1) as f64).max(1.0);
        let mean_gap = (mean_residual - post_residual as f64).abs();
        // Fresh bin is penalized mildly; the penalty shrinks as mean residual grows.
        score += 18.0 - (mean_residual * 0.15).min(12.0) - pressure * 2.0 - mean_gap * 0.05;
    }

    // Progression: late in the stream, favor consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1)) as f64;
    score += progress * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // Tie-break: prefer bins with residual close to the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals of 1..=9 are nearly unusable
    // (min item size is small but such slivers waste capacity almost fully).
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0; // heavy penalty for creating unusable slivers
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize bins that would still leave a large but awkward residual
    if post_residual > 9 && post_residual < item_size {
        // residual smaller than current item => likely dead unless next item fits
        if next_item_size == 0 || next_item_size > post_residual {
            score += 12.0;
        } else {
            score -= 15.0; // next item fits perfectly into the gap
        }
    }

    // Lookahead coupling: if the next item exactly fits the post residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item cannot use this bin's leftover
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (huge post_residual penalty already applied).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones; with few open bins, new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure penalty; slightly cheaper early on.
        score += 10.0 + 8.0 * pressure - 5.0 * (1.0 - progress);
        // If no open bin fits well, opening a new bin is fine (handled by comparisons).
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Existing bin: reward slightly when pressure is high (consolidation).
        score -= 3.0 * pressure;
    }

    // Mild preference for bins whose residual is already below average
    // (fill the emptier bins first to close them out).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Exact 2-step lookahead match: post_residual == next_item_size is perfect.
    if next_item_size > 0 {
        let diff = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        score -= 30.0 * (1.0 - diff / 100.0).max(0.0);
        // Bonus when post_residual becomes unusable (<10) for future items
        if post_residual < 10 {
            score -= 25.0;
        }
    } else {
        // Last item: minimize waste directly
        score -= 10.0;
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * (1.0 - progress);
    }
    // Penalize bins far below mean residual (fragmented bins), reward tight fits
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= 0.3 * mean_gap;
    } else {
        score += 0.2 * (-mean_gap);
    }
    // Prefer filling bins that are already fairly full
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;
    // New-bin candidate: keep it as fallback unless open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64).sqrt();
        if post_residual < next_item_size as f64 && next_item_size > 0 {
            score -= 20.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_quality = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fit_quality * fit_quality;

    // Lookahead: bonus if next item fits into the post-residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Penalize leaving residuals that no typical next item can use.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 6.0; // tiny dead space is bad
            }
        }
    } else {
        // Last item: prefer filling a bin as full as possible.
        score -= 8.0 * fit_quality;
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive if current bins fit poorly.
        let pressure = if fitting_bins_count == 0 {
            20.0
        } else {
            (post_residual as f64) / (fitting_bins_count as f64)
        };
        // Favor new bin early (many items remain) or when alternatives are poor.
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + pressure - 15.0 * (1.0 - horizon);
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the last-chance bin
        }
    } else {
        // Last-chance bonus: if this is the only bin that fits, use it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Slight preference for bins below mean residual (balance spread).
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 3.0 * dev;
        // Mild pressure to consolidate when many bins are open.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth non-linear coupling of post_residual with stream progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + t);
    score -= 25.0 * norm_pr * (1.0 - norm_pr) * (1.0 - t);
    // reward tight fits more as stream progresses
    score -= (item_size as f64 / cap) * (10.0 + 30.0 * t);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 60.0;
    }
    // lookahead: penalize if post_residual can't fit next item but another residual could
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 15.0 * (nx - pr) / cap;
        } else {
            score -= 10.0 * (1.0 - (pr - nx) / cap) * (0.5 + t);
        }
    }
    // penalize deviation from mean residual (prefer balanced bins early)
    score += 8.0 * (pr - mean_residual).abs() / cap * (1.0 - t);
    // mild penalty for many open bins relative to progress
    score += (open_bins_count as f64).ln() * (2.0 + 6.0 * t);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which capacity fraction band it lands in.
    let band = post_residual / (bin_capacity / 5).max(1); // 0..=4 classes (0,20,40,60,80)
    match band {
        0 => score -= 8.0,                       // near-perfect fit: strongly reward
        1 => score -= 3.0,                       // small leftover, still usable
        2 => score += 1.0,                       // mid leftover, mediocre
        3 => score += 4.0,                       // large leftover, wasteful
        _ => score += 6.0,                       // huge leftover (tiny item in big bin)
    }

    // Integer-division harmonic: leftover divisible into next item's class?
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits_next = post_residual / next_item_size;
        if fits_next >= 1 {
            score -= 2.0 + 2.0 * (fits_next.min(3) as f64);
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: dead space penalty scaled by gap
        let gap = (next_item_size - post_residual) as f64;
        score += 1.5 + gap / bin_capacity as f64 * 6.0;
    }

    // Last-chance bin: strongly reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Prefer tighter bins: deviation from mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Modulo-10 class of post_residual: exact decades are cleaner.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    // Early in stream: keep bins open loosely; late: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // New-bin candidate: neutral baseline with mild penalty so it's chosen
    // only when no open bin scores well.
    if bin_residual == bin_capacity {
        score += 6.0 - progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1,
    // but practically below next_item_size or tiny slivers) are heavily penalized.
    let min_gap = next_item_size.min(80).max(1);
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else if post_residual < min_gap {
        // Unusable dead space for the lookahead item: penalize proportionally
        // to how "wasted" the gap is relative to capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 120.0 + 80.0 * waste_frac;
        // If no other bin can fit this item, this is the last chance:
        // soften the penalty so we don't open a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 90.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap remains usable by the next item: reward proportionally.
        score -= 30.0 + 20.0 * (next_item_size as f64 / post_residual as f64).min(1.0);
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 50.0 * tightness * tightness;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize opening new ones); when few are open, be lenient.
    let pressure = (open_bins_count as f64 / 20.0).min(3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure-scaled penalty.
        score += 60.0 + 40.0 * pressure;
        // Late in the stream, opening new bins is more costly (fewer future
        // items to amortize); early on, allow more freedom.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If this item would leave a large unusable gap in existing bins,
        // a fresh bin becomes attractive: reduce new-bin cost.
        if post_residual < min_gap && fitting_bins_count == 1 {
            score -= 70.0;
        }
    } else {
        // Existing bin: small reward for keeping bins consolidated.
        score -= 10.0 * pressure.min(1.0);
    }

    // Slight preference toward bins with below-average residual ( fuller bins
    // keep mean residual balanced and reduce fragmentation).
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in the stream, be picky about waste; later, accept tighter fits.
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // --- 2-step lookahead: reward residuals that exactly match the next item ---
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let diff = pr - nr;
            // Perfect 2-chain (post_residual == next_item_size): big reward.
            if diff == 0.0 {
                score -= 45.0;
            } else {
                // Reward closeness to a perfect chain, decaying quickly.
                score -= 40.0 * (-diff / (8.0 + 0.05 * nr)).exp();
            }
            // Extra bonus if the chain leaves near-zero slack after the next item.
            let post2 = pr - nr;
            if post2 <= 5.0 {
                score -= 12.0;
            } else if post2 <= 15.0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally to how
            // much dead space is stranded relative to the next item.
            score += 8.0 + 0.35 * (nr - pr);
        }
    } else {
        // Last item: only the tightest residual matters.
        score += 5.0 * progress;
    }

    // --- Relative-to-mean coupling: prefer bins with residuals near the mean,
    //     penalize outliers that create fragmented space. ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it
    //     over opening a new bin (unless residual waste is catastrophic). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if item is large and no good fit exists.
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if large_item {
            score -= 10.0;
        } else {
            // Discourage opening new bins for small items when open bins exist.
            score += 18.0 + 10.0 * (1.0 - progress);
        }
    }

    // --- Mild reward for filling bins tightly (small absolute residual). ---
    if post_residual <= 10 {
        score -= 10.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty for wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: strongly favor the only bin that fits (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should only win when it is
    // genuinely better (no fitting open bins, or item is large and would
    // fragment a bin needed for smaller items).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win normally.
        score += 25.0;
        // If this bin is the only option, make it very attractive.
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
        // Large items: keep open bins' residual intact for small future items.
        if item_size >= 60 && mean_residual < 35.0 {
            score -= 20.0;
        }
        // Late in stream, consolidate rather than spawn bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 30.0 * progress;
        }
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item
    // (dead space), reward residuals that can still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Bonus when post residual exactly matches next item (chain packing).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Reward filling bins that already have low residual (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Penalize creating very small unusable residuals (below min item size 1..10 zone).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Mild penalty for spreading across many open bins when few fit.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: penalize large residuals more as stream progresses
    score += progress * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly late in stream
    score -= (1.0 - progress) * (1.0 - (norm_pr - 0.5) * (norm_pr - 0.5) * 4.0) * 3.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins that waste residual relative to mean residual of open bins
    score += (pr - mean_residual) * 0.3;

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 2.0 + next_item_size as f64 * 0.05;
    } else if next_item_size > 0 {
        score += 1.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * 0.2 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular structure over capacity fractions
    let post = post_residual as f64;
    let class = (post_residual % 25) as f64;      // quarter-capacity harmonic class
    let half = (post_residual % 50) as f64;       // half-capacity harmonic class
    let tenth = (post_residual % 10) as f64;      // fine-grained class

    // Reward post-residuals landing on "usable" harmonic classes (multiples of 25/50)
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        // penalize dead space in fine classes, worse for small remainders
        score += (10.0 - tenth) * 0.4;
    }

    // Small absolute post-residual = tight fit, reward strongly
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Integer-division threshold: how many size-10 units remain usable
    let units = post_residual / 10;
    if units == 0 {
        score += 20.0; // dead space, unusable for smallest items
    } else {
        score -= units as f64 * 1.5;
    }

    // Lookahead coupling: does the next item fit into this bin's post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0;
            // bonus if next placement also lands on a good class
            if (post_residual - next_item_size) % 25 == 0 {
                score -= 5.0;
            }
            let _ = slack;
        } else {
            score += 4.0; // next item won't fit here; mildly deprioritize
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap - item_size as f64;
        // early in stream or many open bins: opening is more acceptable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 30.0;
        }
        // if mean residual is fragmented, a new bin is attractive
        if mean_residual < 30.0 && open_bins_count > 0 {
            score -= 8.0;
        }
    } else {
        // existing bins get a mild preference baseline
        score -= 3.0;
        // align with mean residual: bins far below mean are less attractive
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for the smallest plausible item are "dead space".
    let min_item = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_item {
        score += 60.0; // unusable sliver: strongly penalize
    }
    // Penalize gaps that cannot fit the lookahead item either (doubly wasted)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward near-perfect fits superlinearly
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // --- Open-bins pressure: discourage spreading across many bins ---
    score += (open_bins_count as f64) * 1.5;

    // Deviation from mean residual: prefer bins with residuals close to the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- Lookahead synergy: if next item fits exactly in post_residual, reward ---
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Slight late-stream tightening: later in the stream, prefer tighter packs
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Bonus for exact 2-step match (item + next item perfectly fills bin).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin fit is very poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item can't fit anywhere after this placement anyway,
        // opening fresh is neutralized.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 15.0;
        }
    }

    // Prefer fuller bins early in stream; more open bins -> prefer consolidation.
    if open_bins_count > 0 {
        score += 0.1 * (bin_capacity - bin_residual) as f64 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Reward near-full bins (small waste).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted opportunity
            score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the fullest one (smallest residual).
        score += 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Prefer bins with residual below mean (consolidate large residuals for future items).
    score += 5.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins is cheap early, expensive late (many open bins already).
        let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
        score = 55.0 + 30.0 * early + 25.0 * pressure;
        // If item is large, a fresh bin is more acceptable.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is large too, fresh bin pairs well.
        if next_item_size >= 50 && item_size >= 50 {
            score -= 15.0;
        }
        // Last resort: if this is the only fitting option, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small time-horizon modulation: late in stream, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * fit_norm * fit_norm);

    // Stream-progress coupling: tighten residual preference as stream advances
    score += 12.0 * progress * fit_norm * (1.0 - fit_norm) * (fit_norm - 0.5).abs();

    // Penalize dead space relative to next item's needs (smooth quadratic mismatch)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).max(0.0);
        score += 0.35 * gap * gap / cap;
        // Reward residuals that exactly anticipate the next item
        score -= 6.0 * (1.0 - (pr - nxt).abs() / cap).max(0.0);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - fit_norm);
    }

    // New-bin candidate: penalize mildly early, more when many bins open
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Mean-residual coupling: discourage bins far from the mean waste pattern
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space into discrete bands.
    // Small leftovers (<10) are "perfect" (dead space negligible); large leftovers are flexible.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward: post_residual in tiny class
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 15.0;
    } else if post_residual < 35 {
        // mid-class: mildly penalize, these are awkward leftovers
        score += 5.0;
    }

    // Modulo harmonic classes: residuals near multiples of common item sizes (10, 20, 25, 50)
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0; // clean harmonic multiple: likely reusable by grid-like items
    } else {
        score += mod10 as f64 * 0.5; // ragged leftover penalized proportionally
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 12.0 * fill;
            // harmonic match: next item leaves another clean multiple
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 6.0;
            }
            if nxt_post == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportional to wasted opportunity
            score += 4.0 + (next_item_size as f64 - pr) * 0.1;
        }
    }

    // Tightness: prefer bins where item fills a large fraction of residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists (early stream or huge item)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins when mean residual is still useful
        score += 25.0 + mean_residual * 0.3 - 20.0 * (1.0 - progress);
        if item_size >= 80 {
            score -= 20.0; // huge items: fresh bin reasonable
        }
    }

    // Fragmentation guard: avoid leaving residual in the awkward 1..9 band on a fresh-ish bin
    if post_residual >= 1 && post_residual <= 9 && bin_residual < bin_capacity {
        score -= 5.0; // already covered by small-class reward; keep small nudge
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.15;

    // Prefer bins whose residual is below mean (consolidate fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongly reward closing a bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Strict dead-space avoidance: gaps below the minimum item size
        // are unusable forever -> heavy penalty.
        score += 45.0 + 5.0 * (10 - post_residual) as f64;
    }

    // Lookahead (k=2): reward exact match for the next item,
    // penalize leaving a gap the next item cannot use.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Reward packing into already-occupied bins (fill level),
    // which makes brand-new empty bins (residual == capacity) less attractive.
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.35 * used;

    // Open-bin pressure: when many bins are open, discourage opening more
    // (the new-bin candidate has the largest post_residual, but reinforce it).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: if this is the only bin that fits, use it
    // rather than opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual > 0 && post_residual < 10 {
            score += 55.0; // still refuse to create dead space
        }
    }

    // Mild coupling to mean residual: prefer bins below the mean fill
    // spread (keeps residuals balanced, avoids many half-empty bins).
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0; // chain fill: this bin becomes perfect for next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: penalize wasted residual
            let dead = post_residual as f64;
            score += 0.5 * dead;
            if next_item_size > post_residual {
                let gap = (next_item_size - post_residual) as f64;
                score += 0.3 * gap;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    let diff = post_residual as f64 - mean_residual;
    score += 0.4 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0; // fresh bin perfectly set up for next item
        }
        // late in stream, avoid opening bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Slight preference for keeping many open bins manageable
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    if post_residual > 0 {
        score -= 8.0 / post_residual as f64;
    } else {
        score -= 12.0; // perfect fill is excellent
    }

    // Penalize large dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 20.0;

    // Lookahead: if next item fits in the post residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / 20.0);
        } else if next_item_size > post_residual {
            // Next item won't fit here; a tiny leftover is wasted — penalize small residuals.
            if post_residual < 15 {
                score += 10.0 - post_residual as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 5.0;
        // More attractive if existing bins have little room on average.
        score -= (mean_residual / 10.0).min(8.0);
        // Attractive late in the stream when many bins exist (fragmentation risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 3.0;
        // If it's the only fitting bin and it's the new bin, it will be chosen anyway.
        if fitting_bins_count <= 1 {
            score -= 4.0;
        }
    }

    // Mild global pressure: with many open bins, prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Prefer bins whose residual is close to the item (best-fit style).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += slack * 0.15;

    // Small time-varying exploration term to break ties deterministically.
    let phase = (step_index as f64 * 0.37).sin();
    score += phase * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, with non-linear (quadratic) growth.
    let mut score = post + 0.35 * post * post / cap;

    // Tight-fit reward: strongly subtract when post_residual is small.
    let tightness = 1.0 - post / cap;
    score -= 2.5 * tightness * tightness * item;

    // Lookahead coupling: reward if next item can fit into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = post - nxt;
            score -= 1.8 * (1.0 - slack / cap) * (0.5 + progress);
        } else {
            // Dead space penalty scaled by how much next item misses fitting.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.9 * miss * miss / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 6.0 * progress;
    }

    // Many fitting bins: mild penalty to prefer filling scarce-capacity bins.
    if fitting_bins_count > 1 {
        score += 0.4 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packing).
    score += 0.25 * (post - mean_residual);

    // New-bin candidate: make it unattractive unless it is genuinely the only option.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled.
    score += 0.5 * (post_residual as f64 / cap);

    // Harmonic class of post_residual: dead space in (0,10) is worst (unusable
    // for any item). Reward post_residual == 0 strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual >= 10 && post_residual <= 80 {
        // usable range: reward proportionally to how well next item could fit
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        }
    }

    // Modulo classes: residuals near multiples of capacity quarters are
    // "harmonic" slots — they combine well with common item sizes.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr == quarter || pr == half || pr == 3 * quarter {
        score -= 6.0;
    }
    if pr % 10 == 0 && pr >= 10 {
        score -= 3.0; // round residuals align with integer item sizes
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well, or the stream is early and future items are large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let lookahead_bad = next_item_size > 0 && next_item_size as f64 > post_residual as f64;
        // Penalize new bins moderately; the base post_residual (= capacity)
        // already makes it high, add a mild dynamic term.
        score += 15.0 * (1.0 - progress);
        if lookahead_bad {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Prefer bins with below-mean residual (keep a spread of bin fill levels).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev;

    // Coupling: if next item is large and this bin's post_residual can't hold
    // it, mild penalty (this bin becomes dead-ish for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals too small for any item (min size 1 assumed, but
    // small gaps below a usable threshold are effectively dead space).
    let usable_threshold = 12.0;
    if (post_residual as f64) < usable_threshold && post_residual > 0 {
        score += (usable_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += (next_item_size - post_residual as u32) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * (bin_capacity - post_residual) as f64 * 0.05;

    // Progression: later in the stream, be more conservative about waste
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    // Penalize bins with unusually large residuals (fragmentation avoidance)
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            score -= 150.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 40.0 + 0.3 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Tightness reward: small post_residual relative to item size is good
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Relative to mean residual: bins with residual far above mean waste potential
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize slightly unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 {
            score -= 100.0; // open bins nearly full -> new bin is fine
        } else {
            score += 200.0; // prefer filling existing fragmented bins
        }
    }

    // Late in stream: be more aggressive at closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: residual after placement near zero is great.
    let tightness = if post_residual == 0 {
        -60.0
    } else {
        -25.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3)
    };
    score += tightness;

    // Penalize leaving dead space that no plausible future item can use.
    // Items are 1..=100; a residual below ~10 is nearly dead.
    if post_residual > 0 && post_residual < 12 {
        score += 15.0 * (12.0 - post_residual as f64);
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // reward proportionally to how well next item fits
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Give empty bins a mild penalty so tight fits in existing
    // bins win, but allow it when mean residual is high (open bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Early in stream: keep bins open (penalty). Late: more willing to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = 10.0 + 25.0 * progress + 30.0 * fragmentation;
        score += openness;
    } else {
        // Slight penalty for bins already heavily fragmented relative to mean
        if (bin_residual as f64) > mean_residual + 0.5 * bin_capacity as f64 {
            score += 5.0;
        }
        // Reward consolidating into bins with small residuals (avoid many half bins)
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Global pressure: many open bins with high mean residual -> prefer filling
    // existing bins aggressively (subtract to favor them).
    if open_bins_count > 2 {
        score -= 0.5 * mean_residual.min(50.0) / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual penalized more heavily as stream progresses
    let norm_pr = pr / cap;
    score += 40.0 * progress * norm_pr * norm_pr;
    score -= 25.0 * (1.0 - progress) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Perfect fit reward (smooth)
    if pr == 0.0 {
        score -= 100.0;
    }

    // Lookahead: reward residual that fits next item, scaled by progress
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 30.0 * fits_next * (1.0 - (pr - nxt) / cap) * (0.5 + 0.5 * progress);
        // penalize residual slightly above next item (dead space)
        if fits_next > 0.0 && pr - nxt < 5.0 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - 0.5 * progress);
    }

    // Prefer bins with residuals deviating from mean (consolidation)
    let dev = (mean_residual - pr).abs() / cap;
    score += 15.0 * dev * (1.0 - dev);

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: coarse capacity-fraction buckets.
    let pr = post_residual;
    let class = pr / 10; // 0..10 integer division class of post-residual
    // Dead-space penalty grows superlinearly for mid-range unusable leftovers
    // (residuals that fit nothing typical are worst).
    if pr > 0 {
        let wasted = match class {
            0 => 0.0,                       // near-perfect fit
            1..=3 => (pr as f64) * 0.5,     // small leftovers: mildly wasteful
            4..=7 => (pr as f64) * 1.2,     // mid dead space: strongly penalized
            _ => (pr as f64) * 0.35,        // large residual: still usable
        };
        score += wasted;
    }

    // Reward exact or harmonic fits for the lookahead item (k=2).
    if next_item_size > 0 && next_item_size <= pr {
        let nxt = next_item_size as f64;
        if next_item_size == pr {
            score -= 40.0; // perfect chaining: bin closes exactly after next item
        } else {
            // modulo arithmetic harmony: next item divides residual nicely
            let m = pr % next_item_size.max(1);
            if m == 0 {
                score -= 18.0;
            } else {
                let frac = nxt / (pr as f64);
                score -= 12.0 * frac; // bigger usable chunk of residual = better
            }
        }
    } else if next_item_size > pr {
        // lookahead cannot use this residual: penalize proportionally
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep fresh bins available but not dominant.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; cheaper late in the stream / few open bins
        score += 55.0
            - 20.0 * (step_index as f64 / (total_items.max(1) as f64))
            - (open_bins_count as f64).min(5.0);
        // if the item is huge relative to capacity, opening fresh is fine
        if item_size as f64 > 0.7 * cap {
            score -= 20.0;
        }
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Mild progress scaling: earlier in stream, be pickier about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual below the minimum item size (1) is impossible; residuals
    // in [1, 20) are "dead-ish" because future items are often larger.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else {
        // Larger leftover: mild quadratic penalty.
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Tight fit reward: item occupies a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // a fresh bin; the new-bin candidate (residual == capacity) gets
    // penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 4.0;
        // But if no open bin fits well (large dead space elsewhere),
        // the new-bin penalty is softened by mean residual fragmentation.
        score -= mean_residual * 0.2;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= chain_tightness * 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Post residual is dead for the next item: penalize.
            score += next_item_size as f64 * 0.3;
        }
    }

    // Late in the stream, consolidate: mildly favor bins that are already
    // well-filled to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * progress;

    // Mean-residual coupling: when mean residual is small (bins are tight),
    // avoid creating new dead space even more aggressively.
    if mean_residual < 15.0 && post_residual > 0 {
        score += (15.0 - mean_residual) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step fit: post_residual == next_item_size -> big reward
        if lookahead_gap == 0.0 {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64) >= 0 {
            // Next item still fits in the leftover space
            score -= 25.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit: penalize proportionally to wasted potential
            score += 12.0 * (lookahead_gap / 100.0);
        }
        // Small exact-fit preference scaling with lookahead size
        score -= 8.0 * (next_item_size as f64 / 100.0) * (1.0 - lookahead_gap / 50.0).max(0.0);
    }

    // Tight fit reward: small post_residual is good (classic best-fit core)
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating dead space far from mean residual (fragmentation)
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.35 * dead;
    } else {
        score -= 0.15 * dead.abs();
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        let poor_fit_elsewhere = if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) < 0 { 1.0 } else { 0.0 };
        // Penalize new bin by default; discount when many bins open / poor fits
        score += 45.0 - 25.0 * crowd - 20.0 * poor_fit_elsewhere;
        // Late in stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild bonus for keeping open-bin count low
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(2);

    // Penalize dead space: leftover that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect chain: bin exactly fits the next item too.
            score -= 25.0;
        } else {
            // Leftover usable by next item: mild reward scaled by utilization.
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins less when few bins are open).
    let crowding = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open,
        // but allow it early in the stream or when residuals are fragmented.
        score += 18.0 * crowding;
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= 15.0 * (1.0 - progress);
        // If mean residual across bins is low (all bins nearly full), new bin is fine.
        score -= (mean_residual / 20.0).min(10.0);
    } else {
        // Existing bin: reward slightly more when bins are crowded.
        score -= 3.0 * crowding;
    }

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // with a non-linear coupling to item size.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev * (1.0 + item_size as f64 / 100.0);

    // Late-stream pressure: as the stream progresses, waste matters more,
    // so scale leftover penalty up over time.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.35 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, non-linearly coupled with stream progress
    let mut score = pr;

    // Smooth polynomial interaction: residual penalty grows as stream progresses
    let prog2 = progress * progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Reward tight fits (small post_residual) with smooth cubic term
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item * cap;

    // Penalize dead space that next item cannot use (smooth quadratic coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap * (1.0 + progress) * cap;
        } else {
            // smooth reward when next item fits into leftover
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 10.0 * fit_quality * fit_quality;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - prog2);
    }

    // Prefer bins below mean residual (consolidate large holes) smoothly
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild penalty on many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize slightly unless residual waste would be severe
    if bin_residual == bin_capacity {
        let waste_if_reuse = mean_residual - item_size as f64;
        score = cap + 0.5 * open_bins_count as f64;
        if waste_if_reuse > 0.0 {
            score -= 8.0 * (waste_if_reuse / cap).min(1.0);
        }
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Harmonic class of post_residual modulo 10: dead space in classes
    // {0,1,2} is least reusable (min item size 1..10 buckets), penalize others gently.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 6.0; // perfect fill class
    } else if cls <= 2 {
        score += 1.5; // near-perfect, small dead space
    } else if cls >= 8 {
        score += 4.0; // large-ish dead space class
    }

    // Integer-division threshold: post_residual buckets of 20.
    let bucket = post_residual / 20;
    score += bucket as f64 * 2.0;

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack <= 10 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or no open bin fits well (post_residual would be big).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 25.0;
        let mut penalty = 18.0;
        if poor_fit { penalty -= 6.0; }
        if item_size >= 60 { penalty += 8.0; } // big items prefer a fresh bin
        if next_item_size > 0 && next_item_size <= post_residual && post_residual < bin_capacity {
            penalty += 15.0; // existing bin serves next item too; don't open new
        }
        penalty *= 0.5 + 0.5 * (1.0 - progress);
        score += penalty;
    }

    // Mild preference for filling already-open bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Coupling with mean residual: if this bin is below mean residual (tighter),
    // it is more precious; reward placing here.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Strict dead space avoidance: post_residual that is too small to ever
    // hold a plausible item (min size 1, but small gaps below next_item_size
    // are likely dead) is heavily penalized.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }
    // Unusable micro-gap: below the smallest plausible item size.
    if post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus: no waste at all.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure, minus lookahead potential.
        score += 40.0 + pressure;
        if next_item_size > 0 {
            score -= (bin_capacity.saturating_sub(next_item_size)) as f64 * 0.2;
        }
    } else {
        // Fitting an existing bin reduces pressure slightly.
        score -= pressure * 0.1;
    }

    // Slight preference for bins with residuals below the mean (consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item still fits comfortably with small waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: this bin becomes dead space for the lookahead
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize placing into bins with residual far from the mean (keeps bin pool balanced)
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Prefer filling already-open bins as the stream progresses (reduce bin count)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    } else {
        // New empty bin candidate: mild penalty unless nothing else looks good
        score += 3.0;
    }

    // Small bonus for closing out bins that become nearly full
    if post_residual < 10 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that no plausible small item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: bonus if next item fits exactly into post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: many open bins -> prefer filling existing ones.
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Divergence from mean residual: prefer bins whose residual is near mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in stream, be more conservative (avoid fragmentation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets baseline cost that shrinks when
    // existing fits are poor (large post residual) but grows late in the stream.
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (bigger leftover = lower score = preferred)
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep in [0,1]
    score -= 12.0 * poly * norm_pr * norm_pr * cap * 0.1;
    score += 8.0 * (1.0 - poly) * norm_pr * norm_pr * cap * 0.1;

    // Penalize residuals that nothing reasonable fits into later
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.35 * gap * (1.0 + poly);
        if next_item_size as f64 <= pr {
            score -= 6.0 * (1.0 - gap / cap) * (1.0 - poly);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + poly);
    }

    // Mildly discourage spreading across many open bins
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins deviating smoothly (quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Perfect-fit quadratic reward
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + poly);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: how well the leftover decomposes
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Dead-space penalty: residuals that few item sizes can use
    // Items are 1..100; a residual r is usable by items of size <= r.
    // Penalize residuals in "hard" bands: just above common item sizes.
    let dead = if pr > 0 && pr < 20 { 40.0 } else if pr > 50 && pr < 60 { 10.0 } else { 0.0 };
    score += dead;

    // Modulo-class logic: residuals that are multiples of 10 (or 25) are
    // more reusable under typical discrete size streams.
    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily (perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after pairing
            let pr2 = post_residual - next_item_size;
            score -= 30.0 + (pr2 as f64).min(50.0) * 0.5;
            if pr2 % 10 == 0 { score -= 8.0; }
        } else {
            // next item won't fit here: penalize if gap is small (wasted near-fit)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when current fit is poor or mean residual is low.
    if bin_residual == bin_capacity {
        // base score for a fresh bin = post_residual (100). Calibrate against
        // typical open-bin scores: prefer new bin when mean residual is small
        // or item is large relative to mean residual.
        let pressure = (item_size as f64) / mean_residual.max(1.0);
        score -= 25.0 + pressure * 30.0 + (open_bins_count as f64) * 2.0;
        // late in stream, prefer closing out open bins rather than spawning
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        score += progress * 20.0;
    }

    // Mild preference to fill bins with low residual among open bins
    score -= (bin_residual as f64) * 0.05;

    // Fractional coupling: prefer post_residual near small capacity fractions
    if (frac - 0.1).abs() < 0.05 || (frac - 0.2).abs() < 0.05 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a leftover gap that no future item can use
    // (smaller than the known next item and smaller than a typical small item)
    // is heavily penalized.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 35.0;
        }
        if post_residual < 10 {
            score += 45.0;
        } else if post_residual < 20 {
            score += 15.0;
        }
    } else {
        // Perfect fill is maximally rewarded.
        score -= 50.0;
    }

    // Reward bins whose residual still accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: expensive, especially when many bins are open.
        score += 70.0 + 6.0 * open_bins_count as f64;
    } else {
        score -= 4.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting open bin, strongly favor it
    // to avoid opening a new bin (only applies to non-fresh bins).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild tie-break toward bins with tighter residuals relative to the mean.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late-stream tightening: as the stream progresses, be slightly more
    // conservative about wasting space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and the next item size (perfect chain placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying quadratically as mismatch grows.
        let match_reward = 12.0 / (1.0 + diff * diff * 0.05);
        score -= match_reward;

        // If next item fits exactly into the residual left behind, big bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild bonus proportional to tightness.
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        }

        // Penalize leaving a residual that is too small for the next item
        // (dead space relative to lookahead).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean
    // (tighter bins get filled first), penalize above-mean residuals.
    let resid_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = resid_f / mean_residual;
        if rel > 1.0 {
            score += 3.0 * (rel - 1.0);
        } else {
            score -= 2.0 * (1.0 - rel);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin unless the item fits poorly everywhere
    // (new bin has residual == capacity, post_residual == capacity - item_size).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: grows slightly with open bin count pressure.
        score += 8.0 + 0.1 * open_bins_count as f64;
        // If item is large, a fresh bin is more acceptable (item occupies most of it).
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
        // If next item is small and could share with current item in fresh bin, encourage.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Slight time decay: early in stream, be a bit more conservative with spread.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits: waste ratio penalty
    let fit_ratio = post / capacity;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space too small for typical future items
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose residual can also host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / capacity);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when fits are bad
    if bin_residual == bin_capacity {
        score = capacity * 0.55 + 15.0 * fit_ratio - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // discourage hoarding bins early
        score += open_bins_count as f64 * 0.8;
    }

    // Mild pressure toward consolidating into emptier bins when many are open
    score += 0.15 * (mean_residual - post).max(0.0);

    // Late-stream: prefer filling existing bins tighter
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early: prefer tight fits strongly; Late: tolerate larger residuals slightly.
    let tightness = (pr / cap).powf(2.0 + 2.0 * progress);
    score -= tightness * (30.0 - 10.0 * progress);

    // Cubic dead-space penalty for residuals too small for likely future items.
    let dead = if pr > 0.0 && (next_item_size as f64) > pr {
        (pr / cap).powi(3) * 25.0
    } else {
        0.0
    };
    score += dead;

    // Smooth reward when the next item exactly complements the post-residual.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (-gap / 15.0).exp() * 12.0;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress).max(0.05);
    }

    // Mild pull toward bins near the mean residual (smooth quadratic attraction).
    score += ((pr - mean_residual) / cap).powi(2) * 6.0;

    // Slight preference for fewer open bins early on (smooth in progress).
    score += (open_bins_count as f64).ln().max(0.0) * (8.0 * (1.0 - progress));

    // New-bin candidate: penalize mildly so it wins only for poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (cap * 0.25) as u32;
    let half = (cap * 0.5) as u32;
    let three_quarter = (cap * 0.75) as u32;

    // Perfect-fit reward: residual is an exact harmonic class multiple.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo-style harmonic bands: reward residuals that future items (10..80)
    // can still usefully fill; penalize awkward dead zones.
    if post_residual > 0 && post_residual <= quarter {
        // small dead space, mildly bad unless near zero
        score += 8.0;
    } else if post_residual <= half {
        score -= 6.0;
    } else if post_residual <= three_quarter {
        score -= 12.0;
    } else {
        score -= 4.0;
    }

    // Integer-division threshold: can next item fit exactly into post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chained perfect fit
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            score -= (30.0 - waste.min(30) as f64) * 0.5;
        } else {
            // next item cannot fit here; residual becomes dead until later
            score += 10.0;
        }
    } else {
        // last item: only perfect fit matters
        if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: keep it slightly worse than a decent fit,
    // but better than dumping into a bin with large unusable remainder.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // next item pairs well in the fresh bin
        }
    }

    // Harmonic modulo bonus: residual divisible into common item sizes.
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // "Almost dead" gap: usable only by tiny items; graded penalty.
        score += 35.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure to keep it from
        // winning unless the alternative is a bad fit.
        score += 30.0 + 5.0 * pressure;
        // If lookahead fits a typical residual after this placement,
        // opening a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual.max(bin_residual) {
            score -= 8.0;
        }
    } else {
        // Existing bin gets a mild discount that grows with open-bin count.
        score -= 2.0 * pressure.min(6.0);
    }

    // Prefer bins whose residual is near the mean (keeps residuals uniform,
    // improving future combinability), unless it is the new-bin candidate.
    if bin_residual != bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // Lookahead: if the next item exactly matches the post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this gap; slight penalty proportional to gap.
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: residual zero is ideal.
    if post_residual == 0 {
