            let tightness = (post_residual - next_item_size) as f64;
            score -= 200.0 - tightness * 0.5;
        } else {
            // next item does NOT fit into leftover: penalize wasted dead space
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        }
    }

    // Penalize large post residual relative to mean residual (fragmentation).
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap > 0.0 {
        score += mean_gap * 0.3;
    } else {
        score += mean_gap * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, waived for large items with poor fits.
        let poor_fit = (post_residual as f64) > 40.0;
        if poor_fit {
            score -= 50.0;
        } else {
            score += 120.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 60.0;
    }

    // Slight preference for bins with less residual before placement (denser bins).
    score += (bin_residual as f64) * 0.05;

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a nonlinear bonus.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
        } else {
            // next item won't fit here; slight penalty proportional to wasted gap
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when good alternatives exist,
    // but allow it when the current item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress;
        if item_size > 50 && mean_residual < item_size as f64 {
            score -= 12.0; // fragmentation: fresh bin is attractive
        }
    }

    // Global state coupling: prefer filling bins when many are open with high mean residual.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 0.5 * norm_pr * pr * progress;

    // Reward tight fits: quadratic bonus shrinking post_residual
    score -= (cap - pr) / cap * (1.0 - norm_pr) * 20.0 * (1.0 - progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * 1.5;
        } else {
            score -= 0.5 * (pr - nxt).min(30.0) as f64;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize slightly unless open bins are fragmented
    if bin_residual == bin_capacity {
        score = 60.0 + progress * 20.0
            - if mean_residual > 0.0 && open_bins_count > 0 { mean_residual.min(50.0) } else { 0.0 };
    }

    // Mild penalty for contributing to fragmentation relative to mean residual
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes (mod 10) are nearly dead space -> penalize.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // tiny leftovers (1..=9) are wasted capacity unless exactly reusable
        if class <= 3 && pr <= 9 {
            score += 12.0; // dead space penalty
        } else if class == 0 {
            score -= 8.0; // round residuals (10,20,...) are highly reusable
        }
    }

    // Perfect fit reward via integer division thresholds
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 10 {
        score -= 15.0; // near-perfect fit
    }

    // Coupling with next item: does the leftover fit the lookahead?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // how well does next item divide the residual? harmonic match
            let q = pr / next_item_size.max(1);
            let r = pr % next_item_size.max(1);
            if r == 0 {
                score -= 20.0 + (q as f64) * 2.0; // exact division: chain fits
            } else {
                score -= 6.0 + (next_item_size as f64) * 0.15;
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // open bins have poor fits (harmonic fraction of capacity used)
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 || next_item_size == 0 {
            score -= 10.0;
        } else {
            score += 15.0 + 10.0 * (1.0 - frac);
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer tighter bins overall (below mean residual)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with non-linear dead-space penalty.
    // Gaps that are "unusable" (small, below typical minimum item size) are punished hard.
    let dead_zone = 10.0; // smallest item size threshold
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        // Perfect fill is great; tiny sliver is dead space.
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Tight-fit reward: exponential preference for small positive residuals.
    score -= 40.0 * (-post_residual as f64 / 25.0).exp();

    // Penalize leaving a gap that exactly wastes capacity relative to mean residual:
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // next item cannot use the leftover; leftover becomes dead space
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Early stream: be slightly more willing to open bins to build a good portfolio.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * (item_size as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: perfect if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item does NOT fit in this bin's leftover: penalize wasted space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Penalize dead space that is too small to ever be useful (min item size 1, but
    // relative to mean residual: leftovers far below mean are hard to reuse).
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: keep it attractive only when current bins would leave
    // large unusable leftovers; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 10.0;
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
        // if next item is large and current best fits are poor, new bin is fine
        if next_item_size > 60 {
            score -= 3.0;
        }
    }

    // Slight preference for bins with larger residuals when many bins are open
    // (consolidation pressure).
    score -= 0.02 * (bin_residual as f64) / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize exact fills less
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // next item can't use this residual; penalize proportionally
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasteful
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Time horizon: early in stream, be picky (penalize mediocre fits); later, pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.3 * progress;

    // Opening a new bin: mild penalty so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        // but early on with few bins, new bins are cheap
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly;

    // Penalize tight fits less as stream progresses (prefer filling bins late)
    let tightness = 1.0 - norm_pr;
    score -= (1.0 - progress) * tightness * 8.0;

    // Reward leaving room for the lookahead item when it fits
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - ((pr - nxt) / cap)) * (1.0 - progress);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open and this one is nearly empty (fragmentation)
    let mean_dev = (mean_residual - pr).abs() / cap;
    score += 3.0 * mean_dev * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is terrible
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins grouped by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: residuals that are too small to be useful are costly.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more reusable — reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: reward tight harmonic match
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 35.0;
            } else if gap <= 10 {
                score -= 18.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize proportional to wasted lookahead
            score += 4.0 + (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Integer-division thresholds on item_size vs residual: near-perfect fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 20.0;
    } else if fill_ratio > 0.7 {
        score -= 10.0;
    } else if fill_ratio < 0.3 {
        score += 6.0; // leaving a big bin mostly empty is wasteful
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only open a new bin when existing residuals are
    // too fragmented (mean residual low relative to item) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // prefer new bin if no open bin has enough room or mean residual is small
        if bin_residual >= item_size {
            let desperate = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
            let threshold = 0.35 + 0.3 * (1.0 - fragmentation);
            if fragmentation < threshold && desperate > 0.0 {
                score += 45.0; // discourage opening when open bins are usable
            } else {
                score -= 5.0 - 10.0 * progress; // early stream: opening is cheap
            }
        }
        // small residual-capacity bins elsewhere make new bin attractive
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate into fewer bins.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Slight preference for tighter residual overall (harmonic scaling).
    score -= 12.0 * (1.0 - frac) * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= 10 {
        score -= 8.0;
    } else if post_residual > 0 {
        // dead space that can never be used again
        score += 25.0;
    }

    // Coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(20.0);
    }

    // Open-bin pressure: discourage scattering items when many bins are open.
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 1.5;
        let waste = (bin_capacity - item_size) as f64;
        // Base cost of opening a new bin, offset if current bins are fragmented.
        score = 45.0 + pressure - mean_residual * 0.3 + waste * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0;
        }
    }

    // Mild progression term: early stream, be conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

