    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / 100.0);
        // Perfect chain: item + next item exactly fills the bin.
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        }
        // Also reward the case where the NEXT item fits exactly after this one,
        // i.e. bin_residual == item + next (pre-placement perfect pairing).
        if bin_residual == item_size + next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a residual that is too small for the next item (dead space risk).
        if post_residual > 0 && next_item_size > post_residual {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins that become tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we only open when existing fits are bad,
    // scaled by how full the stream already is (early on, opening bins is cheap).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 25.0 * progress;
    }

    // Mild penalty for fragmenting a large residual when few bins are open.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

