    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Cheaper to open a bin early in the stream (more future to amortize).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If existing bins fit tightly (low mean residual relative to item), opening is more attractive.
        let waste = mean_residual - item_size as f64;
        if waste > 20.0 {
            score -= 10.0;
        }
        // If no open bin fits (this call is the only option), fitting_bins_count reflects only the new bin.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Prefer bins with smaller residual before placement (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    // Mild pressure to consolidate: fewer open bins -> slightly favor placing anywhere over opening.
    score += (open_bins_count as f64) * 0.1;

    // Align with mean residual: bins near the mean are "typical"; slight preference to drain outliers.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: reward small residuals, more so as stream progresses
    let quad = norm_pr * norm_pr;
    score -= 40.0 * (1.0 - quad) * (0.5 + 0.5 * progress);

    // Perfect-fit bonus with cubic shaping
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: reward if next item fits post-residual, penalize near-miss
    if next_item_size > 0 {
        let fits = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / cap;
        score -= 15.0 * fits * (1.0 - gap * gap);
        score += 10.0 * (1.0 - fits) * (1.0 - gap);
    }

    // Last-chance pressure: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Penalize deviating from mean residual (keep bin pool homogeneous)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // Mild preference to fill existing bins over opening new ones
    score += 8.0 * (bin_residual == bin_capacity) as i32 as f64 * (1.0 - 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "clean"
    // fractions of capacity are more reusable.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual % (bin_capacity / 4)).max(1) as f64;
    // Penalize residuals that are neither zero nor in the reusable band.
    if post_residual > 0 {
        score += class * 0.15;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small dead space (below smallest possible item) is a perfect fit equivalent.
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    score -= (item_size as f64) * 0.1;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (next_item_size == post_residual) as i32 as f64;
        score -= 20.0 + 10.0 * exact;
        // Harmonic coupling: next item's class matches post residual class.
        if next_item_size % (bin_capacity / 4) == post_residual % (bin_capacity / 4) {
            score -= 8.0;
        }
    }
    // Penalize if next item cannot use the post residual at all.
    if next_item_size > post_residual {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // among open bins (large mean residual spread or few fitting bins).
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        score = 60.0 - pressure * 30.0
            - (post_residual as f64 - mean_residual) * 0.05
            + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size > bin_residual / 2 {
            score += 5.0; // big next item: fresh bin less useful
        }
        return score;
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual < 20 {
        // Small gaps that only tiny items could use: moderate penalty.
        score += 25.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits: the smaller post_residual is relative to item_size, the better.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + tightness);

    // Perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // If no open bin fits at all, opening is unavoidable.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Open-bin pressure: when many bins are open, prefer using them
        // (consolidation) rather than spreading.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement
    // (chains two items nicely); if next item would exactly fill it, extra reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else if next_item_size <= bin_residual && post_residual > 0 && post_residual < 10 {
            // This placement blocks the next item from a near-perfect fit; penalize.
            score += 10.0;
        }
    }

    // Mild preference for bins with residuals below the mean (use up fuller bins first).
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the next item can fit into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Extra reward for near-exact two-item packing
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize creating residual that just barely fails to fit next item
        let miss = (next_item_size - post_residual.min(next_item_size)) as f64;
        if miss <= 10.0 {
            score += 25.0 * (1.0 - miss / 10.0);
        }
    }

    // Reward tight fills relative to mean residual of open bins
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Progress-based caution: late in stream, prefer consolidating into open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Penalize leaving large dead space (post residual too small to ever be useful)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit bonus: fraction of bin used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Penalize small dead space that few items can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 150.0;
        } else if next_fit_gap <= 5 {
            score -= 60.0;
        } else {
            score -= 15.0;
        }
    }
    // If next item cannot fit here, mild penalty for wasting the slot
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are bad
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; discourage while many bins are open with slack
        score += 5.0;
        if open_bins_count > 0 {
            score += 20.0 * (open_bins_count as f64).ln().max(0.0);
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin always accommodates the next item
            score -= 10.0;
        }
    }

    // Global slack pressure: when mean residual is large, prefer filling existing bins harder
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Time horizon: late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * fill_frac;

    // Prefer bins with low residual among open bins (best-fit coupling)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual polynomial in stream progress
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize leaving space that the next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * 0.8 * (0.5 + progress);
        } else {
            score -= (pr - nxt).min(20.0) * 0.3;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, less late
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 3.0;
    }

    // Coupling with mean residual state
    score += (mean_residual - pr) * 0.15 * (0.5 + progress);

    // Small penalty for many open bins with large residuals
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // are "reusable" classes; odd/prime-ish residues are dead space.
    let cap = bin_capacity as f64;

    // Reward post-residuals that fall into harmonic classes (multiples of 5,10,20,25)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is gold
    } else {
        let mut class_bonus = 0.0;
        if pr % 10 == 0 { class_bonus += 8.0; }
        if pr % 20 == 0 { class_bonus += 6.0; }
        if pr % 25 == 0 { class_bonus += 5.0; }
        if pr % 5 == 0 { class_bonus += 3.0; }
        score -= class_bonus;

        // Penalize residues in dead zones: 1..=9 (too small for min item)
        if pr < 10 {
            score += 25.0;
        }
        // Integer division threshold: residue in [10,20) fits only tiny items
        if pr >= 10 && pr < 20 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // harmonic match: next item leaves residue again in a good class
            let nr = pr - next_item_size;
            if nr % 10 == 0 { score -= 12.0; }
            if nr % 5 == 0 { score -= 6.0; }
            if nr < 10 { score += 15.0; }
        } else {
            // next item cannot use this residue at all -> dead space likely
            score += 12.0;
        }
    }

    // Fractional fill of the bin: prefer tighter packing relative to capacity
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full or many bins open
    if bin_residual == bin_capacity {
        score += 45.0;
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= 55.0; // all open bins nearly exhausted -> open new bin
        }
        if open_bins_count > 12 {
            score -= 10.0;
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * fill;

    // Mean residual coupling: if this bin's residual far below mean, it's a good squeeze
    let res_gap = mean_residual - post_residual as f64;
    score -= res_gap.clamp(-50.0, 50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        // Residuals below the minimum item size are pure dead space.
        if post_residual < 10 {
            score += 40.0;
        } else {
            // Penalize gaps that cannot fit the lookahead item (k=2 lookahead).
            if next_item_size > 0 && post_residual < next_item_size {
                score += 12.0;
            }
            // Penalize gaps in the classic "unusable band" (small but nonzero),
            // scaled by how close the gap is to the minimum item size.
            let gap_ratio = post_residual as f64 / bin_capacity as f64;
            if gap_ratio < 0.25 {
                score += 25.0 * (0.25 - gap_ratio) * 4.0;
            }
        }
    } else {
        // Perfect fill is strongly rewarded.
        score -= 30.0;
    }

    // Reward tight fits: fill ratio of this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill;

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins rather than leaving scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (1.0 + post_residual as f64 / bin_capacity as f64) * (2.0 + 3.0 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Deviation from mean residual: prefer bins that are outliers (very full),
    // keeping near-empty bins available for future large items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if bin_residual < mean_residual {
        score -= 5.0 * dev / bin_capacity as f64;
    } else {
        score += 5.0 * dev / bin_capacity as f64;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., the best available residual is small relative to the item).
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 * 1.2;
        if decent_fit_exists && open_bins_count > 0 {
            score += 35.0; // discourage opening new bin when decent fits exist
        } else if open_bins_count > 0 {
            score += 8.0; // mild discouragement otherwise
        } else {
            score -= 50.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: good, but keep some slack preference
            score -= 50.0 - (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit: penalize wasted space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Prefer bins whose residual is near mean (avoid fragmenting outliers)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize choosing a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 {
            score += (bin_capacity as f64 - next_item_size as f64) * 0.2;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space that no plausible item (10..80 by design, but sizes 1..100 unknown) can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are waste
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            score += 3.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Deviation from mean residual: prefer bins either much fuller or matching mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in stream: be pickier about fragmentation; late: just close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.03 * post_residual as f64;

    // Discard new-bin candidate unless nothing decent fits.
    if bin_residual == bin_capacity {
        score += 40.0
            + 25.0 * (fitting_bins_count as f64 / (fitting_bins_count as f64 + 1.0))
            - 20.0 * progress;
        if item_size >= 50 {
            score -= 10.0; // large items may warrant a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr + 40.0 * pr_norm * pr_norm * (1.0 - progress);

    // Late in the stream, waste is more costly -> amplify post_residual penalty
    score += 30.0 * progress * pr_norm * pr_norm;

    // Perfect-fit reward: smooth coupling of post_residual to zero
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize leaving residuals that are too small to be useful later
    // (smooth trough around mid-range residuals)
    let usefulness = (pr_norm * (1.0 - pr_norm) * 4.0).clamp(0.0, 1.0);
    score -= 10.0 * usefulness;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading into new bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * pr_norm;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (consolidate fuller bins)
    score += 0.3 * (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10, 20, 25 create
    // "usable slot classes". Small nonzero residues are dead-space traps.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 {
            score -= 8.0; // perfectly aligned class, easily refillable
        } else if r % 5 == 0 {
            score -= 4.0;
        } else if r < 10 {
            score += 15.0; // tiny dead space, unusable for min-size items
        }
        if r % 20 == 0 && r >= 20 {
            score -= 3.0; // quarter-capacity harmonic class
        }
        if r % 25 == 0 && r >= 25 {
            score -= 3.0; // half-quarter harmonic class
        }
    }

    // Exact fit is ideal.
    if r == 0 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0; // perfect chain
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use leftover: mild penalty scaled by waste
            score += 0.05 * (next_item_size - r) as f64;
        }
    } else {
        // last item: prefer closing bins completely
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: penalize opening new bins when the stream
    // is early or many bins are open; encourage late in stream or when
    // open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * progress;
        if mean_residual > item_size as f64 + next_item_size as f64 {
            score += 12.0; // open bins have room for the future too
        }
    } else {
        // prefer bins tighter than the mean residual (best-fit tendency)
        score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Prefer filling already-open bins when many are open (bin count pressure).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..=10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 4.0 * post_residual as f64;
    }
    // Mid-range gaps (11..=25) are only usable by small items; mild penalty.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // If the lookahead item fits exactly into the post residual, this
    // placement chains perfectly: strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Lookahead fits inside remaining gap; slight bonus proportional
        // to how snugly it nests.
        score -= 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Lookahead cannot use the gap: dead space likely, penalty scaled
        // by gap size (bigger wasted gap = worse).
        score += 0.3 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize proportionally to open count.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make
    // it attractive only when existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with the number already open.
        score += 30.0 + 1.5 * open_bins_count as f64;
        // If current bin's fit would leave a small unusable gap, new bin
        // becomes relatively more attractive (score already penalized).
        if post_residual <= 10 {
            score -= 55.0;
        }
    }

    // Tight-fit reward: fraction of bin used by this placement.
    score -= 0.4 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Late in the stream, consolidate aggressively to close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Slight nudge toward bins below mean residual (balance spreading).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly no dead space is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or closely) matches the next item's size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) == next {
            score -= 500.0; // exact 2-step chain: ideal
        } else if post_residual >= next_item_size {
            let diff = post_residual as f64 - next;
            score -= 200.0 * (-diff / 20.0).exp(); // smooth closeness bonus
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = next - post_residual as f64;
            score += 50.0 + 2.0 * gap;
        }
    }

    // Penalize bins that deviate strongly from the mean residual
    // (keep residual landscape homogeneous for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when the item fits
    // poorly in all open bins (large post_residual would be wasted anyway)
    // or the stream is early and building fresh capacity is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_penalty = if post_residual > 40 { 0.0 } else { 80.0 };
        score += waste_penalty + 100.0 * progress + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fraction of capacity wasted after placement; penalize quadratically.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            let gap = post_residual as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is used only when existing bins score poorly.
        score += 150.0;
        // As stream progresses, opening bins early is cheaper (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 120.0 * (1.0 - progress);
        // If many open bins already, discourage more bins.
        score += 5.0 * open_bins_count as f64;
        // If mean residual across open bins is small, a new bin is more useful.
        score -= mean_residual * 0.5;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 {
            score -= 0.3 * next_item_size as f64;
        }
    } else {
        // Prefer placing into bins with smaller residual (tighter bins first),
        // scaled by how much of the bin is already used.
        let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 25.0 * used_frac;
        // Penalize placing large items into nearly-full bins when other bins exist.
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Global pressure: when few bins fit the item, tighten selection.
    if fitting_bins_count > 0 {
        score += 10.0 / fitting_bins_count as f64;
    }

    // Mild time-horizon term: early in stream, be conservative with tight fits
    // (save small-residual bins for later small items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post residual (lower = tighter fit preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, tight fits matter more; dead space is penalized super-linearly.
    let norm_pr = pr / cap; // 0..1
    let tightness_weight = 1.0 + 2.0 * progress; // grows over stream
    score += tightness_weight * norm_pr * norm_pr * cap * 0.5;

    // Dead-space penalty: post_residual too small to fit the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            // unusable gap for lookahead: penalize proportionally to how close it is to being useful
            let waste_frac = (ns - pr) / ns;
            score += 8.0 * waste_frac * (1.0 + progress);
        } else {
            // reward leaving a gap that exactly accommodates the next item
            let fit_quality = 1.0 - ((pr - ns) / cap).abs();
            score -= 3.0 * fit_quality.max(0.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate handling: prefer opening a new bin only when item barely fits
    // existing bins or open bins are already tight on average.
    if bin_residual == bin_capacity {
        // opening a new bin: base cost, discounted early in stream
        score += 5.0 - 3.0 * progress;
        if fitting_bins_count > 0 {
            let avg_res = if open_bins_count > 0 { mean_residual } else { 0.0 };
            // if open bins have plenty of room, discourage new bin
            score += 4.0 * (avg_res / cap);
            // discourage new bin if item fits comfortably somewhere (post_residual would be small there)
            if pr > item_size as f64 {
                score += 2.0;
            }
        }
    } else {
        // existing bin: reward filling bins that are already mostly full
        let fill = 1.0 - (bin_residual as f64 / cap);
        score -= 2.0 * fill * fill;
    }

    // Smooth coupling with mean residual: spreading load evenly is mildly favored
    let res_gap = (pr - mean_residual) / cap;
    score += 1.5 * res_gap * res_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic buckets: residual in (C/2, C] is "half-class", (C/3, C/2] "third-class", etc.
    // Small residuals (dead space) get penalized super-linearly.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if post_residual <= bin_capacity / 10 {
        // tiny leftover: near-dead space
        score -= 25.0;
    } else {
        // harmonic index: which 1/k fraction of capacity does post_residual fall into
        let k = (cap / post).max(1.0);
        // reward residuals that are "harmonic" (close to 1/k of capacity for small k)
        let nearest = (1.0 / k.round().max(1.0)) * cap;
        let harmonic_bonus = 8.0 * (1.0 - (post - nearest).abs() / cap);
        score -= harmonic_bonus;
        // penalize dead space quadratically for residuals below C/3
        if post < cap / 3.0 {
            score += (cap / 3.0 - post) * (cap / 3.0 - post) / cap;
        }
    }

    // Modulo arithmetic on post_residual: multiples of common item-size classes (10,20,25,50)
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0; // residual aligned with decimal classes, more reusable
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // reward small slack after hypothetical next placement (harmonic chain)
            score -= 6.0 * (1.0 - slack as f64 / cap);
            if slack % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to how much it misses
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it's chosen
    // only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        // late in stream, prefer closing out open bins rather than opening new ones
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if many bins are open, discourage another
        score += open_bins_count as f64 * 0.5;
    } else {
        // favor bins whose residual is close to item size (tight fit)
        let tight = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 5.0 * tight;
    }

    // Prefer bins below mean residual (fill the emptiest usable bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: best possible outcome, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space avoidance: small leftover gaps are nearly unusable.
    let pr = post_residual as f64;
    if pr <= 10.0 {
        // gap too small for any item (min size 1.., but treat tiny gaps as waste)
        score += 300.0 * (1.0 - pr / 10.0);
    } else if pr <= 30.0 {
        // risky medium gap: penalize proportionally, unless next item fits it
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            score += 120.0 * (1.0 - (pr - 10.0) / 20.0);
        } else {
            score -= 40.0; // lookahead item plugs the gap
        }
    } else if pr <= 60.0 {
        score += 20.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 50.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when item is large or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize opening new bins generally, less so if existing residuals are fragmented
        score += 250.0 - 300.0 * fragmentation - 100.0 * (1.0 - progress);
        if item_size >= 70 {
            score -= 80.0; // big items start fresh bins more willingly
        }
    }

    // Open-bins pressure: mildly discourage adding load when many bins are open,
    // encouraging consolidation into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * 8.0;

    // Prefer bins whose residual is below the mean (fill the fullest bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to smallest possible item (1..100 unknown, use 10 as floor guess)
        let min_item = 10.0f64;
        if (post_residual as f64) < min_item {
            score -= 500.0; // tiny unusable sliver, effectively a perfect fit
        } else {
            score += (post_residual as f64) * (post_residual as f64) * 0.01;
        }
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0; // chain fit: next item fills this bin exactly
        } else if post_residual > next_item_size {
            score -= 50.0; // next item still fits after this one
        } else {
            // next item won't fit here; penalize proportionally to the gap
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
        // Extra reward if chaining yields a near-perfect residual
        let chain_residual = post_residual as f64 - next_item_size as f64;
        if chain_residual > 0.0 && chain_residual < 10.0 {
            score -= 100.0;
        }
    }

    // Mean-residual coupling: prefer bins whose post state aligns with the fleet average
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity and no good open bin exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.8 {
            score -= 150.0; // big item in fresh bin is fine
        } else {
            score += 400.0; // discourage wasting a fresh bin on small items
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Mild pressure to reduce number of open bins
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that is too small to be useful for typical items,
    // with a non-linear (quadratic-ish) ramp on small positive residuals.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead_penalty = if pr < 10.0 {
            (10.0 - pr) * (10.0 - pr) * 0.5
        } else {
            0.0
        };
        score += dead_penalty;
    }

    // Lookahead (k=2): if the next item cannot fit in the post residual,
    // this placement may force a new bin next step. Penalize proportionally
    // to how "close" the next item is to fitting.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 2.0;
            // Extra penalty if this is the only fitting bin (last chance):
            // wasting its residual on a non-exact fit is costly.
            if fitting_bins_count == 1 {
                score += gap * 3.0;
            }
        } else {
            // Reward placements that leave room for the lookahead item.
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time-horizon coupling: early in the stream, be conservative and keep
    // bins flexible; later, be greedier about tight fits.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= progress * 10.0;

    // Global state: when many bins are open with high mean residual,
    // slightly favor filling existing bins rather than opening new ones.
    score -= (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate handling: brand-new empty bin has bin_residual == bin_capacity.
    // Its raw post_residual (100 - item_size) is usually large, but add an explicit
    // opening cost that shrinks as the stream progresses (late stream: consolidate).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        // But if no open bin fits well (post_residual of this bin is small means
        // item is large), opening may be fine: soften cost when item is big.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with less residual before placement (tighter bins first),
    // keeping diversity across bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, scaled non-linearly.
    let mut score = pr * (1.0 + 0.6 * pr / cap);

    // Smooth polynomial coupling: large residuals matter more late in the stream.
    let prn = pr / cap;
    score += 12.0 * prn.powi(3) * (0.5 + progress);
    score -= 8.0 * prn * (1.0 - prn) * (1.0 - progress);

    // Penalize residuals that no typical item could reuse (dead space), smoothly.
    let dead = (pr - next_item_size as f64).max(0.0) / cap;
    score += 15.0 * dead * dead;

    // Reward tight fits (small post residual relative to item size).
    let tight = item_size as f64 / (item_size as f64 + pr).max(1.0);
    score -= 10.0 * tight * tight;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * prn;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / pr.max(1.0));
    }

    // New-bin candidate: neutral-ish baseline with slight late-stream penalty
    // so we only open new bins when existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score = cap * (1.1 + 0.5 * progress) - 20.0 * (1.0 - prn);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: exactness is precious.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward residuals that are harmonic fractions of capacity (0, 12.5%, 25%, 50%).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual == quarter {
        score -= 12.0;
    } else if post_residual == eighth || post_residual * 2 == bin_capacity {
        score -= 8.0;
    } else if post_residual < eighth {
        // tiny dead space: nearly a perfect fit, but wasted
        score -= 25.0;
    }

    // Penalize residuals in awkward mid-range classes (dead space that fits nothing typical).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: prefer tightening existing ones (waste-aware).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins tighter than average (good fill).
    score -= 0.3 * (mean_residual - pr);

    // New-bin candidate: only attractive when residual is huge and nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0; // default penalty for opening a bin
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        if post_residual as f64 > 0.6 * cap {
            score -= 20.0;
        }
    }

    // Penalize leaving large-but-unusable residual (between half and full minus small item).
    if post_residual > bin_capacity / 2 && post_residual < item_size.max(next_item_size) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 40.0;
    } else {
        // Larger gaps: mild reward proportional to residual, but scaled so
        // big leftover space is not over-favored (waste indicator).
        score -= 5.0 + 0.05 * (post_residual as f64);
        if post_residual > 60 {
            score += 10.0; // wasteful placement, nearly-empty bin used
        }
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Last-chance bin: strongly favor filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // next item can't use this gap; dead space likely
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins first, keeping loose bins flexible).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // next fits, tighter is better
        } else {
            // next item cannot fit here: penalize proportionally to wasted lookahead
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Reward tight fits of current item (low post residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Penalize creating dead space below minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: prefer bins with residual above mean (keep small bins for small items).
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Late in stream: consolidation matters more, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 + 25.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty per open bin pressure to encourage filling existing bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Prefer filling bins when many bins are already open (bin count pressure).
    score -= 2.0 * open_bins_count as f64 * (1.0 - tight);

    // Deviation from mean residual: prefer bins whose residual is below average (denser bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more willing to open new bins (spread);
    // late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress) * tight - 20.0 * progress * (1.0 - tight);

    // New-bin candidate: make it attractive only when the item fits poorly everywhere
    // (large item or high mean residual). Otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 30.0 - 40.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize leftover space, but with non-linear (quadratic) coupling
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Smooth progress coupling: late in stream, tighter packing matters more
    let late = progress * progress;
    score += 30.0 * late * pr_norm * cap;

    // Lookahead coupling: reward residuals that leave room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = pr >= nx;
        let gap = ((pr - nx) / cap).abs();
        if fit_next {
            // smooth reward decaying with distance to a perfect next-item fit
            score -= 25.0 * (1.0 - gap) * (1.0 - late * 0.5);
        } else {
            // penalize residuals that block the next item proportionally to overshoot
            score += 15.0 * gap * (1.0 + late);
        }
    }

    // Mean residual interaction: placing into a bin far from the mean residual
    // creates heterogeneity; mildly penalize, more so early in the stream.
    let dev = (pr - mean_residual).abs() / cap;
    score += 12.0 * dev * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 15.0 * late;
    }

    // Many open bins: prefer filling existing ones rather than scattering
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm) * 5.0;

    // New-bin candidate: penalize so it only wins when residuals are hopeless
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - late) + 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64) * 0.8;
    }

    // Harmonic class: post_residual divisible into useful chunks is less "dead".
    if post_residual > 0 {
        // Perfect harmony: next item exactly fills the bin.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Next item fits here: mild reward, scaled by how much still remains.
            let rem = post_residual - next_item_size;
            score -= 20.0 - (rem as f64) * 0.15;
        } else {
            // Next item cannot use this residual: penalize large dead space.
            score += (post_residual as f64) * 0.25;
        }
        // Modulo classes: residual leaving room for common small sizes is fine.
        let m = post_residual % 10;
        if m == 0 {
            score -= 4.0;
        } else if m >= 5 {
            score += m as f64 * 0.3;
        }
    } else {
        // Perfect closure of a bin.
        score -= 80.0;
    }

    // Integer-division thresholds on post_residual.
    let q = post_residual / 20;
    score += match q {
        0 => -5.0,          // residual < 20: nearly full, great
        1 => 0.0,           // 20..39: ok
        2 => 2.0,           // 40..59: mediocre
        3 => 5.0,           // 60..79: poor use
        _ => 8.0,           // 80+: wasteful placement
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when residuals are all tight or few bins open.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        // Penalize opening new bins early / when open bins still have room.
        score += 30.0 + progress * 10.0;
        if avg_tightness < 0.25 && open_bins_count > 0 {
            score += 40.0;
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        // If the next item is large, a fresh bin is a safe bet.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild preference to spread across bins when many are open and mean residual is high.
    if open_bins_count > 2 && mean_residual > (post_residual as f64) {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // for future items (items >= 1, but realistically small gaps waste bins).
    let dead_zone: u32 = 9; // gaps <= 9 are dead space for items 10..80 streams
    if post_residual > 0 && post_residual <= dead_zone {
        score += 40.0 + (dead_zone - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits (post_residual small relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 15.0;

    // Penalize leaving a gap that the next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
    }
    // Reward if next item fits exactly into the post residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but relax pressure when few bins are open (early stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // leaves other bins with large residuals; slight penalty to balance.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate handling: an empty bin has large post_residual, so
    // it naturally scores high (bad) unless open bins are very fragmented.
    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 4.0;
        // allow new bin if item is large and residuals are small
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward when next item exactly matches the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // next item fits perfectly here -> strong reward
            score -= (100.0 - gap) * 0.9;
            if gap == 0.0 {
                score -= 120.0; // perfect chain bonus
            }
        } else {
            // next item cannot fit here; penalize large dead space
            score += gap * 0.25;
        }
        // reward when post_residual sits near mean residual (keeps bins balanced)
        score += (post_residual as f64 - mean_residual).abs() * 0.15;
    }

    // Last-chance bin: avoid wasting the only fitting bin on a sloppy fit
    if fitting_bins_count == 1 {
        if post_residual <= 10 {
            score -= 40.0; // tight fit on last chance is good
        } else {
            score += post_residual as f64 * 0.5; // penalize wasting it
        }
    }

    // New-bin candidate handling: empty bin should only win when fit is bad elsewhere
    if bin_residual == bin_capacity {
        // neutral-ish score: slightly worse than a perfect fit, better than huge waste
        score = 55.0 + next_item_size as f64 * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // if next item also fits in fresh bin, opening is more attractive
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good alternative -> open new bin
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize creating dead space that likely nothing can fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are hard to reuse
    }
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            score += 4.0; // kills future fit in this bin
        }
        // If bin can take both current and next item exactly, big bonus.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: only attractive when current fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0; // base cost of opening a new bin
        if fitting_bins_count <= 1 {
            score -= 22.0; // opening is fine when no good alternative exists
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host a pair
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress; // late in stream, consolidation matters less
    }

    // Global state: many open bins -> prefer filling existing ones harder.
    if open_bins_count > 4 {
        score -= 0.8 * open_bins_count as f64;
    }

    // Mean residual coupling: if this bin is above average residual, favor it.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on leftover space (dead space is bad).
    let mut score = norm_post * norm_post * cap;

    // Smooth cubic coupling with stream progress: later in the stream,
    // leftover space becomes increasingly costly.
    score += norm_post.powi(3) * cap * (0.5 + progress);

    // Reward tight fits: subtract proportional to how much of the bin was filled.
    let fill = item_size as f64 / cap;
    score -= fill * fill * cap * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    }

    // Penalize bins with residuals far from the mean (fragmentation avoidance),
    // smoothly via squared deviation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (1.0 - slack) * cap * 0.5;
    } else if next_item_size > post_residual {
        // Post-residual too small for next item: penalize dead space smoothly.
        let waste = next_item_size as f64 / cap;
        score += waste * post * 0.4;
    }

    // Mild penalty on opening a new empty bin when other bins fit,
    // growing with stream progress (consolidate late).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += cap * (0.3 + 0.7 * progress);
    }

    // Slight preference for using fewer bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which quarter of the bin it falls in.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;

    // Penalize dead space classes: residuals in (0,10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Reward exact/near-exact fills (residual 0 or tiny).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Class-based bonuses via integer division thresholds.
    if post_residual >= half {
        // Bin still very usable: strong reward.
        score -= 25.0;
    } else if post_residual >= third {
        // Mid class: mild reward.
        score -= 8.0;
    } else if post_residual >= quarter {
        // Low class: neutral to slight penalty.
        score += 6.0;
    }

    // Coupling with next item lookahead: if the next item fits the post
    // residual exactly-ish, big reward (chained placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Harmonic decay of reward with slack.
            score -= 30.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit here; penalize small post residuals that
            // become dead space relative to the lookahead.
            let over = (next_item_size - post_residual) as f64;
            if post_residual > 0 && over < 15.0 {
                score += 20.0 * (1.0 - over / 15.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bin attractive only when the
    // item fits poorly everywhere else or open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by stream progress and
        // fragmentation of open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = cap - (item_size as f64); // residual if placed here
        new_bin_score += 30.0 * progress; // later in stream, prefer reusing bins
        new_bin_score -= 10.0 * (open_bins_count.min(20) as f64) / 20.0
            * (1.0 - progress);
        // If mean residual across bins is small (bins nearly full), new bin OK.
        new_bin_score -= (mean_residual / cap).max(0.0) * 20.0;
        // If this is the only fitting option, new bin must compete fairly.
        if fitting_bins_count == 0 {
            new_bin_score -= 50.0;
        }
        score = new_bin_score;
    }

    // Slight tie-breaker: prefer bins with less residual before placement
    // (best-fit flavor), scaled by how well item divides capacity.
    let item_class = item_size % 10;
    if item_class == 0 {
        // Item divides capacity into clean classes; reward tighter bins more.
        score -= (bin_residual - item_size) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 8 {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: favor bins whose post residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is less costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate handling: make an empty bin attractive only when the current
    // fit is poor (large post_residual) or many bins are already open with slack.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 30.0;
        if poor_fit || (mean_residual > 40.0 && open_bins_count > 2) {
            score -= 35.0;
        } else {
            score += 55.0;
        }
    }

    // Slight preference for bins below the mean residual (rebalance slack).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact-fit jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size well.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        score -= 25.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills remaining space.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else {
        // Last item: strongly prefer minimizing waste.
        score += 20.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps flexibility.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // pairing large items with fresh bins is fine
        }
    }

    // Mild preference to fill older/crowded states as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Base: tightness of fit — small post_residual is good.
    let mut score = post;

    // Reward near-perfect fits strongly.
    if post == 0.0 {
        score -= 60.0;
    } else if post <= 5.0 {
        score -= 30.0;
    } else if post <= 10.0 {
        score -= 15.0;
    }

    // Penalize dead space relative to typical future item sizes.
    let waste = post / cap;
    score += waste * 40.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt).abs();
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit here: slight penalty for fragmentation
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets base cost of a fresh bin,
    // reduced when current fit is bad or many bins already open.
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 55.0;
        // If the current fit is terrible (large post residual), opening is fine.
        new_bin_cost -= (post / cap) * 45.0;
        // Early in stream, prefer opening bins to build a portfolio.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost -= (1.0 - progress) * 15.0;
        // Fewer open bins -> cheaper to open another.
        new_bin_cost -= (10.0 / (open_bins_count as f64 + 1.0)).min(10.0);
        score += new_bin_cost;
    } else {
        // Existing bin: slight preference for bins below mean residual
        // (use the emptier bins first, keep tight bins for small items).
        if resid > mean_residual {
            score += (resid - mean_residual) * 0.3;
        } else {
            score -= (mean_residual - resid) * 0.15;
        }
    }

    // Time-horizon modulation: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, dead space is cheap (bins get reused later); late, dead space is costly.
    let coupling = progress * norm_pr * norm_pr * (1.0 - norm_pr) * 4.0;
    score += 120.0 * coupling;

    // Smooth waste penalty: quadratic in normalized post residual, modulated by progress
    score += 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only one that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0 + 40.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space exactly matching next item (smooth Gaussian-like term)
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64).abs();
        score -= 50.0 * (-(d * d) / 900.0).exp();
    }

    // Crowding: many open bins with high mean residual -> favor consolidating into fuller bins
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += crowd * mean_residual * 0.3 * (1.0 - progress);

    // New-bin candidate: penalize mildly unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * norm_pr * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by large "harmonics"
    // (10, 20, 25, 50) are more reusable by typical item sizes.
    let r = post_residual;
    let mut harmonic_bonus = 0.0;
    if r > 0 {
        if r % 50 == 0 { harmonic_bonus = 18.0; }
        else if r % 25 == 0 { harmonic_bonus = 12.0; }
        else if r % 20 == 0 { harmonic_bonus = 10.0; }
        else if r % 10 == 0 { harmonic_bonus = 7.0; }
        else if r % 5 == 0 { harmonic_bonus = 3.0; }
    }
    score -= harmonic_bonus;

    // Penalize tiny dead space: residuals 1..=4 are nearly unusable (items >= 1 though,
    // but small items are rare in classic streams) — mild penalty.
    if r > 0 && r < 5 {
        score += 6.0;
    }

    // Perfect fit reward
    if r == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            // harmonic class match between next item and post residual
            if r % next_item_size == 0 {
                score -= 14.0;
            }
            score -= (r - next_item_size) as f64 * 0.25;
        } else {
            // next item cannot fit here; if this is the last fitting bin, open new bin
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin logic: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.85;
        // cheaper to open new bin early in stream or when many bins open with slack
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // if many fitting bins exist, opening new bin is wasteful
        score += fitting_bins_count as f64 * 4.0;
    }

    // Waste normalization: penalize residual far from mean (fragmentation signal)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Tight-packing reward: prefer bins where item fills a large fraction of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 8.0;

    // Integer division threshold on post_residual: residuals in [10,30] band are
    // prime targets for mid-size items; slightly favor them.
    let band = post_residual / 10; // 0..=10
    if band >= 1 && band <= 3 {
        score -= 4.0;
    }

    // Slight load balancing: prefer bins with residual below mean
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (very small gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // gap 1..9 => +55..+15
    }
    // Medium unusable gaps (10..19) moderately penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits strongly (post_residual small but >= 0).
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    // If the bin becomes exactly full, big reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by post-residual, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (penalize new-bin candidate implicitly via open_bins_count term).
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when no tight fit is available (its raw post_residual
    // is large so it usually loses, but give it a mid-range anchor).
    if bin_residual == bin_capacity {
        // Prefer new bin when current open bins are badly fragmented.
        score -= 10.0 + mean_residual * 0.05;
        // Early in the stream, opening bins is cheap.
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (they are the fragmented ones); bins near/below mean are preferred targets.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 800.0; // chain: exact second-step fit
        } else if next_item_size < post_residual {
            let slack = pr - ni;
            score -= 200.0 / (1.0 + slack);
            // penalize large unusable slack after the hypothetical second item
            if slack > 40.0 {
                score += (slack - 40.0) * 1.5;
            }
        } else {
            // next item won't fit here; post residual becomes dead space
            score += pr * 0.5;
        }
    }

    // Tightness reward: prefer bins where the item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 50.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are large
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let waste_threshold = 0.35 * bin_capacity as f64;
        if mean_r < waste_threshold && fitting_bins_count > 0 {
            score += 500.0; // keep using open bins with room
        } else {
            score += 100.0; // mild penalty; new bin ok when residuals are fragmented
        }
        // early stream: opening bins is cheap
        if step_index as f64 / (total_items.max(1) as f64) < 0.1 {
            score -= 80.0;
        }
    }

    // Slight preference to balance residual usage relative to mean
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins with small post-residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no future small item (min size 1..10) can use well:
    // residuals < 10 are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fills the remainder
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here: leftover becomes dead space risk
            score += 5.0 * ((next_item_size - post_residual) as f64 / (bin_capacity as f64));
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 100.0;
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0 + 0.2 * (bin_residual.saturating_sub(item_size)) as f64;
    }

    // Compare against mean residual of open bins: prefer bins that are
    // tighter than average (concentrate waste in fewer bins).
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Time horizon: early in the stream, be more willing to keep bins open
    // loosely (long future); late in the stream, pack tightly.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged when existing bins fit decently,
        // but encouraged when this would be a wasteful squeeze.
        let would_be_tight = (item_size as f64 / bin_capacity as f64) > 0.7;
        if would_be_tight {
            score -= 8.0; // allow fresh bin for large items to keep small residuals usable
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
        // If next item is large and no bin would hold both, fresh bin may help.
        if next_item_size > 0 && next_item_size > post_residual.max(1) && (item_size + next_item_size) <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr as f64;

    // Non-linear coupling: quadratic post-residual penalty shaped by stream progress.
    let quad = base * base * (1.0 + 2.0 * progress);
    score += 30.0 * quad * cap * 0.01;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tight = (1.0 - base).powi(3);
    score -= 25.0 * tight * (0.5 + progress);

    // Dead-space penalty: residuals too small for typical future items.
    let dead = if pr > 0.0 { (1.0 - pr / (item_size as f64 + 10.0)).max(0.0) } else { 0.0 };
    score += 15.0 * dead * dead;

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap).abs();
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Mild dispersion penalty relative to mean residual across open bins.
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    // Slight preference for existing bins over opening new ones early.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Harmonic class of post_residual: reward "useful" residual classes
        // Residuals divisible by common item granularities are more reusable.
        let pr = post_residual;
        let mut class_bonus = 0.0;
        if pr % 10 == 0 { class_bonus += 12.0; }
        else if pr % 5 == 0 { class_bonus += 6.0; }
        if pr % 20 == 0 { class_bonus += 6.0; }
        // Integer-division thresholds: large residuals are wasteful unless reusable
        let half = bin_capacity / 2;
        if pr > half { class_bonus -= (pr - half) as f64 * 0.5; }
        // Tiny dead space (< smallest plausible item) is nearly dead
        if pr < 10 { class_bonus -= 8.0; }
        score -= class_bonus;

        // Coupling with lookahead: penalize if next item cannot fit in post_residual
        if next_item_size > 0 {
            if next_item_size > pr {
                score += (next_item_size - pr) as f64 * 0.6;
            } else {
                score -= 10.0; // chain fit bonus
                // harmonic class match between next item and residual
                if pr % next_item_size.max(1) == 0 { score -= 8.0; }
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive for large items or when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = (open_bins_count as f64).sqrt() * 3.0;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items or late in stream with many open bins
        score = 60.0 - item_frac * 55.0 + open_penalty * (1.0 - progress) - (fitting_bins_count as f64) * 8.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // room to chain next item in fresh bin
        }
        return score;
    }

    // Slight preference for tighter existing bins overall
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit the next item are wasted.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to lookahead: penalize proportionally to its uselessness.
            let dead = (next_item_size - post_residual) as f64;
            score += 2.0 * dead;
        } else if post_residual >= next_item_size && next_item_size > 0 {
            // A gap that still accommodates the lookahead is valuable.
            let slack = (post_residual - next_item_size) as f64;
            score -= 1.5 * slack.min(30.0);
        }
    }

    // Penalize any tiny residual (< 10) as near-unusable dead space.
    if post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage new-bin opening
    // (new empty bin has post_residual = capacity - item, already high).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is already small (tight packing).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Mild reward for filling a large fraction of the bin's current residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but dampen for very small items
    // so tiny items don't get over-prioritized into large gaps.
    let item_f = item_size as f64;
    score *= 1.0 + 0.5 * (1.0 - item_f / bin_capacity as f64);

    // 2-step lookahead: strongly reward when the NEXT item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // next item fits in the gap left here: reward proportional to fill quality
            let fill_quality = nxt / pr.max(1.0);
            score -= 60.0 * fill_quality * fill_quality;
        } else {
            // next item cannot use this gap: penalize large gaps slightly
            score += 10.0 * (1.0 - pr / bin_capacity as f64);
        }
        // Perfect 2-step chain: post_residual == next_item_size exactly
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 80.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from mean
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream or when
    // open bins exist with reasonable residuals; encourage late when bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 60.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
        // allow new bin if item is huge and would leave awkward residual elsewhere
        if item_size >= 80 {
            score -= 70.0;
        }
    }

    // Waste penalty: squared dead space discourages leaving unusable slivers
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 15.0; // tiny slivers are nearly dead space anyway; slight reward for closing out
    } else if pr >= 10.0 {
        score += 0.05 * pr * pr / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize quadratic waste (dead space grows quadratically in badness).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 25.0;

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Extra reward for near-exact chaining of two items.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= (10.0 - chain_waste / 10.0).max(0.0);
        } else if next_item_size <= bin_residual {
            // Next item fits this bin now but not after this placement: mild penalty.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default: discourage opening a new bin.
        score += 30.0;
        // Very large items deserve a fresh bin (avoid fragmenting).
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // Fresh bin is fine if the leftover is still broadly usable.
        if post_residual >= bin_capacity / 3 {
            score -= 10.0;
        }
        // If mean residual across open bins is tiny, existing bins are nearly
        // full anyway — a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Coupling with global mean residual: prefer bins whose post-residual
    // stays near the fleet mean (keeps residuals homogeneous and usable).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.08;

    // Many open bins: mild pressure to consolidate into existing bins.
    score += open_bins_count as f64 * 0.05;

    // Dynamic time horizon: late in the stream, tighten packing (waste matters
    // more since fewer items remain to fill gaps).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: post residual value with progress-dependent shaping
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 30.0 * poly * (1.0 + 2.0 * progress);

    // Penalize wasted residual relative to mean residual (smooth quadratic coupling)
    let mr = mean_residual / cap;
    score += 8.0 * (norm_pr - mr) * (norm_pr - mr) * (1.0 - 0.5 * progress);

    // Reward tight fits: quadratic decay of penalty with fit ratio
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Late-stream consolidation: penalize spreading across many bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "useful" residue classes (multiples of 10, or large enough for small items)
    // should be favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Penalize dead space: leftovers too small to host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic reward: post_residual divisible by 10 aligns with item granularity.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Reward leftovers that can host the lookahead item exactly (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size + 10 {
            score -= 6.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Lookahead cannot follow into this bin; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; reduced late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut penalty = 22.0 * (1.0 - 0.3 * progress);
        // If the item would leave a very poor residual in existing bins, ease opening.
        if frac < 0.10 && post_residual > 0 {
            penalty -= 10.0;
        }
        score += penalty;
    } else {
        // Prefer tighter bins (smaller residual) — already the base term, but
        // add a mild pull toward bins near capacity via harmonic threshold.
        if post_residual <= 20 {
            score -= 5.0;
        }
    }

    // Coupling with mean residual: if this bin is much emptier than average,
    // slightly discourage spreading items too thin.
    score += 0.05 * (mean_residual - pr).max(0.0);

    // Modulo threshold on next item size: large next items (>= 50) favor
    // consolidating current item into the emptiest fitting bin.
    if next_item_size >= 50 && !is_new_bin && post_residual >= 50 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 45.0;
    } else if post_residual <= 20 {
        score += 12.0;
    }

    // Reward tight fits (near-zero post residual) that are not dead space.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: penalize opening a new bin unless it is clearly needed
    // (no fitting open bins, or item is large and would leave huge gaps elsewhere).
    if bin_residual == bin_capacity {
        let new_bin_penalty = if fitting_bins_count == 0 {
            -10.0 // nothing fits anywhere; new bin is fine
        } else {
            70.0 + (bin_capacity - item_size) as f64 * 0.3 // avoid opening when fits exist
        };
        score += new_bin_penalty;
    }

    // Mild progression term: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for residual waste (quadratic dead-space pressure).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // --- 2-step lookahead: reward exact / near match of next item into post_residual ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let gap = post - nxt;
            // Perfect 2-step fill is highly desirable.
            if gap == 0.0 {
                score -= 60.0;
            } else if gap <= 5.0 {
                score -= 40.0 - 6.0 * gap;
            } else {
                // Mild reward for leaving room the next item can use.
                score -= 12.0 * (nxt / post.max(1.0));
            }
        } else {
            // Next item cannot use this residual: penalize leftover dead space
            // proportionally to how unusable it is for the next item.
            let unusable = (post / nxt).min(1.0);
            score += 10.0 * unusable;
        }
    }

    // --- Mean-residual coupling: prefer bins whose residual sits below mean
    // (draining fuller bins first keeps the bin set tight). ---
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (res - mean_residual);
    }

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin. ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: only attractive when the item is large
    // relative to capacity or the stream is early (room to plan ahead). ---
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items early on; bad late or for small items.
        score -= 20.0 * large_item * (1.0 - progress);
        score += 15.0 * progress;
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity.saturating_sub(item_size) {
            // New bin leaves perfect room for next item: encourage.
            score -= 18.0;
        }
        if open_bins_count > 0 && item_size <= 30 {
            // Discarding open capacity for tiny items is wasteful.
            score += 30.0;
        }
    }

    // Slight preference for keeping the number of open bins bounded.
    if open_bins_count > 20 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Reward filling bins deeply (low post-residual is good, but add a proportional pull)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 4.0 * fill_ratio;

    // Penalize creating unusable dead space (slivers below the minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead (k=2): if the next item fits in the resulting residual, reward strongly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size >= bin_residual {
            // next item won't fit here anyway; residual quality matters less
            score -= 1.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can hold the item
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: default is to prefer existing bins
    if is_new_bin {
        score += 25.0;
        // If no open bin fits, opening a new bin is necessary
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Opening a new bin is more attractive if it can also serve the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late in the stream, be more conservative about new bins
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - t);
    }

    // Global state coupling: if open bins are already slack-heavy, prefer tightening them
    if mean_residual > post_residual as f64 + 15.0 && !is_new_bin {
        score -= 3.0;
    }

    // Mild time horizon effect: early on, consolidate; later, flexibility matters less
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * t * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let t = progress;
    let poly = pr * pr / (bin_capacity as f64 * bin_capacity as f64);
    score += poly * (t - 0.5) * 40.0;

    // Reward tight fits, stronger late in the stream
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * (1.0 + t) * 12.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Penalize bins far below mean residual (wasted space hoarding)
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Mild pressure to prefer existing bins as open bin count grows
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: exact fills and small remainders are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 200.0; // perfect fill
    } else if pr <= 5 {
        score -= 40.0; // near-perfect: dead space below min item size
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Modulo classes of post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let class = pr % quarter;
    if class == 0 && pr > 0 {
        score -= 15.0; // residual aligns with capacity fraction
    } else if class < 10 {
        score += 5.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = pr - next_item_size;
        score -= 8.0 + 0.15 * (slack as f64).min(30.0);
    }
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        // residual too small for next item: penalize by dead-space class
        let dead = pr as f64;
        score += 0.4 * dead;
        if dead < 10.0 {
            score += 10.0; // truly unusable sliver
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when many bins are open and residual
    // classes of open bins are poor (large mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_open = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        let penalty = 120.0
            - 40.0 * poor_open
            - 20.0 * progress
            - if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        score += penalty.max(0.0);
    }

    // Prefer tighter existing bins (smaller residual) mildly.
    score += 0.1 * (bin_residual as f64 - post_residual as f64) * 0.0; // no-op guard

    // Small bias toward bins with residuals in "harmonic" sizes 25/50/75 before placement.
    let br_class = bin_residual % 25;
    if br_class == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post) * 4.0;
    }
    // Gaps that cannot fit the lookahead item are semi-dead; mild penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post) * 0.6;
    }

    // Reward near-perfect fits (post residual close to 0 but not dead).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Prefer bins whose residual was already small (tight packing pressure).
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= tightness * 12.0;

    // Open-bins pressure: when many bins are open, avoid spreading; but when
    // few bins are open, tolerate opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.9 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only if this bin would leave a
    // large unusable gap or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10
            || (next_item_size > 0 && post_residual < next_item_size);
        if poor_fit && open_bins_count > 0 {
            score -= 45.0;
        } else {
            score += 20.0 + mean_residual * 0.15;
        }
    }

    // Mean-residual coupling: if this bin's post residual deviates badly from
    // the mean, nudge toward homogenization of residual sizes.
    let dev = (post - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 0.6;

    // Aggressive 2-step lookahead: reward exact match with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match for next item: strong reward.
        if post_residual as u32 == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize.
            score += 8.0 + diff * 0.35;
        }
        // Post-residual too small for anything (below min item size 1 -> always usable, but
        // very small residuals are near-dead): mild penalty scaled by tightness.
        if post_residual < 10 {
            score += 6.0;
        }
    } else {
        // Last item: pure tight-fit greedy.
        score -= 20.0;
    }

    // Compare against mean residual: bins with residual far below mean are "odd" bins;
    // filling them well is good, leaving them fragmented is bad.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let threshold = if next_item_size > 0 { next_item_size as f64 + 15.0 } else { 0.0 };
        // Penalize opening a new bin mildly; it should win only over bad fits.
        score += 18.0 + 0.1 * open_bins_count as f64;
        // If next item is large, an empty bin preserves flexibility.
        if next_item_size >= 60 {
            score -= 12.0;
        }
        let _ = threshold;
    }

    // Stream progression: late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual waste non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: empty bin should lose unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If many bins are open but few fit, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid spawning bins with large unusable leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Lookahead coupling: if the next item can use the post-residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // Post-residual too small for next item: mild penalty.
            score += 8.0;
        }
    }

    // Global state: when mean residual across bins is high, encourage
    // consolidating into existing bins rather than opening new ones.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // modulated by how many alternatives exist.
    let slack = (bin_residual - item_size) as f64;
    score += 0.05 * slack * (1.0 + fitting_bins_count as f64);

    // Mild preference for keeping the number of open bins stable.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: tight fit preferred, normalized residual
    let mut score = pr / cap;

    // Non-linear coupling: residual pressure decays with progress (waste less tolerable later)
    let progress_weight = 0.6 + 1.4 * progress * progress;
    score -= progress_weight * (1.0 - fit_ratio) * (pr / cap);

    // Smooth dead-space penalty: residual that no plausible item can use
    let mean_fit = mean_residual / cap.max(1.0);
    let dead = (pr - (item_size as f64 * 0.5)).max(0.0) / cap;
    score += progress_weight * dead * dead;

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.8 + 0.5 * progress;
    }

    // Scarcity coupling: fewer open bins relative to stream -> be more frugal
    let scarcity = 1.0 / (1.0 + open_bins_count as f64);
    score += scarcity * (pr / cap) * (1.0 - progress);

    // Lookahead: reward bins whose post-residual pairs with the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.35 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.15 * (1.0 - progress);
    }

    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 0.45 + 0.5 * mean_fit * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues divisible into
    // "usable" classes (0, or multiples of 10 that can host small items)
    // get rewarded; odd/prime-ish dead space gets punished.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class-based residual shaping.
    if post_residual > 0 {
        let class = post_residual % 10;
        match class {
            0 => score -= 20.0,                    // clean decade residual
            1..=9 => score += (10 - class) as f64 * 1.5, // awkward remainder
            _ => {}
        }
        // Penalize residuals too small for any item (dead space < min item).
        if post_residual < 10 {
            score += 30.0;
        }
        // Harmonic fraction of capacity: residual near half capacity is flexible.
        let half = cap / 2.0;
        let flex = 1.0 - (post - half).abs() / half;
        score -= flex * 15.0;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + (next_item_size as f64) * 0.3;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to a fresh bin or open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / cap;
        // Prefer new bin when existing bins are tight and item is big.
        score += 60.0 - crowding * 50.0 - large_item * 30.0 - progress * 10.0;
    } else {
        // Mild preference for filling existing bins as the stream progresses.
        score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Prefer bins whose residual is already below average (consolidation).
    score += ((post - mean_residual).max(0.0)) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable, punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        score -= 15.0 / post_residual as f64;
    }

    // Lookahead: bonus if the leftover gap can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if the next item would NOT fit in this bin but WOULD fit a fresh bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate a new bin for better long-run fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure discount.
        score = score.max(0.0) + 45.0 - pressure * 1.5;
    } else {
        score -= pressure * 0.6;
    }

    // Nudge toward bins with residuals near the item size (tight fits).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Prefer bins whose residual deviates from the fleet mean (specialization).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits here after this placement: mild reward scaled by closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space blocks the lookahead item: penalize proportionally to waste.
            let waste = next_item_size - post_residual;
            score += 10.0 + 0.5 * waste as f64;
        }
    }

    // Prefer bins whose residual is below mean (tight packing), penalize loose bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing sensible fits elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * item_size as f64;
    }

    // Late in the stream, tighten up: prefer minimal post residuals more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space: small post-residual that is likely unusable.
    // Dead space threshold grows with item size range; treat residual < ~15 as waste.
    if post_residual > 0 && post_residual < 15 {
        score += 12.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Lookahead coupling: reward if next item exactly fits the post-residual,
    // penalize if next item could have fit but this placement destroys that chance.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 25.0; // perfect chain
        } else if post_residual as u32 >= next_item_size {
            score -= 5.0; // still usable
        } else if bin_residual as u32 >= next_item_size && post_residual < next_item_size {
            score += 20.0; // destroyed a fit for the next item
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // but allow it when open bins are mostly full or fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 10.0 + 25.0 * (1.0 - progress) - 20.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Late in the stream, squeeze harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: squared normalized post-residual scaled by progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    score += 40.0 * progress * pr_norm * pr_norm * cap;

    // Cubic interaction between post-residual and stream progress
    score += 15.0 * (1.0 - progress) * pr_norm * pr_norm * pr_norm * cap;

    // Reward tight fits more strongly as stream progresses (smooth polynomial)
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * progress * tightness * tightness;

    // Dead-space penalty: post-residual that is too small relative to typical item sizes
    let min_item = 1.0;
    let dead_zone = (min_item / cap).max(0.0);
    if pr_norm < dead_zone * 3.0 {
        score += 20.0 * (1.0 - pr_norm / (dead_zone * 3.0));
    }

    // Last-chance bonus: if this is the only bin that fits, encourage using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= pr;
        if !next_fits {
            score += 12.0 * pr_norm * cap / cap;
        } else {
            score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - pr_norm);
        }
    }

    // Mean residual deviation: prefer bins with residual close to the mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // Slight preference to keep fewer open bins early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space below the smallest useful chunk is bad.
    // Class by integer division thresholds: 0 (perfect), <=20 (poor), <=50 (medium), else good.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr <= 20 {
        score += 25.0; // unusable dead space
    } else if pr <= 50 {
        score += 8.0;
    } else {
        score -= 10.0; // still roomy
    }

    // Modulo coupling: post_residual that is a multiple of common item sizes is reusable.
    if pr > 0 {
        let mut reusable = 0u32;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 { reusable = m; }
        }
        score -= reusable as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 20.0 - slack * 0.3;
        if pr == next_item_size {
            score -= 15.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item won't fit here; slightly penalize leaving mid-size gap
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fill = item_size as f64 / cap;
        if pressure > 0.5 {
            score -= 15.0 + fill * 10.0; // forced to open
        } else {
            score += 35.0; // prefer existing bins otherwise
        }
    }

    // Mean residual drift: placing in a bin below mean residual tightens spread.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.15 * (mean_residual - resid_f);
    } else {
        score += 0.10 * (resid_f - mean_residual);
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: dead space after placement.
    let mut score = post_residual as f64;

    // Strict dead-space penalty: gaps too small for typical items are "dead".
    let dead_threshold: f64 = 8.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (perfect fit is ideal).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Fit ratio: how well the item fills the residual.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= fit_ratio * 30.0;
    }

    // Last chance: strongly favor using this bin if it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow more freedom.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here: penalize leaving a gap that's almost usable.
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (fill fuller bins first), above the mean (keep large gaps for big items).
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    // New-bin candidate: opening a new bin is a fallback. Make it attractive
    // only when the item is large relative to the residual or fits are poor.
    if bin_residual == bin_capacity {
        let waste_ratio = item_size as f64 / bin_capacity as f64;
        // A fresh bin is good for large items or when few bins fit the item.
        score = 60.0 - waste_ratio * 55.0;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheap.
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize proportionally
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.5 * wasted.min(80.0);
        }
    }

    // Tightness reward: small post_residual is good, non-linearly
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Compare residual to mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 30.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 20.0 * (rel - 1.5);
        }
    }

    // Last chance: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = if fitting_bins_count > 0 { 1.0 } else { 3.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0 * pressure * (0.5 + progress);
    }

    // Reward using a nearly full bin to close it out
    if bin_residual < bin_capacity && post_residual < 10 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 -> use 20 as soft threshold).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual >= 20 && post_residual < 40 {
        score += 8.0; // awkward zone
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin (avoiding a new bin is usually good).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current fit is bad
    // (large post_residual waste) or many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64); // = item_size/capacity
        let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (mean_residual / bin_capacity as f64);
        // Large items justify a fresh bin; small items into a fresh bin waste capacity.
        let size_bonus = (item_size as f64 / bin_capacity as f64) * 50.0;
        score -= size_bonus - 30.0 * pressure + 20.0 * (1.0 - fit_quality);
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Mild preference for bins whose residual is above average (keep flexible bins flexible):
    // placing into a bin with residual well above mean wastes the "big" bin; prefer below-mean bins.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 4.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Small global-load regularizer: with many open bins, favor filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space grows quadratically when post_residual is small
    let norm_post = post / cap;
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Smooth stream-progress coupling: tighten packing as stream advances
    score += 20.0 * progress * norm_post * norm_post;

    // Reward bins whose residual closely matches the item (smooth Gaussian-like fit term)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 15.0 * (-fit_gap * fit_gap * 40.0).exp();

    // Lookahead: bonus if next item fits into post_residual, penalty otherwise
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post >= n {
            score -= 8.0 * (1.0 - (post - n) / cap);
        } else {
            score += 6.0 * (n - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for bins below mean residual (balance / consolidation)
    score += 0.05 * (post - mean_residual);

    // Penalize opening a new bin when plenty of open bins exist
    if bin_residual == bin_capacity {
        score += 3.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" is the leftover space?
    // Residuals that are multiples of common item sizes (10,20,25,50) are reusable.
    let pr = post_residual;
    let mut usable_bonus = 0.0;
    if pr == 0 {
        usable_bonus -= 40.0; // perfect fit
    } else if pr % 50 == 0 {
        usable_bonus -= 12.0;
    } else if pr % 25 == 0 {
        usable_bonus -= 9.0;
    } else if pr % 20 == 0 {
        usable_bonus -= 8.0;
    } else if pr % 10 == 0 {
        usable_bonus -= 6.0;
    } else if pr < 10 {
        usable_bonus -= 4.0; // small dead space, not terrible
    } else {
        // awkward mid-range leftover: penalize dead space fraction
        usable_bonus += (pr as f64) * 0.15;
    }
    score += usable_bonus;

    // Integer-division thresholds on post_residual relative to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= next_item_size {
            // next item can chain into this bin: reward proportional to tightness
            let tight = 1.0 - ((pr - next_item_size) as f64) / cap;
            score -= 10.0 + 10.0 * tight;
            // exact harmonic match: next item divides the post residual
            if next_item_size > 0 && pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize more if leftover is large dead space
            score += nxt * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is poor
    if bin_residual == bin_capacity {
        // baseline for fresh bin: slightly worse than a good fit, better than awful fit
        score = cap * 0.55;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can host big upcoming items
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Tightness reward: filling most of the bin is good
    let fill_ratio = (item_size as f64) / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Stream progression: late in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Prefer bins with residuals far below mean (keeps big residuals available)
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space (items are >=1, but tiny gaps rarely refill)
    } else if post_residual == 0 {
        score -= 100.0; // perfect fit: strongly reward closing the bin
    } else if post_residual < 20 {
        score += 25.0; // likely dead space
    } else if post_residual < 35 {
        score += 10.0; // marginal gap
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.15;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // gap too small for the next item
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless it creates tiny dead space, handled above).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted if open bins are crowded.
        score += 45.0 + bin_pressure * 2.0;
        if mean_residual > item_size as f64 {
            score += 15.0; // open bins have plenty of room; don't open a new one
        }
    } else {
        // Reward filling bins that are already relatively full.
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fill_ratio * 20.0;
        // Mild preference for bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 30.0;
        // Slight reward for consolidating when many bins are open.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement: mild reward proportional to leftover
            score -= 0.3 * (next_item_size as f64 / bin_capacity as f64) * 100.0;
        } else {
            // next item won't fit: penalize dead space relative to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: penalize creating outlier small residuals
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 20.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's late stream or no good fit exists
    if bin_residual == bin_capacity {
        score += 250.0;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins overall
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 25.0;

    // Penalize dead space: residuals too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 40.0;
        } else if gap < 10.0 {
            score -= 18.0;
        } else {
            score -= (10.0 - gap / 20.0).max(0.0);
        }
    } else if next_item_size > post_residual && !is_new_bin {
        // This bin becomes useless after placement; penalize mildly
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Many open bins: encourage filling existing ones, discourage spreading
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Compare against mean residual: bins with residual close to item size are precious
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += residual_gap * 0.15;

    // Early in stream: be pickier (leave room); late: fill anything
    if progress < 0.3 {
        score += post_residual as f64 * 0.05;
    } else if progress > 0.7 {
        score -= 4.0;
    }

    // New bin candidate: only attractive when existing fits are poor
    if is_new_bin {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
        if next_item_size > 0 && bin_residual >= next_item_size {
            score -= 8.0; // fresh bin keeps flexibility
        }
    }

    // Mild preference for bins with larger residual when placing big items
    score -= (bin_residual as f64 / bin_capacity as f64) * (item_size as f64 / 100.0) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear quadratic penalty on wasted residual, amplified late in stream
    let norm_waste = pr / cap;
    score += 12.0 * norm_waste * norm_waste * (0.5 + progress);

    // Cubic coupling: large residual waste is disproportionately bad
    score += 8.0 * norm_waste * norm_waste * norm_waste * (1.0 + progress);

    // Reward near-perfect fits smoothly (residual close to 0)
    let fit_quality = 1.0 - (pr / cap);
    score -= 6.0 * fit_quality * fit_quality * fit_quality * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_waste);
    }

    // New-bin candidate: smooth penalty scaled by stream progress and open bins
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 4.0 + 6.0 * progress + 0.5 * open_f.sqrt();
        // But if existing fits would leave terrible dead space, allow opening
        let dead = (mean_residual - item).max(0.0) / cap;
        score -= 10.0 * dead * dead;
    }

    // Lookahead: reward bins whose post_residual can host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= 4.0 * (1.0 - gap.min(1.0)) * (1.0 - progress * 0.5);
        // Penalize post_residual that is just barely too small for next item
        if pr < nxt && pr > 0.0 {
            score += 3.0 * (1.0 - pr / nxt) * (0.5 + progress);
        }
    }

    // Mild penalty for bins deviating from mean residual (keeps bin set balanced)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo classes.
    let class = post_residual / 10; // 0..=10 harmonic class
    let rem = post_residual % 10;

    // Dead-space penalty: residuals that are too small to hold typical items.
    if post_residual < 10 {
        score += 40.0 - post_residual as f64; // near-full bins are fine, but tiny leftovers are dead
    } else {
        // Reward residuals that form "harmonic" classes (multiples of 10, 25, 50)
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
        // Penalize awkward classes (just above a small item size)
        if rem != 0 && rem < 5 { score += 3.0; }
        // Class-based gradient: larger classes waste more potential
        score += class as f64 * 0.8;
    }

    // Lookahead coupling: does the leftover fit the next item exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 8.0; // next item still fits
            // harmonic match of classes
            if (post_residual / 10) == (next_item_size / 10) { score -= 3.0; }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= post_residual { score -= 10.0; }
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Tight fit bonus: reward filling most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 - open_bins_count as f64 * 0.2;

    // Deviation from mean residual: prefer bins below mean (close them out).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 15 {
        score += 8.0;
    }

    // Reward tight fits (near-zero post residual).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += pressure * 0.5;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if item leaves a large useful residual in a fresh bin and no
        // existing bin fits well, make new bin competitive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Mild progression scaling: later in stream, be more conservative about
    // waste since amortized cost of extra bins is higher.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Match quality: perfect match (post_residual == next_item_size) gets big bonus.
            let gap = pr - nxt;
            score -= 45.0 * (1.0 - gap / bin_capacity as f64);
            // Small gap tolerance band gets extra nudge.
            if gap <= 10.0 {
                score -= 20.0;
            }
        } else {
            // Post residual too small for the next item: dead space penalty scaled by how unusable.
            let dead = nxt - pr;
            score += 0.9 * dead.min(40.0);
        }
    }

    // Penalize tiny unusable residuals regardless (dead space).
    if post_residual < 10 {
        score += 35.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable to fill.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless lookahead is perfect.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size == item_size && next_item_size > 0 {
            score -= 25.0; // opening fresh bin fine when stream is uniform
        }
    }

    // Early in stream, be slightly more willing to open new bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Mild penalty for too many open bins (encourage consolidation late).
    score += 0.4 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: the fuller the bin becomes, the better.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio * fill_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoiding bin proliferation).
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 7.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity when
    // open bins have slack; penalize more early in the stream and when
    // many bins are open with large mean residual.
    if bin_residual == bin_capacity {
        let slack_pressure = mean_residual * (open_bins_count as f64).sqrt();
        score += 10.0 + 0.25 * slack_pressure * (1.2 - progress);
    }

    // Mild global pressure: prefer bins with low residual (denser bins) and
    // slightly prefer reusing bins over growing the open set.
    score += 0.04 * mean_residual;
    score -= 0.03 * open_bins_count as f64;

    // Prefer using bins that are already partially filled when residuals are small.
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let mut score = r;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = 1.0 + 0.35 * progress - 0.6 * progress * progress + 0.5 * progress * progress * progress;
    score *= poly;

    // Penalize dead space that is too small to be useful later (non-linear).
    let dead = (rn - (rn * rn)).max(0.0);
    score += 18.0 * dead * (1.0 + progress);

    // Reward tight fits (small post_residual), stronger late in stream.
    score -= (1.0 - rn) * (1.0 - rn) * 10.0 * (0.5 + progress);

    // Lookahead: favor residuals that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if r >= nx { 1.0 } else { 0.0 };
        score -= 6.0 * fit_next * (nx / cap) * (0.4 + 0.6 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild pull toward mean residual state (smooth quadratic coupling).
    score += 0.05 * (r - mean_residual) * (r - mean_residual) / cap;

    // New-bin candidate: prefer opening new bins early, discourage late.
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common
    // item sizes (10..80 gcd classes) are more reusable.
    let residue = post_residual % 100;
    let mut harmony: f64 = 0.0;
    for m in [10u32, 20, 25, 30, 40, 50] {
        if residue % m == 0 && residue > 0 {
            harmony += 4.0;
        }
    }
    score -= harmony;

    // Tight fit reward: exact or near-exact fill is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space: residual too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Last chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 {
                score -= 12.0;
            }
            score -= (rem as f64).sqrt() * 0.5;
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 6.0;
        }
    }

    // Compare against mean residual: filling below-average-residual bins
    // (the fullest bins) consolidates waste.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: opening a new bin is reasonable early in the
    // stream or when many bins are open, but costly late with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / 20.0;
        // Default: new bin is a fallback; make it slightly worse than a decent fit
        score += 20.0 + progress * 15.0 - open_pressure * 5.0;
        // But if the current bin would leave huge unusable residue relative
        // to typical item sizes, a fresh bin may win anyway.
        if post_residual > 60 && next_item_size > post_residual && next_item_size > 0 {
            score -= 30.0;
        }
    }

    // Integer-division threshold classes on post_residual.
    let cls = post_residual / 20;
    score += match cls {
        0 => -8.0,
        1 => -4.0,
        2 => 0.0,
        3 => 2.0,
        _ => 4.0,
    };

    // Mild preference to keep few open bins when stream is near end.
    if total_items > 0 && step_index + 2 >= total_items && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (<= 1) are pure waste; penalize tiny unusable gaps hard.
    let dead_threshold: f64 = 1.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 50.0; // unusable sliver
    }

    // Penalize residuals that cannot fit any plausible future item
    // (gap below the minimum item size of the observed stream).
    let min_item = 1.0f64;
    if (post_residual as f64) >= min_item && (post_residual as f64) < min_item + 5.0 {
        score += 20.0; // nearly-dead gap
    }

    // Reward tight fits: the smaller post_residual relative to item size,
    // the better the packing density.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += 3.0 * pressure;

    // New-bin candidate handling: an empty bin has a high baseline residual;
    // make it attractive only when the current fit is poor or many bins exist.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 40.0 || fitting_bins_count == 0;
        if poor_fit {
            score -= 30.0;
        } else {
            score += 15.0 + pressure * 2.0; // keep using existing bins on good fits
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, reward
    // leaving that gap; if next item cannot fit post_residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // below average (already well-filled).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        if diff == 0.0 {
            score -= 25.0; // exact chain: next item fills this bin perfectly
        } else if nx <= pr {
            // next item fits: reward proportional to tightness of the chain
            score -= 12.0 * (1.0 - diff / 100.0);
        } else {
            // next item does NOT fit in post-residual: penalize dead space
            score += 6.0 + diff / 50.0;
        }
        // Extra penalty when post-residual is small but unusable (< min item 1)
        if post_residual < next_item_size && post_residual < 10 {
            score += 8.0;
        }
    }

    // Reward tight fits relative to mean residual across open bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score -= (mean_residual - pr) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize creating very small dead space (< 10) that likely becomes waste
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }
    // Perfect closure bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Late in the stream, consolidate: prefer bins with more usage
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space relative to capacity).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 12.0 * fit_ratio;
    }
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * chain_quality;
    }
    // Penalize post-residuals that are dead zones (too small for typical items).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mildly prefer tighter fits.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New empty bin candidate: penalize opening a new bin unless the item is
    // large and would leave a very tight fit, or current bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        let fullness = 1.0 - (mean_residual / bin_capacity as f64);
        let mut new_bin_penalty = 25.0;
        // A big item in a fresh bin is fine (leaves room shaped by the item).
        new_bin_penalty -= 10.0 * tightness;
        // If open bins are nearly full, opening a new bin is natural.
        new_bin_penalty -= 15.0 * fullness;
        // Early in the stream, slightly cheaper to open bins.
        new_bin_penalty -= 5.0 * (1.0 - progress);
        // If no open bin fits at all, opening is unavoidable.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 30.0;
        }
        score += new_bin_penalty.max(-5.0);
    }

    // Mild global pressure: many open bins with large mean residual -> prefer
    // filling existing bins rather than fragmenting.
    score += 0.02 * (open_bins_count as f64) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;

    // Base: minimize post residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.35 * pr / cap) - 0.25 * (pr / cap).powi(2) * cap;

    // Smooth coupling: post residual valued differently over stream progress.
    // Early on, keep bins flexible (higher residual is fine); later, prefer tight fits.
    let tightness = (pr / cap).powi(3);
    score += progress * tightness * 30.0;
    score -= (1.0 - progress) * (1.0 - pr / cap).powi(2) * 8.0;

    // Interaction with mean residual: placing into bins below mean residual
    // consolidates space; penalize bins far above mean residual.
    let dev = (res - mean_residual) / cap;
    score += dev * (10.0 + 20.0 * progress) - dev * dev * 15.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        score -= 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward post residual that still accommodates the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 + 4.0 * progress;
        } else {
            // Penalize wasted space the next item cannot use, scaled by how close it is.
            let gap = (n - pr) / cap;
            score += 10.0 * gap * (1.0 - gap);
        }
    }

    // Mild penalty for many open bins to encourage consolidation early.
    score += (open_bins_count as f64).sqrt() * 1.5 * (1.0 - progress);

    // New-bin candidate: make empty bins attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 2.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, or large enough for typical items)
    // are preferred; awkward leftovers are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = post / cap;

    // Modulo-10 harmony: leftovers divisible by 10 tile better with 10..80 items
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 6.0;
    } else {
        score += 2.0 + mod10 as f64 * 0.5;
    }

    // Integer-division thresholds: can the leftover host the lookahead item?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect chaining: next item also fits here
        let chain_waste = (post_residual - next_item_size) % 10;
        score -= 8.0 - chain_waste as f64 * 0.3;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Lookahead breaks this bin's chain; penalize proportionally
        score += 3.0;
    }

    // Dead space: leftover too small for the smallest plausible item (1..100
    // unknown distribution => treat < 10 as near-dead, < 20 as risky)
    if post_residual < 10 {
        score -= 12.0; // essentially a closed bin: good, no future burden
    } else if post_residual < 20 {
        score += 5.0; // risky sliver
    }

    // Last-chance bonus: only fitting bin => strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are fragmented or this is a big item with poor fits elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post).abs();
        // Prefer new bin when open bins have low mean residual (tight) or many bins
        score += 4.0 + 10.0 * (1.0 - mean_residual / cap) + open_bins_count as f64 * 0.3 + progress * 2.0;
        if item_size > 60 {
            score -= 6.0; // big items start fresh bins happily
        }
        let _ = fragmentation;
    } else {
        // Reward tight fits on open bins (small post_residual relative to item)
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 5.0 * tightness;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's
    // already fragmented; using it consolidates waste.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score -= (-dev) * 0.05;
    }

    // Harmonic capacity-fraction tiers: post_residual near half or full
    // capacity leaves flexible future options
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    let d_half = (post - half).abs();
    let d_quarter = (post - quarter).abs();
    if d_half < 5.0 || d_quarter < 5.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let max_item: u32 = 100;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64; // tiny slivers are dead space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Reward tight fits (post_residual small relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize leaving room that could fit the next item poorly:
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual stays usable for lookahead -> mild reward
            score -= 8.0;
        } else {
            // residual becomes unusable for the known next item -> penalty
            score += 10.0;
        }
        // If post residual would exactly fit next item, strongly reward
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: only one bin fits the item -> favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = 15.0 + 25.0 * open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += pressure * (1.0 - 0.5 * progress);
        // A new bin is acceptable if item is large (fills well) or fits are scarce
        if item_size > 70 || fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Slight preference for emptier bins among open bins
        score += 0.15 * (mean_residual - bin_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight superlinear penalty
    // on wasted space to avoid leaving unusable slivers.
    let pr = post_residual as f64;
    score = pr + 0.15 * (pr * pr) / bin_capacity as f64;

    // 2-step lookahead: strongly reward when post_residual exactly matches the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        if post_residual >= next_item_size {
            // Next item fits perfectly here: big reward.
            score -= (bin_capacity as f64) * (1.0 - gap / (bin_capacity as f64)) * 0.9;
            if gap == 0.0 {
                score -= bin_capacity as f64; // perfect chain bonus
            }
        } else {
            // Next item won't fit here: penalize leaving space smaller than next item
            // (dead space), scaled by how close it is to fitting (frustration).
            let frustration = n - pr;
            score += frustration * 1.2;
        }
    }

    // Compare against mean residual: bins with residual far from mean are either
    // outliers to consolidate or fresh bins; mildly normalize.
    score += 0.05 * (pr - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin (penalize alternatives implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the current fit is poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Empty bin baseline: good if item is large or fit elsewhere is wasteful.
        let fit_quality = pr / bin_capacity as f64; // == 1 - item/capacity
        score = (bin_capacity as f64) * (1.0 - fit_quality) + 12.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are open, discourage spreading further.
        score += 0.5 * open_bins_count as f64;
    }

    // Small bonus for filling bins deeply (encourage closing bins out).
    score -= 0.3 * (bin_capacity as f64 - pr) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual >= 10 {
        // usable leftover: mild reward if it can host average-size future items
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placement; slight penalty if we leave big gap
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive when open bins could fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        // Penalize new bins more early on and when many bins are open with room.
        score += 35.0 + 15.0 * (1.0 - progress) + 8.0 * open_pressure;
        // But if existing residuals are all tiny (mean_residual low), new bin is fine.
        score -= 0.4 * mean_residual;
        // If item is huge relative to mean residual, existing bins fit poorly; soften penalty.
        let gap = mean_residual - item_size as f64;
        if gap < 5.0 {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit bias).
        let diff = (bin_residual - item_size) as f64;
        score += 0.15 * diff;
        // Slight preference for bins below mean residual (fill emptier-of-space bins first? no:
        // fill fullest bins -> residual below mean is good).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tight;

    // Mild penalty per open bin to discourage bin proliferation implicitly.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 1.0 };
    let tightness = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Base: prefer small post-residual (best fit), with a convex penalty on wasted space
    let mut score = pr + 0.35 * pr * pr / cap;

    // Smooth non-linear coupling: tight fits matter more as the stream progresses
    score -= 18.0 * (1.0 - tightness) * fill * (progress * (2.0 - progress));

    // Reward near-perfect fits with a smooth bump
    let fit_quality = (pr / cap) * (1.0 - pr / cap) * 4.0; // peaks at pr = cap/2
    score -= 6.0 * fit_quality * fill;

    // Penalize leaving residuals smaller than typical next items (dead space), smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (ni - pr).max(0.0) / cap;
        score += 14.0 * waste * waste * (1.0 - progress * 0.5);
        // Reward reserving room for a large upcoming item
        score -= 5.0 * (pr / ni).min(1.0) * (ni / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.3);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - pr / cap);

    // Prefer bins with residuals close to the item (relative fit), smooth term
    let rel = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score -= 10.0 * rel * (1.0 - rel.abs() * 0.5).max(0.0);

    // New-bin candidate: make empty bins slightly unattractive unless residuals are tiny
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 0.15 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "half" or exact multiples
    // of common item classes are more reusable; odd tiny residues are dead space.
    let post = post_residual;
    if post > 0 {
        // dead-space penalty: small unusable residues
        if post < 10 {
            score += 60.0 - post as f64;
        }
        // modulo classes: residues divisible by 10 pair well with typical sizes
        let r = post % 10;
        score += (5 - ((r as i32) - 5).abs()) as f64 * 1.5;

        // half-full class bonus (residual ~50 splits well)
        let frac = post as f64 / cap;
        let half_dist = (frac - 0.5).abs();
        score -= (0.5 - half_dist) * 25.0;

        // integer-division thresholds: post/next pairing
        if next_item_size > 0 {
            let fits_next = post >= next_item_size;
            if fits_next {
                score -= 20.0 + (post - next_item_size) as f64 * 0.3;
            } else {
                score += (next_item_size - post) as f64 * 0.5;
            }
        }
    }

    // perfect fit reward
    if post == 0 {
        score -= 100.0;
    }

    // last-chance bin: strongly favor using it before opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // new-bin candidate: mild penalty so open bins are preferred unless poor fit
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // stream progression: tighten packing toward the end
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 5.0 * (post as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 40.0;
    } else if fill_ratio > 0.7 {
        score -= 15.0 * fill_ratio;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // residual unusable for the known next item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = cap * 0.9 + open_bins_count as f64 * 4.0 + mean_residual * 0.3 - progress * 20.0;
    } else {
        // Slight preference for bins below mean residual (balance spreading).
        score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Penalize leftover gap relative to how far it misses the next item.
        let gap = (post_residual - next_item_size) as f64;
        score += 0.35 * gap;
    } else if next_item_size > 0 {
        // Next item too big for this residual; slight penalty unless residual is tiny.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable dead space (post_residual in awkward range).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Favor bins tighter than the mean residual (good packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight bias against opening new bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Prefer consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.25 * (next_item_size as f64);
        }
        // Perfect chaining: item + next item fills the bin exactly.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count == 0 {
            -100.0 // forced open
        } else {
            let waste = mean_residual.max(0.0);
            15.0 + 0.35 * waste + 2.0 * (open_bins_count as f64).ln().max(0.0)
        };
        score += bad_fit;
    }

    // Early in the stream, be more willing to spread items (keep residuals balanced).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score += 8.0 * (1.0 - progress) * ((post_residual as f64 - mean_residual) / 100.0);
    }

    // Prefer fuller bins among many open bins (bin consolidation).
    score -= 5.0 * (1.0 - (bin_residual as f64) / (bin_capacity as f64)) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: wasted space, mildly non-linear
    let mut score = pr + 12.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate large residuals (keep bins flexible);
    // late, compact tightly.
    let w = 0.5 + 0.5 * progress;
    score += w * 18.0 * (norm_pr * norm_pr - norm_pr);
    score -= (1.0 - w) * 10.0 * norm_pr * (1.0 - norm_pr);

    // Perfect / near-perfect fit reward (smooth)
    let fit_quality = 1.0 - (pr / cap);
    score -= 25.0 * fit_quality * fit_quality;

    // Lookahead: reward if next item fits the post-residual (smooth)
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        let fits_next = if pr >= nxt { 1.0 - gap / cap } else { 0.0 };
        score -= 15.0 * fits_next * fits_next;
        // penalize leaving residual just below next item (dead space)
        let dead = if pr < nxt { (nxt - pr) / cap } else { 0.0 };
        score += 20.0 * dead * dead;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // many alternatives: prefer tight fits even more
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin is attractive early / when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual - item).abs() / cap;
        let openness = 1.0 - progress;
        score = pr - 22.0 * openness - 15.0 * poor_fit * poor_fit
            + 25.0 * progress * progress; // late stream: discourage new bins
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when a last-chance bin exists
        }
    }

    // Slight preference for bins below mean residual (keep big holes for big items)
    score += 4.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "usable" classes (divisible into common small item sizes), penalize
    // dead-space classes.
    let pr = post_residual;
    if pr > 0 {
        // Which harmonic class does post_residual belong to?
        // Class A: pr % 10 == 0 -> perfectly reusable for typical sizes.
        // Class B: pr % 5 == 0  -> still decent.
        // Class C: small leftovers -> dead space.
        let class_penalty = if pr % 10 == 0 {
            -12.0
        } else if pr % 5 == 0 {
            -6.0
        } else if pr % 3 == 0 {
            -2.0
        } else {
            4.0
        };
        score += class_penalty;

        // Integer-division thresholds: bins with post_residual in the
        // "sweet zone" (just below common item sizes) are hard to fill.
        let dead_zone = (pr > 80 && pr < 90) || (pr > 60 && pr < 70) || (pr > 40 && pr < 50) || (pr > 20 && pr < 30);
        if dead_zone {
            score += 8.0;
        }
    } else {
        // Perfect fill: strongly favored.
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this is a harmonic chain - reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // Reward proportional to how tight the follow-up fit is,
            // modulated by slack class.
            score -= 10.0 * (1.0 - slack / cap);
            if slack as u32 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; residual becomes dead space
            // unless small enough to be negligible.
            if pr > 0 && pr < next_item_size {
                score += 3.0 * (pr as f64 / cap);
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are
    // fragmented (high mean residual spread) or late in stream with
    // large next item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap - 0.5).abs();
        let new_bin_bonus = -6.0 + 14.0 * fragmentation + 10.0 * progress;
        score += new_bin_bonus;
        if next_item_size > 60 {
            score -= 4.0;
        }
    }

    // Mild preference for filling more-open bins when many are open.
    if open_bins_count > 3 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // Tie-break toward tighter fits overall.
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that cannot fit the lookahead item (when one exists) are
    // likely dead space too — penalize proportionally to how close we are.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post / (next_item_size as f64).max(1.0));
    }

    // Reward tight fits: lower post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // filling existing ones; few open bins -> opening new bins is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when item barely fits
        // nowhere well; penalize when open bins are plentiful and mean
        // residual is large.
        score += 15.0 + 6.0 * pressure - 0.15 * mean_residual;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Room for lookahead pairing in a fresh bin.
            score -= 10.0;
        }
    } else {
        // Existing bin: mild reward scaled by open-bin pressure.
        score -= 2.0 * pressure;
    }

    // Late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the residual left behind,
    // this is an ideal chain placement.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 500.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 150.0;
        }
        // Penalize residuals that are too small for the next item but nonzero
        // (dead space the next item cannot use).
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 40.0 + (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Reward bins whose residual was already tight relative to the mean
    // (prefer packing into bins below-average residual to consolidate space).
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 200.0;
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 250.0; // allow fresh bin for large items when nothing fits
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0; // fresh bin is fine if next item can chain into it
        }
    }

    // Slight preference to fill older/more crowded bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 * (20 - post_residual) as f64 / 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 16.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin; reduced late in the stream
        // or when all open fits would leave large waste.
        score += 22.0 - 8.0 * progress - 10.0 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced: nothing else fits
        }
    } else {
        // Mild preference for filling already-open, low-residual bins.
        score += 0.05 * (mean_residual - bin_residual as f64).max(-20.0);
        // Spread load when many bins are open and this bin is large-residual.
        if open_bins_count > 3 && bin_residual as f64 > mean_residual {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, mildly discounted early (space is cheap early)
    let mut score = pr * (0.6 + 0.6 * progress);

    // Non-linear polynomial coupling: quadratic/cubic waste penalty grows with progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) + norm_pr * norm_pr * norm_pr * (2.0 + 2.0 * progress);
    score += 20.0 * coupling;

    // Perfect / near-perfect fit reward (subtract), amplified by progress
    let fit_quality = 1.0 - norm_pr;
    score -= 6.0 * fit_quality * fit_quality * (1.0 + progress);

    // Lookahead: if next item fits into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = pr - nxt;
            score -= 8.0 * (1.0 - slack_after_next / cap) * (0.5 + progress);
        } else {
            // next item won't fit: penalize leaving a large unusable gap
            score += 4.0 * norm_pr * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // Many open bins: prefer consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + norm_pr) * 2.0;

    // Deviation from mean residual: prefer bins whose residual is close to the post placement need
    score += 0.3 * (mean_residual - pr).abs() * (0.5 + progress);

    // New-bin candidate handling: only attractive for large items or late stream
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / cap) * 30.0;
        score = score - large_item_bonus + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) non-linearly
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class logic: post_residual modulo classes.
    // Residuals that are "usable" for typical small items (divisible into
    // common chunk sizes) are less dead space than prime/awkward residuals.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        0.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr >= 10 && pr % 10 <= 2 {
        -2.0
    } else if pr < 10 {
        10.0 + (10 - pr) as f64 // tiny dead space is nearly unusable
    } else {
        // awkward residual: penalize by distance to nearest multiple of 10
        let d = pr % 10;
        3.0 * d as f64
    };
    score += class_penalty;

    // Lookahead: if the next item fits the post_residual, big reward;
    // also harmonic coupling between post_residual and next_item_size.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // exact modular coupling: next item leaves a clean class again
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 {
                score -= 10.0;
            } else if npr % 5 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: slight penalty, worse if residual is large
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline; prefer existing bins
    // unless this bin would leave very bad residual while a fresh bin wastes nothing.
    if bin_residual == bin_capacity {
        // fresh bin: score = full capacity residual minus small bonus
        score = cap - 5.0;
        // if item is large relative to capacity, a fresh bin is attractive
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 10.0 * (frac - 0.5);
        }
        // if many open bins with high mean residual, prefer reusing them
        score += 0.3 * mean_residual;
    } else {
        // mild bonus for reusing open bins to keep bin count low
        score -= 3.0;
        // penalize opening pressure: if many bins already open, favor reuse more
        score -= 0.1 * open_bins_count as f64;
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A residual below 10 (minimum item size) is pure dead space.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward near-perfect fits (post_residual very small but usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    } else if post_residual > 5 && post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening them
    // rather than spawning more; when few bins open, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // New-bin candidate baseline: neutral-ish score so it only wins when
    // all open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        // Slight preference for new bins early, slight penalty late in stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * 0.5 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
