pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 15.0;
    }

    // Penalize bins whose residual is much larger than the item (wasteful use of a large gap).
    if bin_residual > item_size * 2 {
        score += (bin_residual - item_size * 2) as f64 * 0.3;
    }

    // Lookahead: penalize if post_residual can't fit next item (dead space), reward if it can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if post_residual is a good fit for next item.
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0;
            }
        } else {
            score += (post_residual as f64) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins
    // have poor fits (high mean residual) or few bins can fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = mean_residual / bin_capacity as f64;
        score += 25.0; // baseline cost of opening a bin
        score += open_bins_count as f64 * 2.0;
        if pressure > 0.5 {
            score -= (pressure - 0.5) * 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins; later, allow
    // more openness since future packing matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score += (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual deviates from mean in a useful way (use below-mean bins first).
    if !is_new_bin {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.2;
        } else {
            score += (-dev) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear waste penalty: dead space hurts more as it approaches mid-capacity
    let x = pr / cap;
    score += 12.0 * x * (1.0 - x) * (0.5 + t);

    // Reward tight fits (small post_residual) with smooth quadratic kick
    score -= 20.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: only one fitting bin -> strong preference to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * t;
    }

    // New-bin candidate: penalize opening new bins early, more when many open bins exist
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + t * 10.0);
        score += 25.0 + 5.0 * pressure - 10.0 * t;
        // If next item fits in the fresh bin, mild bonus
        if (next_item_size as f64) <= cap * 0.5 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: penalize residual that can't fit next item, reward residual that can
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins deviating from mean to balance residuals
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left after placement

    // Dead-space penalty: residuals that are unusable for typical items.
    // Class boundaries via integer division thresholds on post_residual.
    let class = post_residual / 10; // harmonic class index (0..10)
    match class {
        0 => score += 60.0,          // 0..9 : nearly perfect fill, reward heavily below
        1 => score += 10.0,          // 10..19: good but not perfect
        2 | 3 => score += 0.0,       // 20..39: neutral zone
        4 | 5 => score += 8.0,       // 40..59: mediocre leftover
        6 | 7 => score += 20.0,      // 60..79: large hole
        _ => score += 35.0,          // 80..99: huge hole, bin wasted
    }

    // Modulo arithmetic coupling: residuals congruent to small values mod capacity
    // quarters are more reusable for common item sizes.
    let q = post_residual % 25;
    if q == 0 { score -= 12.0; }         // exact quarter multiple: highly reusable
    else if q <= 5 { score -= 5.0; }     // near-quarter: decent

    // Lookahead: reward bins whose post_residual fits the next item (chain placement).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // how tightly the next item would fit afterwards
            let next_post = post_residual - next_item_size;
            score -= (next_item_size as f64) * 0.35;
            if next_post == 0 { score -= 25.0; }
            else if next_post <= 10 { score -= 10.0; }
        } else {
            score += 6.0; // next item cannot use this leftover
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (i.e., best post_residual would be large).
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap + 15.0;
        // if the item is small relative to capacity, a new bin wastes little
        score -= (item_size as f64) * 0.4;
        // if many bins fit the item, prefer reusing one of them
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 6.0;
        }
        // late in the stream, discourage proliferation of open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0 + (open_bins_count as f64) * 2.0;
    }

    // Mild pressure to consolidate when many bins are open with high mean residual.
    if bin_residual < bin_capacity {
        score -= (mean_residual - post).max(0.0) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since nothing (min item size 1... but realistically small items are rare) can fill them.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0;
    }
    // Medium dead space that only tiny items could use: moderate penalty.
    if post_residual > 9 && post_residual <= 19 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 9.0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit in post residual, mild penalty proportional to gap.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let waste = (bin_residual - item_size) as f64;
    score += waste * 0.15;

    // New-bin candidate: neutral-ish baseline, slightly penalized so it is only
    // chosen when all open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * (open_bins_count as f64);
    }

    // Late-stream consolidation: as the stream progresses, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual exactly-ish
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.5 * slack; // strong reward for chaining next item
        if slack == 0.0 { score -= 30.0; } // perfect pair
    } else if next_item_size > 0 {
        // next item won't fit here: penalize wasted potential
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Relative-to-mean coupling: bins with residual below mean are precious
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev; // low residual => lower score => favored

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        // but allow new bin if item is large and would leave big dead space anywhere
        if item_size >= 60 && post_residual < 10 {
            score -= 45.0;
        }
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 20.0; // fresh bin can host next item too
        }
    }

    // Early stream: keep bins flexible; late stream: consolidate tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - 2.0 * tightness).abs().powi(3) * (1.0 - tightness);

    // Strong reward when this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining),
    // penalize if next item would leave this bin awkwardly unusable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 8.0; // dead space risk
        }
    }

    // New-bin candidate handling: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let best_open_fit = if fitting_bins_count > 0 {
            (mean_residual - (mean_residual % 1.0)).max(0.0)
        } else {
            100.0
        };
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        // Prefer new bin when fitting bins are scarce or residuals are large/wasteful.
        score += 40.0 - 6.0 * fitting_bins_count as f64 - pressure;
        if post_residual == 0 {
            score -= 15.0; // perfect fit into fresh bin shouldn't happen, but guard
        }
        // Late in the stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Slight preference for filling more-full bins first (best-fit bias).
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
        // If many bins can fit, mildly discourage wasting this one on a loose fit.
        if fitting_bins_count > 2 && tightness > 0.5 {
            score += 5.0;
        }
    }

    // Global balance: prefer bins whose residual is near the mean (keep spread even),
    // unless a very tight fit is available.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: minimize wasted residual, with non-linear (quadratic) growth of waste penalty.
    let mut score = pr + 30.0 * norm_pr * norm_pr;

    // Smooth interaction: residual waste matters more as the stream progresses.
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward tight fits (small post residual) with a smooth cubic decay bonus.
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: bonus if the post residual can host the next item smoothly.
    if nxt > 0.0 && pr >= nxt {
        let fit_quality = 1.0 - ((pr - nxt) / cap);
        score -= 12.0 * fit_quality * (1.0 - progress * 0.5);
    } else if nxt > 0.0 {
        // Post residual too small for next item: smooth dead-space penalty.
        score += 8.0 * (nxt - pr) / cap * (1.0 + progress);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * (1.0 - norm_pr);
    }

    // Penalize bins that are already much emptier than the mean (fragmentation smoothing).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: empty bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable for large items or late in the stream,
        // penalized smoothly otherwise so tight fits into open bins win.
        let openness = 0.5 * item + 0.5 * progress;
        score += 45.0 * (1.0 - openness) + 10.0 * (open_bins_count as f64).sqrt().recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward near-perfect fits (post_residual in lowest capacity fractions)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always best
    } else if post <= cap * 0.1 {
        score -= 60.0;
    } else if post <= cap * 0.2 {
        score -= 25.0;
    } else if post > cap * 0.5 {
        score += 15.0; // leaving more than half empty is wasteful
    }

    // Modulo arithmetic on post_residual: harmonic classes of 10
    let post_class = post_residual % 10;
    if post_class == 0 {
        score -= 8.0; // residual divisible by 10: more likely reusable
    } else {
        score += post_class as f64 * 0.8; // odd dead space penalty
    }

    // Integer division threshold: post_residual / item_size ratio
    if item_size > 0 {
        let ratio = post as f64 / item_size as f64;
        if ratio >= 1.0 {
            score -= 6.0; // room for another same-size item
        }
    }

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0; // chain-friendly placement
        // extra reward if next item also matches harmonic class of residual
        if post_residual % next_item_size.max(1) == 0 {
            score -= 12.0; // residual is an exact multiple of next item
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0; // next item won't fit here; slight penalty
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // current bin would leave large dead space
    if bin_residual == bin_capacity {
        // brand-new empty bin candidate
        score += 30.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: new bin is necessary
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // large upcoming item may need fresh space
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - post) * 0.15;

    // Open bins count: many open bins -> favor consolidation
    if open_bins_count > 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (1)
    // are fine, but residuals that are small yet nonzero relative to the
    // incoming stream are wasteful. Penalize the "awkward gap" band.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: the smaller the post_residual, the better the fit.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else {
        // Non-linear penalty on wasted fraction of the bin.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste_frac * waste_frac;
    }

    // Penalize awkward gaps: post_residual that is small (>0) but unlikely
    // to be usable. If next item cannot fit in the gap, it is dead space.
    if post_residual > 0 && next_item_size > post_residual {
        score += 12.0 + 8.0 * (1.0 - progress);
    } else if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0; // gap is immediately reusable
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // consolidating into existing bins; few open bins -> new bins are cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit, reduced
        // when few bins are open or the current bin's fit is poor.
        score = 40.0 + pressure * 3.0 - 15.0 * (1.0 - progress);
        // If the best alternative leaves a big gap, new bin becomes attractive:
        // handled implicitly since poor fits carry large waste penalties.
    } else {
        score += pressure * 0.5;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Mean residual coupling: bins far below mean residual are "fresher";
    // filling stale (low-residual) bins consolidates space.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect match of next item into the residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 25.0; // exact 2-step match: place here
        } else if pr > nxt {
            let gap = pr - nxt;
            // penalize leftover after hypothetical next placement
            score += 0.35 * gap;
            if gap <= 10.0 {
                score -= 8.0; // near-perfect chain
            }
        } else {
            // next item can't fit here; slight penalty scaled by deficit
            score += 0.15 * (nxt - pr);
        }
    }

    // Compare residual against mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev; // prefer bins with below-average residual (tighter bins)

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins costly unless no good fit exists.
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count > 1 {
            // other open bins fit: only open new bin if fits elsewhere are very loose
            let best_other_loose = post_residual as f64 > 40.0;
            !best_other_loose
        } else {
            true
        };
        if bad_fit {
            score += 60.0; // discourage opening a new bin
        } else {
            score += 15.0; // mild preference for fresh bin over terrible fit
        }
    }

    // Slight pressure as stream progresses to consolidate bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is ideal.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 12.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead (k=2): if the next item fits into post_residual, reward;
    // otherwise penalize leaving exactly a gap that nothing will fill.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Dead space: gap smaller than the smallest plausible item (1..100 unknown dist).
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last chance: this is the only bin that fits the item — strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is
    // large relative to capacity or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // New bins are fine early on; later, only for large items or when no
        // open bin fits well.
        score += 18.0 * progress;
        score -= item_frac * 20.0;
        // If many bins are open and mean residual is large, avoid new bins.
        score += (mean_residual / bin_capacity as f64) * 10.0;
        // If no open bin can fit the item (fitting_bins_count == 0 means only
        // the new-bin candidate was called), accept the new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins with smaller current residual among fitting bins
    // (best-fit style), modulated by global mean residual.
    let rel_res = (bin_residual as f64) / (bin_capacity as f64);
    score += rel_res * 6.0;
    score -= (mean_residual / bin_capacity as f64).min(1.0) * 3.0;

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t2 = t * t;
    let t3 = t2 * t;

    // Normalized post-residual and item size
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;

    // Non-linear coupling: waste penalty grows superlinearly with residual,
    // modulated by stream progress (early: tolerate slack; late: punish it)
    let progress_weight = 0.5 + 1.5 * t2 + 1.0 * t3;
    score += progress_weight * (pr2 * 30.0 + pr3 * 40.0);

    // Reward near-perfect fits smoothly (residual close to 0)
    let fit_quality = (-pr * 6.0).exp(); // ~1 when residual tiny, decays smoothly
    score -= 18.0 * fit_quality * (0.6 + 0.4 * t);

    // Dead-space valley: residual just below typical next item is wasted
    if next_item_size > 0 {
        let nres = next_item_size as f64;
        if (post_residual as f64) < nres {
            let gap = (nres - post_residual as f64) / cap;
            score += 25.0 * gap * (1.0 + t);
        } else {
            // smooth reward if next item could still fit in the leftover
            let room = (post_residual as f64 - nres) / cap;
            score -= 10.0 * room * (1.0 - room.max(0.0));
        }
    }

    // Last-chance bonus: only fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline penalty scaled by how full open bins are
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 + 15.0 * mean_fill * (0.5 + 0.5 * t) + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins below mean residual (consolidate slack)
        let dev = (post_residual as f64 - mean_residual) / cap;
        score += 8.0 * dev;
    }

    // Mild penalty for many open bins (encourage consolidation early)
    score += 0.3 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item-size classes (mod 10) are more likely to be filled later.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 12.0, // perfectly harmonic residual -> very reusable
        5 => 6.0,  // half-class residual still quite reusable
        2 | 4 | 6 | 8 => 3.0, // even class
        _ => 0.0,  // odd class, least reusable
    };
    score -= class_bonus;

    // Integer-division threshold: small post residuals are dead space.
    let dead_zone = bin_capacity / 10; // 10
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual) as f64 * 2.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic match check on classes.
        let harmony = (post_residual % 10) == (next_item_size % 10)
            || post_residual == next_item_size
            || post_residual == next_item_size * 2
            || post_residual == next_item_size * 3;
        let reward = if harmony { 18.0 } else { 9.0 };
        score -= reward * (next_item_size as f64 / 100.0 + 0.5);
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: mild penalty scaled by wasted class.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when the item fits poorly everywhere
    // and open bins are already quite full on average.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        let poor_fit = (post_residual as f64) > item_size as f64 * 0.75;
        if tightness > 0.6 && poor_fit {
            score -= 20.0 * tightness;
        } else {
            score += 15.0 + 10.0 * (1.0 - tightness);
        }
    }

    // Progress-based consolidation: late in the stream, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Discourage spreading across too many open bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // typical items (<= ~10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open or item is large
        // relative to mean residual (poor fit elsewhere).
        score -= pressure * 8.0;
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
    } else {
        score += pressure * 2.0;
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit the post-residual but could fit this bin now,
    // slightly penalize leaving a blocking gap.
    if next_item_size > post_residual as u32 && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space suppression).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain: bin will be closed exactly
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            // reward good secondary fill, penalize leaving awkward slivers
            if frac >= 0.5 {
                score -= 10.0 * frac;
            } else {
                score += 6.0 * (1.0 - frac);
            }
        } else {
            // next item cannot use the residual: penalize large leftover
            score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.08 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * (item_size as f64) / bin_capacity as f64;
        let poor_fit = (post_residual as f64) > 40.0 && fitting_bins_count > 0;
        if poor_fit || crowded > open_bins_count as f64 * 0.9 {
            score -= 8.0 + 5.0 * progress;
        } else {
            score += 25.0; // discourage opening new bins when existing ones suffice
        }
    }

    // Mild preference to consolidate into fewer bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
