    // Penalize dead space: residuals too small for the smallest plausible item.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty for wasting space.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins are well-populated.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
        // If mean residual is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
        // If no open bin really fits well (all residuals small), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild bonus for placing into the emptiest-feeling bins when many bins are open.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        if (bin_residual as f64) > mean_residual + 20.0 {
            score -= 3.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor tight packing);
    // late in the stream, slightly prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * tightness;
    score += 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (good fit), with smooth polynomial shaping
    let mut score = 40.0 * x - 30.0 * x * x + 8.0 * x * x * x;

    // Stream-progress coupling: late in stream, tighten fit preference more aggressively
    let tight = 1.0 + 2.5 * progress * progress;
    score += tight * (1.0 - (1.0 - x) * (1.0 - x)) * 20.0;

    // Dead-space penalty: residual too small to ever be useful (below min item size 1 => none, but near-zero residual wastes)
    if pr == 0 {
        score -= 15.0; // perfect fill reward
    } else if pr < item_size as u32 {
        // residual smaller than current item => likely dead space unless next item fits
        if (next_item_size as f64) > pr {
            score += 10.0 * (1.0 - pr / item_size as f64);
        }
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / pr) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual context: if this bin is far below mean residual, it's a good consolidation target
    let dev = mean_residual - pr as f64;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        // penalty grows with how many bins could fit (prefer reusing)
        score += 18.0 + 6.0 * (fitting_bins_count as f64);
        // but relax late in the stream when fragmentation hurts
        score -= 10.0 * progress;
        // if post residual in this new bin would be tiny relative to next item, discourage
        if next_item_size > 0 && (next_item_size as f64) > pr {
            score += 8.0;
        }
    }

    // Mild pressure to close bins when many are open
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit base: tighter fit wins.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes (divisible into common item sizes), punish dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Residuals expressible as sums of typical small items are reusable.
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Integer-division thresholds: small dead space is wasted.
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 10.0; }
        else if pr <= 40 { score -= 4.0; }
        else if pr <= 60 { score += 2.0; }
        // Very large residual means this bin was barely used.
        if pr > 80 { score += 8.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack < 10 { score += 6.0; } // would create fresh tiny dead space
        } else {
            // Next item cannot follow here; slight penalty if residual becomes stranded.
            if pr < next_item_size && pr < 15 { score += 10.0; }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // are congested (few fitting bins, high mean fill) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0);
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score = 70.0 + 30.0 * congestion - 20.0 * mean_fill - 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin can host the next item too; mild discount.
            score -= 5.0;
        }
    }

    // Mild pressure against bin sprawl: many open bins -> prefer consolidating.
    score += 0.4 * open_bins_count as f64;

    // Slight tie-break noise-free deterministic perturbation by item class.
    score -= 0.01 * (item_size % 7) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residuals too small for the smallest item (1) are pure waste,
    // residuals below a practical threshold (~15) are near-waste.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 + (15 - post_residual) as f64 * 8.0;
    } else if post_residual >= 15 && post_residual < 30 {
        score += 10.0;
    }

    // Reward tightness relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild bonus if next item still fits, penalty scaled by leftover slack
        let nxt_left = post_residual - next_item_size;
        if nxt_left < 15 {
            score += 5.0; // would create new dead space
        } else {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight reward for using this bin now
        score -= 10.0;
    }

    // Last-chance bin: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 80.0 + open_bins_count as f64 * 12.0 + progress * 100.0;
        // But if mean residual of open bins is small (all bins nearly full),
        // opening a new bin is reasonable: soften the penalty.
        if mean_residual < 20.0 {
            score -= 60.0;
        }
    } else {
        // Existing bin: small reward that shrinks as open_bins_count grows.
        score -= 5.0;
    }

    // Coupling: prefer bins with residual below mean (more filled bins).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item fits snugly in post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space: post residual too small for typical future items
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 1.5 * waste;
    }

    // Small unusable residuals are dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Reward filling a bin completely
    if post_residual == 0 {
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins already tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // fresh bin can host the pair
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize leaving residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    if post_residual >= 10 && post_residual <= 25 {
        score -= 4.0; // residual still reusable by typical small items
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Exact pairing bonus: item + next item fills bin almost perfectly.
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if pair_fill > 0.9 && post_residual >= next_item_size {
            score -= 10.0 * (pair_fill - 0.9);
        }
    }

    // New-bin candidate: usually undesirable unless few bins open or fit is scarce.
    if bin_residual == bin_capacity {
        let mut penalty = 20.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            penalty -= 25.0; // no good alternative: opening a bin is fine
        }
        if next_item_size > 0 && next_item_size > post_residual {
            penalty += 5.0;
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 15.0 * progress;
        score += penalty;
    }

    // Mild pressure to fill bins with large residuals (reduce fragmentation).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer bins already below mean residual (keeps residual distribution tight).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1)

    // Base: prefer small post-residual (tight fit), with non-linear shaping
    let mut score = pr;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate slack slightly more; late, penalize waste harder.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (2.0 * p2 - 1.5 * p3) * (x * (1.0 - x)) * cap;

    // Dead-space penalty: post-residual below typical next-item size is wasted space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            let w = 0.5 + 1.5 * progress;
            score += w * gap * (1.0 - x * x);
        } else {
            // bonus: next item could still fit here
            score -= (0.3 + 0.7 * progress) * (-gap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // Mild preference to fill bins when many are open (consolidation)
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - x) * 0.5;

    // Pull toward mean residual: avoid extreme fragmentation relative to fleet state
    score += 0.1 * (pr - mean_residual) * (0.5 + progress);

    // Smooth quadratic penalty for very small residuals (dead space)
    score += (1.0 - x) * (1.0 - x) * cap * (0.2 + 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit with tightness reward
    let tight = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tight;

    // Harmonic classes: reward post_residuals that are "usable" residual classes.
    // Class A: post_residual divisible into nice chunks (multiples of 10/20/25/50)
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        score -= harmony;
        // Small usable residuals are better than awkward mid-size dead space
        if pr <= 10 {
            score -= 8.0;
        } else if pr <= 20 {
            score -= 3.0;
        } else if pr > 60 {
            score += 4.0; // large leftover is fine (still reusable)
        } else {
            // mid-range dead zone: penalize by distance to nearest multiple of 10
            let d = (pr % 10).min(10 - pr % 10) as f64;
            score += 0.8 * d;
        }
    } else {
        score -= 15.0; // perfect closure
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / 40.0).max(0.0);
            // harmonic match: next item divides post_residual
            if pr % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            score += 2.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: make empty bin mildly attractive only when
    // open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score = 45.0
            - 0.15 * open_bins_count as f64
            - 0.3 * mean_residual
            + 0.25 * item_size as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: early on, be conservative with new bins; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - tight);

    // Prefer filling bins when many bins are open (reduce fragmentation)
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer bins whose post-fit residual is either 0 (perfect) or large enough to be reusable.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Dead-space penalty: residuals in the "unusable band" (roughly 1..=15)
        // are pure waste, since future items are >= 1 but small gaps rarely match.
        let dead_band_hi = 15.0f64;
        if pr <= dead_band_hi {
            // Quadratic dead-space penalty, worst near mid-band (gap too big to ignore, too small to use).
            let mid = dead_band_hi * 0.5;
            let depth = (mid - (pr - mid).abs()) / mid; // 0 at edges, 1 at center
            score += 25.0 + 45.0 * depth * depth;
        } else {
            // Usable residual: mild reward, larger residual is more flexible.
            score -= 6.0 * ((pr / bin_capacity as f64).min(1.0));
        }
    }

    // Tight-fit bonus: the item fills a large share of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Deviation from mean residual: prefer bins with SMALL residual (best-fit tendency),
    // but bins with residual far below mean are already near-full -> good targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if (bin_residual as f64) < mean_residual {
        score -= 8.0 * (dev / bin_capacity as f64).min(1.0);
    } else {
        score += 6.0 * (dev / bin_capacity as f64).min(1.0);
    }

    // Lookahead: if the next item can fit into the post residual, this placement is extra valuable.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        // Creating a gap that the known next item cannot use -> penalize.
        score += 12.0;
    }

    // Last-chance pressure: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible, handled above).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    // Applied as a penalty on the NEW-BIN candidate only (bin_residual == bin_capacity),
    // plus a mild global pressure term.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).sqrt() * 3.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure scaled by number of alternatives.
        score += 18.0 + bin_pressure + 4.0 * fitting_bins_count as f64;
        // But if no open bin truly fits well (all would leave dead space), allow the new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        // Perfect 2-step match: huge reward
        if post_residual == next_item_size {
            score -= 100.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: penalize dead space proportionally
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual relative to mean residual of open bins
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 0.5 {
            score -= 15.0 * (0.5 - ratio); // creating small residual is good
        } else {
            score += 10.0 * (ratio - 0.5); // leaving above-average residual is wasteful
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: default cost; open only if existing fits are poor
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in stream, opening new bins is cheaper than fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If next item is large, a fresh bin helps it later
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Many open bins: prefer consolidation into existing bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: exact fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0;
    }
    // Penalize small-but-nonzero residuals more as stream progresses
    // (less time to fill them later).
    let progress = if total_items > 1 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * (0.5 + progress);
    }

    // Lookahead: reward bins whose residual can host the next item
    // (keeps future flexibility), penalize bins that cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 0.1 * next_item_size as f64;
        } else {
            score += 3.0;
        }
        // Perfect chaining: item + next item exactly fills the bin.
        if item_size as f64 + next_item_size as f64 == bin_residual as f64 {
            score -= 200.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when existing residuals are large and scattered (fragmented state).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // More attractive when open bins are already numerous and full-ish.
        let mean_frac = mean_residual / bin_capacity as f64;
        score += mean_frac * 40.0;
        // Early in the stream, prefer reusing open bins.
        score += (1.0 - progress) * 40.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 30.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
    } else {
        // Reusing open bins: mild reward scaled by how full the bin gets.
        let fill_ratio = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fill_ratio;
    }

    // Prefer bins with residual close to the item size (tight fit curve).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Slight preference for consolidating residual mass when many bins open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // Deterministic tie-break via bin residual parity structure.
    score -= (bin_residual % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling: post_residual normalized against capacity
    let r = post_residual as f64 / cap;
    let r2 = r * r;
    let r3 = r2 * r;
    score += 12.0 * r2 - 8.0 * r3 * (1.0 + progress);

    // Reward tight fits (small post_residual) more aggressively as stream progresses
    score -= 20.0 * (1.0 - r) * (0.5 + progress);

    // Penalize unusable dead space: post_residual smaller than plausible smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_term = (gap / cap).powi(2);
        score -= 18.0 * (1.0 - fit_term.min(1.0)) * (1.0 - progress * 0.5);
        // Perfect lookahead fit: strong reward
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // dead space relative to next item
            score += 6.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / cap);
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly when open bins exist with decent residuals,
    // but allow opening when residuals are fragmented
    if bin_residual == bin_capacity {
        let base = 25.0 + 15.0 * progress;
        let fragmentation = if open_bins_count > 0 { (mean_residual / cap).min(1.0) } else { 1.0 };
        score += base * (0.4 + 0.6 * fragmentation);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to fill bins with larger residuals less when many bins are open
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * r2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-exact fits: heavily reward small dead space.
    if post_residual <= 3 && post_residual > 0 {
        score -= 60.0 + (3 - post_residual) as f64 * 20.0;
    } else if post_residual <= 10 {
        score -= 15.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Harmonic classes: residual dead space that is a multiple of common
    // item sizes is more likely reusable later.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 {
            score -= 12.0; // round residual likely matchable
        } else if r % 5 == 0 {
            score -= 6.0;
        }
        // Dead space smaller than the minimum item size is truly dead.
        if r < 10 {
            score += 25.0 * (10 - r) as f64;
        }
        // Integer division thresholds: large leftover halves are valuable.
        if r >= bin_capacity / 2 {
            score -= 8.0;
        } else if r >= bin_capacity / 4 {
            score -= 3.0;
        } else {
            score += 5.0;
        }
    }

    // Lookahead: if the next item fits the post-residual exactly or well,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        if lookahead_waste == 0 {
            score -= 80.0;
        } else if lookahead_waste <= 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use leftover: mild penalty proportional to gap.
        score += ((next_item_size - post_residual) as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && !(bin_residual == bin_capacity) {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins
    // would create bad fits.
    if bin_residual == bin_capacity {
        // Base preference against opening bins.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Large items relative to capacity are fine to start a fresh bin.
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // If lookahead next item is large and this item is small,
        // keeping current bins tight is better.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && item_size <= 20 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Slight preference for tighter existing bins (best-fit bias).
        score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;
    }

    // Prefer placing into bins among many fitting bins by tightness.
    if fitting_bins_count > 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space): residual after placement that
    // is too small to be useful but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (near-zero post residual) strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Nonlinear penalty proportional to wasted fraction of the residual.
        let waste_frac = post_residual as f64 / bin_residual.max(1) as f64;
        score += 15.0 * waste_frac * waste_frac;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and remaining stream.
        score += 20.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins that reduce variance (fill the fullest).
    score += 3.0 * (bin_residual as f64 - mean_residual).max(0.0) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) with a strong discount.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post-residual, penalize when it leaves a large unusable gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= (10 - gap) as f64 * 3.0;
            } else {
                score += gap as f64 * 0.5;
            }
        } else {
            // Next item cannot fit here; slight penalty for wasting the slot.
            score += 8.0;
        }
    }

    // Compare residual against mean residual across open bins: prefer bins
    // that are already well-filled (low residual) to consolidate load.
    let residual_gap = post_residual as f64 - mean_residual;
    score += residual_gap * 0.3;

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and open bins are mostly full, or there are very few open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        let item_large = item_size as f64 > 60.0;
        let bins_tight = mean_residual < item_size as f64 * 1.2;
        let mut new_bin_penalty = 40.0 + open_pressure * 2.0;
        if item_large && bins_tight {
            new_bin_penalty -= 30.0;
        }
        if open_bins_count == 0 {
            new_bin_penalty = -50.0; // must open first bin
        }
        if progress > 0.9 && bins_tight {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference to keep some spread of residuals early in the stream.
    if open_bins_count > 3 && post_residual as f64 > mean_residual + 40.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fills get a strong discount.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 2.0 * tightness * tightness * (item_size as f64);
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when fits are poor
    // or the stream is early and open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64; // = capacity - item for new bin
        // Base penalty keeps new bins behind decent fits.
        score += 25.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
        // But if all open bins would leave big gaps, new bin becomes attractive.
        if fitting_bins_count > 0 {
            let avg_gap = mean_residual / fitting_bins_count.max(1) as f64;
            if avg_gap > (item_size as f64) * 1.5 {
                score -= 35.0;
            }
        }
        let _ = fit_quality;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor),
        // modulated by global mean residual.
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += 0.2 * diff;
        if (bin_residual as f64) < mean_residual {
            score -= 5.0; // favor bins tighter than average
        }
    }

    // Mild time-horizon shaping: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: penalize post residual with non-linear growth (dead space matters more as it grows)
    let mut score = post + 40.0 * norm_post * norm_post;

    // Reward tight fits: smooth polynomial coupling of fit quality with stream progress
    let fit_quality = 1.0 - norm_post;
    score -= 30.0 * fit_quality * fit_quality * fit_quality * (0.5 + t);

    // Last-chance bonus: only one fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead: reward bins whose post residual could host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // penalize wasting the bin so the next item cannot fit
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Slight preference for bins deviating from mean residual (balanced consolidation)
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Late-stream: discourage opening new bins when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions (quarters)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Reward bins whose post_residual lands in "usable" harmonic classes
    // (multiples of common item sizes / capacity fractions).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // Class of post_residual via integer division thresholds
        let class = post_residual / quarter; // 0..4
        match class {
            0 => score -= 25.0,           // tiny leftover: near-perfect fit
            1 => score += 5.0,            // quarter-ish leftover: awkward zone
            2 => score -= 10.0,           // half leftover: very reusable
            _ => score -= 2.0,            // large leftover: moderately reusable
        }

        // Modulo coupling: post_residual divisible by common item granularity
        let m = post_residual % 10;
        if m == 0 {
            score -= 8.0;
        } else {
            score += m as f64 * 0.7; // ragged remainders are dead space
        }

        // Harmonic match with next item (lookahead): post_residual classes
        // that can host the next item are valuable.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // next item fits exactly into this residual?
                if post_residual == next_item_size {
                    score -= 30.0;
                } else {
                    let slack = (post_residual - next_item_size) as f64;
                    score -= (20.0 - slack.min(20.0)) * 0.8;
                }
            } else {
                // next item won't fit here; residual becomes a trap if small
                if post_residual < 10 {
                    score += 15.0;
                }
            }
        }

        // Exact half-capacity class bonus
        if post_residual == half {
            score -= 12.0;
        }
        if post_residual == three_quarter || post_residual == quarter {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.5 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        score += 45.0 - pressure.min(40.0);
        // if the item would leave a bad harmonic class elsewhere, opening fresh is fine
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
    }

    // Slight preference to fill fuller bins (tight packing)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Mean residual anchoring: prefer bins near the mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Dead-space penalty: gaps that are too small for any future item ----
    // Smallest possible item is 1; a post_residual of exactly 0 is a PERFECT fit.
    if post_residual == 0 {
        score -= 60.0; // perfect fill, strongly reward
    } else if post_residual < 10 {
        // Unusable dead space: gap below the minimum plausible item size.
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 30 {
        // Small-ish gaps are risky: only usable by small items.
        score += (30 - post_residual) as f64 * 1.5;
    }

    // ---- Tight-fit reward: item fills a large fraction of the residual ----
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 25.0;
        } else if fill_ratio > 0.7 {
            score -= 12.0;
        } else if fill_ratio < 0.3 {
            // Dumping a small item into a big bin wastes capacity.
            score += 10.0;
        }
    }

    // ---- Lookahead: does post_residual still fit the next item? ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Gap remains usable for the known next item: reward.
            score -= (next_item_size as f64) * 0.3;
        } else {
            // This placement kills the bin for the immediate next item.
            score += 15.0;
        }
    }

    // ---- Last-chance bin: if this is the only bin that fits, avoid opening a new one ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // ---- Open-bin pressure: consolidate into fewer bins when many are open ----
    score += open_bins_count as f64 * 0.5;

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well.
        // Penalize it so we prefer reusing, unless the stream is early and
        // open bins are nearly full (high mean fill).
        let mean_fill = bin_capacity as f64 - mean_residual;
        if mean_fill > 0.75 * bin_capacity as f64 {
            score -= 30.0; // open bins nearly full: a fresh bin is fine
        } else {
            score += 45.0; // strongly prefer existing bins
        }
        // Early in the stream, allow more bins for flexibility.
        score -= (1.0 - progress) * 10.0;
    }

    // ---- Mean residual coupling: prefer bins below mean residual (fuller bins) ----
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // 2-step lookahead: strongly reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect match bonus; decay with gap size.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasted residual proportional to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.4 * overshoot;
        }
    }

    // Dead-space penalty: residual too small to ever be useful (min item 1..100, be safe with < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it unattractive unless the fit here is terrible
    // and many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 120.0; // no open bin fits: must open new bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space that few future items (min size 1) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny slivers are nearly dead space
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0; // mid residuals are reusable
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively
    // (fewer new bins), earlier, allow exploration.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - fill_ratio);

    // Global pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.3 * mean_residual;
    }

    // New-bin candidate logic: only attractive when the item is large and
    // no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64;
        // Opening a new bin is good for big items when open bins are fragmented,
        // bad when item is small or open bins are mostly empty.
        score += 45.0 - 55.0 * large - 2.0 * pressure * (mean_residual / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items together in fresh bins
        }
    }

    // Mild preference for bins with residuals close to the item (exactness).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: squared normalized dead space
    let dead = pr / cap;
    score += 12.0 * dead * dead * (1.0 + 2.0 * progress);

    // Reward tight fits: smooth sigmoid-like coupling of item size
    let tight = item / cap;
    score -= 6.0 * tight * tight * (1.0 - dead);

    // Last-chance bonus (smooth, not piecewise)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 8.0 * last_chance * (1.0 - progress);

    // Lookahead coupling: prefer bins whose post_residual pairs with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score += 4.0 * gap * gap;
        // exact match reward, smooth
        let match_f = (-gap * gap * 20.0).exp();
        score -= 5.0 * match_f;
    }

    // Pressure from many open bins: favor filling existing bins
    let pressure = (open_bins_count as f64).ln() / (1.0 + (mean_residual / cap).ln());
    score -= 2.0 * pressure * (0.5 + progress);

    // Mild preference to keep mean residual balanced
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate: penalize opening a bin unless residuals are tight
    let is_new = if (bin_residual as f64 - cap).abs() < 1e-6 { 1.0 } else { 0.0 };
    let avg_fill = 1.0 - mean_residual / cap;
    score += is_new * (3.0 + 10.0 * avg_fill * avg_fill * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class logic: classify post_residual into modular residue classes.
    // Residues divisible by common item-size steps (e.g. 10, 20, 25) are "usable"
    // future slots; odd/tiny residues are dead space.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        40.0
    } else if pr % 10 == 0 {
        12.0
    } else if pr % 25 == 0 {
        10.0
    } else if pr % 5 == 0 {
        4.0
    } else {
        -6.0 // awkward residue: penalize
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: small dead space (< 10) is nearly unusable.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot fit in post residual but could fit elsewhere, mild penalty.
    if next_item_size > pr {
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; discount the penalty for large items late in stream.
        score += 25.0 - 20.0 * large_item * (0.5 + 0.5 * progress);
        // If many open bins already have large mean residual, avoid adding more bins.
        score += 0.05 * mean_residual;
        // But if no open bin fits well (post_residual would be tiny in others),
        // opening new is fine: counteract via open_bins_count fragmentation signal.
        if open_bins_count > 0 && (mean_residual / bin_capacity as f64) < 0.15 {
            score -= 10.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    // Slight global pressure: keep scores centered so comparisons stay meaningful.
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals that are too small to fit any
    // plausible future item (items >= 1) are wasted; small gaps (1..10)
    // are the worst since nothing from a broad distribution fits.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few
    // open bins, tolerate new bins less.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate handling: an empty bin has full residual; make it
    // attractive only when the fit here would leave a large unusable gap
    // or the next item cannot use the post residual.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin, modulated by context.
        score = 45.0;
        if fitting_bins_count <= 1 {
            score -= 30.0; // nothing else fits well; open a bin
        }
        if post_residual > 0 && post_residual < 10 {
            score += 50.0; // opening a bin for a tiny item is wasteful
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // next item can still use this fresh bin
        }
        score += step_index as f64 / (total_items.max(1) as f64) * 5.0;
    } else {
        // Lookahead coupling: if next item exactly fits the post residual,
        // reward this placement strongly (chain packing).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 45.0;
            } else if next_item_size <= post_residual {
                score -= 8.0;
            } else {
                score += 5.0; // next item cannot use the gap
            }
        }
        // Prefer bins whose residual is close to the mean (balanced state),
        // penalize outliers creating fragmented capacity.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post residual is good; penalize relative to capacity
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += post_frac * 50.0;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how tight it is
            let slack = (post_residual - next_item_size) as f64;
            score -= (100.0 - slack.min(100.0)) * 0.8;
        } else {
            // next item does not fit: penalize wasted lookahead opportunity
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(100.0) * 0.5;
        }

        // Next item fits into post_residual AND would leave tiny remainder again
        if post_residual >= next_item_size {
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 150.0;
            }
        }
    }

    // Compare residual against mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Prefer filling bins when many bins are open (bin consolidation)
    score += open_bins_count as f64 * 0.5;

    // Slight early-stream preference for opening bins to spread items
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // New bin candidate: only attractive if no open bin offers a good fit
    if bin_residual == bin_capacity {
        // penalize opening a new bin generally
        score += 120.0;
        // but if lookahead item is large and current item leaves big residual, new bin is fine
        if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 * 1.5 {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Exact / near-exact fill is excellent.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: favor bins whose post residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // even better if next item fills it well
        let next_left = post_residual - next_item_size;
        if next_left < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0;
        // Opening bins is slightly more acceptable late in the stream.
        score -= 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins with residuals below the mean (consolidate fuller bins).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress) - 1.5 * norm_pr * norm_pr * (1.0 - progress);

    let mut score = pr * (1.0 + 0.6 * progress) - 2.0 * pr * pr / cap;

    // Tight fit bonus, stronger late in stream
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small to be useful
    let small_gap = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * 2.0 } else { 0.0 };
    score += small_gap;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0;
        }
    }

    // Prefer bins with lower residual relative to mean when many bins open
    score += 0.05 * (pr - mean_residual) * (1.0 + open_bins_count as f64 / 10.0);

    // New-bin candidate: make it mildly unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    let _ = poly;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions / modulo classes) ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Penalize post-residuals that fall into "dead" harmonic classes:
    // residues that few plausible item sizes can fill.
    let mod16 = post_residual % 16;
    let dead_penalty = match mod16 {
        0 => -8.0,             // perfectly divisible class: reusable
        1 | 2 | 3 => 6.0,      // tiny slivers: near-dead space
        4 | 5 | 6 | 7 => 3.0,  // awkward small class
        8 | 9 | 10 | 11 => 1.0,
        _ => -1.0,             // larger classes still usable
    };
    score += dead_penalty;

    // Integer-division threshold: post_residual below min item size is pure loss.
    if post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // --- Lookahead coupling: does next item fit into the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward exact or near-exact chaining (harmonic match).
            let gap = post_residual - next_item_size;
            score -= 12.0 - gap as f64 * 0.35;
            if gap == 0 {
                score -= 15.0; // perfect pairing bonus
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted opportunity.
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.08;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 2.0;
    }

    // --- Tight fit reward: filling most of the bin is good ---
    let fill = 1.0 - frac;
    score -= 6.0 * fill * fill;

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; opening a new bin is costly.
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Competition among fitting bins: prefer tighter fits more strongly.
        score += 2.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: only attractive when open bins
        // have poor residuals or are too fragmented.
        score = cap * 0.92;
        let avg_bad = mean_residual < (item_size as f64 + 8.0);
        if avg_bad {
            score -= 14.0; // open bins can't usefully absorb the item
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // A new bin can host a perfect pair with the lookahead item.
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits anywhere; must open
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // --- Mild pressure to consolidate when many bins are open ---
    score += (open_bins_count as f64).sqrt() * 0.6;

    // Prefer bins whose residual deviates from the mean in a useful (small) way.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future items
    // are pure waste. Penalize post_residual in the "dead zone" (1..=10) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger usable gaps: mild reward scaled by reusability.
        score -= 5.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += 1.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // (keeps bin states homogeneous), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Lookahead: if the next item fits into post_residual exactly or well,
    // reward leaving that gap; if next item cannot use the gap, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 30.0; // chain fit: excellent
            } else {
                score -= 8.0;
            }
        } else {
            score += 10.0; // gap unusable by next item
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine for large items but wasteful for small ones
        // when other bins fit; add a base cost that tight fits / last-chance
        // bonuses in existing bins can overcome.
        score += 55.0;
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fills (small dead space relative to what was consumed).
    let used = bin_capacity as f64 - post_residual as f64;
    score -= used.sqrt() * 2.0;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - ni).abs() < 1.0 {
            // Perfect: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mild reward scaled by its size.
            score -= 15.0 * (ni / 100.0);
        } else {
            // Dead space relative to the lookahead item: penalize.
            score += (ni - pr).min(30.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize mildly so we
    // prefer existing bins, but relax when few bins fit (avoid trapping items).
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
        if fitting_bins_count <= 2 {
            score -= 25.0;
        }
    }

    // Prefer residuals consistent with the fleet average (keeps bins uniform).
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fills are perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that can no longer hold typical small items.
        let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += dead * 2.0;

        // Lookahead: if next item fits into the post-residual, reward this bin.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0 + 0.5 * next_item_size as f64;
            } else {
                // Next item won't chain here; penalize proportionally to waste.
                score += 0.3 * (post_residual as f64);
            }
        }

        // Last-chance bin: strongly favor using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Time horizon: early in the stream, prefer consolidating into open bins;
        // late in the stream, tightness matters more than opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);

        // Crowding: many open bins -> encourage filling existing ones.
        score += 3.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

        // Compare residual against mean residual: bins with less-than-average
        // residual are "drier" and should be prioritized.
        score -= 0.4 * (mean_residual - post_residual as f64);

        // New-bin candidate handling: only attractive when nothing fits well.
        if bin_residual == bin_capacity {
            let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
            let large_next = if next_item_size >= 60 { 1.0 } else { 0.0 };
            // Base penalty keeps new bins behind decent existing fits.
            score += 25.0
                - 30.0 * scarcity
                - 10.0 * large_next
                - 10.0 * progress;
            // If existing fits are all poor (post_residual small but nonzero),
            // opening fresh space becomes competitive.
            if post_residual < item_size as f64 * 0.5 {
                score -= 15.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: wasted space after placement
    let mut score = post;

    // Non-linear penalty on dead space: small residuals are hard to fill
    let r_norm = post / cap;
    score += 30.0 * (1.0 - r_norm) * r_norm * r_norm;

    // Smooth coupling with stream progress: prefer tight fits later in the stream
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 25.0 * progress * tightness * tightness;

    // Reward filling bins whose residual closely matches the item (smooth kernel)
    let match_kernel = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
    score -= 20.0 * match_kernel * match_kernel;

    // Lookahead: penalize if next item would not fit the post residual
    if next_item_size > 0 {
        let gap = next_item_size as f64 - post;
        if gap > 0.0 {
            score += 8.0 * (gap / cap) * (1.0 + progress);
        } else {
            score -= 5.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild diversity pressure toward mean residual
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit).
    let mut score = pr;

    // Harmonic class of post-residual: small residues that are "usable"
    // for typical small items get a bonus; awkward dead zones get penalized.
    let res = post_residual;
    let class = res % 10;
    if res == 0 {
        score -= 30.0; // perfect fit
    } else if res <= 10 {
        score -= 12.0; // near-perfect, likely unusable anyway
    } else if res <= 25 {
        score -= 4.0; // still quite usable for small items
    } else if res <= 50 {
        score += 1.0;
    } else {
        score += 3.0; // large residue: could have hosted a bigger item elsewhere
    }
    // Modulo-10 penalty: residues like 11..19 are prime dead space for items
    // drawn in multiples of 10; reward residues divisible by 10.
    if class == 0 && res > 0 {
        score -= 3.0;
    } else if class != 0 && res > 10 && res < 90 {
        score += (10 - class) as f64 * 0.3;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 14.0 - slack * 0.1;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Slight penalty if this placement wastes space the next item could use.
        let waste = (next_item_size as f64 - pr).min(20.0);
        score += waste * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish, but discourage opening new bins when
    // existing bins are fairly empty relative to mean residual.
    if bin_residual == bin_capacity {
        score += 8.0;
        if open_bins_count > 0 {
            score += (mean_residual / cap) * 10.0;
        }
    } else {
        // Favor bins with residual close to item (relative tightness).
        let tight = 1.0 - (pr / cap);
        score -= tight * 2.0;
    }

    // Late in the stream: consolidate more aggressively into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
    } else {
        score += progress * 4.0;
    }

    // Penalty proportional to number of bins that also fit (prefer leaving
    // other options open when this fit is loose).
    if fitting_bins_count > 1 && pr > 20.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fill
    } else if post_residual <= 10 {
        score += 60.0; // tiny dead gap: highly undesirable
    } else if post_residual <= 25 {
        score += 25.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // If the NEXT item fits exactly in post_residual, strongly favor this bin (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        score -= 30.0 - (chain_gap as f64) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual cannot host the next item: penalize proportionally
        score += 15.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 3.0;

    // Prefer bins below mean residual (fill the emptier ones less; favor tighter-than-average bins).
    score -= 2.0 * (mean_residual - bin_residual as f64);

    // New-bin candidate: empty bin. Attract it only when no open bin offers a good fit
    // (i.e., this call itself would otherwise score poorly due to large post_residual),
    // but penalize it when open bins are plentiful and stream is late.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        score += base_penalty;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does next item exactly fill the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chain two items perfectly
        } else if next_item_size <= post_residual {
            // next item fits too: small post residual is still useful
            score -= 40.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize wasted space
            score += 30.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64 * 0.1;
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits with a strong non-linear bonus.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    if fit_ratio >= 0.999 {
        score -= 1000.0;
    } else if fit_ratio > 0.75 {
        score -= 40.0 * (fit_ratio - 0.75) / 0.25;
    }

    // Penalize small dead space that nothing (min size 1) can still use well:
    // very tiny post-residuals are wasted capacity.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would not fit here anyway, mild penalty for wasting space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size > post_residual {
            score += 0.05 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.02 * (post_residual - next_item_size) as f64;
        }
    }

    // Time horizon: early in the stream, be conservative (favor keeping
    // residuals balanced); late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.10 * (post_residual as f64 - mean_residual).abs();

    // Many open bins: discourage spreading; prefer tighter residual bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64
            - 150.0 * pressure
            - 20.0 * (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the last fitting bin
        }
        if progress > 0.9 {
            score += 30.0 * progress; // late stream: avoid new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) emphasis
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: residual tightness matters more as stream progresses
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward tight fits relative to mean residual (smooth sigmoid-like coupling)
    let mean_norm = mean_residual / cap;
    let tight = 1.0 - norm_pr;
    score -= 25.0 * tight * (1.0 - mean_norm) * (1.0 - mean_norm);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + 0.5 * progress);
    }

    // Lookahead: penalize leaving residual that fails next item, reward match
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // next item can still fit: reward smooth slack match
            let gap = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - gap * gap);
        } else {
            // next item cannot fit: penalize proportionally to wasted space
            score += 10.0 * (nxt - pr) / cap * 100.0;
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    // Prefer bins whose residual is close to item size (smooth coupling)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 30.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of the post residual: which quarter of the bin remains.
    let quarter = (bin_capacity / 4).max(1);
    let class = (post_residual / quarter) as f64; // 0..=4
    // Within-class harmonic refinement: 1 / (1 + remainder) style decay
    let rem = (post_residual % quarter) as f64;
    let harmonic = 1.0 / (1.0 + rem / quarter as f64);

    // Base score: prefer small post residual, but reward leaving a class
    // boundary that can still host a "harmonic partner" size.
    let mut score = post * 0.9 - class * 6.0 + harmonic * 3.0;

    // Dead-space penalty: residuals that no item (1..=100) pairs well with.
    // Post residual in (0,10) is nearly unusable -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Sweet spots: residual >= 50 keeps two-halves potential; >= 25 keeps quarters.
    if post_residual >= 50 {
        score -= 8.0;
    } else if post_residual >= 25 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next fits but imperfectly: penalize proportionally to waste
            let waste = (post_residual - next_item_size) as f64;
            score += waste * 0.35;
        } else {
            // next item won't fit here: slight reward for tight packing now
            score -= (post_residual / (bin_capacity / 10).max(1)) as f64 * 1.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): should only win when open bins fit badly.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalize slightly so a decent existing fit wins,
        // but reward when existing bins are scarce or residuals are tiny.
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if open_bins_count > 0 {
            let avg_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score -= avg_tightness * 15.0;
        }
        // Early in stream, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild pressure to keep mean residual spread healthy.
    score += (mean_residual - post).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 9 {
            // Tiny dead space: nearly wasted capacity -> big penalty.
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual <= 20 {
            // Moderately poor gap (items are >= 10, so gap < 10 is truly dead;
            // gaps 10..20 only fit the smallest items) -> moderate penalty.
            score += (20 - post_residual) as f64 * 3.0;
        } else if post_residual >= 30 {
            // Large usable residual is good: reward it.
            score -= post_residual as f64 * 0.35;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward filling bins tightly relative to current item size.
    score -= (item_size as f64 / bin_residual as f64) * 25.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 9.0 {
            score -= 20.0; // next item will seal this bin nicely
        } else {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover gap: penalize creating it.
        score += 8.0;
    }

    // Late in the stream, avoid leaving many half-empty bins around.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.1 * progress;

    // New-bin candidate: neutral baseline so it wins only when all open
    // bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a fit where the NEXT item also fits snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.35 * gap; // perfect 2-step match gets biggest bonus
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize dead space, worse if very small.
        let dead = post_residual as f64;
        score += 0.25 * dead * (1.0 - dead / bin_capacity as f64);
    }

    // Compare post_residual against mean residual: keep bins balanced-ish,
    // but prefer filling bins that are already below average.
    if (post_residual as f64) < mean_residual {
        score -= 0.4 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * ((post_residual as f64) - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Late in the stream, tighten packing (avoid leftover slivers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    // New-bin candidate: neutral baseline, slightly penalized so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.2 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is a good home for the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Penalize dead space that can never fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small slivers are fine
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Time horizon: early in stream, be more selective (penalize waste);
    // late in stream, just pack anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Global state coupling: if mean residual is high, prefer filling fat bins.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * large;
        if fitting_bins_count > 0 {
            score += 15.0; // discourage opening when alternatives exist
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin accommodates lookahead
        }
    }

    // Prefer bins that are already somewhat full (consolidation).
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    // Mild penalty for proliferating bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let item = item_size as f64;

    // Base: reward small post-residual with a quadratic shaping
    let mut score = norm_post * norm_post * cap;

    // Smooth coupling: as stream progresses, penalize residual more strongly
    score += 18.0 * norm_post * (progress * progress);

    // Reward tight fits (low post residual relative to item size) with smooth term
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Penalize near-mean residuals (avoid fragmentation clustering)
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev * cap * 0.1;

    // Last-chance bonus: smooth exponential-style reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 25.0 * tightness;
    }

    // Lookahead coupling: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs() / cap;
        score += 10.0 * gap * gap * cap * 0.05;
        // Smooth reward when next item fits exactly into post residual
        let fit_next = ((post - nxt).max(0.0) / cap).powi(2);
        score -= 8.0 * (1.0 - fit_next) * tightness * progress;
    }

    // Mild penalty for opening new bins late in the stream (smooth ramp)
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 5.0 + 15.0 * progress * (1.0 - tightness);
    }

    // Smooth open-bin pressure: more open bins -> favor filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals that are multiples of
    // common item sizes (gcd-friendly classes) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_frac = 1.0 - pr / cap;

    // Reward high fill fraction non-linearly (best-fit core with a boost).
    score -= 12.0 * fill_frac * fill_frac;

    // Perfect or near-perfect closure gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Harmonic class penalty: leftover space in awkward modular classes
    // (small odd remainders) tends to be dead space. Penalize residuals
    // that are tiny but nonzero, and residuals not divisible by 10.
    let class = post_residual % 10;
    if class != 0 && post_residual > 0 {
        score += 6.0;
        if class <= 3 {
            score += 5.0; // 1..3 units of dead space is worst
        }
    }

    // Lookahead coupling: if the next item exactly matches the post
    // residual, this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // next item still fits: mild reward proportional to reuse
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize more if this bin was
            // the only fitting option (forced choice anyway).
            if fitting_bins_count == 1 {
                score -= 8.0;
            } else {
                score += 7.0;
            }
        }
    }

    // Last-chance bin logic: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // relative to the item (mean residual much smaller than item size).
    if bin_residual == bin_capacity {
        let gap = item_size as f64 - mean_residual;
        if gap > 0.0 {
            score -= 10.0 + gap * 0.3;
        } else {
            score += 20.0; // open bins already accommodate well
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // avoid bin proliferation
        score += open_bins_count as f64 * 1.5;
    }

    // Mild tie-break: prefer bins whose residual is below the mean
    // (consolidating space into fewer, tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if no plausible future item (min size 1, but realistically
    // small items) can use it; treat gaps below a threshold as waste.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        // unusable sliver: heavily penalize
        score += (10.0 - gap) * 8.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but exact fit best).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that the lookahead item can exactly fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 5.0; // gap still usable by lookahead
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // gap unusable by lookahead
    }

    // Prefer filling bins that are already fairly full (tight packing).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    // Open-bins pressure: when many bins are open, discourage opening more
    // (new empty bin has bin_residual == bin_capacity, fill_ratio == 0).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 6.0 * (1.0 - fill_ratio);

    // Last-chance bonus: if this is the only bin that fits, avoid wasting it
    // unless the fit is very tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Slight preference toward bins below mean residual (balance residuals),
    // keeping a pool of large gaps for large future items.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Mild stream-progression term: later in stream, favor tighter fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= fill_ratio * progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: next item exactly fills the bin after this placement.
    if next_item_size > 0 {
        if post_residual as i64 == next_item_size as i64 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it would fill afterwards.
            let after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: penalize dead space.
            score += 15.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: only this bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when nothing sensible is available.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let bad_fit = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 30.0 * pressure - 10.0 * progress + 20.0 * bad_fit;
    }

    // Slight preference for filling bins early in the stream.
    score += 0.05 * (1.0 - step_index as f64 / total_items.max(1) as f64) * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer small post_residual.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a huge bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving dead space that no typical item (>=1) could use:
    // small post_residual is good; moderate residuals are risky.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-dead space, but at least it's small
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Scarcity pressure: few fitting bins relative to open bins -> consolidate.
    if open_bins_count > 0 {
        let scarcity = 1.0 - (fitting_bins_count as f64 / open_bins_count as f64);
        score -= 10.0 * scarcity;
    }

    // Lookahead: reward a bin whose post_residual can host the next item.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
            // Extra reward if next item fits almost exactly afterwards.
            let after_next = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - after_next / cap).max(0.0);
        } else {
            score += 5.0; // would strand this bin's space
        }
    }

    // New-bin candidate logic: empty bin gets base residual=cap, but we
    // penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in stream, opening bins is cheap; later, avoid it.
        let open_penalty = 25.0 + 45.0 * progress;
        // If mean residual is high, open bins are underused -> don't open more.
        let underuse = (mean_residual / cap).max(0.0);
        score += open_penalty + 20.0 * underuse;
        // If nothing fits except this new bin, the fitting count includes it;
        // soften when it's genuinely the only option.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild consolidation preference: bins below mean residual are emptier;
    // prefer filling emptier bins to balance residuals? Prefer fuller bins
    // (small residual) to close them out.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base cost: wasted space, amplified non-linearly as stream progresses
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Smooth polynomial coupling: dead-space penalty grows super-linearly
    score += cap * 2.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly early on
    score -= cap * 1.2 * (1.0 - x) * (1.0 - x) * (1.0 - progress * 0.5);

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let nx = next_item_size as f64 / cap;
        score -= cap * (0.8 + 1.0 * progress) * (1.0 - nx) * (1.0 - nx);
    } else if next_item_size > 0 {
        // Next item likely needs a new bin anyway; slight penalty
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-average residual (concentrate waste)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity quarters
    let q = post_residual / (bin_capacity / 4).max(1);
    match q {
        0 => score -= 30.0,           // near-perfect fill
        1 => score -= 10.0,           // decent leftover
        2 => score += 5.0,            // mediocre
        _ => score += 15.0,           // large dead space
    }

    // Parity/harmonic coupling: post_residual divisible by common item classes
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins are reasonably full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 20.0 + 30.0 * (1.0 - progress);
        if mean_residual < item_size as f64 * 1.5 {
            score -= 15.0; // existing bins are tight; new bin OK
        }
    }

    // Favor fuller bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is worthless
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit is excellent
        score -= 40.0;
    }

    // Reward using a bin whose residual was already small (consolidation).
    let tightness = (bin_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * 15.0;

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // rather than opening more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use this gap; penalize gap smaller than typical items
            score += 12.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (fill below-mean-residual bins first to compact them).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-ish but slightly penalized so we only
    // open a new bin when existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.2;
        if post_residual < 10 {
            score += 45.0; // opening a new bin with a large item wastes it
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild normalization.
    let cap = bin_capacity as f64;
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / cap));

    // 2-step lookahead: strongly reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect = (post_residual as f64 - next_item_size as f64).abs() < 0.5;
        if perfect {
            score -= 40.0; // chain fit: this bin will be perfectly closed next step
        } else if next_item_size as u32 <= post_residual {
            score -= 15.0 * (1.0 - diff / cap);
        } else {
            // next item won't fit here: penalize leaving large unusable residue
            score += 0.3 * (post_residual as f64).sqrt();
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but scale down late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 20.0 - 10.0 * progress;
        if fitting_bins_count == 0 { nb = -5.0; } // fallback: must open
        if next_item_size > 0 && next_item_size <= item_size.saturating_sub(0) && post_residual >= next_item_size {
            nb += 5.0; // fresh bin can absorb next item too
        }
        score += nb;
    }

    // Slight preference to fill bins that are already quite full.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize wasted space quadratically.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Penalize large dead space that becomes unusable (post_residual < 10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // fits are poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let poor_fits = (post_residual as f64 - bin_capacity as f64) < 15.0;
        if poor_fits {
            score -= 15.0; // prefer fresh bin when fits are bad
        } else {
            score += 35.0; // discourage new bin when decent fits exist
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 5.0 * (1.0 - progress);
    }

    // Late in the stream, prefer bins that keep residuals near multiples of small items.
    if progress > 0.7 && post_residual >= 10 && post_residual <= 20 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post_residual (tight fit), with non-linear sharpening
    let mut score = x * (1.0 + 2.0 * x * x);

    // Smooth polynomial coupling with stream progress: late in stream, value tight fits more
    let prog_term = 1.0 + 1.5 * progress * (1.0 - x);
    score *= prog_term;

    // Penalize dead space relative to next item: if next item can use the residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 1.0 * (nxt / cap) * (1.0 - progress);
        } else {
            // residual too small for next item: penalize quadratically if very small
            score += 0.8 * (1.0 - x) * (1.0 - x);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
