    }

    // Mild penalty for spreading across many open bins vs mean residual
    let mr = mean_residual / cap;
    score += 0.3 * (x - mr).abs();

    // New-bin candidate: empty bin gets a moderate penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit -> overwhelming preference.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Residual divisibility classes: residuals divisible by 10 (or 5) are
    // more likely to be reused by later items drawn from typical streams.
    let div10 = (post_residual % 10 == 0) as f64;
    let div5 = (post_residual % 5 == 0) as f64;
    score -= 12.0 * div10 + 5.0 * div5;

    // Dead-space penalty: small nonzero residuals (1..=9) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Quotient class: how many "unit blocks" of capacity/10 remain.
    let q = (post_residual / 10) as f64;
    score += 0.8 * q * q; // superlinear penalty for leaving large residual (wasteful bin use)

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; relaxed when the stream is early or
        // next item is large relative to the residual we would leave elsewhere.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 45.0;
        if next_item_size > 0 && (next_item_size as f64) > pr + 1.0 {
            nb -= 10.0; // other bins' leftover won't help next item anyway
        }
        if progress < 0.2 {
            nb -= 8.0; // early stream: spreading out is cheaper long-run
        }
        score += nb;
    }

    // Lookahead coupling: reward placements whose post residual can host
    // the next item exactly or in a harmonic class.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 {
                score -= 15.0;
            }
            if rem < 10 && rem > 0 {
                score += 10.0; // would create dead space after next item
            }
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // a good "filler" target; normalize by capacity.
    let dev = (mean_residual - pr) / cap;
    score -= 10.0 * dev;

    // Congestion: many open bins -> prefer tighter packing (lower post residual).
    let congestion = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * congestion * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: dead-space cost, superlinear in how "unusable" the gap is.
    let mut score = post;

    // Penalize small unusable gaps much harder (dead space archetype).
    // A gap is "dead" if it's below the smallest plausible item (assume ~10)
    // or too small for the lookahead item.
    let min_item = 10.0f64;
    if post > 0.0 && post < min_item {
        score += 50.0 * (min_item - post) / min_item;
    }
    if next_item_size > 0 && (next_item_size as f64) > post {
        // gap can't host the next item: mild penalty scaled by shortfall
        score += 8.0 * ((next_item_size as f64) - post) / cap;
    } else if next_item_size > 0 && (next_item_size as f64) <= post {
        // lookahead fits: reward chaining
        score -= 6.0;
    }

    // Perfect fit reward
    if post == 0 {
        score -= 20.0;
    }

    // Tight fit reward relative to item size
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio;

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation; but allow new bin when open bins are crowded.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when few bins open, reward when many
        score += 12.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
    } else {
        // mild reward for using existing bins when many are open
        score -= 0.5 * (open_bins_count as f64).sqrt();
    }

    // Prefer bins with residual near mean (balance the pool)
    score += 0.3 * (post - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 0.9;
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // Penalize residuals too small for the lookahead item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Penalize small but nonzero dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Late in stream: tighten packing, discourage spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 heuristic: < 15)
    if post_residual < 15 {
        score += 6.0 * (15 - post_residual) as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Global state: penalize opening new bins when many bins are open with slack
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (12.0 + 10.0 * (1.0 - progress) + 0.05 * open_bins_count as f64);

    // Favor bins below mean residual (more slack than average) slightly
    score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex so small residuals are favored.
    let mut score = pr + 12.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream tolerates larger residuals; late stream punishes them.
    let coupling = norm_pr * (1.0 + 3.0 * progress * progress + 2.0 * progress * (1.0 - progress));
    score += 30.0 * coupling;

    // Reward tight fits with a smooth cubic of (1 - norm_pr).
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: bonus if next item fits the post residual (smooth kernel).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_kernel = (-gap / 20.0).exp();
        score -= 15.0 * fit_kernel * (0.5 + 0.5 * progress);
    }

    // Penalize wasting the last fitting bin when alternatives exist.
    if fitting_bins_count == 1 && open_bins_count > 1 {
        score += 8.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Slight preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Quantize post_residual into harmonic classes of width 10; reward small classes
    let class = post_residual / 10;
    score += class as f64 * 4.0;

    // Dead-space penalty: residual too small for the minimum item size (1)
    // but awkwardly small relative to typical items (10..80): penalize residual in (0,10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // harmonic divisibility bonus: next item divides post_residual evenly
            if post_residual % next_item_size == 0 {
                score -= 30.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here: penalize wasting space
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // existing bins with good fits, but a bonus when existing fits are poor
    if bin_residual == bin_capacity {
        score += 40.0 + 0.2 * open_bins_count as f64;
    }

    // Late in the stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Prefer bins with below-average residual (keep spread of residuals wide)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack < 10 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize as dead space.
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.6;
        // If the current item would leave a dead gap in any existing bin, opening fresh is better.
        if post_residual >= item_size.min(bin_capacity) {
            let future_gap = item_size;
            if future_gap < 10 {
                score -= 20.0;
            }
        }
        // Late in the stream, prefer closing out existing bins.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: eliminate dead space aggressively.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 100.0 + (5 - post_residual) as f64 * 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 300.0; // next item fills this bin exactly
        } else if post_residual as f64 >= next_item_size as f64 {
            // chainable bin: scale reward by tightness of the chain fit
            score -= 150.0 / (1.0 + diff / 10.0);
        } else {
            // post_residual too small for next item: penalize unusable sliver
            score += 40.0 + diff;
        }
        // extra bonus if next item would exactly fill after chaining
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain2 = post_residual - next_item_size;
            if chain2 <= 5 {
                score -= 60.0;
            }
        }
    }

    // Relative residual vs mean: prefer bins tighter than average when item fits well.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 80.0;
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 250.0 * desperation + 60.0;
        // early stream: slightly discourage hoarding new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 30.0;
    }

    // Mild pressure against bin sprawl.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Dead-space penalty: small leftovers (< 10, the minimum item size) are unusable.
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can still host the next item,
    // penalize bins that would be ruined for the upcoming item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
        // Chain fit: perfect pairing where item + next item exactly consumes residual.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin should only win when the item
    // is large (poor fits elsewhere are likely) or the stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base handicap so new bins are not opened frivolously.
        score += 25.0;
        // Large items justify a fresh bin (they leave big useful residuals).
        score -= 30.0 * large_item * large_item;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 10.0 * (1.0 - progress) * if open_bins_count < 4 { 1.0 } else { 0.3 };
        // If many bins are open and mean residual is high, reuse instead of opening.
        score += 0.15 * mean_residual;
    } else {
        // Mild preference for filling already-open bins when they are below average fullness.
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    // Crowding control: with many open bins, gently favor consolidation into existing bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothly warped by stream progress.
    // Late in the stream, residual waste matters more (harder to fill later),
    // so we amplify the penalty on large post_residual as progress -> 1.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear dead-space penalty: small residuals (< ~20) are nearly unusable
    // for items of size 10..80, penalize quadratically, scaled by progress.
    let dead = (20.0 - pr).max(0.0) / 20.0;
    score += 30.0 * dead * dead * (0.5 + progress);

    // Reward tight fits: smooth polynomial coupling of item_size with post_residual.
    let tightness = item_size as f64 / cap;
    score -= 25.0 * tightness * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-diff / 15.0) * (1.0 - progress);
        // Penalize if next item cannot fit (wasted lookahead compatibility)
        if next_item_size as f64 > pr {
            score += 8.0 * (next_item_size as f64 - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild dispersion penalty: prefer bins below mean residual (keep big holes open).
    score += 0.3 * (mean_residual - pr) * (1.0 - progress);

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64 * norm_pr * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "useful" is the leftover space?
    // Residuals divisible by common item granularities (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr == 0 {
        harmony_bonus = 40.0; // perfect fit
    } else {
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 20 == 0 { harmony_bonus += 4.0; }
        if pr % 25 == 0 { harmony_bonus += 3.0; }
        if pr % 50 == 0 { harmony_bonus += 5.0; }
        // Integer-division thresholds: small dead space is bad
        if pr < 10 { harmony_bonus -= 12.0; }
        else if pr < 20 { harmony_bonus -= 6.0; }
        else if pr > 60 { harmony_bonus += 4.0; } // still roomy for future items
    }
    score -= harmony_bonus;

    // Lookahead coupling: does post_residual harmonically fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or with harmonic leftover
            let nxt_left = pr - next_item_size;
            if nxt_left % 10 == 0 || nxt_left == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            score += 5.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5;
        // But if current bin would leave terrible dead space, opening fresh is fine
        if pr < 15 && pr > 0 {
            score -= 20.0;
        }
    }

    // Fraction of capacity used by this placement
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 10.0;

    // Stream progression: later in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced closing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item
    // (or for the smallest possible item, 1) are heavily penalized.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual < dead_threshold {
        // Fully filled bins are perfect; otherwise dead space is bad.
        if post_residual == 0 {
            score -= 30.0;
        } else {
            score += 25.0 + (dead_threshold - post_residual) as f64 * 0.5;
        }
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer compacting into
    // existing bins over spreading; with few bins, opening is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Prefer bins with residual below the mean (consolidating space).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly so it is only chosen when all
    // open bins would create dead space (their scores rise above this).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
    }

    // Lookahead: if next item exactly fits the post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasted residual that can't chain.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
        // Chain bonus: post_residual matches next item almost exactly.
        let match_gap = (post_residual as f64 - next_item_size as f64).abs();
        if match_gap <= 5.0 {
            score -= 25.0;
        }
    }

    // Compare against mean residual: prefer bins with residuals below average
    // (concentrate scarcity) unless the fit is tight.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.4 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Early in stream: be picky (keep space flexible); late: pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.3 * post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If the item is large and few bins fit it, a fresh bin is more acceptable.
        score -= 1.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect pairing: this item + next item exactly fill residual.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: empty bin is a fallback; make it mildly
    // attractive only when existing bins fit poorly or are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress - 3.0 * congestion;
        // Never open a new bin when a last-chance fit exists elsewhere.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    }

    // Mild preference for bins below mean residual (spreads load evenly).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Late in stream: consolidate aggressively, avoid waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a smooth non-linear penalty
    // that grows superlinearly for small residuals (dead space) as the stream progresses.
    let mut score = pr;

    // Polynomial coupling of post_residual with progress:
    // early in the stream, waste is cheap; late, waste is heavily penalized.
    let waste_curve = pr / cap;
    score += progress * (waste_curve * waste_curve) * cap * 0.5;
    score += progress * progress * (1.0 - waste_curve) * 10.0;

    // Smooth lookahead coupling: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs() / cap;
        score -= (1.0 - fit_gap) * 8.0 * (1.0 - progress);
        // Penalize leaving a residual that is uselessly small or awkwardly large for next item
        score += progress * fit_gap * 12.0;
    } else {
        // Last item: strongly prefer filling bins as completely as possible.
        score -= (1.0 - waste_curve) * 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - waste_curve);
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += (open_bins_count as f64).ln() * (pr / cap) * 3.0;

    // Prefer bins deviating favorably from the mean residual (tighter than average).
    score += (pr - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose residual is divisible by
    // common item-size chunks (e.g. 10/20/25/50) are reusable; penalize odd residues.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit is best
    } else {
        let mut harmony = 0.0;
        if r % 10 == 0 { harmony += 6.0; }
        if r % 20 == 0 { harmony += 4.0; }
        if r % 25 == 0 { harmony += 3.0; }
        if r % 50 == 0 { harmony += 5.0; }
        // integer-division dead-space threshold: residues < 10 are near-useless
        let dead = (r < 10) as i32 as f64;
        score -= harmony;
        score += dead * 40.0;
    }

    // Lookahead coupling: does this bin's post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain placement possible
            // harmonic match: next item exactly fills remainder class
            if post_residual % next_item_size.max(1) == 0 { score -= 8.0; }
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last-chance bin before opening a new bin: strong reward if fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.15 * (bin_residual as f64 - post_residual as f64);
    }

    // New-bin candidate handling: only prefer it late in stream or when current
    // fit is terrible (large post_residual relative to capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // penalize opening new bins early / when many bins open
        score += 20.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // but if existing fit wastes > half capacity, soften
        if post_residual > bin_capacity / 2 && bin_residual != bin_capacity {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packing).
    score += 0.25 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Fraction-of-capacity reward: post_residual small fraction of capacity favored.
    score += 10.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    }
    // Post-residual that cannot fit even the smallest item is pure waste.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 15.0;
    }

    // Reward tight fits (low post residual relative to capacity).
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: discourage spreading across many bins, encourage closing bins out.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item won't fit here; penalize leaving a gap that blocks it.
        score += 8.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            // Base cost of opening a new bin, softened if residuals are large/fragmented.
            score += 20.0;
            if mean_residual > 30.0 {
                score -= (mean_residual - 30.0) * 0.4;
            }
            if fitting_bins_count == 1 {
                // Existing bin is last chance; keep new bin less attractive.
                score += 30.0;
            }
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 == nx {
            // Perfect match: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else if (post_residual as f64 - nx).abs() <= 2.0 {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: good, proportional reward.
            score -= 8.0 + 0.25 * nx;
        } else {
            // Next item cannot use the leftover: dead-space penalty,
            // scaled by how badly it misses and stream progress.
            let miss = nx - post_residual as f64;
            score += miss * (1.5 + 2.0 * progress);
        }
    }

    // --- Tightness of the current placement ---
    let tight = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tight;

    // --- Relative to mean residual: prefer bins with less residual (fuller) ---
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // --- Last-chance bonus: if this is the only fitting bin, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, more early when few bins exist;
        // but reward it if post_residual is very usable for the next item.
        let mut newbin_penalty = 30.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && post_residual >= next_item_size {
            newbin_penalty -= 15.0;
        }
        if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
            newbin_penalty -= 20.0;
        }
        score += newbin_penalty;
    }

    // Slight penalty for very small unusable post-residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (2.0 + 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Penalize dead space: residual too small for any plausible item (1..=100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty if it leaves large residue anyway
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer fuller bins over emptier ones among open bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Global state coupling: many open bins with high mean residual -> discourage
    // spreading; prefer packing into existing bins.
    if open_bins_count > 1 {
        score += (mean_residual / bin_capacity as f64) * 8.0;
    }

    // New-bin candidate logic: empty bin gets a base handicap so it's only chosen
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If the item is large, a fresh bin is more attractive.
        score -= (item_size as f64 / 100.0) * 15.0;
        // If next item is large too, fresh bin preserves flexibility.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild time pressure: late in stream, avoid opening bins at all.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.9 {
        score += 10.0 * (progress - 0.9) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, but its importance grows with stream progress
    let mut score = pr * (0.6 + 0.8 * progress);

    // Smooth polynomial coupling: quadratic and cubic terms of normalized post residual
    score += 25.0 * pr_norm * pr_norm * (1.0 + progress);
    score += 40.0 * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Penalize dead space that is too small for typical future items
    let dead = 1.0 - (pr / 100.0).min(1.0);
    score += 15.0 * dead * dead * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly late in stream
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Lookahead: if next item fits into post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap) * (1.0 - pr_norm) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidation when many bins are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Mean residual alignment: prefer bins close to mean residual (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: penalize opening a new bin unless it is early or residual would be perfect
    if bin_residual == bin_capacity {
        let waste = if next_item_size > 0 { (item_size + next_item_size).min(bin_capacity) as f64 / cap } else { item_size as f64 / cap };
        score = 60.0 + 40.0 * (1.0 - waste) - 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that stay in "usable" classes
    let pr = post_residual;
    // Class boundaries via integer division on capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: tiny residuals (below eighth) are nearly unusable
    if pr < eighth {
        score += (eighth - pr) as f64 * 2.5;
    }
    // Reward mid-band residuals that still fit typical small items
    if pr >= quarter && pr <= half {
        score -= (pr - quarter) as f64 * 0.6;
    }

    // Modulo-class logic: residuals divisible by common item sizes (10, 20, 25, 50)
    // are "harmonic" and likely reusable by future items.
    let harmonic_bonus = if pr == 0 {
        12.0 // perfect fit
    } else if pr % 50 == 0 {
        8.0
    } else if pr % 25 == 0 {
        6.0
    } else if pr % 20 == 0 {
        5.0
    } else if pr % 10 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        score -= 6.0 + (after as f64).sqrt() * 0.8;
        if after % 10 == 0 { score -= 2.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here after placement; mild penalty unless it's a perfect fit now
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current residuals are all poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = mean_residual < (item_size as f64 * 0.9);
        let base_penalty = 8.0 + open_bins_count as f64 * 0.15;
        score += if poor_fit { base_penalty - 6.0 } else { base_penalty + progress * 4.0 };
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= fill_ratio * 4.0;
    }

    // Mild penalty for wasting large residuals on small items
    if (post_residual as f64) > cap * 0.7 && item_size < quarter {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space (gaps below minimum item size 1..~10 are wasted)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Strong penalty for near-full-but-wasteful residuals that cannot fit typical items
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness;

    // Open-bin pressure: prefer filling existing bins when many are open
    score += (open_bins_count as f64) * 3.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Progress-based mild tightening of dead-space tolerance
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Mean residual context: penalize bins far above mean residual (fragmenting spread)
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.2;

    // New-bin candidate: make empty bin moderately attractive only when it beats bad fits
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits (post residual near zero)
    let fit_bonus = if post_residual == 0 {
        50.0
    } else if post_residual <= 5 {
        30.0
    } else if post_residual <= 15 {
        12.0
    } else {
        0.0
    };
    score -= fit_bonus;

    // 2-step lookahead: reward when next item fits the post-residual well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chains: next item leaves little dead space too
            let chain_quality = 1.0 - (slack / post_residual.max(1) as f64);
            score -= 10.0 + 15.0 * chain_quality;
        } else {
            // Penalize leaving residual that next item cannot use at all
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.15 * unusable.min(40.0);
        }
    }

    // Penalize creating dead space relative to the smallest plausible next item (1..=100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare residual against mean residual: prefer tighter-than-average bins
    score += 0.1 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Early in the stream, allow opening new bins cheaply; later, conserve
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let new_bin_penalty = 20.0 + 30.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is attractive only if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 5.0; // big-then-small ordering works well in fresh bins
        }
    }

    // Slight preference for bins with more residual when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later
    // (items are 1..=100, so residual below ~10 is nearly dead).
    if post_residual < 10 {
        score += 12.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fill is excellent
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 25.0;
        } else if diff > 0 && diff < 10 {
            score -= 8.0;
        } else if diff < 0 {
            score += 4.0; // next item won't fit here; mildly discourage
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * item_size as f64;
    }

    // New-bin candidate handling: opening a bin is costly; discourage it
    // unless current bin fits are poor (large post_residual waste).
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, keep bins open (consolidate); late, allow spreading.
        let open_penalty = 20.0 + 25.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        // If best existing waste would be worse than what a fresh bin
        // would leave (residual = 100 - item), opening becomes attractive.
        let fresh_residual = (bin_capacity - item_size) as f64;
        let waste_advantage = avg_waste - fresh_residual;
        score = fresh_residual + open_penalty - 1.5 * waste_advantage.max(0.0);
    }

    // Mild global pressure: many open bins with high mean residual
    // suggests we should consolidate into existing bins.
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Small time-horizon modulation: as stream progresses, prefer
    // tighter packing slightly more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = x * x * (3.0 - 2.0 * x) * cap * 0.5 + pr;

    // Smooth interaction: tight fits matter more as stream progresses
    score -= (1.0 - x).powi(3) * (20.0 + 30.0 * progress);

    // Penalize dead space that no plausible item can fill (smooth ramp)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.35 * gap * (1.0 + progress);
    } else {
        // last item: strongly prefer filling an existing bin
        score -= 25.0 * (1.0 - x);
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - x);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * x;

    // Prefer bins whose residual deviates from mean (keep homogeneity)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        score += 40.0 - 25.0 * (1.0 - x).powi(2);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: items of size <= 50 leave residual
    // classes; small post-residuals are good, but tiny ones (<10) are dead space
    // unless they can host the next item.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward near-full bins (small post-residual) with a harmonic discount.
    if post_residual > 0 {
        score -= 60.0 / post;
    } else {
        score -= 80.0; // perfect fill
    }

    // Penalize dead space in the awkward band (1..=9): nothing fits there.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // next item rescues the dead space
        }
    }

    // Harmonic classes by integer division of post_residual into deciles.
    let class = post_residual / 10;
    match class {
        0 => score -= 10.0,               // 0-9: tight fit
        1 => score -= 5.0,                // 10-19: fits small items
        2 | 3 => score -= 2.0,            // 20-39: mid classes
        4 | 5 => score += 0.0,            // 40-59: neutral
        6 | 7 => score += 6.0,            // 60-79: wasteful
        _ => score += 12.0,               // 80+: nearly empty
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (mean_residual / cap).max(0.01);
        score += 40.0 + pressure.min(60.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Lookahead: if next item fits exactly in post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack <= 10 {
            score -= 15.0;
        }
    }

    // Progress-based mild tightening: late in the stream, prefer tighter packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Mean-residual coupling: when mean residual is low, cherish good fits more.
    score -= (cap - mean_residual).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward filling bins nearly full (post_residual small relative to capacity).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill_ratio;

    // Open bins pressure: penalize using bins when many are open, favor consolidation.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual would be huge waste.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Allow new bin if current fit would leave a tiny dead gap and lookahead fits better.
        if post_residual < 10 && next_item_size > post_residual && next_item_size > 0 {
            score -= 55.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: leftover becomes dead space for the horizon.
        if post_residual < 20 {
            score += 20.0;
        }
    }

    // Late in the stream, prefer tighter packing to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins below mean residual (fuller bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly reduce score when post_residual is small but > 0
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: small post_residual that can never fit typical items is fine,
    // but medium dead space is bad. Penalize post_residual in "awkward" range.
    if post_residual > 0 {
        let awkward = if post_residual < 10 { 0.0 } else { (post_residual as f64 - 10.0).min(40.0) };
        score += 0.35 * awkward;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }
    // If next item is close to fitting, mild penalty for wasting the slot
    else if next_item_size > 0 && post_residual > 0 {
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 15.0 {
            score += 0.4 * gap;
        }
    }

    // Last chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to preserve flexibility
    else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Global state: if mean residual is high, we have slack — prefer filling existing bins less aggressively
    let slack = mean_residual - post_residual as f64;
    score += 0.15 * slack.max(0.0);

    // Time horizon: late in the stream, consolidate harder (avoid opening new bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when the fit into open bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or when few bins fit
        let mut new_bin_cost = 18.0 + post_residual as f64;
        if fitting_bins_count == 1 { new_bin_cost += 30.0; } // never open when a last-chance bin exists
        if next_item_size > 0 && (post_residual as u64) >= (bin_capacity as u64) {
            new_bin_cost -= 5.0; // empty bin guarantees fit for next item too
        }
        score = new_bin_cost + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress
    let coupling = norm_pr * (1.0 + progress * norm_pr) * (1.0 - progress * 0.5);
    score += 12.0 * coupling;

    // Penalize large dead space quadratically as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.3 + progress);

    // Reward tight fits (small post-residual) more strongly early on
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let next_fits = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 15.0 * next_fits * (1.0 - norm_pr);
    }

    // Penalize scattering across many open bins when residuals are high
    score += 2.0 * open_bins_count as f64 * norm_pr * norm_pr;

    // Mean residual deviation: prefer bins near the mean (smooth term)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain residue classes.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Penalize post-residuals that are small-but-nonzero (unusable slivers).
    if pr > 0 && pr < 10 {
        score += 25.0 - (pr as f64) * 2.0;
    }
    // Reward post-residuals aligned to common item-size harmonics (divisible by 10, 20, 25, 50).
    if pr % 10 == 0 { score -= 6.0; }
    if pr % 20 == 0 { score -= 3.0; }
    if pr % 25 == 0 { score -= 2.0; }
    if pr % 50 == 0 { score -= 2.0; }
    // Modulo-phase coupling between post_residual and next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let phase = ((post_residual - next_item_size) % 10) as f64;
        score -= 8.0 - phase; // exact chain fit is best
    } else if next_item_size > 0 {
        // Next item cannot chain into this bin: penalize proportionally.
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Fraction-of-capacity coupling: prefer filling bins to high fractions.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_frac * fill_frac * 15.0;

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = mean_residual / cap;
        let poor_fit = (post_residual as f64) / cap > 0.5;
        // Bias: open new bins early or when existing bins have low mean residual.
        score += 30.0 + crowded * 40.0 - progress * 20.0;
        if poor_fit { score -= 10.0; }
    } else {
        // Slight preference for tighter existing bins relative to mean residual.
        score += ((bin_residual as f64) - mean_residual) * 0.05;
    }

    // Mild pressure to consolidate as open-bin count grows.
    score += (open_bins_count as f64) * 0.02 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Lookahead: penalize if the next item cannot fit into the post residual.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 12.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
