    }

    // Penalize deviating far from the mean residual (encourages balanced fills).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: make it unattractive unless current bins are very full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        score += 40.0 + 60.0 * avg_fill;
    }

    // Slight progression term: later in the stream, tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize wasted space relative to next item.
        score += 0.5 * (next_item_size as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect chain: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
