    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Relative to mean residual: bins with residual below mean are more valuable to fill.
    score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 0.2 * (post_residual as f64);
    }

    // Progression: slightly prefer compacting early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space (waste) more than large leftover space,
    // encouraging tight fits and leaving room for small future items.
    if post_residual > 0 {
        score += 8.0 / (post_residual as f64).powf(0.7);
