    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let tight_fit_exists = post_residual == 0 && fitting_bins_count > 0;
        let _ = tight_fit_exists;
        // Base new-bin cost; reduced late in the stream or when many bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 10.0 * progress;
        // If next item is large, opening a fresh bin may be wiser.
        if next_item_size > 0 && (next_item_size as f64) > bin_residual as f64 * 0.9 {
            score -= 8.0;
        }
        // Discourage opening bins when existing bins have plenty of room.
        if mean_residual > item_size as f64 * 2.0 {
            score += 10.0;
        }
    }

    // Lookahead synergy: reward placements that leave room exactly for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if (post - nxt).abs() < 1.0 {
            score -= 12.0;
        } else if post >= nxt && post - nxt <= 10.0 {
            score -= 5.0;
        } else if post < nxt && post > 0.0 {
            score += 3.0 * (1.0 - post / nxt);
        }
    }

    // Prefer filling bins with below-average residual (consolidate space).
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 2.0;
    } else {
        score += (resid - mean_residual).min(20.0) * 0.15;
    }

    // Mild preference for emptier bins when many bins are open (load balancing).
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Slight bonus for placing large items into tight bins.
    score -= (item_size as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on large residuals
    let mut score = pr * (1.0 + 2.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: late in stream, tolerate residual less
    let progress_coupling = 1.0 + 1.8 * progress * progress - 0.6 * progress;
    score *= progress_coupling;

    // Dead-space penalty: residual too small for smallest plausible item
    let dead = (20.0f64 - pr).max(0.0) / 20.0;
    score += 45.0 * dead * dead * (0.5 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
    } else {
        // mild penalty when many alternatives exist
        score += (fitting_bins_count as f64 - 1.0).min(6.0) * 2.0;
    }

    // Lookahead: reward if next item fits in post_residual (chaining)
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else {
            // penalize leaving residual that blocks the next item
            let gap = pr - (next_item_size as f64 - pr).max(0.0);
            score += 8.0 * (1.0 - (gap / cap).max(0.0));
        }
    }

    // Contextual terms: open bins and mean residual
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);
    score -= (mean_residual - pr) * 0.25;

    // New-bin candidate handling: only attractive early or when current bin is a bad fit
    if bin_residual == bin_capacity {
        let new_bin_bonus = 25.0 * (1.0 - progress) + 20.0 * norm_pr_zero_fallback(item_size, cap);
        score += pr; // = capacity, naturally high
        score -= new_bin_bonus;
    }

    score
}

#[inline]
fn norm_pr_zero_fallback(item_size: u32, cap: f64) -> f64 {
    // large items benefit from a fresh bin more
    (item_size as f64 / cap).min(1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward high fill fraction.
    score -= 40.0 * fit_ratio * fit_ratio;

    // Harmonic class logic: classify post_residual into residue classes.
    // Residuals that are "dead" (too small for the smallest plausible item, <10)
    // are perfect; residuals in awkward mid-range classes are penalized.
    let pr_u = post_residual;
    if pr_u == 0 {
        score -= 25.0; // perfect packing
    } else if pr_u < 10 {
        score -= 18.0; // dead space, effectively full
    } else {
        // Modulo-10 class of the residual: classes near 0 are more reusable.
        let class = pr_u % 10;
        score += (class as f64) * 0.6;
        // Integer-division thresholds: residual in [10,30) is awkward.
        if pr_u / 10 <= 3 {
            score += 8.0;
        } else if pr_u / 10 <= 5 {
            score += 3.0;
        }
    }

    // Coupling with next item (lookahead): if next item fits post_residual exactly
    // or nearly, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 - (slack as f64) * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of all open bins.
        // Penalize new bins unless existing bins are badly fragmented or item is large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0;
        new_bin_penalty += (open_bins_count as f64) * 1.5;
        // If mean residual across open bins is small, open bins are nearly full -> new bin ok.
        new_bin_penalty -= (mean_residual / cap) * 30.0;
        // Large items late in stream: opening fresh bin can be fine.
        new_bin_penalty -= (item_size as f64 / cap) * 15.0;
        // If item leaves a nice round residual (harmonic class) in a new bin, slight relief.
        if post_residual % 10 == 0 {
            new_bin_penalty -= 4.0;
        }
        score += new_bin_penalty * (1.0 - 0.3 * progress);
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual (more filled).
    score += ((bin_residual as f64) - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals that can never fit the
    // smallest plausible item are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 40.0;
    }
    // Very tight fits leave nearly unusable slivers.
    if post_residual <= 5 {
        score += 25.0;
    }

    // Reward bins whose leftover can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // unless this bin is the last chance to fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the average residual (good fits).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            score -= (30.0 - diff.min(30.0)) * 0.8; // next item still fits, closer is better
        } else {
            score += diff * 0.3; // next item would not fit here; penalize proportionally
        }
    }

    // Penalize small unusable dead space (below minimum item size 1..~10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space trap
    }

    // Relative to mean residual: prefer bins with residual below average (tighter bins),
    // penalize dumping into very loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin gives
    // a good fit. Give it a mild penalty that tight fits can overcome.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is more attractive early (many items remain to fill it later).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for filling bins that are already quite full.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // unusable sliver
        } else if dead < item_size as f64 {
            score += 8.0;  // below current item scale
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain fit: residual still usable after hypothetical next placement
            let chain = post_residual - next_item_size;
            if chain >= 10 {
                score -= 4.0;
            }
        } else {
            // residual would be stranded relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0));
    score -= 6.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: bins far below mean residual waste space.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 5.0 * dev;

    // Time horizon: early in stream, be pickier about large residuals (keep bins flexible).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score += 40.0; // default penalty: prefer existing bins
        if fitting_bins_count == 0 || next_item_size == 0 {
            score -= 35.0;
        }
        // open a fresh bin early if item is huge and would leave awkward residual elsewhere
        if item_size > bin_capacity * 4 / 5 {
            score -= 20.0;
        }
        if progress > 0.5 && open_bins_count > 4 {
            score -= 10.0; // late stream: opening bins is fine to finish cleanly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear coupling to stream progress.
    // Late in the stream, tighter fits (small post_residual) matter more.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Polynomial penalty for dead space: residuals too small to host typical items.
    let dead = (norm_pr * norm_pr * (norm_pr - 0.25)).max(0.0);
    score += 60.0 * dead * (1.0 + progress);

    // Reward filling a bin nearly completely, smoothly scaled.
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Penalty for opening new bins when many are open with slack.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Lookahead: favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        score -= 12.0 * fits_next * (1.0 - (pr - next_item_size as f64) / cap).abs();
    }

    // Mild pressure toward bins with below-average residual (tighter bins first).
    score += 0.1 * (mean_residual - bin_residual as f64).abs() * (mean_residual - bin_residual as f64).signum();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small dead space (mod classes near 0) is good.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits, especially when post_residual falls into "useful" harmonic classes.
    let class = post_residual % 10; // harmonic residue class of dead space
    let class_bonus = match class {
        0 => 12.0,           // perfectly reusable remainder (multiples of 10)
        1..=3 => 6.0,        // small, likely fillable by tiny items
        8 | 9 => 8.0,        // nearly next multiple: one small item tops it off
        _ => 0.0,            // awkward middle classes
    };
    score -= class_bonus;

    // Penalize dead space that can never fit a typical item: post_residual below item's floor.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Fraction-of-capacity coupling: prefer residuals that are large fractions used well.
    let fill_ratio = (bin_residual - post_residual) as f64 / cap;
    score -= 10.0 * fill_ratio * fill_ratio; // reward high fill

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and lookahead item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > cap * 0.5; // item left bin half-empty
        let lookahead_needs = next_item_size > 0 && next_item_size > post_residual;
        let mut penalty = 15.0;
        if bad_fit && lookahead_needs {
            penalty = -20.0; // fresh bin is attractive for the next big item
        }
        if fitting_bins_count <= 1 {
            penalty -= 25.0; // no good alternative anyway
        }
        score += penalty;
    }

    // Lookahead harmony: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0; // next item can still use this bin
    }

    // Late-stream consolidation: fewer open bins preferred as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).sqrt();

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are unusably small for
    // typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Lookahead: if the next item cannot fit into the resulting residual,
    // this placement creates a dead gap for the immediate future.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward if the residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few bins, mild preference to open new bins
    // for large items to keep flexibility.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: a fresh empty bin is only attractive when
    // no good existing option exists (e.g., item barely fits anywhere or
    // many bins are already open and residual is large-item-sized).
    if bin_residual == bin_capacity {
        // Baseline: empty bin wastes the whole capacity; make it moderately
        // unattractive so tight fits in open bins win.
        score = (bin_capacity as f64) * 0.9;
        // If the item cannot fit well anywhere else (this is the only fitting
        // candidate), opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, consolidating is better than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Large items relative to residual: opening fresh bin avoids stranding.
        if item_size as f64 > 0.5 * bin_capacity as f64 && open_bins_count > 3 {
            score -= 25.0;
        }
    }

    // Mild tie-break toward bins with above-mean residual (keeps tighter bins
    // reserved for small items).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits: reward tighter coupling (smaller leftover after next)
            let after_next = post - next;
            score -= 40.0 * (1.0 - after_next / cap);
            if after_next == 0.0 {
                score -= 300.0;
            }
        } else {
            // dead space for the next item: penalize proportionally to mismatch
            score += 25.0 * (next - post) / cap;
        }
    }

    // Compare post_residual relative to mean residual: prefer bins whose residual
    // becomes close to the mean (balanced packing) but avoid leaving large slack
    let mean = mean_residual;
    let dev = (post - mean).abs();
    score += 5.0 * dev / cap;

    // Last chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: penalize opening a new bin when it isn't needed,
    // unless the item is huge and fits poorly everywhere (handled by lookahead).
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 1000.0; // forced new bin
        }
    }

    // Prefer tighter existing bins: smaller bin_residual (relative to capacity) is better
    score += 10.0 * (bin_residual as f64) / cap;

    // Late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual as f64;

    let mut score;

    if is_new_bin {
        // Neutral-ish score: only wins when all open bins fit poorly.
        // Slightly better late in stream (committing to a fresh bin is fine then).
        score = 55.0 - 10.0 * t;
        // Discourage opening a bin when many bins already open and mean residual is high.
        score += 0.05 * open_bins_count as f64 + 0.05 * mean_residual;
        return score;
    }

    // Base: prefer small post residual (tight fit).
    score = pr;

    // Reward large item consumption (filling big holes with big items).
    score -= 0.12 * item_size as f64;

    // Lookahead: if next item can fit in the leftover space, this placement is great.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * nxt;
        } else if pr > 0 && pr < 10.0 {
            // leaves tiny unusable sliver that next item can't use: mild penalty
            score += 0.3 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // When several bins fit, slightly prefer tighter ones (already via pr),
        // but add small noise-free coupling with mean residual to spread load.
        score += 0.02 * (mean_residual - pr).abs();
    }

    // Time horizon: early on, be a bit more conservative about creating dead space.
    score += (1.0 - t) * 0.1 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let coupling = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 60.0 * coupling;

    // Penalize dead space more as stream matures
    score += 8.0 * pr_norm * pr_norm * (progress + 0.5);

    // Last-chance bin bonus: strongly prefer when only this bin fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * pr_norm;
    }

    // Lookahead: reward bins whose post_residual can still host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 5.0 * pr_norm;
    }

    // Slight penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * (open_bins_count as f64).sqrt() * (0.5 + progress);
    }

    // Prefer tighter fits relative to mean residual
    score += 3.0 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by
    // integer-division thresholds against the capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / 10).min(10); // harmonic decile of residual

    // Reward tight fits: residual classes 0..=1 are near-perfect.
    score -= (10 - class as f64) * 4.0;

    // Penalize "awkward" residuals: values in (0,10) mod 10 that no
    // small item (>=1) can use efficiently — dead-space coupling.
    let dead = post_residual % 10;
    if post_residual > 0 && dead > 0 && dead < 3 {
        score += 12.0; // sliver residual: likely unusable
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial fit: reward proportional to fill of next item
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual at all: penalize
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate: penalize opening a fresh bin unless the
    // current item is large and no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / cap; // avg slack across open bins
        score += 20.0
            + 25.0 * (1.0 - item_size as f64 / cap)
            + 30.0 * pressure
            - 10.0 * progress;
    } else {
        // Slight preference for fuller bins (best-fit flavor) via
        // harmonic fill fraction.
        let fill = (bin_residual as f64) / cap;
        score -= 6.0 * fill;
    }

    // Divergence from mean residual: prefer bins that absorb outliers,
    // keeping the fleet of residuals harmonically balanced.
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny sliver: worst dead space
        } else if post_residual < item_size.min(20) {
            score += 25.0; // gap smaller than typical future item
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure from many open bins: favor filling existing bins.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: only attractive when item fits poorly everywhere else,
    // i.e. when this empty-bin call has large residual and mean residual is low.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: slightly above a good fit in an open bin
        score = (bin_capacity - item_size) as f64 + 8.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0; // open bins are too full; new bin is fine
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // lookahead: if next item is large, fresh bin gives flexibility
        if next_item_size > 40 {
            score -= 6.0;
        }
    } else {
        // Lookahead synergy: leaving exactly next_item_size is ideal.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 18.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small (good packing).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // 2-step lookahead: if the next item exactly matches post_residual, this is a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: reward proportionally to how tight the chain is.
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * chain_tightness;
        } else {
            // Next item won't fit here: penalize leaving a stranded gap near next_item_size.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap.abs() < 10.0 {
                score += 40.0;
            }
        }
    }

    // Compare post_residual against mean residual: leaving below-average residual is good.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize new-bin candidate unless current bin would leave a large awkward residual
    // or the item fits the empty bin perfectly.
    if bin_residual == bin_capacity {
        if item_size == bin_capacity {
            score -= 500.0; // perfect full-bin usage
        } else {
            // Opening a new bin is only attractive if existing fits are very loose.
            score += 60.0;
            if fitting_bins_count == 0 {
                score -= 200.0; // no alternative: must open new bin
            }
            // If next item also fits the fresh bin alongside this one, encourage opening.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 40.0;
            }
        }
    }

    // Mild pressure against hoarding many open bins with large residuals.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: penalize small post residuals more as stream progresses
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 - progress) + pr * progress * progress;
    score += 20.0 * poly;

    // Dead-space penalty: residual that is small but nonzero (unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // exact chain fit
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Mean residual deviation: prefer bins close to mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * dev;

    // Tight fit reward
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // New-bin candidate: penalize mildly so it is chosen only when no good open bin exists
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "nice" fractions
    // of capacity are more reusable. Class via integer division thresholds.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Harmonic class penalty: residuals in [0,10) are near-dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        score -= 6.0;
    }

    // Reward residuals that are exact harmonic divisors of capacity (50, 25, 20, 10...)
    let harmonics: [u32; 6] = [50, 40, 25, 20, 10, 5];
    for h in harmonics.iter() {
        if post_residual == *h {
            score -= 14.0;
            break;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item fills the leftover
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - tight / cap);
        } else {
            // next item cannot use this residual: penalize large wasted leftovers
            score += 0.25 * pr;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or many bins are open (spreading load).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 55.0 - 40.0 * item_frac;
        // if current bin would leave tiny dead space, opening new bin is fine
        if post_residual < 15 {
            score -= 45.0;
        }
    }

    // Mild load balancing: prefer bins whose residual is near the mean.
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for tighter fits overall (fractional coupling).
    score += 30.0 * frac * (1.0 - frac); // peaks at frac=0.5, penalizes mid residuals mildly

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;
    let nx = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;

    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let mean = mean_residual.clamp(0.0, cap);
    let fill = (item / cap).clamp(0.0, 1.0);
    let is_new = bin_residual == bin_capacity;

    let mut score = pr;

    if post_residual == 0 {
        score -= cap * (0.50 + 0.15 * progress + 0.10 * fill);
    } else {
        let mut micro_gap = (cap.sqrt() * 1.2).max(1.0);
        if next_item_size > 0 {
            micro_gap = micro_gap.min((next_item_size as f64).max(1.0));
        } else {
            micro_gap = 0.0;
        }

        if micro_gap > 1.0 && pr < micro_gap {
            let t = (micro_gap - pr) / micro_gap;
            score += cap * (0.22 + 0.18 * progress) * t * t;

            if !is_new && nx > 0.0 && residual + 0.5 >= nx && item + 0.5 < nx {
                score += cap * (0.20 + 0.10 * progress);
            }
        }

        if nx > 0.0 {
            if pr + 0.5 < nx {
                let shortfall = nx - pr;
                score += shortfall * (0.40 + 0.25 * progress) + cap * 0.03;

                if !is_new && residual + 0.5 >= nx && item + 0.5 < nx {
                    let size_deficit = ((nx - item) / cap).clamp(0.0, 1.0);
                    let space_deficit = ((nx - pr) / cap).clamp(0.0, 1.0);
                    score += cap * (0.60 * size_deficit + 0.50 * space_deficit) + shortfall * 0.30;
                }
            } else if (pr - nx).abs() <= 0.5 {
                score -= cap * (0.30 - 0.10 * progress);
            } else {
                let slack_after_next = ((pr - nx) / cap).clamp(0.0, 1.0);
                score -= cap * 0.08 * (1.0 - slack_after_next);
            }
        }
    }

    if is_new {
        let fitting_pressure = if fitting_bins_count > 0 {
            (0.8 + 0.35 * fitting).min(6.0)
        } else {
            0.0
        };

        score += 1.2 + 1.8 * open.sqrt() + 0.03 * open + fitting_pressure;
        score += (mean / cap) * (1.5 + 2.0 * progress);

        if fitting_bins_count == 0 {
            score -= cap * 1.5;
        } else if nx > 0.0 && pr + 0.5 >= nx {
            score -= cap * 0.04;
        }
    } else {
        score -= 0.6 + 0.03 * open + ((cap - mean) / cap) * 1.0 + fill * 0.5;

        if fitting_bins_count == 1 {
            score -= 1.2 + 1.2 * (1.0 - progress);
        }

        if residual + 0.5 < mean {
            score -= ((mean - residual) / cap).clamp(0.0, 1.0) * (1.0 + 1.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= 30.0 * fit_ratio;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item cannot use leftover space -> penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare post_residual against mean residual: avoid leaving much more/less than average
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if item is large, opening a fresh bin is reasonable
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // Slight preference for bins already below mean residual (pack small leftovers together)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    } else if post_residual < 20 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
        // Extra reward if next item fills the bin completely afterwards.
        if post_residual - next_item_size == 0 {
            score -= 120.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leftovers too small for the next item (dead space risk),
        // scaled by how small the leftover is.
        let dead = post_residual as f64;
        score += dead * 0.6;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current
    // bin would leave large unusable residue or the item is large.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin: prefer using existing bins with tight fits.
        score += 250.0;
        // If the item is large and mean residual is low, a new bin becomes attractive.
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 180.0;
        }
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 100.0 * progress;
    }

    // Slight preference for fuller bins relative to the fleet average.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild pressure against hoarding many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.6 * progress + 0.8 * progress * progress);
    let mut score = pr + 12.0 * poly;

    // Penalize dead space more as stream advances
    let waste = norm_pr * norm_pr;
    score += 30.0 * waste * (0.5 + progress);

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose leftover can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Mild penalty for spreading across too many bins
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins that reduce dispersion
    score += 0.5 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no item (min size 1)
    // can use is only post_residual==0; but small unusable gaps are costly.
    // Class A: gap too small for the lookahead item -> wasted relative to k=2 lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Class B: gap in "awkward band" (1..=9) is nearly dead space for typical streams.
    if post_residual > 0 && post_residual <= 9 {
        score += 30.0;
    }

    // Class C: residual that still admits many sizes is valuable; keep bins flexible.
    // Reward keeping post_residual >= 30 (half-capacity-ish) modestly.
    if post_residual >= 30 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): make it expensive so we only open when the
    // fit elsewhere is poor (large post_residual / dead space elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: proportional to wasted capacity if item goes here.
        score = (bin_capacity - item_size) as f64 + 60.0;
        // Opening early in the stream is cheaper (long horizon to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // If no existing bin fits, the new-bin call is the only option: make it win.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // If existing fit would leave a tiny dead gap, opening a fresh bin is better.
        if post_residual > 0 && post_residual <= 9 && next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Tie-break: prefer bins whose residual deviates favorably from the mean
    // (pack into below-average-residual bins to consolidate).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Slight preference for packing into already-open bins vs. inflating open set.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item are waste.
    // Treat residual < 10 as fully dead: heavy penalty proportional to how dead it is.
    let dead = if post_residual > 0 && post_residual < 10 { (10 - post_residual) as f64 * 6.0 } else { 0.0 };
    score += dead;

    // Perfect fit bonus: zero post_residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits (small but usable post_residual).
    if post_residual > 0 && post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize leaving a gap that next_item_size exactly wastes or fits poorly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can use the gap: mild reward, scaled by how snug it is.
            let snug = (post_residual as f64 - next_item_size as f64).abs();
            score -= (15.0 - snug.min(15.0)) * 0.6;
        } else {
            // gap is too small for the next item: penalize if it's in the dead zone.
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Open-bin pressure: discourage scattering across many bins; opening new bins
    // is penalized via the empty-bin candidate (large residual) naturally,
    // but add explicit pressure so consolidation wins ties.
    score += open_bins_count as f64 * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild deviation from mean residual: prefer bins whose residual is near the mean
    // to keep bin states balanced.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    // Slight late-stream conservatism: as the stream progresses, avoid creating
    // tiny unusable gaps even more (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += dead * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: strongly reward when next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain (gap 0) gets a big reward; decays with gap size.
        score -= 55.0 * (-gap / 25.0).exp();
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item (dead space risk).
        let excess = (next_item_size - post_residual) as f64;
        score += 12.0 * (excess / 30.0).min(1.5);
    }

    // Compare post_residual against mean residual: avoid creating outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / (mean_residual + 1.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Allow opening a new bin when it would create a near-perfect chain with the next item
        // or when open bins are very fragmented (high mean residual dispersion proxy).
        let chain_bonus = if next_item_size > 0 && (bin_capacity - item_size) as i64 == next_item_size as i64 { 20.0 } else { 0.0 };
        let fragmentation = (open_bins_count as f64).ln() * 6.0;
        score += 25.0 + fragmentation - chain_bonus;
    }

    // Slight late-stream conservatism: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size is wasted. Penalize post_residual in the
    // awkward "too small for typical items" zone.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Partial reward, scaled by how well it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 15.0 * progress;
    }

    // Prefer bins with residual below mean residual (tighter bins first),
    // scaled by how many bins are open (more bins -> more consolidation pressure).
    let diff = mean_residual - bin_residual as f64;
    score -= diff * (0.3 + 0.05 * open_bins_count as f64).min(1.2);

    // Penalize creating tiny unusable remnants relative to item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild reward for filling bins deeply as the stream progresses.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin unless existing bins
    // are all nearly full or the item is huge.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let urgency = (item_size as f64 / bin_capacity as f64).max(avg_fill);
        score += 45.0 * (1.0 - urgency);
    }

    // Early stream: slightly favor consolidating into fewer bins.
    score += (1.0 - progress) * 3.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: minimize wasted space, with non-linear penalty on small residuals (dead space)
    let mut score = post;

    // Quadratic-cubic dead-space penalty: residuals that are too small to ever fit
    // another item (min item size 1, but realistically small slivers) are heavily penalized.
    let dead = (1.0 - pr).powi(3);
    score += 40.0 * dead;

    // Smooth coupling of post_residual with stream progress: late in the stream,
    // prefer tighter packing (larger post residual penalized more).
    let late_factor = 1.0 + 2.0 * progress * progress;
    score += late_factor * (pr * pr) * 20.0;

    // Reward using nearly-full bins (small post_residual) more strongly as stream advances
    score -= 15.0 * progress * (1.0 - pr).powi(2);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // Mild penalty when many bins compete but this one is a poor fit
        let crowding = (fitting_bins_count as f64).ln().max(1.0);
        score += 5.0 * pr / crowding;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 25.0 * (1.0 - slack).max(0.0);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 8.0 * ((nxt - post) / cap).min(1.0);
        }
    }

    // Prefer bins whose residual is close to the mean residual (balance load smoothly)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Encourage opening new bins early when many bins are already open and residual is large
    let new_bin_pull = (open_bins_count as f64) * progress * pr * 2.0;
    score += new_bin_pull;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "reusable"
    // classes (small or large multiples), penalize awkward mid-range remainders.
    let post = post_residual as i64;
    if post > 0 {
        // class by integer division into capacity eighths
        let class = post / (bin_capacity as i64 / 8);
        match class {
            0 => score -= 12.0,                       // tiny leftover: near-perfect fit
            1 => score -= 4.0,                        // small usable gap
            2 | 3 => score += 6.0,                    // awkward mid gap (fits little)
            _ => {}                                   // large residual: fine
        }
        // modulo-based harmony: residuals divisible by common item sizes are reusable
        if post % 10 == 0 { score -= 3.0; }
        if post % 5 == 0 { score -= 1.5; }
        if post % 20 == 0 { score -= 2.0; }
    } else {
        // perfect fill: strongly favored
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 && (next_item_size as i64) <= post {
        let waste = post - next_item_size as i64;
        score -= 10.0 - (waste as f64).min(10.0);
    } else if next_item_size > 0 {
        score += 3.0; // next item won't fit here
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer tightening existing bins over spreading
    let t = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * (0.5 + t);
    score += crowding * 0.05 * (post as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powf(2.0);
        let open_pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 * (0.6 + 0.4 * tightness)
              - open_pressure * 8.0
              - if next_item_size > 0 && next_item_size <= bin_residual { 4.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps left after placement are nearly unusable
    // (min item size ~1..100 unknown, but small residuals waste capacity). Penalize hard.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    } else if post_residual > 12 && post_residual <= 25 {
        score += 10.0;
    }

    // Reward exact / very tight fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual before placement was small (good compaction).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize choosing a bin less, i.e., subtract, but add pressure to new bins below).
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // fits poorly everywhere else or no bins exist.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 || fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 40.0; // last-chance bin exists: avoid opening new one
        } else {
            // Prefer new bin only if item is large relative to typical residuals
            // and next item likely needs fresh space.
            let prog = step_index as f64 / (total_items.max(1) as f64);
            let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
            let next_big = (next_item_size as f64 / bin_capacity as f64) > 0.6;
            if big_item && next_big && prog < 0.8 {
                score -= 15.0;
            } else {
                score += 30.0 + mean_residual * 0.2;
            }
        }
    }

    // Lookahead: if the post residual can host the next item, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post residual too small for next item: mild penalty scaled by waste
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item: reward tight-but-viable fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }

    // Penalize dead space: post-residual too small for the next item (and below
    // the minimum plausible item size of 1, treat < next_item_size as waste).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating very small unusable slivers relative to mean residual.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
        score += 15.0;
    }

    // Prefer tighter bins (small residual before placement) slightly.
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_residual as f64);

    // Penalize dead space that is too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // stranded residual blocks future packing
        }
        // Perfect pairing: item + next item exactly fills bin.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless this is a
    // very large item or existing residuals are poorly matched.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred by default.
        score += 20.0;
        // Large items open bins more readily.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If mean residual barely fits the item, opening fresh is fine.
        if mean_residual < item_size as f64 * 1.1 {
            score -= 12.0;
        }
        // Early in stream, new bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is large and this item is small, keep small items
        // in open bins; open new bins for medium items.
        if next_item_size > 60 && item_size < 30 {
            score += 8.0;
        }
    } else {
        // Mild bonus for keeping many small bins consolidated.
        score -= 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        // Prefer placing into bins whose residual is close to item size
        // (best-fit sharpening).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * gap;
    }

    // Global pressure: when many bins are open, discourage waste.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = post * post / (cap * cap) * (0.5 + progress);
    score += 0.6 * poly;

    // Penalize dead space more later in the stream
    score += progress * (post / cap) * (post / cap);

    // Reward tight fits (small post_residual) smoothly
    score -= 0.4 * (1.0 - post / cap) * (1.0 - post / cap);

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead: bonus if next item fits in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 0.3 * (nxt / cap);
        } else {
            score += 0.2 * (1.0 - post / cap);
        }
    }

    // Relative residual vs mean residual: prefer bins below mean residual (tighter)
    score += 0.15 * (post - mean_residual) / cap;

    // Mild penalty for many open bins to encourage consolidation
    score += 0.01 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-zero (perfect fit) heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Class of post_residual by division into harmonic bands of capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let band = (pr / cap * 4.0).floor(); // 0..3
    match band as u32 {
        0 => score -= 30.0,       // tiny dead space: good packing
        1 => score += 10.0,       // quarter-class: mediocre
        2 => score += 5.0,        // half-class
        _ => {}                   // large residual: neutral
    }

    // Modulo classes: residuals that are multiples of common item sizes (10,20,25,50)
    // are more "usable" — reward divisibility.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 10 == 0 { score -= 8.0; }
        if pr_u % 25 == 0 { score -= 6.0; }
        if pr_u % 50 == 0 { score -= 6.0; }
    }

    // Coupling with next item: if next item fits exactly in post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits with small leftover
            let next_left = post_residual - next_item_size;
            if next_left <= 10 { score -= 25.0; }
            score -= (next_left as f64) * 0.15;
        } else {
            // next item won't fit here: penalize leaving mid-range dead space
            score += pr * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score += 55.0;
        if item_size > bin_capacity / 2 { score -= 20.0; }
        if open_bins_count == 0 { score -= 60.0; }
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            // no open bin can meaningfully hold future items
            score -= 15.0;
        }
        let _ = fragmentation;
    }

    // Slight preference for tighter bins overall (smaller residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Mild stream-progression coupling: later in stream, be more conservative
    // about spreading (favor filling existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.05 * progress;

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps bin classes balanced).
    score -= ((mean_residual - pr) * 0.03).abs().copysign(1.0) * ((mean_residual - pr) * 0.03).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small waste relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing
    // ones rather than spreading; when few are open, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bin count is already high.
        score += 8.0 + 6.0 * pressure;
        // But if no existing bin fits well (large waste), new bin is fine.
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        score -= 2.0 * pressure;
    }

    // Lookahead: if next item fits into this bin's post_residual, reward.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 18.0;
    } else if next_item_size > 0 && (post_residual as i64) < 10 {
        score += 10.0;
    }

    // Mean residual coupling: bins far below mean residual are "loose";
    // prefer putting items there to consolidate space.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.15 * dev;
    }

    // Late in stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect chain fit: next item exactly fills the leftover space.
        let slack_after_next = post_residual - next_item_size;
        score -= (post_residual as f64) * 0.6;           // deep lookahead preference
        if slack_after_next == 0 {
            score -= 25.0;                                // exact two-item fill: ideal
        } else if slack_after_next < 10 {
            score -= 12.0;                                // near-perfect chain
        }
        // Relative-to-mean coupling: bins with more room than average are better chain hosts.
        score -= ((post_residual as f64) - mean_residual).clamp(-50.0, 50.0) * 0.15;
    } else if next_item_size > 0 {
        // Next item cannot follow: leftover becomes potential dead space.
        // Penalize proportionally to how wasted the space is relative to capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * 30.0;
    }

    // Penalize large absolute leftover more than linearly (dead space grows in value).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny sliver: nearly full bin, great packing
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is unusable.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive early or when no fitting bins exist.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large upcoming items favor fresh bins
        }
    }

    // Mild pressure against hoarding many open bins with large residuals.
    score += (open_bins_count as f64) * 0.05 * ((post_residual as f64) / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual waste super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that nothing typical can use (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh bins should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global fragmentation.
        let frag = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        score = 55.0 + 30.0 * frag;

        // Early in the stream, opening bins is cheap (build a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);

        // If next item is large and no open bin can host both, new bin is attractive.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 25.0;
        }
        // Late stream: prefer closing out existing bins; new bins cost more.
        score += 25.0 * progress;
    }

    // Mild preference for bins below mean residual (consolidate waste).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Slight penalty for bin count pressure: keep pool usage efficient.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 2.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer tight fills (low post_residual), with smooth polynomial shaping
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; later, penalize it more strongly.
    let prog_term = post / cap * (0.5 + 1.5 * progress * progress);
    score += prog_term;

    // Reward high fill ratio (item nearly fills the bin) with smooth cubic term
    score -= fit_ratio * fit_ratio * fit_ratio * 2.0;

    // Penalize dead space that is too small to fit typical items (smooth quadratic)
    let dead = post / cap;
    score += dead * dead * 3.0 * (1.0 - fit_ratio);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead: if next item fits the post residual, reward this placement smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 0.8 * (1.0 - nxt / cap);
        } else {
            // smooth penalty proportional to how much the next item overflows this residual
            score += 0.4 * ((nxt - post) / cap).min(1.0);
        }
    }

    // Mild pressure to consolidate when many bins are open (smooth in open_bins_count)
    score += 0.05 * (open_bins_count as f64).sqrt() * dead;

    // Deviation from mean residual: prefer bins whose residual is close to mean (balanced use)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 1.2 - 0.8 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 10 are
    // more reusable for typical item sizes; penalize awkward dead space.
    let pr = post_residual;
    let harm = (pr % 10) as f64;
    score += harm * 0.6; // residue within decade: larger offset = worse fit

    // Perfect closure reward
    if pr == 0 {
        score -= 40.0;
    } else if pr < 10 {
        // tiny dead space is nearly worthless
        score += 12.0;
    }

    // Integer-division threshold: post_residual in a harmonic class that
    // matches the lookahead item size is very desirable.
    if next_item_size > 0 && pr >= next_item_size {
        let class_match = (pr / 10) == (next_item_size / 10);
        if class_match {
            score -= 15.0;
        }
        // Reward residual that can still host the next item
        score -= 8.0;
    } else if next_item_size > 0 && pr > 0 {
        // residual cannot host next item -> dead space risk
        score += (next_item_size as f64) * 0.25;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty so we don't open bins frivolously
        score += 20.0;
        // but if the current bin would leave a large awkward residual, allow opening
        if pr > bin_capacity / 2 {
            score -= 18.0;
        }
        // early in the stream, keeping bins tight matters less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Coupling with mean residual: if this bin is far below average residual,
    // it is already "tight" — filling it further is good.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.15;

    // Modulo coupling on capacity fraction: bins whose residual is a small
    // fraction of capacity are prime targets.
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += frac * 6.0;

    // Many open bins: discourage spreading into fresh bins
    if open_bins_count > 4 && !is_new_bin {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals below the minimum item size (1..10)
    // are unusable gaps. Penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (10.0 - post_residual as f64) * 2.0;
    }

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with below-average residual (denser bins) slightly.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits in the post residual, reward leaving room.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin is a good fit (poor fill ratio on existing bins) and the
    // item is large. Otherwise penalize new bins to avoid bin proliferation.
    if bin_residual == bin_capacity {
        if fill_ratio > 0.7 || fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 150.0 + open_bins_count as f64 * 5.0;
        }
    }

    // Mild stream-progression term: later in the stream, be slightly more
    // conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, with a superlinear penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / bin_capacity as f64;

    // 2-step lookahead: reward if next item exactly fills the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 60.0; // perfect chaining: next item seals this bin
        } else if nxt <= pr {
            // next item fits here: reward proportional to how much would remain
            let chain_left = pr - nxt;
            score -= 25.0 * (1.0 - chain_left / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize bins that would strand space
            score += 0.15 * (nxt - pr).min(40.0);
        }

        // Coupling with mean residual: if this bin's post-residual deviates
        // from the fleet mean, adjust. Keeping residuals homogeneous leaves
        // more combinable space for future items.
        let dev = (pr - mean_residual).abs();
        score += 0.05 * dev;

        // If next item fits the mean residual better than this bin's post
        // residual, this bin is a worse host for the chain.
        if nxt <= mean_residual && nxt > pr {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * (post_residual as f64);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // early in the stream or when the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let huge = item_size as f64 > 0.7 * bin_capacity as f64;
        if huge || (open_bins_count == 0) {
            score -= 40.0;
        } else {
            score += 15.0 + 30.0 * progress;
        }
    }

    // Mild pressure against spreading across many open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize small dead space that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding penalty: many open bins -> prefer filling existing ones
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.3 * crowding;

    // Time horizon: early in the stream, be picky (penalize mediocre fits);
    // late in the stream, accept anything that fits
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 10.0;

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only open a new bin when current item is large
    // and no tight fit is available elsewhere
    if bin_residual == bin_capacity {
        score += 30.0 - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap; // 0..1 usable space fraction

    // Smooth polynomial coupling: penalize mid-range residual more than tight fits
    let shape = 4.0 * fit_ratio * (1.0 - fit_ratio); // peaks at 0.5 residual (dead space)
    score += 12.0 * shape * (1.0 + prog);

    // Reward tight fits, stronger as stream progresses
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 18.0 * (0.5 + prog);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * prog;
    }

    // Lookahead: favor bins whose post-residual can host next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - (pr / (next_item_size as f64 + 1.0)).min(1.0));
    }

    // Mean residual context: prefer bins deviating below mean (consolidate)
    score += (pr - mean_residual) * 0.15;

    // New-bin candidate: penalize mildly early, more when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead space" classes.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.6; // penalize residuals in awkward classes

    // Perfect/near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Harmonic tier of post_residual via integer division thresholds.
    let tier = post_residual / 25; // 0..3 tiers
    score += match tier {
        0 => 0.0,
        1 => 5.0,
        2 => 12.0,
        _ => 20.0,
    };

    // Lookahead: reward bins whose post_residual harmonically matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 20.0 - gap as f64;
            } else {
                score += (gap as f64) * 0.15;
            }
        } else {
            // next item cannot fit here; mild penalty proportional to shortfall
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Opening a new bin is more attractive early in the stream or when
        // mean residual across open bins is small.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        score += (mean_residual / bin_capacity as f64) * 25.0;
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.3;

    // Coupling: item size classes interact with residual class.
    let item_class = item_size / 20; // 0..4 harmonic item tier
    score += (item_class as f64) * (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that cannot fit even the smallest plausible item (size 1..100,
    // but gaps below ~10 are almost surely dead) is pure waste.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 40.0 * (10.0 - gap);
    }
    // Mildly penalize moderately small gaps that few future items can use.
    if gap >= 10.0 && gap < 30.0 {
        score += 0.6 * (30.0 - gap);
    }

    // Reward near-perfect fits strongly.
    if gap == 0.0 {
        score -= 25.0;
    } else if gap <= 5.0 {
        score -= 8.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, opening a new one is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open (avoid opening
        // unnecessarily), but discount the penalty when current fit is poor.
        score += 18.0 + 6.0 * pressure;
        // If this bin is the only fitting option, opening a new bin is wasteful.
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
        // If the next item is large and mean residual is small, a fresh bin
        // can be attractive: soften the penalty.
        if (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward being a good steward of open capacity.
        score -= 2.0 * pressure;
        // Last-chance bin: strongly prefer using it to avoid bin proliferation.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Lookahead: if next item fits exactly in the post residual, big bonus.
        if next_item_size > 0 && (next_item_size as u32) == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 4.0;
        }
    }

    // Slight progression term: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (gap == 0.0 as u32 as f64) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Slack left for next item, but penalize wasted slack proportionally.
        let slack = (post_residual - next_item_size) as f64;
        score += 0.35 * slack;
    } else if next_item_size > 0 {
        // Next item cannot fit here afterwards; penalize more if gap is small.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.9 * gap;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Compare against mean residual: prefer bins that use up excess space.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin still helps the lookahead
        }
    }

    // Prefer denser packing as stream progresses.
    score += 0.1 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for any plausible item (min size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // awkward zone
    }

    // Lookahead: reward if next item can fit into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to waste gap.
            score += 0.03 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Competition among many fitting bins: mild preference, scaled by scarcity.
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit is bad or open bins are crowded.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted when many bins are open (consolidation pressure low)
        // and when the current item is large (large items in fresh bins keep flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 45.0 - 0.15 * (item_size as f64);
        if open_bins_count > 4 {
            new_bin_score += 2.0; // too many open bins, discourage more
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // no alternative: must open
        }
        // Late in stream, prefer consolidating into existing bins.
        new_bin_score += 10.0 * progress;
        score = score.min(new_bin_score) * 0.0 + new_bin_score.max(score - 40.0);
        // Ensure fresh bin is chosen only when existing fits are poor:
        score = new_bin_score;
    }

    // Mean-residual coupling: if average residual across bins is high,
    // encourage packing into existing bins (subtract slightly for all open bins).
    score -= 0.02 * mean_residual;

    // Time-horizon modulation: early stream, be greedy for tight fits;
    // late stream, favor any fit to avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 1.5 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: minimize post residual, smoothed with a quadratic dead-space penalty
    let mut score = post_norm * (1.0 + 2.0 * post_norm);

    // Non-linear coupling of post residual with stream progress:
    // late in the stream, tight fits matter more; early, flexibility is valuable.
    let tightness = 1.0 - post_norm * post_norm;
    score -= progress * tightness * 0.6;

    // Penalize bins far from the mean residual (fragmentation avoidance),
    // with a smooth cubic coupling to progress.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * (0.3 + 0.5 * progress * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // unless the resulting residual is huge dead space.
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - post_norm * post_norm);
    }

    // Lookahead: reward residuals that can accommodate the next item,
    // with a smooth cosine-like shaping term.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post - next_item_size as f64) / cap;
        score -= 0.4 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 0.3 * progress;
    }

    // Mild pressure against proliferating bins late in the stream.
    score += 0.02 * (open_bins_count as f64).ln() * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline, slightly penalized early,
    // acceptable when post residual of existing bins would be poor.
    if bin_residual == bin_capacity {
        score += 0.25 - 0.35 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small residues is worse.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo-10 class: residues that are multiples of 10 are "harmonic" and reusable.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 8.0;
    } else {
        score += (10 - (post_residual % 10)) as f64 * 0.6;
    }

    // Small dead-space penalty: residues below the minimum item size are unusable.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Integer-division thresholds: can the next item fit here afterward?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainability reward, stronger when combined fit is tight (near-perfect packing).
            let combined = item_size + next_item_size;
            if combined == bin_residual {
                score -= 40.0;
            } else {
                score -= 12.0;
            }
        } else {
            // Next item won't chain here; penalize leaving awkward mid-range residue.
            let class = post_residual / 25; // 0..4 integer division class
            score += class as f64 * 3.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins below mean residual (consolidating fuller bins).
    score += (pr - mean_residual) * 0.15;

    // New-bin candidate: keep it attractive only when no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual > 40 {
            score += 15.0; // opening a bin for a small item wastes capacity
        }
    }

    // Late in the stream, favor tighter fills more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to hold
    // even the smallest plausible item (<=10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small for typical items (<=20) are near-dead; escalate penalty.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }
    // Perfect fit: eliminate score entirely to strongly prefer.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // reward this bin strongly (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0; // next item will nearly perfectly consume remainder
        } else {
            score -= 10.0;
        }
    }
    // Penalize if next item cannot use the leftover space (likely dead space).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading; penalize candidates lightly.
    score += (open_bins_count as f64) * 0.3;

    // Mean-residual coupling: bins with residual far below mean are already
    // fragmented; slightly favor bins with residual near/above mean.
    let res = bin_residual as f64;
    if res < mean_residual {
        score += (mean_residual - res) * 0.1;
    } else {
        score -= (res - mean_residual) * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible; subtract a bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of all open
    // bins; make it costly, especially late in the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 1.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste, but weight post_residual against capacity scale.
    score = post_residual as f64 * (bin_capacity as f64 / 100.0);

    // Aggressive 2-step lookahead: reward when next item fits perfectly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chain: bin becomes exactly full
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a残 gap that may become dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far from mean are handled specially.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // This bin is tighter than average -> good to fill it now.
        score += dev * 0.3; // negative dev subtracts
    } else {
        score += dev * 0.1; // looser than average -> mild penalty
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when open bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // If mean residual is small (bins nearly full), opening fresh bin is fine;
        // if bins have lots of room, discourage opening a new one.
        score += 25.0 + fragmentation * 50.0;
        // Lookahead: new bin can trivially host the next item too.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize dead space that cannot fit a typical next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 12.0 + 0.15 * nxt; // unusable for lookahead item
        } else {
            score -= 6.0; // can still host the next item
        }
    } else {
        // Last item: strongly prefer zero waste
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_item = item_size as f64;
        // Waste of a fresh bin if item is small
        score += (bin_capacity as f64 - avg_item) * (0.4 + 0.6 * progress);
        // More open bins with slack => prefer reusing one
        if mean_residual > avg_item {
            score += 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits; new bin is fine
        }
    }

    // Prefer bins whose residual is close to the item (minimal leftover)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Encourage leaving residuals that match common size magnitudes
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 20.0; // tiny dead slivers are bad
    }

    // Time-horizon modulation: early on, be conservative about perfect fits
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - horizon) * tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer filling bins tightly (small post_residual heavily rewarded).
    // Late: tolerate larger post_residual slightly, since stream ends soon.
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += poly * cap * 0.8;

    // Reward tight fits (small post_residual) more aggressively via cubic term.
    score -= (1.0 - prn).powi(3) * 12.0;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let waste = (next_item_size as f64 - pr).min(cap);
        score += waste * (0.5 + 0.5 * (1.0 - progress));
    } else if next_item_size > 0 {
        // Reward bins whose post_residual still accommodates the next item.
        score -= 4.0 * (pr - next_item_size as f64).max(0.0) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin, more so early on,
    // unless it is the only option; dampen penalty late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mild penalty for deviating from mean residual (balance load).
    score += ((pr - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity-fraction classes.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows super-linearly for small unusable residuals.
        let pr = post_residual as f64;
        let frac = pr / bin_capacity as f64;
        // Harmonic class by integer division thresholds: 1..=10, 11..=25, 26..=50, 51..=100
        let class: f64 = if post_residual <= 10 {
            0.0 // nearly dead space
        } else if post_residual <= 25 {
            1.0
        } else if post_residual <= 50 {
            2.0
        } else {
            3.0
        };
        // Penalize low classes (unusable space), scaled by fraction.
        score += (3.0 - class) * 15.0 * (1.0 + frac);

        // Modulo-arithmetic coupling: residuals divisible by common item sizes (10/20/25)
        // are more reusable; reward them.
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 5.0; }
        if post_residual % 25 == 0 { score -= 5.0; }

        // If next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0;
            } else if next_item_size < post_residual {
                // Reward proportionally to how well next item fills remaining space.
                let fill = next_item_size as f64 / pr;
                score -= 60.0 * fill;
            } else {
                // Next item cannot fit: slight penalty scaled by how much it overshoots.
                score += 10.0;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 80.0;
        } else if fitting_bins_count > 1 {
            // Slight preference for tighter bins when alternatives exist.
            score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
    }

    // New-bin candidate handling: neutral baseline with mild penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + (open_bins_count as f64) * 2.0;
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += (mean_residual - 30.0).max(0.0) * 1.5;
    }

    // Tie-breaking: prefer bins with residual close to item size (tight fit) generally.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for typical items are wasted.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when the item
    // would leave a large, reusable gap or no good open bin exists.
    if bin_residual == bin_capacity {
        // Neutral base; discourage when many open bins already fit well.
        score += 30.0;
        if post_residual as f64 >= mean_residual {
            score -= 25.0;
        }
    }

    // Pressure from number of open bins: consolidate when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize if next item is larger than residual (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Slight preference for bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Small slack after next item => excellent chain fit.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 150.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportional to the unusable gap.
        let gap = next_item_size as f64 - post_residual as f64;
        score += 0.5 * gap;
    }

    // Relative residual coupling: bins tighter than the mean are better targets.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening a new bin unless the current bin is a genuinely poor fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is attractive only when no tight fit exists elsewhere.
        score += 80.0;
        if post_residual as f64 >= mean_residual {
            score += 40.0;
        }
        // If next item is large and this fresh bin could chain it, keep it competitive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 90.0;
        }
        // Late in the stream, avoid wasting bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot fit future items.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 40.0 * dead * dead * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual + 10 {
        score += 5.0; // near miss: wasted chain opportunity
    }

    // Prefer bins with below-mean residual (save roomy bins for larger items).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Early stream: encourage opening new bins for large items; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    if new_bin > 0.0 {
        // New bin attractive for large items or when no tight fit exists.
        score += 5.0 - 20.0 * tightness - 10.0 * progress;
        if item_size > 50 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size > post_residual.min(0) {
            // placeholder no-op to keep new-bin logic simple
        }
    } else if post_residual <= 5 {
        // Nearly full bins are great to fill up.
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins early.
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let progress_poly = t * t * (3.0 - 2.0 * t); // smoothstep
    score += prn * prn * (1.0 - progress_poly) * 12.0; // penalize wasted space early
    score -= prn * progress_poly * 6.0; // reward tight fits late

    // Interaction: post_residual vs mean residual deviation
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Reward using nearly-full bins (small post residual) more strongly as stream advances
    score -= (1.0 - prn).powi(3) * (4.0 + 10.0 * t);

    // Last-chance bin bonus (avoid opening a new bin when only one fits)
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress_poly;
    }

    // Lookahead: penalize leaving residual that cannot fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 3.0 * (nx - pr) / cap * (1.0 + t);
        } else {
            score -= 1.5 * (pr - nx).min(20.0) as f64 / cap;
        }
    }

    // New-bin candidate: prefer it only when residuals are very tight late in stream
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).max(0.0).min(1.0);
        score += 15.0 - 12.0 * t - 5.0 * tightness;
        score += prn * prn * 10.0 * (1.0 - t);
    }

    // Mild penalty for bin sprawl
    score += 0.02 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual near 0 gets strong discount.
    score -= 30.0 * (-post / 8.0).exp();

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Dead space classes that are hard to fill (1..9 small residues) get penalized,
    // while residues that pair with common item sizes get rewarded.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => 6.0,                 // perfectly aligned class (e.g. 10,20,...) — reusable
        2 | 4 | 6 | 8 => 2.0,     // even class — moderate reusability
        5 => 3.0,                 // half-capacity class
        1 | 3 | 7 | 9 => -4.0,    // odd awkward class — likely dead space
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: post_residual >= 50 keeps half a bin usable.
    if post_residual >= 50 {
        score -= 4.0;
    } else if post_residual < 10 {
        score += 3.0; // tiny sliver, nearly dead
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            score += 2.0; // next item won't fit here; this bin is closing anyway
        }
    }

    // Prefer filling already-open bins when many are open (avoid bin sprawl).
    score -= (open_bins_count as f64).sqrt() * 0.5;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * (0.3 * progress);

    // Slight preference for bins tighter than the current mean residual.
    score -= (mean_residual - post) * 0.1;

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A gap is "dead" if the next item cannot fit into it.
        let dead = next_item_size > 0 && post_residual < next_item_size;
        // Also treat tiny gaps (< 10) as dead regardless.
        let tiny = post_residual < 10;
        if dead || tiny {
            // Non-linear penalty growing as the gap becomes more useless.
            let gap_ratio = post_residual as f64 / bin_capacity as f64;
            score += 60.0 * (1.0 - gap_ratio) * (1.0 - gap_ratio);
        } else {
            // Usable residual: reward proportionally (subtract).
            let fit_ratio = post_residual as f64 / bin_capacity as f64;
            score -= 15.0 * fit_ratio;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item in this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // Penalize if placing here blocks the next item while other bins might handle it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Mild preference to fill bins below mean residual (compactness).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Opening a new bin gets more expensive as bins accumulate, but cheap
        // early in the stream or when the current item is large.
        score += 30.0 + 3.0 * pressure - 0.2 * item_size as f64;
        // If next item is small, a fresh bin is fine (it can absorb it).
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item's size (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild bonus proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack / 20.0);
        } else {
            // Next item would NOT fit here: penalize proportionally to the miss.
            let miss = (next_item_size - post_residual) as f64;
            score += 40.0 * (miss / 50.0).min(2.0);
        }
    }

    // Tightness relative to mean residual: prefer tighter-than-average bins.
    let tightness = mean_residual - post_residual as f64;
    score -= 0.8 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize leaving small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // New-bin candidate: make it unattractive unless this is the last item
    // or no real benefit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size == 0 {
            score += 100.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 200.0 * (1.0 - progress);
        // If very few bins can fit the item, new bin is a reasonable fallback.
        if fitting_bins_count <= 1 && bin_residual >= item_size {
            score -= 180.0;
        }
    }

    // Mild scaling of base residual by stream progress: later in the stream,
    // be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item / resid.max(1.0);
    score -= 2.5 * fill_ratio * fill_ratio * resid;

    // Penalize dead space: small post-residual is good, but useless slivers (<10)
    // are wasted unless they are exactly zero (perfect fit).
    if post_residual == 0 {
        score -= 30.0; // perfect fit jackpot
    } else if post_residual < 10 {
        score += 8.0; // sliver penalty
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_quality = (post_residual - next_item_size) as f64;
        score -= 1.2 * (1.0 - pair_quality / cap);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0; // leftover blocks the lookahead item
    }

    // Last-chance logic: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is expensive; make it costly unless
    // the item is huge or fits are everywhere-poor.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0 + 0.3 * open_bins_count as f64;
        let urgency = (item / cap) * (1.0 - progress); // big items early justify new bins
        score += base_penalty - 25.0 * urgency;
        // If many bins already fit the item, opening a new one is clearly wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 + 5.0 * (fitting_bins_count as f64).min(6.0);
        }
        // Perfect-fit potential with lookahead: a fresh bin can host item + next exactly.
        if next_item_size > 0 && item + next_item_size as f64 >= cap - 1.0 {
            score -= 20.0;
        }
    }

    // Global state modulation: when mean residual across open bins is high,
    // consolidation into existing bins matters more.
    let mean_gap = (mean_residual - resid) / cap;
    score += 2.0 * mean_gap;

    // Time-horizon effect: late in the stream, waste tolerance shrinks.
    score *= 1.0 + 0.5 * progress;

    // Mild penalty for leaving large residuals when many bins are open (fragmentation).
    if open_bins_count > 3 {
        score += 0.05 * post * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Quadratic waste penalty: small post-residuals are disproportionately valuable
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Cubic coupling of post_residual with stream progress: late in the stream,
    // tight fits matter even more (less time to reuse leftover space)
    let t = progress * (1.0 - progress) * 4.0; // peaks mid-stream at 1
    score -= 25.0 * (1.0 - norm_pr) * (1.0 + progress * progress) * (1.0 - 0.3 * t);

    // Exact fit bonus (post_residual == 0)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead synergy: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_gap = pr - ns;
            score -= 20.0 * (1.0 - fit_gap / cap) * (1.0 - progress);
        } else {
            score += 10.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 - progress);
    }

    // Penalize opening new bins when many open bins still have room
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        score += 15.0 + 0.5 * mean_r + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // New bins are more acceptable early and when mean residual is low
        score -= 20.0 * (1.0 - mean_r / cap) * (1.0 - progress);
    }

    // Mild preference for bins tighter than the mean (consolidation)
    score += 0.3 * (pr as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (C/8 classes)
    let cap_frac = (item_size * 8) / bin_capacity; // 0..=8
    let next_frac = if next_item_size > 0 { (next_item_size * 8) / bin_capacity } else { 9 };

    // Reward tight fits: low post_residual is good
    score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // Perfect fit bonus (post_residual is a small harmonic residue)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Dead-space penalty: post_residual too small for the smallest item (1)
    // but small enough to be wasted for typical items (harmonic dead zones)
    if post_residual >= 1 && post_residual <= 9 {
        // small unusable sliver — mild penalty unless it's zero
        score += 4.0;
    }

    // Modulo-class pairing: reward bins whose post_residual complements
    // the next item's size class
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0; // next item fills bin perfectly
        } else if gap <= 10 {
            score -= 10.0;
        }
        // harmonic class match: same eighth of capacity
        if cap_frac == next_frac {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // bin becomes unusable for the lookahead item
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // fit is poor and we are early enough in the stream to amortize it
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual > 30;
        if poor_fit && progress < 0.7 {
            score -= 18.0;
        } else {
            score += 15.0;
        }
    }

    // Prefer bins with below-average residual (compact full bins first)
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 6.0 * dev;

    // Integer-division threshold on post_residual: quarter-capacity buckets
    let quarter = post_residual / (bin_capacity / 4);
    score += quarter as f64 * 2.0;

    // Slight preference for fewer open bins when many are open
    if open_bins_count > 8 {
        score += 0.05 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
