    // Slight late-stream tightening: as stream progresses, be greedier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    // New-bin candidate: make empty bins attractive only when nothing fits well.
    if bin_residual == bin_capacity {
