        score -= 60.0;
    }

    // Penalize leaving dead space that no plausible item (>=1) can use poorly:
    // small but nonzero post_residual is dangerous dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            score += 6.0;
        }
        // If next item exactly fills the leftover, big bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many alternatives: mild penalty to keep flexibility for future items.
    if fitting_bins_count > 3 {
        score += 4.0 * (fitting_bins_count.min(10) as f64 - 3.0);
    }

    // New-bin candidate logic: opening a fresh bin is attractive when open bins
    // are crowded or the fit is loose, but wasteful early in the stream or when
    // a tight fit exists.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual across open bins is small (bins are full)
        // and there are already several bins; penalize new bins early on.
        score += 30.0 * (1.0 - crowding) + 15.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        // If this bin would leave the item with lots of slack, a new bin is fine.
        score -= 8.0;
    }

    // Mild preference for bins with residual close to mean (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time-horizon coupling: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fit is good (low post_residual lowers score)
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic-cubic polynomial in normalized post_residual
    // weighted by stream progress. Early on, prefer filling bins loosely (open more bins);
    // later, prefer very tight fits aggressively.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * 4.0; // peaks mid-residual, ~0 at 0 and 1
    score += poly * (60.0 + 140.0 * progress);

    // Penalize dead space that cannot fit a plausible next item (lookahead-aware)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && pr < nx {
            score += (nx - pr) * (1.5 + 2.5 * progress);
        } else if pr >= nx {
            score -= (pr - nx).min(30.0) * (0.4 + 0.6 * progress) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 60.0 * progress;
    }

    // Slight penalty when bin is far below mean residual (keeps residual distribution balanced)
    score += (mean_residual - pr).abs() * 0.15;

    // Mild preference for using existing bins over opening new ones early
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // small integers are more "usable" by future items -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }        // perfectly harmonic slot
        else if pr % 5 == 0 { score -= 6.0; }
        else if pr % 2 == 0 { score -= 2.0; }
        // dead-space penalty for tiny unusable remainders
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 8.0; }
    } else {
        // perfect fill is ideal
        score -= 40.0;
    }

    // Lookahead: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0;
            if slack as u32 % 10 == 0 { score -= 5.0; }
            if slack < 10.0 { score -= 6.0; } // near-exact fit for next item
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when existing residuals are badly
    // fragmented relative to the item (i.e. item leaves large waste everywhere).
    if bin_residual == bin_capacity {
        // neutral baseline: new bin costs one unit of future capacity
        score = (bin_capacity - item_size) as f64 + 6.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual > (item_size as f64 * 1.5) {
            score += 10.0 * (1.0 - progress); // early on, prefer consolidation
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0; // fresh bin accommodates lookahead too
        }
    }

    // Slight preference for tighter (fuller) bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    // Treat a gap as "dead" if it's smaller than the smallest plausible item (1) scaled by
    // observed stream position — early on, keep gaps flexible; later, tolerate tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = 3.0 + 7.0 * (1.0 - progress); // 10 early -> 3 late

    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }

    // Reward tight fits strongly (post_residual near 0 or exactly matching a usable gap).
    if post_residual == 0 {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect slot for the lookahead item: excellent placement.
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Gap can still host the next item: keep it attractive.
        score -= 8.0;
    } else if next_item_size > 0 {
        // Gap cannot host next item: penalize proportionally to how wasted it is.
        let waste = post_residual as f64 - (next_item_size as f64) * 0.5;
        if waste > 0.0 {
            score += waste * 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual as f64 <= dead_threshold {
            score -= 10.0; // last chance AND decent fit
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let bin_pressure = open_bins_count as f64 * 0.6;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has residual == capacity. Make it moderately
    // attractive by default but not so attractive that we abandon nearly-full bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with the number already open.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // If the current item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 20.0;
        }
        // If the next item is large and no open bin would fit it, opening fresh is safer.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        score += progress * 10.0;
    }

    // Mild alignment with mean residual: prefer bins whose residual is below average
    // (i.e., already partially filled) to keep a set of diverse gap sizes.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // exactly fills the post_residual (perfect chaining).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect two-item chain: near-perfect fill.
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tightly it fits.
            let tightness = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 300.0 * tightness;
        } else {
            // Next item does not fit: penalize dead space that blocks chaining.
            let waste = (nxt - post) / bin_capacity as f64;
            score += 150.0 * waste;
        }
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 80.0 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the tightest one (post_residual already does this),
        // but add a mild penalty to avoid spreading items across many bins.
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when the item is large relative to
    // typical residuals and no good chaining exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mean_tight = mean_residual / bin_capacity as f64;
        // Open a new bin if item is big and open bins are already loose.
        let attractiveness = fill_ratio * (1.0 - mean_tight);
        score = 150.0 - 120.0 * attractiveness + 20.0 * fill_ratio;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // New bin can also chain the next item.
            score -= 60.0;
        }
    }

    // Mild late-stream pressure to consolidate rather than open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: post_residual too small to ever be useful (< 10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving residual that wastes next item's options
            score += 5.0;
        }
    }

    // New-bin candidate handling: make fresh bins attractive only when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so new bins are chosen only for bad fits elsewhere
        score += 15.0;
        // Early stream: opening bins is cheaper (builds options)
        score -= 12.0 * (1.0 - progress);
        // Many open bins with high mean residual: avoid opening more
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 20.0;
        }
        // Large items prefer fresh bins
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual is closest to item (best fit refinement)
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fit_ratio;
        // Prefer bins with residual near capacity (consolidate)
        score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Late stream: be conservative, minimize bin count pressure
    if progress > 0.8 {
        score += open_bins_count as f64 * 0.5;
    }

    // Mild penalty when this bin is one of many fitting options (keep options open)
    if fitting_bins_count > 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + (pr / cap).powi(2) * 20.0 + (pr / cap).powi(3) * 10.0;

    // Smooth progress coupling: later in the stream, tight fits matter more
    let tightness = 1.0 - pr / cap; // fraction filled
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize bins whose residual is far above the mean residual (wasteful fill)
    score += ((pr - mean_residual) / cap).abs() * (5.0 + 10.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // Mild penalty when many bins compete (spread items to preserve flexibility)
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack) * 12.0; // next item fits snugly
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly discourage late (wasted capacity is costlier later)
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress * progress;
        // allow new bin if item is large relative to capacity
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Slight penalty for very large open-bin count (bin proliferation)
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is bad if too small for typical items
    let pr = post_residual;
    if pr > 0 {
        if pr < 10 {
            // unusable dead space under minimum item size — heavy penalty
            score += 40.0 * (10 - pr) as f64;
        } else {
            // modulo-10 harmonic class: residuals divisible by 10 are more reusable
            if pr % 10 == 0 {
                score -= 8.0;
            } else if pr % 5 == 0 {
                score -= 4.0;
            }
            // small residuals (10..25) are hard to fill later
            if pr < 25 {
                score += (25 - pr) as f64 * 0.8;
            }
        }
    }

    // Lookahead coupling: does this bin remain useful for the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 6.0;
            // exact match with next item is excellent
            if pr == next_item_size {
                score -= 25.0;
            }
        } else {
            // bin becomes dead for the next item
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = 100.0 + item_size as f64 * 0.3;
        // prefer new bin if all existing fits would leave tiny dead space
        if pr > 0 && pr < 10 {
            score -= 45.0;
        }
        // many open bins with low mean residual: consolidation preferable
        if open_bins_count > 2 && mean_residual < 30.0 {
            score += 20.0;
        }
        // early in stream: keep bins open, cheap to consolidate later
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score += 15.0;
        }
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small unusable gaps (below min item size 1..=10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
    }

    // Prefer bins with residual below mean (denser bins first)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if next item fits this bin's post residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here; bonus scaled by how well it matches.
            let slack = (post_residual as f64 - next_item_size as f64);
            score -= 25.0 - slack.min(25.0);
        } else {
            // Next item does not fit; penalize leaving awkward space.
            let gap = (next_item_size as f64 - post_residual as f64);
            score += gap * 0.6;
        }
        // Perfect chain: post_residual equals next item exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 5.0;
    }

    // Penalize bins whose residual is far from the mean (outliers in waste).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only bin that can fit, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64;
        if crowded {
            score -= 8.0;
        } else {
            score += 10.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer residual fragments).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals more aggressively (dead space is quadratic waste).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state coupling: with many open bins, prefer tightening existing ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += pressure * (bin_residual as f64 - item_size as f64) * 0.05;

    // Mean residual alignment: prefer bins close to the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Time horizon: late in the stream, be conservative (favor tight fits even more).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // or nothing fits well; otherwise keep it slightly penalized.
    if bin_residual == bin_capacity {
        if item_size as f64 > 0.7 * bin_capacity as f64 || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        + 25.0 * pr_norm * pr_norm * pr_norm;

    // Smooth stream-progress coupling: late in the stream, penalize wasted space more
    let late = progress * progress;
    score += late * 30.0 * pr_norm;

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (pr - ni).max(0.0) / cap;
        score += 35.0 * waste * (1.0 + progress);
        // Mild reward if post_residual still accommodates next item
        score -= 8.0 * (1.0 - (pr / ni).min(1.0)) * (pr >= ni as u32) as i32 as f64;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr_norm;

    // Deviation from mean residual: prefer bins whose residual is close to mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score -= 10.0 * (1.0 - dev.min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    // Residuals in "small dead zones" (0..10) are near-perfect fits -> strong reward.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Integer-division thresholds: classify post_residual into harmonic bands of capacity/4.
    let quarter = bin_capacity / 4;
    let band = post_residual / quarter; // 0..4
    score += band as f64 * 6.0;

    // Modulo arithmetic: penalize residuals that waste prime slack (odd classes hard to fill).
    let m = post_residual % 5;
    if m == 1 || m == 4 {
        score += 4.0; // awkward residues
    } else if m == 0 {
        score -= 3.0; // divisible-by-5 residuals pair well with common item sizes
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this residual: penalize proportional to wasted space
        score += (post_residual as f64).min(40.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // if current bin fits are poor (high mean residual) or many bins are open.
    if bin_residual == bin_capacity {
        score = 45.0
            - (mean_residual / bin_capacity as f64) * 20.0
            - (open_bins_count.min(20) as f64) * 0.5;
        if post_residual == bin_capacity {
            // keep new-bin attractive when item is large relative to capacity
            score += item_size as f64 * 0.1;
        }
    }

    // Late in stream: prefer tighter packing, discourage fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * progress;

    // Favor bins whose residual is below mean (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

