    if next_item_size > 0 && post_residual > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += lookahead_gap * 1.5;

        // Exact chain: post_residual == next_item_size -> strong reward
        if post_residual == next_item_size {
