    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 60.0 + (fitting_bins_count as f64) * 30.0;
    }

    // Small residual is unusable dead space (below min item size 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large unusable dead space (non-linear squashing of small residuals).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += (dead * dead) / (bin_capacity as f64 * 4.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.5 * (next_item_size as f64);
        } else {
