        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.3 * open_bins_count as f64 * (0.5 + progress);

    // Align with mean residual: bins close to mean residual are safer choices.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: allow opening a fresh bin only when it enables a
    // large future slot and existing fit would be very tight.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let poor_fit = (bin_residual as f64 - item_size as f64) < 15.0;
        if poor_fit || (next_item_size > 0 && post_residual >= next_item_size && tightness > 0.5) {
            score -= 12.0;
        } else {
            score += 20.0 + 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr
        - 40.0 * (1.0 - prn) * (1.0 - prn) * (1.0 + progress)
        + 25.0 * prn * prn * (1.0 - progress);

    // Reward near-perfect fills, smoothly.
    score -= 30.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    // Penalize dead space below the smallest plausible item, smoothly damped by progress.
    let dead = (20.0 - pr).max(0.0) / 20.0;
    score += 35.0 * dead * dead * (1.0 - 0.5 * progress);

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - progress);
    }

    // Last-chance fitting bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 2.0 * open_bins_count as f64 * prn * progress;

    // New-bin candidate: keep it competitive only for large items / poor fits elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * (item_size as f64 / cap) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo thresholds on capacity
    let pr = post_residual;
    let class = pr % 20;
    // Penalize dead space in low-value harmonic classes (tiny unusable slivers)
    if pr > 0 && pr < 10 {
        score += 60.0; // dead space smaller than any item
    }

    // Integer-division thresholds: post_residual / 10 buckets
    let bucket = pr / 10;
    score -= bucket as f64 * 2.0;

    // Harmonic coupling: post_residual class vs next item size class
    if next_item_size > 0 {
        let fits_next = next_item_size <= pr;
        if fits_next {
            // Reward bins whose post_residual is in the same harmonic class as next item
            if pr % 10 == next_item_size % 10 {
                score -= 15.0;
            }
            score -= (next_item_size as f64).min(pr as f64) * 0.3;
        } else {
            // Next item won't fit here; penalize proportionally to wasted capacity
            score += (next_item_size as f64 - pr as f64) * 0.5;
        }
        // Exact match: next item fills this bin perfectly later
        if next_item_size == pr {
            score -= 120.0;
        }
    } else {
        // Last item: prefer tightest fit only
        score = pr as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty so new bins are used only when needed
        score += 150.0;
        // But if this is the only fitting candidate, allow opening a new bin
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
        // Late in stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 40.0;
        // Fewer open bins => cheaper to open new
        score -= (open_bins_count as f64).ln().max(0.0) * -5.0;
    }

    // Mean residual coupling: avoid bins far below mean residual (fragmented outliers)
    score += (mean_residual - pr as f64).abs() * 0.1;

    // Progress-scaled tightness pressure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are worthless.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space: heavy penalty, worse the smaller it is.
            score += 60.0 * (10.0 - pr) / 10.0;
        } else {
            // Usable gap: mild reward proportional to how much fits.
            let usable = (pr / 10.0).floor() * 10.0;
            score -= 0.5 * (usable / 10.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: more open bins -> prefer filling existing ones,
    // and make opening a new bin less attractive.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits in the resulting gap, reward it;
    // if it would not fit, penalize creating a gap it can't use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is already below mean (consolidating waste).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Early stream: slightly favor tight packing; late stream: favor closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: small post_residual is great.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: if the next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits: bonus proportional to how well it fills the remainder.
            let fill_frac = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill_frac;
        } else {
            // Next item won't fit in the leftover: penalize large leftovers slightly more.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: keeping residuals uniform is good.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins fit poorly.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 70.0; // baseline cost of a fresh bin
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Next item could pair in a fresh bin: make new bin more attractive
            // when existing residuals are large (poor packing potential).
            new_bin_score -= 30.0 * (mean_residual / bin_capacity as f64);
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // no alternative: must open new bin
        }
        score = new_bin_score + (post_residual as f64);
    }

    // Stream progression: early on, be slightly more willing to open bins (spread risk).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically (unusable leftovers).
    if post_residual < item_size.min(next_item_size.max(1)) {
