    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins more when many open bins have room (consolidate).
        score += 12.0 + pressure * 10.0 - progress * 5.0 + (open_bins_count as f64) * 0.5;
        // But if the item is huge and mean residual is low, new bin is fine.
        if item_size as f64 > bin_capacity as f64 * 0.7 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
