}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with polynomial shaping of residual
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (encourage spreading); late, demand tight fits.
    let tightness = norm_pr * norm_pr * (0.5 + 2.0 * progress);
    score += 40.0 * tightness;

    // Dead-space penalty: residuals too small for any plausible item are wasted,
    // penalize superlinearly, stronger as the stream progresses.
    let dead = (1.0 - norm_pr).powi(3);
    score -= 25.0 * dead * (0.3 + 0.7 * progress);

    // Lookahead: reward bins whose post-residual accommodates the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // but allow it when mean residual across open bins is small.
    if bin_residual == bin_capacity {
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 * (1.0 - openness) * (1.0 - 0.5 * progress);
        score -= 5.0 * progress;
    }

    // Slight preference for bins tighter than the mean residual (balance)
    score += 3.0 * (pr - mean_residual).tanh();

    // Mild pressure against bin sprawl
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
