        }
        // Perfect closure: bin filled exactly is ideal.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Integer-division thresholds on next_item_size: if the next item fits
    // into the post residual (possibly via a half/third class), reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size / 2 <= post_residual && next_item_size % 2 == 0 {
            score -= 3.0;
        }
        // If next item cannot fit in ANY residual class here, slight penalty
        // for consuming a bin the next item could have used.
        if next_item_size > post_residual && post_residual >= next_item_size / 2 {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using
    // it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits: subtract relative fit quality.
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when the current fit is poor or few bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin; reduced late in the stream or when
        // alternatives are scarce.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 55.0 - 15.0 * progress - 4.0 * (fitting_bins_count as f64);
        // If next item is large, a fresh bin preserves flexibility.
        let flex = if next_item_size >= 50 { 8.0 } else { 0.0 };
        score = dead + open_cost - flex;
        // Empty-bin post residual is a multiple of 100; no dead-space bonus applies.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild tie-break: prefer bins below mean residual (consolidating slack).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the less wasted space, the better.
    score -= 0.6 * (item_size as f64);

    // Penalize unusable dead space: residuals too small for typical items.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty for small-but-nonzero post_residual (awkward gaps).
    if post_residual > 0 {
        score += 40.0 / (post_residual as f64 + 1.0);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit in post_residual, penalize slightly (dead space for next step).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64);
        // But if open bins are crowded (low mean residual), a new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Slight phase pressure: later in the stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fit_ratio * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize small dead space that nothing (min size 1) can use well later;
    // dead space near 0 is fine, mid-range residuals are wasteful.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item cannot fit, penalize slightly (dead end for lookahead chain).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin early in the stream or when mean residual
        // across open bins is low (fragmented state); penalize when open bins
        // have plenty of room and we're deep in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
        score += 0.5 * mean_residual;
        score += 2.0 * open_bins_count as f64;
        // If no open bin fits well (this call would be a fallback), allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Favor bins whose residual is close to item size (best-fit flavor),
        // scaled by how many alternatives exist.
        let snugness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * snugness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = progress.clamp(0.0, 1.0);

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early stream: favor tight fills (low post_residual). Late stream: dead space matters less,
    // so post_residual penalty is discounted by a smooth saturating ramp.
    let discount = 1.0 - 0.45 * (p * p * (3.0 - 2.0 * p)); // smoothstep-based discount
    let mut score = post * discount;

    // Non-linear waste curvature: penalize mid-range residuals superlinearly
    // (residuals around 30-60 are least reusable), smooth via normalized sine-free polynomial.
    let x = post / cap; // in [0,1]
    let curvature = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += 14.0 * curvature * (1.0 - p);

    // Reward bins that can also fit the lookahead item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let tightness = 1.0 - (post - nx) / cap;
            score -= 6.0 * tightness * tightness;
        } else {
            // Smoothly penalize when next item cannot fit here.
            score += 3.0 * ((nx - post) / cap).min(1.0);
        }
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - p * 0.5);
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * p;

    // Alignment with mean residual state: prefer bins near the mean (smooth term).
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Slight bias toward opening a new bin for very large items early on,
    // implemented smoothly via post-residual relative to item size.
    let fill_ratio = item_size as f64 / cap;
    score -= 5.0 * fill_ratio * fill_ratio * (1.0 - p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residues are "dead space".
    let residue_class = post_residual % 10;
    if residue_class != 0 {
        score += (10 - residue_class) as f64 * 0.8;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit tiers via integer division thresholds.
    let tier = post_residual / 10;
    score -= match tier {
        0 => 40.0,
        1 => 22.0,
        2 => 8.0,
        _ => 0.0,
    };

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: reward if next item divides the post residual exactly.
            if post_residual % next_item_size == 0 {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit: penalize leaving medium dead space.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive late or when mean residual is high (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 55.0 - progress * 15.0 + fragmentation * 20.0 - (open_bins_count as f64) * 0.5;
        // Large items prefer a fresh bin.
        if item_size >= 60 {
            score -= 12.0;
        }
        // But if a perfect fit exists, never open a new bin.
        if post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual) {
            score += 100.0;
        }
    }

    // Mild preference for filling already-open bins as stream progresses.
    score += mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Favor bins whose residual was already small (tight packing).
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Open-bin pressure: discourage spreading across many bins late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Mean-residual coupling: if this bin is far below mean residual, it's a good filler.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }
    // If next item would leave a dead gap, penalize slightly.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 8.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        score = 60.0 + open_bins_count as f64 * (2.0 - 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 60.0;

    // 2-step lookahead: if the next item exactly fills the post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills again
            score -= 20.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot fit here: penalize wasted space slightly
            score += 10.0;
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin before opening a new bin: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could reasonably fit,
    // unless the fit would be very loose (dead space).
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when the fit is poor in existing bins.
        // Make it moderately costly so it's chosen only for loose fits.
        score += 30.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Small penalty for creating tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with less residual overall (best-fit bias).
    score += bin_residual as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual super-linearly once it becomes "dead space".
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score -= 40.0 * (dead_threshold - post_residual as f64);
    } else {
        score += 0.15 * post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild reward if next item can still chain into this bin
        score -= 5.0 * (post_residual as f64 / next_item_size as f64).ln().max(0.0);
    } else if next_item_size > post_residual {
        // next item can't follow here; penalize proportionally to wasted potential
        score += 3.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * (post_residual as f64);
    }

    // New-bin candidate handling: make fresh bins attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by how tight the best existing fit would be.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score = bin_capacity as f64 - 20.0 * tightness;
        // Open new bins more readily early in the stream and when many bins are already open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if open_bins_count > 3 {
            score += 2.0 * open_bins_count as f64;
        }
        // If the next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    // Global residual pressure: when mean residual is high, prefer consolidating into low-residual bins.
    score += 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0);

    // Slight preference to fill bins with larger residual earlier in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic dead-space penalty: small post-residuals are valuable.
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * cap * 0.01;

    // Late-stream coupling: prefer tight fits as stream progresses.
    score -= 6.0 * (1.0 - norm_pr) * (progress * (1.0 + progress));

    // Reward bins that can also fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr + 0.5);
    }

    // Mild penalty when bin residual is far from mean residual (avoid fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction of residual consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_frac * fill_frac;

    // Harmonic class of post_residual: residues near multiples of small
    // divisors (10, 20, 25) are more "reusable" for future items.
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r20 = (pr % 20) as f64;
    let r25 = (pr % 25) as f64;
    let d10 = r10.min(10.0 - r10);
    let d20 = r20.min(20.0 - r20);
    let d25 = r25.min(25.0 - r25);
    score += 0.8 * d10 + 0.5 * d20 + 0.4 * d25;

    // Integer division thresholds: post_residual buckets
    let bucket = pr / 10; // 0..=10
    let bucket_f = bucket as f64;
    // Dead-space penalty for tiny unusable leftovers
    if pr > 0 && pr < 10 {
        score += 35.0;
    } else if pr == 0 {
        score -= 25.0; // perfect closure
    } else {
        // mid buckets slightly favored
        score -= 2.0 * (1.0 - (bucket_f - 5.0).abs() / 5.0).max(0.0);
    }

    // Lookahead coupling: can next item land exactly in the leftover?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score += 0.3 * slack;
            // exact harmonic match on 10-grid
            if pr % 10 == 0 && next_item_size % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 8.0; // next item cannot use this bin anyway
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize so we prefer good fits,
    // but allow opening when mean residual is fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        score += 12.0 - 10.0 * frag;
        if post_residual == bin_capacity {
            score += 5.0; // opening a bin for nothing extra
        }
    }

    // Stream progression: tighten packing late in the stream
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * t * (mean_residual - pr as f64).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (1) are pure waste,
    // but residuals just below next_item_size are especially unusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly favored
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable gap -> dead space
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // gap can't hold the lookahead item
    } else {
        score -= 8.0; // gap still usable
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // A fresh bin has huge residual; make it unattractive unless item is large
        // relative to typical residuals and mean residual is small.
        let mean_r = mean_residual.max(0.0);
        let scarcity = (item_size as f64 / bin_capacity as f64).max(0.0);
        score += 35.0 - 30.0 * scarcity - 0.05 * mean_r;
    }

    // Slight late-stream bias: consolidate more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // next item fits: residual after two placements
            let post2 = post_residual - next_item_size;
            score -= 120.0 - (post2 as f64) * 0.8;
        } else {
            // next item does not fit here: penalize leaving awkward residual
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += waste * 60.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer filling bins with small residuals; penalize opening new bins early in stream
    if bin_residual == bin_capacity {
        score += 50.0 + 30.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Dead-space penalty: residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (item_size as f64) * 0.8;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.3 * (next_item_size as f64);
        // Extra reward if next item exactly fills the bin afterwards.
        if post_residual - next_item_size < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty for leaving awkward gap.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: only attractive when item is large or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let large_item_bonus = if item_size >= 50 { 20.0 } else { 0.0 };
        let next_needs_space = if next_item_size >= 40 { 10.0 } else { 0.0 };
        score += 30.0 - large_item_bonus - next_needs_space
            - crowded * 22.0 - progress * 10.0;
    }

    // Prefer bins below mean residual (filling emptier bins keeps balance).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Mild exploration pressure over time: encourage consolidation late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;                       // normalized post residual in [0,1]
    let fit_frac = item_size as f64 / cap;            // fraction of bin consumed

    // Core: reward tight fits via smooth non-linear decay of post residual
    let mut score = 40.0 * norm_post.powf(1.7);

    // Non-linear coupling: tight fits matter more as the stream progresses
    score -= 25.0 * (1.0 - norm_post).powf(2.0) * (0.5 + progress);

    // Penalize large dead space quadratically, amplified late in the stream
    score += 30.0 * norm_post * norm_post * (0.4 + 1.2 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - norm_post);
    }

    // Lookahead coupling: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let gap = (post - nxt).abs() / cap;
        score += 12.0 * (1.0 - fits_next) * norm_post;      // penalize blocking next item
        score -= 15.0 * fits_next * (1.0 - gap).powf(2.0);  // reward perfect chain fit
    }

    // Mild dispersion penalty: prefer bins near the mean residual (smooth coupling)
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: penalize opening a bin unless it is genuinely needed
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count > 0 { 1.0 / (fitting_bins_count as f64) } else { 1.0 };
        score += 20.0 + 25.0 * (1.0 - progress) * scarcity;
        // allow new bin late when open bins are all poorly utilized
        score -= 10.0 * progress * (1.0 - (mean_residual / cap).powf(2.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold the
    // smallest plausible item are pure waste — penalize them hard.
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Perfect fit: full closure is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (best-fit flavor with
    // a non-linear squeeze so near-exact fits are strongly preferred).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmenting
    // space further; prefer consolidating into existing capacity.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits the post-residual, reward this
    // placement (chain compatibility); otherwise penalize mildly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the
    // mean, it is already fragmented — penalize adding more dead space.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    // New-bin candidate: only attractive when no open bin offers a
    // decent fit, or the stream is early and consolidation is unlikely.
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score = 55.0 + desperation - 25.0 * (1.0 - early);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (perfect chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        // Exact match: nearly free placement next step.
        if gap == 0.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; the leftover is dead space unless tiny.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize post_residual relative to mean residual (wasting space vs average).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            // How poorly do existing bins fit? Compare best post residual proxy via mean.
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        };
        // Keep new bin slightly worse than a decent existing fit.
        score += 20.0 - 30.0 * pressure;
    }

    // Late in the stream, tighten packing: discourage large leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: the smaller the leftover, the better the placement.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 0.6 * next_item_size as f64;
        } else {
            // Penalize placements that strand the next item.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.25 * gap.min(30.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding penalty: spreading across many half-full bins is bad.
    score += 0.15 * (open_bins_count as f64).sqrt() * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large (leaving little waste) or when we are late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = (item_size as f64 - 50.0).max(0.0) * 0.4;
        score += 20.0 - large_item_bonus - 10.0 * progress;
    }

    // Global-state coupling: if mean residual is small, conserve space by
    // preferring placements with small post-residual even more.
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Mild time-horizon term: early on, keep bins flexible (larger post-residual
    // slightly penalized less); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: dead space penalized more as stream progresses
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: penalize if next item can't use the leftover space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 8.0 * (1.0 - pr / nxt);
        } else {
            score -= 5.0 * (pr / nxt).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        score += 15.0 * (1.0 - crowded);
        score += 10.0 * progress;
    }

    // Mild penalty for scattering across many open bins
    score += 0.3 * open_bins_count as f64;

    // Pull toward mean residual to balance bin fullness
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that pair well with common
    // small items (10..=30) are "usable"; large prime-ish residues are dead space.
    let post = post_residual;
    let class_bonus: f64 = if post == 0 {
        -60.0 // perfect fit: huge reward
    } else if post <= 10 {
        -25.0
    } else if post % 10 == 0 {
        -18.0 // round residues are reusable
    } else if post % 5 == 0 {
        -10.0
    } else if post % 2 == 0 {
        -4.0
    } else {
        6.0 // odd awkward residue: penalty
    };
    score += class_bonus;

    // Coupling with lookahead: reward when next_item_size divides the post-residual
    // exactly (integer division threshold logic).
    if next_item_size > 0 && next_item_size <= post {
        if post % next_item_size == 0 {
            score -= 22.0;
        } else if next_item_size >= post / 2 {
            score -= 8.0; // next item consumes most of the leftover
        }
    } else if next_item_size > post && next_item_size > 0 {
        score += 5.0; // leftover too small for lookahead anyway
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // and many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if post > 50 { 1.0 } else { 0.0 };
        score += 35.0 - 25.0 * bad_fit - 10.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
    }

    // Tight-fit reward: items filling >= 80% of residual are excellent.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill >= 0.8 {
        score -= 15.0;
    } else if fill < 0.3 {
        score += 8.0; // wasteful small placement into big residual
    }

    // Mild pressure toward consolidating into bins below the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Threshold on absolute post-residual: anything in (40, 60) leaves a
    // half-empty bin that is hard to reuse later.
    if post > 40 && post < 60 {
        score += 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize tiny leftover gaps that are
    // effectively unusable (below the minimum plausible item size band).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space
        } else if post_residual < 25 {
            score += 25.0; // hard-to-fill sliver
        } else if post_residual < 40 {
            score += 8.0; // moderately awkward gap
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward bins whose leftover can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leftovers that can host nothing at all going forward.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well,
    // i.e. keep its default score high but not prohibitive.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Slight nudge toward bins deviating from the mean residual (better fits).
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
