pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let norm = pr / bin_capacity as f64;
    let poly = norm * norm * (1.0 - progress) - norm * progress;
    score += 40.0 * poly;

    // Penalize dead space more as stream progresses
    score += progress * (pr * pr) / (bin_capacity as f64 * bin_capacity as f64) * 60.0;

    // Reward tight fits (small post_residual) with smooth quadratic term
    score -= (1.0 - norm) * (1.0 - norm) * 25.0;

    // Lookahead: penalize leaving residuals that cannot fit next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * progress;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty proportional to open bins to discourage fragmentation
    score += open_bins_count as f64 * 0.5 * progress;

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    score += 0.3 * (pr - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by capacity fractions (dead-space classes)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize residuals that fall into "dead" classes (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Harmonic reward: residuals that are exact capacity fractions are reusable
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % eighth == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // coupling: prefer leaving room class-compatible with next item
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.3;
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use leftover: penalize proportional to excess
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual - pr).abs();
        score += 20.0 + fragmentation * 0.1;
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 15.0; // discourage new bin when open bins can hold item
        }
        if post_residual == 0 { score -= 0.0; }
        // early stream: new bins are cheap-ish; late stream: prefer filling
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Mild tie-breaking by mean residual alignment
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Pressure from number of open bins: prefer filling existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item would be blocked by the resulting gap.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_residual {
        score += 10.0;
    }

    // Slight progression bias: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress;
    }

    // Mean residual coupling: avoid bins far from the mean (keeps balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            // Exact match bonus: next item fills this bin nearly perfectly.
            let gap = pr - nx;
            if gap <= 10.0 {
                score -= 30.0 * (1.0 - gap / 10.0);
            } else {
                score -= 8.0;
            }
        } else if pr > 0.0 {
            // Next item can't fit here; penalize small dead space creation.
            let waste = nx - pr;
            score += 6.0 * (1.0 - (waste / nx).min(1.0));
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 10.0;
    }

    // Reward tight fits relative to mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a poor fit.
    if fitting_bins_count == 1 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.7 {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Penalize leaving large unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }
    if post_residual >= 10 && post_residual < item_size.min(50) {
        score += 3.0;
    }

    // New-bin candidate: prefer using existing bins unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize consuming a bin whose residual would perfectly fit
    // the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score += 25.0; // wasting an exact future fit
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 12.0; // leaving nearly-exact but unusable sliver
        } else if post_residual >= next_item_size {
            score -= 6.0; // leaving room for the next item is good
        }
    }

    // New-bin candidate handling: opening a fresh bin is attractive early
    // (many future items) or when the current fit is loose.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Empty bin: baseline score adjusted by horizon and fragmentation state.
        score = bin_capacity as f64 * 0.6 + 30.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            // Only prefer a new bin if existing fits are poor; add a mild penalty.
            score += 8.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin suits a large upcoming item
        }
    }

    // Global state coupling: when mean residual is high (bins are loose),
    // tighten preference for good fits; when low, avoid fragmenting scarce space.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.15 * mean_gap;

    // Late in the stream, prefer consolidating into existing bins.
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = 0.5 * norm_pr - 1.2 * norm_pr * progress + 2.0 * norm_pr * norm_pr * progress * progress;
    score += coupling * cap * 0.3;

    // Penalize dead space that is too small to be useful later (smooth quadratic)
    let dead_zone = 30.0;
    let d = (pr - dead_zone) / cap;
    score -= 10.0 * (-d * d * 8.0).exp() * (1.0 - 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual (smooth)
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let margin = (pr - next_item_size as f64).abs() / cap;
        score -= fits_next * 12.0 * (1.0 - margin).max(0.0);
        // Penalize wasting space if next item nearly fits but doesn't
        let near_miss = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += 8.0 * (-near_miss * 40.0).exp() * (1.0 - fits_next);
    }

    // Slight preference to fill already-open bins over opening new ones
    score += 5.0 * (bin_residual as f64 / cap) * (1.0 - 0.3 * progress);

    // Mild penalty relative to mean residual to balance load
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate shaping: neutral baseline with slight late-stream bias
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" sizes
    // (multiples of common small item sizes leave usable space).
    let pr = post_residual as i64;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % (*m as i64) == 0 {
                harmony += 6.0;
            }
        }
        // quarter classes of capacity
        let q = bin_capacity / 4;
        if pr % (q as i64) == 0 { harmony += 4.0; }
        score -= harmony;

        // Penalize tiny dead space (< 10 unusable)
        if pr < 10 {
            score += 40.0;
        } else if pr <= 15 {
            score += 8.0;
        }
    } else {
        // perfect fit is excellent
        score -= 30.0;
    }

    // Integer-division threshold classes on post_residual
    let cls = pr / 20; // 0..5 class
    score -= (cls as f64) * 2.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 15.0;
        }
        // modulo harmony between next item and post residual
        if post_residual % next_item_size.max(1) == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0; // dead space blocks next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let tight = post_residual <= 5;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if tight { score -= 20.0; } else { score += 15.0 + 10.0 * (1.0 - progress); }
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fullness * 10.0;
    if open_bins_count > 4 && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Stream progression: later in stream, be more conservative (prefer tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - pr / 10.0); // tiny gap = heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward residual that still fits the lookahead item (usable gap).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // gap too small for next item
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has residual == capacity, so add a fixed handicap there.
    if bin_residual == bin_capacity {
        score += 12.0 + 1.5 * open_bins_count as f64;
    }

    // Mild tie-break toward bins already below mean residual (consolidate slack).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Exact match for next item is highly desirable.
        if diff < 0.5 {
            score -= 30.0;
        } else {
            // Penalize proportionally to mismatch, capped.
            score += (diff / 10.0).min(8.0);
        }
        // If next item cannot fit in this bin after placement, mild penalty
        // unless the leftover is very small (dead space).
        if pr < nxt {
            // dead space: unusable leftover before next item arrives
            score += (pr / 20.0).min(6.0);
            // tiny dead space is worse (wasted capacity)
            if pr < 10.0 {
                score += 4.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += post_residual as f64 * 0.5;
    }

    // Compare against mean residual across open bins.
    // Bins with residual far above mean are "loose" — prefer filling them
    // when post_residual stays reasonably large.
    if post_residual as f64 > mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item
    // is large and would leave open bins fragmented.
    if bin_residual == bin_capacity {
        // Base cost for a fresh bin.
        score += 12.0;
        // Opening a new bin is attractive when the item is big and would
        // nearly fill it, or when no open bin fits well.
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.8 {
            score -= 10.0;
        }
        // If many bins are open with high mean residual, prefer reusing them.
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 8.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 2.0;

    // Stream progression: early on, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual), with a non-linear squaring
    // that strongly punishes large dead space.
    let pr = post_residual as f64;
    score = 0.6 * pr + 0.004 * pr * pr;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if post residual is too small to ever hold
    // the next item (or typical small items), penalize dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but not perfectly: slight reward proportional to fill
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space the next item cannot use
            score += 0.25 * (next_item_size as f64 - pr).min(40.0);
        }
    } else {
        // last item: any residual is pure waste; prefer exact fill
        score += 0.5 * pr;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * (item_size as f64);
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    // (post residual would be very small unusable slivers) or when many bins
    // are already open with high fragmentation.
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin
        score = 0.55 * bin_capacity as f64;
        // penalize opening new bins when current fit is decent
        if post_residual >= 0 && bin_residual >= item_size {
            let wasted_here = (bin_residual - item_size) as f64;
            // compare against best possible reuse: if some bin gives near-exact fit,
            // opening a new bin is wasteful.
            score += 0.3 * wasted_here;
        }
        // early in the stream, opening bins is cheap; later, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // if many open bins already, discourage more
        score += 2.0 * open_bins_count as f64;
    }

    // Global fragmentation: if mean residual is high, prefer placing into
    // fragmented bins to consolidate them (bins with residual near mean get reward).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins that are already mostly full (small residual)
    score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Slight time-dependent aggressiveness: late in the stream, be greedy about
    // closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, softly damped by progress (late stream -> value tight fits more)
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling of residual with progress
    let t = norm_pr;
    score += 20.0 * (t * t - 2.0 * t * t * t + t * t * t * t) * (0.5 + progress);

    // Penalize large post-residuals relative to mean residual (wasted space)
    score += 0.3 * (pr - mean_residual).max(0.0) * (1.0 + progress);

    // Reward tight fits: small post residual subtracts
    score -= 15.0 * (1.0 - t).powi(3) * (1.0 + progress);

    // Lookahead: if next item fits the post-residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress);
    }
    // Penalize if next item won't fit but is close (dead space risk)
    if next_item_size > 0 && (next_item_size as f64) > pr && (next_item_size as f64) - pr < 20.0 {
        score += 6.0;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mild penalty for proliferating open bins early
    score += 0.5 * (open_bins_count as f64).powf(0.5) * (1.0 - progress);

    // New-bin candidate: neutral-ish, slightly penalized unless residual would be very tight
    if bin_residual == bin_capacity {
        score = pr + 30.0 * (1.0 - progress) - 20.0 * progress * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Penalize dead space in harmonic bands: small leftovers (<20) are rarely reusable.
    if post_residual < 20 {
        score += 60.0 * (20.0 - pr);
    } else if post_residual <= 50 {
        // Sweet spot: leftovers in [20,50] pair well with typical item sizes.
        score -= 25.0;
    } else {
        // Large leftovers are fine but slightly less attractive than the sweet spot.
        score -= 10.0 * frac;
    }

    // Modulo classes: post_residual divisible by small integers aligns with common item sizes.
    let pr_i = post_residual;
    if pr_i % 10 == 0 && pr_i > 0 {
        score -= 8.0; // round residuals pair nicely with decade item sizes
    }
    if pr_i % 5 == 0 && pr_i % 10 != 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: can next item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills this bin.
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional to waste.
            score += 0.5 * (next_item_size as f64 - pr).min(60.0);
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current placement
    // would create severe dead space and mean residual is already fragmented.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < 15 && next_item_size > post_residual;
        if bad_fit && mean_residual > 30.0 {
            score -= 55.0; // open new bin instead of fragmenting
        } else {
            score += 35.0; // default: prefer reusing open bins
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.85 {
        score -= 20.0 * fill;
    }

    // Stream progression: early on, be picky about tight fits; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill);

    // Slight nudge toward bins below mean residual (balancing fragmentation).
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
