    // If next item leaves a near-exact combined fit, extra reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if next item cannot use the dead space created.
    if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins tighter than the mean residual (better fits).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: neutral baseline, slightly discouraged unless existing bins are bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.3 - (fitting_bins_count.max(1) as f64).recip() * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin accommodates lookahead well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect two-item fill (post_residual == next_item_size) is highly desirable.
        score -= 8.0 * (1.0 - lookahead_gap / (bin_capacity as f64 * 0.5)).max(0.0);
        // Exact two-item completion bonus.
        if post_residual == next_item_size {
            score -= 6.0;
        }
        // Penalize leaving residual that neither fits the next item nor is useful.
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 4.0 * (1.0 - post_residual as f64 / (next_item_size as f64 + 1.0));
        }
    } else {
        // Last item: prefer tightest fill.
        score += 2.0 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than average.
    score += 1.5 * ((post_residual as f64) - mean_residual) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Penalize new-bin candidate unless the fit into open bins is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Opening a new bin is more attractive early in the stream.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Mild penalty for large post-residual dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 2.0; // tiny dead space means near-perfect packing
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward bins where the lookahead item also fits (chaining placements)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * next_item_size as f64;
    }

    // Penalize leaving awkward dead space: residual too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, unless item is large
    // relative to residual and current bins are crowded / fragmented.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(1.0);
        let fill_ratio = item_size as f64 / cap;
        let mut penalty = 200.0 * crowding;
        // large items deserve fresh bins
        penalty -= 180.0 * fill_ratio;
        // late in stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += 100.0 * progress;
        // if open bins are fragmented (low mean residual), fresh bin is more attractive
        penalty -= (cap - mean_residual).max(0.0) * 0.3;
        score += penalty.max(-50.0);
    }

    // Prefer tighter absolute fit among open bins
    score += 0.3 * (bin_residual - item_size) as f64;

    // Mild preference for bins with below-average residual (keep big holes for big items)
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: quadratic penalty on post_residual scaled by progress
    score += 0.35 * (pr / cap) * (pr / cap) * (1.0 - progress) * cap;

    // Reward tight fits (small post_residual) with cubic term
    score -= 0.25 * (1.0 - pr / cap).powi(3) * item_size as f64;

    // Interaction: post_residual vs mean residual divergence, modulated by progress
    let div = (mean_residual - pr) / cap;
    score += 0.6 * div * div * (0.5 + progress) * cap;

    // Last-chance bin bonus, smoothed by progress
    if fitting_bins_count == 1 {
        score -= 3.0 + 4.0 * progress;
    }

    // Lookahead: penalize if post_residual can't fit next item but bin_residual could
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr < nx) && (bin_residual as f64 >= nx) {
            score += 1.5 * (nx / cap) * (1.0 + progress);
        } else if pr >= nx {
            score -= 1.0 * (nx / cap);
        }
    }

    // Mild penalty for spreading across many bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer opening a fresh bin only when it will be well used
    if bin_residual == bin_capacity {
        score = item_size as f64 * (1.0 + 0.5 * (1.0 - progress)) + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "dead zones" (too small for typical items) are heavily penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional class of post_residual relative to capacity
    let frac = pr / cap;

    // Dead-space class: post residual below the smallest plausible item
    // (<= 10) is wasted space -> strong penalty via modulo classes.
    let dead_zone = post_residual < 10;
    if dead_zone {
        score += 60.0;
    }

    // Harmonic (modulo) classification of post_residual into 12 classes of cap/12
    let class = (post_residual * 12 / bin_capacity.max(1)) as f64;
    score += class * 2.0;

    // Perfect-ish fits rewarded: post_residual in [0,5]
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (exact coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // post residual can host next item: reward proportionally to closeness
            let slack = pr - nxt;
            score -= 10.0 - 0.15 * slack;
            // harmonic bonus if post_residual is an integer multiple class of next item
            if (post_residual as u64) % (next_item_size.max(1) as u64) == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize mildly unless dead zone anyway
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer existing bins with good fits; open new bin only when the
        // item is large relative to capacity or existing bins are fragmented.
        let large_item = (item_size as f64) > 0.6 * cap;
        let fragmented = mean_residual < (item_size as f64) * 0.9;
        if large_item || fragmented {
            score -= 30.0; // make new bin attractive
        } else {
            score += 35.0; // discourage opening new bins unnecessarily
        }
    }

    // Tight-fill reward: how much of the bin's residual the item consumes
    let fill_ratio = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * fill_ratio;

    // Stream progression: late in the stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fill_ratio;

    // Mean residual coupling: if average residual is high, tolerate looser fits
    score += 0.05 * (mean_residual - pr).abs();

    // Small noise-free tie-breaker on residual class parity
    if class as u64 % 2 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worst.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0; // tiny gap = pure dead space
        } else if pr < 25.0 {
            score += 25.0 * (25.0 - pr) / 15.0;
        }
    } else {
        score -= 80.0; // perfect fit reward
    }

    // Reward tight fills (high utilization of this placement).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    let open_pressure = (open_bins_count as f64 / 20.0).min(3.0);
    score -= 12.0 * open_pressure * (bin_residual as f64 / cap);

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // leftover too small for next item => dead space risk
    }

    // New-bin candidate: only attractive when current residuals are poor.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        let new_bin_base = cap - item_size as f64;
        score = new_bin_base + 40.0 - 25.0 * (mean_gap / cap).min(1.0) * (open_bins_count.min(10) as f64 / 10.0);
        if fitting_bins_count <= 2 {
            score -= 30.0; // few alternatives: new bin is reasonable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or nearly: strong reward
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 200.0; // exact 2-step chain
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let resid_f = post_residual as f64;
    let dev = resid_f - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strong incentive to use it before opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize leaving very small unusable slivers (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 60.0 + 200.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0; // hard to fill
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / 100.0);
        } else {
            // penalize leaving residual that blocks the known next item
            let wasted = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += wasted * 0.3;
        }
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // More competing bins -> prefer the best fit only mildly.
        score += fitting_bins_count as f64 * 1.5;
    }

    // Global state: many open bins -> discourage spreading, prefer filling.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += open_pressure * 2.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Time horizon: early on, be conservative about new bins; late, prefer tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, reduced if the item is large (needs its own bin anyway)
        // and if there are few open bins.
        let mut new_bin_score = 55.0;
        new_bin_score -= (item_size as f64 / 100.0) * 20.0;
        new_bin_score -= (fitting_bins_count == 0) as i32 as f64 * 60.0;
        new_bin_score += progress * 15.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * progress * progress);

    // Reward tight fits: post_residual near zero gets strong discount
    let tight_bonus = -3.0 * (1.0 - norm_pr).powi(3) * (1.0 + fit_ratio);

    // Penalize dead space that next item cannot use (smooth interaction)
    let next_fit_pen = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        0.6 * (gap / cap) * (0.5 + progress)
    } else {
        0.0
    };

    // Last-chance bin bonus: smooth in fitting_bins_count
    let last_chance = -1.5 / (fitting_bins_count as f64 + 1.0);

    // Mild preference for bins below mean residual (balance residuals smoothly)
    let balance = 0.3 * (mean_residual - pr) / cap;

    // Late-stream consolidation: favor filling existing bins more as stream ends
    let endgame = -1.2 * progress * (1.0 - norm_pr);

    let mut score = poly + tight_bonus + next_fit_pen + last_chance + balance + endgame;

    // New-bin candidate: penalize opening fresh bins unless residuals are all large
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score += 4.0 * (1.0 - avg_fill) + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize post_residuals that fall in "dead zone" classes (too small to fit typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Harmonic class logic: post_residual modulo 10 classes
    let class = post_residual % 10;
    match class {
        0 => score -= 8.0,   // perfectly aligned residual, very reusable
        5 => score -= 4.0,   // half-class, decent
        2 | 8 => score -= 2.0,
        _ => {}
    }

    // Reward tight fits (small post_residual but usable)
    if post_residual > 0 && post_residual <= 15 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize leaving large residual
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.5 + post_residual as f64;
        if fitting_bins_count >= 1 {
            score += 20.0; // discourage opening new bin when alternatives exist
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item coming, fresh bin useful
        }
    }

    // Progress-aware: later in stream, prefer filling bins tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.1 + 0.15 * progress);

    // Prefer bins with residuals below mean (consolidate space)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Fraction-of-capacity coupling on post_residual
    let frac = pr / cap;
    if frac < 0.1 && frac > 0.0 {
        score += 12.0; // near-dead residual
    } else if frac >= 0.3 && frac <= 0.5 {
        score -= 6.0; // sweet-spot residual for medium items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements leaving a gap large enough to be reusable.
    if post_residual >= 10 {
        score -= 15.0;
    }

    // Penalize bins whose residual is much larger than needed (wasteful fit).
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += slack * 0.15;

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Late in the stream, tighten packing to avoid leftover sprawl.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Slight preference for bins tighter than the average residual.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / 100.0).max(0.0);

        // Perfect two-item fill is excellent
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Leaving space too small for next item = dead space
        if post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
    }

    // Penalize tiny unusable residuals (waste)
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Favor bins tighter than average (good fit), penalize loose bins
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host a clean pair
        }
    }

    // Late in stream: prefer filling existing bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate slack; late, penalize it strongly.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * 20.0 * norm_pr * norm_pr * norm_pr;

    // Reward using bins that are already slack-heavy relative to the mean.
    let slack_vs_mean = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * slack_vs_mean * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item; penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - gap * gap);
        } else {
            score += 5.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 10.0 + 12.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in [1..10] is nearly unusable
    let dead = post_residual < 10;
    if dead { score += 25.0; }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well with
    // typical item granularities; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else {
        score += (post_residual % 10) as f64 * 0.6;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: does the next item fit the post residual? Reward that.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 6.0 + 0.25 * next_fit_quality;
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty proportional to wasted potential
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Tightness reward: filling a bin more completely relative to capacity
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // Penalize creating residuals in awkward mid-range (11..=30) which rarely combine
    if post_residual >= 11 && post_residual <= 30 {
        score += 0.15 * (post_residual as f64 - 10.0);
    }

    // New-bin candidate: only attractive when open bins are all tight or residual
    // mismatch is severe. Base cost of opening a bin.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If current bin would leave a bad residual and next item is large, opening
        // a fresh bin may be better.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 18.0;
        }
        if open_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure against accumulating many loose open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let before = bin_residual as f64;
    let after = post_residual as f64;
    let next = next_item_size as f64;
    let item_ratio = (item_size as f64 / cap).clamp(0.0, 1.0);

    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 6.0)).clamp(0.0, 1.0);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    let is_new_candidate = bin_residual == bin_capacity;

    let mut score = after / cap;

    if post_residual == 0 {
        score -= 1.0 + 0.45 * item_ratio + 0.65 * open_norm;
    } else if next > 0.0 && after < next {
        let unusable = (next - after) / next;
        let future_weight = 0.75 + 0.25 * (1.0 - progress);
        score += (0.55 + 1.35 * unusable + 0.45 * open_norm) * future_weight;
    } else if next > 0.0 {
        score -= 0.08 + 0.12 * open_norm;
        if after == next {
            score -= 0.18;
        }
    }

    if !is_new_candidate {
        let tightness = ((before - mean_residual) / cap).clamp(-0.25, 0.25);
        score += (0.04 + 0.10 * open_norm) * tightness;

        if fitting_bins_count == 1 {
            let usable_for_next = post_residual == 0 || (next > 0.0 && after >= next);
            let strength = if usable_for_next {
                1.35 + 0.75 * open_norm
            } else {
                0.45 + 0.35 * open_norm
            };

            score -= strength + 0.20 * item_ratio + 0.20 * (1.0 - after / cap);
        }
    } else if fitting_bins_count == 0 {
        score += 0.03 + 0.07 * progress;
    } else {
        let mut new_penalty = 1.45
            + 1.20 * open_norm
            + 0.30 * progress
            + 0.50 * mean_norm * open_norm
            + 0.10 * item_ratio;

        if next > 0.0 && after >= next {
            new_penalty -= 0.20;
        }

        if next > 0.0 && post_residual > 0 && after < next {
            new_penalty += 0.35 + 0.45 * ((next - after) / next);
        }

        score += new_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tight fit reward: penalize large leftover space quadratically
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = post_residual - next_item_size;
        // Exact two-item fill is excellent
        if match_gap == 0 {
            score -= 500.0;
        } else {
            score -= 200.0 - (match_gap as f64 / bin_capacity as f64).powi(2) * 200.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to how "wasted" the residual is
        let waste = post_residual as f64 / (next_item_size as f64);
        score += 30.0 * waste.min(3.0);
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins)
    let dev = mean_residual - post_residual as f64;
    score += dev * 2.0;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when open bins exist; relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        score += 120.0 + open_pressure * 5.0 * (1.0 - progress * 0.5);
        // If no open bin fits well and item is large, opening may be fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for keeping larger residuals available in other bins
    score += (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer small post-residual (tight fit).
    let mut score = post;

    // Reward tightness non-linearly: near-perfect fits get a big bonus.
    if post <= 2.0 {
        score -= 30.0;
    } else {
        score -= 12.0 * (1.0 - post / cap).powi(6);
    }

    // Penalize dead space that can't fit typical small items (dead zone < 20).
    if post > 0.0 && post < 20.0 {
        score += 18.0 * (1.0 - post / 20.0);
    }

    // Lookahead: if next item fits exactly into post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            score -= 20.0 * (1.0 - slack_after_next / cap);
            if slack_after_next == 0.0 { score -= 25.0; }
        } else {
            // Next item won't fit here: mild penalty, scaled by how badly.
            score += 6.0 * ((nxt - post) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about residual quality.
        score += 4.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: prefer filling bins when mean residual is low
    // (bins are already fragmented; don't spread waste).
    score -= 5.0 * (mean_residual / cap) * (1.0 - post / cap);

    // Time horizon: early in stream, opening new bins is cheap (many items left
    // to fill them); late in stream, consolidate aggressively.
    let late_bonus = 15.0 * t;
    score -= late_bonus * (1.0 - post / cap);

    // New-bin candidate handling: make it moderately attractive early, unattractive
    // when an existing bin gives a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Fresh bin has perfect flexibility; cost is a whole new bin.
        score = cap * 0.9 - late_bonus - 10.0 * (1.0 - t);
        if fitting_bins_count <= 1 {
            // No real alternative exists anyway; new bin is fine.
            score -= 25.0;
        }
    }

    // Slight preference for larger items placed in fuller bins (balance).
    score -= 3.0 * (fit / cap) * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = post;

    // Smooth polynomial coupling of post residual with stream progress:
    // late in the stream, waste is penalized more strongly (quadratic/cubic growth)
    let waste_penalty = (x * x) * (1.0 + 2.0 * progress) + (x * x * x) * (3.0 * progress);
    score += waste_penalty * cap;

    // Reward near-perfect fits smoothly (bell-shaped around x ~ 0)
    let perfect_bonus = (-x * x * 12.0).exp() * (10.0 + 20.0 * progress);
    score -= perfect_bonus;

    // Last-chance bin: smooth reward decaying as other options appear
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress) + 5.0;
    }

    // Dead-space avoidance: post residual too small for typical future items
    // smooth trough: penalize residuals that are "awkward" (small but nonzero)
    let awkward = (-(x - 0.35) * (x - 0.35) * 8.0).exp();
    score += awkward * 8.0 * progress;

    // Lookahead: if next item fits exactly in post residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_gap = (post - next_item_size as f64) / cap;
        score -= (1.0 - fit_gap) * (6.0 + 10.0 * progress);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by how much it misses
        let miss = (next_item_size as f64 - post) / cap;
        score += miss * 10.0;
    }

    // Mild preference for fuller bins as open bins multiply
    score += (open_bins_count as f64).ln().max(0.0) * x * 4.0;

    // Slight nudge toward bins above mean residual (consolidate space)
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with quadratic penalty for dead space
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10
    let class = (post_residual % 10) as f64;
    // Residues near 0 (very tight fit) are excellent; residues that combine
    // badly with typical small items (e.g. 1..3) are dead space.
    score += match (post_residual % 10) {
        0 => -6.0,
        1 | 2 => 5.0,
        3 | 4 => 2.0,
        _ => 0.0,
    } + 0.15 * class;

    // Integer-division thresholds on post_residual: leftover smaller than the
    // minimum item size (10) is unusable — reward fullness via division buckets
    let bucket = post_residual / 10;
    score -= bucket as f64 * 0.8;
    if post_residual < 10 {
        score -= 8.0; // perfectly packed bin
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 0.05 * next_item_size as f64;
        // Harmonic match: next item fills leftover to a multiple of 10
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize more if this bin had lots of room
        score += 0.03 * pr;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when current bins are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin, reduced when many open bins exist
        // with poor aggregate fit quality
        let fragmentation = (mean_residual / cap).abs() - 0.5;
        score += 25.0 - 20.0 * fragmentation.max(0.0);
        if open_bins_count == 0 {
            score -= 30.0; // must open
        }
    }

    // Stream progression: later in stream, be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 6.0 * progress;
    }

    // Mild preference to spread load when mean residual is high (balance classes)
    score += 0.02 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable gap => heavy penalty
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit: fully consumed bin
    }

    // Penalize post_residual that cannot host the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward bins whose post_residual exactly matches the next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tight = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tight;

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * (open_bins_count as f64).sqrt() * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits badly
    // everywhere else (large item, tight overall residuals).
    if bin_residual == bin_capacity {
        let spread = (mean_residual - item_size as f64).abs();
        if item_size >= 70 || (mean_residual < item_size as f64 + 5.0) {
            score -= 5.0; // opening a new bin is reasonable
        } else if spread > 20.0 {
            score += 30.0; // plenty of room elsewhere: discourage new bin
        } else {
            score += 8.0;
        }
    }

    // Mild preference for bins below mean residual (fill the emptier side).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that cannot fit any plausible future item (min size 1,
    // but small dead space below typical item sizes is often wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would exactly fill post residual, extra reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item is large and would not fit anywhere after this placement,
    // slightly penalize consuming a bin that could hold the next big item.
    if next_item_size > 0 && next_item_size > post_residual && item_size > bin_capacity / 2 {
        score += 8.0;
    }

    // Prefer bins whose residual is already far from the mean (consolidate small residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Early in the stream: be picky, prefer tight fits and allow new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // Late in the stream: consolidate into open bins rather than opening new ones.
    score -= progress * 10.0;

    // Many open bins: discourage opening yet another bin.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it attractive only when current open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 60.0 - progress * 20.0 - open_bins_count as f64 * 2.0;
        // If the item is large and few bins fit it, a fresh bin is reasonable.
        if fitting_bins_count <= 1 {
            new_bin_score -= 30.0;
        }
        // If the next item is large, keep a fresh bin available.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            new_bin_score -= 15.0;
        }
        score = score.min(new_bin_score.max(score - 0.0));
        // Combine: choose new bin if its adjusted score beats usage score.
        let use_score = score + 70.0; // placeholder offset to allow comparison below
        score = if new_bin_score < use_score - 70.0 { new_bin_score } else { score };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post-residual with non-linear shrink of large residuals
    let mut score = r - 40.0 * (1.0 - (1.0 - rn) * (1.0 - rn)) * rn;

    // Smooth coupling of residual with stream progress: later in stream, tighter packing favored
    score += 25.0 * rn * rn * t;

    // Penalize residuals that cannot fit the lookahead item smoothly
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (r - nxt).max(0.0) / cap;
        let wasted = 1.0 - (gap / (1.0 + gap));
        score += 18.0 * wasted * (1.0 - t);
        // Reward if lookahead fits exactly-ish
        let fit_gap = (r - nxt).abs() as f64;
        score -= 12.0 * (1.0 - fit_gap / cap) * (r >= nxt) as i32 as f64;
    }

    // Last-chance bonus: few fitting bins encourages using this one
    if fitting_bins_count <= 2 {
        score -= 15.0 / (fitting_bins_count as f64 + 1.0);
    }

    // Mild pressure relative to mean residual across open bins
    score += 0.05 * (r - mean_residual);

    // Slight penalty for many open bins (consolidation incentive)
    score += 0.5 * open_bins_count as f64 * rn;

    // New-bin candidate: make empty bins moderately attractive only early or when nothing fits well
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 30.0 * (1.0 - t) - 20.0 * t * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity/16 buckets. Buckets that are "dead" (too small for typical
    // items, i.e. < 10) are heavily penalized; buckets that could host
    // common small items get a mild bonus.
    let class = post_residual / 6; // buckets of width 6 over capacity 100
    if post_residual < 10 {
        // Unusable dead space: strong penalty scaled by how dead it is.
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // Sweet spot: leftover that small items can still fill.
        score -= 25.0;
    } else if post_residual <= 40 {
        score -= 10.0;
    } else {
        score -= 4.0;
    }

    // Modulo-based harmonic coupling: post_residual congruence classes
    // that align with common item sizes (10..=80) leave reusable gaps.
    let harmonics = [10u32, 12, 15, 16, 20, 25, 30, 40];
    let mut harmonic_bonus = 0.0;
    for &h in harmonics.iter() {
        if post_residual >= h {
            harmonic_bonus += (post_residual % h) as f64;
        }
    }
    score += harmonic_bonus * 0.05;

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly prefer this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here; penalize proportional to waste.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Spread pressure: when many bins are open, prefer bins with below-mean
    // residual (consolidate fuller bins, keep emptier bins flexible).
    score += (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate: neutral-ish score so it's chosen only when all
    // open bins offer poor fits. Slightly discourage early in the stream,
    // slightly encourage reusing bins late (avoid bin proliferation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // gap 1 => +57, gap 9 => +33
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item if it fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // lookahead won't fit in the leftover gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mild penalty per open bin, encouraging consolidation.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is below the mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: prefer fresh bin only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0 + open_bins_count as f64;
        // But if the current item leaves a big usable chunk, a new bin is attractive.
        if post_residual >= 40 {
            score -= 20.0;
        }
        // Late in the stream, opening bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fits (low post_residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: strong reward when next item fits the post_residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            // partial chain reward, scaled by how much slack remains after next item
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - chain_left / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to the overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    } else {
        // last item: strongly prefer minimal residual
        score += 10.0 * fit_ratio;
    }

    // Dead-space penalty: residuals too small for typical items are wasteful.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately unattractive unless item is large
    // (large items benefit from a fresh bin).
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { -15.0 } else { 12.0 };
        score += 25.0 + large_item_bonus;
    }

    // Early in stream: be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization is the core objective).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Penalize dead space proportional to how unusable it is relative to
    // the minimum possible item size (assumed small, scale by 10).
    let dead = post_residual as f64 / 10.0;
    score += dead * dead * 0.5;

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent; if the next item would fit only poorly,
    // penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (25.0 - slack.min(25.0)) * 0.8;
        } else {
            // next item won't fit here; slight penalty for blocking large residuals
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (favor new bins less); late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Global state: many open bins with high mean residual -> encourage
    // filling existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64).abs() * 0.3;
        if open_bins_count > 4 && mean_residual > item_size as f64 {
            score -= 8.0;
        }
    } else {
        // New-bin candidate: only attractive when no tight option exists.
        // Penalize new bins more when many bins are open (fragmentation risk).
        score += 15.0 + (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit core).
    let fit_gap = (bin_residual - item_size) as f64;
    score += fit_gap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 + progress * (1.0 - norm_pr)) * (1.0 - 0.5 * progress);

    let mut score = 3.0 * pr + 8.0 * coupling * cap;

    // Penalize dead space scaled by residual tightness polynomial
    let tight = (norm_pr * (1.0 - norm_pr) * 4.0); // peaks at 0.5 residual
    score += 12.0 * tight * (1.0 + progress);

    // Lookahead: reward residuals that can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (pr - nx).abs();
        score -= 20.0 * fits_next * (1.0 - gap / cap) * (1.0 + 0.5 * progress);
        score += 6.0 * (1.0 - fits_next) * (1.0 + progress);
    }

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 + progress);
    }

    // Prefer bins tighter than the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * (1.0 - 0.3 * progress);

    // Mild pressure to consolidate when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: penalize early, allow late when stream nearly done
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover lies in
    // "useful" residue classes (multiples of common small sizes) are better.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect closure
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr >= 10 && pr <= 20 {
        -6.0 // leftover can host a small item
    } else {
        0.0
    };
    score += class_bonus;

    // Penalize dead space in awkward classes
    if pr > 20 && pr % 10 != 0 && pr % 5 != 0 {
        score += (pr as f64) * 0.15;
    }

    // Lookahead: if next item fits the post residual, reward strongly
    if next_item_size > 0 && next_item_size <= pr {
        let snug = (pr - next_item_size) as f64;
        score -= 12.0 - snug * 0.2;
    } else if next_item_size > pr {
        // next item cannot use leftover: penalize proportionally to waste
        score += frac * 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        // neutral-ish score: mean residual of open bins plus a fixed overhead
        score = 55.0 + mean_residual * 0.5;
        if open_bins_count == 0 {
            score = -100.0; // must open first bin
        } else if next_item_size > 0 && next_item_size <= mean_residual as u32 {
            score += 20.0; // existing bins can host next item too
        }
        // late in the stream, prefer closing bins rather than opening
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Crowding pressure: many open bins -> favor filling existing ones
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Mild preference for bins below mean residual (balance spread)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone (1..=12)
    // are heavily penalized since few items (min size 1, but typical stream items
    // are larger) can ever fill them.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64) / 13.0;
    }
    // Mid-range dead space gets a milder penalty.
    if post_residual > 12 && post_residual < 30 {
        score += 6.0 * (1.0 - (post_residual as f64 - 12.0) / 18.0);
    }

    // Reward tight fits (post_residual near 0 without being in dead zone).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Perfect-fit lookahead: if next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size <= 4 {
        score -= 12.0;
    }
    // Penalize if next item cannot fit in post_residual (dead end for this bin).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean residual coupling: bins far below mean residual waste potential; prefer
    // bins whose residual is close to the item (low fragmentation contribution).
    let frag = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.15 * frag;

    // New-bin candidate: baseline attractiveness; make it moderately costly so it
    // is chosen only when existing fits are poor, but allow it when open-bin count
    // is low and residual fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 3.0 * open_bins_count as f64 - 10.0 * progress;
        // If next item is small, a fresh bin is more attractive (long usable life).
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into the leftover space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits, but leaves a chain — mild reward proportional to how snug it is.
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space: next item cannot use the leftover — penalize small unusable remnants.
            score += 30.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Penalize residuals that no item (min size 1..100) can plausibly use later.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Relative to mean residual: prefer bins whose leftover is close to the average
    // (balanced packing), penalize outliers creating fragmentation.
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item fills it well.
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size >= 90 {
            score -= 300.0; // large item into fresh bin is fine
        }
    }

    // Slight preference to fill older/tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize larger post_residual quadratically.
    score += 0.15 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: leftover space too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // If next item fits in post_residual, mild bonus proportional to how well it fills.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * fill;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual cannot host next item: penalize proportional to wasted potential.
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Scarcity pressure: when few bins fit the item, prefer bins that keep options open.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global residual alignment: prefer bins whose residual deviates from the mean
    // in a way that reduces variance (consolidation effect).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev.abs().sqrt() * if dev > 0.0 { 1.0 } else { -1.0 };

    // Time horizon: early in the stream, be more willing to open new bins (keep flexibility);
    // late in the stream, pack tightly and avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 40.0 * progress;
        // But early on, opening a bin is cheap.
        score -= 25.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading; favor filling existing bins.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to item size (minimal waste).
    let slack = (bin_residual - item_size) as f64;
    score += 0.1 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * (0.5 + 0.5 * progress);

    let mut score = pr + 20.0 * poly;

    // Penalize small residuals that are hard to fill later (smooth via tanh-like term)
    let small_waste = 1.0 - (pr / 20.0).tanh();
    score += 15.0 * small_waste * pr_norm;

    // Reward near-perfect fits (post_residual close to 0)
    score -= 30.0 * (-pr / 10.0).exp();

    // Lookahead: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we prefer using open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (fill emptier bins) with smooth coupling
    score += 5.0 * ((mean_residual - pr) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

