    let class = post_residual % 10;
    let decade = post_residual / 10;

    // Dead-space penalty: small unusable leftovers are bad
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Harmonic class weighting: leftovers near multiples of 10 are reusable
    score -= match class {
        0 => 12.0,
        1..=3 => 4.0,
        4..=6 => 0.0,
        7..=9 => 3.0,
        _ => 0.0,
    };

    // Perfect fit reward
    if post_residual == 0 {
