    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 - slack as f64 * 0.3;
        if slack == 0 {
            score -= 15.0;
        }
    }
    // Penalize if next item would not fit here but fits a fresh bin class
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // Prefer new bin if open bins are crowded or mean residual is small
        let pressure = mean_residual / bin_capacity as f64;
        score = 45.0 - pressure * 40.0 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big next item benefits from fresh space
        }
        if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the lone fitting bin
        }
    }

    // Tightness coupling: reward filling a bin with high current residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Progress modulation: early in stream, be more selective about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * decade as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: gaps too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Strong penalty for medium dead-space bands that rarely get filled
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0 + 0.5 * (20 - post_residual) as f64;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space relative to capacity
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Open bins pressure: discourage spreading when many bins are open
    score += 0.15 * open_bins_count as f64;

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        score += 5.0 + 0.2 * open_bins_count as f64;
        if post_residual > 40 {
            score -= 20.0; // large item into fresh bin leaves useful space
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 5.0;
    }

    // Slight progression adaptation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (bin becomes perfectly full after next item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 40.0; // perfect 2-step fill
        } else if diff <= 5.0 {
            score -= 20.0 * (1.0 - diff / 5.0);
        } else {
            // penalize post-residuals that are neither small nor matching
            if post > nxt && post < nxt + 10.0 {
                score += 3.0; // just barely can't fit next item
            }
        }
        // prefer leaving room proportional to next item if we can't match exactly
        score += 0.15 * diff;
    }

    // Relative-to-mean residual coupling: bins with residual far below the
    // mean are "waste-heavy" targets; prefer filling them.
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post - mean_residual) / mean_residual;
        if rel < 0.0 {
            score -= 8.0 * (-rel).min(1.0); // below-mean residual: good to fill
        } else {
            score += 4.0 * rel.min(1.0); // above-mean residual: less attractive
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize near-full bins only mildly (they are good targets actually):
    // reward small post residuals.
    if post <= 10.0 {
        score -= 10.0 * (1.0 - post / 10.0);
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (favor existing bins).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            // New-bin candidate: usually penalized unless existing fits are bad.
            let mut new_bin_penalty = 30.0 + 20.0 * progress;
            if next_item_size > 0 && (next_item_size as f64) <= 100.0 - item_size as f64 {
                // new bin can still accommodate next item comfortably
                new_bin_penalty -= 10.0;
            }
            if fitting_bins_count == 0 {
                new_bin_penalty = 0.0; // forced new bin
            }
            score += new_bin_penalty;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that no plausible future item can fill
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 10.0; // chainable
            let leftover = post_residual - next_item_size;
            if leftover > 0 && leftover < 10 {
                score += 8.0; // would create sliver after next item
            }
        } else {
            // next item cannot use this residual; penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64) * 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins
    score += (open_bins_count as f64) * 0.8;

    // Bin whose residual is far from mean residual: slight penalty (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Time horizon: early in stream, be more willing to open new bins (keep residuals clean);
    // late in stream, squeeze into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin baseline: post_residual = capacity - item_size, already in score
        score -= progress * 10.0; // later => new bins cheaper relative to fragmentation
        if open_bins_count > 20 {
            score += 15.0; // too many open bins already
        }
    } else {
        score += (1.0 - progress) * 5.0; // early: mildly discourage filling open bins
    }

    // Prefer bins with larger residual when item is large (better use of space)
    score -= (bin_residual as f64 / bin_capacity as f64) * (item_size as f64 / 100.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let base = pr;
    // non-linear coupling of post_residual with stream progress
    let poly = base * (1.0 + 0.8 * progress * (pr / cap)) + 4.0 * (pr / cap) * (pr / cap) * (1.0 - progress);
    // reward tight fits
    let tight = -30.0 * (1.0 - pr / cap).powi(3);
    // penalize near-empty residual waste that next item cannot use
    let waste = if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        12.0 * gap * (1.0 + progress)
    } else { 0.0 };
    // last-chance bonus
    let last = if fitting_bins_count == 1 { -15.0 } else { 0.0 };
    // prefer filling bins when many open
    let crowd = 0.5 * open_bins_count as f64 * (pr / cap);
    // new-bin candidate: mildly discourage unless residual is unusable
    let new_bin = if bin_residual == bin_capacity { 25.0 + 20.0 * progress } else { 0.0 };
    base + poly + tight + waste + last + crowd + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class (0..=10)
    match class {
        0 => score -= 30.0,                 // near-perfect fit, tiny dead space
        1 => score -= 20.0,                 // excellent
        2 => score -= 12.0,                 // good
        3 => score -= 6.0,
        4 => score -= 2.0,
        5 => {}                             // neutral: half-full residual
        6 => score += 3.0,
        7 => score += 6.0,
        8 => score += 10.0,
        9 => score += 15.0,
        _ => {}                             // empty bin class handled below
    }

    // Modulo-10 fine structure: residual divisible by 10 is more reusable
    // for integer item sizes drawn from unknown distributions.
    if pr > 0 && pr % 10 == 0 {
        score -= 5.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // future still fits: penalize proportional to wasted fraction
            let slack = (pr - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here: penalize dead-space creation
            score += 6.0 * (next_item_size as f64 - pr as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
        score += 15.0 + 5.0 * congestion;
        // late in stream, new bins are cheaper than fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild preference for filling bins that are already well utilized.
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 3.0 * fill;

    // Tie-break coupling with mean residual: prefer bins below the mean
    // (drive all residuals down together).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, zero waste
    } else if post_residual < 10 {
        // unusable gap (below typical item floor): heavy penalty scaled by gap size
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        // usable gap: mild penalty, favor tighter fits
        score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Reward bins whose residual exactly matches the item (perfect packing).
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // next item cannot follow here; penalize slightly if gap is wasted
            score += 5.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 10 {
            score -= 30.0; // still better to consume the bin than open another
        } else {
            score -= 80.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // encourage consolidation when few bins are open.
    if bin_residual == bin_capacity {
        // new-bin candidate: score = base residual + pressure terms
        score += 25.0 * (open_bins_count as f64).sqrt();
        // a new bin is acceptable early in the stream or when mean residual is low
        score -= 10.0 * (1.0 - mean_residual / bin_capacity as f64);
        if step_index as f64 / (total_items.max(1) as f64) < 0.1 {
            score -= 15.0;
        }
    } else {
        // using an existing bin reduces open-bin count pressure
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer tight fits (small post_residual)
    score += (post_residual as f64) * 0.5;

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to wasted potential
            score += 10.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: bins with more residual than average are
    // better candidates to absorb the item (keeps tight bins for tight fits)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating small unusable dead space (<10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild late-stream consolidation: fewer open bins is better late on
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * progress;

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 + (item_size as f64) * 0.2;
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good alternative -> open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 3.0 * fill_frac;

    // Penalize large post-residuals nonlinearly (dead space).
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving awkward residual.
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin; decreases late in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 10.0 * progress;
        // More open bins -> prefer consolidation, penalize new bin.
        score += 1.5 * open_bins_count as f64;
        // If mean residual across bins is small (bins nearly full), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // If next item is large and current residuals are small, new bin attractive.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 5.0;
        }
    } else {
        // Prefer bins with residual close to item (minimize fragmentation).
        let fit_diff = (bin_residual - item_size) as f64;
        score += 0.3 * fit_diff;
        // Favor bins whose residual deviates from mean (balance residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Early stream: slightly prefer filling existing bins to keep bin count low.
    if step_index < total_items / 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;
    // Non-linear polynomial coupling: post_residual scaled by smooth progress interactions
    let poly = norm_pr * norm_pr * cap; // quadratic dead-space penalty
    let mut score = base + 0.5 * poly;
    // Early stream: tolerate larger residuals (favor filling bins later); late stream: penalize residual sharply
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score *= progress_weight;
    // Reward tight fits: subtract for small post_residual
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Lookahead: penalize if next item cannot fit the post residual (wasted opportunity)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.3 * gap;
        // Reward if next item fits snugly
        if next_item_size as u32 <= post_residual {
            score -= 10.0 * (1.0 - ((next_item_size as f64 - pr).abs() / cap));
        }
    }
    // Mean residual deviation: prefer bins close to mean residual (balanced packing)
    score += 0.2 * ((pr - mean_residual) / cap).abs() * cap;
    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 captures
    // "dead space classes" — residuals that are small or awkwardly small
    // (e.g. 1..9) are nearly unusable for typical items.
    let dead_class = post_residual % 10;
    if post_residual < 10 {
        score -= 25.0; // perfect tight fit, excellent
    } else if dead_class <= 2 {
        score += 6.0; // awkward tiny dead space on top of residual
    }

    // Fractional fill level of the bin (capacity fractions).
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill * fill; // reward high fill non-linearly

    // Harmonic threshold on post_residual via integer division:
    // post_residual / 10 gives a "decade class". Prefer bins whose
    // residual lands exactly on a class matching the next item size.
    if next_item_size > 0 {
        let next_decade = next_item_size / 10;
        let post_decade = post_residual / 10;
        if next_item_size <= post_residual {
            // Next item fits here: strongly reward exact decade match.
            if next_decade == post_decade {
                score -= 12.0;
            } else {
                score -= 4.0 * (post_residual as f64 - next_item_size as f64) / 100.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 5.0 + 0.05 * (next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge
    // and mean residual across open bins is small (all bins nearly full).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / (bin_capacity as f64);
        let penalty = 30.0 - 20.0 * pressure - 10.0 * progress;
        score += penalty.max(-15.0);
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 20.0; // nothing useful anywhere, new bin is fine
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual
    // (concentrate waste, keep large residuals consolidated).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable item (1..100 stream) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // unusable sliver -> heavy penalty
    } else if post_residual >= 10 && post_residual < 20 {
        score += 40.0; // risky small gap
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Tightness ratio: favor bins where the item fills a large share of residual.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: the gap is likely dead
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this placement would leave a bad gap.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by pressure
        score = bin_capacity as f64 - 50.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        if open_bins_count > 8 {
            score += 30.0; // too many open bins -> prefer consolidation elsewhere
        }
        if post_residual == 0 {
            score -= 0.0; // neutral, empty bin handled above
        }
    }

    // Open-bin pressure: mild reward for using existing bins when many are open.
    score -= 2.0 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins with residual close to item size
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, scaled relative to mean residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 0.5 * fit_ratio * mean_residual.max(0.0);

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leftover dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    } else {
        // last item: strongly prefer filling residual as much as possible
        score -= 10.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // with alternatives, mild penalty so tighter alternatives win
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin gets a moderate base penalty,
    // so it's chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is already small (consolidate waste).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Mild bonus for high utilization of this bin by current item.
    score -= 0.2 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 60.0 * tightness * tightness;

    // Penalize large dead space relative to typical item sizes (10..80 range mid ~45).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += (dead / 45.0).powf(2.0) * 4.0;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap);
    }
    // If next item can't fit anywhere in post residual, penalize leaving awkward residue.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // New-bin candidate logic: only attractive when current bin would leave bad residue
    // or when open bins are already fairly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early (consolidate), reward late when bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 50.0 * (1.0 - progress) - 25.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If the current item would leave a tiny unusable residual in existing bins, new bin is fine.
        if post_residual >= 10 && post_residual <= 9 {
            score -= 10.0;
        }
        // Compare against mean residual: if mean residual barely fits item, new bin better.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 30.0;
        }
        let _ = fragmentation;
    }

    // Mild preference for fuller bins when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Small time-horizon modulation: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer small post-residual, with a smooth super-linear penalty
    // on dead space (quadratic + cubic coupling normalized by capacity).
    let x = post / cap;
    let mut score = post * (1.0 + x * x + 0.5 * x * x * x);

    // Smooth stream-progress coupling: late in the stream, dead space matters
    // more (less chance to fill it), so amplify the post-residual penalty.
    score *= 1.0 + 0.6 * progress * x;

    // Reward tight fits: subtract a smooth bonus when post_residual is small
    // relative to the item size.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= 4.0 * item_size as f64 * tightness * tightness / cap;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // (avoid opening a new bin needlessly). Smooth in fitting_bins_count.
    if fitting_bins_count >= 1 {
        score -= 12.0 / fitting_bins_count as f64;
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (chaining); smooth quadratic coupling.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let chain = 1.0 - ((post - nxt) / cap);
            score -= 5.0 * (nxt / cap) * chain * chain;
        } else {
            // Next item won't fit here: mild penalty for blocking potential,
            // scaled by how far off it is.
            let gap = (nxt - post) / cap;
            score += 3.0 * gap * gap * nxt;
        }
    }

    // Mean-residual coupling: if this bin's post-residual is far below the
    // mean residual, we're consolidating space well — small reward.
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev * dev.abs().signum() * 0.0 + 1.5 * dev;

    // New-bin candidate: penalize opening a new bin unless existing bins are
    // poor fits or we're early with few bins. Smooth in open_bins_count.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let crowd = (open_bins_count as f64).ln().max(0.0) + 1.0;
        score += 15.0 * scarcity * (2.0 + 0.3 * crowd) * (1.0 - 0.5 * progress);
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= 6.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    // Residuals in "useful" bands (small, reusable gaps) should be rewarded.
    let post = post_residual as f64;
    let frac = post / cap;

    // Integer-division thresholds on post_residual: classify into harmonic classes
    // cap/8, cap/4, cap/2. Deep classes (tiny leftovers) are penalized dead space.
    let eighth = bin_capacity / 8;       // 12
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50

    if post_residual == 0 {
        // Perfect fit: best possible outcome.
        score -= 60.0;
    } else if post_residual <= eighth {
        // Nearly full: small but awkward remainder.
        score -= 35.0;
    } else if post_residual <= quarter {
        // Sweet spot: residual in (12, 25] fits common small items.
        score -= 25.0;
    } else if post_residual <= half {
        // Mid band: still flexible.
        score -= 12.0;
    } else {
        // Large leftover: wasteful placement, big item into big space.
        score += 8.0;
    }

    // Modulo-arithmetic coupling: does post_residual align with next_item_size
    // (exact fit for the lookahead) or with harmonic classes of capacity?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // lookahead fills bin exactly
        } else if next_item_size < post_residual {
            // Lookahead fits; reward tightness of that fit.
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Lookahead does NOT fit: this bin leaves a gap the next item can't use.
            score += 6.0;
        }
        // Modulo check: post_residual divisible by small harmonic steps (10s)
        // tends to pair well with round-sized future items.
        if post_residual % 10 == 0 && next_item_size % 10 == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the leftover would be a tiny dead sliver.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if post_residual > 0 && post_residual < 10 {
            score += 10.0; // creates unusable sliver anyway
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress and
        // how many bins are already open (fragmentation pressure).
        score = 0.55 * cap
            + 0.25 * (step_index as f64 / total_items.max(1) as f64) * cap
            + 0.05 * open_bins_count as f64;
        // If several bins already fit, opening a new one is rarely right.
        if fitting_bins_count > 0 {
            score += 15.0 * fitting_bins_count.min(5) as f64;
        }
        // If the next item is huge and current bins are fragmented, a fresh
        // bin becomes more attractive.
        if next_item_size as f64 > 0.6 * cap {
            score -= 12.0;
        }
    } else {
        // Mild preference for tighter existing bins relative to mean residual.
        score += 0.15 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0);
    }

    // Progress-aware tie-break: later in the stream, prefer exactness more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1) are
    // pure waste, but residuals below the typical usable threshold are especially bad.
    // Penalize any post_residual that is small but nonzero (unusable sliver).
    let sliver_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < sliver_threshold {
        score += (sliver_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure.
        score += 15.0 + pressure * 6.0;
    } else {
        // Existing bin: slight reward under pressure.
        score -= pressure * 2.0;
    }

    // Lookahead (k=2): if the next item can exactly use this bin's post_residual,
    // big bonus; if next item cannot fit in post_residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a bin with above-mean residual reduces fragmentation spread.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.15;

    // Mild preference for filling fuller bins early in the stream.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward bins where the leftover
    // after this item exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // chain fit: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportional to wasted gap
            score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are good
    // targets for large items; loose bins should absorb small items.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.25 * mean_gap;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize the brand-new empty bin candidate unless current fit is bad
    // or the next item would be stranded.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0; // new bin wastes the chain opportunity
        }
        if item_size >= 70 {
            score -= 25.0; // huge items are fine in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open a new bin
        }
    }

    // Early in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scaled by how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64).exp();
    }

    // Perfect fit gets strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if this bin could hold next item but placement wastes that chance, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // placing here blocks next item from this bin
            score += 6.0;
        }
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let consolidation_pressure = (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high or early stream.
        score += 10.0 + 8.0 * consolidation_pressure + 6.0 * (1.0 - progress);
        // Allow new bin if mean residual across open bins is tiny (all nearly full).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward more when consolidation pressure is high.
        score -= 4.0 * consolidation_pressure.min(3.0);
        // Prefer fuller bins (smaller residual) slightly.
        score += 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Late in stream, be more greedy about exact/tight fits.
    score -= 8.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear waste coupling: dead space penalized super-linearly, worse early in stream
    let dead_norm = pr / cap;
    score += dead_norm * dead_norm * cap * (0.5 + 1.5 * (1.0 - progress));

    // Tight fits rewarded strongly (quadratic reward on small post-residual)
    score -= (1.0 - dead_norm).powi(2) * item_size as f64 * 0.5;

    // Lookahead: penalize if next item no longer fits post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * 0.8 * (0.5 + progress);
        } else {
            // reward leaving room for the next item, smoother if snug
            score -= (1.0 - ((pr - nxt) / cap)) * 2.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= item_size as f64 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening bins when good fits exist, more so late
    if bin_residual == bin_capacity {
        score += cap * (0.3 + 0.7 * progress) + open_bins_count as f64 * 2.0;
    } else {
        // Prefer fuller bins relative to mean residual
        score += (mean_residual - bin_residual as f64).abs() * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 -> clean slots, reward
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 5 -> mild reward
    if post_residual % 5 == 0 {
        score -= 2.0;
    }
    // Class C: post_residual mod 10 in {1,2,3} -> tiny dead space, penalize
    let m = post_residual % 10;
    if m == 1 || m == 2 || m == 3 {
        score += 4.0;
    }

    // Integer division thresholds: small residuals are wasted space
    if post_residual < 10 {
        score += 12.0; // dead space below min item size
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // harmonic pairing: post_residual mod next_item_size small => good
            score -= (8.0 - (post_residual % next_item_size) as f64).max(0.0);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless it's a very tight fit
    if bin_residual == bin_capacity {
        score += 18.0 + 0.1 * open_bins_count as f64;
        if item_size >= 50 {
            score -= 10.0; // big items are fine in fresh bins
        }
    }

    // Progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mean residual deviation: prefer bins close to mean residual (balance)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavy penalties.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item almost fits but not quite (dead end).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
    score += pressure * 0.5;

    // New-bin candidate: only attractive when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64 + 10.0;
        if decent_fit_exists {
            score += 40.0 + open_bins_count as f64 * 2.0;
        } else {
            score -= 5.0;
        }
    }

    // Mild alignment with mean residual: prefer bins with below-average residual
    // (i.e., fuller bins) to consolidate space.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // slack after hypothetically fitting the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack);
            // penalize residual too small to ever fit a minimum item
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * gap;
        }
        // penalize dead space: post_residual > 0 but < smallest plausible item
        if post_residual > 0 && post_residual < 10 {
            score += 60.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate: make it unattractive unless no open bin fits well
    if bin_residual == bin_capacity {
        score += 250.0;
        // allow new bin early in stream or when many bins already open
        score -= 100.0 * (step_index as f64 / total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for filling large residual bins
    score -= (bin_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize large dead space relative to capacity
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0;
        }
        // exact pairing bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // New-bin candidate: penalize opening a new bin when good fits exist,
    // but allow it when open bins are all crowded (low mean residual).
    if bin_residual == bin_capacity {
        score += 80.0;
        if mean_residual < item_size as f64 * 1.5 && open_bins_count > 0 {
