        let tight = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 30.0 * (1.0 - tight);
    }

    // Time horizon: early in stream, be conservative with new bins; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * (1.0 - progress);
    } else {
        score -= 20.0 * progress;
    }

    // Prefer fuller bins overall
    score -= 0.5 * (bin_capacity as f64 - bin_residual as f64);

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), scaled smoothly.
    let mut score = pr;

    // Non-linear coupling: tight fits (small post_residual) are rewarded more
    // strongly as the stream progresses, via a smooth polynomial interaction.
    let tightness = 1.0 - (pr / cap);
    let coupling = tightness * tightness * (0.5 + 1.5 * progress);
    score -= 12.0 * coupling * pr / cap;

    // Penalize large dead space quadratically, weighted by stream maturity.
    let dead = (pr / cap).powi(2);
    score += 25.0 * dead * (0.4 + 0.8 * progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual is unusable for the next item, penalize smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let miss = (nx - pr) / cap;
            score += 10.0 * miss * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this placement wastes space.
    score += 0.3 * (pr / cap) * (open_bins_count as f64).sqrt();

    // Mean-residual alignment: prefer bins whose residual stays near the mean
    // (smooth Gaussian-like term) to keep residual distribution balanced.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate handling: empty bin should only win when it truly helps.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual non-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 5 {
        score -= 60.0;
    }

    // Harmonic class logic: classify post_residual into residue classes mod 10.
    // Small residues (<10) are dead space; residues that can host common item sizes are valuable.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 && pr < 10 {
        score += 25.0; // dead-space penalty for tiny leftover
    }
    // Classes matching typical item sizes (10,20,...) keep bin reusable for aligned items.
    if class == 0 && pr > 0 {
        score -= 15.0;
    } else if class >= 5 && pr >= 15 {
        score -= 8.0; // mid-class leftovers still fit many items
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        // Harmonic alignment: next item size multiple of 10 pairs well with aligned residuals.
        if next_item_size % 10 == 0 && class == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // Post-residual too small for next item: mild penalty scaled by dead space.
        score += 10.0 * frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current open bins are crowded
    // or this is a poor fit everywhere.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count <= 1 {
            score -= 60.0; // no good alternative: new bin is fine
        }
        if open_bins_count > 0 {
            // If mean residual across open bins is small, opening fresh bin is attractive.
            if mean_residual < item_size as f64 * 1.2 {
                score -= 40.0;
            }
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Prefer filling bins that are already mostly full (waste-avoidance).
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * used * used;

    // Slight penalty proportional to number of open bins to discourage bin proliferation
    // when residuals are similar to mean.
    if (mean_residual - post_residual as f64).abs() < 5.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste. Penalize small-but-nonzero gaps super-linearly.
    if post_residual > 0 {
        // gap of 1..=9 is unusable for min-size item; huge penalty
        if post_residual < 10 {
            score += 200.0;
        } else {
            // quadratic penalty on wasted fraction of the bin
            let waste_frac = post_residual as f64 / bin_capacity as f64;
            score += 40.0 * waste_frac * waste_frac;
        }
    } else {
        // perfect fit: strong reward
        score -= 150.0;
    }

    // Reward tight fits relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 2.0 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // lumpy bin — prefer placing into it to consolidate space.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Lookahead: if next item fits exactly into the post residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 60.0; // chains perfectly with next item
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the leftover gap; penalize if gap is dead
        if post_residual > 0 && post_residual < 10 {
            score += 100.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // make it costly by default, cheaper when item is large.
        score += 60.0 - 0.4 * item_size as f64;
        // If existing bins are fragmented (high mean residual spread), new bin ok
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: small post_residual is good, but zero is best.
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 2.0;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits with slack left; mild reward scaled by slack smallness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack);
        } else {
            // next item does NOT fit in leftover: dead space likely, penalize
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    }

    // Compare against mean residual across open bins.
    // Bins tighter than the mean are more precious; prefer using loose bins first.
    if (post_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New empty bin candidate: only attractive when current bins are very full
    // (mean residual small) or the item would leave a large awkward gap.
    if bin_residual == bin_capacity {
        let tight = mean_residual < 8.0;
        let awkward = (post_residual as f64) > 0.0 && (post_residual as f64) < 10.0;
        if tight || awkward {
            score -= 20.0;
        } else {
            // discourage opening new bins when decent fits exist
            score += 30.0 + (open_bins_count as f64);
        }
    }

    // Prefer filling bins that are already quite full (keep few bins tight).
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score += fill_ratio * 4.0;

    // Slight preference to keep number of open bins low.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
