    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) / bin_capacity as f64;
        // Base cost of opening a bin; decreases as stream progresses (sunk costs matter less).
        score += 30.0 - 15.0 * progress;
        // If item leaves a very awkward residual in any bin, new bin is competitive.
        if poor_fit < 0.15 && item_size < 60 {
