    // Prefer filling larger-residual bins slightly when few bins open (avoid fragmentation).
    if open_bins_count > 1 && bin_residual as f64 > mean_residual {
        score -= 1.0;
    }

    // Time-horizon term: early in stream, be conservative (higher score for waste);
    // late in stream, squeeze bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
