    // Base: prefer tight fits (small post_residual), with mild non-linear sharpening.
    let mut score = pr + 0.15 * (pr * pr) / cap;

    // Interaction: post_residual coupled with stream progress — late in the stream,
    // dead space is costlier, so amplify the quadratic term smoothly.
    score += 0.35 * progress * (pr * pr) / cap;

    // Reward placements where the lookahead item still fits the residual
