    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 6.0 * snug * snug;
    }

    // Penalize leaving a residual that almost surely becomes dead space
    // (smooth sigmoid-like bump around tiny residuals).
    let tiny = (1.0 - (pr / cap).min(1.0)).powi(4);
    score += 2.0 * tiny * pr / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // fit into existing bins is poor. Penalize the new bin by an amount that
    // smoothly decays as mean residual across open bins shrinks.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).min(1.0);
        score += 5.0 + 10.0 * crowding + 4.0 * (1.0 - progress);
        // Slightly favor new bins late in stream if open bins are all nearly full.
        if open_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Reward using bins that are already partially loaded (compactness pressure).
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 3.0 * fill * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
