    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 20.0 + 3.0 * open_bins_count as f64 + 15.0 * progress;
        // Slightly cheaper to open a new bin early in the stream.
        score -= 10.0 * (1.0 - progress);
        // If the new bin would be tightly packed by this item, reduce penalty.
        if item_size >= 70 {
            score -= 10.0;
        }
    } else {
        // Mild preference for fuller bins relative to mean residual.
        if (bin_residual as f64) < mean_residual {
            score += 4.0;
        } else {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post_residual more strongly when fit is exact.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space below the minimum item size region:
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual; mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);
    score -= 2.0 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate handling: make empty bin moderately attractive only when
    // current item is large relative to residual and no tight fit exists.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, decaying as stream progresses
        score = cap * 0.9 - 15.0 * progress;
        if item_size as f64 / cap > 0.8 {
            score -= 10.0; // big items okay to start fresh
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 8.0; // future may need this space elsewhere
        }
    }

    // Small nonlinear coupling: fragment penalty grows with fill fraction.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score += 5.0 * (post_residual as f64 / cap) * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    let mut score = base * (1.0 + 2.0 * progress * base);
    // penalize dead space quadratically when few bins remain open
    let tightness = (open_bins_count as f64).max(1.0).ln();
    score += 0.35 * base * base * progress / tightness;
    // reward near-perfect fits smoothly
    let fit = 1.0 - pr / cap;
    score -= 0.5 * fit * fit * fit;
    // lookahead: penalize wasting space needed by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0) / cap;
        score += 0.6 * waste * (1.0 + progress);
        // reward if next item fits in post residual
        let bonus = (pr - nx).max(0.0) / cap;
        score -= 0.4 * bonus * (1.0 - progress);
    }
    // last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 0.8 * (1.0 - progress);
    }
    // new-bin candidate: penalize mildly unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 0.15 + 0.3 * (1.0 - fit);
    }
    // mean residual alignment: prefer bins close to mean residual
    let drift = (pr - mean_residual) / cap;
    score += 0.1 * drift * drift;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals in [1,10] are prime real estate (small items 10..80 rarely fit);
    // residuals that are multiples of common item sizes pair well with future items.
    let pr = post_residual;
    let frac = pr as f64 / bin_capacity as f64;

    // Penalize small dead space heavily (non-linear squashing).
    if pr > 0 {
        let dead = (10.0 / pr as f64).min(10.0);
        score += 4.0 * dead;
    } else {
        // Perfect closure is ideal.
        score -= 15.0;
    }

    // Harmonic bonus: post_residual divisible by 25/50/100 leaves room for
    // quarter/half-capacity items.
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size < pr {
            score -= 2.0 + 5.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted pairing chance.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty
    // so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64).sqrt();
        // Late in stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild preference for bins below mean residual (balancing load).
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Tight-fit reward: item filling most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 5.0 * fill;

    // Integer-division threshold: post_residual < 20 is nearly dead space.
    if pr > 0 && pr < 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; residuals below a "useful threshold" are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Reward bins whose residual was already small (tight packing).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize creating a gap that just barely misses the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += pressure * (post_residual as f64 * 0.5);

    // Deviation from mean residual: prefer bins near the mean (balanced fill),
    // but when few bins remain fitting, ignore this.
    if fitting_bins_count > 1 {
        score += (post_residual as f64 - mean_residual).abs() * 0.3;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        // Base cost of opening a new bin; discounted when open bins are large in count
        // or the current fit is terrible.
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.6;
        score = if desperation > 0.0 || poor_fit {
            score * 0.5 + 30.0
        } else {
            score + 120.0 + open_bins_count as f64 * 2.0
        };
    }

    // Mild stream-progression tilt: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as u32 == next_item_size {
            score -= 400.0; // chain: item now, next item fills bin perfectly
        } else if post_residual as u32 > next_item_size {
            // next item fits after this one: reward closeness of the double-fill
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would NOT fit: penalize dead space created
            score += 60.0 + 0.5 * diff;
        }
    }

    // Compare post_residual to mean residual: prefer bins left tighter than average.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (post_residual would be huge, i.e. item tiny relative to empty bin).
    if bin_residual == bin_capacity {
        score += 250.0
            - 0.5 * item_size as f64
            - 10.0 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Late-stream tightness: waste matters more as stream progresses.
    score += 0.3 * (post_residual as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fills (low post_residual relative to capacity).
    score -= 30.0 * (1.0 - post / cap);

    // Lookahead: if next item exactly fills the leftover, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // leftover is dead space for the next item
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when alternatives exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * open_bins_count as f64;
    }

    // Prefer bins whose residual is far below the mean (i.e., filling laggard bins).
    score += 0.1 * (mean_residual - post);

    // Time horizon: later in the stream, weight tightness more strongly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear penalty for awkward dead space
    let mut score = pr
        + 18.0 * pr_norm * pr_norm * (1.0 - pr_norm)
        - 12.0 * pr_norm * (1.0 - pr_norm);

    // Smooth progress coupling: early stream tolerates large residuals less (keep bins flexible),
    // late stream penalizes residual more (consolidate)
    let late = progress * progress;
    let early = (1.0 - progress) * (1.0 - progress);
    score += late * pr * 0.6 - early * pr * 0.3;

    // Perfect fit reward (smooth gaussian-like bump near zero residual)
    score -= 25.0 * (-pr_norm * 8.0).exp();

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap / 15.0).exp();
        // penalize if post residual is slightly larger than next item (dead space)
        score += 0.15 * gap * pr_norm;
    }

    // Many open bins: encourage filling existing ones over opening new
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
    score += openness * pr * 0.4;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.5 * (mean_residual - pr).max(-30.0).min(30.0) * (1.0 - progress);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by modulo classes of capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-10 class of post_residual: small residues are "dead space"
    let mod10 = post_residual % 10;
    if mod10 != 0 {
        score += (10 - mod10) as f64 * 0.35;
    }

    // Integer-division thresholds: post_residual in low quarters is bad
    let quarter = cap / 4.0;
    if post < quarter {
        score += 6.0;
    } else if post < 2.0 * quarter {
        score += 2.0;
    }

    // Perfect-fit harmonic classes: post_residual divisible by common item sizes
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: does next item fit exactly or harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= 3.0;
            if nxt_post % 10 == 0 {
                score -= 3.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only open a new bin when the stream is early
    // or mean residual across open bins is already tiny (fragmented state)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        if fragmentation < 0.25 && open_bins_count > 0 && progress > 0.05 {
            score -= 6.0;
        } else {
            score += 10.0;
        }
    }

    // Prefer filling tighter bins when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap) * 1.5;

    // Small tie-break toward exact fills
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum plausible item
    // size (1) are worthless, but "nearly dead" gaps (very small relative to
    // capacity) are the real waste. Penalize them super-linearly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // unusable sliver: huge penalty so this bin is avoided unless nothing else works
        score += 40.0 + (dead_threshold - post_residual as f64) * 6.0;
    } else if (post_residual as f64) < 0.25 * bin_capacity as f64 {
        // small-but-alive gap: mild penalty proportional to how cramped it is
        score += 4.0 * (1.0 - post_residual as f64 / (0.25 * bin_capacity as f64));
    }

    // Reward tight fits (post_residual near zero but still usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 6.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new
    // bins; encourage closing out partially-filled bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: acceptable early, increasingly penalized
        // as open bins accumulate, unless the fit into open bins is bad.
        score += 8.0 + open_pressure * 0.5;
    } else {
        // Favor bins whose residual is below the mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the leftover: leftover likely becomes dead space
        score += 3.0;
    }

    // Late in the stream, be greedier about filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that hypothetical placement.
            let after_next = post_residual - next_item_size;
            score -= 200.0 - 0.5 * after_next as f64;
        } else {
            // next item does not fit: penalize proportional to how far off it is.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.8 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: neutral-ish score so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 30.0;
        }
        if fitting_bins_count == 1 {
            score += 200.0; // don't open new bin when an existing bin is the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to the smallest possible future item (1..100 range).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * dead * dead;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves further waste; mild reward proportional to how snug.
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: penalize leaving medium-sized holes.
            let hole = post_residual as f64;
            if hole >= next_item_size as f64 * 0.5 && hole < next_item_size as f64 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state: when many bins are open, discourage opening new bins implicitly
    // by penalizing high post residuals more (fragmentation control).
    let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score += 4.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, prefer consolidating (tighter fits matter more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * fit_ratio;

    // Deviation from mean residual: prefer bins whose residual is already below average
    // (concentrate filling), unless it's a fresh bin.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 3.0 * dev;
    } else {
        // New empty bin candidate: mild penalty so it's chosen only for poor fits elsewhere,
        // relaxed when few bins are open or item is large.
        score += 10.0 - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - pr / cap; // fullness after placement, in (0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm); // penalizes mid-range residuals
    let mut score = pr
        - 40.0 * poly * (1.0 + progress)
        - 30.0 * tight * tight * (0.5 + progress);

    // Reward near-perfect fits more strongly as stream progresses
    if pr == 0.0 {
        score -= 50.0 * (0.5 + progress);
    }

    // Lookahead coupling: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 15.0 * (1.0 - (pr - nx) / cap) * (0.5 + progress);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild preference toward consolidating into fewer bins early on
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * pr_norm;

    // Penalize bins far below the mean residual (wasteful use of a roomy bin)
    score += 5.0 * (mean_residual - pr).max(0.0) / cap;

    // New-bin candidate: keep it competitive only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Penalize leftovers by class: tiny dead space is fine, mid-range leftovers are worst.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= eighth {
        score -= 25.0;
    } else if post_residual <= quarter {
        score -= 10.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    } else {
        // large leftover: bin was nearly empty, only good if this bin is the fresh-bin candidate
        score += 4.0;
    }

    // Modulo-10 harmonic band: leftover divisible into small chunks is reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 18.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item won't fit here; penalize more if leftover is awkwardly small
            if post_residual < quarter {
                score += 6.0;
            }
        }
    } else {
        // last item: prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: avoid opening a new bin if this fits reasonably.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Fresh empty bin candidate: only attractive when open bins have high residuals
    // or this bin would be the fresh one — make it unattractive by default.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item stream: new bin may be wise
        }
    }

    // Early stream: keep bins open, spread load slightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    // Prefer bins below mean residual (fill emptier bins first when equal).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Reward near-perfect fits (waste <= 5) strongly.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // If the next item could reuse this post_residual, reward it (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap just below the next item's size (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Allow opening a new bin if no open bin fits at all.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Reward using bins when many are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Last-chance bin: strongly favor it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late-stream urgency: fill bins tighter as the stream progresses.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // smaller gap after next placement is better; penalize dead space
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            score += 0.35 * gap;
        } else {
            // next item cannot fit here; post_residual becomes pure dead space
            let dead = post_residual as f64;
            score += 0.6 * dead * (dead / bin_capacity as f64);
        }
    } else {
        // last item: just minimize leftover
        score += 0.2 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual below mean are precious,
    // discourage wasting them on poor fits.
    if (bin_residual as f64) > mean_residual {
        score += 0.25 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are heavily fragmented or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        // penalize new bin normally...
        score += 18.0 + 10.0 * (1.0 - progress);
        // ...but discount it when existing bins are fragmented and item is large
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fragmentation * big_item;
        // never open a new bin if a perfect chain exists elsewhere
        if next_item_size > 0 && fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post residual so large dead space is punished hard.
    score += 0.35 * (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 120.0; // nearly perfect fit, residual likely unusable anyway
    }

    // Lookahead: if the next item fits into the post residual, this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item would have fit now but not after this placement — mild penalty
            score += 15.0;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are large and fragmented relative to the item, or few bins are open.
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early in the stream, new bins are cheap (future items can fill them).
        let new_bin_discount = 40.0 * (1.0 - t) + 10.0;
        score = 55.0 - new_bin_discount
            + 0.25 * mean_residual * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can always host the next item too.
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    } else {
        // Prefer filling bins whose residual is close to the item (minimal waste).
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 45.0 * fit_ratio * fit_ratio;

        // Penalize placing into bins whose residual is far above the mean (keep
        // large residuals available for large future items).
        if (bin_residual as f64) > mean_residual + 15.0 && item_size < 40 {
            score += 12.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize remaining space, but non-linearly (wasted space matters more when small)
    let mut score = pr * (1.0 + 0.5 * (1.0 - pr / cap).powi(2));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep bins roomy; late, tolerate tight fits less harshly.
    let coupling = pr / cap;
    score += 8.0 * coupling * coupling * (0.5 + progress) - 4.0 * coupling * progress;

    // Reward near-perfect fits with a smooth bump
    let fit_tightness = 1.0 - (pr / cap).powi(3);
    score -= 6.0 * fit_tightness * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (1.0 - pr / cap) * (nx / cap);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += (open_bins_count as f64).ln() * (pr / cap);

    // Mean residual context: penalize bins far from the mean residual (keeps spread tight)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: make it moderately unattractive unless residuals are very tight
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (quarter bins)
    let class = post_residual / (bin_capacity / 4).max(1);
    score += (class as f64) * 2.0;

    // Tight fit reward: post_residual small relative to item size
    let tight = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 / (1.0 + tight)) * 8.0;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize residuals that no plausible item (1..=100) can use efficiently:
    // dead space if post_residual is tiny but nonzero
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 12.0 / (1.0 + gap as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins with larger residuals (reduce fragmentation)
    score -= (bin_residual as f64 / cap) * 5.0;

    // Mean residual coupling: avoid disturbing bins close to the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate handling: make fresh bin costly early, cheaper late
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
        if fitting_bins_count >= 1 {
            score += 10.0; // only open new bin if existing fits are bad
        }
    }

    // Modulo harmonic bonus on post_residual (nice leftover sizes)
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post-residuals are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable gap (min item size 1..100 interface, but small gaps waste)
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 35 {
        score += 3.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 2.0 * pressure;
    } else {
        // New-bin candidate: penalize mildly so it only wins on poor fits.
        score += 6.0 + 3.0 * pressure;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
            // extra reward for tight coupling of next item into the gap
            let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 4.0 * tightness;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 2.0; // gap likely dead for the next item
        }
    }

    // Mean-residual coupling: if this bin is below average residual, filling it balances residuals.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= 0.5 * diff;
    }

    // Late-stream consolidation: toward the end, prefer tightest fits harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild quadratic penalty
    // on wasted space to punish large dead zones more strongly.
    let pr = post_residual as f64;
    score += 0.15 * pr * pr / bin_capacity as f64;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect match: item fills the bin exactly after next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here: reward proportionally to how well
            // the remaining gap is consumed (small leftover after both).
            let double_leftover = pr - ni;
            score -= 25.0 * (1.0 - double_leftover / bin_capacity as f64);
        } else {
            // Next item does NOT fit here: penalize leaving a gap that is
            // "almost but not quite" the next item (worst dead space).
            let gap = pr - ni; // negative
            let closeness = 1.0 - (-gap / bin_capacity as f64);
            score += 20.0 * closeness;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score -= 10.0 * (1.0 - pr / bin_capacity as f64);
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer placing into bins whose residual is already below average
    // (consolidate waste into few bins), penalize dumping into large bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // --- Last-chance bonus: this is the only bin that fits the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are very
        // fragmented (high mean residual) or item is huge and would leave
        // a tiny unusable sliver in any open bin.
        let fragmentation = mean_residual / bin_capacity as f64;
        let sliver = pr as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if pr < 15.0 {
            // Huge item leaving a tiny sliver: new bin is great (sliver
            // likely fillable by small future items).
            score -= 55.0 + 30.0 * (1.0 - sliver);
        } else if fragmentation > 0.45 {
            score -= 10.0 * fragmentation;
        } else {
            // Prefer reusing open bins early on; new bins get costlier late.
            score += 25.0 + 15.0 * progress;
        }
    }

    // Mild crowding pressure: with many open bins, favor consolidation.
    if open_bins_count > 4 {
        score += 0.2 * open_bins_count as f64 * (pr / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to smallest plausible future item
    if post_residual > 0 {
        score += (post_residual as f64).sqrt() * 1.5;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = 1.0 - (next_item_size as f64 / post_residual as f64);
        score -= 10.0 + 8.0 * chain;
    } else if next_item_size > post_residual {
        // next item won't chain here; penalize leaving awkward gap
        score += 3.0;
    }

    // Dead space that neither current nor next item can use
    if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.15;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    let consolidation_pressure = mean_residual / bin_capacity as f64
        * (open_bins_count as f64).ln().max(1.0);
    score -= consolidation_pressure * 4.0;

    // Time horizon: late in stream, prefer filling existing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0 * fit_ratio * 10.0;
    score += progress * post_residual as f64 * 0.1;

    // New bin candidate: only attractive when item is large or no good open bin exists
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 6.0 } else { 0.0 };
        score += 10.0 - large_item_bonus
            - (if fitting_bins_count == 0 { 30.0 } else { 0.0 })
            + progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post-residual, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let x = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth interaction: residual penalty grows/curves with progress
    score += 0.6 * x * x * (1.0 - p) + 1.2 * x * x * p;
    // Cubic coupling term favoring tiny residuals early, penalizing mid residuals late
    score += 0.4 * x * (1.0 - x) * (0.5 + p);
    // Penalize large wasted residual as stream advances (quartic smoothness)
    score += 0.8 * x.powi(4) * p;

    // Reward tight fits smoothly (post_residual near zero)
    score -= (1.0 - x).powi(3) * 0.5;

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + p);
    }

    // Lookahead: reward leaving room for the next item (smooth hinge)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = ((pr - nxt) / cap).max(0.0);
        score -= 0.7 * (1.0 - fits) * (fits > 0.0 || pr >= nxt) as i32 as f64;
        // extra coupling: if next item exactly fills residual
        let diff = (pr - nxt).abs();
        score -= 0.9 * (-diff / 20.0).exp();
    }

    // Mean residual context: penalize bins far from mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.002 * dev * dev;

    // New-bin candidate: mild penalty so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 0.35 + 0.5 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Harmonic class of the post-residual: dead space in the "hard" low band
    let pr = post_residual;
    if pr > 0 {
        if pr < 10 {
            score += 30.0; // unusable sliver for most items
        } else if pr < 20 {
            score += 15.0;
        } else if pr < 34 {
            score += 6.0;
        }
    } else {
        score -= 50.0; // perfect closure
    }

    // Modulo-10 harmonic classes: residual that is a multiple of 10 is reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0;
        // bonus if next item exactly closes the bin
        if next_item_size == pr {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize leaving awkward space
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // prefer new bin when mean residual is small (bins are full-ish)
        score = 40.0 - 60.0 * fragmentation - 20.0 * progress;
        // never open a new bin when it's the only option anyway (score stays high enough to be chosen only if all else fails)
        if fitting_bins_count <= 1 {
            score += 100.0;
        }
    }

    // Slight preference for bins tighter than the mean
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (>=1) can
    // use well are heavily penalized. Items are 1..=100, so any residual is
    // technically usable, but tiny residuals (< 10) are low-value.
    if post_residual < 10 {
        score += 40.0; // dead space penalty
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits: the smaller the wasted fraction of the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: if this is the ONLY bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // ones rather than opening new bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: a fresh empty bin is a fallback; make it
    // unattractive unless existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Mild preference to use bins with lower residual overall (fill emptier bins first).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step pairing: item + next item fills bin exactly.
            score -= 60.0 + item_size as f64;
        } else if post_residual > next_item_size {
            // Next item can still fit afterwards; reward tightness of the gap.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 - gap.min(25.0);
        } else {
            // Next item cannot use the leftover; penalize dead space, more so
            // when the leftover is small and thus hard to reuse later.
            let dead = post_residual as f64;
            score += 10.0 + (dead / bin_capacity as f64) * 20.0;
        }
    } else {
        // Last item: prefer minimal residual, with bonus for exact closure.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are
    // "tighter" and better to fill now; bins above the mean are loose.
    let rel = (bin_residual as f64) - mean_residual;
    score += rel * 0.35;

    // Prefer tight fits overall (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 15.0;

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so we don't open bins frivolously.
        score += 45.0 + open_bins_count as f64 * 3.0;
        // If next item is large and would fit a fresh bin well, opening
        // becomes more attractive when current bins are very loose.
        if next_item_size > 0 && mean_residual > (next_item_size as f64) * 1.8 {
            score -= 25.0;
        }
        // Early in the stream, having some bins open is fine; late in the
        // stream, avoid spreading residual across many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Exact-fill bonus for the current placement.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to hold the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when other bins fit, unless the item
    // would leave a very bad residual everywhere.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 12.0 } else { -50.0 };
        score += pressure;
        // New bins are more acceptable late in the stream (fewer future items
        // to fill them), and when open bins are already crowded on average.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - t);
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    // Mild penalty for spreading across many open bins: prefer consolidating
    // into fewer, fuller bins.
    score += 0.15 * open_bins_count as f64;

    // Coupling: penalize placements whose post_residual is far below the mean
    // residual (creating fragmented small holes) but reward near-mean fills.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small time-horizon modulation: early in the stream, be more selective
    // (penalize loose fits since many items remain); late, accept more.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with polynomial coupling to stream progress.
    // Early on, large residuals are acceptable (bins can be filled later);
    // late in the stream, dead space is increasingly costly.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Smooth non-linear coupling: quadratic term in normalized residual,
    // weighted by progress — small residuals are fine, large ones get superlinear penalty.
    score += 30.0 * progress * norm_pr * norm_pr * cap * 0.1;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement; if next item is close to fitting, mild reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (pr - next).abs();
        if next <= pr {
            // next item fits: reward exact/near-exact fits smoothly
            score -= 25.0 * (1.0 - gap / cap).powi(3);
        } else {
            // next item does not fit: mild penalty proportional to overshoot
            score += 8.0 * ((next - pr) / cap).powi(2);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid new-bin inflation).
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins whose residual stays near the mean
    // (keeps a portfolio of usable bins rather than one huge / many tiny).
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate calibration: an empty bin has maximal residual; make it
    // moderately attractive only when the current fit is terrible and no lookahead helps.
    if bin_residual == bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "waste band" does it fall into?
    // Class 0: post_residual == 0 (perfect fill) — huge reward.
    // Class 1: small remainder (<= 10) — great.
    // Class 2: medium remainder (11..=30) — moderate penalty.
    // Class 3: large remainder (> 30) — dead-space penalty.
    let pr = post_residual;
    let band = if pr == 0 { 0u8 }
        else if pr <= 10 { 1 }
        else if pr <= 30 { 2 }
        else { 3 };

    match band {
        0 => { score -= 60.0; }
        1 => { score -= 25.0; }
        2 => { score += 12.0; }
        _ => { score += 35.0; }
    }

    // Integer-division harmonic classes on residual: multiples of common item sizes
    // (10/20/25/50) leave residue reusable by typical item sizes.
    let harmonic = [10u32, 20, 25, 40, 50, 100].iter().any(|&m| pr % m == 0 && pr > 0);
    if harmonic { score -= 8.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item cannot use this bin's remainder: penalize large leftover.
        score += 0.25 * pr as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has raw score = capacity.
    // Make fresh bins attractive only when existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; scaled by stream position (later => cheaper to consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 95.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can host both items
        }
    }

    // Prefer filling bins whose residual deviates below the mean (tighter bins first).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // Mild pressure against accumulating many open bins with large residuals.
    score += 0.02 * open_bins_count as f64 * (pr as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Small gaps that only fit tiny items are nearly dead too.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that the next item just barely misses.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 8.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.6;

    // New-bin candidate handling: an empty bin has large residual;
    // make it attractive only when existing bins would leave bad gaps
    // or mean residual is already low (fragmented bins).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.35 {
            score -= 10.0; // existing bins are full-ish, new bin fine
        } else {
            score += 18.0; // prefer filling existing bins first
        }
    }

    // Prefer bins tighter than average (better fit quality).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual to next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // perfect 2-step fit
        } else if diff <= 5 {
            score -= 25.0;
        } else if diff <= 15 {
            score -= 10.0;
        } else {
            // penalize dead space that next item cannot use
            score += (diff as f64).min(60.0) * 0.3;
        }
    }

    // Tight fits in general are good (low post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Reward filling bins that are already small-residual (close them out)
    if post_residual <= 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Compare against mean residual: bins with residual near/below mean are better targets
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when current item leaves huge unusable gap
    if bin_residual == bin_capacity {
        let gap_penalty = if next_item_size > 0 && post_residual > 0
            && (post_residual as u32) < next_item_size
        { 25.0 } else { 0.0 };
        score += 55.0 - gap_penalty;
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that cannot fit the next item (lookahead blocking).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size && post_residual > 0 {
            // Reward leaving space the next item can use.
            score -= 0.3 * (post_residual.min(next_item_size * 2)) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64).sqrt();
        // But early in the stream, allow exploration.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is high, prefer reusing them.
        score += 0.2 * mean_residual;
    }

    // Mild penalty for very large leftovers that likely become dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 0.3 * (20 - post_residual) as f64;
    }

    // Prefer bins with less residual among comparable fits (fragmentation control).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: normalized post-residual, non-linearly shaped by stream progress.
    // Early on, prefer tight packing (low post_residual); later, tolerate slack.
    let x = pr / cap;
    let base = x.powf(1.2 + 1.3 * progress);

    // Smooth interaction: post_residual squared coupling with progress
    // penalizes large dead space increasingly as the stream ends.
    let dead_space_penalty = (x * x) * (0.6 + 1.8 * progress);

    // Reward near-perfect fits with a smooth bump: exp of squared deviation.
    let fit_bonus = -2.5 * (-(x * x) * 12.0).exp();

    // Last-chance bonus: strongly favor using the only bin that fits.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -3.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead: penalize leaving residual that fails to fit the next item.
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr < next_item_size as f64 {
            (0.5 + 1.5 * progress) * (next_item_size as f64 - pr) / cap
        } else {
            -0.3 * (1.0 - progress) * (1.0 - nx)
        }
    } else {
        0.0
    };

    // Deter opening new bins when open bins already fit reasonably well.
    let new_bin_deter = if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        1.2 + 2.0 * (1.0 - progress) + 0.8 * avg
    } else {
        0.0
    };

    // Mild dispersion term: prefer bins whose residual differs from the mean
    // (keeps a spread of residual sizes for future items).
    let dispersion = if bin_residual != bin_capacity {
        0.15 * ((bin_residual as f64 - mean_residual) / cap).abs()
    } else {
        0.0
    };

    base + dead_space_penalty + fit_bonus + last_chance + lookahead + new_bin_deter + dispersion
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: dead space classified by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Harmonic bins: post_residual divisible into small reusable classes.
    // Classes: multiples of 10 (half/full quarters) are "usable" residuals.
    let harmonic = (post_residual % 10 == 0) || (post_residual % 25 == 0);
    if harmonic {
        score -= 30.0 + 0.5 * post;
    } else {
        // Odd dead space penalized more when small (unusable).
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 120.0;
        // If item nearly fills a fresh bin, opening is fine.
        if item_size as f64 > 0.8 * cap {
            score -= 150.0;
        }
        // Early in stream with few bins, opening new bins is cheaper.
        if open_bins_count > 8 {
            score += 40.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 60.0 + 80.0 * tight;
        } else {
            // next item won't fit here: mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Prefer filling bins below mean residual (tighter bins get priority).
    score += (post - mean_residual) * 0.5;

    // Progress coupling: late in stream, be more aggressive at closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - frac);

    // Integer-division threshold on post_residual classes.
    let cls = post_residual / 20; // 0,1,2,3,4,5
    score += match cls {
        0 => 40.0,           // tiny dead space
        1 => 0.0,
        2 => -10.0,
        3 => -20.0,
        _ => -25.0,          // roomy residual, still reusable
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use are wasted.
    // Penalize small unusable gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0; // dead space < min item size
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small even for the lookahead item: heavy penalty scaled by gap uselessness
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.05;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * 0.6 + progress * 5.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins exist and can consolidate.
        score += 40.0 + pressure;
    } else {
        score -= pressure * 0.3;
    }

    // Slight preference for bins already below mean residual (balance spreading).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
