pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fits preferred; penalize large dead space non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Lookahead: if the next item fits in the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            score += 10.0 * (next_item_size - post_residual.min(next_item_size)) as f64 / bin_capacity as f64;
        }
    }

    // Last chance: strongly favor using this bin if it's the only one that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Global state: many open bins -> prefer filling existing ones; few -> allow new bins.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 8.0 * crowding;

    // Mean residual coupling: prefer bins whose residual is below average (consolidate large gaps).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 25.0 * dev;

    // New-bin candidate: only attractive when current bin residuals are poor for the item.
    if bin_residual == bin_capacity {
        let waste_elsewhere = mean_residual.max(0.0) / bin_capacity as f64;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bonus = 30.0 * waste_elsewhere + 50.0 * poor_fits
            - (post_residual as f64 / bin_capacity as f64) * 20.0;
        // Early stream: opening bins is cheap; late stream: discourage.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 100.0 - bonus - 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * progress + 3.0 * p2 + 4.0 * p3);
    score += 12.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let gap = pr - mean_residual;
    score += 0.08 * gap * gap;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - ((pr - ni) / cap));
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: prefer it only when no good fit exists
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - progress) + norm_pr * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of capacity fractions.
    // Residuals that are "dead" (small, hard to fill) get penalized;
    // residuals in useful classes (multiples of common item sizes) get rewarded.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,           // perfectly divisible residual, very reusable
        1 | 2 => score += 8.0,        // nearly-full dead space, hard to reuse
        3 | 4 | 6 | 7 => score += 2.0,
        5 => score -= 4.0,            // half-class residual, moderately reusable
        _ => {}
    }

    // Integer-division thresholds on post_residual: classify into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else if pr < quarter / 2 {
        score += 10.0; // tiny unusable sliver
    } else if pr <= quarter {
        score -= 2.0;
    } else if pr <= half {
        score -= 6.0; // half-empty residual is valuable
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0;
        if slack % 10 == 0 {
            score -= 5.0; // next item leaves harmonic residual too
        }
        if slack == 0 {
            score -= 10.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post_residual cannot host next item: mild penalty scaled by how close it is
        let gap = (next_item_size - post_residual) as f64;
        score += (gap / 20.0).min(6.0);
    }

    // Last-chance bin: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score += 18.0 + 10.0 * progress - crowding.min(12.0);
        // If next item is large and won't fit anywhere anyway, new bin is fine.
        if next_item_size > 0 && next_item_size > bin_residual - item_size && fitting_bins_count <= 1 {
            score -= 8.0;
        }
    }

    // Prefer filling bins with larger residual (waste-aware): tie-break via mean residual.
    if (bin_residual as f64) > mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    // Late in stream: be greedier about closing bins tightly.
    if total_items > 0 && step_index as f64 / total_items as f64 > 0.8 {
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest item are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize residuals too small for the next item (dead space w.r.t. lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh space; encourage filling existing bins.
    let bin_pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += bin_pressure * 3.0;

    // Brand-new bin candidate: penalize mildly so it's only chosen when
    // open bins fit poorly (large dead space or last-chance alternatives exist).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        // But if the next item is large and this item is small, opening a
        // fresh bin preserves big residual for the future.
        if next_item_size > 50 && item_size < 30 {
            score -= 30.0;
        }
    }

    // Tight packing bonus: residual close to mean suggests consistent fill.
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score -= 0.5 / (1.0 + mean_diff);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // leftover after next item would be post_residual - next_item_size
            let after_next = (post_residual - next_item_size) as f64;
            // penalize residual that next item cannot use well
            score += after_next * 0.3;
            if after_next < 10.0 {
                score -= 50.0; // near-perfect chain
            }
        } else {
            // next item cannot fit in this bin's leftover: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    } else {
        // last item: just minimize post_residual
        score += 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Compare against mean residual: bins tighter than mean are precious, prefer filling loose bins
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.2;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 5.0;

    // Penalize creating tiny unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let avg_fragmentation = mean_residual / bin_capacity as f64;
        // base cost of a fresh bin
        let mut new_bin_score = 70.0;
        // if open bins are very fragmented, new bin becomes attractive
        new_bin_score -= avg_fragmentation * 120.0;
        // fewer fitting bins -> new bin more acceptable
        if fitting_bins_count <= 1 {
            new_bin_score -= 60.0;
        }
        // lookahead: a new bin can always host the next item
        if next_item_size > 0 {
            new_bin_score -= 20.0;
        }
        // early in stream, new bins are cheaper (more future items to amortize)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score -= (1.0 - progress) * 15.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space that the next item cannot use at all.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 4.0 * pressure;
    }

    // Time horizon: early in the stream, be slightly more willing to spread items
    // (more future items to pack); later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: make the empty bin attractive only when it
    // yields a very flexible remainder (large enough for the next item) or when
    // existing fits are poor.
    if bin_residual == bin_capacity {
        let flexible = next_item_size > 0 && post_residual >= next_item_size;
        if flexible {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth non-linear waste penalty: dead space grows superlinearly
    score += 60.0 * pr_norm * pr_norm * (1.0 - pr_norm);

    // Coupling of post_residual with stream progress: late in the stream,
    // small residuals become more valuable to fill (tighten penalty).
    score += 80.0 * pr_norm * pr_norm * progress;

    // Reward high fill ratio smoothly
    score -= 40.0 * fit_norm * fit_norm;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize leaving awkward gaps
        score += 10.0 * pr_norm * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer existing bins unless they'd leave tiny dead space;
        // penalize opening a new bin more as the stream matures.
        score += 15.0 + 35.0 * progress;
        // But if item is huge relative to capacity, opening is fine
        score -= 25.0 * fit_norm * fit_norm;
    }

    // Mild pressure from many open bins: encourage consolidating into them
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean-residual coupling: if this bin's post residual is below the mean,
    // it's a tighter fit; reward it smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev - 8.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on coarse
    // capacity fractions (multiples of 25) are "clean" and reusable.
    let cap25 = bin_capacity / 4;
    let cap50 = bin_capacity / 2;
    let harmonic_bonus = if post_residual == 0 {
        -60.0 // perfect fill: best possible outcome
    } else if post_residual % cap50 == 0 {
        -30.0
    } else if post_residual % cap25 == 0 {
        -18.0
    } else if post_residual < 10 {
        25.0 // tiny dead space, nearly unusable
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division class of post_residual: how many items of the next
    // size class could still fit? Reward bins that can host the lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits_next = post_residual / next_item_size;
        score -= 8.0 * fits_next.min(3) as f64;
    } else if next_item_size > 0 {
        // next item cannot follow here; penalize proportionally to waste
        score += 6.0;
    }

    // Modular threshold on post_residual vs next_item_size: exact co-fill
    // (post_residual == next_item_size) is a perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 22.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a bin is only attractive when the item is
    // large relative to capacity or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // penalize new bin more when existing bins are roomy (high mean residual)
        score += 55.0 + 40.0 * fragmentation + 20.0 * (1.0 - progress);
        // but allow new bin for huge items that would wreck a good bin
        if item_size * 4 >= bin_capacity * 3 {
            score -= 30.0;
        }
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 15.0;
    } else if fill_ratio < 0.3 && bin_residual != bin_capacity {
        score += 10.0; // wasting a large residual on a tiny item
    }

    // Mild preference to keep open-bin count low late in the stream.
    score += 0.4 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (low post_residual, especially zero).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 900.0; // perfect 2-chain
        } else if (diff as u32) <= 5 {
            score -= 350.0;
        } else if (diff as u32) <= 10 {
            score -= 120.0;
        } else if next_item_size > post_residual {
            // next item won't fit here: residual is dead space relative to lookahead
            score += 40.0 + 0.5 * post_residual as f64;
        } else {
            score += 0.3 * diff as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are preferred for large items.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.4 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize leaving large dead space early in the stream when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 30 && progress < 0.5 {
        score += 0.6 * (post_residual as f64 - 30.0);
    }

    // New-bin candidate: only attractive when it enables a good lookahead chain
    // (empty bin => post_residual == capacity - item).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 250.0;
        } else {
            score += 120.0 + 0.2 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is nearly consumed.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: small post_residual is good, but mid-range gaps are worst.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score -= 8.0; // near-perfect fill
        } else if gap < item_size as f64 {
            // gap too small for typical items: dead space penalty scaled by gap
            score += 0.6 * gap;
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * chain_fit;
        } else {
            // next item won't fit here: slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over.min(40.0);
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= 30.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer using open bins when the fit is decent; open new bin only
        // when item is large relative to typical residual or few bins fit.
        let pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 30.0 * pressure - 40.0 * scarcity - 10.0 * progress;
        // If mean residual across open bins is large, open bins can absorb items.
        score += 0.25 * mean_residual.min(80.0);
    } else {
        // Using an existing bin reduces bin count pressure; reward more when many bins open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild global dispersion term: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual bins are more "committed").
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Progress-scaled exploitation: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, reward quadratically
    let pr = post_residual as f64;
    score -= (1.0 - pr / bin_capacity as f64).powi(4) * 30.0;

    // Penalize dead space that no future item can plausibly use
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 25.0 * (1.0 - pr / bin_capacity as f64);
        }
        // Reward bins whose post_residual exactly matches next item
        if post_residual as u32 == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: minimize post residual strongly
        score += pr * 0.5;
    }

    // Last-chance bin bonus: only fitting bin should be strongly preferred over opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Smooth non-linear coupling with stream progress: later in stream, tighten more
    let tightness = (pr / bin_capacity as f64).powi(2);
    score += tightness * (10.0 + 30.0 * progress);

    // Mild penalty when bin residual far from mean residual (fragmentation signal)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).powi(2) * 5.0;

    // Slight preference for consolidating into fewer bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * progress * 0.5;

    // New-bin candidate: penalize opening a new bin unless item is large relative to residual pattern
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
        // late stream: opening new bins is cheaper than fragmenting
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes based on integer division thresholds.
    // Residual classes: [0..9] perfect, [10..19] good, [20..34] ok, [35..49] poor, [50+] terrible.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -30.0
    } else if pr <= 9 {
        -15.0
    } else if pr <= 19 {
        -5.0
    } else if pr <= 34 {
        0.0
    } else if pr <= 49 {
        12.0
    } else {
        25.0
    };
    score += class_penalty;

    // Modulo-10 harmonic class: residuals divisible by 10 align with typical item granularity.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }
    // Residuals in awkward mid-band (mod 10 in 6..9) are harder to fill.
    let m = pr % 10;
    if m >= 6 && m <= 9 && pr > 0 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // reward proportionally to how well next item fills the leftover
            let fill = next_item_size as f64 / (pr as f64 + 1.0);
            score -= 10.0 * fill;
            // penalize leaving a tiny unusable sliver after next placement
            let post2 = pr - next_item_size;
            if post2 > 0 && post2 < 10 {
                score += 6.0;
            }
        } else {
            // next item won't fit here: leftover becomes dead space until later
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins (tight fits): reward small post_residual relative to capacity.
    score -= (1.0 - pr as f64 / cap) * 5.0;

    // Progress factor: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (cap - pr as f64) * 0.05;

    // Bin-count pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.3;

    // Mean residual alignment: if this bin's residual is far above mean, it's a poor filler target.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: make it attractive only when item fits poorly anywhere.
    // Base new-bin score ~ residual capacity minus a fixed opening cost.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // = post_residual for fresh bin
        score += 18.0; // opening cost
        if next_item_size > 0 && next_item_size <= pr {
            score -= 8.0;
        }
        if fitting_bins_count == 1 {
            score += 25.0; // discourage new bin when an existing bin is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< min item size 1..100 -> treat <10) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open bins pressure: when many bins are open, prefer filling existing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual != bin_capacity {
        score -= pressure * 3.0;
    } else {
        // New-bin candidate: penalize when open bins exist and can fit the item
        if fitting_bins_count > 0 {
            score += 8.0 + pressure * 4.0;
        }
        // Slight reward for new bin late in stream if residuals are fragmented
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap just slightly larger than the next item (wasteful)
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 5 {
        score += 6.0;
    }

    // Mild preference for bins with residuals close to mean (balance residuals)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 30.0 * (-post_residual as f64 / 10.0).exp();

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the post residual,
    // this is a perfect pair — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Next item fits: penalize proportional to leftover dead space after both.
            let after_next = post_residual - next_item_size;
            score += 0.6 * after_next as f64;
            // Bonus if after-next residual is small but nonzero.
            if after_next <= 10 {
                score -= 80.0;
            }
        } else {
            // Next item cannot fit here; penalize bins that leave a gap
            // slightly larger than next_item_size (unusable for it).
            let gap = post_residual as f64;
            if gap >= next_item_size as f64 * 0.9 && gap <= next_item_size as f64 * 1.5 {
                score += 120.0;
            }
            score += 0.4 * gap;
        }
    }

    // Compare post residual against mean residual of open bins:
    // leaving less than average waste is good.
    score -= 2.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin early in the stream when open bins exist,
    // but allow it late when consolidation is less valuable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0 - 100.0 * progress;
        // If no other bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for filling bins with larger residuals when many bins open.
    score += 0.1 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary tightness term: reward small post residual non-linearly.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 40.0 * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: penalize proportionally to dead space created.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last chance: this is the only bin that fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let badness = (item_size as f64 / bin_capacity as f64).powi(2);
        score += 55.0 + 30.0 * badness;
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Late in the stream, opening fresh bins wastes residual; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state coupling: prefer bins below mean residual (more crowded bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild preference for bins with small absolute residual when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), softened early.
    let mut score = pr * (0.6 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling: post-residual interacts with stream progress.
    // Late in the stream, tight fits matter more; early, we tolerate slack.
    let progress_coupling = norm_pr * (1.0 - progress) * (1.0 - progress);
    score -= 18.0 * progress_coupling;

    // Reward filling bins nearly exactly, scaled by progress.
    let exactness = 1.0 - (pr / cap).powf(2.0);
    score -= 12.0 * exactness * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if the next item fits the post-residual exactly, reward.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = 1.0 - gap / cap;
        score -= 10.0 * fit_next.max(0.0) * fit_next.max(0.0);
    }

    // Penalize bins far below the mean residual (fragmented bins), smooth term.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for proliferating bins late in the stream.
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when this placement would waste a lot.
    if bin_residual == bin_capacity {
        score += 8.0 - 14.0 * norm_pr * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of common
    // item sizes (10..=80 grid) are more likely to be filled later.
    let post = post_residual;
    if post > 0 {
        // residue distance to nearest multiple of 10 (harmonic grid)
        let r10 = (post % 10) as f64;
        let d10 = r10.min((10 - r10) as f64);
        score -= 6.0 * (1.0 - d10 / 5.0); // reward near-multiples of 10
        // residue distance to nearest multiple of 20 (coarser harmonic class)
        let r20 = (post % 20) as f64;
        let d20 = r20.min((20 - r20) as f64);
        score -= 4.0 * (1.0 - d20 / 10.0);
        // tiny residues are excellent (near-perfect fit)
        if post <= 5 {
            score -= 15.0;
        } else if post <= 10 {
            score -= 7.0;
        }
        // dead-space penalty: residual that no plausible item can use
        // (items >= 10, so residual < 10 is stranded unless it is 0)
        if post < 10 {
            score += 12.0 * (1.0 - post as f64 / 10.0);
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Integer-division thresholds on post_residual vs next item (lookahead k=2)
    if next_item_size > 0 {
        if post >= next_item_size {
            // this bin can also serve the next item: reward, scaled by how
            // tightly the next item will fit afterwards
            let post2 = post - next_item_size;
            score -= 8.0;
            if post2 < 10 && post2 > 0 {
                score -= 5.0; // double near-perfect packing
            }
        } else {
            // post-residual cannot host next item; penalize proportionally
            let waste_ratio = next_item_size as f64 / post.max(1) as f64;
            score += 4.0 * waste_ratio.min(4.0);
        }
        // harmonic class match between post-residual and next item size class
        let class = |x: u32| x / 20; // coarse size class: 0..4
        if class(post.min(100)) == class(next_item_size.min(100)) {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.05);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 55.0
            - 10.0 * (item_size as f64 / bin_capacity as f64) // big items like fresh bins
            - 15.0 * progress
            - if next_item_size > 0 && next_item_size >= post_residual { 6.0 } else { 0.0 };
        // penalize new bin when plenty of slack exists in open bins
        let slack = (mean_residual - item_size as f64).max(0.0);
        score = base + 0.5 * slack + 0.02 * crowded;
        if post_residual == 0 {
            score -= 20.0; // fresh bin will be exactly filled
        }
    }

    // Slight preference for tighter bins generally (small residual before placement)
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64).max(0.0) * 0.0;

    // Mild tie-break: prefer bins whose residual is an integer-division
    // multiple class of the item size
    if bin_residual > 0 {
        let q = bin_residual / item_size.max(1);
        if q >= 1 {
            score -= 1.0 + q as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold even the smallest plausible item are worthless.
    if post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item can't use this gap: mild penalty proportional to wasted gap
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure to consolidate when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residuals close to the mean (keeps bin population balanced).
    score += 0.10 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: opening a fresh bin should only win when current fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // cheaper to open a bin early in the stream or when next item is large
        if next_item_size >= 60 {
            score -= 15.0;
        }
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward scaled by tightness.
            score -= 40.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // Next item won't fit: penalize dead space left behind.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward bins tighter than the mean residual (good fits), penalize loose ones.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize the new-bin candidate so we only open bins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if the item is huge relative to capacity and no good fit exists, opening is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidation matters more: favor filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: low post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward near-perfect fits (small leftover) with a bonus.
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 18.0 / (1.0 + chain_fit);
    }
    // If next item is too big for post-residual, mild penalty for wasting chain potential.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the fit in existing bins is poor. Penalize the empty bin moderately,
    // less so early in the stream or when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0
            - 25.0 * progress
            + 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // If mean residual across open bins is high (lots of scattered space),
        // discourage opening yet another bin.
        score += (mean_residual / bin_capacity as f64) * 30.0;
    }

    // Mild penalty for placing into bins with residuals much larger than the item
    // when other bins might use that space better (fragmentation guard).
    if bin_residual < bin_capacity {
        let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * waste_ratio;
    }

    // Slight preference for bins whose residual is close to the mean residual
    // (keeps the pool of open bins homogeneous, easier to combine later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills mildly; late in stream, reward tight fills strongly.
    let tightness = 1.0 - pr; // fraction of bin used by this placement
    let coupling = (0.5 + 2.5 * progress * progress) * tightness * tightness;
    score -= 40.0 * coupling;

    // Penalize large residual quadratically (dead space grows worse quadratically).
    score += 0.02 * post * post / cap;

    // Smooth interaction: residual vs mean residual deviation.
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bin bonus (smooth via fitting count).
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item (smooth logistic-like term).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let fit_next = (post - next).max(0.0);
        let room = 1.0 / (1.0 + (-6.0 * (fit_next / cap - 0.05)).exp());
        score -= 15.0 * room * (0.5 + 0.5 * progress);
    }

    // Slight preference for consolidating among many open bins.
    score += (open_bins_count as f64).ln() * (1.0 - tightness) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: residues near multiples of 25 are "good"
    let r = (post_residual % 25) as f64;
    let harmonic_bonus = if r == 0.0 {
        12.0
    } else if r <= 5.0 || r >= 20.0 {
        6.0
    } else {
        -4.0 * (r / 12.5)
    };
    score -= harmonic_bonus;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - post / cap;
    score -= 20.0 * tightness * tightness;

    // Lookahead: strongly reward if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 15.0 * snug;
        } else {
            // next item won't fit here: penalize large dead space
            score += 0.10 * post;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit is very poor
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - post / cap; // = item_size / cap
        score += 18.0 * (1.0 - fit_quality);
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Progress-based mild exploration of mean residual alignment
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post > mean_residual {
        score += 3.0 * (1.0 - progress);
    } else {
        score -= 2.0 * progress;
    }

    // Penalize very large unusable residuals (dead space classes)
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small slivers are fine, nearly perfect fill
    }
    if post_residual >= 60 {
        score += 6.0; // large dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        // Define "unusable" relative to the next item's size (lookahead-aware).
        let min_useful = if next_item_size > 0 { next_item_size.min(item_size) } else { 10 };
        if post_residual < min_useful {
            // The gap cannot fit the next item -> dead space penalty, worse the smaller it is.
            let deadness = 1.0 - (post_residual as f64 / min_useful.max(1) as f64);
            score += 12.0 * deadness + 6.0;
        }
        // Smooth quadratic waste term: small residuals are disproportionately bad.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64 * 2.0);
    } else {
        // Perfect fit: strong reward.
        score -= 20.0;
    }

    // Reward bins whose leftover can host the lookahead item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Favor leaving a residual close to next_item_size (chained fit).
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty so lookahead-friendly bins win ties.
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight packing
    // into existing bins (i.e., penalize the new-bin candidate implicitly via others).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(10.0);
    } else {
        // New-bin candidate: penalize it, more so as open bins accumulate.
        score += 6.0 + pressure;
        // But late in the stream with fragmented residuals, allow opening fresh bins.
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 3 {
            score -= 10.0;
        }
    }

    // Prefer bins tighter than the mean residual (fill the emptiest useful bins first
    // keeps large holes available for large future items).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead matching against next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // next item will perfectly fill this bin: excellent
            score -= 600.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here: mild reward scaled by slack
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 2.5;
        }
    }

    // Waste penalty: large leftover space is bad
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive if the item is small
    // (leaves a versatile residual) or existing fits are poor
    if bin_residual == bin_capacity {
        let versatility = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 180.0 - versatility * 220.0;
        // late in the stream, discourage opening new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 100.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 12.0;
    } else {
        score += 12.0;
    }

    // Prefer filling existing bins when many are open
    score -= open_bins_count as f64 * 3.0;

    // General stream progression: fill bins more aggressively over time
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving a residual that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: with many open bins, prefer consolidation into existing space.
    score += 0.4 * open_bins_count as f64;

    // Divergence from mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be conservative about filling bins;
    // later, squeeze aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * fit_ratio;

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 45.0 * scarcity + 10.0;
        // Late in the stream, closing out bins matters more; still keep new bins costly.
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Tight fits become progressively more valuable as the stream advances
    score -= (1.0 - pr_norm) * (1.0 + 2.0 * progress + 4.0 * p2 + 3.0 * p3) * 10.0;

    // Penalize dead space non-linearly (quadratic in wasted capacity), stronger late
    score += pr_norm * pr_norm * (1.0 + 3.0 * progress) * 15.0;

    // Cubic interaction: near-exact fills (post_residual small) get a cubic boost
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * 20.0;

    // Last-chance bin: reward strongly with smooth progress modulation
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: favor bins whose post_residual can still host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 5.0 * (1.0 - (pr - n) / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Discourage spreading across many open bins when residuals are already small
    let mr = mean_residual / bin_capacity as f64;
    score += (open_bins_count as f64).ln() * mr * 3.0;

    // New-bin candidate: prefer opening a fresh bin only when no tight fit exists
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress - (1.0 - pr_norm) * 0.0;
        if fitting_bins_count == 1 {
            score += 30.0; // strongly avoid abandoning the only fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let post_frac = post_f / cap_f; // 0..1

    // Dead-space penalty: residuals in "awkward" harmonic bands are hard to fill.
    // Bands: (0,0.1) near-perfect; (0.1,0.2) good; (0.2,0.5) awkward; (0.5,1) reusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_frac < 0.2 {
        score -= 5.0;
    } else if post_frac < 0.5 {
        // awkward dead zone: penalize modulo-class residue
        let r = post_residual % 10;
        score += 12.0 + (r as f64) * 0.8;
    } else {
        score -= 8.0; // large residuals remain reusable
    }

    // Lookahead compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact chaining
        } else if next_item_size <= post_residual {
            // harmonic class match via integer division
            let cls_next = next_item_size / 10;
            let cls_post = post_residual / 10;
            if cls_next == cls_post {
                score -= 15.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot fit here: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + gap * 0.05;
        }
    } else {
        // last item: prefer filling tightly
        score += post_frac * 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; only attractive
    // when the item fits poorly everywhere else. New bin has post_residual == capacity - item.
    if bin_residual == bin_capacity {
        // penalize new bins unless current open bins are very full (low mean residual)
        let pressure = (mean_residual / cap_f).recip(); // grows as mean residual shrinks
        score += 20.0 + 15.0 / pressure.max(0.05) + (open_bins_count as f64) * 0.5;
    }

    // Stream progression: late in the stream, tighten packing (favor small post_residual more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_frac * (5.0 + 10.0 * progress);

    // Mild reward for balancing: bins below mean residual are good targets
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (<10) are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 5.0;
    }

    // Lookahead: penalize bins whose residual cannot host the next item,
    // scaled by how badly it misses.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly
    // prefer it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: mild penalty so a fresh bin is only chosen when
    // every open bin offers a poor fit. Pressure grows with open_bins_count
    // to discourage bin proliferation.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 0.5;
    }

    // Gentle open-bins pressure: prefer consuming residual of bins that are
    // already open, weighted by relative fill.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.01 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness);

    // 2-step lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted space.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 10.0 * (overshoot / bin_capacity as f64);
        }
    }

    // Penalize creating dead space below the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (fill emptier-but-usable bins first
    // keeps tight bins for tight items); mild coupling to mean residual.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize unless current bin would leave large unusable space.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of fit: reward near-exact fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that is hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the known next item: penalize.
        score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidation.
    let pressure = mean_residual / bin_capacity as f64;
    score += 10.0 * pressure * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, tolerate opening new bins; late, consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly as stream progresses.
        score += 25.0 * (0.3 + 0.7 * progress);
        // But if item is large and no open bin is tight, opening is fine.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 10.0;
        }
    } else {
        score -= 8.0 * progress * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth interaction: as the stream progresses, prefer tighter fits (low post_residual) more strongly.
    score += 30.0 * progress * pr_norm * item_norm;

    // Cubic coupling term: dead space becomes increasingly costly late in the stream.
    score += 40.0 * progress * progress * pr_norm * pr_norm * pr_norm;

    // Penalize bins whose residual deviates from the mean residual (prefer balanced packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Reward bins that can also fit the lookahead item (smooth sigmoid-like gate on post_residual vs next item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0) / cap;
        score -= 25.0 * fit_next * (1.0 - progress);
    } else {
        // Last item: strongly prefer minimizing post_residual.
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - pr_norm * pr_norm);
    }

    // Mild penalty for proliferation of open bins when post_residual is large (wasteful spread).
    score += 0.5 * (open_bins_count as f64).ln() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // classes (divisible by small sizes / large enough for future items) are rewarded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize tiny dead space (waste), reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual >= 90 {
        // Nearly-empty bin used for a small item: wasteful
        score += 15.0;
    }

    // Modulo arithmetic: leftover compatible with common item sizes is reusable.
    let reusable = |r: u32| -> bool {
        (r % 10 == 0) || (r % 20 == 0) || (r % 25 == 0) || (r % 50 == 0)
    };
    if reusable(post_residual) {
        score -= 6.0;
    }

    // Lookahead: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain placement possible: reward proportionally to how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack * 0.08;
            if reusable(post_residual - next_item_size) {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: this residual becomes dead space until later
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in stream, opening new bins is cheap; later, consolidate.
    score += progress * 3.0;

    // New-bin candidate: neutral-ish but slightly penalized so we reuse when fit is decent.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps smaller than the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits (small but usable waste is good)
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize large leftover if it's awkward relative to typical items
    let awkward = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * awkward;

    // Last fitting bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: add base penalty scaled by open-bin pressure
        score += 10.0 + 2.0 * pressure;
    } else {
        // Slight reward for using existing bins, stronger with more open bins
        score -= pressure.min(8.0);
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Dead space that the next item cannot use at all
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
