pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 1.5 * fill_ratio * (bin_residual as f64);
    }

    // Penalize small dead space that likely becomes unusable (post_residual < 10).
    if post_residual < 10 {
        score += 8.0;
    } else if post_residual <= 20 {
        score += 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 18.0;
        } else if slack < 10 {
            score -= 6.0;
        }
        // Penalize if next item would be stranded by a big leftover
        if next_item_size > post_residual && post_residual < 10 {
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be more open to spreading (keep flexibility);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Global state coupling: many open bins with high mean residual -> prefer filling
    // existing bins to avoid bin proliferation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 1.0 + 0.02 * open_bins_count as f64;
    }
    // Low mean residual (bins nearly full): slightly prefer new bin if fit is poor.
    if mean_residual < item_size as f64 * 0.5 && post_residual > 30 {
        score += 3.0;
    }

    // Mild penalty for leaving residual in a band that rarely fits future items (11..19).
    if post_residual >= 11 && post_residual <= 19 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress
    score -= 12.0 * (norm_pr * norm_pr) * (0.5 + 0.5 * progress);
    score -= 8.0 * (norm_pr * (1.0 - norm_pr)) * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    score -= 20.0 * norm_item * (1.0 - norm_item).powi(2) * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot hold the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (pr - norm_next * cap).max(0.0) / cap;
        score += 15.0 * gap * gap * (0.5 + 0.5 * progress);
        // Reward leaving exactly room for the lookahead item
        let fit_next = (norm_next * cap <= pr) as i32 as f64;
        score -= 6.0 * fit_next * norm_next * (1.0 - progress);
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 10.0 * scarcity * norm_item;

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Pull toward mean residual to balance bin loads
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into 10-wide residue bands.
    let class = post_residual / 10;
    // Dead-space penalty grows super-linearly for small unusable leftovers.
    if post_residual < 10 {
        score -= 25.0; // perfect/near-perfect closure is excellent
    } else if post_residual < 20 {
        score -= 8.0;
    } else {
        // penalize large leftover bands that few items can still use
        score += 0.15 * (class as f64).powi(2);
    }

    // Reward if the lookahead item exactly fits the post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial credit scaled by how much would remain after the chain
            let chain_left = post_residual - next_item_size;
            score -= 12.0 - 0.2 * chain_left as f64;
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it is
    // chosen only when open-bin fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer filling bins whose residual is far below the mean (tight bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Modulo-100 harmonic nudge: exact fill classes.
    if bin_capacity % 10 == 0 && post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;

    // ---- New-bin candidate: make it expensive so it only wins when
    // ---- every open bin offers a truly bad fit.
    if is_new_bin {
        // Base cost of opening a bin, scaled by how wasteful this item is in it.
        let mut new_score = bin_capacity as f64 * 1.5 + item_size as f64 * 0.35;
        // If this is the ONLY candidate that can fit the item, we must open anyway:
        // soften the cost so it reliably beats nothing else (no other candidates exist,
        // but keep it well below any "reject" semantics).
        if fitting_bins_count <= 1 {
            new_score -= 120.0;
        }
        // Slight discount late in the stream when many bins are already open
        // (consolidation pressure diminishes; avoid hoarding residuals forever).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_score -= progress * 10.0;
        return new_score;
    }

    // ---- Existing-bin scoring: strict dead-space avoidance.
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small to host the lookahead item
    // are likely to become permanent waste. Penalize them super-linearly.
    let next_fits = next_item_size > 0 && next_item_size <= post_residual;
    if !next_fits {
        // Gap unusable by the lookahead: penalize proportionally to how
        // "stranded" the residual is (small gaps are worst).
        let dead = post_residual as f64;
        score += dead * dead * 0.05;
    } else {
        // Reward a chainable residual: the next item can slot in right after.
        score -= 12.0 + next_item_size as f64 * 0.25;
    }

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only open bin that fits, prefer it
    // strongly over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure proportional to the number of open bins: with many bins
    // open, consolidating into existing residual capacity is more valuable.
    score += open_bins_count as f64 * 0.4;

    // Contextual term: if the bin's residual is far below the mean residual,
    // it is already "used up"; finishing it is good. If it is far above the
    // mean, consuming it now may strand a large gap elsewhere.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward perfect next-item fit
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64 * 0.5)).max(0.0);
        // exact match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // penalize leaving a large unusable gap for next item
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // relative to mean residual: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // penalize very small dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // mild penalty for opening a new bin when open bins exist that fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 20.0 + 0.3 * item_size as f64;
    }

    // late in stream: prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here: mild penalty proportional to overflow.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins for poor fits);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_bias = 0.5 + 0.5 * progress;
    score -= fill_bias * (mean_residual - post_residual as f64).abs() * 0.2;

    // Penalize opening new bins when many bins are already open and one fits well.
    if bin_residual == bin_capacity {
        let best_alt = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 30.0 * best_alt * (1.0 - tightness.max(0.0)) + 10.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, tighter fills (small post_residual) are rewarded more strongly.
    let norm_pr = pr / cap;
    score -= norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap * 0.5;

    // Penalize large leftover dead space super-linearly as stream advances.
    score += norm_pr * norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward near-perfect fills (post_residual close to 0) with a smooth bump.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * 8.0 * (0.5 + progress);

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (1.0 - pr / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to wasted potential
        score += 2.0 * (next_item_size as f64 - pr) / cap * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this placement leaves fragmented space.
    let frag = (pr - mean_residual).abs() / cap;
    score += frag * frag * open_bins_count as f64 * 0.3;

    // New-bin candidate: keep it moderately attractive early, less so late.
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by residue mod 10
    let residue = post_residual % 10;
    // Dead space penalty: small nonzero residues are the least reusable
    if residue > 0 && residue < 5 {
        score += 6.0;
    } else if residue >= 5 && residue < 10 {
        score += 2.5;
    }
    // Perfect fit: reward strongly
    if post_residual == 0 {
        score -= 40.0;
    }
    // Post-residual exactly matches next item: reward lookahead harmony
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item cannot fit in this leftover; leftover is likely dead space
            score += 8.0;
        }
        // Integer-division class coupling: leftover divisible by next item is good
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty for consuming scarce-fit bins
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    // Early stream: prefer filling existing bins tightly; late stream: tolerate slack
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // Prefer bins below mean residual (tighter bins first)
    score += 0.15 * (post_residual as f64 - mean_residual);

    // New-bin candidate: penalize unless current fit is very poor
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // opening fresh is attractive only if item is huge relative to capacity
        let huge = (item_size as f64 / bin_capacity as f64) > 0.7;
        if huge && next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        } else {
            score += 20.0 + 0.3 * waste;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // tiny gaps punished hardest
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If next item fits exactly into the post residual, big reward (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid wasting residual capacity;
    // with few open bins, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins whose residual is close to mean (balanced packing) when tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for filling fuller bins (smaller bin_residual) as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0 * (0.5 + progress);

    // New-bin candidate: only attractive when no open bin is decent.
    if bin_residual == bin_capacity {
        let decent_exists = mean_residual >= item_size as f64 + 5.0;
        if decent_exists && open_bins_count > 0 {
            score += 30.0; // discourage opening new bin when a decent fit exists
        } else {
            score -= 5.0; // mildly prefer fresh bin over creating dead space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        // Perfect two-step match: this bin's post residual exactly fits the next item.
        if post_residual as f64 == next {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Post residual still usable by next item: reward closeness to exact match.
            let slack = post_residual as f64 - next;
            score -= 30.0 * (1.0 - slack / (next + 20.0));
        } else {
            // Dead space: post residual can't hold the next item -> penalize proportionally.
            score += 1.5 * (next - post_residual as f64);
        }
        // Bonus when next item would fit *exactly* into post residual even if not equal (small sizes).
        if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize leftover space.
        score += 0.0;
    }

    // Relative-to-mean-residual coupling: prefer bins whose post residual is below the mean
    // (compact bins), penalize leaving large residuals relative to average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit is poor
    // (large post residual dead space or next item can't fit anywhere).
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual < next_item_size;
        if poor_fit {
            score -= 25.0; // opening a new bin is reasonable
        } else {
            score += 35.0; // discourage wasting a fresh bin on a decent fit
        }
    }

    // Slight preference to fill bins earlier in the stream (keeps open bin count low).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 + progress * progress * 3.0);
    score += coupling * cap * 0.5;
    // Penalize large dead space quadratically, stronger late in stream
    score += norm_pr * norm_pr * cap * (0.5 + progress);
    // Reward tight fits (small post_residual) with smooth decay
    score -= (1.0 - norm_pr).powi(3) * cap * 0.3;
    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= cap * 0.4 * (1.0 - progress);
    }
    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= (pr - nxt).min(pr) * 0.2;
        }
    }
    // Mild penalty for proliferating bins relative to mean residual
    score += (open_bins_count as f64) * (mean_residual / cap).powi(2) * 2.0;
    // New bin candidate: prefer it only when all open residuals are poor
    if bin_residual == bin_capacity {
        score -= mean_residual * 0.5;
        score += cap * 0.1 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: multiples of 10 are "clean" slots
    let cls = post_residual % 10;
    score += match cls {
        0 => -6.0,                      // perfect decade residual, reusable
        1 | 9 => 2.0,
        2 | 8 => 3.0,
        3 | 7 => 4.0,
        4 | 6 => 5.0,
        _ => 6.0,                       // cls 5: worst dead space
    } * (1.0 + (cls as f64) / 10.0);

    // Integer-division thresholds on post_residual
    if post_residual == 0 {
        score -= 25.0;                  // perfect fit
    } else if post_residual < 10 {
        score += 12.0;                  // unusable sliver
    } else if post_residual / 10 >= 4 {
        score -= 4.0;                   // large reusable block (>=40)
    }

    // Lookahead: does next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // harmonic bonus if next_item lands on a decade too
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless residual would be badly fragmented
    if bin_residual == bin_capacity {
        score = cap - (item_size as f64); // baseline = post_residual of fresh bin
        if open_bins_count > 0 && mean_residual > (next_item_size as f64) {
            score += 20.0;              // an open bin already fits the next item
        }
        if post_residual % 10 != 0 {
            score += 4.0;
        }
    }

    // Slight preference for tighter bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Chain bonus: if next item fits perfectly after this, strongly prefer.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual slightly below next item (unusable wedge).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize tiny dead space that nothing (min size 1) could use well relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins with residual below mean (tighter packing), reward filling above-mean bins.
    if (bin_residual as f64) > mean_residual {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is very poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * item_size as f64;
        // Early in stream, new bins are cheap; late in stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Reward near-full fills.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space below
    // the smallest plausible item (<=10) is worthless; dampen that.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // partial reward proportional to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill;
        } else {
            // next item won't fit here: slight penalty if we leave large awkward gap
            if post_residual > 0 && post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter ones (already via post_residual)
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (penalize cramming); late in stream, conserve bins (favor existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bonus = 30.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus small early-stream discount.
        score += 55.0 - new_bin_bonus;
        // If next item is large and current item is large, opening fresh bin
        // can be good (pair two large items).
        if next_item_size >= item_size && item_size >= 40 {
            score -= 45.0 * (1.0 - progress);
        }
    } else {
        // Existing bin: late-stream conservation reward.
        score -= 15.0 * progress;
    }

    // Global state: many open bins with slack -> prefer filling them (avoid
    // fragmentation); few open bins -> opening new bins is cheaper.
    if open_bins_count > 3 {
        score -= 8.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: if this bin's residual is far below the mean
    // (it's the tightest), reward it; if far above, penalize.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Prefer bins whose residual is close to item_size (near-perfect fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, smoothly warped by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear penalty for small post-residuals (dead space), stronger late in stream.
    score += (1.0 - norm_pr) * (1.0 - norm_pr) * 30.0 * (0.5 + 0.5 * progress);

    // Cubic coupling of post_residual with progress: prefer tight fits as stream ends.
    score -= progress * norm_pr * (1.0 - norm_pr) * 20.0;

    // Lookahead: reward leaving room for the next item via smooth interaction.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_after = (pr - nx).max(0.0) / cap;
        score -= 15.0 * fit_after * (1.0 - progress);
        score += 10.0 * (1.0 - fit_after) * progress;
    }

    // Last-chance bonus: only fitting bin -> strong reward.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Slight preference for bins below mean residual (balance residuals) with smooth coupling.
    score += 0.1 * (mean_residual - pr) * (1.0 + progress);

    // Mild penalty for opening new bins when many bins are open, decaying with progress.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes mod 10
    let class = post_residual % 10;
    let dead_penalty = match class {
        0 => -6.0,          // perfect fill
        1 | 2 => 4.0,       // nearly-full but useless slivers
        3..=7 => 0.0,
        8 | 9 => 3.0,       // awkward large gap
        _ => 0.0,
    };
    score += dead_penalty;

    // Reward if next item fits exactly in post_residual (harmonic pairing)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 + 0.15 * slack;
        if post_residual == next_item_size {
            score -= 8.0; // perfect harmonic pair
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover space
        score += 3.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins have plenty of room
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * mean_residual;
        // but allow new bin if current item is large and mean residual tight
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Progress-scaled tightness preference: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Prefer bins whose residual is close to item (best-fit flavor)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual that is too small to ever fit a meaningful item is dead space.
    let min_useful = 10u32;
    if post_residual < min_useful {
        score += 40.0;
    } else if post_residual <= 25 {
        // Small gaps below the minimum item size range are likely dead.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to bin_residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Penalize leaving a gap just above the next item size (blocks future fit poorly),
    // reward if post_residual exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.3;
            if gap == 0 {
                score -= 15.0; // perfect chaining
            }
        } else {
            score += 8.0; // next item cannot reuse this bin
        }
    }

    // Open bins pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the fit here is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
    }

    // Slight preference to fill bins with larger residual as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - (post_residual as f64)).max(0.0) * 0.1;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin will be exactly filled next step
        } else if next_item_size <= post_residual {
            // next item fits, but leave some slack — mild bonus scaled by fit tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted post_residual that is too small to be useful
            let useless = post_residual as f64;
            score += 0.5 * useless * (1.0 - useless / bin_capacity as f64);
        }
    } else {
        // Last item: prefer filling an existing bin as tightly as possible
        score += 10.0;
    }

    // Compare post_residual against mean residual: avoid leaving residuals far below mean
    // (fragmentation) but also avoid hogging large residual bins with small items.
    let residual_dev = post_residual as f64 - mean_residual;
    score += 0.3 * residual_dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative to capacity
    // or no good chaining is possible in open bins.
    if bin_residual == bin_capacity {
        // Fresh empty bin: neutral base; penalize slightly so existing tight fits win,
        // but reward when item is big (hard to place later).
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += 15.0 - big_item_bonus;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // opening a fresh bin allows perfect 2-item packing
            score -= 20.0;
        }
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind, especially if it cannot fit the next item.
    if post_residual > 0 {
        if (next_item_size > 0 && post_residual < next_item_size) {
            score += 12.0;
        }
        // Dead space that is small relative to capacity is wasted space.
        if post_residual < 10 {
            score += 6.0;
        }
    }

    // Lookahead: reward bins whose leftover can host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins early and when plenty of usable space exists.
        score += 20.0 + 25.0 * (1.0 - progress) + 30.0 * pressure;
        if fitting_bins_count > 0 && fit_ratio > 0.8 {
            score += 25.0; // an excellent fit exists; strongly discourage new bin
        }
    }

    // Mild preference to fill bins that deviate below the mean residual (compact them).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Slight tie-break toward fewer open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small leftover space (non-linear quadratic coupling)
    let mut score = post * (1.0 + 1.5 * post_norm * post_norm);

    // Strongly reward near-perfect fits (dead-space avoidance)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0 * (1.0 - post_norm * 10.0);
    }

    // Smooth polynomial progress coupling: later in stream, tighter packing matters more
    score += post * (0.8 + 1.2 * progress * progress);

    // Lookahead: penalize if next item cannot use the post residual (smooth decay)
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= post;
        if fits_next {
            let waste = (post - next_item_size as f64) / cap;
            score -= 18.0 * (1.0 - waste * waste) * (1.0 - progress);
        } else {
            let gap = (next_item_size as f64 - post) / cap;
            score += 14.0 * gap * gap;
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Many open bins: discourage fragmenting further; prefer consolidation
    score += (open_bins_count as f64) * 0.35 * post_norm;

    // New-bin candidate: penalize unless residual would be very useful / fits are scarce
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let large_item_bonus = (item_size as f64 / cap).powi(2) * 30.0;
        score += 22.0 * (1.0 - 0.6 * progress) - scarcity * 30.0 - large_item_bonus;
        // if mean residual of open bins is high, opening new bin is wasteful
        score += (mean_residual / cap).max(0.0) * 25.0;
    }

    // Mean residual interaction: prefer bins below mean residual (tighter bins first)
    score += (post - mean_residual) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: classify leftover space into
    // capacity fractions. Leftovers in the "dead zone" (too small to hold
    // typical future items) are heavily penalized.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty via integer-division classes:
    // class 0: pr < eighth  -> nearly unusable
    // class 1: pr < quarter -> usable only by tiny items
    // class 2: pr < half    -> moderately usable
    // class 3: otherwise    -> good
    let class = if pr == 0 { 4 } else if pr < eighth { 0 } else if pr < quarter { 1 } else if pr <= bin_capacity / 2 { 2 } else { 3 };

    score += match class {
        4 => -50.0,                       // perfect fit: reward strongly
        0 => 45.0,                        // dead space
        1 => 18.0,
        2 => 0.0,
        _ => -6.0,                        // roomy leftover is fine
    };

    // Modulo arithmetic on post_residual: leftovers that are multiples of
    // small harmonic units (10/20) pair well with common item sizes.
    if pr > 0 && (pr % 10 == 0) {
        score -= 4.0;
    }
    if pr >= 20 && pr % 20 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a harmonic pair -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            // reward proportional to how tightly next item fits
            score -= 15.0 * (1.0 - slack as f64 / cap);
            if slack < eighth {
                score -= 8.0; // near-exact two-item packing
            }
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            score += 5.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && pr >= 0 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): prefer it only when existing bins fit
    // poorly. Penalize opening new bins when good fits exist, but allow it
    // when many bins are open and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty for opening a new bin
        score += 30.0;
        // if item is large, new bin is attractive (large items pair with fresh space)
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // late in the stream, consolidation matters more
        score += 10.0 * progress;
        // if mean residual across open bins is large, use existing bins instead
        score += 0.3 * mean_residual;
        // many open bins: discourage proliferation
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference for tighter fits overall (smaller post_residual wins ties).
    score += 0.05 * (pr as f64 / cap) * 100.0 * 0.0; // no-op guard, keep deterministic

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are pure waste; residuals in a "narrow band" are hard to fill later.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: heavily penalize beyond its raw size.
        score += (10.0 - pr) * 3.0;
    } else if post_residual <= 20 {
        // Narrow band: moderately hard to fill.
        score += (20.0 - pr) * 0.8;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here: slight penalty proportional to how close we came.
        let gap = (next_item_size as f64) - pr;
        if gap < 15.0 {
            score += gap * 0.5;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (new-bin candidate has fitting_bins_count context too).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins,
    // penalize the fresh-bin option (which has large residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 8.0 + (open_bins_count as f64) * 1.5 + progress * 10.0;
        // But if no open bin fits well, opening is fine: fitting_bins_count==0
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward using it, more so when many bins are open.
        score -= (open_bins_count as f64).min(10.0) * 0.8;
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (i.e., tighter bins) to keep large residuals available for large items.
    if bin_residual < bin_capacity {
        let diff = mean_residual - (bin_residual as f64);
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leave zero dead space.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when the post residual
    // exactly matches the next item size (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize residuals too small for the next item (dead space):
    // if next item cannot fit in the leftover space, the space is wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Relative-to-mean-residual term: prefer bins whose remaining space
    // after placement is close to (but slightly below) the mean residual,
    // i.e. bins that get "tightened" toward the average.
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.2 * mean_diff.abs();

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // item is large relative to the bin and open-bin residuals are large.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 20.0 + 40.0 * pressure;
        // If next item is big, a fresh bin is more attractive.
        score -= (next_item_size as f64) * 0.15;
    }

    // Mild late-stream tightening: as the stream progresses, avoid
    // leaving loose residuals (consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly favored.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize dead space: post_residual too small to be useful later.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 0.5;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual as u32 - next_item_size) as f64;
            score -= slack.max(0.0).min(20.0) * 0.8; // next item fits with some slack
            if post_residual == next_item_size {
                score -= 15.0; // perfect chain
            }
        } else {
            score += 5.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = (post_residual as f64) / bin_capacity as f64;
        // Prefer new bin if it would preserve a large residual and many bins compete.
        score -= fit_quality * 30.0 * (1.0 - progress);
        score += open_bins_count as f64 * 1.5; // discourage bin proliferation over time
        if item_size >= 50 {
            score -= 10.0; // big items do well in fresh bins
        }
    }

    // Prefer filling bins with below-average residual (consolidate emptier bins).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Mild penalty for very loose fits relative to item size.
    if item_size > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        score += (1.0 - ratio) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual (tight fit), scaled non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (quadratic growth).
    let coupling = (pr / cap).powi(2) * (1.0 + 2.0 * progress * progress);
    score += 20.0 * coupling;

    // Reward bins whose residual matches the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt) / cap).abs();
        score -= 8.0 * match_term.max(0.0) * (1.0 - progress);
    }

    // Penalize opening a new bin when other bins fit (smoothly, by fitting supply).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 15.0 + 2.0 * fitting_bins_count as f64 + 10.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Mild preference for bins deviating from mean residual (diversity of sizes).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight penalty for many open bins (consolidation pressure), smoothed.
    score += 0.1 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small-item compatible" residue class are preferred.
    let pr = post_residual;
    let class_bonus = match pr {
        0 => -30.0,                          // perfect fill
        1..=10 => -20.0,                     // near-perfect
        _ => {
            // reward leftovers divisible by common small-item sizes (2,5,10)
            let mut bonus = 0.0;
            if pr % 10 == 0 { bonus -= 12.0; }
            else if pr % 5 == 0 { bonus -= 6.0; }
            else if pr % 2 == 0 { bonus -= 2.0; }
            else { bonus += 4.0; }           // odd leftovers are awkward
            bonus
        }
    };
    score += class_bonus;

    // Lookahead coupling: does the leftover fit the next item exactly / well?
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap); // leftover usable by next item
        if pr == next_item_size { score -= 10.0; }
    } else if next_item_size > pr {
        // leftover too small for next item: penalize proportionally to wasted fraction
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 8.0 * progress;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would waste a lot
    // or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        let pressure = mean_residual / cap;
        // open a new bin if it yields a cleaner leftover than mean, else avoid
        score += 10.0 - 20.0 * (waste / cap) * (1.0 - pressure);
        if open_bins_count == 0 { score -= 50.0; }
    } else {
        // favor tighter existing bins (small residual before placement)
        score += 8.0 * (bin_residual as f64 / cap - 0.5);
    }

    // Mild dispersion penalty: prefer bins below mean residual (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: post_residual quarters.
    let quarter = pr / (bin_capacity / 4);
    score += quarter as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // while exact or near-exact fits are strongly rewarded.
    if post_residual == 0 {
        score -= 200.0; // perfect fill: ideal
    } else if post_residual < 10 {
        score += 60.0; // tiny dead space: nearly unusable for items >= 10
    } else {
        // Reward tightness: the smaller the remaining gap relative to capacity, the better.
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 25.0; // lookahead item can't use this residual
        } else {
            score -= 15.0; // lookahead item fits in the leftover
        }
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open
    // unless the fit is excellent; encourage using existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to number of open bins.
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 5.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mild stream-progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer bins with lower residual relative to the mean (tighter bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // 2-step lookahead: reward if the next item exactly fills the post residual,
    // reward mildly if it fits, penalize if it doesn't.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover space: dead space penalty scaled by gap
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: just minimize waste
        score += 0.1 * post_residual as f64;
    }

    // Penalize dead space relative to mean residual (avoid stranding space
    // when other bins have more usable room).
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Make the empty bin costly unless the
    // item is large and would leave a very fragmented residual elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0; // default cost of opening a new bin
        if item_size >= 50 && next_item_size > 0 && next_item_size > post_residual_of_open(mean_residual) {
            score -= 20.0; // large item, poor outlook in open bins: new bin ok
        }
        if open_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // late in stream, avoid many near-empty bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference for consolidating when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

#[inline]
fn post_residual_of_open(mean_residual: f64) -> u32 {
    (mean_residual.max(0.0) as u32).min(100)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fills are perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that can't fit typical small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_threshold = 10.0 + 5.0 * (1.0 - progress);
        if (post_residual as f64) < dead_threshold {
            score -= 8.0 * (1.0 - (post_residual as f64) / dead_threshold);
        }
        // Penalize very large leftover waste (unusable fragmentation).
        if post_residual > 80 {
            score += 6.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // If next item won't fit here, mildly penalize unless it's a tight fit anyway.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins fit poorly (high mean residual fragmentation) or few bins exist.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        // If open bins have plenty of residual (good fits likely), penalize new bin.
        score += 15.0 + 25.0 * (1.0 - pressure);
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins: discourage opening yet another.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Favor filling bins with residual far from mean (reduce variance).
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * diff;
    }

    // Mild global bonus for using existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let post_norm = post / cap;
    let base = post * (1.0 + 0.6 * post_norm * post_norm);

    // Progress-dependent scaling: late in stream, tighten bins more aggressively
    let progress_coupling = base * (1.0 + 0.8 * progress * post_norm);

    // Smooth dead-space penalty: quadratic in post_residual, weighted by item size
    let item_frac = item_size as f64 / cap;
    let dead_space = 0.5 * post * post / cap * (0.5 + item_frac);

    // Mean residual divergence: penalize bins far from mean residual smoothly
    let mean_dev = (residual - mean_residual) / cap;
    let mean_term = 0.3 * mean_dev * mean_dev.abs() * cap;

    // Last-chance bonus: if this is the only fitting bin, reward strongly (smooth)
    let last_chance = if fitting_bins_count <= 1 { -40.0 } else { 0.0 };

    // Lookahead: penalize if post_residual cannot fit next item (smooth logistic-like)
    let next = next_item_size as f64;
    let lookahead = if next > 0.0 {
        let fits_next = (post - next).max(0.0) / cap;
        -0.4 * fits_next * cap * (1.0 - fits_next)
    } else {
        0.0
    };

    // Open bins pressure: many open bins -> favor filling existing ones
    let open_pressure = -0.2 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_norm);

    progress_coupling + dead_space + mean_term + last_chance + lookahead + open_pressure
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (large chunks reusable by typical items) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement: reward high fill.
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill;

    // Integer-division threshold classes on post_residual (capacity 100):
    // class 0: pr in [0,10)  -> dead space, penalize strongly
    // class 1: pr in [10,25) -> marginally usable
    // class 2: pr in [25,50) -> good reusable chunk
    // class 3: pr >= 50      -> half-empty bin, wasteful placement
    let class = if pr < 10.0 { 0 } else if pr < 25.0 { 1 } else if pr < 50.0 { 2 } else { 3 };
    score += match class { 0 => 18.0, 1 => 6.0, 2 => -4.0, _ => 10.0 };

    // Exact-fit harmonic bonus: post_residual divisible by small harmonic steps.
    let pr_u = post_residual;
    if pr_u % 10 == 0 && pr_u > 0 {
        score -= 5.0;
    }
    if pr_u % 20 == 0 && pr_u > 0 {
        score -= 3.0;
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills remainder
            if next_item_size == post_residual {
                score -= 15.0;
            } else {
                score -= 7.0;
            }
        } else {
            // Next item won't chain here; penalize if we leave a near-fit gap
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 8.0;
            }
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless placement is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: prefer opening a new bin only when no open bin offers
    // a decent fit (mean residual small relative to item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit = mean_residual - item_size as f64;
        if mean_fit < 0.0 || mean_fit > 0.6 * cap {
            // open bins are either unusable or very loose -> new bin attractive
            score -= 10.0 + 4.0 * progress;
        } else {
            score += 14.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.15 * open_bins_count as f64;

    // Encourage packing into bins already below mean residual (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1..=10)
    // are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 {
            // gap can't hold the next item: mild penalty scaled by waste
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage new-bin openings
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // existing bins are heavily fragmented (high mean residual spread).
        score += 15.0 + pressure;
        if mean_residual < 5.0 && open_bins_count > 0 {
            score -= 10.0; // existing bins nearly full -> new bin is fine
        }
    } else {
        score -= pressure.min(12.0);
    }

    // Prefer bins whose residual is close to what we consume (tight packing).
    score += 0.1 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits too; reward tight two-item packing.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack.min(100.0);
        } else {
            // next item won't fit here; penalize dead space relative to next size.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Penalize small unusable residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Opening a new bin is wasteful when many bins are already open and one fits well.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item leaves large residual and no good fits exist
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
        if open_bins_count as f64 > mean_residual {
            score += 20.0;
        }
    }

    // Late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot be filled by the next item (wasted gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / 20.0).min(1.5);
    score -= pressure * (2.0 + 3.0 * progress) * tightness;

    // Divergence from mean residual: prefer bins below mean residual (denser bins).
    score += 0.08 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        let poor_fits = (fitting_bins_count == 0) as i32 as f64;
        let bad_gap = if next_item_size > 0 && item_size < next_item_size { 1.0 } else { 0.0 };
        score += 30.0 - 35.0 * poor_fits + 10.0 * bad_gap - 5.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit = fitting_bins_count as f64;
    let nxt = next_item_size as f64;

    // smooth non-linear coupling of post_residual with progress
    let poly = pr * pr / cap;                 // quadratic dead-space penalty
    score += poly * (0.5 + 0.5 * t) * 0.5;

    // reward tight fits, stronger as stream progresses
    score -= (cap - pr) / cap * (1.0 + t) * 4.0;

    // last-chance bin bonus (smoothly weighted)
    let last_chance = 1.0 / (fit * fit);
    score -= last_chance * 6.0 * (1.0 + 0.5 * t);

    // lookahead: reward bins whose post_residual can host next item
    if nxt > 0.0 && pr >= nxt {
        score -= (1.0 - pr / cap) * 3.0;
    } else if nxt > 0.0 {
        score += (nxt - pr) / cap * 2.0;
    }

    // penalize scattering when many bins open; smooth in mean residual
    let mr = mean_residual / cap;
    score += open_bins_count as f64 * 0.05 * (0.5 + 0.5 * mr);

    // new-bin candidate: mild penalty so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (post_residual % 10 == 0) rewarded.
    let harm = post_residual % 10;
    if harm == 0 {
        score -= 12.0;
    } else {
        score += harm as f64 * 0.8;
    }

    // Penalize dead space: small nonzero post_residual that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Integer division threshold: residual classes of the bin before placement.
    let res_class = bin_residual / 25;
    score += res_class as f64 * 2.5;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 && gap > 0 {
                score -= 20.0;
            } else if gap < 10 {
                score += 8.0;
            } else {
                score -= gap as f64 * 0.05;
            }
        } else if next_item_size <= bin_residual {
            // next item fits current bin better than this one
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is tight
    // (small residual class) or many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (bin_residual as f64 - mean_residual) < 15.0;
        if tight && open_bins_count > 0 {
            score += 25.0; // prefer existing tight bin, penalize new bin
        } else {
            score += 5.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (better fits).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for even the smallest
    // item are unusable — punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-maybe-usable gaps get a milder nonlinear penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (perfect fill is ideal).
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item won't fit here; dead space is locked in
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.6 * pressure;

    // Last-chance bonus: if this is the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: make it slightly unattractive unless residuals are
    // fragmented (high mean residual spread) or no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: fill this bin exactly over two items
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.15 * slack;
        } else {
            // Next item won't fit here; penalize dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize large leftover dead space that likely becomes unusable
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual <= 20 {
        score -= 8.0;
    } else {
        score += 0.2 * (post_residual as f64 - 20.0);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // or few bins fit the item (poor fit elsewhere)
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > 60 { 20.0 } else { 0.0 };
        score += 40.0 - large_item_bonus;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin can fit: must open new bin
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize leaving unusable slivers of dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits: post_residual small relative to item size.
    score += (post_residual as f64 / (item_size.max(1) as f64)) * 8.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // More competing bins -> mild penalty unless fit is very good.
        score += fitting_bins_count as f64 * 2.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting a large residual on a small item.
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.3;
        }
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Time horizon: early in stream, be more open to new bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when fit exists.
        let mut new_bin_penalty = 20.0 + 45.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 25.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size >= 40 {
            new_bin_penalty -= 15.0; // new bin useful for a large upcoming item
        }
        score += new_bin_penalty;
    } else {
        // Late stream: reward filling existing bins harder.
        score -= 15.0 * progress;
    }

    // Mild pressure against accumulating many open bins with scattered residuals.
    if open_bins_count > 4 && post_residual > 30 {
        score += (open_bins_count as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear post-residual shaping: penalize tiny dead space quadratically.
    let post_norm = post / cap;
    score += 12.0 * post_norm * (1.0 - post_norm) * (1.0 - post_norm);

    // Smooth stream-progress coupling: prefer tight fits early, waste tolerance late.
    let tightness = (item_size as f64) / cap;
    score -= 6.0 * tightness * (1.0 - progress) * (1.0 - post_norm);
    score += 4.0 * post_norm * post_norm * progress;

    // Last-chance bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Lookahead: reward residual that could host next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = if post >= nx { 1.0 } else { 0.0 };
        let gap = ((post - nx) / cap).max(0.0);
        score -= 8.0 * fits * (1.0 - gap * gap);
        score += 2.0 * (1.0 - fits) * post_norm;
    }

    // Deter spreading across many bins when mean residual is large.
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual / cap);

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly.
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 12.0,                 // perfectly closed space -> very desirable
        1..=5 => 6.0,              // small dead space
        6..=9 => -2.0,             // awkward residual, penalize slightly
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: post_residual / item_size ratio
    let quot = post_residual / item_size.max(1);
    score -= (quot.min(3)) as f64 * 3.0;

    // Capacity fraction coupling
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * fill_frac * 8.0;

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space for the lookahead item
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly unless current bin fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual.max(1.0);
        score += if poor_fit { 5.0 } else { 18.0 };
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Progression: tighten packing later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Mean residual divergence: prefer bins near the mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    let min_item = 1.0f64;
    if (post_residual as f64) < 10.0 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill is ideal
    } else {
        // Smooth penalty growing as residual approaches the dead zone
        let proximity = 1.0 - (post_residual as f64 - min_item) / 10.0;
        if proximity > 0.0 {
            score += 25.0 * proximity * proximity;
        }
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // and encourage packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 0.6 * pressure * (1.0 - progress * 0.5);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so it
    // wins only when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * open_bins_count as f64;
        // If next item is small, a fresh bin preserves flexibility
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Lookahead: reward bins whose post_residual can host the next item
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Deviation from mean residual: prefer bins close to average to keep
    // the bin profile balanced (avoids stranding one very-full bin).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual == bin_capacity {
        // Brand-new empty bin candidate: penalize opening a new bin unless
        // the fit into existing bins would be very poor.
        score += 30.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Next item fits after this one; mildly reward based on leftover.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit in this bin after placement; penalize
            // proportionally to how much dead space is created.
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: creating below-average
    // residual concentrates packing (good); above-average residual is wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits the item, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Slight preference for tighter bins early on when many bins are open.
    score += (open_bins_count as f64) * (bin_residual as f64 - item_size as f64) / (bin_capacity as f64 * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 80 {
        score -= 8.0; // post space is reusable by future items
    } else {
        score += 5.0 * ((post_residual as f64 - 80.0) / 20.0).min(1.0);
    }

    // Perfect closure bonus: exact fill.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual as u32 {
        // next item won't fit here anyway; mildly neutral
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is poor and many bins are open with fragmented space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bins generally; relax if fit is bad and fragmentation high.
        score += 45.0
            - 20.0 * fragmentation / (bin_capacity as f64)
            - 15.0 * (fit_ratio - 0.5).max(0.0)
            + 10.0 * (1.0 - progress);
    }

    // Prefer densifying few bins early; spread more when many bins open.
    let density_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * density_pressure * (1.0 - fit_ratio);

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time horizon: early stream, be conservative (keep space flexible);
    // late stream, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 2.0 * progress * progress);

    // Penalize very small dead space more sharply as stream progresses
    score += (1.0 - x) * (1.0 - x) * (3.0 + 4.0 * progress);

    // Reward tight fits (small post residual) especially when bins are scarce
    let scarcity = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
    score -= (1.0 - x) * (1.0 + scarcity) * (1.0 + 0.5 * progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 * (1.0 - (next_item_size as f64 / cap).powi(2));
    } else if next_item_size > 0 {
        score += 1.0 + progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many bins are open and mean residual is high
    if bin_residual == bin_capacity {
        score += 1.5 + mean_residual / cap + 2.0 * progress;
    }

    // Coupling with mean residual: prefer bins close to the mean (balanced usage)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: bins whose post_residual falls into "dead" classes are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as i64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Fraction-of-capacity classes: reward leaving residuals that are usable
    // (residual >= smallest plausible item). Items can be as small as 1.
    let residual_frac = post_residual as f64 / cap;

    // Penalize residuals in awkward harmonic classes (e.g. 1..=9 dead space),
    // scaled by how deep in the stream we are.
    if post_residual > 0 && post_residual <= 9 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * progress;
    }

    // Harmonic class via integer division: residuals in [10, 25) are semi-dead
    // unless the next item can use them.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here after current placement: strong reward.
            score -= 30.0 + (next_item_size as f64).min(post as f64) * 0.5;
        } else {
            // Next item cannot use this bin's remainder: penalize by gap size class.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.8;
        }
        // Modulo-class coupling: if next item exactly consumes remainder, big reward.
        if next_item_size == post_residual {
            score -= 120.0;
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0 + residual_frac * 20.0;
    }

    // New-bin candidate: neutral residual (full capacity). Prefer opening a new bin
    // only when the item is large and no open bin has a good fit.
    if bin_residual == bin_capacity {
        // Base score is post_residual = capacity, already high. Adjust:
        if item_size >= 60 {
            score -= 40.0; // large items pack well in fresh bins
        } else {
            score += 15.0; // prefer existing bins for small/medium items
        }
        // If many bins fit the item, discourage new bin.
        if fitting_bins_count > 2 {
            score += 30.0;
        }
    }

    // Tightness reward: closer fill => lower score, non-linearly.
    let fill = 1.0 - residual_frac;
    score -= fill * fill * 40.0;

    // Mean-residual coupling: if this bin is far below mean residual (i.e. fuller),
    // it's a better target.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Modulo-10 harmonic class of post_residual: certain classes are more
    // reusable (multiples of 5/10 pair well with typical item sizes).
    let m = post_residual % 10;
    if m == 0 {
        score -= 12.0;
    } else if m == 5 {
        score -= 6.0;
    } else if m <= 4 {
        score += m as f64 * 1.5;
    } else {
        score += (10 - m) as f64 * 1.5;
    }

    // Small penalty for proliferation of open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0; // still a near-perfect fill, keep it attractive
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight packing.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use leftover; the gap is likely dead space
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or mean residual is too small to matter.
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual >= item_size as f64;
        if mean_fit && fitting_bins_count > 0 {
            score += 20.0; // discourage opening new bins when open ones fit
        } else {
            score -= 10.0; // encourage a fresh bin over wrecking a scarce gap
        }
    }

    // Mild stream progression tilt: early on, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Favor bins where the next item leaves little waste again.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leaving a dead space gap that next item cannot use.
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare post residual against mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open with usable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 + 80.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
        // But if next item is large and this item is small, opening fresh may help.
        if next_item_size > 0 && next_item_size >= 70 && item_size <= 30 {
            score -= 100.0;
        }
    }

    // Mild penalty for very small unusable post residual (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, but soften when post_residual
    // can still accommodate typical future items (small items are reusable).
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Reward tight fits (small post_residual) more strongly.
    if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 25 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting a good bin.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 0.1 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: an empty bin is attractive only when the item
    // is large or existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mean_r_norm = mean_residual / bin_capacity as f64;
        // Prefer new bin for large items or when mean residual is high (fragmented state).
        let new_bin_bonus = 18.0 * fill_ratio + 20.0 * mean_r_norm * mean_r_norm;
        score -= new_bin_bonus;
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Many open bins -> encourage filling existing ones (consolidation pressure).
    let open_norm = open_bins_count as f64;
    score -= 0.6 * open_norm * (1.0 - pr / bin_capacity as f64);

    // Reward bins whose residual is below the mean (comparatively full bins).
    let mean_diff = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score -= 8.0 * mean_diff;

    // Time-dependent exploration: mid-stream, be adaptive; early, greedy tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let adapt = (progress * std::f64::consts::PI).sin();
    score -= 4.0 * adapt * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 60.0 * pr_norm * pr_norm * (1.0 - pr_norm)
        + 40.0 * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Progress coupling: early stream tolerates larger residuals; late stream punishes them
    let prog_coupling = (progress - 0.5) * 80.0 * pr_norm * pr_norm;
    score += prog_coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (20.0 + 30.0 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits into post_residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 + 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Penalize divergence from mean residual (keeps bin pool homogeneous)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: mildly penalize opening new bins early, less so late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Small post_residual (< 10) is dead space -> penalize extra.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Integer-division thresholds on post_residual: usable slots.
    // post_residual / 10 gives number of smallest items it could still hold.
    let slots = post_residual / 10;
    score += slots as f64 * 2.0;

    // Reward bins whose post_residual can exactly fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (20.0 - (gap as f64).min(20.0)) * 1.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.35 * (bin_capacity as f64 - item_size as f64);
        score += base;
        // If no open bin fits, new bin is cheap.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // Late in stream, avoid opening new bins lightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Modulo class of post_residual: multiples of 5 are more reusable.
    if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Mild preference for fuller bins as stream progresses.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a small nonzero gap is nearly unusable waste.
    if post_residual > 0 && post_residual < 12 {
        score += 45.0 + (12 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits relative to the bin's current residual.
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin, scaled by open-bin pressure.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.5;
        // If no open bin fits well, opening a new bin becomes more attractive.
        if post_residual < 20 {
            score -= 20.0;
        }
    }

    // Lookahead (k=2): favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward when the next item fits
    // the post-residual (chain packing), especially exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit here; penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Penalize large unusable residuals (dead space below min plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Prefer tight bins relative to mean residual
    let mean_res = if mean_residual > 0.0 { mean_residual } else { 1.0 };
    score += (post_residual as f64 - mean_res) * 0.3;

    // Slight preference for compacting many bins early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 10.0 * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: penalize mildly so it only wins on truly bad fits
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that can't fit a typical future item.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 30.0 * dead;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward partial compatibility with next item
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual {
        // penalize blocking the next item
        score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // cheaper to open new bin when many open bins are fragmented
        score -= 5.0 * (mean_residual / bin_capacity as f64);
        // early in stream, opening bins is fine; late, avoid sprawl
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * t;
        // if current item is huge relative to capacity, new bin is attractive
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins among open bins.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Prefer bins whose residual is near mean (keeps diversity of sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Slight penalty for accumulating too many open bins.
    score += 0.3 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer filling bins tightly (low post residual)
    let mut score = post;

    // Non-linear reward for tight fits (post_residual near zero), stronger early in stream
    let tightness = (1.0 - post / cap).powf(3.0);
    score -= 12.0 * tightness * (1.0 - 0.5 * progress);

    // Penalize mid-range dead space quadratically (awkward residuals ~ half capacity)
    let dead = post / cap;
    score += 8.0 * (dead * (1.0 - dead)).powf(2.0) * 4.0;

    // Lookahead coupling: reward leaving space that fits next item, penalize otherwise
    if next_item_size > 0 && (post as u32) >= next_item_size {
        let fit_quality = (post - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - fit_quality).powf(2.0);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Late stream: prefer consolidating into open bins over opening new ones
    let open_norm = open_bins_count as f64;
    score += post * (0.3 + 0.7 * progress) * (open_norm / (open_norm + 5.0));

    // New-bin candidate: penalize proportionally to wasted capacity unless residual of others is bad
    if bin_residual == bin_capacity {
        let escape = (mean_residual / cap).powf(2.0);
        score += 20.0 - 25.0 * escape;
    }

    // Smooth coupling of item size with progress: large items late -> prefer tight bins even more
    score -= 4.0 * (item / cap) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that divide capacity evenly
    let cap = bin_capacity as f64;
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 12.0; // perfectly divisible residual => reusable by equal splits
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure
    } else {
        // penalize dead space in awkward zones (harmonic gaps)
        let q = post_residual / 10;
        let harmonic_penalty = match q {
            0 => 8.0,
            1 => 2.0,
            2 => 4.0,
            3 => 1.0,
            4 => 0.5,
            _ => 0.0,
        };
        score += harmonic_penalty;
    }

    // Integer-division threshold coupling with next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward proportional to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 10.0 + 20.0 * (1.0 - tight / cap);
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.15 * (post_residual as f64 - next_item_size as f64).min(40.0);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residual would be tiny waste or stream early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_used = (bin_capacity - item_size) as f64;
        score = waste_if_used + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // forced new bin
        }
    }

    // Slight preference for bins tighter than average
    score += 0.05 * (mean_residual - bin_residual as f64).max(-30.0);

    // Mild pressure against bin sprawl
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(3.0);
        // A gap is "unusable" if smaller than a plausible minimum item size.
        let unusable = post_residual < 20;
        if unusable {
            score += 25.0 + 60.0 * dead;
        } else {
            score += 10.0 * dead;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight packing: residual consumed fraction.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let gap = mean_residual - item_size as f64;
        if gap < 15.0 {
            score -= 20.0; // open bins too full -> new bin is good
        } else {
            score += 45.0; // existing bins fit reasonably -> avoid new bin
        }
        // Late in stream, be more reluctant to open bins.
        score += 20.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
