pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more strongly than linear.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tight * tight;

    // Penalize dead space: post residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item can use the post residual, reward it.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
            let waste_after_next = post_residual as i64 - next_item_size as i64;
            if waste_after_next < 10 {
                score -= 10.0;
            }
        } else {
            // Post residual too small for next item: mild penalty scaled by wasted amount.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when item is large or existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) / cap;
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 60.0
            + 50.0 * large_item
            + 30.0 * poor_alternatives
            + 20.0 * (1.0 - progress)
            - 0.5 * open_bins_count as f64;
        // Discourage new bins when mean residual could still host this item comfortably.
        if mean_residual >= item_size as f64 {
            score += 35.0;
        }
        // If next item is small, keeping residual around is valuable -> penalize new bin less.
        if next_item_size > 0 && next_item_size <= post_residual.max(1) as u32 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if bin_residual > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly * cap * 0.01;
    // penalize dead space more strongly late in stream
    score += (pr * pr / cap) * (0.5 + progress);
    // reward tight fits
    score -= (item_size as f64 / cap) * 15.0 * (1.0 + progress);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    // lookahead coupling: reward leaving space for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 10.0 * (1.0 - (pr - n) / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (n - pr) / cap;
        }
    }
    // mean residual interaction
    score += 0.1 * (mean_residual - pr).abs() * (0.5 + progress);
    // new-bin candidate: mild penalty so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes behave differently
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => -12.0, // perfectly reusable residual (fits any future small item)
        5 => -6.0,  // half-decade residual still quite usable
        1 | 9 => 4.0,
        2 | 8 => 2.5,
        3 | 7 => 1.0,
        _ => 0.0,   // 4 | 6
    };
    score += class_bonus;

    // Dead space penalty: residuals too small for the smallest items
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // pure dead space
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportional to how well next item uses leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover -> penalize wasted space
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tighter fits among many candidates
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio * fill_ratio;

    // Late in the stream, consolidate: favor existing bins over new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses or many bins open
        score += 6.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        if post_residual < item_size {
            score += 100.0; // impossible new-bin call, guard
        }
    } else {
        score -= 2.0 * progress;
    }

    // Mean residual coupling: if this bin is far below mean residual, it is a poor host
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any future item (min size 1,
    // but practically small gaps under ~12 are wasteful) are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 12 { 3.0 } else if post_residual < 20 { 1.5 } else { 0.0 };
        score += dead * (post_residual as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing residuals are fragmented
        // or the item is large relative to what open bins can absorb.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + 0.5 * open_bins_count as f64;
        // If the next item is large and this item nearly fills a bin, opening fresh
        // can be good: reduce the new-bin penalty slightly.
        if next_item_size > 60 {
            score -= 10.0;
        }
        if fragmentation > 40.0 {
            score -= 8.0;
        }
    } else {
        // Placing into an open bin reduces open-bin pressure slightly.
        score -= 0.1 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item fits exactly into the resulting residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 12 {
            score += 5.0; // leaves a dead gap for the known next item
        }
    }

    // Mild stream-progression term: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward proportional to how well it nests
            score -= 0.3 * (next_item_size as f64 / post_residual as f64) * 100.0;
        } else {
            // next item cannot use the leftover: penalize dead space relative to mean residual
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Last-chance bin bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins already fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if existing fits are bad
        let tightness = (item_size as f64 / bin_capacity as f64) * 100.0;
        score += 50.0 + tightness;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Prefer bins with smaller residual overall (tighter packing)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight progression term: later in stream, prefer closing gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below the
    // minimum item size (1 here, use a soft threshold ~10) is nearly worthless.
    if post_residual > 0 {
        let waste = if post_residual < 10 { post_residual as f64 * 3.0 } else { post_residual as f64 };
        score += 0.5 * waste;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; penalize proportionally to leftover waste.
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += 0.4 * (bin_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Compare against mean residual: placing into a below-average-residual bin
    // (a fuller bin) is preferred.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly everywhere else. Give the empty bin a moderate penalty
    // that tight fits / last-chance placements can overcome.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, slightly discourage spreading into new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // But if next item is large and current fit is bad, new bin is attractive:
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 12.0;
        }
    }

    // Mild penalty for proliferating open bins when a decent fit exists.
    if bin_residual < bin_capacity {
        score += 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Polynomial coupling: tight fits matter more as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = next_item_size as f64 - post;
        if gap > 0.0 {
            score += gap * (0.8 + 0.6 * progress);
        } else {
            // Next item fits: reward proportional coupling.
            score -= 4.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus when few bins fit.
    if fitting_bins_count <= 1 {
        score -= 6.0 + 8.0 * fit_ratio;
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.15 * open_bins_count as f64 * progress * norm_post;

    // Deviation from mean residual: prefer bins whose post-residual
    // harmonizes with the fleet average (smooth quadratic).
    let dev = norm_post - mean_residual / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity classes
    let r = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Dead-space penalty: residuals that are too small to fit any plausible item
    if r < 10 {
        score += 60.0;
    } else if r < quarter {
        score += 25.0;
    }

    // Reward "harmonic" residuals: divisible-friendly values (multiples of 10, 20, 25, 50)
    if r % 10 == 0 {
        score -= 8.0;
    }
    if r % 20 == 0 {
        score -= 6.0;
    }
    if r % 25 == 0 || r == half {
        score -= 5.0;
    }

    // Lookahead coupling: does post_residual fit next item exactly / at all?
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item can go here too -> excellent chaining
            score -= 15.0;
            if r == next_item_size {
                score -= 20.0; // perfect pair closure
            }
            // penalize leaving awkward leftovers after chaining
            let after2 = r - next_item_size;
            if after2 > 0 && after2 < 10 {
                score += 12.0;
            }
        } else {
            score += 10.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin is a bad fit
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // but if this bin would leave a very tight residual elsewhere... it's already fresh
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer closing out tight residuals rather than new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins tighter than average (better fill discipline)
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.15;
    } else {
        score += (resid_f - mean_residual) * 0.10;
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits (small but usable-ish gaps) mildly.
        score -= 12.0 / (1.0 + post_residual as f64);
    }

    // Dead space relative to capacity: penalize waste fraction.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: slight penalty to prefer best-fit discrimination.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Open bins pressure: with many open bins, discourage spreading; prefer filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // Next item won't fit here; penalize leaving moderate gaps.
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when many bins open.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate calibration: empty bin gets a moderate baseline so it wins
    // only when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect 2-step match: next item still fits after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward tightness of the two-step fit.
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize placements that leave a residual too small for the next item
    // (dead space creation), especially when the leftover is tiny.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to current residual (small waste now).
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_tightness;

    // Compare against mean residual: prefer bins that are already relatively full
    // (residual below mean) to consolidate space.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when other bins fit, unless the fit is very tight.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size) as f64;
            if post_residual as f64 > best_possible * 0.5 {
                score += 40.0; // discourage wasteful new bin
            }
        }
        // A new bin is fine late in the stream if many bins are open and fragmented.
        if open_bins_count > 0 && (mean_residual / bin_capacity as f64) > 0.6 {
            score -= 10.0;
        }
    }

    // Slight long-stream consolidation pressure: keep bin count stable over time.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual relative to item size is better.
    if post_residual == 0 {
        score -= 60.0; // perfect fit bonus
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_ratio * fit_ratio;
    }

    // Penalize small dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if next_item_size <= bin_capacity {
            // next item will need a new bin anyway; slight penalty if we waste space
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, prefer closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (15.0 + 30.0 * (1.0 - progress));

    // Prefer bins with below-average residual (keeps big residual bins open).
    let mean_res = mean_residual;
    if bin_residual as f64 > mean_res + 1.0 {
        score += 3.0 * (bin_residual as f64 - mean_res) / bin_capacity as f64;
    } else {
        score -= 3.0 * (mean_res - bin_residual as f64) / bin_capacity as f64;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * open_bins_count as f64 * new_bin;
    score -= 0.2 * open_bins_count as f64 * (1.0 - new_bin);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap; // in [0,1]
    // Dead-space penalty grows super-linearly as residual shrinks; modulated by progress
    let dead_space = pr_norm * pr_norm * (0.5 + progress);
    score += 20.0 * dead_space;

    // Reward tight fits: subtract a smooth bump peaked at small post_residual
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 15.0 * tightness * (1.0 + 0.5 * progress);

    // Penalize bins whose residual deviates from mean residual (balance pressure)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: reward leaving room for the next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        if gap >= 0.0 {
            let fit_quality = 1.0 - (gap / cap);
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            // next item cannot fit here; penalize proportionally to shortfall
            score += 8.0 * ((-gap) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for proliferation of open bins early in the stream
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // New-bin candidate: smooth sigmoid-like barrier against opening new bins
    if bin_residual == bin_capacity {
        let barrier = 1.0 / (1.0 + (-8.0 * (progress - 0.5)).exp());
        score += 30.0 * barrier + 10.0;
        // But allow new bin if item would leave very unusable residue in any bin
        score -= 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is worse.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class thresholds: residual that could still fit common item sizes
    // (>=10) is valuable; residual < 10 is dead space -> penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Does next item fit into post_residual? Reward leaving usable space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain bonus scaled by how snugly the next item fits later
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.15 * slack;
            // harmonic class match: post_residual in same modulo class as next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
        } else {
            // residual too small for lookahead: dead space penalty
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist,
    // but allow it when mean residual is already fragmented.
    if bin_residual == bin_capacity {
        score += 50.0;
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer filling bins whose residual is close to mean (balance) slightly,
    // but reward tight packing (small residual before placement) more.
    let tightness = 1.0 - (bin_residual as f64 / c);
    score -= 20.0 * tightness * tightness;

    // Fractional harmonics on post_residual vs capacity
    if frac > 0.0 && frac < 0.1 {
        score += 10.0; // tiny unusable residue
    } else if frac >= 0.25 && frac < 0.5 {
        score -= 8.0; // quarter-capacity residue is reusable
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual is "dead" if it cannot hold even the smallest plausible item (size 1..=10).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 60.0 * (1.0 + (dead_threshold - post_residual) as f64 / dead_threshold as f64);
    } else if post_residual > dead_threshold && post_residual < 20 {
        // Semi-dead zone: mildly risky gap
        score += 15.0 * (1.0 - (post_residual - dead_threshold) as f64 / 10.0);
    }

    // Reward tight fits (small post_residual relative to bin_residual).
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness * tightness;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using the bin when it is the last chance before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to leftover after next item.
        let nn = post_residual - next_item_size;
        if nn <= dead_threshold {
            score += 10.0; // would create dead space next step
        } else {
            score -= 8.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln1p() * 4.0 * (0.5 + progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize opening a new bin, more so with many open bins / late stream.
        score += 12.0 + pressure;
        // But allow new bin if mean residual across open bins is small (all bins nearly full).
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean (consolidate waste).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space nonlinearly (worst between 1 and ~20).
        let pr = post_residual as f64;
        score += 40.0 * (1.0 - (pr / 30.0)).exp() * (30.0 / pr).min(3.0);
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let tightness = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 25.0 + 30.0 * tightness;
        } else {
            // Post-residual too small for next item: dead-space risk.
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mild bias against proliferating bins early in the stream.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for tighter bins overall.
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post_residual already does this); add superlinear penalty on large dead space.
    let dead = post_residual as f64;
    score += 0.35 * (dead / bin_capacity as f64) * dead;

    // Lookahead: if next item fits exactly into post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 12.0 + 0.25 * slack_after_next as f64;
    }
    // If next item is too big for post_residual but small overall, mild penalty for wasting the gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: avoid opening a new bin when only this bin fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins that are already relatively full relative to the mean residual.
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Penalize opening new bins more when many bins are open (consolidation pressure),
    // but relax as the stream progresses (early exploration of new bins is fine).
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 8.0 * (1.0 - t) + 2.0 * (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        score += new_bin_bonus;
    }

    // Mild penalty for very small leftover gaps that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 0.5 * progress);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * fit * fit * (1.0 - progress);

    // Penalize near-full residuals that become dead space, scaled by progress
    let dead = if pr > 0.0 { (norm_pr - fit).abs() } else { 0.0 };
    score += 12.0 * dead * dead * progress;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 15.0 * (nx / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 8.0 * (nx / cap) * progress;
        }
    }

    // Mean residual coupling: prefer bins deviating from mean early, near mean late
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.3 + 0.7 * progress);

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 measure "dead space quality".
    let post_mod = post_residual % 10;
    let post_div = post_residual / 10;

    // Penalize residuals that fall into awkward harmonic classes (small nonzero mod).
    if post_residual > 0 {
        score += match post_mod {
            0 => -6.0,                       // perfectly harmonic slot
            1 | 2 => 4.0,                    // nearly-full dead space, hard to reuse
            3 | 4 => 2.0,
            8 | 9 => 3.0,                    // sliver too small for min item class
            _ => 0.0,
        };
    }

    // Reward small post_residual (tight fit) with a quadratic term.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_mod = (post_residual - next_item_size) % 10;
            score -= 8.0 - (nxt_mod as f64) * 0.5;
        } else {
            // next item cannot use this residual: slight penalty scaled by mismatch class
            let gap = (next_item_size - post_residual) / 10;
            score += (gap as f64) * 1.5;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // discourage opening a new bin when alternatives exist;
            // scale penalty with how many bins fit and how good mean residual is.
            score += 30.0 + 5.0 * (fitting_bins_count as f64)
                   + 0.2 * (open_bins_count as f64);
        } else {
            // last chance: opening a new bin is fine
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // this is the only bin that fits: strongly favor using it
        score -= 12.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (more filled).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Integer-division threshold on post_residual: residuals < 10 are near-perfect.
    if post_div == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Stream progression: slightly more conservative late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual was tight relative to the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let dead_gap = if post_residual < 10 { 80.0 } else { 0.0 };
        score += 15.0 + dead_gap - mean_residual * 0.2;
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Progress pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 45.0;
        } else if post_residual as u32 > next_item_size {
            // next item still fits after this placement
            score -= 10.0;
            // extra reward if it would then leave small waste
            let two_step_waste = post_residual as u32 - next_item_size;
            if two_step_waste <= 5 {
                score -= 15.0;
            }
        } else {
            // next item would NOT fit here: penalize leaving residual smaller than next item
            score += 12.0 + 0.2 * (next_item_size - post_residual as u32) as f64;
        }
    }

    // Compare against mean residual: bins tighter than average are good targets
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when good open bins exist (new-bin candidate has residual == capacity)
    if bin_residual == bin_capacity {
        score += 8.0;
        // but allow new bin if next item is large and current item is small (better pairing later)
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            score -= 5.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: quadratic penalty on wasted space ratio.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize residuals that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // residual remains useful
        } else if post_residual > 0 {
            // dead space relative to lookahead
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
        // If this bin is the only one that fits, and next item would still fit after, reward.
        if fitting_bins_count == 1 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless item is huge
    // or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // Prefer new bin for very large items early on; penalize otherwise.
        score += 45.0 - 40.0 * pressure - 10.0 * progress;
        // If many open bins with slack, opening yet another is wasteful.
        score += 0.8 * open_bins_count as f64;
        // If mean residual among open bins is small, new bin is justified.
        score -= 0.5 * mean_residual;
    }

    // Mild preference for filling bins that are already partially used when
    // many bins are open (consolidation pressure).
    if bin_residual < bin_capacity {
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
    }

    // Time-horizon coupling: early in stream, be pickier about waste (long future);
    // late in stream, accept slightly worse fits to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += waste * (1.0 - progress) * 10.0;

    // Penalize bins whose residual is awkwardly small (unusable dead zone).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * 40.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 3.0 * progress) * 25.0;

    // Lookahead: penalize if post_residual can't fit the next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * (0.5 + 0.5 * progress);
        // Reward if next item fits snugly afterwards
        let after = pr - next_item_size as f64;
        if after >= 0.0 {
            score -= (1.0 - after / bin_capacity as f64) * 10.0;
        }
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    // Coupling with mean residual across open bins
    score += (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of capacity wasted

    // Dead-space penalty grows super-linearly; residuals in "awkward" bands are worse.
    // Classes: (0,10] tiny -> great; (10,30] awkward small; (30,50] mid; >50 still reusable.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, zero waste
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 30 {
        score += 10.0; // awkward dead space
    } else if post_residual <= 50 {
        score += 3.0;
    } else {
        score -= 5.0; // large residual keeps flexibility
    }

    // Modulo arithmetic on post_residual: residuals matching common item-size
    // harmonics (multiples of 10, 20, 25) are more likely to be filled later.
    let harmonic_bonus = if post_residual % 10 == 0 {
        8.0
    } else if post_residual % 20 == 0 || post_residual % 25 == 0 {
        5.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Integer-division threshold: can the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: strongly reward, especially if next item also leaves a harmonic residual.
            let chain_post = post_residual - next_item_size;
            let chain_quality = if chain_post % 10 == 0 { 12.0 } else { 6.0 };
            score -= chain_quality;
        } else {
            // Next item won't chain here; penalize proportional to how close it was.
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(20.0) * 0.4;
        }
    } else {
        // Last item: only absolute waste matters.
        score = post as f64 * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when the current bin
    // would be left with truly awkward dead space. Make new bins moderately attractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, prefer consolidation; later, allow spreading.
        let new_bin_bias = 30.0 - 20.0 * progress;
        score += new_bin_bias;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += (mean_residual / cap).max(0.0) * 15.0;
    }

    // Mild pressure against scattering when many bins are already open.
    score += open_bins_count as f64 * 0.05;

    // Tight-fit reward: item fills most of the bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual gap is "unusable" if it is smaller than the smallest possible item (1),
    // but practically, tiny gaps (< ~10) are dead space in most streams.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 4.0;
    }

    // Perfect fit bonus: exact closure of the bin is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize large wasted capacity relative to the bin.
    score += (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Open bins pressure: discourage spreading across too many bins.
    score += open_bins_count as f64 * 0.35;

    // Last chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use the leftover: this residual is likely dead space.
        score += 5.0;
    }

    // New-bin candidate handling: only open a new bin when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with tight fits win, but reduced when many
        // open bins are nearly full (mean residual low).
        score += 3.0 + mean_residual * 0.05;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference late in the stream to consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins whose post-residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + match_gap);
    }
    // Penalize dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: avoid wasting the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Discourage opening new bins when a reasonable fit exists in open bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 10.0; // pair could have gone together in a fresh bin anyway
        }
    }

    // Slight preference for bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Late-stream pressure: fill existing bins more aggressively near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals that are too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score -= 20.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item cannot fit here; slight penalty for wasting a good slot.
            score += 4.0;
        }
    }

    // New-bin candidate handling: discourage opening new bins early or when
    // reasonable fits exist; encourage it when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 * (1.0 - progress);
        // If many bins fit the item, opening a new bin is wasteful.
        score += 2.0 * fitting_bins_count as f64;
        // If open bins are fragmented (high mean residual spread vs item), new bin ok.
        if mean_residual < item_size as f64 && fitting_bins_count > 0 {
            score -= 5.0;
        }
        // Avoid hoarding too many open bins late in the stream.
        if open_bins_count > 20 {
            score += 10.0;
        }
    }

    // Mild penalty for placing into bins with much larger residual than needed
    // (preserve large-residual bins for larger future items).
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    if waste_ratio > 0.5 && item_size < 40 {
        score += 6.0 * waste_ratio;
    }

    // Slight global pressure: with many open bins, prefer filling existing ones.
    score += 0.15 * open_bins_count as f64;

    // Normalize with mean residual coupling: prefer bins below mean residual
    // (tighter bins) to keep large spaces available.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in [0,1]
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Normalized post-residual and item size
    let pr_norm = post_residual as f64 / bin_capacity as f64;
    let item_norm = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: quadratic post-residual penalizes
    // large dead space more aggressively as the stream progresses.
    let dead_space_penalty = pr_norm * pr_norm * (0.5 + 2.5 * progress);
    score += dead_space_penalty * bin_capacity as f64;

    // Cubic interaction between item size and progress:
    // larger items become more valuable to place tightly later in the stream.
    score -= item_norm * item_norm * item_norm * 20.0 * (0.3 + 0.7 * progress);

    // Smooth coupling of post-residual with mean residual across open bins:
    // if this bin's post-residual is far below the mean, it's a tight fit — reward.
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= tightness * tightness * 10.0 * (1.0 - progress);

    // Lookahead coupling: smooth polynomial reward when post-residual
    // matches the next item's potential fit.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        let gap = (pr_norm - next_norm).abs();
        score += gap * gap * 15.0 * progress;
        // Reward if next item exactly consumes the post-residual region
        let harmony = 1.0 - (pr_norm - next_norm).abs() / (pr_norm + next_norm + 1e-6);
        score -= harmony * harmony * 8.0;
    } else {
        // Last item: strongly reward minimizing post-residual (cubic)
        score += pr_norm * pr_norm * pr_norm * 30.0;
    }

    // Last-chance bin: reward using it when it's the only fitting bin,
    // scaled smoothly by progress.
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.4 + 0.6 * progress);
    }

    // Slight penalty for accumulating too many open bins, smooth in progress.
    score += open_bins_count as f64 * 0.05 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize mildly so open bins are preferred unless
    // the fit is poor; the polynomial dead-space term on an empty bin is
    // small, so this keeps new bins competitive only for bad fits.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress - item_norm * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: bins whose post-residual lies in a
    // "small-item friendly" class are rewarded. Classes of 10 (capacity
    // fractions of C=100) via integer division.
    let post_class = post_residual / 10;
    let item_class = item_size / 10;

    // Reward small post-residuals (tight fit) super-linearly.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Perfect / near-perfect fit bonuses.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic pairing: does post_residual match a plausible next item size?
    // Reward when next_item_size fits exactly or nearly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_waste = post_residual - next_item_size;
        score -= 20.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        if next_waste == 0 {
            score -= 30.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this leftover: penalize large dead space
        // proportionally to how far off it is, using class mismatch.
        score += 0.15 * (next_item_size as f64 - post_residual as f64);
        // Penalize odd harmonic classes (residuals not divisible cleanly).
        if post_class % 2 == 1 {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current bin's post-residual is genuinely bad (large, unmatchable).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if the stream is early or open bins are all tight, opening
        // is cheaper: discount by mean residual saturation.
        let tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 35.0 * tight;
        // Large items prefer a fresh bin to avoid fragmentation.
        if item_class >= 6 {
            score -= 20.0;
        }
    } else {
        // Slight preference for reusing already-open bins to keep the
        // open-bin count low, scaled by stream maturity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
        // Congestion: when many bins compete, favor the tightest fits more.
        if fitting_bins_count > 3 {
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Dead-space penalty for residuals below the minimum item size (1):
    // anything >0 and <10 is nearly unusable for typical classes.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (smallest item is 1, but tiny gaps attract small items and waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Perfect fit: reward heavily.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward when the residual left behind can still fit the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Lookahead can't fit in this bin anyway; a fresh placement here is neutral-positive.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening new ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: penalize proportional to open bins,
        // scaled by how full the mean residual suggests existing bins are.
        score += 30.0 + open_pressure;
        if mean_residual > (item_size as f64) {
            score += 10.0; // existing bins have room; avoid opening a new one
        }
    } else {
        // Existing bin: reward slightly for being chosen when bins are plentiful.
        score -= open_pressure * 0.25;
    }

    // Late in the stream, tighten up: dead space matters more since fewer items remain
    // to fill it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post_residual.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual) already handled by base score.

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact chaining is gold.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0) * 0.5;
            if post_residual == next_item_size {
                score -= 25.0; // perfect 2-item fill
            }
        } else {
            // Post-residual too small for next item: dead-space risk, penalize
            // proportionally to how unusable the leftover is.
            let waste = post_residual as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            score += waste * (0.3 + 0.7 * next_frac);
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 30.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large and no tight option exists.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 20.0;              // default penalty: prefer existing bins
        if fill_frac > 0.7 {
            score -= 30.0 * (fill_frac - 0.7) / 0.3; // large items justify fresh bins
        }
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for fragmenting many open bins late in the stream.
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64 - 8.0).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable leftovers (dead space), harder near the end of stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 20.0 * progress;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (bin_residual as f64 + 1.0) * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward;
    // if post_residual is just barely too small for next item, penalize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Prefer bins whose residual is below the mean (pack fuller bins first).
    score += ((bin_residual as f64) - mean_residual).max(-30.0).min(30.0) * 0.3;

    // Mild penalty for opening a new bin when many bins are already open,
    // relaxed early in the stream.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 12.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        score += new_bin_penalty * (1.0 - 0.3 * progress);
        // But if the only alternative creates big dead space, new bin looks better:
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, non-linearly warped by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Smooth quadratic penalty for large dead space, amplified late in stream
    score += (norm_pr * norm_pr) * cap * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) with a smooth coupling to item size
    score -= norm_item * (cap - pr) * 0.6 * (1.0 - progress * 0.5);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= (cap - slack) * 0.35 * (1.0 + progress);
        } else {
            score += (nxt - pr) * 0.15;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 0.5 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more when many bins already open
    if bin_residual == bin_capacity {
        score += cap * (0.3 + 0.05 * open_bins_count as f64) * (1.0 - 0.3 * progress);
        // But if mean residual of open bins is small (all crowded), opening is fine
        score -= mean_residual * 0.2;
    }

    // Slight preference for bins already below mean residual (consolidate slack)
    score += (mean_residual - pr as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus scales with fraction of bin consumed.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Harmonic class of post_residual (mod 10 buckets): dead-space classes.
    // Residuals that are small (< 10) are pure dead space -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else {
        // Modulo-10 harmonic class: prefer residuals in classes that match
        // common item sizes (multiples of 5/10 are re-usable).
        let class = post_residual % 10;
        if class == 0 {
            score -= 12.0; // perfectly reusable class
        } else if class == 5 {
            score -= 8.0;  // half-class, still reusable
        } else {
            score += (class as f64) * 1.5; // awkward class penalty
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            // partial reward decaying with leftover after next item
            let after_next = post_residual - next_item_size;
            score -= 15.0 - (after_next as f64) * 0.15;
        } else {
            // next item cannot fit here; penalize more if gap is small (near miss)
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make it attractive only when alternatives are poor.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: mean residual pressure decides.
        score = 60.0 + mean_residual * 0.5 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // reserving fresh space for a bigger next item helps
        }
        return score;
    }

    // Mild stream-progression tilt: later in stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Prefer bins whose residual is already below average (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += next_item_size as f64 * 0.1;
        }
    }

    // New-bin candidate (bin_residual == bin_capacity): open only when forced.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: must open
        }
    } else {
        // Prefer existing bins; extra pressure when this is the last chance.
        score -= 5.0;
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation pressure via mean residual.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (post_residual == 0).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Leftover can still host the next item: mild reward proportional to slack match.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space relative to next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.25 * dead;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * ((mean_residual - post_residual as f64) / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced when many items remain or few bins fit.
        let mut new_bin_penalty = 55.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        } else if fitting_bins_count == 1 {
            new_bin_penalty = 25.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= (1.0 - 0.3 * progress);
        score += new_bin_penalty;
    }

    // Small bonus for using bins that are already quite full (tight packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Penalize leaving very small unusable slivers (dead space 1..=5).
    if post_residual > 0 && post_residual <= 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for opening a new bin when an open bin could fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + 0.15 * open_bins_count as f64;
    }

    // Reward tight fits (low post-residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: penalize leaving residual that can't fit next item,
    // reward residual that exactly accommodates it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            let slack = (post_residual - next_item_size) as f64;
            score += 0.05 * slack;
        } else {
            score += 6.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for the minimum item (1) are
    // still usable, but very small residuals are wasted; penalize extremes.
    if post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    // Global state coupling: many open bins with high mean residual ->
    // encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * mean_residual * (1.0 - progress) - 0.05 * mean_residual * progress;

    // Prefer bins with less residual when many bins are open (consolidation).
    score += 0.02 * (bin_residual as f64) * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight packing), non-linearly.
    let x = post / cap; // normalized post-residual in [0,1]
    let mut score = 100.0 * x * x + 40.0 * x * x * x;

    // Smooth stream-progress coupling: later in the stream, tolerate/penalize
    // residual differently — quadratic interaction term.
    score += 60.0 * x * x * progress;
    score -= 30.0 * x * (1.0 - progress);

    // Reward filling bins whose residual was already small (compaction).
    let fill_ratio = item / res.max(1.0);
    score -= 50.0 * fill_ratio * fill_ratio;

    // Penalize post-residual that cannot hold the lookahead item (dead space),
    // smoothly scaled by how far the next item is from fitting.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = ((nxt - post) / cap).max(0.0);
        score += 45.0 * gap * gap;
        // Reward if lookahead exactly fits the post-residual.
        let fit_gap = (nxt - post).abs() as f64 / cap;
        score -= 25.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * (post > 0.0) as i32 as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin (smooth in 1/fitting_bins_count).
    if fitting_bins_count >= 1 {
        score -= 35.0 / fitting_bins_count as f64;
    }

    // Mild penalty when this bin's residual deviates from mean residual
    // (encourages balanced residual distribution, smooth quadratic).
    let dev = (res - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: an empty bin has post == cap (x == 1).
    // Give it a smooth adaptive offset so it only wins when all open bins
    // would leave very large post-residuals, and early in the stream.
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    score += is_new_bin * (80.0 - 60.0 * progress) * (1.0 - x * x).max(0.0).min(1.0) * 0.0
        + is_new_bin * (70.0 - 50.0 * progress);

    // Slight penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into a
    // "reusable" class (large, divisible-ish chunks) are more valuable to keep.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -40.0 // perfect fit — extremely desirable
    } else if pr <= 10 {
        30.0 // tiny dead space — heavily penalize
    } else if pr <= 25 {
        12.0
    } else if pr <= 50 {
        0.0
    } else {
        -8.0 // large residual keeps future options open
    };
    score += class;

    // Integer-division harmonic tiers on post_residual (mod-style classes).
    if pr > 0 {
        let tier = (pr / 20) as f64;
        score -= tier * 3.0;
        if pr % 20 == 0 {
            score -= 5.0; // exact multiple: harmonically clean residual
        }
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (next_item_size as f64) * 0.15;
        } else {
            score += ((next_item_size - pr) as f64) * 0.08;
        }
    }

    // Last chance: this is the only bin that fits — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: neutral baseline, slightly above good fits.
    if bin_residual == bin_capacity {
        let base = 55.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64) * 0.6;
        let mean_pull = (mean_residual - item_size as f64).max(0.0) * 0.2;
        return base + progress * 20.0 + open_pressure - mean_pull;
    }

    // Prefer fuller bins: scale by fill fraction.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 25.0;

    // Slight preference for bins below mean residual (balance avoidance of
    // many half-empty bins) when open bin count is high.
    if open_bins_count > 3 {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no realistic item can use
    // are heavily penalized. Treat gaps below ~12 as unusable dead space.
    let dead_threshold: f64 = 12.0;
    let post = post_residual as f64;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 6.0;
    }
    // Mid-range gaps are mildly wasteful too (hard to fill exactly).
    if post >= dead_threshold && post < 25.0 {
        score += (25.0 - post) * 0.8;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post / (item_size.max(1) as f64);
    score -= (1.0 / (1.0 + tightness)) * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bins pressure: discourage spreading across many open bins when
    // residuals are already large; encourage consolidation.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);
    score += pressure * 2.5;

    // Lookahead coupling: if the next item fits the post-residual, reward
    // leaving exactly that gap; penalize gaps the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when the current fit would create dead space.
    if bin_residual == bin_capacity {
        if post < dead_threshold && post > 0.0 {
            score -= 20.0; // opening fresh beats creating dead space
        } else {
            score += 5.0; // otherwise prefer existing bins
        }
    }

    // Mild stream-progression term: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Dead space relative to the next item's demand.
        score += (next_item_size as f64) * 0.35;
    }

    // Penalize post_residual that is too small for typical future items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins below mean residual are tighter, prefer them.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Mild preference to keep number of open bins low early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.0 - progress) * 0.3;

    // New-bin candidate: neutral-ish score; only chosen when no open bin scores better.
    if bin_residual == bin_capacity {
        score = 55.0 + (item_size as f64) * 0.1;
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize small post-residual dead space that few items can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or
    // the fit is poor, or late in the stream where consolidation is cheap.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / 20.0;
        let poor_fit_everywhere = fitting_bins_count as f64;
        let penalty = 45.0
            - 15.0 * progress
            - 10.0 * (mean_residual / cap).min(1.0)
            - crowded
            - 4.0 * poor_fit_everywhere;
        score += penalty.max(0.0);
    } else {
        // Prefer bins whose residual is close to mean (balance load) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item cannot fit here; slightly penalize leaving gap.
            score += 3.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - x) * (1.0 - x));

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (cap - pr) * progress * (1.0 - x).powi(3) * 0.3;

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap < 0.0 {
            score += (-gap) * 0.6;
        } else {
            score += (gap * (1.0 - gap / cap)).powi(2) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.4 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins vs mean residual
    score += (open_bins_count as f64).ln() * x * 2.0;
    score += (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on a "usable" class
    // (multiples of a quantum) are more likely to absorb future items.
    let quantum: u32 = 10;
    let post_class = post_residual / quantum;
    let post_rem = post_residual % quantum;
    // Penalize residual that is not a multiple of the quantum (dead space).
    score += (post_rem as f64) * 0.35;

    // Reward small residuals: near-full bins are desirable placements.
    if post_residual <= quantum {
        score -= 25.0;
    } else if post_residual <= 2 * quantum {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
            // Harmonic check: post_residual - next_item_size landing on a class boundary.
            let pair_rem = (post_residual - next_item_size) % quantum;
            score += pair_rem as f64 * 0.25;
        } else {
            // Next item cannot use this residual: mild penalty scaled by wasted capacity.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.08 * waste;
        }
    } else {
        // Last item: strongly prefer filling existing bins as tightly as possible.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when open bins have plenty of residual capacity.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 + 25.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Reward choosing bins with below-average residual (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Integer-division threshold on bin_residual: bins in the "large residual" class
    // are less precious; slight penalty reduction there to keep big holes usable.
    let res_class = bin_residual / (bin_capacity / 4).max(1);
    score -= res_class as f64 * 1.5;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: gaps too small to be useful later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // A gap is "dead" if smaller than the smallest plausible future item; use lookahead as anchor.
    let min_useful = if next_item_size > 0 { next_item_size.min(20).max(1) } else { 10 };
    if post_residual > 0 && (post_residual as f64) < min_useful as f64 {
        score += 40.0 + 2.0 * (min_useful as f64 - post_residual as f64);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 30.0 * (-post_residual as f64 / 10.0).exp();

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into existing bins
    // (penalize the new-bin candidate more strongly).
    score += 0.8 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate: only attractive when current fit wastes a lot.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * (post_residual as f64);
    }

    // If the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (-slack / 8.0).exp();
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: mild penalty scaled by how much we waste.
        score += 0.3 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Slight preference for bins below mean residual (balancing load) early on.
    score += 0.1 * ((bin_residual as f64) - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: exact match of next item into post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits; reward tighter chain fits
            let chain_gap = post_residual - next_item_size;
            score -= 150.0 * (1.0 - chain_gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if post_residual is large dead space
            let dead = post_residual as f64;
            score += 0.5 * dead * dead / bin_capacity as f64;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good existing option (high mean residual fragmentation)
    if bin_residual == bin_capacity {
        score += 50.0 + mean_residual * 0.5;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 100.0; // existing bin can host next item too; discourage new bin
        }
    }

    // Early stream: be slightly conservative, keep large residuals open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Penalize scattering across many open bins when few fitting options exist
    if fitting_bins_count > 3 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: small post_residual that is still nonzero is fine,
    // but post_residual that cannot fit the next item is wasted if next item is large.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            // dead space for the lookahead item
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste;
        } else {
            // lookahead fits here: strong reward for chaining
            score -= 8.0;
            let chained_left = post_residual - next_item_size as u32;
            score -= 0.1 * (chained_left as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // Candidate for a new bin: penalize, scaled by open bins and stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 + 0.4 * open_bins_count as f64 + 10.0 * progress;
        // But if mean residual is high (open bins are all quite full), new bin is more acceptable.
        score -= 0.05 * mean_residual;
    } else {
        // Existing bin: mild reward scaled by how full the bin already is.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 4.0 * fill;
        // Slight penalty when this bin's residual is far above mean (keep balanced usage).
        score += 0.03 * ((bin_residual as f64) - mean_residual).abs();
    }

    // Early stream: be less picky, encourage filling bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * tightness;

    // Exact fit gets a huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual

    // Base: penalize wasted space non-linearly (quartic coupling with progress)
    let mut score = post * (1.0 + 0.8 * progress * progress) + 0.35 * cap * x * x * (1.0 + progress);

    // Reward tight fits: small post residual relative to item size
    let tightness = item_size as f64 / residual.max(1.0);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0);
        score += 0.25 * gap + 0.05 * gap * gap / cap;
        // If next item fits exactly, reward strongly
        if next_item_size as f64 <= post {
            score -= 6.0 * (next_item_size as f64 / post.max(1.0));
        }
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 20.0 * (1.0 - x);
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize proportional to how many open bins could fit
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * (fitting_bins_count as f64) + 20.0 * (1.0 - progress) * (1.0 - progress);
        // But if open bins are all fragmented (high mean residual spread vs post), soften
        score -= 0.1 * mean_residual;
    }

    // Mild dispersion penalty: prefer bins far from mean residual (diversity of sizes)
    let dev = (post - mean_residual).abs() / cap;
    score += 3.0 * dev * (1.0 - dev);

    // Crowd penalty: many open bins -> prefer consolidating into emptier-fitting bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space
    // below a "useful chunk" threshold is wasted.
    let useful = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < useful {
        score += (useful - post_residual) as f64 * 3.0; // tiny unusable sliver penalty
    }

    // Harmonic class of post_residual: perfect zero is ideal,
    // small classes are penalized, large classes are fine.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let pr = post_residual as f64;
        let frac = pr / cap;
        // mod-style bucketing of residual fraction
        let bucket = (frac * 8.0).floor() as i32;
        score -= bucket as f64 * 1.5;
        // exact division classes: residual divisible by common item sizes
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (next_item_size as f64 / cap) * 6.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; penalize proportionally to wasted capacity
        score += (post_residual as f64 / cap) * 8.0;
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins
    // are crowded (high mean residual) or many bins already fit the item.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score += 30.0 - crowded * 45.0; // crowded bins -> new bin becomes attractive
        if fitting_bins_count > 2 {
            score -= 10.0;
        }
        // early stream: consolidate, avoid bin explosion
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 12.0;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (pick the emptiest bin when residuals are large, tightest when small).
    let dev = bin_residual as f64 - mean_residual;
    score -= (dev / cap) * 4.0;

    // Slight preference to keep number of open bins low.
    score += open_bins_count as f64 * 0.15;

    // Harmonic threshold: items leaving residual in [1..15] are dead zones
    if post_residual >= 1 && post_residual <= 15 {
        score += 6.0 * (16 - post_residual) as f64 / 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize tiny unusable gaps harshly
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight packing: larger item fraction -> lower score
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Pressure from number of open bins: with many bins open, prefer filling existing ones
    score += open_bins_count as f64 * 1.2;

    // Lookahead: if the next item also fits in the post residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // residual too small for lookahead item -> mild penalty for wasted compatibility
        score += 5.0;
    }

    // Alignment with mean residual: bins deviating far below mean residual are "worn out"
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: penalize so a fresh bin is opened only when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        // New empty bin candidate: only attractive if no existing bin fits well.
        let desperation = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let poor_fit_everywhere = if fitting_bins_count == 1 && (bin_residual as f64 - item_size as f64) < next_item_size as f64 && next_item_size > 0 { 40.0 } else { 0.0 };
        return 120.0 - desperation - poor_fit_everywhere + post_residual as f64 * 0.5;
    }

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near-perfect match (small slack left that likely becomes dead space anyway).
    else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 25.0;
    }
    // Dead space: next item cannot use the remainder.
    else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize proportionally to wasted space, harsher late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * progress);
    }

    // Reward bins tighter than the fleet average (good packing density).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild preference for many open bins consolidation late in the stream.
    if open_bins_count > 3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is already low, amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize post_residual that is too small to ever be useful again
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward heavily; if it just barely does not, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // next item would fit only if we DON'T place here — mild penalty
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize the fresh bin progressively
    // as open-bin fragmentation is low (mean residual high).
    if bin_residual == bin_capacity {
        let fragmentation_pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // If open bins are mostly full (low mean residual), new bin is fine.
        score += 60.0 * (1.0 - fragmentation_pressure) + 10.0;
        // Early in the stream, opening bins is cheap; later, avoid it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across too many open bins when residuals
    // are already small overall (encourage consolidation).
    if open_bins_count > 4 && bin_residual < bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if (bin_residual as f64) < avg {
            score += 4.0;
        } else {
            score -= 4.0;
        }
    }

    // Reward bins whose residual is a "good" size (divisible-ish chunks)
    // that likely match common item sizes.
    let r = post_residual;
    if r >= 10 && r <= 100 && (r % 10 == 0) {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: normalized post residual (wasted space)
    let mut score = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more
    let t = progress;
    let poly = 1.0 + 2.0 * t * t + 1.5 * t * t * t;
    score += poly * (pr / cap) * (pr / cap);

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= 0.5 * t * (1.0 - pr / cap);

    // Penalize bins whose residual deviates strongly from mean residual
    // (keep residual pool homogeneous for future items)
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.0 + 0.5 * t;
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 0.6 * (1.0 - slack) * (1.0 + t);
        } else {
            score += 0.4 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across too many open bins early
    score += 0.02 * (open_bins_count as f64) * (1.0 - t);

    // New-bin candidate bias: slightly discourage opening a new bin unless
    // the fit into existing bins would be terrible
    if bin_residual == bin_capacity {
        score += 0.35 + 0.3 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect-fit classes get strong rewards.
    let zero_fit = post_residual == 0;
    let small_fit = post_residual <= 10;
    let mid_fit = post_residual > 10 && post_residual <= 30;

    if zero_fit {
        score -= 500.0; // perfect packing: always reward
    } else if small_fit {
        score -= 120.0;
    } else if mid_fit {
        score -= 30.0;
    } else {
        // large dead space: penalize proportionally to wasted capacity fraction
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac;
    }

    // Integer-division thresholds on post_residual: classify leftover into harmonic bands.
    let band = post_residual / 25; // 0..=4 bands
    score += band as f64 * 8.0;

    // Coupling with next_item_size: if the lookahead item can exactly fill post_residual,
    // this bin is extremely valuable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            if rem2 <= 10 {
                score -= 60.0; // two-step near-perfect packing
            } else {
                score += rem2 as f64 * 0.5;
            }
        } else {
            // next item cannot use the leftover at all: mild penalty scaled by mismatch
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Modulo arithmetic: bins whose residual is a "nice" fraction of capacity
    // (multiples of 10, 20, 25) are easier to fill later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a good fit (post_residual large) or the stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // penalize new bins moderately; relax penalty when open bins are fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 60.0 + 40.0 * (1.0 - progress) + 0.2 * open_bins_count as f64 - 0.1 * fragmentation;
    }

    // Tight-fit bonus: item nearly fills the bin (residual before was small).
    if bin_residual - item_size < item_size / 2 && post_residual > 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. A residual gap is "dead" if it is smaller than
    // the minimum plausible item size (assume >= 5) but nonzero.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 5.0 {
        score += 40.0 * (5.0 - gap);
    } else if gap == 0.0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Penalize leaving a gap that cannot fit the next item (lookahead waste),
    // but reward a gap that exactly accommodates it.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if gap >= next && gap < next + 5.0 {
            score -= 25.0; // gap reserved nicely for next item
        } else if gap > 0.0 && gap < next {
            score += 12.0; // gap too small for the known next item
        }
    }

    // Tight-fit reward: prefer bins where the item fills a large fraction of
    // the available residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidation into
    // existing bins; a new empty bin should only win when fits are bad.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above typical good fits,
        // growing with the number of already-open bins.
        score += 20.0 + 6.0 * pressure;
        // Late in the stream, discourage spawning extra bins.
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 5.0 + pressure;
    }

    // Mild attraction toward bins whose residual is near the mean residual
    // (keeps the bin pool homogeneous and predictable).
    score += 0.15 * (gap - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.07;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fit_ratio * fit_ratio * (bin_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Lookahead coupling: reward if leftover residual can host the next item,
    // penalize residuals that are just barely too small for the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // residual too small for next item: dead space penalty scaled by how close it is
            let closeness = 1.0 - (next_item_size - post_residual) as f64 / 100.0;
            score += 6.0 * closeness;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 0.15 * (mean_residual);
    }

    // New-bin candidate handling: empty bin should only win when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, softened when many items remain
        // and current open bins are fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64 * 0.6
            + 20.0 * (1.0 - fragmentation)
            - 15.0 * progress
            - if next_item_size == 0 { 5.0 } else { 0.0 };
        // if item fits snugly in a fresh bin (large item), new bin is more attractive
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.02 * open_bins_count as f64;

    // Prefer using bins with larger residuals less (keep big holes for big items).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = pr * (1.0 + 0.9 * pr / cap);

    // Smooth polynomial coupling: residual waste penalized more as stream progresses.
    let x = pr / cap;
    let waste = x * x * (1.0 - x);
    score += 120.0 * waste * (0.4 + progress);

    // Reward tight fits (small post residual relative to item size) with smooth term.
    let tightness = it / cap;
    score -= 15.0 * tightness * (1.0 - x) * (1.0 - x);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits into post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward mid-sized dead space.
        score += 10.0 * (1.0 - progress) * (pr / cap);
    }

    // New-bin candidate: make it attractive only when the item is large relative to
    // remaining space in typical open bins (smooth in mean_residual).
    if bin_residual == bin_capacity {
        let squeeze = mean_residual / cap;
        score += 25.0 * (1.0 - squeeze) - 30.0 * (1.0 - progress) * (1.0 - squeeze);
        // Penalize opening bins when many already fit the item.
        score += 5.0 * (fitting_bins_count as f64);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.4 * (open_bins_count as f64) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Dead-space penalty: residuals that are small but not tiny are worst
    // (too small for typical items, wasted capacity). Harmonic classes of 10.
    let class = post_residual / 10;
    match class {
        0 => { score -= 12.0; }        // perfect/near-perfect fill
        1 => { score += 8.0; }         // awkward sliver
        2 => { score += 4.0; }
        3 => { score += 1.0; }
        4 => { score -= 2.0; }
        5 => { score -= 4.0; }         // half-full leftover is reusable
        6 => { score -= 3.0; }
        7 => { score -= 2.0; }
        8 => { score -= 1.0; }
        _ => { score -= 0.5; }
    }

    // Reward tight fits scaled by how many bins compete for the item.
    if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it, unless residual after is tiny-but-unusable.
        score -= 15.0;
        if post_residual > 0 && post_residual < 10 {
            score += 5.0; // creates a dead sliver, but still better than new bin
        }
    } else {
        // Competing bins: prefer the tightest fit.
        score -= (fitting_bins_count as f64).min(6.0) * (1.0 - frac) * 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nfrac = next_item_size as f64 / post.max(1.0);
            // reward when next item would fill most of the leftover
            if nfrac > 0.7 { score -= 8.0 * nfrac; }
            else if nfrac < 0.2 && post_residual < 20 { score += 3.0; }
        } else {
            // next item cannot fit here; mildly penalize hoarding space it can't use
            let over = (next_item_size - post_residual) as f64;
            if over < 15.0 { score += over * 0.4; }
        }
    }

    // New-bin candidate logic: empty bin should only win when no good existing option.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with stream progress (waste matters more early? no—
        // late in stream, remaining items few, so reuse matters less).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 6.0 * progress;
        // But if the item is large and mean residual is low, new bin is attractive.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // room to pair items in the fresh bin
        }
    }

    // Mild preference for balancing mean residual: avoid dumping into the fullest bin
    // when many bins are open.
    if open_bins_count > 4 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Modulo harmony: residuals that are multiples of common item sizes are more reusable.
    for m in [10u32, 20, 25, 50].iter() {
        if post_residual % *m == 0 && post_residual > 0 {
            score -= 2.0;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (they are effectively wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 8.0; // likely dead space
    }

    // Reward tight fits (post_residual near zero is good, so subtract).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; slight penalty for leaving awkward gap
        score += 3.0;
    }

    // Mean residual coupling: penalize bins far above the mean residual
    // (wasteful placement) mildly, reward below-mean usage.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Give it a mild bonus so it beats truly terrible fits, but not tight fits.
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward if next item fits the post_residual exactly well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward proportional to how well it matches
            let match_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * match_quality;
        } else {
            // Next item won't fit after this placement: penalize wasted potential
            let overflow_gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (overflow_gap / bin_capacity as f64).min(1.0);
        }
    } else {
        // Last item: just minimize post residual
        score -= 5.0;
    }

    // Compare post_residual relative to mean residual of open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel); // tighter than average: good
        } else {
            score += 6.0 * (rel - 1.0).min(1.5); // looser than average: bad
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin early in stream or when few bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins with less residual overall (fill fuller bins first)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize tiny dead space that nothing (min size 1) can still use usefully,
    // but reward zero residual strongly (perfect closure).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 8.0; // awkward dead space
    }

    // Lookahead: if the next item fits exactly into the post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 3.0;
        }
    } else {
        // Last item: prefer closing bins completely.
        score -= post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += pressure * 2.0;

    // Mean residual coupling: if this bin is much tighter than average, prefer it.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // New-bin candidate (empty bin): penalize unless current bins are too full/fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        // If mean residual across open bins is small, opening a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 35.0;
        }
    }

    // Mild time decay: early in the stream, keep bins open and flexible;
    // late in the stream, prioritize filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling: dead space penalized super-linearly as stream progresses.
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (0.5 + progress);
    score += 25.0 * norm_post * norm_post * norm_post;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 30.0 * (1.0 - gap / cap);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (fill fuller bins first).
    score += 0.3 * (post - mean_residual);

    // New-bin candidate: keep it competitive only when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score = 55.0 + 40.0 * fragmentation * (1.0 - progress) - 25.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= 0.5 * cap {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 defines a class.
    // Classes with residual ≡ 0 (perfect fit) are heavily rewarded.
    let rem = post_residual % 10;
    if rem == 0 {
        score -= 12.0; // perfect harmonic class: excellent fit
    } else if rem <= 3 {
        score += 2.0 * (3 - rem) as f64; // small dead space, mild penalty
    } else {
        score += (rem as f64) * 0.6; // mid-class dead space penalty
    }

    // Integer-division thresholds on post_residual: how many items of size 10 could still fit.
    let slots = post_residual / 10;
    score -= slots as f64 * 1.5;

    // Tightness ratio: fraction of bin used by this placement.
    let fill = item_size as f64 / cap;
    score -= fill * 8.0;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // harmonic class match between post_residual and next item (mod 10)
            if next_item_size % 10 == rem {
                score -= 5.0;
            } else {
                score += 1.0;
            }
        } else {
            // next item cannot fit here; residual likely becomes dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin starts with high base score,
    // only attractive when current bin residuals are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // penalize opening new bins early in the stream or when few bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 10.0;
        score += 3.0 * (open_bins_count as f64).ln().max(0.0);
        // but if mean residual is small (all bins nearly full), new bin is fine
        score -= (mean_residual / cap) * 20.0;
    } else {
        // Prefer bins whose residual is closest to a harmonic class boundary
        let frac = bin_residual as f64 / cap;
        if frac < 0.25 {
            score += 4.0; // nearly-full bin: using it is valuable
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // minimum item size are wasted forever -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: small usable leftover is good.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only open bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 12.0;
    }

    // Open-bins pressure: penalize spreading across many bins slightly,
    // scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + 2.0 * progress) * 0.05;

    // Prefer bins below mean residual (keep large residuals for big items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fit).
    score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chaining, huge reward
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.15 * slack;
            if slack == 0.0 {
                score -= 20.0; // another perfect fit after chain
            }
        } else {
            // Next item will NOT fit here: penalize dead space, more so late in stream.
            score += 10.0 + 25.0 * progress;
        }
    }

    // Relative-to-mean residual coupling: bins with unusually small residual
    // are nearly full -> good to fill them; bins with large residual vs mean
    // should stay flexible for future items.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 12.0 * (1.0 - rel); // nearly full bin, prioritize
        } else if rel > 1.5 {
            score += 8.0 * (rel - 1.5); // keep roomy bins flexible
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New empty bin candidate: only attractive when the item is large relative
    // to capacity (poor fit anywhere else) or no real alternative exists.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * (0.35 + 0.6 * (1.0 - size_frac));
        if fitting_bins_count <= 1 {
            score -= 25.0; // few alternatives -> opening a new bin is fine
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual == bin_capacity - item_size {
            score -= 15.0; // fresh bin can chain the next item too
        }
    }

    // Mild tie-break: prefer bins among many fitting ones slightly less crowded state.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: early on, be greedy/tight; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize when post_residual is small but nonzero dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fit
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else {
        // Penalize large dead space quadratically, scaled by remaining stream length.
        let waste = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += waste * 60.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item could fit into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        }
        // If next item would exactly fill post_residual, big reward.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Global state: prefer bins with below-average residual (fill emptier-tight bins first),
    // but mild, so we don't fragment.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Crowd control: when many bins are open, discourage opening new ones implicitly
    // by rewarding existing bins slightly more.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    } else {
        // New-bin candidate: penalize unless current item is large and no good fit exists.
        score += 5.0;
        if item_size > bin_capacity / 2 && (fitting_bins_count == 0 || post_residual > 40) {
            score -= 15.0;
        }
    }

    // Mild time-horizon modulation: later items favor filling existing bins harder.
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a non-linear
    // polynomial coupling between post_residual and stream progress.
    // Early in the stream, leftover space is more reusable; late in the
    // stream, dead space is more costly, so we amplify it super-linearly.
    let dead_space = post / cap;
    let progress_amplifier = 1.0 + 1.5 * progress * progress;
    let mut score = post * (1.0 + dead_space * progress_amplifier);

    // Smooth occupancy coupling: bins far below the mean residual are
    // less attractive (their space is better saved), bins above the mean
    // residual are attractive fill targets. Cubic smooth interaction.
    let deviation = (mean_residual - post) / cap;
    score += 8.0 * deviation * deviation * deviation;

    // Last-chance bonus: if this is the only fitting bin, strongly reward
    // using it instead of opening a new bin (smoothly scaled by tightness).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let tightness = 1.0 - (post_residual as f64) / cap;
        score -= 25.0 + 40.0 * tightness * tightness;
    }

    // Lookahead: reward bins whose post_residual can still host the next
    // item exactly or with small waste; penalize residuals that strand
    // the next item just barely. Smooth quadratic coupling.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = post - nx;
        if slack >= 0.0 {
            // next item fits too: reward, more so mid-stream
            score -= 10.0 * (1.0 - slack / cap) * (0.5 + progress);
        } else {
            // next item won't fit here: mild penalty proportional to how
            // close we are to fitting (near-miss = wasted potential)
            let near_miss = 1.0 + slack / nx; // in (0,1]
            score += 6.0 * near_miss * near_miss;
        }
    }

    // Mild penalty for proliferating bins when plenty of open bins exist.
    score += (open_bins_count as f64).ln().max(0.0) * dead_space * 4.0;

    // New-bin candidate: an empty bin gets a neutral-ish but not dominant
    // score; it should only win when all fitting bins are poor fits.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score: f64;

    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: only attractive when the item is large
        // relative to capacity (would otherwise leave big dead space anyway).
        let frac = item / cap; // 0..1
        let mut nb = (cap - item) * 1.5; // base cost of opening a bin
        nb -= 30.0 * frac * frac;        // reward large items
        if item_size >= (bin_capacity * 3 / 4) {
            nb -= 25.0; // big item: new bin is often optimal
        }
        if item_size <= (bin_capacity / 4) {
            nb += 40.0; // tiny item in a fresh bin is wasteful
        }
        // late in the stream, closing out is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb -= 10.0 * progress;
        score = nb;
    } else {
        // Core tightness term: quadratic waste penalty
        score = post * post / cap;

        // Harmonic class logic on post_residual: bins whose residual falls in
        // "reusable" classes (multiples of 25) are more valuable to preserve.
        let class = post_residual % 25;
        score += match class {
            0 => -8.0,           // perfectly reusable residual class
            1..=5 => 2.0,        // near-perfect: slightly favored
            6..=15 => 6.0,       // awkward middle class
            _ => 3.0,            // small slivers
        };

        // Integer-division thresholds: residual that can hold exactly one more
        // small/medium item is a good stopping point.
        if post_residual >= 10 && post_residual < 20 {
            score -= 3.0;
        }

        // Lookahead: reward if next item fits exactly in the post residual,
        // penalize if it creates a near-miss (dead space of 1..5).
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if next_item_size == post_residual {
                score -= 20.0; // perfect chaining
            } else if next_item_size < post_residual {
                let gap = post - nxt;
                score += gap * gap / cap; // leftover after chaining
                if gap <= 5.0 {
                    score -= 4.0; // near-perfect chain still good
                }
            } else {
                score += 2.0; // next item won't fit here anyway
            }
        }

        // Last-chance bin: strongly prefer using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Mild pressure to consolidate when many bins are open.
        if open_bins_count > 4 {
            score -= 0.5 * (open_bins_count.min(20) as f64).sqrt();
        }

        // Prefer bins below mean residual (they're the tightest, most at risk).
        score += 0.3 * (mean_residual - post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Open-bin pressure: penalize creating many open bins mildly.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Dead space is worse late in the stream when few items remain to fill it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += 20.0 * progress;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0 * progress;
    }

    // New-bin candidate: prefer using existing bins unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
    }

    // Slight preference for bins with lower residual than mean (good packing zones).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 60.0 * fill_ratio * fill_ratio;

    // Perfect-fit bonus for near-exact residual consumption.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if the next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // Next item fits: penalize leftover slack after the lookahead item.
            score -= 50.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack <= 5 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize small post residuals (dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // penalize very roomy bins to preserve them for large future items.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 10.0;
    } else if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Discourage opening a new bin when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But allow new-bin opening early in the stream or when open bins are crowded.
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Slight stream-progression pressure: later in the stream, be more conservative
    // about spreading items across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score += (post_residual as f64).powf(1.35) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0 + item_size as f64;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + next_item_size as f64 * 0.8;
    }
    // If next item would exactly fill post_residual, huge reward (perfect packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Penalize leaving a residual that is too small for the next item (dead space trap),
    // scaled by how close we are to the end of the stream (dead space matters less late).
    let t = step_index as f64 / (total_items.max(1) as f64);
    if next_item_size > post_residual && post_residual > 0 {
        score += 40.0 * (1.0 - t);
    }

    // Prefer filling bins with larger residuals relative to the fleet mean
    // (balance: don't starve one bin while others stay full).
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // Penalize spreading across many open bins when few remain that can fit.
    score += open_bins_count as f64 * 0.3;

    // Early in the stream, be more willing to open new bins for large items;
    // late in the stream, consolidate aggressively.
    score += t * post_residual as f64 * 0.6;

    // New empty bin candidate: only attractive when the item is large or
    // no open bin fits well (post_residual small means tight fit elsewhere).
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64);
        score -= 50.0 * tightness; // large items: new bin is fine
        score += 80.0 * (1.0 - t); // early stream: new bins are cheap
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 30.0; // don't open a bin that traps the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: tolerate larger residuals (bins stay flexible). Late: punish residuals hard.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * p2 + 3.0 * p3) * cap;
    score += 0.35 * coupling;

    // Smooth reward for tight fits (small post_residual), stronger as stream progresses.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 8.0 * tightness * (0.5 + progress);

    // Penalize the brand-new empty bin candidate mildly, ramping down late in stream
    // (late in stream, reusing open bins is preferred to open new ones).
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    score += is_new_bin * (30.0 - 25.0 * progress);

    // Lookahead: if next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gap_norm = gap / cap;
        score += 0.5 * gap_norm * cap * (1.0 - 0.5 * progress);
        // Reward if next item fits at all in this bin after placement.
        let fits_next = (pr >= nxt) as f64;
        score -= 6.0 * fits_next * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (0.5 + progress);
    }

    // Penalize bins whose residual deviates from mean residual (fragmentation signal),
    // with smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap * (0.3 + 0.7 * p2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins are 100 capacity; classify
    // post_residual into integer-division buckets (dead-space classes).
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => score -= 40.0,                    // near-perfect fit: strongly reward
        1 => score -= 25.0,                    // excellent fit
        2 => score -= 12.0,                    // good fit
        3 | 4 => score -= 4.0,                 // decent fit
        5 | 6 => score += 6.0,                 // mediocre: leaves half-ish bin
        7 => score += 14.0,                    // poor
        8 => score += 22.0,                    // bad dead space
        _ => score += 30.0,                    // nearly empty bin used wastefully
    }

    // Modulo arithmetic on post_residual: residues that pair well with common
    // item sizes (multiples of 10/20) are more reusable.
    let r = post_residual % 10;
    if r == 0 {
        score -= 8.0; // clean multiple of 10: high chance next item fits
    } else if r >= 7 {
        score += 5.0; // awkward residue, likely dead space
    }

    // Lookahead coupling: if next item exactly fits post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (15.0 * (1.0 - slack as f64 / 50.0)).max(0.0);
        } else {
            // next item cannot fit here: slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64 * 0.15).min(20.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit
    // is very poor or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual < 20;
        if poor_fit {
            score -= 10.0; // allow fresh bin when nothing fits well
        } else {
            score += 45.0 + 40.0 * (1.0 - progress); // discourage early bin sprawl
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mean residual context: when open bins are on average roomy, tighten
    // selection pressure toward the emptiest-but-usable bins.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but gaps < 8 are practically unusable given typical stream granularity).
    if post_residual > 0 && post_residual < 8 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else if post_residual < 20 {
        score += 15.0; // nearly dead space
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0; // post residual likely wasted relative to lookahead
    }

    // New-bin candidate handling: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            let min_gap_needed = item_size as f64 * 1.6;
            ((mean_residual - min_gap_needed).max(0.0)) / 10.0
        };
        score += 35.0 + desperation + 0.8 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the last-chance bin
        }
    }

    // Mild late-stream tightening: consolidate as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted space relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(50.0);
        }
    }

    // Compare against mean residual: bins below mean residual are precious
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit_elsewhere = (bin_capacity as f64 - item_size as f64) < mean_residual;
        if pressure > 0.0 || (poor_fit_elsewhere && fitting_bins_count > 1) {
            score -= 20.0; // open new bin when open bins are bad fits
        } else {
            score += 30.0; // discourage new bin when decent fits exist
        }
    }

    // Mild stream-phase modulation
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post residuals.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 3.0 * fit_ratio * (bin_residual as f64);

    // Penalize dead space that is too small for the smallest plausible item,
    // but only if the lookahead item cannot use it either.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        } else {
            // Reward bins where the next item can also fit (chained packing).
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it is only
    // chosen when existing bins would create heavy fragmentation.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Early in the stream, opening bins is cheap; later, be conservative.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 4.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual means we
    // should consolidate into existing bins rather than spread out.
    let consolidation_pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 10.0);
    if bin_residual < bin_capacity {
        score -= consolidation_pressure;
    } else {
        score += consolidation_pressure;
    }

    // Waste penalty: leftover space below the typical small item threshold is dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild preference for fuller bins overall.
    score -= 0.5 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling: post_residual normalized to [0,1]
    let x = post / cap;
    // Dead-space penalty grows super-linearly for small residuals (hard-to-fill slivers)
    score += 18.0 * (1.0 - x) * (1.0 - x) * x * x;

    // Stream progress: later in the stream, prefer tighter packing (amplify small post_residual reward)
    let progress_coupling = 0.5 + 1.5 * progress * progress;
    score -= 6.0 * progress_coupling * (1.0 - x * x);

    // Mean residual interaction: if bin residual is far below mean, it's a good tight fit
    let rel_mean = mean_residual / cap;
    score += 4.0 * (x - rel_mean) * (x - rel_mean);
    score -= 3.0 * (rel_mean - x).max(0.0);

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = (post - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item
        score += 5.0 * (1.0 - x);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless existing bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (fitting_bins_count as f64).max(1.0);
        let tight = (mean_residual / cap).max(0.0);
        score += 25.0 - 20.0 * tight - 6.0 * (crowding - 1.0).min(3.0);
        // Early stream: opening bins is fine; late stream: avoid fragmentation
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0..1 fraction of capacity left

    // Dead-space penalty grows superlinearly for tiny, unusable residuals.
    if pr == 0 {
        score -= 1000.0; // perfect fit — strongly favored
    } else if pr < 10 {
        score += (10.0 - pr) * 8.0; // nearly-dead space penalty
    } else if pr <= 20 {
        score += 5.0;
    }

    // Harmonic bands: reward residuals that align with "useful" size classes
    // (multiples of capacity quarters / eighths).
    let band = (pr / 10).min(10) as f64; // integer-division class 0..10
    score -= band * 2.0; // larger residual classes slightly favored (more usable)

    // Modulo-structure: residuals congruent to common item sizes (10..80 mod 100)
    // are more likely to be filled by future items.
    let mut harmonic_bonus = 0.0;
    for k in 1..=8u32 {
        let cls = k * 10;
        if pr == cls || pr == cls + 5 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus;

    // Fractional-capacity coupling: residuals close to 1/3 or 1/2 capacity are valuable.
    let half = (pr as i32 - 50).abs() as f64;
    let third = (pr as i32 - 33).abs() as f64;
    score -= 10.0 / (1.0 + half);
    score -= 6.0 / (1.0 + third);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + slack);
        } else {
            // next item can't use this residual — penalize proportionally
            score += (next_item_size as f64 - pr).min(30.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are badly fragmented
    // or stream is early with many items left.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - pr).abs()
        } else {
            0.0
        };
        // penalize opening new bin normally...
        score += 60.0;
        // ...unless current best fits are poor (high mean residual mismatch) and
        // plenty of stream remains.
        score -= fragmentation * 0.8 + (1.0 - progress) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Tight-fit reward: filling most of the bin now is good.
    let fill_ratio = item_size as f64 / c;
    score -= fill_ratio * 15.0;

    // Mild penalty for proliferating bins when mean residual is still high.
    score += open_bins_count as f64 * 0.3 * (mean_residual / c).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize "dead space": small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (post_residual near zero is ideal).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize wasteful placements in mostly-empty bins (low fill fraction).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score += (1.0 - fill) * 15.0;

    // Open-bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.8;

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (best-fit-like behavior), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: treat leftover as dead space.
        score += post_residual as f64 * 0.5;
    }

    // New-bin candidate: score a fresh bin based on stream progression and crowding.
    // Early / uncrowded: opening a new bin is cheap; late / crowded: discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + progress * 60.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item also fits in the leftover space, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportional to how well next item matches the leftover.
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: leftover too small for the next item -> penalize.
        let waste = post_residual as f64;
        score += waste * 1.5;
    }

    // Compare against mean residual: bins with less residual than average are
    // "tighter" and should be preferred for filling.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it unattractive unless it's the only option,
    // i.e. no open bin fits (handled by fitting_bins_count == 0 case implicitly
    // since other calls won't exist). Penalize opening new bins when alternatives exist.
    if bin_residual == bin_capacity {
        score += 200.0;
        // Late in the stream, opening a fresh bin is less costly (fewer future items to strand).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 100.0;
    }

    // Mild preference for tighter bins overall.
    score += (bin_capacity - bin_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 6.0 + 0.15 * (nxt - post_residual as f64);
        } else {
            // Reward bins whose leftover can still serve the next item.
            score -= 3.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        }
    } else {
        // Last item: any bin that fits is fine; strongly prefer filling existing bins.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.1 * item_size as f64;
        if (post_residual as f64) < 10.0 {
            score -= 10.0; // near-perfect fill
        }
    }

    // New-bin candidate handling: empty bin gets a penalty that shrinks when
    // open bins are scarce or residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score += 18.0
            - 8.0 * fragmentation
            - 10.0 * scarcity
            - 4.0 * progress;
    }

    // Slight preference for bins below mean residual (balance load, keep
    // large residuals available for large future items).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Early stream: be more conservative about filling bins poorly since many
    // items remain; late stream: just fill anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), non-linearly coupled with progress
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial interaction: dead-space penalty grows with progress
    let dead = norm_post * norm_post;
    score += 40.0 * dead * (0.5 + progress);

    // Reward exact-ish fits more strongly late in the stream
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness * (1.0 + progress);

    // Lookahead coupling: penalize post-residual that cannot fit next item smoothly
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64) - (next_item_size as f64)).abs() / cap;
        score -= 10.0 * fits_next * (1.0 - gap * gap);
        score += 8.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild pressure against opening new bins when many bins are open
    score += (open_bins_count as f64).ln() * 3.0 * (1.0 - progress);

    // New-bin candidate should lose unless residuals are heavily fragmented
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity-fraction bucket it falls in.
    let item_class = (item_size * 4) / bin_capacity; // 0..3 (small, medium, large, huge)
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward tight fits: post_residual near zero is good, but a tiny sliver
    // (dead space < 10) is wasted — penalize slivers strongly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual <= 20 {
        score -= 15.0; // still a decent slot for small items
    }

    // Harmonic pairing: if the lookahead item fits exactly into the post residual,
    // this placement completes a perfect 2-item bin — big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item fits: mild reward scaled by how well it fills the remainder
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * fill;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this bin's remainder — the residual is more likely dead
        score += 10.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // sizes (multiples of 10/20/25) are more reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 10 != 0 && post_residual % 5 != 0 {
        score += 5.0; // awkward remainder
    }

    // Class coupling: large item into a bin leaving a large-class residual is bad
    // (residual too big to waste, too small for another large).
    if item_class >= 2 && post_class >= 2 && post_residual < 50 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has neutral utility; make it
    // slightly worse than a good fit but better than a terrible one.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).ln().max(0.0) * 5.0;
        // discourage hoarding many open bins when stream is early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild preference to consolidate: keep mean residual low across bins.
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable follow-up item are wasted forever. Penalize hard.
    let dead_threshold: u32 = 12;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits generally (post_residual small relative to residual).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover: mild extra penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure * 0.5;
    } else {
        // New-bin candidate: penalize opening a bin, more so late in the
        // stream and when many bins are open; relax if mean residual is
        // very low (all existing bins nearly full).
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 15.0 + pressure + 20.0 * mean_tight;
    }

    // Mild attraction toward bins whose residual is close to the mean
    // (balances load across open bins).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match between post_residual and next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 500.0; // chain fit: next item fills this bin exactly
        } else {
            score += diff * 2.0; // penalize mismatch with lookahead
        }
        // If next item cannot fit the post residual, dead space likely.
        if (next_item_size as u32) > post_residual && post_residual > 0 {
            score += 30.0;
        }
    }

    // Relative to mean residual: prefer bins with residual near/below mean (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin is a bad fit.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score += 150.0 + waste * 1.5;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: must open new bin
        }
    }

    // Progress-based scaling: be more conservative (waste-averse) early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted fraction
    let waste_frac = post_residual as f64 / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // next item can also fit here -> very good chain
            let slack = post_residual as f64 - nxt;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // leftover dead space for next item: penalize proportionally
            let gap = nxt - post_residual as f64;
            score += 8.0 * (gap / cap).min(1.0);
        }
        // if next item fits exactly in post_residual, big reward
        if post_residual as u32 == next_item_size {
            score -= 35.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins with high mean residual: encourage consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = mean_residual - bin_residual as f64;
    // prefer bins with residual below the mean (denser bins)
    score += 5.0 * (residual_gap / cap).clamp(-1.0, 1.0);
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64 * waste_frac;
    }

    // Late in the stream: be more conservative, avoid fragmenting
    score += 10.0 * progress * waste_frac;

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin; shrink if many bins open or item large
        let mut open_cost = 55.0 + 20.0 * (1.0 - item_size as f64 / cap);
        if fitting_bins_count == 0 {
            open_cost -= 80.0; // no alternative
        }
        if next_item_size > 0 && next_item_size as f64 <= cap - item_size as f64 {
            open_cost -= 10.0; // new bin can chain next item
        }
        score = (post_residual as f64) + open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: quadratic penalty on post residual (waste), smoothed by stream progress
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * t) * cap;

    // Reward tight fits: strong when post residual is small relative to item size
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item * (0.5 + t);

    // Lookahead coupling: if next item fits into post residual, reward this placement
    if nxt > 0.0 && nxt <= pr {
        let fit_ratio = nxt / pr.max(1.0);
        score -= fit_ratio * fit_ratio * (10.0 + 20.0 * (1.0 - t));
    } else if nxt > 0.0 {
        // next item won't fit here: mild penalty scaled by leftover dead space
        score += (nxt - pr).min(cap) * 0.05 * (1.0 + t);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Penalize scattering when many bins are open relative to mean residual
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * mean_residual * 0.02;

    // New-bin candidate: keep it neutral-slightly-high unless open bins are nearly full
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * t + mean_residual * 0.05;
    }

    // Smooth non-linear interaction: cubic term coupling residual with progress
    score += norm_pr.powi(3) * cap * (1.0 - t) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands in a
    // "usable" residue class (>= 25, i.e. can host future mid-size items)
    // are rewarded; dead-space classes (< 10) are penalized.
    let dead = (post_residual < 10) as i32;
    let usable = (post_residual >= 25) as i32;
    score += dead as f64 * 18.0;
    score -= usable as f64 * 6.0;

    // Integer-division thresholds on post_residual (harmonic capacity fractions)
    let q = post_residual / (bin_capacity / 4); // 0..=3 quarter classes
    score -= q as f64 * 2.5;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward; if it fits at all, mild reward; if it cannot fit,
    // leftover is likely dead space -> penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic pairing: next item splits residual into two useful halves
            let pair = post_residual / next_item_size;
            score -= pair.min(3) as f64 * 1.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.12;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (post_residual < 15) as i32 as f64 * 8.0;
    }

    // New-bin candidate: penalize opening a fresh bin when a decent fit exists;
    // allow it when this bin would leave near-zero useful residual anyway.
    if bin_residual == bin_capacity {
        score += 14.0;
        if post_residual >= 20 && item_size <= bin_capacity / 2 {
            score += 10.0; // big item into fresh bin is fine
        }
    }

    // Tight fits are classic best-fit winners.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Stream progression: early on, keep bins open and flexible; late in the
    // stream, prefer closing bins out (tight packing matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Spread across open bins: if mean residual is high, many bins are loose;
    // prefer consolidating into fuller bins (low residual relative to mean).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score += (rel - 1.0) * 4.0;
    }

    // Modulo-10 harmonic class of item size: items in "5-tail" classes pair
    // well with complementary residuals; reward bins whose residual complements.
    let tail = item_size % 10;
    if tail != 0 && post_residual % 10 != 0 {
        score -= 1.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps are the worst outcome. Define a "dead zone":
    // residual too small to hold the smallest plausible item (1..=10).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Medium dead zones (11..=20) are risky: only usable by tiny items.
    if post_residual >= 1 && post_residual <= 20 {
        score += 25.0;
    }

    // --- Perfect-fit reward ---
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0; // near-perfect fit
    }

    // --- Lookahead coupling: does the next item fit this residual? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual is reusable by the next item: reward.
            score -= (next_item_size as f64) * 0.6;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Residual is dead for the next item: penalize proportionally.
            score += (post_residual as f64) * 0.4;
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that can take the item; avoid opening a new bin.
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer bins whose residual is most consumed.
        score += (bin_residual as f64) * 0.1;
    }

    // --- Open-bin pressure: discourage proliferation of bins ---
    score += (open_bins_count as f64) * 0.5;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // A fresh bin has full residual; make it attractive only when the
        // item leaves a large, reusable residual or nothing else fits well.
        if post_residual >= 50 {
            score -= 10.0;
        } else {
            score += 20.0; // opening a bin for a poor fit wastes capacity
        }
        // Early in the stream, opening bins is cheap; late, prefer packing.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // --- Mean residual alignment: prefer bins near the mean (balance) ---
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 40.0;
    }

    // Penalize dead space: post_residual too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: prefer bins with residual above mean
    // (concentrate waste in fewer bins, keep tighter bins for future items).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when fit is poor,
    // but allow it when the current bin would leave awkward residual vs next item.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            // empty bin perfectly matches next item only if item fills it; keep penalty
        }
        if next_item_size > 0 && bin_residual as i64 - next_item_size as i64 >= 0 {
            score -= 10.0; // fresh bin can host the lookahead item too
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    } else {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post residual), with slight nonlinearity
    score = post_residual as f64 * (1.0 + (post_residual as f64 / bin_capacity as f64) * 0.5);

    // Lookahead: reward bins where the next item also fits into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - chain_quality / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // penalize leaving residual that no known next item can use
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open bins exist
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = bin_capacity as f64 - item_size as f64;
        score += 30.0 + waste * (0.5 + 0.5 * progress) + open_bins_count as f64 * 2.0;
        // but if open bins are all fragmented (low mean residual), new bin is fine
        if mean_residual < item_size as f64 * 0.6 {
            score -= 20.0;
        }
    }

    // Mild preference for filling bins below mean residual (consolidate fragmented bins)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: reward small post-residual via a smooth non-linear penalty
    let mut score = 2.5 * norm_pr.powi(2) + 0.6 * norm_pr;

    // Perfect fit bonus (smooth near-zero residual reward)
    score -= 3.0 * (1.0 - norm_pr).powi(6) * (1.0 - norm_pr);

    // Coupling: post-residual usefulness vs next item (k=2 lookahead)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            // residual can still host the next item: reward, stronger late in stream
            let tight = 1.0 - (gap / cap).powi(2);
            score -= 2.0 * tight * (0.4 + progress);
        } else {
            // residual cannot host next item: penalize dead space, more so early
            score += 1.2 * (gap / cap).abs().powi(2) * (1.4 - progress);
        }
    }

    // Scarcity: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 4.0;
    } else if fitting_bins_count > 1 {
        // spread demand: mild penalty to avoid over-concentrating on one bin
        score += 0.15 * (fitting_bins_count as f64).ln();
    }

    // Bin-count pressure: with many open bins, prefer filling existing ones
    score += 0.02 * (open_bins_count as f64).sqrt() * norm_pr;

    // Mean-residual coupling: penalize creating residual far from mean (fragmentation)
    score += 0.4 * ((pr as f64) - mean_residual).abs() / cap;

    // New-bin candidate: empty bin gets a mild base handicap so it only wins
    // when open bins would waste space; handicap fades as stream progresses
    if bin_residual == bin_capacity {
        score += 1.5 - 0.8 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 40.0;

    // Harmonic class of post_residual: dead space is worse when it cannot
    // plausibly hold a future item. Class residual by size buckets via
    // integer division (modular/harmonic classes on capacity).
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => score -= 30.0,           // near-perfect fit, excellent
        1 => score -= 15.0,           // 10-19 dead space, still usable
        2 => score -= 5.0,
        3 | 4 => score += 3.0,        // mid dead space, moderately bad
        5 | 6 => score += 10.0,       // 50-69: awkward zone
        7 => score += 2.0,            // 70-79: fits most items again
        _ => {}                       // 80+: nearly empty, neutral
    }

    // Modulo coupling: post_residual divisible by small moduli are "clean"
    // slots (likely to match future item sizes drawn on grids).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 12.0 - (slack_after_next as f64) * 0.15;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining: exact fill
        }
    }
    // Penalize if next item barely misses this bin (would strand space).
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).min(12.0) * 1.5;
    }

    // Mean residual coupling: bins tighter than the mean are worth filling.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // Progress: late in the stream, avoid opening bins with lots of slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to progress and slack.
        score += 20.0 + 60.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    } else if progress > 0.8 {
        score += frac * 30.0; // extra late-stage tightness pressure
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 100.0;
    }

    // Reward tight fits: the smaller post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins; favor filling existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the upcoming item.
        score += 15.0;
    }

    // Penalize placements leaving residual far below mean residual (fragmenting).
    if post_residual as f64 > mean_residual + 20.0 {
        score += 10.0;
    }

    // Slight preference for using partially filled bins over the fresh-bin candidate.
    if bin_residual < bin_capacity {
        score -= 5.0;
    } else {
        // New-bin candidate: add a fixed opening penalty so it's chosen only
        // when no open bin offers a decent fit.
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual), quadratic penalty for waste.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // 2-step lookahead: perfect match — post_residual equals next item size exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Strong reward for exact match (chain packing).
        if diff < 0.5 {
            score -= 60.0;
        } else if nxt <= pr {
            // Next item fits here: reward closeness, penalize leftover slack after next item.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            score += 0.2 * (pr - nxt);
        } else {
            // Next item won't fit here: mild penalty proportional to overflow gap.
            score += 0.15 * (nxt - pr);
        }
    } else {
        // Last item: maximize final fill.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are already tight;
    // filling them further is good. Above-mean bins get a mild penalty.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it
    // attractive only when no good fit exists (few fitting bins / large item).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let tight_fit = item_size as f64 / bin_capacity as f64;
        // Reward opening a new bin when item is large or alternatives are scarce.
        score -= 45.0 * scarcity * (0.5 + 0.5 * tight_fit);
        // Penalize opening a new bin early in the stream when many bins are open.
        score += 0.3 * open_bins_count as f64;
    }

    // Slight progression term: later in stream, prefer consolidating into open bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Exact-fill bonus: item perfectly consumes bin now.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to hold the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // wasted residual relative to what could have been used
            score += 0.35 * (post_residual as f64 - nxt).abs();
        } else {
            // residual can host the next item: bonus scaled by how well it fits
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 4.0 * (1.0 - slack);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New empty bin candidate: penalize unless no open bin fits or item is large.
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.4 * open_bins_count as f64;
        let pressure = if fitting_bins_count <= 1 { 40.0 } else { 0.0 };
        let big_item = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += base + pressure + big_item;
    }

    // Progress-based horizon: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / cap);

    // Global fragmentation pressure: if mean residual is high, prefer filling bins down.
    score -= 0.25 * (mean_residual / cap) * (bin_residual as f64 / cap) * 10.0;

    // Mild penalty for leaving very awkward residual slivers (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let next_fit = next_item_size as f64 / cap;

    // Base: penalize leftover, but discount small residuals via polynomial shaping
    let mut score = pr / cap;

    // Non-linear waste shaping: residuals that are too small to be useful are dead space
    let dead = (1.0 - pr / cap).powi(6);
    score += 0.8 * dead;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, prefer tighter packing (smaller post_residual) more strongly
    let coupling = pr / cap * (0.5 + 1.5 * progress * progress);
    score += 0.6 * coupling;

    // Reward high fill ratio with a smooth concave term
    score -= 0.5 * (1.0 - (1.0 - fit) * (1.0 - fit));

    // Lookahead: reward if next item fits smoothly into the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let snug = 1.0 - ((pr - next_fit * cap) / cap).abs();
            score -= 0.4 * snug;
        } else {
            // penalize leaving a residual that next item cannot use
            score += 0.3 * (next_fit - pr / cap).max(0.0);
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 0.5;
    }

    // New-bin candidate: make it unattractive unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        score += 0.9 + 0.5 * (1.0 - progress);
    }

    // Mild penalty when bin deviates from mean residual (balance pressure, smooth)
    score += 0.1 * ((pr - mean_residual) / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "reusable" residue classes (multiples of 10 / small residues) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit is the best outcome.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Residue class reward: leftover divisible by 10 pairs well with the
    // item-size alphabet; leftover in [1..9] is dead space.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 25.0;
    } else if r10 <= 3 {
        score += 15.0 * (4.0 - r10 as f64);
    }

    // Fractional capacity classes: leftover under 1/4 capacity is nearly dead.
    if post < cap * 0.25 {
        score += 30.0;
    } else if post < cap * 0.5 {
        score += 10.0;
    } else if post >= cap * 0.75 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            score -= 20.0 * (1.0 - (post - nxt) / cap);
        } else {
            // next item cannot follow here: penalize more when residual small
            score += 12.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, prefer it
    // heavily over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: opening a bin should only win when no decent fit
    // exists; make the empty-bin baseline moderately high but not extreme.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream, opening bins is cheaper (fewer future regrets).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * progress;
    }

    // Prefer tighter bins overall (small residual relative to mean residual).
    score += 0.5 * (mean_residual - post);

    // Modulo threshold on next item: large next items (harmonic class > 50)
    // need big residuals; reward bins that can host them.
    if next_item_size > 50 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Integer-division threshold: post_residual / item_size >= 2 means the
    // bin could hold another item of the same class — good.
    if item_size > 0 && post_residual / item_size >= 2 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for even the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Penalize post_residual that cannot hold the lookahead item when it could otherwise pair.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * next_item_size as f64;
    }
    // Reward a perfect two-item pairing with lookahead.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Open-bin pressure: prefer compacting into existing bins when many are open.
    score += 0.55 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Mean residual context: bins far below mean residual are more valuable to fill.
    score -= 0.10 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it attractive only when current bin would leave large dead space
    // and few bins are open; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let waste_if_used_here = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 14.0 + 0.4 * open_bins_count as f64 - 30.0 * waste_if_used_here * (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect (or near-perfect) fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item exactly fits the remaining space,
    // this placement is doubly attractive.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 20.0;
        }
        // Penalize leaving a residual that is slightly too small for the
        // next item (dead space trap).
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping larger residuals for future large items.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the fit would be very poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.25 * (open_bins_count as f64);
        // But allow a new bin if no existing bin fits well and lookahead
        // suggests a chain is starting.
        if fitting_bins_count == 0 && next_item_size > 0 && next_item_size > post_residual {
            score -= 18.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for
    // better long-run structure; late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post_residual).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible item can fill.
    // Items are 1..100, but a residual below the smallest item is pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual > 50 {
        // large leftover is fine only if bin was fresh; penalize proportionally
        score += 0.15 * (post_residual as f64 - 50.0);
    }

    // Lookahead: if the next item would no longer fit after this placement,
    // and no other bin could host it either, penalize blocking this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let progress = step_index as f64 / (total_items as f64).max(1.0);
            let urgency = if fitting_bins_count <= 1 { 25.0 } else { 8.0 };
            score += urgency * (1.0 - 0.5 * progress);
        } else {
            // bonus: this bin can chain two consecutive items (great packing)
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are
    // crowded or the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / 20.0;
        let poor_fit = (post_residual as f64) / (bin_capacity as f64); // = 1.0 for empty bin
        score += 45.0 + 10.0 * crowded * (1.0 - poor_fit) * 0.0 + 2.0 * open_bins_count as f64;
        // small time discount: late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 15.0 * (1.0 - progress);
    }

    // Global state coupling: prefer bins whose residual deviates favorably from mean.
    // Choose the bin that brings residuals closer together (balances workload).
    let new_gap = (post_residual as f64 - mean_residual).abs();
    let old_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.4 * (new_gap - old_gap);

    // Mild preference for fewer open bins when many are open.
    if open_bins_count > 10 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping
    let mut score = pr;

    // Quadratic-cubic polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 60.0 * poly * (0.5 + progress);

    // Penalize large dead space more as stream progresses (less time to reuse it)
    let dead = norm_pr * norm_pr;
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= 25.0 * (-pr / 12.0).exp() * (1.0 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // Mild pull toward bins near mean residual (keeps bin profile balanced)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: slight penalty so we prefer filling existing bins
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is "usable" by common item sizes
    // is less penalized than dead space in awkward residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Post-residual modulo classes: residuals divisible by 10 (or 5) are more likely
    // to be exactly filled by future items -> reward them.
    let class10 = (post_residual % 10 == 0) as i32;
    let class5 = (post_residual % 5 == 0) as i32;
    score -= 6.0 * class10 as f64;
    score -= 2.0 * class5 as f64;

    // Integer-division thresholds: small post_residual (< 10) is near-perfect packing.
    if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual,
    // this is a harmonic pair -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let nxt = next_item_size as f64;
            // reward tight fits, penalize leaving a bad residue after the pair
            let pair_res = post_residual - next_item_size;
            score -= 10.0 * (nxt / cap);
            score += 0.15 * (pair_res % 10) as f64;
            if pair_res > 0 && pair_res < 5 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by how much it overflows
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: empty bin gets a baseline that keeps it competitive
    // only when current fit is poor.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits, opening new bin is correct
        }
    }

    // Tight-fit reward: near-exact fill of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 20.0 * (fill_ratio - 0.9);
    }

    // Progress modulation: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * class10 as f64;
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Penalize residuals in awkward classes (e.g. 1 mod 10) that few items can use.
    let awkward = (post_residual % 10 == 1 || post_residual % 10 == 9) as i32;
    score += 4.0 * awkward as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Any post_residual that is too small to hold even a minimal item (1..=3)
    // is pure waste; penalize heavily.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0;
    }
    // Gaps too small for typical items (below the minimum plausible item size band)
    // are near-waste; scale penalty as gap shrinks toward zero.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits: smaller post_residual relative to item size is good.
    if item_size > 0 {
        score -= (item_size as f64 / (bin_residual as f64).max(1.0)) * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins and
    // encourage filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it's a "small hole" bin), favor filling it now.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.2;
    }

    // Lookahead: if the next item could use this bin's post_residual, reward
    // leaving exactly that much space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // moderately attractive only when the fit into existing bins is bad
    // (large post_residual) or late in the stream with few bins.
    if bin_residual == bin_capacity {
        let base = 15.0;
        // Opening a new bin is penalized when many bins are already open.
        let open_pressure = (open_bins_count as f64) * 0.8;
        // Late in the stream, prefer consolidating into open bins.
        let late_penalty = progress * 20.0;
        score += base + open_pressure + late_penalty;
        // But if the new bin would be filled very tightly by this item, it's fine.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead-space minimization).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * (fit_ratio - 0.85);
    }
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 55.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            // next item fits: reward proportionally to tightness
            score -= 35.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item would not fit: penalize large leftovers
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: opening a new bin is only attractive
    // if no open bin offers a decent fit; make fresh bin mildly costly.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else if post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
            // item is small relative to capacity; new bin wasteful
            score += 30.0;
        } else {
            score += 12.0;
        }
    }

    // Late in the stream, prioritize closing bins (reduce open-bin sprawl).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(6);

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Lookahead coupling: reward if next item fits into post_residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 18.0 * (slack_after_next as f64 / bin_capacity as f64);
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening is worse late in stream or when few bins are open with room.
        score += 55.0 - 20.0 * fragmentation - 25.0 * (1.0 - progress);
        // If mean residual is large and item is small, new bin is very wasteful.
        if mean_residual > item_size as f64 * 2.0 {
            score += 30.0;
        }
        // If current item is large and nothing fits well, allow new bin.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mild preference for bins with larger residuals among fitting bins (better packing).
    score -= 0.05 * bin_residual as f64;

    // Time-horizon modulation: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Penalize bins far below mean residual (wasteful usage pattern).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Quadratic dead-space penalty: small residuals are costly, scaled by progress
    let norm_pr = pr / cap;
    score += 12.0 * (norm_pr * (1.0 - norm_pr)) * (0.5 + progress);

    // Cubic coupling of post_residual with stream progress
    score -= 8.0 * (norm_pr - 0.5) * (norm_pr - 0.5) * (norm_pr - 0.5) * progress;

    // Reward tight fits: item_size relative to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: prefer bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap);
    }

    // Penalize deviation from mean residual (fragmentation spreading)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: slight penalty so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: quantize into capacity fractions (1/8ths).
    let class = (post_residual * 8 / bin_capacity.max(1)) as i64;
    // Dead-space penalty grows superlinearly for small residuals that nothing (>=1) can fill.
    if post_residual > 0 {
        let dead = 1.0 / (post_residual as f64).sqrt();
        score += dead * 8.0;
        // Perfect closure is excellent.
        if post_residual == 0 { score -= 60.0; }
    } else {
        score -= 60.0;
    }

    // Lookahead: reward residuals that can still host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.5;
        // Exact next-item fit is a strong harmonic pairing.
        if post_residual == next_item_size { score -= 20.0; }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize small unusable classes more.
        score += 10.0 + class as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Tie-break toward tighter bins when several fit.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate logic: empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Neutral-ish base so a genuinely good open bin beats it.
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        // Late in the stream, consolidating is cheaper than opening.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // If mean residual is large, prefer existing bins.
        score += mean_residual * 0.4;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is fine if next item can go anywhere
        }
    }

    // Coupling: penalize leaving residuals in awkward modulo classes (e.g. 3,5 of eighths).
    match class {
        1 => score += 12.0,
        3 => score += 8.0,
        5 => score += 8.0,
        7 => score += 4.0,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 are unusable by any item (min size 1,
    // but small gaps waste capacity) — penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin candidate and reward reusing crowded sets).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when this bin would leave bad dead space
    // or the fit is very poor relative to alternatives.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0 + 0.5 * open_bins_count as f64;
        // But if placing here would create unusable dead space, new bin becomes better.
        if post_residual > 0 && post_residual < 10 {
            score -= 35.0 * (10.0 - post_residual as f64);
        }
        // If the item fills a new bin well, opening is reasonable.
        if fill > 0.8 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward keeping this bin; if next item cannot use post residual, add mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += 5.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // penalize dumping into already-loose bins.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
    }

    // Penalize large leftover dead space relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Penalize very small post_residual (wasted sliver) unless it's a perfect fit
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 25.0;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate should lose unless open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * mean_residual.min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space: post_residual that is too small to ever fit
    // a typical item (assume min item ~10) is wasted.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate logic: only attractive when item is large relative to
    // capacity or current bins are crowded/poorly fitting.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let size_pressure = item_size as f64 / bin_capacity as f64;
        score += 25.0; // base cost of opening a new bin
        score -= 40.0 * size_pressure;
        score -= 3.0 * crowding;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Time horizon: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // Slight preference for bins with below-mean residual (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mean_r = mean_residual.max(0.0);

    // Base: penalize leftover space, smoothed non-linearly.
    let mut score = pr * (1.0 + 0.35 * progress);

    // Non-linear dead-space penalty: quadratic in normalized residual.
    let norm_post = pr / cap;
    score += 18.0 * norm_post * norm_post;

    // Reward tight fits: interaction between item size and post residual.
    let tightness = 1.0 - (pr / cap);
    score -= 10.0 * tightness * (fit / cap) * (1.0 + progress);

    // Lookahead coupling: if the post residual can host the next item, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: post residual likely dead space; penalize mildly.
        score += 4.0 * norm_post * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Crowd penalty: many open bins with large mean residual -> prefer consolidation.
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * crowd * (mean_r / cap) * (1.0 - progress);

    // New-bin candidate shaping: empty bin gets a smooth handicap that shrinks
    // only when the current fit into open bins is truly bad.
    if bin_residual == bin_capacity {
        let waste_if_open = pr; // == cap for new bin
        let bad_fit = (pr / cap) * (1.0 - (fit / cap));
        score += 15.0 + 10.0 * progress - 5.0 * bad_fit * (fitting_bins_count as f64).min(3.0);
        let _ = waste_if_open;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible into capacity fractions are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        // Reward residuals that are "harmonic" divisors of capacity (50, 25, 20, 10, etc.)
        if bin_capacity % post_residual == 0 {
            score -= 30.0;
        }
        // Reward residuals in the small-but-usable band (waste minimization)
        if post_residual <= 10 {
            score -= 25.0;
        } else if post_residual <= 20 {
            score -= 12.0;
        } else if post_residual > 60 {
            score += 15.0; // large leftover = likely dead space
        }

        // Lookahead coupling: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 200.0;
            } else if next_item_size < post_residual {
                let slack = post_residual - next_item_size;
                score -= 40.0 * (1.0 - slack as f64 / cap);
                // harmonic class of the resulting second-level residual
                if bin_capacity % slack.max(1) == 0 {
                    score -= 15.0;
                }
            } else {
                // next item won't fit here; mild penalty scaled by how much it overshoots
                score += 0.3 * (next_item_size - post_residual) as f64;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 60.0;
        }

        // New-bin candidate: penalize opening a new bin unless current fit is terrible
        if bin_residual == bin_capacity {
            score += 120.0;
            // but allow opening early when open bins are crowded with large residuals
            score += 0.2 * mean_residual;
            if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
                score -= 50.0; // big items pair well in fresh bins
            }
        }

        // Modulo-class tiebreak on post_residual quarters
        match post_residual % 4 {
            0 => score -= 2.0,
            1 => score += 2.0,
            2 => score -= 1.0,
            _ => score += 1.0,
        }

        // Stream progression: later in the stream, be greedier about tight fits
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (1.0 - pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened carelessly.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if the next item is large, opening a fresh bin now may be wise
        // when this placement would leave a big gap.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
    } else {
        // Reward bins whose post-residual can host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins tighter than average (good packing).
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    // Late in the stream, consolidate: penalize leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching: reward when post_residual matches next item exactly ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            // Slack between post_residual and next item: smaller gap = better.
            let gap = post_residual as f64 - next;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64); // near-perfect match strongly rewarded
            // Bonus if the gap is small enough that anything else would be wasted
            if gap < 10.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here: post_residual is dead space for the lookahead.
            // Penalize proportionally to how much of the bin is wasted.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 80.0 * waste;
            // Extra penalty when the next item is large (harder to place elsewhere).
            score += 0.3 * (next - post_residual as f64);
        }
    } else {
        // Last item: just minimize leftover space.
        score += 0.0;
    }

    // --- Tightness reward: prefer bins where the item fills a large fraction of residual ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // --- Relative to mean residual: bins tighter than average are more precious ---
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 15.0 * (1.0 - rel); // tighter-than-average bin favored
        } else {
            score += 10.0 * (rel - 1.0); // looser-than-average bin penalized
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are poor.
        // Default: make new bin unattractive so we pack existing bins.
        score += 120.0;
        // But if many open bins exist and none fit well (high mean residual waste),
        // relax the penalty slightly late in the stream.
        if open_bins_count > 3 && progress > 0.5 {
            score -= 40.0;
        }
        // If next item is huge and would need a fresh bin anyway, neutralize.
        if next_item_size > 0 && next_item_size as f64 >= 0.9 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Small dead-space penalty for very small post residuals (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract a fraction of the filled amount.
    let filled = bin_residual.saturating_sub(post_residual) as f64;
    score -= 0.35 * filled;

    // Penalize awkward dead space: residuals that are small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Lookahead: if the next item fits exactly or nearly in the post residual,
    // strongly favor this placement (creates a perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; tiny residuals become pure waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 20.0 * progress;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to the best available residual, or when open bins
    // are very fragmented (mean residual low but item barely fits anywhere).
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).min(3.0)
        } else {
            3.0
        };
        // Base cost of a fresh bin.
        score += 55.0;
        // If the item is huge and current bins fit poorly, opening is cheap.
        score -= 40.0 * fragmentation * (item_size as f64 / bin_capacity as f64);
        // Early in the stream, new bins are more acceptable (build diversity).
        score -= 25.0 * (1.0 - progress);
        // Many open bins: discourage adding yet another.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for filling bins whose residual is close to the mean
    // (keeps the pool of residuals homogeneous and packable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight time pressure: as the stream ends, favor tighter packing overall.
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Base: quadratic coupling of post-residual with stream progress.
    // Early on, prefer filling bins (low post_residual); late, tolerate slack.
    let mut score = pr_norm * pr_norm * (1.0 - progress) * 60.0
        + pr_norm * 20.0;

    // Smooth non-linear interaction: residual vs mean residual deviation.
    let mean_norm = mean_residual / cap;
    let dev = pr_norm - mean_norm;
    score += dev * dev * 15.0 * (0.5 + progress);

    // Reward tight fits with smooth exponential term.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fit_ratio * fit_ratio) * 10.0 * (1.0 - is_new_bin);

    // Lookahead coupling: penalize if next item cannot use post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (nx - pr).abs() / cap;
        score += gap * gap * 25.0;
        score -= usable * (1.0 - progress) * 8.0;
        // Reward leaving exactly room for next item (perfect pairing).
        let pair_err = (pr - nx).abs() / cap;
        score -= (1.0 - pair_err * pair_err) * 6.0 * usable;
    } else {
        // Last item: strongly prefer zero residual.
        score += pr_norm * 40.0;
    }

    // Last-chance bin bonus (only fitting bin): smooth sigmoid on scarcity.
    let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64).exp());
    score -= scarcity * 12.0 * (1.0 - is_new_bin);

    // Open bins pressure: more open bins -> mildly favor consolidation.
    let open_norm = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln().max(0.0);
    score += open_norm * pr_norm * 10.0;

    // New-bin candidate handling: smooth penalty unless post_residual is large
    // relative to a typical future need, scaled by progress.
    score += is_new_bin * (30.0 - 25.0 * (1.0 - (pr_norm * (1.0 - progress)).exp()));

    // Dead-space penalty: cubic in small residuals.
    if pr_norm < 0.25 {
        let d = (0.25 - pr_norm) / 0.25;
        score += d * d * d * 35.0 * (1.0 - is_new_bin);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class term: post_residual modulo 10 (dead-space granularity).
    // Small nonzero leftovers in awkward classes get a slight penalty.
    score += (post_residual % 10) as f64 * 0.15;

    // Penalize dead space: leftover too small to ever fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += 3.0 * waste_frac;
    }

    // Reward leaving room for the lookahead item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
        // Extra harmonic coupling: leftover exactly divisible into next item's class
        if post_residual % next_item_size.max(1) == 0 {
            score -= 1.0;
        }
    }

    // Last-chance bin: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: heavily penalize opening a fresh bin when alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + open_bins_count as f64 * 0.5 - 2.0 * progress;
    }

    // Prefer tighter bins (below mean residual) to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range)
    // are pure waste. Penalize the "unusable gap" zone super-linearly.
    if post_residual > 0 {
        // gap below 10 can never host an item (min size 1, but tiny gaps are
        // statistically dead); gap < item_size threshold handled by feasibility.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 15.0 * (25.0 - post_residual as f64) / 15.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover2 = post_residual - next_item_size;
        if leftover2 < 10 {
            score -= 40.0; // chains into another near-perfect fit
        } else {
            score -= 10.0;
        }
    }
    // Penalize if next item almost fits but not quite (creates blocking gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Slightly prefer bins below mean residual (balance load, keep big gaps available).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate (empty bin): neutral base so it only wins when open bins
    // have bad fits. Give it a mild fixed cost to discourage needless opening.
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: try to make post_residual match the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            // Perfect two-item chain: place item here so next item fits exactly.
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after placement: reward proportionally.
            score -= 0.6 * nxt;
        } else {
            // Next item won't fit here: post_residual becomes (partially) dead space.
            score += 0.35 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    // (but never the brand-new-bin candidate, which is handled below).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Brand-new empty bin candidate: penalize opening a new bin when open bins fit,
    // unless the item would leave a tiny unusable sliver everywhere else.
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // still allow a new bin if it yields a near-perfect fill
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below average
    // (tighter bins get used first, keeping large residuals open for big items).
    score -= 0.25 * (bin_residual as f64 - mean_residual);

    // Mild stream-progression pressure: as the stream matures, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid zero-waste obsession
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Penalize dead space that is too small to be useful later (hard-to-fill slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        score -= 12.0 * (1.0 - (lookahead_waste as f64 / bin_capacity as f64));
        if lookahead_waste == 0 {
            score -= 20.0; // perfect chain
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // next item wouldn't fit after this placement; mild penalty
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large and fragmented
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // penalize new bins generally, more so early in the stream
        score += 30.0 + 20.0 * (1.0 - progress);
        // but if open bins are nearly full (low mean residual), a new bin is fine
        score -= 25.0 * fragmentation;
        // if no other bin fits, new bin should win
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to item_size (best-fit core)
    score += 0.3 * (bin_residual as f64 - item_size as f64).abs();

    // Slight preference for bins with residual far below mean (consolidate emptier bins)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post-residual scaled by a smooth polynomial in stream progress.
    // Late in the stream, small residuals are more valuable to preserve (waste less).
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = pr * progress_weight;

    // Non-linear penalty for residuals that are awkward: near half-capacity or
    // just below typical item sizes — smooth via sin-free polynomial bump.
    let awkward = {
        let x = pr_norm;
        // peaks near x ~ 0.35-0.55 (dead zone: too small for medium items, too big to ignore)
        let center = 0.45;
        let d = x - center;
        let bump = (d * d * 6.0).exp();
        bump * cap * 0.6
    };
    score += awkward * (0.4 + 0.6 * progress);

    // Reward tight fits: subtract when post_residual is very small.
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 12.0 * tightness * (1.0 + progress);

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack).powi(2);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: neutral-ish base so it loses only when a good fit exists.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.1 * progress) - 5.0 * (1.0 - progress);
        // discourage opening new bins when many bins already fit the item
        score += 6.0 * (fitting_bins_count as f64).powf(0.8);
    }

    // Mild pressure from global mean residual: prefer bins close to mean (balance).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create capacity classes.
    let post = post_residual;
    let class = post % 10;
    // Dead-space penalty: post_residual that is nonzero but tiny (<10) is nearly unusable.
    if post > 0 && post < 10 {
        score += 60.0 - (post as f64) * 4.0;
    }

    // Perfect-fit harmonic classes: post_residual divisible by 10 or 25 is "usable".
    if post == 0 {
        score -= 200.0;
    } else if class == 0 {
        score -= 25.0;
    } else if post % 25 == 0 {
        score -= 20.0;
    }

    // Integer-division thresholds on post_residual: how many items of the next size fit?
    if next_item_size > 0 {
        let fits_next = (post / next_item_size.max(1)) as f64;
        if next_item_size <= post {
            // Reward bins that can still host the lookahead item.
            score -= 15.0 + fits_next * 5.0;
            // Extra reward for exact match with a harmonic class of the next item.
            if post == next_item_size {
                score -= 40.0;
            } else if (post - next_item_size) % 10 == 0 {
                score -= 12.0;
            }
        } else {
            // Next item can't fit here; penalize proportionally to wasted potential.
            score += 10.0 + (next_item_size - post) as f64 * 0.5;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // moderately attractive only when open bins are crowded or the fit is bad.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let poor_fit = (item_size as f64) / (bin_capacity as f64);
        score = 100.0 - poor_fit * 30.0 - crowded * 8.0;
        // Prefer new bin late in the stream when fragmentation is high.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Tie-break toward bins whose residual is close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are unusable for future
    // items (sizes >= 1 but realistically >= 10 in classic streams); penalize
    // them super-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Lookahead: if the next item can fit into the post_residual, reward;
    // if the next item almost fits (within 5), mildly penalize the near-miss.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual + 5 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are already fragmented; encourage consolidation.
    score += open_bins_count as f64 * 0.3;
    score -= mean_residual * 0.2;

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when no open bin offers a decent fit (i.e. when the
    // best-case post_residual across open bins would be small dead space).
    if bin_residual == bin_capacity {
        // Baseline competitiveness: empty bin gives post_residual = 100 - item.
        // Slightly favor it when the current bin would leave a tiny gap.
        if post_residual > 0 && post_residual <= 9 {
            score -= 20.0;
        }
        // Mildly penalize opening new bins late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: prefer existing bins unless fit is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin; lowered when no good existing option exists.
        let mut new_bin_score = 55.0
            - (post_residual as f64 - next_item_size as f64).abs() * 0.4
            - fitting_bins_count as f64 * 3.0;
        // Late in the stream, consolidation matters more; discourage new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 20.0;
        // If many bins can fit, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            new_bin_score += 15.0 * (fitting_bins_count as f64 - 2.0);
        }
        return new_bin_score;
    }

    // --- 2-step lookahead matching (aggressive) ---
    if next_item_size > 0 {
        // Perfect match: this bin's leftover exactly fits the next item -> strong reward.
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this placement; reward closeness of the match.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize proportionally to the leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Penalize tiny dead space that nothing (min size 1) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer bins whose residual is already below the mean residual (tight bins first).
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.25 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.4 * open_bins_count as f64;

    // Early in the stream, allow more freedom; later, enforce tight packing harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to capacity: small post_residual is good,
    // but a post_residual too small for the lookahead item is wasted.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            // post_residual perfectly chains with next item
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            // tiny unusable sliver
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // penalize new bin unless few fitting bins or open bins are mostly full
        score += 25.0;
        score -= 20.0 * (1.0 - mean_residual / bin_capacity as f64);
        score -= 5.0 * crowded;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // new bin keeps room for lookahead
        }
        let _ = progress;
    }

    // Mild time-horizon coupling: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * fit_ratio;

    // Prefer bins whose residual is below the mean (use up the emptier ones less,
    // keep balanced bins available): penalize picking bins far above mean residual.
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, with smooth non-linear shaping (quartic waste term).
    let mut score = post * (1.0 + 0.9 * norm_post * norm_post);

    // Stream-progress coupling: early on, tolerate moderate residuals to keep bins
    // flexible; late in the stream, aggressively punish wasted space.
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += urgency * post * (0.35 + 0.65 * norm_post);

    // Perfect or near-perfect fit reward (smooth, not a hard threshold).
    let tightness = 1.0 - norm_post;
    score -= 18.0 * tightness * tightness * tightness;

    // Lookahead synergy: reward when the residual exactly accommodates the next item.
    if next_item_size > 0 && (next_item_size as f64 - post).abs() < f64::EPSILON * 1000.0 {
        score -= 25.0;
    } else if next_item_size > 0 {
        let gap = (post as i64 - next_item_size as i64).abs() as f64;
        score += 0.12 * gap * (0.5 + urgency);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + urgency);
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many bins are open
    // and how much average capacity is being left unused (fragmentation pressure).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        let openness = (open_bins_count.min(50) as f64 / 50.0).sqrt();
        score += 22.0 + 30.0 * frag + 15.0 * openness + 20.0 * urgency * (1.0 - frag);
        // Exception: large items relative to typical residual deserve a fresh bin.
        let size_ratio = item_size as f64 / cap;
        score -= 40.0 * size_ratio * size_ratio * frag;
    }

    // Mild crowding penalty: spreading across many open bins is fine, but avoid
    // excessive fragmentation late in the stream.
    score += 0.05 * open_bins_count as f64 * urgency * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fractions) ---
    let pr = post_residual as f64;
    let frac = pr / cap_f; // fraction of capacity left over

    // Harmonic penalty: residual in (0, 10] is dead space; residual exactly
    // matching common item sizes (classes via integer division) is valuable.
    let dead_zone = 1.0 + 12.0 * (1.0 - (pr / 10.0).min(1.0)); // up to ~13 penalty for tiny residuals
    if post_residual > 0 && post_residual < 10 {
        score += dead_zone;
    }

    // Integer-division threshold classes: reward residuals that are "useful"
    // for typical item sizes (multiples of 5, 10, 20).
    let useful = (post_residual % 5 == 0) as f64 * 4.0
        + (post_residual % 10 == 0) as f64 * 4.0
        + (post_residual % 20 == 0) as f64 * 3.0;
    score -= useful;

    // --- Lookahead coupling: does post_residual fit next_item_size? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward leaving room for the next item, stronger the tighter
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / cap_f);
        } else {
            // penalty scaled by how much the next item misses this bin
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 + 6.0 * (1.0 - miss / cap_f);
        }
    }

    // --- Tightness reward for the current fit ---
    let tightness = 1.0 - (item_size as f64) / cap_f;
    score -= 6.0 * (1.0 - tightness); // larger items in this bin are better

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0; // strongly prefer using the only bin that fits
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost so we only open when fits are poor.
        let mut new_cost = 28.0;
        // Early in the stream, be slightly more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_cost -= 8.0 * (1.0 - progress);
        // If mean residual across open bins is high, prefer reusing them.
        new_cost += (mean_residual / cap_f).min(1.0) * 10.0;
        // If nothing fits (this call is the only "fitting" option counted as new),
        // opening is fine.
        if fitting_bins_count == 0 {
            new_cost -= 25.0;
        }
        // Harmonic check: a fresh bin leaves a clean harmonic residual class
        // for the next item (residual = capacity - item).
        if item_size % 10 == 0 {
            new_cost -= 4.0;
        }
        score = new_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64 / 10.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: penalize placements when many bins are open,
    // favoring consolidation into existing bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the gap: penalize leaving medium dead space.
            score += 5.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., tighter bins) to keep large residuals available elsewhere.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin should only win when
    // no good fit exists among open bins. Penalize it moderately.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about opening new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // matches the next item's size (perfect chain placement).
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post_residual as f64 - next).abs();
        // Strong reward for exact/near-exact match with next item.
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).powi(6);
        // Extra bonus for perfect chain: post_residual == next_item_size.
        if post_residual as f64 == next {
            score -= 40.0;
        }
        // Penalize post-residuals that are small but unusable for the
        // next item (dead space trap).
        if post_residual > 0 && (post_residual as f64) < next {
            score += 8.0 * (1.0 - post_residual as f64 / next);
        }
    }

    // Relative-to-mean term: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when no existing bin
    // fits well or the item is large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins normally...
        score += 20.0;
        // ...but large items with poor fit options justify a fresh bin.
        if fitting_bins_count <= 1 && tightness > 0.5 {
            score -= 35.0;
        }
        // Late in the stream, avoid spawning bins with big residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer filling already-open bins (bin consolidation pressure).
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
