    }

    // New-bin candidate logic: empty bin should only win when current fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalty grows with number of open bins and mean residual (encourage consolidation).
        score += 15.0 + 0.5 * open_bins_count as f64 + 0.1 * mean_residual;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        score -= 20.0 * progress;
        // If item is large relative to typical residuals, new bin is attractive.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Global consolidation pressure: prefer bins with residuals below mean (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
