    let fill = 1.0 - pr / cap;

    let mut score = pr;

    // Non-linear reward for tight fits (small post_residual), smoothed polynomial
    score -= 30.0 * (fill * fill * fill) * (1.0 + progress);

    // Penalize residual that is too small to be useful later (dead space)
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 25.0 * dead * dead;

    // Coupling with mean residual: prefer bins whose residual is near mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Lookahead: reward if next item fits into post_residual, penalize otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 15.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 10.0 * (nx / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress * (pr / cap);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 5.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: post_residual in small "harmonic classes" (0..=10) are best.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else {
        // Dead-space penalty grows super-linearly for large unusable gaps.
        score += (post_residual as f64) * (post_residual as f64) * 0.05;
    }

    // Modulo/harmonic class: post_residual that is a multiple of 10 aligns with
    // common item sizes, making it more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: reward if next item fits the post residual well (pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's remainder: penalize large leftovers.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many bins
    // already exist and how much mean residual capacity is idle.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64) * 2.0 + mean_residual * 0.5;
        // But if nothing fits well anywhere (large mean residual unused by item),
        // opening fresh is less bad — soften when item is large.
        if item_size > 70 {
            score -= 25.0;
        }
    }

    // Early in the stream, spreading items across bins is cheap insurance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 {
        score += 3.0 * (1.0 - progress * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range)
    // are pure waste. Penalize tiny non-zero gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Open-bin pressure: discourage spreading into more bins when many are open,
    // but encourage closing bins that are nearly full.
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // next item won't fit here: this gap may become dead space
            score += (post_residual.min(next_item_size) as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only for good reason.
        score += 40.0;
        // If the only fitting bin would leave a bad gap, opening fresh is fine.
        if fitting_bins_count == 1 {
            let would_be_gap = bin_residual.saturating_sub(item_size);
            if would_be_gap > 0 && would_be_gap < 10 {
                score -= 55.0;
            }
        }
        // Early in stream, new bins are cheap; later, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
    }

    // Mild attraction toward bins below mean residual (emptier bins absorb
    // fragmentation, keeping tight bins available for small items).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual) more aggressively.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            // Penalize large leftover after the follow-up placement.
            score -= 25.0 * (1.0 - leftover / bin_capacity as f64).powi(3);
        } else {
            // Next item cannot follow: penalize proportionally to wasted potential.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative residual coupling: prefer bins whose residual deviates favorably from mean.
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, prefer closing bins tightly rather than opening new ones.
    score += 20.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
