pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize creating residual that no plausible next item fits into
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 12.0 * (nx - pr) / cap;
        } else {
            score -= 8.0 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight penalty for proliferating open bins relative to mean residual
    if open_bins_count > 1 {
        score += 3.0 * (open_bins_count as f64).ln() * (1.0 - norm_pr) * (1.0 - progress);
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let gap = (mean_residual - (cap - item_size as f64)).abs();
        score += 15.0 + 0.5 * gap;
        if pr >= next_item_size as f64 && next_item_size > 0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on a
    // "clean" residue class are more reusable, reward them.
    let class = post_residual / 10; // coarse harmonic bucket 0..10
    match class {
        0 => score -= 45.0,          // near-perfect fit
        1 => score -= 30.0,          // excellent
        2 => score -= 18.0,
        3 => score -= 8.0,
        4 => score -= 2.0,
        5 => score += 4.0,           // half-full leftover, mediocre
        6 => score += 8.0,
        7 => score += 14.0,
        8 => score += 22.0,
        _ => score += 30.0,          // large unusable-ish remainder
    }

    // Exact modulo harmony: post_residual divisible by 10 is friendly
    // to typical item sizes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0;
            if slack <= 5 {
                score -= 10.0; // chain fit: next item nearly fills it
            }
        } else {
            // post_residual can't host next item: dead space risk
            score += 5.0;
            if post_residual < 10 {
                score += 10.0; // tiny dead space
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Crowding pressure: many open bins -> prefer consolidation into
    // existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score -= 3.0 + 4.0 * progress;
    }

    // Penalize leaving residual far from the mean residual (fragmentation).
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate (empty bin): neutral baseline with mild penalty so
    // it only wins when existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big next item: fresh bin is attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }
    // Penalize residuals that are too small to fit typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (1.0 + post_residual as f64) * 2.0;
    }

    // Last-chance pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.5;
    } else {
        score -= 3.0; // reward reuse of existing bins
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.5;
    }

    // Mean residual coupling: bins below mean residual are more "filled", prefer them.
    score -= (mean_residual - post_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Stream progression: as stream advances, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chain), softly for near matches.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 1000.0; // perfect two-step match
        } else if (post_residual as u32) >= next_item_size {
            // next item still fits here: bonus grows as the slack shrinks toward next_item_size
            let slack = post_residual as f64 - next;
            score -= 40.0 / (1.0 + slack);
        } else {
            // post_residual too small for next item: dead space penalty, worse when large
            let dead = next - post_residual as f64;
            score += dead * 1.5;
        }
    }

    // Compare against mean residual of open bins: prefer leaving residuals
    // near the mean (balanced packing), penalize outliers.
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff * diff / (1.0 + mean_residual);

    // Tight fits are good: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the
    // stream and when many bins are already open (they may absorb future items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If the next item is huge, a fresh bin is less bad.
        if next_item_size >= 50 {
            score -= 30.0;
        }
    }

    // Late in the stream, closing bins tightly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 12 {
        score += 10.0 - post_residual as f64;
    } else if post_residual >= 12 && post_residual < 30 {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 3.0;
        }
    } else {
        // Last item: prefer filling a bin as fully as possible.
        score -= 8.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 1.5 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early on, be picky about fits; late, prefer consolidation.
    score *= 1.0 + 0.35 * (1.0 - t);

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 14.0 * desperation + 6.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 6.0 * poly * (1.0 + progress);

    // Reward tight fits more strongly as the stream progresses (smooth coupling).
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (4.0 + 10.0 * progress);

    // Penalize wasting space when the item nearly fills the bin but leaves dead space
    // that no plausible item can use (dead-space penalty, smooth in post_residual).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.5) / cap;
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let match_q = 1.0 - (gap / cap);
        score -= 5.0 * match_q * match_q * (0.5 + progress);
    } else if next_item_size > 0 {
        // Penalize bins that leave the next item stranded.
        score += 3.0 * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: make it mildly unattractive when open bins can fit,
    // but attractive late in the stream when residual fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { (mean_residual / cap).clamp(0.0, 1.0) } else { 0.0 };
        score += 8.0 * (1.0 - progress) + 4.0 * (1.0 - fragmentation) * (1.0 - progress);
        score -= 6.0 * progress * fragmentation;
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fills (0) are best;
    // small dead space classes are penalized progressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space class via integer division: small residuals are "unusable"
        // unless they match a common item-size class (multiples of 10).
        let dead_class = post_residual / 10;
        score += (dead_class as f64) * 0.5;

        // Reward residuals that lie in harmonic classes matching typical item sizes
        let harmonic = post_residual % 10 == 0 && post_residual >= 10;
        if harmonic {
            score -= 8.0;
        }

        // Very small unusable slivers (1..10) are heavily penalized
        if post_residual < 10 {
            score += 25.0;
        }

        // Lookahead coupling: does next item fit into post_residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 20.0;
                // Extra reward if next item also leaves a harmonic residual
                let next_post = post_residual - next_item_size;
                if next_post % 10 == 0 {
                    score -= 10.0;
                }
                if next_post == 0 {
                    score -= 30.0;
                }
            } else {
                // Dead-end for lookahead: penalize, scaled by how much it misses
                let miss = (next_item_size - post_residual) as f64;
                score += miss * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (large post_residual waste or item barely fits anywhere).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // New bins look good when item is large (hard to place later)
        score -= 15.0 + 25.0 * tightness;
        // But if a perfect existing fit exists elsewhere, this loses anyway
        if post_residual == 0 { score -= 500.0; }
    }

    // Progress coupling: late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mean residual alignment: prefer bins whose residual is near the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Crowding: many open bins -> prefer filling existing ones
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (1..=80)
    // can use well are heavily penalized. The most wasteful gaps are those
    // just below the minimum useful chunk sizes.
    let dead_zone: f64 = if post_residual == 0 {
        0.0 // perfect fit — ideal
    } else if post_residual < 10 {
        60.0 // tiny unusable sliver
    } else if post_residual < 20 {
        35.0
    } else if post_residual < 30 {
        18.0
    } else {
        0.0
    };
    score += dead_zone;

    // Penalize residual that cannot fit the lookahead item (creates forced
    // future fragmentation), scaled by lookahead size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits (item dominates the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make the empty bin attractive only when this bin's
    // fit would leave a bad gap; otherwise existing bins are preferred.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a perfect fit in an open bin,
        // better than any bin with dead-space penalty.
        score = bin_capacity as f64 * 0.9 - 10.0 * fill_ratio
            + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 4.0; // big item into fresh bin is fine
        }
    }

    // Mild preference for bins below mean residual (keep residuals balanced).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact match with the next item (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Residual left after hypothetically serving next item too.
            let two_step = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + two_step);
        } else {
            // Next item won't fit here; penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Strong penalty for creating small unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Prefer bins tighter than the mean residual (good compact fits).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New empty bin candidate: only attractive when few bins fit the item
    // or the current bin would leave a bad fit for the next item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0
            + 50.0 * (fitting_bins_count as f64)
            - 100.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 150.0; // fresh bin can host both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits the post residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving a residual that wastes capacity for the next item
            score += 0.05 * (next_item_size as f64 - post_residual as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage opening new ones / spreading load
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is large
        score += 20.0 + 2.0 * open_bins_count as f64 + 0.3 * mean_residual;
        // Late in the stream, closing out bins is better than opening new ones
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Favor fuller bins when many bins are open (bin-count pressure)
        score -= 0.1 * open_bins_count as f64 * tightness;
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space)
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.05 * (mean_residual - resid_f);
    } else {
        score += 0.05 * (resid_f - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with a convex quadratic penalty
    // so that mid-range residuals are punished more than linear.
    let mut score = norm_pr * (1.0 + 0.6 * norm_pr * (1.0 - t));

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, tiny residuals are worthless, large ones matter more.
    let progress_coupling = norm_pr * norm_pr * (0.5 + 1.5 * t * t);
    score += 0.35 * progress_coupling;

    // Reward tight fits (post_residual near zero) with a smooth bell-shaped bonus.
    let tightness = (-4.0 * norm_pr).exp();
    score -= 0.8 * tightness * (1.0 + 0.5 * t);

    // Penalize waste relative to the mean residual of open bins.
    score += 0.15 * (pr - mean_residual) / cap;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2 + 0.8 * (1.0 - t);
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 0.5 * (nx / cap) * (1.0 + (pr - nx) / cap);
        } else if nx > bin_residual as f64 {
            // next item needs a new bin anyway; slightly prefer keeping large residuals
            score -= 0.1 * norm_pr;
        }
    }

    // New-bin candidate (bin_residual == bin_capacity): post_residual is large,
    // so base terms already penalize it; add a mild bonus early in the stream
    // and when few bins fit, decaying smoothly with progress.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score -= 0.4 * (1.0 - t) * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near capacity/4 multiples are
    // "usable" pockets; reward landing exactly on such classes.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 harmonic class
    match class {
        0 => score -= 12.0,                       // near-perfect fit
        1 => score -= 4.0,                        // small pocket, still useful
        2 => {}                                   // neutral half-full
        3 => score += 3.0,                        // large residual, wasteful
        _ => {}                                   // empty-bin class
    }

    // Dead-space penalty: post_residual too small for any plausible item
    // (min item size unknown; assume 1..=100 interface, treat <10 as dead).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    // Lookahead coupling: does the next item fit in the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic compatibility: next item leaves another good class.
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score -= 10.0;
            } else {
                score -= (next_post / quarter) as f64 * 2.0;
            }
        } else {
            score += 6.0; // next item won't fit here; this bin becomes dead-ish
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins with low residual relative to open-bin mean.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: penalize mildly so we only open when open bins are bad,
    // but relax as stream progresses and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 8.0 * progress - (open_bins_count.min(10) as f64) * 0.5;
        // If next item is large and won't fit anywhere typical, fresh bin is fine.
        if next_item_size > 70 {
            score -= 5.0;
        }
    }

    // Mild tie-break: favor tighter fit ratio.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32.max(next_item_size.min(item_size)) as f64;
    if post_residual > 0 {
        if (post_residual as f64) < min_item {
            score += 40.0; // unusable sliver
        } else if post_residual as f64 <= mean_residual * 0.5 {
            score += 10.0; // below-average gap, likely dead
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and remaining stream.
        score += 20.0 + 5.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        // Slight bonus to reuse existing bins when many are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // gap won't serve the next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward perfect/near-perfect fits heavily
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: if next item exactly fills the post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_fill;
        } else {
            // next item cannot use this residual -> penalize wasted space
            score += 10.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).min(1.0);
        }
    }

    // Compare residual to mean residual of open bins: prefer bins with below-mean residual (tighter bins)
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let openness = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 45.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
        score += new_bin_penalty * (1.0 - 0.3 * openness);
        // if many bins already open, discourage adding more
        score += 2.0 * (open_bins_count as f64).sqrt();
        // if no open bin fits well (post_residual large waste elsewhere handled), allow new bin for big items
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 30.0;
        }
    }

    // Mild penalty for leaving residuals that are too small to be useful (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits in post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving space that next item nearly fits (wasted chain).
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 5.0;
            }
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (keep bins clean);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base attractiveness, adjusted by state.
        let mut new_bin_score = 45.0 + post_residual as f64;
        // Early: opening fresh bins is fine; late: discourage.
        new_bin_score += 30.0 * progress;
        // Many open bins with high mean residual -> prefer filling existing bins.
        new_bin_score += (open_bins_count as f64).sqrt() * 4.0 + mean_residual * 0.3;
        // Large current item in a fresh bin is safe.
        new_bin_score -= item_size as f64 * 0.15;
        score = score.min(score) ; // keep base
        return new_bin_score;
    }

    // Existing-bin consolidation pressure late in the stream.
    score -= 10.0 * progress;

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // If many bins can fit, allow mild spreading to preserve flexibility.
    if fitting_bins_count > 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap; // normalized post residual in [0,1]

    let mut score = r;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, prefer tight fills modestly; late, penalize wasted residual more strongly.
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += progress_weight * norm_r * norm_r * cap * 0.5;

    // Reward near-perfect fits via smooth gaussian-like bump on normalized residual.
    let bump = (-((norm_r - 0.05) * (norm_r - 0.05)) / 0.02).exp();
    score -= 8.0 * bump;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - r).max(0.0) / cap;
        score += gap * gap * cap * (1.0 + progress);

        // Reward leaving residual that exactly (or nearly) fits the next item.
        let fit_bump = (-((r - nxt) * (r - nxt)) / 25.0).exp();
        score -= 6.0 * fit_bump;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mild penalty proportional to number of open bins to discourage bin sprawl.
    score += open_bins_count as f64 * 0.05;

    // Slight attraction toward bins with residual near the mean (balanced packing),
    // smoothly damped as the stream progresses.
    let dev = (r - mean_residual) / cap;
    score += dev.abs() * (1.0 - progress) * 3.0;

    // New-bin candidate: make empty-bin choice costly unless residual is unusable.
    if bin_residual == bin_capacity {
        score = r + 15.0 + 20.0 * (1.0 - progress);
        // Allow new bin when no open bin fits well (smooth escape hatch).
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by large power-of-2 classes
    // are more reusable. Reward (subtract) when post_residual lies in "useful" classes.
    let pr = post_residual;
    if pr > 0 {
        let class = (pr.trailing_zeros() as f64).min(6.0); // 0..6
        score -= 4.0 * class; // power-of-two-aligned residuals are more reusable
        // Integer-division thresholds: post_residual >= 50 keeps half-bin usable
        if pr >= bin_capacity / 2 {
            score -= 8.0;
        } else if pr >= bin_capacity / 4 {
            score -= 3.0;
        } else {
            score += 5.0; // small dead-space penalty
        }
        // Exact-fill bonus
        if pr == 0 {
            score -= 30.0;
        }
    }

    // Tight fit reward: residual barely exceeds item
    let slack = (bin_residual - item_size) as f64;
    if slack <= 5.0 {
        score -= 12.0;
    } else if slack <= 15.0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current
    // fit is terrible or many bins are open with fragmented residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap - 0.5).abs();
        // Base cost of a fresh bin
        score = cap * 0.55 + 10.0 * fragmentation + 5.0 * (1.0 - progress);
        // If item is small relative to capacity, fresh bin wastes potential
        score += 0.3 * (cap - item_size as f64);
        // If no open bins at all, must open
        if open_bins_count == 0 {
            score -= cap;
        }
    } else {
        // Prefer bins with below-mean residual (consolidate fuller bins)
        score -= 0.5 * (mean_residual - bin_residual as f64);
    }

    // Modulo harmonic bonus: post_residual mod 10 == 0 leaves round residuals
    if pr % 10 == 0 && pr > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever be useful
    // (smaller than the minimum plausible item) are heavily penalized.
    let min_item = 1u32; // interface allows sizes down to 1
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }

    // Non-linear dead-space penalty: small positive residuals that are unlikely
    // to fit the next item are punished super-linearly.
    if post_residual > 0 && next_item_size > post_residual {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * waste * 0.05;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize placements that leave
    // awkward gaps when bin count is already high.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual > 0 {
        score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    // (large item, low mean residual spread).
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 15.0; // base inertia against opening new bins
        score -= mean_gap * 0.5; // discount if open bins have poor slack
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin keeps flexibility for lookahead
        }
    }

    // Mild lookahead alignment: if next item fits exactly in post_residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }

    // Stream progression: early on, be slightly more conservative about
    // fragmenting bins; later, allow tighter packing aggression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if (nr - pr).abs() < 1.0 {
            score -= 200.0; // perfect chaining: next item completes this bin
        } else if nr <= pr {
            // next item fits in the leftover: reward proportionally to fill
            score -= 60.0 * (nr / pr);
        } else {
            // next item cannot use leftover: penalize dead space
            score += 0.3 * pr;
        }
        // Bonus if next item would also fit snugly relative to mean residual
        if nr > 0.0 && nr < mean_residual {
            score -= 10.0 * (1.0 - nr / mean_residual);
        }
    }

    // Relative to mean residual: bins with residual far above mean are less attractive
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 25.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && (next_item_size as f64) >= item_size as f64 {
            score -= 15.0; // pairing big item with next big item in fresh bin
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small penalty per open bin to encourage closing bins out
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Dead-space penalty: post_residual that is too small for the smallest
    // plausible future item is wasted capacity.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        // But penalize if placing here strands a residual that can't fit next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // New-bin candidate arbitration: an empty bin is attractive only when the
    // current item is large (poor fit anywhere else) or few bins fit the item.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score = 40.0 + 45.0 * large_item;
        if fitting_bins_count <= 2 {
            score -= 25.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0; // room to pair the next item in a fresh bin
        }
        // Late in the stream, discourage opening new bins (leftover bins are waste).
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * t;
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins (penalize new bins implicitly, reward fills).
    if bin_residual < bin_capacity {
        let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);
        if mean_residual > (bin_capacity as f64) * 0.6 {
            score += 4.0; // many bins are loose; prefer the tightest anyway via tight bonus
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual (waste), non-linearly shaped by stream progress.
    // Early: prefer filling bins tightly (penalize large residual mildly).
    // Late: penalize large residuals more strongly since fewer chances to reuse them.
    let mut score = pr * (0.9 + 1.6 * progress * progress);

    // Smooth polynomial coupling: residual squared term grows with progress
    score += 2.0 * x * x * (1.0 + progress) * cap * 0.1;

    // Penalize bins whose post-residual cannot fit the next item when lookahead exists
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            // Reward leaving room for the next item (subtract)
            score -= (pr - nxt).min(cap * 0.5) * 0.3 * (1.0 - progress * 0.5);
        }
    }

    // Last-chance bin: strong reward to use it and avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Mild preference for consolidating into bins below mean residual (tighter bins)
    score -= (mean_residual - pr) * 0.15;

    // New-bin candidate: penalize mildly by default so it wins only when fits are bad;
    // penalty shrinks with progress since dead space matters more late.
    if bin_residual == bin_capacity {
        score += 18.0 - 6.0 * progress;
        // but if item is large relative to capacity, opening a fresh bin is fine
        score -= item_size as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual <= 10 (tiny dead space) -> strong reward.
    // Class 2: post_residual <= 20 -> moderate reward.
    // Larger leftovers penalized progressively (wasted capacity).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 20.0;
    } else if pr <= 30 {
        score -= 8.0;
    } else {
        // Quadratic-ish penalty on large dead space, scaled by capacity fraction.
        let frac = pr as f64 / cap;
        score += 10.0 * frac * frac * cap;
    }

    // Harmonic residue classes: leftover divisible by common item sizes
    // (10, 20, 25, 50) is more likely reusable by future items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Integer-division threshold: leftover that could host the next item is valuable.
        if next_item_size > 0 && pr >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fills the bin exactly after this placement chain.
            if pr - next_item_size <= 10 { score -= 6.0; }
        } else if next_item_size > 0 {
            // Penalize leftovers that cannot host the lookahead item.
            score += 4.0;
        }
    }

    // Tightness: reward filling a large fraction of the bin's current residual.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill * fill;

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // best existing fit is poor. Give the empty bin a baseline cost that grows
    // with how many bins are already open (encourage consolidation), but allow
    // it to win when the placement here would leave a large unusable gap.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // A new bin is fine for big items that define a fresh structure.
        if item_size >= 50 { score -= 20.0; }
    }

    // Early in the stream, tolerate more bins (exploration); late, consolidate hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += (bin_residual as f64 - mean_residual).abs() * 0.3;
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals too small to ever be useful.
    // A gap is "dead" if it is smaller than the smallest possible item (1) is trivially
    // fine, but gaps below the next item size (or below a small threshold) waste space.
    let min_useful = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual < min_useful && post_residual > 0 {
        // Dead space relative to the lookahead item: the larger the waste, the worse.
        score += 25.0 + (min_useful - post_residual) as f64 * 1.5;
    }
    if post_residual < 10 && post_residual > 0 {
        // Gaps under 10 are nearly unusable for typical item distributions.
        score += 15.0 + (10 - post_residual) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // but soften as the stream progresses (consolidation becomes more valuable).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 30.0 + open_bins_count as f64 * 2.0 * (1.0 + progress);
        // Allow a new bin if all existing fits create dead space.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Mild reward for filling existing bins, scaled by how full they are.
        let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill_frac;
    }

    // Coupling with mean residual: prefer bins whose residual is close to the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Leftover usable by next item: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack.min(150.0);
        } else {
            // Next item cannot fit in the leftover: penalize large dead space.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize creating unusable dead space below the minimum item size (1..100 unknown, assume small floor).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize moderately so we only open when placements are poor,
    // but relax the penalty as the stream progresses (early on, spreading is cheaper).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 450.0 - 250.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving awkward residuals that few common items can use.
    if post_residual > 0 {
        let awkward = if post_residual < 10 { 0.0 }
            else if post_residual <= 20 { -4.0 }   // usable by small items
            else if post_residual <= 50 { 6.0 }    // dead zone: too big for small, too small for large
            else { 2.0 };
        score += awkward;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item can't use this residual; slight penalty proportional to waste
            score += 2.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }
    // Many fitting bins: mild penalty to keep bins consolidated.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (high mean residual fragmentation or item barely fits anywhere).
    if bin_residual == bin_capacity {
        let poor_fits = (bin_residual - item_size) as f64;
        let fragmentation = (mean_residual - item_size as f64).abs();
        let pressure = (open_bins_count as f64 / 8.0).min(3.0);
        // Base cost of a fresh bin, discounted when open bins are messy.
        score = 30.0 + poor_fits * 0.2 + pressure - fragmentation * 0.3;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0; // fresh bin can host a nice pair
        }
        if fitting_bins_count == 0 {
            score = 5.0; // must open a bin anyway
        }
    }

    // Mild time-horizon drift: early on, be exploratory (favor consolidating),
    // later, be greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    let coupling = norm_post * norm_post * (0.5 + progress) + norm_post * progress * progress;
    score += 30.0 * coupling;
    // Reward tight fits (small post_residual) especially late in the stream
    score -= 20.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.3 + 0.7 * progress);
    // Penalize opening a new bin when open bins could fit, smoothly
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 15.0 + 10.0 * progress;
    }
    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }
    // Lookahead: favor leaving space for next item
    let next_norm = next_item_size as f64 / bin_capacity as f64;
    if next_item_size > 0 {
        let gap = (norm_post - next_norm).abs();
        score += 10.0 * gap * gap;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: coarse 10-unit buckets add a gentle
    // stair-step preference for bins whose remainder falls into low classes.
    let class = post_residual / 10;
    score += class as f64 * 0.3;

    // Dead-space penalty: if the lookahead item cannot use the remainder,
    // the leftover is likely wasted. Penalize proportionally to the gap,
    // with a modulo-flavored extra kick when post_residual sits just below
    // the next item size (worst harmonic misalignment).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        let misalign = if next_item_size % 10 == 0 { 1.5 } else { 0.5 };
        score += 6.0 + gap as f64 * 0.5 * misalign;
    }

    // Lookahead pairing bonus: if the next item fits exactly in the remainder,
    // strongly reward this placement (creates a perfect two-item packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    // Last-chance bonus: this is the only open bin that can fit the item;
    // avoid opening a new bin when a fit exists.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when many alternatives exist (prefer tight fits elsewhere).
    if fitting_bins_count > 1 {
        score += 2.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is the only option.
            score -= 40.0;
        } else {
            // Competing with usable bins: penalize, more so as bins accumulate
            // (consolidation pressure grows over the stream).
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 + open_bins_count as f64 * 0.2 + progress * 4.0;
            // If the new bin would leave a large awkward remainder relative
            // to the next item, discourage it further.
            if next_item_size > 0 && post_residual < next_item_size {
                score += 4.0;
            }
        }
    }

    // Slight preference for bins already well-filled (keeps residuals small).
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure loss; residuals that cannot fit the next item are partial loss.
    if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    } else {
        // Dead space: gap smaller than next item (or than 10 as typical floor)
        let min_useful = if next_item_size > 0 { next_item_size.min(10).max(1) } else { 1 };
        if (post_residual as u32) < min_useful {
            score += 25.0; // unusable sliver
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0; // gap unusable for lookahead item
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 18.0; // perfect lookahead fit
        }
        // Gradient: small residuals are more valuable per unit than large ones
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);
    }

    // Exact fit of current item
    if post_residual == 0 && bin_residual == item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, consolidate instead of spreading
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * 1.5;

    // Early in the stream, be slightly more willing to fill tightly;
    // late in the stream, prioritize closing bins (perfect fills).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (if post_residual == 0 { 15.0 } else { 0.0 });

    // Mild penalty for wasting a large residual on a small item
    if item_size < bin_residual / 2 && bin_residual < bin_capacity {
        score += 6.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) as f64 > mean_residual);
        if poor_fit_elsewhere {
            score -= 10.0;
        } else {
            score += 35.0; // discourage opening new bins when good fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits after this placement: strong reward, scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * slack;
        } else {
            // Next item will not fit here: penalize proportionally to leftover mismatch.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.25 * miss;
        }
        // Bonus for perfect two-step chain (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just prefer tightest fit (already via post_residual).
    }

    // Relative-to-mean coupling: bins with residual far below mean are "precious" tight fits.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin unless current bins are poor fits:
    // new bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // New bin starts with large post_residual; add penalty that shrinks
        // when existing bins are crowded (few fitting bins relative to open bins).
        let crowding = if open_bins_count > 0 {
            fitting_bins_count as f64 / open_bins_count as f64
        } else {
            1.0
        };
        score += 20.0 * crowding;
    }

    // Mild waste penalty for large dead space relative to capacity.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (slack / bin_capacity as f64 + 0.1);
    }
    // Penalize creating dead space that exactly blocks the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; few open bins: encourage consolidation
    let density = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.0 * density;

    // Time horizon: early in the stream, be more willing to open fresh bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: good if this bin is unusable for others or stream is young
        let worth = if fitting_bins_count <= 1 { 0.0 } else { 30.0 };
        score = 40.0 + worth * (1.0 - progress) - 10.0 * progress;
    } else {
        // Late in stream, favor closing out bins (small residuals) harder
        score *= 1.0 + 0.5 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth coupling: small post-residuals become more valuable as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Perfect fit bonus (post_residual near zero)
    score -= 20.0 * (-pr / 5.0).exp();

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_after_next = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - slack_after_next / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        // penalize leaving residual that nothing can use
        score += 5.0 * norm_pr * (1.0 - pr / next_item_size as f64).min(1.0);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + progress);
    }

    // Penalize spreading across many bins; encourage filling existing bins
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // New-bin candidate: make empty bins less attractive unless residual waste elsewhere is high
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (1.0 - progress) - mean_residual * 0.05;
    }

    // Mild reward for large fill fraction of current bin
    score -= 10.0 * (item_size as f64 / cap) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals near multiples of
    // common item sizes (10..80 buckets) are more reusable.
    let pr = post_residual;
    // Reward residuals that fall into "harmonic" classes: multiples of 25 or 50,
    // or small residuals (< 10, dead space anyway).
    let harmonic = if pr == 0 {
        30.0 // perfect fit — strong reward
    } else if pr % 50 == 0 || pr % 25 == 0 {
        12.0
    } else if pr % 20 == 0 || pr % 10 == 0 {
        6.0
    } else if pr < 10 {
        3.0 // small dead space is nearly free
    } else {
        0.0
    };
    score -= harmonic;

    // Penalize awkward mid-range residuals via modulo distance to nearest 10.
    let d10 = (pr % 10) as f64;
    score += 1.5 * d10.min((10 - pr % 10) as f64);

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when fits are poor or lookahead mismatches.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // Discount when few bins fit (last-chance avoidance) or lookahead
        // won't fit the current bin's post-residual anyway.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count <= 1 { score -= 35.0; }
        if next_item_size > post_residual && post_residual > 0 { score -= 10.0; }
        // Early stream: slightly cheaper to open bins to build a pool.
        score -= 10.0 * (1.0 - progress);
        // If many open bins already, discourage hoarding.
        score += open_bins_count as f64 * 0.8;
        score -= mean_residual * 0.05;
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward for harmonic alignment of (post_residual - next_item_size).
        let pr2 = post_residual - next_item_size;
        if pr2 % 25 == 0 || pr2 == 0 { score -= 4.0; }
    } else if next_item_size > post_residual {
        // Post-residual unusable by lookahead: penalize proportional to waste.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Prefer tighter bins generally: closeness of fit reward.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Mean-residual balancing: favor bins below mean residual (fill crowded bins).
    score += 0.1 * (mean_residual - bin_residual as f64).max(-20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for unusable small gaps (post_residual < 10, or below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            // next item can't use the gap: penalize proportionally to wasted space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize with open-bin pressure so it's chosen only when fits are bad.
        score += 25.0 + (open_bins_count as f64) * 3.0;
    } else {
        // Mild reward for consolidating into fewer bins.
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Slight preference for bins below mean residual (balance residual spread).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late-stream tightening: as the stream progresses, penalize waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - tightness * tightness);

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap_ratio = post_residual as f64 / next_item_size as f64;
            score += 15.0 * gap_ratio;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid wasting this bin's unique fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin early unless stream is early or item large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 30.0 * (1.0 - progress) + item_size as f64 * 0.3;
        score += new_bin_penalty;
        // If item is huge, new bin may be reasonable
        if item_size >= 70 { score -= 20.0; }
    }

    // Slight penalty for very small post_residual dead space that nothing can use later
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 25.0;
            } else {
                score -= (1.0 - gap as f64 / bin_capacity as f64) * 10.0;
            }
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += (1.0 - post_residual as f64 / next_item_size.max(1) as f64) * 6.0;
        }
    }

    // Prefer filling bins with large residuals when many bins are open (consolidation).
    if bin_residual != bin_capacity && open_bins_count > 3 {
        score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0);
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or many bins are open and this fit wastes a lot.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 55.0; // base cost of a fresh bin
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if waste > 0.6 {
            score -= 45.0; // item is small; poor fit everywhere justifies new bin
        }
        // Late in stream, opening bins is cheaper than fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early streams: prefer filling bins tightly (low post_residual).
    // Late streams: tolerate residual waste slightly more, smooth polynomial ramp.
    let coupling = norm_post * (1.0 + 0.8 * progress + 0.6 * p2 + 0.4 * p3);
    score += 3.0 * (coupling - norm_post);

    // Reward near-perfect fits with a smooth quadratic bonus.
    let tight = 1.0 - norm_post;
    score -= 6.0 * tight * tight;

    // Penalize dead space that no future item can plausibly use.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post > 0.0 && nx > post {
            let unusable = (nx - post) / cap;
            score += 8.0 * unusable * unusable;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 2.0 * (nx / cap);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // New-bin candidate: keep it neutral early, discourage late when open bins fit well.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 2.0 + 0.15 * openness * (0.5 + 0.5 * progress);
        if fitting_bins_count > 0 {
            score += 3.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins below mean residual (balancing).
    score += 0.5 * (mean_residual - post).max(-20.0).min(20.0) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space that cannot hold small items (1..=10) usefully.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits (post_residual in low modulo classes of 10).
    let class = post_residual % 10;
    score -= (10 - class) as f64 * 0.8;

    // Integer-division thresholds: quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual < 2 * quarter {
        score -= 3.0; // residual still reusable for mid items
    } else if post_residual >= 2 * quarter && post_residual < 3 * quarter {
        score -= 6.0;
    } else if post_residual >= 3 * quarter {
        score -= 9.0;
    }

    // Lookahead: strongly reward if next item also fits in resulting residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 12.0 + (pr - ns) * 0.5;
            // Harmonic pair: next item's own class compatibility
            let pair_class = (post_residual as u32).wrapping_mul(31) % 7;
            score -= pair_class as f64 * 0.3;
        } else {
            score += (ns - pr) * 0.6; // next item won't fit here
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are already open with slack.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
        if mean_residual > 20.0 {
            score += (mean_residual - 20.0) * 0.4;
        }
    }

    // Prefer bins below mean residual (tighter bins absorb waste better).
    score += (pr - mean_residual) * 0.15;

    // Mild stream-progression damping of exploration bonuses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize mid-range dead space that is unlikely to fit future items.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading items; with few bins, opening new ones is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open,
        // reward when few bins exist or the item is large.
        score += 25.0 + 20.0 * pressure - (item_size as f64) * 0.3;
    } else {
        // Existing bin: reward slightly more when open-bin pressure is high.
        score -= 5.0 * pressure;
    }

    // Lookahead: if the next item would fit in this bin's post-residual,
    // reward the placement (chaining).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit post-residual and post-residual is small,
    // the gap is truly dead — extra penalty.
    if next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, filling bins matters more than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;
    score += 10.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (small post_residual), nonlinearly
    score = post_residual as f64 * (1.0 + 0.02 * post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: reward when post_residual exactly matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: post_residual == next_item_size -> strong reward
        if gap == 0.0 {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item can follow: reward proportional to closeness
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize
            score += 5.0 * gap / bin_capacity as f64;
        }
    } else {
        // Last item: purely minimize waste
        score -= 10.0;
    }

    // Relative to mean residual: bins with residual below mean are "tighter"
    // and better candidates; penalize bins far above mean residual (wasteful)
    let rel = post_residual as f64 - mean_residual;
    score += 0.05 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Penalize opening new bins early in the stream; allow it late
        // or when many bins are open (consolidation pressure)
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 40.0 * (1.0 - progress) * (1.0 - 0.5 * open_pressure) + 10.0;
        // If the next item is large, a fresh bin is more valuable
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Slight preference for filling fewer bins overall
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
