pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Non-linear interaction: dead space penalized more strongly later in the stream
    let dead = norm_pr * norm_pr * (1.0 + 3.0 * progress * progress);
    score += 30.0 * dead;

    // Reward tight fits (small post_residual) with a non-linear bonus
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - 0.5 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 + progress);
    }

    // Penalize opening new bins when many bins are already open and mean residual is large
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 15.0 * open_bins_count as f64 * (0.5 + pressure) * (0.3 + 0.7 * progress);
    } else {
        // Favor bins whose residual is below mean (consolidating fuller bins)
        let diff = (bin_residual as f64 - mean_residual) / cap;
        score += 10.0 * diff * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement smoothly
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let tightness = (pr - next_item_size as f64) / cap;
        score -= 20.0 * fits * (1.0 - tightness) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

