    let class = (post_residual % 10) as f64;
    score += class * 0.35;

    // Fractional fill level of the bin after placement
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 18.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // dead space below minimum item size is unusable
        score -= 25.0;
    }

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 22.0;
            // harmonic pairing: next item leaves a small remainder too
            let nr = post_residual - next_item_size;
            if nr < 10 {
                score -= 15.0;
            }
