            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize spreading across many open bins slightly
    score += (open_bins_count as f64) * 0.6;

    // Encourage tight packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= fill * 10.0 * progress;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin
        } else {
            // opening a new bin only wins if existing fit is very poor
            let waste = (bin_residual - item_size) as f64;
            score = waste + (open_bins_count as f64) * 1.2 + 25.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 30.0;
