pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are waste.
    // Treat post_residual < 10 as fully dead; penalize quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small usable post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // If the next item fits exactly in the post_residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit but post_residual is small-but-nonzero, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = (bin_residual == bin_capacity) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += new_bin * (10.0 + 20.0 * open_bins_count as f64 + 10.0 * progress);

    // Slight preference for bins with below-mean residual (consolidate emptier bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Reward small dead space relative to item size.
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    if next_item_size > 0 {
        // Perfect 2-step lookahead: next item exactly fills the post residual.
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how much of the residual it consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill;
        } else {
            // Next item cannot fit in this bin's leftover: penalize dead space harder.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }

        // If next item is large and this bin is the only fitting one, keep it usable.
        if next_item_size > bin_residual && post_residual > 0 {
            score += 0.2 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins whose leftover stays near/below average
    // (avoid accumulating oversized holes).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it rather than opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when the current fit is poor
    // (large dead space) or few bins fit and we can start fresh.
    if is_new_bin {
        // Base penalty so new bins lose against decent fits.
        score += 30.0;
        // But if the item would leave a huge hole in an existing bin, opening fresh
        // becomes competitive: scale relief by the waste we avoid.
        let waste_elsewhere = (bin_capacity - item_size) as f64;
        let poor_fit_pressure = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        score -= 0.4 * waste_elsewhere * (poor_fit_pressure / bin_capacity as f64);
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 40.0 * (1.0 - progress);
        // Late in the stream, prefer consolidating into open bins.
        score += 60.0 * progress;
        // Many open bins: discourage opening yet another.
        score += 3.0 * open_bins_count as f64;
    }

    // Mild consolidation pressure: prefer bins that are already partially filled.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no future item can plausibly use.
    // Dead space = post_residual too small for the smallest plausible item (use lookahead when available).
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 20.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // penalize bins that would waste space the next item could have used.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys a bin that could have taken the next item.
            score += 6.0;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere or global residuals are bloated.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin grows with how many bins are already open.
        score += 25.0 + 0.4 * open_bins_count as f64;
        // If global mean residual is large, opening new bins is wasteful; penalize more.
        score += 0.15 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Perfect-fit escape hatch: a new bin is great for a huge item.
        if item_size >= 90 {
            score -= 60.0;
        }
    }

    // Mild preference for bins with residual close to global mean (balanced packing),
    // slightly favoring above-mean-residual bins for big items.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff * (1.0 - item_size as f64 / bin_capacity as f64);

    // Small penalty for leaving residual in the awkward 1..=9 band regardless.
    if post_residual >= 1 && post_residual <= 9 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: strongly prefer small post_residual, with non-linear (quadratic) coupling
    let mut score = norm_pr + 2.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: waste penalized more heavily as stream progresses
    score *= 1.0 + 0.8 * progress * (1.0 - 0.5 * norm_pr);

    // Lookahead: if next item fits exactly into post_residual, reward strongly (smooth bump)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs() / cap;
        let fit_bonus = (-3.0 * fit_gap).exp();
        score -= 1.5 * fit_bonus;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 1.0 + 0.5 * (fitting_bins_count as f64).min(3.0);
        // A new bin is more attractive late in the stream if open bins are fragmented
        if fitting_bins_count == 0 {
            score -= 1.5;
        }
    }

    // Mild penalty for bins deviating from mean residual (prefer balanced packing)
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    // Slight preference for tighter bins among many options
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Harmonic classes of post_residual: exact fill >> tiny dead space >> mid-range waste
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr < 10 {
        score -= 18.0; // negligible dead space class
    } else {
        // penalize by coarse class of waste (integer division thresholds)
        let class = (pr / 10) as f64; // 1..9
        score += class * 2.5;
        // mid-range residuals (20..50) are hardest to fill later
        if pr >= 20 && pr <= 50 {
            score += 8.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual harmonically matches next item
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // exact chain fit
        } else if next_item_size <= pr {
            score -= 12.0;
        } else {
            score += 6.0; // next item won't fit here -> bin likely closes
        }
    }

    // Last-chance bin: only open bin that can take this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 28.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 65.0; // default: prefer reusing open bins
        if fitting_bins_count == 0 {
            score -= 120.0; // no open bin fits -> must open
        } else if fitting_bins_count == 1 {
            score -= 20.0; // weak last-chance alternative still loses usually
        }
        // strategic: big item arriving next, keep current bins for small ones
        if next_item_size > 50 && item_size <= 50 {
            score -= 25.0;
        }
        // late in stream, avoid bin proliferation
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= t * 10.0;
    }

    // Coupling with mean residual across open bins: avoid spreading capacity unevenly
    score += (mean_residual - pr as f64) * 0.06;

    // Mild pressure against opening many bins over time
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 2.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Penalize a gap that is just barely too small for the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Tight fit reward: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 20.0 * (fill_ratio - 0.8);
    }

    // Open-bin pressure: when many bins are open, discourage spreading items
    // across bins unless the fit is very tight; encourage consolidation.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64;
        // But soften for very tight fits so consolidation still wins.
        if fill_ratio > 0.9 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual < 10 {
            score += 40.0; // cancel reward for unusable dead space
        }
    }

    // New-bin candidate: penalize opening a fresh bin unless no good fit
    // exists among open bins. A fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If many open bins have large mean residual, opening new bins is
        // especially wasteful.
        score += mean_residual * 0.3;
        // Late in the stream, avoid opening new bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

