    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins
        score += 15.0 + open_bins_count as f64 * 3.0;
        // If mean residual is large, opening new bin is wasteful
        score += mean_residual * 0.5;
        // Early in stream, new bins are cheaper; late, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    } else {
        // Reward using bins with larger pre-existing residual (consolidation)
        score -= (bin_residual as f64 - mean_residual) * 0.3;
        // Mild penalty per open bin to discourage bin sprawl
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer placing larger items earlier (best-fit decreasing effect via item size)
    score -= item_size as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
