    let waste_term = (pr / cap).powi(2) * cap * (0.5 + progress);
    score += 0.8 * waste_term;

    // Reward tight fits with smooth cubic falloff
    let tightness = 1.0 - pr / cap;
    score -= 15.0 * tightness.powi(3);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Penalize opening new bins when good fits exist (new-bin candidate detection)
    if bin_residual == bin_capacity {
        let nxs = next_item_size as f64;
        let lookahead_fit = if nxs > 0.0 { (nxs / cap - pr / cap).abs().min(1.0) } else { 0.0 };
        score += 10.0 + 8.0 * (1.0 - progress) - 6.0 * lookahead_fit;
        if fitting_bins_count > 0 {
