        }
    }

    // Mild penalty for bin proliferation relative to mean residual balance
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strong bonus when post_residual is small.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        // Harmonic classes: partition post_residual into integer-division classes of 10.
        let class = post_residual / 10;
        let in_class = post_residual % 10;
        // Dead space penalty grows for classes that are hard to fill (small residuals).
        if post_residual < 10 {
            score += 25.0; // unusable sliver for items >= 1? still tiny
        } else if class <= 2 {
            score += 8.0 + in_class as f64; // awkward small residual
        } else if class >= 5 {
            score -= 4.0; // roomy residual, still useful
        }
        // Fractional coupling: residual fraction of capacity
        let frac = pr / cap;
        score += 10.0 * frac * frac; // quadratic waste penalty
    }

    // Lookahead coupling: reward if next item fits in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size {
        // penalize creating residual that just misses next item slightly
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 5.0 {
            score += 6.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets baseline near mean residual pressure.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are poor (high mean residual mismatch)
        let pressure = (mean_residual - item_size as f64).abs();
        score = 0.5 * cap + pressure * 0.5 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
        // Late in stream, slightly prefer reusing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    }

    // Modulo harmonic tiebreak on item_size classes
    score += ((item_size % 10) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (waste ratio coupling).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 8.0;

    // If next item fits exactly in the post-residual, big reward (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 25.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Post-residual too small for lookahead: dead space penalty.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * -1.5;
        if mean_residual > item_size as f64 * 2.0 {
            score += 20.0; // plenty of room elsewhere; opening a bin is wasteful
        }
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing ones.
    score += open_bins_count as f64 * 2.0;

    // Slight preference for bins with residual close to item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly empty post-residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or closely) matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (20.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        // Exact lookahead match is a jackpot.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving residual slightly below the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Prefer bins with residual below mean (tight packing), penalize
    // bins wasting more space than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item
    // is large and fits poorly anywhere else.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize bins whose residual was already small (avoid wasting a nearly-full bin's value... actually
    // prefer using bins with small residual first so they close out).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post_residual, big reward;
    // if next item cannot fit in post_residual but could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage unless
    // this bin's fit is poor or this is the last fitting bin.
    if bin_residual == bin_capacity {
        // Brand-new bin: base cost of opening a bin, reduced when few bins fit the item
        // (avoid fragmentation) or stream is early (room to grow).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 55.0;
        if fitting_bins_count == 0 {
            open_cost -= 30.0;
        } else if fitting_bins_count == 1 {
            open_cost -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        open_cost += 25.0 * progress;
        // If mean residual across open bins is large, opening a new bin wastes capacity.
        open_cost += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 30.0;
        // If the new bin would end up with tiny post_residual (item ~ capacity), that's fine.
        if post_residual <= 20 {
            open_cost -= 35.0;
        }
        score += open_cost;
    } else {
        // Existing bin: slight reward when it's one of few options (last-chance bin).
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Reward matching against mean residual: bins near the mean are "typical" targets;
        // keep extreme residuals for special items.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Mild penalty for too many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of residual.
    let mut score = x * x * (3.0 - 2.0 * x) * cap * 0.5 + pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream -> tolerate larger residuals; late stream -> penalize heavily.
    let coupling = (x - 0.5) * (x - 0.5) * (1.0 + 2.0 * progress) * cap;
    score += coupling * 0.8;

    // Reward filling a bin more completely as stream progresses.
    score -= (1.0 - x) * (1.0 - x) * progress * cap * 0.6;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Many open bins: mild penalty to avoid bin proliferation.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 + 3.0 * progress;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += (next_item_size as f64 - pr) * 0.05;
    }

    // Deviation from mean residual: penalize outliers (dead-space imbalance).
    score += (pr - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let r = post_residual;
    let mod10 = (r % 10) as f64;
    let mod20 = (r % 20) as f64;
    let mod25 = (r % 25) as f64;
    let mod50 = (r % 50) as f64;

    // Reward residuals that align with harmonic classes (likely reusable)
    let harmonic_bonus = 8.0 * (mod10 / 10.0) + 4.0 * (mod20 / 20.0) + 3.0 * (mod25 / 25.0) + 2.0 * (mod50 / 50.0);
    score += harmonic_bonus;

    // Penalize small unusable dead space (0 < r < 10) strongly
    if r > 0 && r < 10 {
        score += 30.0;
    }
    // Perfect fit is excellent
    if r == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is good if it leaves a large round residual class later
        if item_size % 25 == 0 || item_size % 50 == 0 {
            score -= 10.0;
        }
        // Avoid proliferation of bins when many can fit
        if fitting_bins_count > 3 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 35.0;
        } else if next_item_size <= r {
            score -= 6.0 * (1.0 - (r - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; small penalty proportional to wasted alignment
            score += 3.0 * ((next_item_size - r) as f64 / 100.0);
        }
    }

    // Mean residual coupling: prefer bins near the mean (balance preservation)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Late-stream tightening: as stream progresses, prefer tight fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Prefer filling fuller bins (post_residual small) as stream advances
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

