        let match_bonus = (1.0 - diff / bin_capacity as f64).max(0.0);
        score -= 6.0 * match_bonus * match_bonus;

        // Penalize leaving dead space the next item cannot use.
        if next_item_size as u32 > post_residual && post_residual > 0 {
            score += 3.0;
        }
    }

    // Penalize large post_residual relative to mean residual (creating unusable gaps).
    score += 0.5 * ((post_residual as f64 - mean_residual) / bin_capacity as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
