        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins when open bins still have room on average.
        score += 55.0 * crowding;
        // Slightly favor new bins late in the stream (consolidation less valuable).
        score -= 10.0 * progress;
        // If no bin can fit the item at all, new bin is necessary.
        if fitting_bins_count == 0 {
