        }
    } else {
        // last item: prefer closing bins completely
        harmony -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening new
    // bin alternatives by rewarding this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
