        harmony += 15.0 * (1.0 - progress);
    }

    // Tightness bonus: small relative waste
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    harmony -= 20.0 * (1.0 - tightness);

    // Mild pressure to reuse crowded bin sets
    harmony -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score += harmony;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    // A gap is "dead" if it is smaller than the smallest plausible item.
    let min_item = 1.0;
    let dead_threshold = 15.0; // gaps below this are rarely reusable
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    // Zero residual is perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving gaps that cannot fit the lookahead item but could
    // have fit it before placement (wasted opportunity).
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u32) < next_item_size && (bin_residual as u32) >= next_item_size {
            score += 12.0;
        }
        // Reward leaving exactly enough room for the next item (chaining).
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        // Neutral base; opening a new bin costs one bin but preserves
        // large residuals of existing bins.
        score = 60.0 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild progress adaptation: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // matches the next item size well (chain placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits perfectly in this bin after current placement
            if gap == 0.0 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item would NOT fit: penalize leaving a gap smaller than next item
            score += 20.0 + 0.3 * gap;
        }
    }

    // Compare post_residual relative to mean residual: prefer bins
    // that bring their residual closer to the mean (balanced packing).
    let pre_gap = (bin_residual as f64 - mean_residual).abs();
    let post_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * (pre_gap - post_gap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize large dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in stream: slightly prefer filling existing bins densely;
    // late in stream: keep flexibility, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // near-perfect fit bonus handled above; tiny leftover is fine
    } else if post_residual >= 10 && post_residual <= 40 {
        // usable residual band: mild reward scaled by tightness
        score -= 8.0 * (1.0 - (post_residual as f64 - 10.0) / 30.0);
    } else if post_residual > 60 {
        score += 6.0; // wasteful placement
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0; // perfect pairing
        } else if post_residual as i64 >= next_item_size as i64 {
            score -= 10.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else if (post_residual as f64) < nxt && (post_residual as f64) > cap * 0.25 {
            score += 5.0; // blocks next item into sizeable dead space
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or stream is early / many bins already open with poor mean residual.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap).max(0.001);
        let mut new_bin_score = 55.0; // base reluctance to open a new bin
        new_bin_score -= 20.0 * (1.0 - progress);           // cheaper early in stream
        new_bin_score -= (open_bins_count as f64).min(20.0) * 1.5; // allow spread when many bins open
        new_bin_score -= (mean_residual / cap - 0.5).max(0.0) * 30.0; // open when existing residuals are bloated
        new_bin_score += item_size as f64 * 0.2;            // large items prefer fresh bins
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a bin
        }
        score = score.max(0.0) + new_bin_score;
    }

    // Slight preference for fuller bins overall (best-fit flavor).
    score += (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 0.6 * poly * cap;
    // Penalize wasted space relative to mean residual across open bins
    score += 0.25 * (pr - mean_residual).abs();
    // Reward tight fits (small post_residual) with smooth decay
    score -= 0.4 * cap * (-norm_pr * 3.0).exp() * (0.5 + 0.5 * progress);
    // Lookahead: reward residual that could host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 0.5 * cap * (-gap / (0.25 * cap)).exp();
        if pr < nx {
            score += 0.3 * (nx - pr);
        }
    }
    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }
    // Mild penalty for spreading across many bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    // New-bin candidate: keep neutral baseline, penalize slightly unless current bins fit poorly
    if bin_residual == bin_capacity {
        score = cap + 0.5 * mean_residual - 10.0 * (fitting_bins_count == 0) as i32 as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but dead space below a small-item threshold is wasted.
    let small_threshold = cap * 0.2;
    if (post_residual as f64) < small_threshold {
        score -= (small_threshold - post_residual as f64) * 0.8;
    }

    // Harmonic class of post_residual: modulo classes of 10 (classic capacity fractions).
    let pr = post_residual as i64;
    let cls = pr % 10;
    // Residuals in classes {0,1,2,9} are near-perfect or near-useless; treat differently.
    if cls == 0 {
        score -= 12.0; // perfect packing
    } else if cls >= 7 {
        score += 6.0; // sliver residuals unlikely to be filled
    }

    // Integer-division thresholds on post_residual: which future item classes could fit.
    // Item sizes 1..100: residual < 10 fits almost nothing -> heavy penalty unless near 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 15.0 - waste * 0.3;
            // Harmonic pairing: next item exactly consumes residual class
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 8.0;
            }
        } else {
            score += 5.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins harder.
    let spread_pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += spread_pressure * 0.5;

    // New-bin candidate: empty bin gets a moderate default score; only chosen if
    // all open bins score worse (poor fits / slivers).
    if bin_residual == bin_capacity {
        score = cap * 0.55
            + (next_item_size as f64) * 0.15
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Mid-range dead space (10..20) is also wasteful for typical item sizes.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        score -= 25.0 / post_residual as f64;
    }

    // Prefer bins whose residual closely matches the item (tight coupling).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.35 * tightness;

    // Open-bin pressure: discourage scattering across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is close to filling post_residual exactly, extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are nearly exhausted
    // or this item fits nothing well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 25.0 - 20.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight early-stream preference to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fill bin perfectly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect pairing: place here
        } else {
            // penalize mismatch relative to gap size, softer for small gaps
            score += gap * 0.35;
        }
        // If next item fits in the post-residual, mild bonus
        if next_item_size <= post_residual {
            score -= 8.0 + 0.05 * (post_residual - next_item_size) as f64;
        }
    }

    // Penalize creating tiny unusable dead space (relative to item size domain 1..100)
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 6.0 + (50 - post_residual.min(50)) as f64 * 0.2;
    }

    // Prefer bins that are already partially filled: tighter residual relative to mean is good
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current residuals are all poor fits.
    if bin_residual == bin_capacity {
        let mut base_penalty = 30.0;
        // If this bin is one of few fitting options and open bins are fragmented, allow opening
        if fitting_bins_count == 0 {
            base_penalty -= 40.0; // no open bin fits -> new bin necessary
        } else if fitting_bins_count == 1 {
            base_penalty += 15.0; // there is exactly one fit; keep last-chance bonus decisive
        }
        // Early in stream, tolerate more bins; late in stream, consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        base_penalty += progress * 10.0;
        score += base_penalty;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items,
    // but only when this is not the last-chance bin.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 {
        score += 25.0;
    }

    // Lookahead: if the next item fits perfectly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.2 * over;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be more willing to spread items
    // across bins (encourage packing into existing bins with good fits);
    // late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into bins below mean residual (fill emptier bins).
    if open_bins_count > 1 {
        let diff = (mean_residual - bin_residual as f64) / cap;
        score += 8.0 * diff;
        // Extra pressure to consolidate when many bins are open.
        score += 0.5 * (open_bins_count as f64).ln() * (1.0 - tightness);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post residual of a fresh bin is large; make it compete honestly
    // but with a mild bias against opening bins when consolidation works).
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) * 3.0;
        score += open_pressure;
        // If the item is large, a fresh bin is relatively more acceptable.
        score -= 0.1 * item_size as f64;
    }

    // Small deterministic tie-breaker based on residual structure.
    score += 0.01 * (post_residual % 7) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post-residual, with smooth non-linear shaping
    let mut score = post * (1.0 + 0.35 * progress);

    // Non-linear penalty for awkward dead space (quadratic coupling with progress)
    score += 8.0 * norm_post * norm_post * cap * (0.4 + 0.6 * progress);

    // Reward tight fits (post_residual near zero) with smooth cubic term
    score -= 6.0 * (1.0 - norm_post).powi(3) * (1.0 + 0.5 * progress);

    // Penalize bins whose residual deviates from the mean residual (prefer homogeneous fill)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate: smooth penalty growing with stream progress and open bins
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 15.0 + 20.0 * progress + 10.0 * openness;
    }

    // Lookahead coupling: reward if the next item fits the post-residual well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 5.0 * (1.0 - slack).powi(2);
        } else {
            score += 3.0 * (nxt - post) / cap * cap / cap;
        }
    }

    // Mild reward for consolidating into fewer bins as stream matures
    score -= 2.0 * progress * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes
    // Residuals that are perfect fits for common small items are valuable.
    let pr = post_residual;
    // Perfect closure reward: exact fill
    if pr == 0 {
        score -= 60.0;
    }
    // Harmonic classes: residuals divisible by common item sizes are reusable
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        for d in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
            if pr >= d && pr % d == 0 {
                reuse_bonus += 8.0;
            }
        }
        // small residuals (<=10) are near-dead
        if pr <= 10 {
            reuse_bonus += 6.0; // near-closure is good
        } else if pr < 20 {
            reuse_bonus -= 12.0; // awkward dead zone
        }
        score -= reuse_bonus;
    }

    // Lookahead coupling: does post_residual fit next item exactly or well?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; penalize proportionally
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
        // modular harmony between post_residual and next_item_size
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 10.0;
        }
    } else {
        // last item: strongly prefer tight fits
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fit via relative tightness
        let tight = (item_size as f64) / (bin_residual as f64);
        score -= 15.0 * tight;
    }

    // Prefer keeping mean residual balanced: penalize bins far above mean residual
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Early in stream: be more willing to open new bins (keep options open)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus openness incentive
        let mut new_bin = 40.0;
        new_bin -= 20.0 * progress; // later => cheaper to reuse existing bins
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin -= 8.0; // roomy bin good for upcoming large items
        }
        if open_bins_count > 6 {
            new_bin += (open_bins_count as f64 - 6.0) * 2.0; // discourage bin sprawl
        }
        score = new_bin + 0.5 * post_residual as f64;
    } else {
        // mild sprawl penalty for using many open bins early
        score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Integer-division threshold shaping on post_residual
    let q = pr / 10;
    score += match q {
        0 => -5.0,
        1 => 6.0,
        2 => 0.0,
        3 => -3.0,
        4 => -4.0,
        _ => -2.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (items are >= 1, but tiny gaps are practically unusable)
    // are heavily penalized as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 50.0;
    } else {
        // Usable leftover: mild reward proportional to how much was consumed.
        score -= 0.15 * item_size as f64;
    }

    // Dead space as fraction of capacity: quadratic penalty for leaving a
    // small-but-nonzero gap relative to what remains.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    if residual_frac > 0.0 && residual_frac < 0.15 {
        score += 40.0 * (0.15 - residual_frac);
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, allow opening new bins when fits are poor.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open, reward when few.
        score += 10.0 * open_pressure.sqrt();
        // Opening a new bin is attractive if the best fit would leave a bad gap.
        score -= 0.1 * mean_residual;
    } else {
        score -= 2.0 / (1.0 + open_pressure);
    }

    // Lookahead coupling: reward if the next item can use the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for exact-ish match of the gap to the next item.
            let gap_match = (post_residual as f64 - next_item_size as f64).abs();
            score -= 8.0 / (1.0 + gap_match);
        } else {
            score += 6.0;
        }
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about leftover space since fewer chances remain to recover.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * residual_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), with mild convexity.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.01;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin becomes exactly full
        } else if next_item_size < post_residual {
            // partial chain value decays with leftover after next item
            let after_next = post_residual - next_item_size;
            score -= 30.0 - (after_next as f64) * 0.25;
        } else {
            // next item can't follow; post_residual risks becoming dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Relative-to-mean-residual coupling: avoid bins whose residual deviates badly
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.08;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin offers a decent fit (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        // penalize new bin unless item is large or existing fits are poor
        score += 25.0 - (item_size as f64) * 0.2;
        // fewer open bins -> cheaper to open a new one
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
    }

    // Prefer placing into bins with low current residual (denser bins first)
    score += (bin_residual as f64) * 0.05;

    // Slight preference to keep number of open bins low
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later
    if post_residual < 10 {
        score += 25.0; // nearly-full bin is fine actually; small residual is good
    } else if post_residual < 30 {
        score -= 10.0; // awkward leftover zone
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post residual accommodates next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (post_residual as f64 - next_item_size as f64 + 1.0).sqrt();
        } else {
            score += 8.0; // breaks the chain
        }
        // If next item exactly matches post residual, big bonus
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // New-bin candidate logic: only attractive when fits are poor or many bins open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (post_residual as f64) > 0.6 * (bin_capacity as f64);
        score += 30.0; // base penalty for opening a bin
        if poor_fit { score -= 45.0; }
        if open_bins_count > 8 { score += 15.0; } // discourage bin sprawl
        if progress > 0.8 { score += 10.0; } // late stream: consolidate
        if mean_residual > 40.0 { score += 12.0; } // existing slack is abundant
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Fragmentation pressure: penalize leaving medium residuals
    let frag = (post_residual as f64 / 100.0).powi(3);
    score += 30.0 * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: quadratic waste penalty, amplified as stream progresses.
    let mut score = pr * (1.0 + 2.0 * progress * prn) + 12.0 * progress * prn * prn;

    // Reward tight fits (small post_residual relative to item size).
    let item = item_size as f64;
    score -= 6.0 * (item / cap) / (1.0 + prn * 4.0);

    // Lookahead: reward if next item fits in the post residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = ((pr - nxt).abs()) / cap;
        score += 4.0 * (1.0 - fits) * (1.0 + progress);
        score -= 3.0 * fits * (1.0 - gap);
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += 0.15 * open_bins_count as f64 * prn;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // New-bin candidate: make it unattractive unless residual would be large and stream early,
    // or all existing fits are terrible.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 6.0;
        score += 18.0 - early_bonus + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below mean (tighter bins).
    score += 2.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 bands
    let band = post_residual % 10;
    // Penalize residuals that are "awkward" classes (1..9 small leftovers are dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if band <= 4 {
        score += 6.0;
    } else if band >= 5 {
        score += 2.0;
    }

    // Integer-division thresholds: perfect fits / large residuals are great
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 50 {
        score -= 15.0;
    } else if post_residual >= 30 {
        score -= 8.0;
    }

    // Coupling with next item (lookahead k=2)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly here -> strong reward
            score -= 20.0;
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // next item won't fit here; leftover is likely dead
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual >= 20 {
            score -= 10.0;
        }
    } else if fitting_bins_count > 1 {
        // tightness competition: prefer bins where this item is a tight fit
        let tight = (item_size as f64) / (bin_residual as f64);
        score -= tight * 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; attractive only if no good fit exists
        score = 55.0;
        if fitting_bins_count == 0 {
            score = 10.0; // forced open
        } else if mean_residual < item_size as f64 + 8.0 {
            score -= 25.0; // existing bins are nearly full anyway
        } else if fitting_bins_count == 1 {
            score += 20.0; // keep the last-chance bin available
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // many open bins: discourage opening more
        score += open_bins_count as f64 * 2.0;
    }

    // Mean residual context: if this bin is far below mean residual, it's a good filler
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are pure loss.
    let min_item = 1.0f64.min(cap); // items can be as small as 1
    if (post_residual as f64) < 10.0 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if (post_residual as f64) < 20.0 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = (item_size as f64) / (bin_residual as f64);
        score -= 30.0 * tightness;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a "junk" bin; prefer filling it.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // New-bin candidate: make it attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + 0.35 * open_bins_count as f64 - 10.0 * progress;
        if fitting_bins_count == 1 {
            score += 120.0; // never open a new bin when exactly one open bin fits
        }
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score -= 5.0; // empty bin always fits the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight non-linearity.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: strongly reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let gap = post - next;
            // Perfect chain fit gets a big bonus.
            if gap == 0.0 {
                score -= 30.0;
            } else {
                score -= 12.0 * (-gap / 20.0).exp();
            }
        } else {
            // Next item cannot use this bin's leftover; penalize proportional waste.
            score += 0.15 * (next - post);
        }

        // Bonus if next item also fits in the bin's residual before placing current item
        // (bin remains useful for the future).
        if next_item_size as f64 <= post {
            score -= 5.0;
        }
    }

    // Relative-to-mean-residual coupling: placing into a bin far below mean residual
    // balances the workload across bins.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin offers a decent fit. Penalize new bins mildly so tight fits win,
    // but less when many bins are open (fragmentation pressure).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 25.0 - 15.0 * pressure;
    }

    // Mild reward for consolidating into few bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.5 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize leaving large unusable dead space relative to smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny sliver is wasted capacity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            score += 0.35 * (post_residual as f64);
        } else {
            // Reward leaving space exactly usable by next item.
            let slack = (post_residual as f64) - nx;
            score -= 6.0 * (1.0 - slack / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many fitting bins: prefer the one with smallest residual (best fit),
    // penalize spreading into already-crowded bin sets.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in stream, be pickier (penalize mediocre fits);
    // late in stream, just close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64) / cap;

    // Global pressure: few open bins relative to mean residual -> prefer
    // filling existing bins; many open bins with high mean residual -> open new.
    if open_bins_count > 0 {
        let pressure = mean_residual / cap;
        score += 8.0 * pressure * (post_residual as f64 / cap);
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or existing fits are poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 18.0 - 20.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score += 10.0;
        }
    }

    // Small bonus for exact fill.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual

    // Base: prefer small post-residual, with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * t * t);

    // Penalize mid-range dead space quadratically (hard-to-fill residuals)
    let dead = x * (1.0 - x); // peaks at x=0.5
    score += 30.0 * dead * (0.5 + t);

    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * (1.0 - x) * (1.0 - x) * (0.3 + t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64;
            score -= 10.0 * (1.0 - slack / cap) * (0.5 + 0.5 * t);
        } else {
            score += 12.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty when bin is far below mean residual (avoid scattering)
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + t);

    // Slight preference for reusing bins over opening new ones early
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: classify dead space by integer division thresholds
    let class = post_residual / 10; // classes 0..=10
    // Dead space that cannot host even the smallest plausible item is heavily penalized
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Nonlinear dead-space penalty: small residuals are "dead" unless next item fits
        let dead = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += dead * (18.0 + 12.0 * class as f64) * (0.6 + 0.4 * progress);
        // Harmonic bonus: residual in classes that commonly recombine (multiples of half/quarter capacity)
        if post_residual == bin_capacity / 2 { score -= 8.0; }
        if post_residual == bin_capacity / 4 || post_residual == 3 * bin_capacity / 4 { score -= 4.0; }
    }

    // Lookahead coupling: reward if next item exactly fills the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0; // chain completion
        } else if post_residual - next_item_size <= 10 {
            score -= 12.0; // near-chain
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 40.0
            + 10.0 * (open_bins_count as f64).ln().max(0.0)
            - 15.0 * progress
            - spread.min(30.0);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // large next item benefits from fresh capacity
        }
    }

    // Mild preference for bins already below mean residual (concentrate fill)
    score += (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.3;

    // Slight early-stream conservatism: keep bins balanced at the start
    score += (1.0 - progress) * 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward bins whose leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened if many bins already open or
        // current fit would leave large dead space.
        let dead = (bin_residual - item_size) as f64;
        score += 20.0 + open_bins_count as f64 * 0.5 - dead * 0.15;
        if fitting_bins_count == 0 {
            score -= 50.0; // forced new bin anyway
        }
    } else {
        // Mild preference for fuller bins (small residual before placement).
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Late-stream tightening: favor consolidation as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled against mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let slack = pr - nxt;
            score -= 12.0 - 0.15 * slack; // next item still fits, mild bonus decaying with slack
        } else {
            let gap = nxt - pr;
            score += 0.25 * gap; // next item won't fit here; penalize awkward remainder
        }
        // If post_residual becomes dead space (< min plausible item), penalize hard
        if post_residual > 0 && post_residual < 5 {
            score += 20.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 - 2.0 * pressure - 5.0 * progress;
        // If next item is large and current item is small, opening fresh bin is decent
        if next_item_size > item_size * 2 {
            score -= 8.0;
        }
    }

    // Penalize leaving residuals that no typical item can use (very small or awkward zones)
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (post_residual that nothing can use).
    if post_residual > 0 {
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            // Dead space that even the next item cannot use.
            score += 0.5 * post_residual as f64;
        } else {
            score -= 0.2 * post_residual as f64;
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented or fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening new bins normally; ease up when many bins are open and fragmented.
        let mut penalty = 25.0 + 20.0 * (1.0 - fragmentation);
        if open_bins_count == 0 {
            penalty = -50.0; // must open a bin
        }
        // Late in the stream, consolidation matters more.
        penalty += 10.0 * progress;
        // If this item is large relative to mean residual, new bin may be wise.
        if (item_size as f64) > mean_residual {
            penalty -= 15.0;
        }
        score += penalty;
    }

    // Mild preference for bins with residuals near common item sizes (modular harmony).
    let harmony = ((post_residual as i64 - 50).abs()) as f64;
    score += 0.05 * harmony;

    // Small penalty proportional to number of open bins to encourage consolidation.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.35 * progress * pr_norm * pr_norm);

    // Penalize dead space quadratically as stream progresses (residuals become less reusable).
    score += 18.0 * pr_norm * pr_norm * (0.3 + 0.7 * progress);

    // Perfect fit reward: smooth bell around zero post-residual.
    score -= 22.0 * (-pr_norm * 12.0).exp();

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: reward if next item fits in the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0);
        let fit_quality = 1.0 - (fits / cap);
        score -= 8.0 * fit_quality * (1.0 - progress);
    } else {
        // Last item: minimize waste strongly.
        score += 10.0 * pr_norm;
    }

    // Mild penalty when bin residual deviates from mean residual (prefer uniformity early).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // Encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 0.05 * pr_norm;

    // Slight preference for tighter bins overall.
    score += 3.0 * (1.0 - (bin_residual as f64 / cap)) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: tiny slivers (mod classes) are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 5 {
        score += 40.0; // unusable sliver
    } else if pr < 10 {
        score += 25.0;
    } else {
        // residue classes mod 10: values leaving multiples of 10 pair well with common sizes
        let r = pr % 10;
        if r == 0 {
            score -= 12.0;
        } else if r >= 7 {
            score += 8.0;
        }
    }

    // Reward bins that can also host the lookahead item (harmonic pairing).
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0;
        let gap = (pr - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 10.0; // near-perfect two-item chain
        }
    } else if next_item_size > 0 {
        // lookahead cannot follow here; if it can't fit anywhere else either, keep flexibility
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual across open bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish residual (capacity), penalize slightly less when
    // open bins are crowded and the item is large (poor fit everywhere).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else if item_size >= 60 || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0 + 20.0 * (1.0 - progress); // early on, keep bins open
        }
    }

    // Slight preference for compacting bins when many bins are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..10) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
