    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins deviating below mean residual (keeps large gaps available).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: acceptable early or when nothing fits well; penalize otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a near-perfect fit (small dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else {
        let pr = post_residual as f64;
        // Penalize unusable slivers: residual smaller than the minimum item size.
        if pr < 10.0 {
            score += 80.0 * (10.0 - pr);
        }
        // Mild penalty proportional to leftover, to prefer tight fits generally.
        score += 0.25 * pr;
    }

    // 2-step lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward chainability, especially a tight chain (little slack left after next item).
        let chain_slack = post_residual - next_item_size;
        score -= 60.0 + 0.5 * chain_slack as f64;
        if chain_slack == 0 {
            score -= 100.0; // perfect two-item chain
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for the next item: penalize relative to how close it was.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.6 * gap;
    }

    // Compare against mean residual across open bins: prefer bins that are
    // already "below average" fill (small residual) to consolidate waste.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Early in the stream, opening bins is cheaper; later, avoid bin proliferation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 120.0 * progress;
        // Penalize opening new bins when many bins are already open.
        score += 8.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space that is too small to plausibly hold future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    // into existing bins rather than spreading.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score += 10.0 * consolidation;
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep
    // residuals flexible); late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it so it only wins when fits are terrible.
        let mut new_bin_penalty = 45.0;
        // Early on, opening bins is cheaper; late, it is expensive.
        new_bin_penalty *= 0.5 + progress;
        // If the current item is large relative to mean residual, existing bins
        // are poor fits, so soften the penalty.
        new_bin_penalty -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If no open bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 60.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Late stream: reward tight packing more aggressively.
        score -= 15.0 * progress * fit_ratio;
    }

    // Mild penalty for very small items wasting large-residual bins.
    if item_size < 20 && bin_residual > 70 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
