    let mut score = pr * (1.0 + 0.8 * progress * progress)
        - 22.0 * (pr / cap).powi(2) * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly early in the stream
    score -= 15.0 * (1.0 - pr / cap).powi(3) * (1.0 - progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.25 * (pr as f64 - mean_residual).abs();

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: penalize if post_residual cannot fit next item but almost could
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else if nx - pr <= 10.0 {
            score += 8.0 * (nx - pr);
        }
    }

    // New-bin candidate: neutral baseline with mild late-stream penalty
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 5.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors
    // capture "usable leftover" classes (e.g., exact multiples of common
    // item-size harmonics leave space that future items can fill).
    let pr = post_residual;
    let r4 = pr % 4;
    let r8 = pr % 8;
    let r16 = pr % 16;
    let d16 = pr / 16; // integer-division threshold class

    // Reward post-residuals that sit in "harmonic" residue classes:
    // multiples of 4 and 8 are more likely to be filled by later items.
    score -= 6.0 * ((r4 == 0) as i32 as f64) + 4.0 * ((r8 == 0) as i32 as f64) + 3.0 * ((r16 == 0) as i32 as f64);

    // Penalize awkward mid-range dead space via integer division bands.
    if d16 >= 1 && d16 <= 2 && r16 != 0 {
        score += 8.0; // 16..47 leftover: dead zone
    }
    if pr == 0 {
        score -= 12.0; // perfect fill
    }

    // Lookahead coupling: harmonic class of next_item_size vs post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward closeness of fit (harmonic match)
            let gap = pr - next_item_size;
            score -= 5.0 * (1.0 - gap as f64 / bin_capacity as f64);
            if gap % 4 == 0 {
                score -= 3.0;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
        // exact harmonic pairing: post_residual equals next item size
        if pr == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0
            - 15.0 * ((post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64))
            + 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packing).
    score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Capacity fraction thresholds on post_residual.
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score -= 6.0; // nearly full bin is great
    } else if frac > 0.5 {
        score += 3.0; // leaving more than half empty is wasteful
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 / (total_items.max(1) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
