    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Compare against mean residual across open bins: prefer bins whose
    // post-residual deviates favorably (smaller) from the mean.
    score += 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to what open bins would leave behind, or stream is early.
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral baseline, penalize slightly so it's chosen
        // only when open-bin fits are bad; relax as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 - 20.0 * progress;
        // If next item is large, a fresh bin with room for it is attractive.
        if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 {
            score -= 10.0;
        }
    }

    // Slight preference for using fewer bins overall.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, already in score.

    // Strong penalty for wasted residual that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward near-perfect fits (residual becomes very small but nonzero handled above).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // bins fit poorly. Penalize the empty bin mildly so tight fits in open bins win,
    // but let it win when all fitting open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: proportional to current item size
        // (bigger items "justify" a new bin less since they fill it quickly anyway).
        score = 55.0 + 0.25 * item_size as f64;
        // Early in the stream, opening bins is cheap (plenty of items to come
        // that can fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many open bins already, discourage yet another bin.
        score += 0.6 * open_bins_count as f64;
        // If the next item is large, a fresh bin is valuable (it can host it).
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 0.3 * next_item_size as f64;
        }
        // If no open bin can even fit the item... can't happen here since candidate
        // fits, but guard: if many bins fit, new bin is less attractive.
        if fitting_bins_count > 2 {
            score += 5.0 * (fitting_bins_count as f64 - 2.0);
        }
        return score;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward
    // (chained placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item uses the leftover.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: mild penalty scaled by dead space.
            score += 0.1 * post_residual as f64;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean: placing into a
    // bin with residual far above mean wastes its large capacity; placing into a
    // below-mean-residual bin consolidates fullness.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: late in the stream, prioritize closing bins out (fill them fully),
    // so reward placing into the least-empty bin more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.2 * bin_residual as f64;

    // Mild penalty when many bins are open: prefer consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Small deterministic tie-breaker based on residual to stabilize selection.
    score += 0.01 * (post_residual as f64).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    let mut score = pr + 40.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 12.0 * (0.5 + progress);

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - nxt) / cap).max(0.0);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln() * (1.0 + 3.0 * progress);

    // Encourage bins below mean residual (consolidation)
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: how "reusable" is the post residual?
    // Class residuals that are multiples of common item sizes (10..80 grid)
    // are more likely to be filled later.
    let pr = post_residual;
    let harmony = if pr == 0 {
        -40.0 // perfect fit: reward strongly
    } else {
        let mut h = 0.0;
        // check divisibility by coarse harmonic steps
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 { h -= 3.0; }
        }
        // dead-zone penalty: tiny unusable slivers
        if pr < 10 { h += 25.0; }
        // integer-division threshold classes on post_residual
        let class = pr / 10; // 0..10
        h -= (class as f64) * 1.5; // bigger leftover generally better
        h
    };
    score += harmony;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // partial fit quality: modulo harmony of the chain
            let r2 = pr - next_item_size;
            score -= 8.0;
            if r2 < 10 && r2 > 0 { score += 10.0; }
        } else {
            score += 4.0; // next item won't chain here
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && pr >= 0 {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly so we prefer good fits,
    // but allow opening when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        // fresh bin has full residual 100 -> base score already 100 (post=100)
        // scale pressure by open bins and mean residual fragmentation
        let frag = if mean_residual > 0.0 { (mean_residual / bin_capacity as f64).powi(2) } else { 0.0 };
        score -= 20.0 * frag;
        // late in stream, prefer consolidation into open bins
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * t;
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for next item: mild penalty
        score += 3.0;
    }

    // Tight fit reward: fraction of bin used by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with below-mean residual (fill emptier bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 25.0 + open_bins_count as f64 * 0.5;
        // Cheap if item is large and would leave big gap elsewhere anyway.
        score = base - fill * 5.0;
        if fitting_bins_count == 1 {
            // An open bin is the last chance; opening new bin is costly.
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (dead space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + 20.0 * (5 - post_residual) as f64;
    }

    // Aggressive 2-step lookahead: perfect chaining with next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits here afterwards: mild reward proportional to leftover
            let two_step_left = post_residual - next_item_size;
            score -= 100.0 - 0.5 * two_step_left as f64;
        } else {
            // next item won't fit after placing here: penalize proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    } else {
        // Last item: closing a bin fully is ideal
        score += 0.0;
        if post_residual > 0 {
            score += 10.0;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with small residual (tight bins) when mean is large
    let res = post_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { res };
    score += 0.4 * (res - mean);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred, unless they would leave big waste
        score += 60.0;
        if post_residual as f64 > mean + 30.0 {
            score -= 80.0; // open a fresh bin instead of fragmenting
        }
    }

    // Slight preference to fill older/denser bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Penalize creating residual windows that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
