pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = pr / cap; // 0..1 residual fraction after placement

    let mut score = pr;

    // Smooth non-linear coupling: quadratic dead-space penalty grows with stream progress
    let dead = fit_norm * fit_norm * (1.0 + 2.0 * progress) * cap;
    score += dead;

    // Reward tight fits smoothly (cubic falloff)
    score -= 3.0 * cap * (1.0 - fit_norm).powi(3);

    // Lookahead: penalize if post-residual cannot smoothly serve next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 2.0 * (ns / cap) * cap * (1.0 - (pr - ns) / cap);
        } else {
            score += 1.5 * (ns - pr);
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 2.5 * item_size as f64;
    }

    // Mild pressure to prefer crowded bins as more bins are open
    let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).clamp(0.0, 1.0);
    score += open_norm * (pr - mean_residual).abs();

    // Progress-weighted preference for filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += (0.5 + 2.0 * progress) * cap * (1.0 - (item_size as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes; residuals near multiples of 10
    // are more reusable (items 10..80 often land on decade boundaries).
    let pr = post_residual as u32;
    let decade = pr % 10;
    let decade_bonus = match decade {
        0 => 18.0,
        1 | 9 => 9.0,
        2 | 8 => 5.0,
        _ => 0.0,
    };
    score -= decade_bonus;

    // Harmonic class via integer division thresholds: small post_residual = tight fit = good,
    // but too small is dead space unless a future small item can use it.
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 12.0;
    } else if pr > 80 {
        score += 20.0; // large leftover wastes a bin slot
    }

    // Coupling with next item: if the next item fits exactly or well into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr as f64).abs() < 1.0 {
            score -= 45.0; // next item fills this bin exactly
        } else if next_item_size <= pr {
            let fit_quality = ni / pr as f64;
            score -= 20.0 * fit_quality;
        }
        // Harmonic class of next_item_size vs post_residual modulo classes
        if pr % 10 != 0 && (next_item_size % 10) == pr % 10 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap + 30.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size <= 30 {
            score -= 15.0; // pairing large next item with fresh bin
        }
    }

    // Prefer bins with residual below mean (consolidate fullness).
    let res_frac = bin_residual as f64 / cap;
    score += 12.0 * (res_frac - mean_residual / cap).abs().signum() * (res_frac - mean_residual / cap);

    // Mild preference for fewer open bins.
    score += open_bins_count as f64 * 0.5;

    // Exact-fill reward on capacity fraction classes.
    if bin_capacity % pr.max(1) == 0 && pr > 0 && pr <= 50 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 stream, assume ~10).
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // unusable sliver
    } else if (post_residual as f64) < 20.0 {
        score += 20.0; // near-dead gap
    }

    // Reward tight fits: the smaller post_residual relative to item, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * (open_bins_count as f64).ln().max(0.0) + 20.0 * progress;
    } else {
        // Slight reward for using existing bins, stronger when many are open.
        score -= 5.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item could exactly fill the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0; // leaves room for the next item
    } else if next_item_size > 0 {
        score += 8.0; // next item cannot use this bin anyway
    }

    // Mild pull toward bins with residuals close to the mean (balance load).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; penalize large dead space
            let dead = post_residual as f64;
            score += 0.5 * dead;
            // extra penalty if dead space is unusable for typical small items
            if dead < 10.0 {
                score += 20.0;
            }
        }
    } else {
        // last item: prefer tightest fit
        score += 0.3 * post_residual as f64;
    }

    // Compare residual against mean residual across open bins
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - avg_fill);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // new bin guarantees fit
        }
    }

    // Early stream: be more conservative about tight fits (more items coming)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference to fill bins when many bins are open
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is too small OR too large relative to item sizes.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: post_residual that cannot fit typical future items is waste.
    // Typical item ~ bin_capacity * 0.35; unusable sliver threshold.
    let dead_threshold = bin_capacity as f64 * 0.1;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 12.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty for splurging on a good bin now.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 8.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // If next item won't fit here, small penalty proportional to leftover.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate logic: empty bin gets baseline cost, cheaper late in stream
    // or when current bins have large residuals (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let mut new_bin_cost = 20.0;
        // Early stream: opening bins is fine.
        new_bin_cost -= 10.0 * (1.0 - t);
        // If mean residual across open bins is small, current bins are tight; opening is attractive.
        new_bin_cost -= (mean_residual / bin_capacity as f64).min(1.0) * 8.0;
        // If only few bins can fit, opening new bin is more attractive.
        new_bin_cost -= 5.0 * (1.0 / fitting_bins_count.max(1) as f64);
        score += new_bin_cost;
    }

    // Global pressure: many open bins -> prefer filling existing ones (penalize new bins implicitly,
    // reward placing into bins below mean residual to balance).
    if bin_residual != bin_capacity {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
        // Prefer bins with residual close to (but >=) item size: tightness reward.
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 6.0 * tightness;
    }

    // Late-stream consolidation: as stream progresses, avoid leaving medium residuals.
    if t > 0.7 && post_residual > 0 {
        score += 5.0 * t * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear tightening of residual as the stream progresses:
    // early on, waste is cheap; later, small residuals are heavily penalized.
    let tight = 1.0 + 2.0 * progress * progress;
    score *= tight;

    // Smooth quadratic coupling of post_residual with mean residual:
    // penalize bins whose leftover deviates from the fleet mean (fragmentation).
    let dev = post - mean_residual;
    score += 0.05 * dev * dev;

    // Reward (subtract) when the next item fits smoothly into the post-residual,
    // with a smooth bell-shaped coupling.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_ratio = nxt / post.max(1.0);
            score -= 6.0 * (1.0 - fit_ratio) * fit_ratio * 4.0;
        } else {
            // smooth penalty when next item cannot fit the leftover
            let over = (nxt - post) / cap;
            score += 8.0 * over * over;
        }
    }

    // Last-chance bin: strongly favor using it (smoothly scaled by progress).
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // New empty bin candidate: penalize opening a new bin unless it is the
    // only option; penalty grows smoothly with number of open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    } else {
        // slight preference for fuller existing bins when many are open
        score -= 0.1 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit rewards (perfect fills are gold in bin packing)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Harmonic class logic: dead space is worse when its low-order class
    // (mod 10) is large, since small item sizes (1..=100) commonly leave
    // residuals in the same decade; a high mod-10 class means the leftover
    // is awkward for future small items.
    score += (post_residual % 10) as f64 * 0.6;

    // Integer-division threshold: residuals in [50, 100) can still host a
    // half-bin item; residuals below that are increasingly dead.
    let half_class = post_residual / 50; // 0, 1, or 2
    score -= half_class as f64 * 10.0;

    // Lookahead coupling (k=2): reward if the next item fits exactly or
    // well into the post residual; penalize if it cannot fit at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.25;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many
    // bins are already open (amortization) or mean residual is high
    // (existing bins have room to exploit).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5 + mean_residual * 0.05;
    }

    // Deviation from mean residual: prefer placements that keep the bin
    // population balanced, avoiding fragmentation.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Slight late-stream conservatism: as the stream progresses, avoid
    // leaving large residuals (less future to fix them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Reward if the lookahead item can exactly fill the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size > post_residual {
            // Dead space for the next item: penalize proportionally.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins tighter than average (good fills).
    score -= 0.25 * (mean_residual - bin_residual as f64);

    // New-bin candidate: default cost, reduced if this item would leave a bad gap elsewhere
    // or if the current bin is nearly empty (better to start fresh for large items).
    let mut new_bin_score = 70.0 + 0.3 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Fresh bin receiving a large item is fine; small item into fresh bin is wasteful.
        new_bin_score += 0.5 * (bin_capacity - item_size) as f64;
        score = score.min(new_bin_score.max(score));
        if item_size >= 50 && (bin_residual - item_size) < 10 {
            score -= 30.0;
        }
    } else {
        // If placing here creates an unusable gap and other bins fit, allow opening a new bin.
        if post_residual < 10 && fitting_bins_count > 1 {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is disproportionately bad)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 12.0 * fit_ratio;
    } else {
        score += 4.0 * (1.0 - fit_ratio);
    }

    // Aggressive 2-step lookahead: if next item exactly fills the post residual,
    // this placement is perfect — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to tightness
            let tight = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * tight;
        } else {
            // next item cannot use the leftover: penalize dead space growth
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64).min(1.0) * 15.0;
        }
    }

    // Prefer bins whose residual deviates from mean in a useful way:
    // a bin with residual much larger than mean is "wasted" — using it is good.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.08 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = (item_size as f64 / bin_capacity as f64) < 0.35;
        let crowded = open_bins_count as f64 > 2.0 + step_index as f64 / (total_items.max(1) as f64) * 8.0;
        if bad_fit && crowded && next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 6.0; // open new bin to preserve big residuals
        } else {
            score += 20.0; // otherwise strongly discourage new bins
        }
    }

    // Late in the stream, consolidate: prefer tighter residual targets
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term,
    // but add a superlinear penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Exact or near-exact fits get a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this bin
    // (creates a good chain); if post_residual is too small for the next item
    // but nonzero, penalize dead space that likely becomes unusable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
        }
        // Bonus if post_residual exactly matches next item (perfect pairing).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when the item fits poorly everywhere
    // else; make the empty bin attractive for large items but discourage it for
    // small items when open bins exist.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        // Large items fill a fresh bin well; small items should not open new bins.
        score -= 25.0 * load_frac;
        score += 18.0 * (1.0 - load_frac);
        // As the stream progresses, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Many open bins with slack: discourage opening yet another bin.
        score += 0.5 * open_bins_count as f64;
    }

    // Global state coupling: if the mean residual across open bins is large,
    // there is slack available; mildly penalize placements that leave this bin
    // with residual far from the mean (encourages balanced residual usage).
    let diff = post_residual as f64 - mean_residual;
    score += 0.05 * diff * diff;

    // Mild penalty for leaving large awkward residuals that common item sizes
    // (10..80) cannot exploit well: residual in (0, 10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (small post_residual); later, weight residual
    // waste more heavily to consolidate open bins.
    let progress_weight = 1.0 + 2.5 * progress * progress;
    let mut score = base * progress_weight;

    // Penalize residual that is too small to be useful (dead space), smoothly.
    let dead_threshold = 0.08 * cap;
    if pr < dead_threshold {
        let t = pr / dead_threshold;
        score += (1.0 - t) * (1.0 - t) * 6.0;
    }

    // Reward leaving room for the lookahead item (smooth polynomial fit term).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let exact = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= exact * exact * 4.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        score += (gap / cap) * (gap / cap) * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Slight preference for bins with residual below the mean (tighter packing),
    // smoothly coupled with the number of open bins.
    let diff = (mean_residual - pr) / cap;
    score += diff * diff * 2.0 - diff * 1.5;

    // Late-stream consolidation: discourage spreading across many open bins.
    score += (open_bins_count as f64) * progress * 0.3;

    // New-bin candidate: mildly penalize unless open bins look hopeless.
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: prefer residuals that are
    // "nice" multiples of small divisors (highly composite leftovers),
    // which are more likely to host future items exactly.
    let harmonic_bonus = |r: u32| -> f64 {
        if r == 0 {
            return 30.0; // perfect fit is ideal
        }
        let mut h = 0.0;
        for d in [1u32, 2, 4, 5, 10, 20, 25, 50] {
            if r % d == 0 {
                h += 2.0;
            }
        }
        h
    };

    // Reward bins whose post-residual is highly divisible; penalize prime-ish dead space.
    score -= harmonic_bonus(post_residual);

    // Penalize small unusable leftovers (dead space), scaled by how prime-like it is.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 - (post_residual as f64) * 0.5;
    }

    // Lookahead: if the next item exactly fills the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits here: good, especially if leftover after that is harmonic
            let post2 = post_residual - next_item_size;
            score -= 8.0 + harmonic_bonus(post2);
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to gap
            let gap = next_item_size - post_residual;
            if gap < 10 {
                score += (10 - gap) as f64 * 0.6;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when decent open bins exist,
    // unless the stream is early and we want capacity spread.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 18.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // If the item is large relative to capacity, opening fresh is less bad.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    } else {
        // Prefer tighter fits among open bins: reward small post_residual nonlinearly.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.15;
    }

    // Coupling with mean residual: avoid bins far from the mean (keeps diversity usable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold: post_residual classes mod 10
    let cls = post_residual % 10;
    match cls {
        0 => score -= 4.0,           // round leftover: very reusable
        5 => score -= 2.0,           // half-class: decent
        1 | 3 | 7 | 9 => score += 2.5, // prime-ish leftovers: less reusable
        _ => {}
    }

    // Late in the stream, consolidation matters more: penalize spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Any post_residual below the minimum item size (1) is impossible here,
    // but gaps that cannot fit a "typical" next item are dead space.
    let dead_threshold = 10.0_f64.min(next_item_size as f64);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 + (dead_threshold - post_residual as f64) * 2.0;
    }

    // Perfect fit reward: waste nothing.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 {
        // Penalize if post_residual is positive but too small for next item.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count.
        score += open_pressure;
        // Mild discount if mean residual across open bins is high (bins are loose),
        // making reuse attractive anyway; but if bins are tight, new bin ok.
        score -= (mean_residual - 20.0).max(0.0) * 0.5;
    } else {
        // Existing bin: reward reuse, scaled by how many bins are open.
        score -= open_pressure * 0.5;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Prefer bins whose residual is close to item (tight fit) over huge leftover bins.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect fit (2-step lookahead core).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0; // item chains perfectly with the next one
    } else if next_item_size > 0 && post_residual > next_item_size {
        // leftover after also fitting next item: prefer small leftovers
        score -= 120.0 - (post_residual - next_item_size) as f64 * 1.5;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize wasted residual
        score += (post_residual as f64).min(next_item_size as f64) * 0.6;
    }

    // Reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 40.0;

    // Penalize deviation from mean residual (avoid fragmenting outliers).
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.4;
    }

    // Late in the stream, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 80 {
        // usable residual is fine, slightly reward mid-range when many items remain
        score -= 6.0 * (1.0 - t) * (post_residual as f64 / 80.0);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 14.0 * (1.0 - slack / cap);
        } else {
            score += 4.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against global state: prefer bins with residual below mean (consolidate fullness).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        // Base penalty for opening a new bin.
        let mut new_bin_score = cap + 55.0 + 3.0 * open_f;
        // Early in stream, new bins are cheaper; late, avoid bin proliferation.
        new_bin_score += 25.0 * (1.0 - t);
        // If several bins fit, extra penalty for opening a new one.
        if fitting_bins_count > 0 {
            new_bin_score += 20.0 * (fitting_bins_count as f64);
        }
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            new_bin_score -= 12.0;
        }
        score = score.max(new_bin_score);
        score = new_bin_score;
    } else {
        // Mild penalty for spreading across many open bins.
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr * pr / cap; // quadratic dead-space penalty
    let interaction = poly * (0.5 + progress); // later in stream => punish residual more

    let mut score = pr + interaction;

    // Reward tight fits smoothly
    score -= 40.0 * fill * fill * (0.5 + progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space close to next item size (smooth bell)
    if next_item_size > 0 {
        let d = pr - next_item_size as f64;
        score -= 15.0 * (-(d * d) / 400.0).exp();
    }

    // Penalize bins already far below mean residual (fragmented bins)
    score += 0.1 * (mean_residual - pr).max(0.0);

    // Mild new-bin aversion that grows with open bins and progress
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worst when it's a small,
    // "unusable-looking" sliver. Classify post_residual into classes via
    // integer division thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class by which eighth of the capacity the leftover falls into.
        let class = (pr * 8.0 / cap).floor() as u32; // 0..7
        match class {
            0 => score += 25.0,  // tiny sliver (1..12): dead space, penalize
            1 => score += 10.0,  // 13..24: still awkward
            2 => score += 3.0,   // 25..36: moderate
            3 => score -= 2.0,   // 37..49: healthy
            4 => score -= 4.0,
            5 => score -= 5.0,
            6 => score -= 6.0,
            _ => score -= 4.0,   // nearly empty bin: fine but not special
        }
    }

    // Modulo harmonic: leftover spaces that are multiples of common item
    // sizes (10, 20, 25, 50) are reusable; others less so.
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if reusable && post_residual > 0 {
        score -= 6.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 8.0; // sub-10 sliver is almost always dead space
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (creates a perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover after next placement matters.
            let post2 = post_residual - next_item_size;
            if post2 == 0 {
                score -= 18.0;
            } else if post2 < 10 {
                score += 6.0; // would create a sliver
            } else {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; prefer bins that will be closed out
            // cleanly. Small post_residual is fine then.
            if post_residual >= next_item_size - 5 {
                score += 2.0; // near-miss waste risk
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual <= 10 {
            score -= 8.0; // even a sliver-producing last fit beats a new bin
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual
    // (== capacity). Encourage new bins only when no open bin fits well,
    // i.e., when mean residual is low relative to item size.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        if pressure > 1.5 || open_bins_count == 0 {
            score -= 20.0; // open a new bin when open bins are too full
        } else {
            score += 15.0; // prefer existing bins otherwise
        }
    }

    // Slight preference to fill fuller bins first (best-fit baseline).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Late-stream tiebreak: consolidate as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    } else {
        // Larger usable leftovers are mildly rewarded.
        score -= 6.0;
    }

    // Reward exact or near-exact fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing
    // a bad fit unless the fit is actually tight.
    if fitting_bins_count == 1 {
        if post_residual <= 15 {
            score -= 40.0; // tight fit, take it
        } else {
            score += 30.0; // wasteful last-chance fit, discourage
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidation
    // (penalize spreading into bins with large residuals).
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with residual well above the mean
    // are "slack" bins; filling them is good, but leaving tiny gaps is bad.
    let slack = bin_residual as f64 - mean_residual;
    score += 0.15 * slack;

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 35.0; // next item will nearly close this bin
        } else {
            score -= 5.0; // next item still fits reasonably
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // leftover likely becomes dead space
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // best alternative would create severe dead space.
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 80.0;
        }
        // Base attractiveness of a fresh bin: moderate.
        score -= 20.0;
        // Early in the stream, opening bins is cheap; later, prefer reuse.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-gap / 20.0).exp(); // strong reward for tight 2-step fit
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: next item exactly fills this bin
        }
        // Penalize leaving residual that the next item cannot use at all
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Penalize dead space below minimum item size (unusable waste)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item is large and current fit is loose, opening fresh is fine
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 * 1.5 {
            score -= 30.0;
        }
    }

    // Slight preference to fill fuller bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let tight_fit = (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= 40.0 * tight_fit;

    // Penalize leaving residuals that no plausible future item can use well
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead sliver
    }
    if post_residual >= 10 && post_residual <= 30 {
        score -= 12.0; // usable gap for mid-size items
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0; // chain placement possible
            let leftover = post_residual - next_item_size;
            score += leftover as f64 * 0.15;
        } else {
            score += 6.0; // breaks the chain
        }
    }

    // Penalize opening a new bin when open bins can fit the item,
    // scaled by how "wasteful" the new-bin residual would be
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + waste * 0.6;
        // But if existing fits are loose (high mean residual vs item), new bin less bad
        let loose = mean_residual - item_size as f64;
        if loose > 20.0 {
            score -= (loose - 20.0) * 0.8;
        }
        // Early in stream: prefer consolidating; late: allow spreading
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 25.0;
    }

    // Prefer filling bins that are already mostly full (small residual)
    score += (bin_residual as f64) * 0.25;

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    // Nudge toward bins below mean residual (balance the pool)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste created, with mild non-linear shrinkage of large residuals
    let mut score = post * (1.0 - 0.35 * (post / cap) * (1.0 - post / cap));

    // Reward tight fits: quadratic coupling between fill fraction and progress
    let fill = item / cap;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Penalize residuals that no plausible future item can use well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            // dead space relative to lookahead: smooth penalty
            score += 3.0 * ((nxt - post) / cap).powf(1.5);
        } else {
            // lookahead fits perfectly -> strong reward
            let slack_after = post - nxt;
            score -= 6.0 * (1.0 - slack_after / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize early, allow late in stream when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score += 10.0 - 8.0 * progress + 6.0 * fragmentation;
    } else {
        // Prefer bins below mean residual (fill emptier bins first, keep tight ones)
        score += 1.5 * (post - mean_residual) / cap;
    }

    // Mild pressure to consolidate as stream progresses
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let q = pr / (bin_capacity / 10).max(1); // decile class of leftover space
    let rem = pr % (bin_capacity / 10).max(1);

    // Reward tight fits: post_residual in low deciles gets strong discount.
    score -= (10 - q.min(10)) as f64 * 4.0;

    // Exact power-of-two-style divisibility: residuals divisible by common item
    // sizes (e.g. 10, 20, 25, 50) pair well with future items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 || pr % 50 == 0 { score -= 5.0; }
    } else {
        score -= 30.0; // perfect closure, best possible outcome
    }

    // Dead-space penalty: leftover that no plausible item (>=1) can be judged on;
    // penalize residuals that are too small to be useful but nonzero.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= 8.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; mild penalty scaled by wasted fraction
            score += 5.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits
    // well. Penalize new bin by the item's footprint (wasted capacity of a fresh bin)
    // plus a mild congestion term when many bins are already open.
    if bin_residual == bin_capacity {
        score = item_size as f64 + 10.0 + 2.0 * (open_bins_count as f64).sqrt();
        // If mean residual across open bins is small (open bins are nearly full),
        // opening fresh is more acceptable.
        score -= mean_residual.min(cap) * 0.3;
        // Late in the stream, prefer reusing bins slightly more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Tie-break: prefer bins with residual close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    // Small harmonic jitter on remainder class to break ties deterministically.
    score += rem as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps below min item size are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // small but potentially usable gap: mild penalty
        score += 12.0;
    }

    // Reward very tight fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual was already fragmented (high mean residual => loose packing)
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Open-bin pressure: with many open bins, discourage opening new ones implicitly
    // by favoring existing bins; penalize selection proportional to open count on new bins
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well the next item fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // Penalize residuals that are just slightly too small for next item (dead space).
            let waste = (next_item_size - post_residual) as f64;
            if waste < 20.0 {
                score += 0.8 * (20.0 - waste);
            }
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose remaining space stays near the mean (balanced packing),
    // penalize making a bin much smaller than the rest.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin, unless current residuals are all too small
    // (i.e., mean residual is small relative to item size) — then allow it.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 35.0
            + 0.5 * open_bins_count as f64
            + (1.0 - step_index as f64 / total_items.max(1) as f64) * 20.0;
        let desperation = if item_size as f64 > mean_residual { 60.0 } else { 0.0 };
        score += new_bin_penalty - desperation;
    }

    // Slight preference for filling fuller bins first.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (-tight * 8.0).exp();

    // Penalize dead space that no plausible item can fill (items >= 1, but weight by lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 25.0; // perfect lookahead match
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins with large mean residual: prefer filling existing bins, avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 20.0 + 15.0 * open_bins_count as f64 + 30.0 * progress;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing capacity exists; opening new bin is wasteful
        }
    } else {
        // Slight preference for bins with residual near mean (balanced usage).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
        // Prefer bins with less residual (fuller bins first, best-fit flavor).
        score += 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Strongly reward tight fits: quadratic in normalized fill
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill;

    // Penalize large dead space quadratically
    score += 0.02 * pr * pr / cap;

    // New-bin candidate: penalize opening a bin when open bins exist that fit
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 25.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
    }

    // Last-chance bin: reward heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack_fit = 1.0 - (pr - ns) / cap;
            score -= 6.0 * slack_fit * slack_fit;
        } else {
            score += 3.0;
        }
    }

    // Stream-progress coupling: early on, prefer balanced residuals (near mean_residual);
    // later, prefer filling bins aggressively.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * (1.0 - progress) * dev * dev;
    score -= 10.0 * progress * fill;

    // Mild pressure against bin sprawl
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / cap;
    score -= 60.0 * (1.0 - fit_ratio).powi(3);

    // Harmonic class of post_residual: dead space if nothing next fits.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward chaining.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_waste / cap);
        } else {
            // Dead space: penalize modulo-style unusable remainder.
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 + 40.0 * (gap / cap);
        }
    }

    // Integer-division threshold: residuals in [0..10] are near-perfect.
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual > 50 {
        // Large leftover: only fine if bin was nearly empty anyway.
        score += 10.0 * (post_residual as f64 - 50.0) / 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New empty bin candidate: penalize so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 70.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // don't open early when a bigger item follows
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    // Stream progression: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Mid-range gaps that few future items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones; penalize the new-bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    } else {
        score -= pressure.min(10.0);
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave the residual even tighter-wasted, mild penalty.
    if next_item_size > 0 && next_item_size > bin_residual {
        score += 3.0;
    }

    // Prefer bins tighter than the mean residual (better fills).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on leftover space (tight packing).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            score -= 45.0; // perfect chain
        } else if post > next {
            // reward leftover room matching next item, scaled by tightness
            score -= 25.0 * (1.0 - (post - next) / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space proportional to gap
            score += 0.8 * (next - post);
        }
    }

    // Relative-to-mean-residual coupling: bins with residual near mean are neutral;
    // placing into a bin far above mean residual wastes its space.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.25 * (post_f - mean_residual).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // allow opening when few bins are open or item is large relative to capacity
        if open_bins_count == 0 || (item_size as f64) > 0.8 * bin_capacity as f64 {
            score -= 25.0;
        }
        // lookahead: if next item is small, new bin is fine
        if next_item_size > 0 && (next_item_size as f64) < 0.3 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Early in stream: slightly prefer opening bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Penalize dead space that is too small to likely fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins where the next item also fits (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Extra reward if next item fills bin nearly exactly.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize unless this bin becomes perfect.
        if post_residual > 0 {
            score += 5.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when current residual is awkward.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = if item_size > bin_capacity { 0.0 } else {
            let r = bin_residual % (item_size.max(1));
            if r < 10 { 1.0 } else { 0.0 }
        };
        // Penalize opening new bins generally, less so early or when open bins are full-ish.
        score += 60.0 - 20.0 * progress;
        if awkward > 0.0 {
            score -= 40.0;
        }
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 0 {
            score -= 25.0;
        }
    } else {
        // Prefer bins whose residual is above average (use slack where it exists).
        if (bin_residual as f64) > mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty for leaving residual in the awkward 10..20 zone.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: quadratic waste penalty (non-linear coupling of post_residual with itself)
    let mut score = pr * (1.0 + pr / cap);

    // Coupling with mean residual: bins deviating from the mean residual state
    // are penalized/rewarded smoothly via a normalized cubic interaction.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * dev.abs().min(2.0).signum() * dev.abs();

    // Stream-progress coupling: as the stream advances, waste tolerance shrinks
    // quadratically (tight packing becomes more valuable late).
    let tightness = 1.0 + 3.0 * progress * progress;
    score *= tightness;

    // Lookahead: reward leaving a residual that can host the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // gently penalize residuals that block the next item
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately expensive, cheaper only late in stream
    // when spreading across bins can pay off (smooth logistic in progress).
    if bin_residual == bin_capacity {
        let logistic = 1.0 / (1.0 + (-8.0 * (progress - 0.6)).exp());
        score = cap * (1.5 - 0.5 * logistic) + pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills are perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modular harmonic classes: residuals divisible by common small sizes
    // (10, 20, 25, 50) are more reusable later.
    let r = post_residual;
    if r % 10 == 0 { score -= 12.0; }
    if r % 20 == 0 { score -= 6.0; }
    if r % 25 == 0 { score -= 6.0; }
    if r % 50 == 0 { score -= 8.0; }

    // Penalize "awkward" residuals: 1..9 dead space is nearly unusable.
    if r > 0 && r < 10 {
        score += 25.0;
    }
    // Mid-range dead zones (11..14, 16..19, 21..24) are less reusable.
    if (11..15).contains(&r) { score += 8.0; }
    if (16..20).contains(&r) { score += 4.0; }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if next_item_size <= r {
            score -= (r - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot fit here; slight penalty proportional to waste.
            score += 3.0;
        }
        // Harmonic match: next item is a divisor-friendly chunk of residual.
        if r > 0 && r % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so tight fits in open bins win.
        score += 15.0;
        // If many bins already open, opening yet another is worse.
        score += open_bins_count as f64 * 2.0;
        // But if the item is huge relative to capacity and mean residual is small,
        // a fresh bin may be reasonable.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.8 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // Late in the stream, prefer reusing open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 10.0;
        }
    }

    // Tightness reward: smaller post_residual fraction of capacity is better.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Slight preference for bins with below-mean residual (denser bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..=15)
    // are hard to fill later, so penalize them heavily.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 + (15 - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space penalty scales with how many bins are already open:
    // with many open bins, wasting space in one of them is cheap to avoid.
    score += open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.5;

    // Lookahead: if the next item would fit into the post residual,
    // reward this placement (keeps future options alive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Mild pressure to consolidate into existing bins rather than open new ones.
    score += open_bins_count as f64 * 0.5;

    // Early in the stream, be slightly more willing to spread out;
    // late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: the next item can fit here too -> strong reward,
            // scaled by how snugly the next item nests into the leftover.
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 + 0.25 * next_item_size as f64 - 0.05 * snug;
        } else if post_residual > 0 {
            // Dead space: next item cannot use the remainder -> penalize
            // proportionally to how much of the next item is wasted space.
            let waste = (next_item_size - post_residual).min(next_item_size) as f64;
            score += 0.15 * waste;
        }
    } else {
        // Last item: prefer the emptiest fitting bin to close it out.
        score -= 8.0;
    }

    // --- Tight fit reward: small post_residual is excellent ---
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    } else if post_residual < 10 {
        score -= 10.0; // nearly perfect
    } else if post_residual > 60 {
        // Large leftover after placing a small item: likely wasteful split.
        score += 0.10 * (post_residual as f64 - 60.0);
    }

    // --- Relative to mean residual of open bins ---
    // Favor bins that are already more filled than average (smaller residual).
    score += 0.20 * (mean_residual - bin_residual as f64).max(-100.0);

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.10 * item_size as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early (spread risk) but costly late when
        // many bins are open; also discouraged if an open bin fits decently.
        let openness = open_bins_count as f64;
        score += 6.0 + 1.5 * openness * (0.3 + 0.7 * progress);
        // But if the current item is large and would leave a big hole in any
        // open bin, a fresh bin is attractive: reduce the penalty.
        if item_size >= 70 {
            score -= 10.0;
        }
        // Lookahead: a fresh bin always accommodates the next item.
        if next_item_size > 0 {
            score -= 4.0;
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    score += 0.03 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect-fit lookahead bonus: if the next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits inside this bin's leftover: mild bonus scaled by tightness
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: slight penalty proportional to overshoot
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Tightness reward: reward small post_residual relative to capacity.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Penalize creating dead space that few future items could use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny slivers are effectively full bins: good
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if poor_fit || fitting_bins_count == 0 {
            score -= 20.0; // go ahead and open a new bin for a big item
        } else {
            score += 45.0 + 10.0 * open_bins_count as f64; // discourage wasting fresh bins
        }
    }

    // Global pressure: many open bins with low mean residual -> consolidate into emptier bins.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 10.0 * pressure * (open_bins_count as f64).ln();
    }

    // Early vs late phase: early on, be picky (favor tight fits); late, just pack.
    score *= 1.0 + 0.3 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // waste is penalized more heavily as the stream advances.
    let x = pr / cap; // normalized post residual in [0,1]
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 30.0 * poly;

    // Reward near-perfect fits with a smooth quartic term
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 8.0 * fit_quality * (0.5 + 0.5 * progress);
    }

    // Penalize opening new bins when many bins are open and mean residual is high
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual);
        score += 6.0 + 0.5 * crowding * (1.0 - progress);
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.05 * (mean_residual - pr).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic-class logic: classify post_residual into residue classes modulo
    // small divisors, rewarding "harmonically useful" dead space that future
    // items (sizes 1..=100) can still fill exactly or nearly.

    // Base: prefer tight fits.
    score = post_residual as f64 * 1.0;

    // Reward near-perfect packing: post_residual in low harmonic classes.
    if post_residual <= 10 {
        score -= 30.0; // excellent fill
    } else if post_residual <= 25 {
        score -= 12.0;
    }

    // Modulo-10 harmonics: dead space that is a multiple of 10 is more likely
    // reusable by typical item sizes.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 8.0;
    } else {
        score += m10 as f64 * 0.8; // penalize off-class residue
    }

    // Modulo-5 secondary class.
    let m5 = post_residual % 5;
    if m5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 15.0 - gap as f64 * 0.25; // tighter lookahead fit is better
        } else {
            // Next item cannot use this bin's residue anyway; slight penalty
            // for leaving large stranded space.
            score += (post_residual as f64 - cap * 0.5).max(0.0) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit's score.
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 10.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // opening fresh space for a big follower is fine
        }
    }

    // Progress-aware dead-space penalty: late in the stream, stranded capacity
    // is less likely to be recovered.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / cap) * progress * 10.0;

    // Mean-residual coupling: if this bin is far below average residual,
    // filling it keeps many flexible bins open.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Small tie-breaker toward fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are waste.
    // Penalize unusable-tiny gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual close to 0) more than raw value implies.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Reward bins whose residual exactly accommodates the item (perfect fit).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post-residual, this placement is doubly good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fills the bin completely after this placement.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }
    // Penalize leaving a gap the next item *almost* fits into (near-miss dead space).
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate (empty bin): make it attractive only when current fit is bad
    // or no good alternative exists; penalize it when the fit here is decent.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 30.0;
        // But if this bin's post_residual would be a very poor fit, opening new is fine.
        if post_residual > 0 && post_residual < 15 {
            score -= 45.0;
        }
        // If many bins are open and mean residual is large, opening new is wasteful.
        if mean_residual > 30.0 {
            score += 15.0;
        }
        // Early in the stream, be more willing to open bins (build diversity of residuals).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    score += 0.3 * ((bin_residual - item_size) as f64).abs().min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits: minimize post residual non-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score += (post_residual as f64).powf(1.35) * 0.05;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0; // perfect chaining: this bin then next item perfectly
        } else {
            score -= 20.0 - (slack as f64).min(30.0) * 0.2;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportional to mismatch
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Compare against mean residual: prefer bins that are tighter than average
    // (packing large items into fuller bins keeps loose bins flexible).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity (little waste risk) and few bins fit.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.6 || (fitting_bins_count == 0 && next_item_size > 0 && next_item_size > post_residual) {
            score -= 30.0 * fill_ratio;
        } else {
            score += 40.0; // discourage opening new bins for small items
        }
    }

    // Late in the stream, prefer closing bins tightly (less fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Penalize leaving dead space that no realistic item (>=1) can use well:
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal, superlinear penalty.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // Fractional fill of the bin by this item: fuller placement is better.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 15.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Mild reward proportional to how well the next item fills leftover space.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= next_fill * 8.0;
        } else {
            // Post residual too small for next item: penalize dead space unless tiny.
            if post_residual > 0 {
                let waste = post_residual as f64 / bin_capacity as f64;
                score += waste * 12.0;
            }
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 40.0 - 15.0 * progress;
        // If few bins can fit the item, opening fresh is more acceptable.
        if fitting_bins_count <= 1 {
            open_cost -= 20.0;
        }
        // If open bins have large mean residual, using them is preferable.
        open_cost += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
        score += open_cost;
    }

    // Prefer consolidating into bins with below-average residual (tighter bins).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Small penalty on many open bins to discourage fragmentation.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: normalized post-residual, non-linearly amplified.
    let x = pr / cap;
    let mut score = 6.0 * x * x + 2.0 * x;

    // Smooth progress coupling: later in stream, dead space hurts more.
    score += (1.0 + 3.0 * progress) * x * x;

    // Interaction: post_residual vs mean residual — penalize residuals far from mean.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large relative to capacity
    // or the stream is early (amortization over remaining items).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let amortize = 1.0 - progress;
        score += 3.5 - 4.0 * size_frac * size_frac - 2.0 * amortize * size_frac;
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic overlap term).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (pr - next_item_size as f64) / cap;
        score -= 2.5 * (1.0 - gap * gap).max(0.0) * nx;
    }

    // Mild penalty for many open bins relative to progress.
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo common item-size
    // divisors. A residual that is an exact multiple of small sizes (10, 20, 25)
    // is "harmonic" and likely reusable; non-harmonic dead space is penalized.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 40, 50] {
            if pr % d == 0 {
                harmony += 8.0;
            } else {
                let r = pr % d;
                // distance to nearest multiple of d: small distance = flexible
                let dist = r.min(d - r) as f64;
                harmony += 4.0 * (1.0 - dist / (d as f64 / 2.0));
            }
        }
        score -= harmony;

        // Integer-division thresholds: residuals that can hold a "class" chunk
        let class_chunks = pr / 10;
        score -= 0.5 * class_chunks as f64;
    } else {
        // Perfect fit is best possible
        score -= 100.0;
    }

    // Dead-space penalty: residual below the minimum item size is pure waste,
    // unless it is exactly zero.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward;
    // if it nearly fits, mild penalty for blocking a near-miss.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0;
            // extra reward when next item exactly fills the harmonic remainder
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            if gap <= 10.0 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: an empty bin should only win when all open fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins are already
        // open (consolidation pressure) or late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 45.0;
        new_bin_cost -= 10.0 * (open_bins_count.min(20) as f64 / 20.0);
        new_bin_cost -= 10.0 * progress;
        // If current fit wastes a lot (large post residual relative to capacity),
        // opening a fresh bin becomes more attractive.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        new_bin_cost -= 30.0 * waste_frac;
        score += new_bin_cost;
    }

    // Mild preference for tighter bins overall (tight-fit bias).
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (0 < post_residual < 10)
    // are the worst outcome; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: post_residual small relative to item size.
    score -= (item_size as f64) * 0.5;

    // Penalize wasting a large residual on a small item (bad fill ratio).
    score += 0.4 * (bin_residual as f64 - item_size as f64);

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // over opening new ones (new-bin candidate has max residual).
    score += 0.3 * (open_bins_count as f64);

    // New-bin candidate penalty: only open a new bin if no decent fit exists.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If several bins fit, opening a new bin is rarely justified.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // Last-chance bin: strongly prefer using it rather than opening a new bin.
        if fitting_bins_count == 1 {
            score += 15.0;
        }
    }

    // Last-chance bonus for an existing bin that is the only one fitting.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use.
        score += 10.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., leaving above-average bins untouched) is slightly penalized.
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // Mild stream-progression urgency: later in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: good chaining, penalize leftover after that
            score -= 100.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit: penalize leftover dead space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when reasonable fits exist
    if bin_residual == bin_capacity {
        score += 50.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 120.0;
        }
    }

    // Late-stream bias: consolidate more aggressively toward the end
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize wasted dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    }
    if post_residual > 50 {
        score += 4.0; // large leftover is risky
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward if the pair nearly fills the bin.
            if post_residual - next_item_size <= 10 {
                score -= 5.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item fits this bin only with the current one gone; slight penalty
            // for consuming the space it would need.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is generally expensive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        let mean_fit = if mean_residual >= item_size as f64 { 1.0 } else { 0.0 };
        // Base cost of a new bin, reduced late in the stream when carrying
        // many open bins with large residuals is wasteful.
        let mut new_bin_cost = 18.0
            - 6.0 * progress
            - 0.5 * (open_pressure - 1.0).max(0.0);
        // If the item fits poorly nowhere else (no open bin has room),
        // opening a new bin is fine; if other bins fit, make it costly.
        if fitting_bins_count > 0 {
            new_bin_cost += 10.0;
            // If mean residual across open bins is large, we should use them instead.
            new_bin_cost += 0.15 * mean_residual.max(0.0) * mean_fit;
        }
        score += new_bin_cost.max(2.0);
    }

    // Mild preference for keeping the number of open bins low early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score += 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    // Small time-dependent tie-breaker to diversify exploration.
    score += 0.05 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Base fit quality: prefer tight fits (small post_residual) with smooth non-linear shaping.
    let fit_frac = post / cap; // 0 = perfect fit, 1 = empty bin
    score += 12.0 * fit_frac * fit_frac * (1.0 + prog);

    // Penalize creating dead space that no plausible future item can use.
    // Small residuals (< ~10) are near-perfect; moderate residuals waste capacity.
    let dead = (post - (post.min(10.0))).max(0.0);
    score += 0.35 * dead * (1.0 + 0.5 * (1.0 - prog));

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            // Reward proportional to how snugly the next item fits afterwards.
            score -= 6.0 * (1.0 - slack / cap) * (1.0 - 0.5 * prog);
        } else {
            // Next item won't fit: mild penalty, stronger early when bins are precious.
            score += 3.0 * (1.0 - prog);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + prog);
    }

    // New-bin candidate (empty bin): penalize so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let pressure = if open > 0.0 { mean_residual / cap } else { 0.0 };
        // Opening is more acceptable when open bins have large residuals (poor reuse value)
        // and later in the stream; smooth logistic-like coupling.
        let open_bonus = 1.0 / (1.0 + (-8.0 * (pressure - 0.35)).exp());
        score += 30.0 * (1.0 - open_bonus) + 10.0 * (1.0 - prog) - 2.0 * open;
    }

    // Mild reward for consolidating into bins that are already quite full.
    let used_frac = (bin_residual as f64) / cap;
    score -= 4.0 * used_frac * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
