    // unless it's a brand-new bin candidate.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    } else {
        // New-bin candidate: mild penalty so it's chosen only when
        // no open bin gives a good fit; grows with open bin count.
        score += 8.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals too small for any future item are wasted.
    // Items are 1..100, so residual < 1 is impossible, but tiny residuals (< min plausible item)
    // are effectively dead. Penalize sharply when post_residual is a small unusable gap.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    }
    // Soft penalty for residuals below a typical small-item size band
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual) non-linearly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins when alternatives exist
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);

    // Prefer bins whose residual is close to the item (minimize fragmentation)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    // Lookahead coupling: if the next item fits into the resulting residual, reward it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // residual blocks the lookahead item
        }
    }

    // New-bin candidate logic: an empty bin has high raw post_residual; make it attractive
    // only when no good fit exists (fitting_bins_count small) or mean residual is very low.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let scarcity = (1.0 - (mean_residual / bin_capacity as f64)).clamp(0.0, 1.0);
        score -= 20.0 * pressure + 15.0 * scarcity * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: big discount
        if diff == 0.0 {
            score -= 50.0 + 20.0 * (1.0 - progress);
        } else if next_item_size <= post_residual {
            // next item could still fit here later: mild discount scaled by closeness
            score -= 10.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item cannot fit in post_residual: penalize dead space
            score += 5.0 + 0.3 * diff;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Reward tight fits relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, offset slightly when many bins open and residuals fragmented
        score += 40.0;
        score -= 2.0 * open_bins_count as f64 * (1.0 - progress);
        if post_residual as f64 > mean_residual + 10.0 {
            score += 10.0;
        }
    }

    // Prefer bins with small residual overall (best-fit flavor)
    score += 0.1 * (bin_residual as f64 - post_residual as f64) * 0.0;

    // Mild penalty for leaving residuals in the awkward 1..10 dead zone
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: strongly prefer tight fits.
    score += (post_residual as f64).powi(2) * 0.02;

    // Reward bins whose residual closely matches the item.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0;

    // Lookahead: penalize leaving a residual that neither fits nor
    // synergizes with the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: bonus, scaled by how snugly.
            score -= 6.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Residual too small for next item: dead-space penalty grows
            // as the leftover shrinks below the next item's size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.05;
        }
        // Perfect chain: residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize creating small unusable residuals (below typical item floor).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Global pressure: when many bins are open with slack, prefer
    // consolidating into bins with above-average residual usage.
    let usage_gap = (mean_residual - post_residual as f64) * 0.03;
    score += usage_gap;

    // Time horizon: early in the stream, be conservative (favor tight fits
    // more); late in the stream, prioritize closing bins out (favor small
    // post-residual even harder).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= tightness * 4.0 * (1.0 - progress);
    score += (post_residual as f64) * 0.01 * progress;

    // New-bin candidate: only attractive when no open bin fits well
    // (high post_residual everywhere) or many bins already open.
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin costs roughly the wasted residual avoided.
        let mut new_bin_score = (bin_capacity as f64) * 0.55 - (item_size as f64);
        // If existing bins leave large residuals, opening a new bin is fine.
        new_bin_score -= mean_residual * 0.05;
        // Few open bins -> prefer filling them; many -> new bin is cheaper.
        new_bin_score -= (open_bins_count as f64) * 0.4;
        // Last-chance pressure: never open a new bin if this is the only fit.
        if fitting_bins_count <= 1 {
            new_bin_score += 40.0;
        }
        // Late in stream, avoid spreading out.
        new_bin_score += progress * 10.0;
        score = score.min(score.max(new_bin_score));
        // Replace score with new-bin score directly (candidate comparison).
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills mildly; late, reward tight fills strongly.
    let norm_fit = 1.0 - (pr / cap); // 1 = perfect fit, 0 = empty
    let poly = norm_fit * norm_fit * (1.0 + 2.0 * progress) - 0.5 * norm_fit * progress;
    score -= 30.0 * poly;

    // Penalize residuals that cannot fit the lookahead item (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0) / cap;
        score += 20.0 * waste * waste;
        // Reward leaving room exactly for the next item.
        let gap = (pr - nx).abs() / cap;
        score -= 10.0 * (1.0 - gap) * norm_fit;
    } else {
        // Last item: reward perfect fill strongly.
        score -= 40.0 * norm_fit * norm_fit;
    }

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() / cap;

    // New-bin candidate: make empty bin attractive only when no tight fit exists.
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * (1.0 - progress) - 10.0 * norm_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is a "nice"
    // fraction of capacity (0, cap/4, cap/3, cap/2) are valuable.
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;
    let harmonic_bonus = if post_residual == 0 {
        60.0
    } else if post_residual == quarter {
        40.0
    } else if post_residual == third {
        35.0
    } else if post_residual == half {
        45.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits, penalize by how much slack would remain
            score += (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item will not fit here: leftover becomes dead space
            score += 15.0;
        }
    } else {
        // last item: prefer zero residual strongly
        score -= (post_residual == 0) as u32 as f64 * 50.0;
    }

    // Integer-division class of item_size relative to capacity.
    let item_class = item_size / (bin_capacity / 10);
    score -= item_class as f64 * 2.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the fit is perfect or the current bins are crowded.
    if bin_residual == bin_capacity {
        let perfect = item_size == bin_capacity;
        let crowded = mean_residual < item_size as f64 * 0.5 && open_bins_count > 2;
        if perfect || crowded {
            score -= 30.0;
        } else {
            score += 20.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // Mild late-stream consolidation: as the stream progresses, prefer
    // filling existing bins over spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Modulo-16 harmonic class of post_residual: small leftovers in
    // "wasteful" classes get penalized.
    let class = post_residual % 16;
    if class != 0 && post_residual > 0 {
        score += class as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item (>=1, but practically small gaps under
    // ~10 units are near-useless) get an extra penalty.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead) / 10.0; // small unusable gap => strong penalty
    }

    // Reward tight fits (post_residual near zero relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item cannot use this residual: mild penalty for large leftover
        score += 0.05 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the
    // current fit is poor. Give it a baseline cost plus pressure term.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.6 * open_bins_count as f64 + 0.3 * mean_residual;
        // allow new bin when few bins open early in stream
        if open_bins_count <= 2 && step_index < total_items / 4 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is "drier" than average -> prefer consuming it.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fill bin.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64 * 0.5)).max(-1.0);
        // Perfect pair-fill bonus
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        }
        // Penalize leaving residual slightly larger than next item (wasted wedge)
        if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score += 15.0;
        }
        // Reward leaving residual smaller than next item (dead space consumed)
        if next_item_size > post_residual {
            score -= 5.0;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 30.0;
    }

    // Compare post_residual against mean residual of open bins:
    // placing in a bin whose residual is far below mean keeps big holes concentrated.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Progress-scaled tightness pressure: later in stream, demand tighter fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Mild penalty when many bins are open: encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Discard new-bin candidate unless current fit is very poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            score -= 70.0; // rare: open new bin for a perfect 2-step match
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty beyond a threshold
    let tight_threshold = 10.0;
    if (post_residual as f64) > tight_threshold {
        score += (post_residual as f64 - tight_threshold) * (post_residual as f64 - tight_threshold) * 0.05;
    } else {
        score -= 20.0; // near-perfect fit bonus
    }

    // Penalize bins that cannot fit the next item (dead space for lookahead)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            score -= 5.0; // lookahead can chain into this bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many open bins already have slack
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        score += 15.0 + openness * 1.5 - progress * 5.0;
        // New bin is fine if mean residual is very low (all bins nearly full)
        if mean_residual < 8.0 {
            score -= 25.0;
        }
    } else {
        // Slight preference for bins with residual close to mean (balanced packing)
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;
    }

    // Prefer larger residual bins early, tighter bins later (horizon effect)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 3.0
           - (bin_residual as f64 / bin_capacity as f64) * progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Later in the stream, larger residuals are penalized more (dead space matters more).
    let pr_norm = pr / cap;
    let time_w = 0.5 + 2.0 * progress * progress;
    score += time_w * pr_norm * pr_norm * cap * 0.3;

    // Reward tight fits: quadratic bonus when post_residual is small.
    let tight = 1.0 - pr_norm;
    score -= 3.0 * tight * tight * tight * cap * 0.1;

    // Penalize residuals that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * gap * cap;
        } else {
            // Reward leaving room for the next item, smoothly decaying.
            let room = (pr - nx) / cap;
            score -= 2.0 * (1.0 - room.min(1.0)) * (1.0 - room.min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Slight preference for bins with residuals below mean (consolidate space).
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // Mild penalty for opening a new bin when many bins are open and progress is low.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes mod 10.
    let pr = post_residual;
    let class = (pr % 10) as f64;

    // Reward post residuals that are "dead" but tiny (good tight fit).
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 10.0 - class * 0.3;
    }

    // Penalize residuals in awkward harmonic classes: hard to fill later.
    // Residuals like 1..9 (too small for min item 1..100 unknown) — treat small
    // but nonzero residuals as dead space with a nonlinear penalty.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5; // small dead space penalty
    }

    // Fractional capacity coupling: how much of the bin is consumed.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 8.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportionally, but penalize leftover
            // after the hypothetical placement (harmonic class of that).
            let pr2 = pr - next_item_size;
            score -= 20.0 - (pr2 % 10) as f64 * 0.4;
            if pr2 == 0 { score -= 15.0; }
        } else {
            // next item won't fit here: mild penalty for blocking lookahead
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins would leave big ugly residuals.
        // Baseline: slightly worse than a decent fit, better than a bad one.
        score = cap - (item_size as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open new bin
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        // If many open bins with large mean residual, discourage new bin.
        score += open_bins_count as f64 * 0.5 + mean_residual * 0.05;
    }

    // Small tie-break noise-free coupling with open bin count: spread load.
    score += (open_bins_count as f64).ln() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (below the minimum item size) are pure waste — penalize quadratically.
    let dead = (post_residual as f64 - 1.0).max(0.0);
    if post_residual < 10 {
        score += dead * dead * 2.5;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 15.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual cannot host the next item — mild penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // residuals are fragmented or the item is large with poor fits elsewhere.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 45.0
            + open_bins_count as f64 * 0.4
            - item_size as f64 * 0.15
            + fragmentation * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host next item well
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading items thin.
    score += open_bins_count as f64 * 0.15;

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain a perfect follow-up placement
        } else if next_item_size < post_residual {
            let rem = post_residual - next_item_size;
            score -= 25.0 * (1.0 - rem as f64 / bin_capacity as f64); // good chain, tighter is better
        } else {
            // next item won't fit here: penalize leaving a gap slightly larger than next item
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 10.0 {
                score += 15.0 + (10.0 - gap); // near-miss dead space is bad
            }
        }
    }

    // Compare against mean residual: prefer bins whose post_residual is close to (or below) mean.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if the item leaves a big awkward residual in any bin
        // or fits poorly everywhere. Base penalty keeps it conservative.
        score += 35.0;
        if post_residual as f64 / bin_capacity as f64 > 0.5 {
            score -= 20.0; // item is small; fresh bin keeps large flexibility
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Slight preference to fill older/scarcer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 18.0;

    // Penalize post-residual dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Bonus if next item can chain into this bin.
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Penalize crowding when many bins fit (prefer diversity).
        score += fitting_bins_count as f64 * 0.4;
    }

    // New-bin candidate: only attractive when current fits are poor or few bins fit.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Open a new bin when existing residuals are large (wasteful state)
        // or this is the only fitting option.
        let open_bonus = 30.0 * (1.0 - pressure) - 12.0 * (1.0 - poor_fit);
        score = score * 0.3 + bin_capacity as f64 * 0.5 - open_bonus;
        if fitting_bins_count <= 1 {
            score += 40.0; // never prefer new bin when it's the only fit
        }
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 8.0;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // Reward exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits via smooth non-linear polynomial in post_residual.
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Dead-space penalty: small but nonzero post_residual is wasted space.
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * 2.0 } else { 0.0 };
    score += dead;

    // Perfect-fit reward, smoothly scaled by stream progress.
    if post == 0 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits the post residual (smooth quadratic).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 35.0 * (1.0 - slack * slack) * (1.0 + 0.5 * progress);
        } else {
            let over = (nxt - post) / cap;
            score += 25.0 * over * over;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize spreading across many bins; prefer filling existing bins.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Mean-residual coupling: prefer bins whose residual is near the mean (balanced packing).
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: make opening a new bin costly unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 120.0 - 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- New-bin candidate detection ---
    if bin_residual == bin_capacity {
        // Opening a new bin is almost always worse than using an existing fit,
        // unless this is the ONLY option (fitting_bins_count <= 1 counts only this bin).
        let mut nb = cap + 50.0;
        if fitting_bins_count <= 1 {
            nb -= 500.0;
        }
        // Late in the stream, prefer consolidating into existing bins even more.
        nb += 30.0 * progress;
        // If next item is large, a fresh bin is somewhat more attractive.
        nb -= 0.1 * next_item_size as f64;
        return nb;
    }

    // --- Core: minimize post residual, but weight by usability classes ---
    let mut score = post;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Dead-space penalty: residual too small for ANY item (min size 1..100 unknown,
        // but small leftovers under ~10 are nearly unusable).
        if post_residual < 10 {
            score += 12.0;
        }
        // Harmonic class: residual divisible structure — round leftovers (multiples
        // of 10) are more likely reusable by future items; odd fragments less so.
        let cls = post_residual % 10;
        if cls != 0 {
            score += 2.0 + 0.2 * cls as f64;
        }
    }

    // Reward bins whose leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Leftover blocks the next item: mild penalty scaled by how much it blocks.
        score += 0.05 * (next_item_size as f64 - post);
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // More competing bins: slight tie-breaking toward tighter fits.
        score += 0.3 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer filling bins that are already relatively full (low residual),
    // coupling with the mean residual across open bins.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight late-stream tightening: waste matters more as stream nears end.
    score += 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps (< 10,
    // the classic minimum item size) and soft penalty for tight-but-wasteful gaps.
    if post_residual < 10 {
        score -= 50.0; // perfect fill: gap can never be used anyway
    } else if post_residual <= 20 {
        score += 25.0; // small gap: likely dead space
    }

    // Reward leaving room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 8.0; // cannot host next item: mild penalty
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        if post_residual >= 10 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins with residual near mean (balanced use).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    // Stream progression: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is already good; boost it).
    let exactness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * exactness * exactness;

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly prefer this bin (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let chain_quality = 1.0 - gap / (bin_capacity as f64);
        score -= 22.0 * chain_quality * chain_quality;
    }

    // Penalize post_residual that is *almost* but not quite the next item:
    // creates dead space that likely nothing will use.
    if next_item_size > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        if shortfall < next_item_size as f64 {
            score += 6.0 * (1.0 - shortfall / (next_item_size as f64)) * (1.0 - shortfall / (next_item_size as f64));
        }
    }

    // Penalize leaving residuals far from mean (fragmenting the fleet),
    // unless it's a great fit.
    score += 0.35 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default cost of opening a bin; make it attractive
    // only when the fit in open bins is poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.15 * (open_bins_count as f64);
    }

    // Late in the stream, close out bins aggressively (favor filling).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * exactness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract more when post_residual is small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead coupling: if the next item can still fit in the post-residual,
    // reward this bin strongly; otherwise penalize creating dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Dead space for the lookahead: penalize proportionally to wasted gap
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // fits poorly everywhere (large post_residual relative to capacity) or when
    // many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying late in the stream
        score = bin_capacity as f64 * 0.75 - 25.0 * progress;
        // If a perfect fit exists elsewhere, opening is bad
        if post_residual == 0 { score += 100.0; }
        if fitting_bins_count > 0 && item_size as f64 / bin_capacity as f64 > 0.9 {
            score += 50.0; // big items: always use an existing bin if it fits
        }
    }

    // Penalize bins whose residual deviates far below the mean residual
    // (they are already fragmented; prefer bins near or above the mean)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    // Mild pressure to close out bins when many are open
    score += 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear waste penalty: small residuals are dead space, penalize quadratically.
    let pr_norm = pr / cap;
    score += 40.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * pr_norm;

    // Reward placements that leave room for the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (nx <= pr) as i32 as f64;
        let tightness = 1.0 - ((pr - nx).abs() / cap);
        score -= 25.0 * fits_next * tightness * tightness;
    }

    // Stream-progress coupling: later in stream, prefer tighter packing more strongly.
    let progress_coupling = progress * progress;
    score -= 15.0 * progress_coupling * (1.0 - pr_norm);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when good alternatives exist; smooth in mean residual.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / cap);
        score += 20.0 + 30.0 * (1.0 - progress) + 10.0 * mean_tightness;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it decomposes into
    // useful capacity fractions (perfect fits are zero-score).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class 1: near-perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Class 2: post_residual divisible by common small item sizes
    // (harmonic divisibility makes residual reusable)
    if post_residual > 0 {
        for &d in &[10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 40.0;
                break;
            }
        }
        // penalize awkward odd residuals
        if post_residual % 2 == 1 && post_residual < 20 {
            score += 30.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item almost fits, penalize blocking.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            score -= 0.5 * (next_item_size as f64);
        } else if post_residual > 0 && next_item_size - post_residual <= 10 {
            score += 60.0; // just misses: dead space risk
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive if current residual is badly fragmented
    if bin_residual == bin_capacity {
        let pressure = (mean_residual - pr).abs();
        score += 120.0 - 0.8 * (open_bins_count as f64) - 0.5 * pressure;
        if frac > 0.9 {
            score -= 50.0; // early stream: fresh bin is fine
        }
    }

    // Prefer filling bins with large residual usage
    score -= 0.3 * (item_size as f64);

    // Mild drift over stream: tighten packing later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 30.0; // tiny dead space is nearly worthless
        } else {
            // value of residual depends on whether future items (10..80) can use it
            let usable = if post_residual >= 80 { 0.0 }
                else if post_residual >= 50 { 5.0 }
                else if post_residual >= 30 { 12.0 }
                else { 20.0 };
            score += usable;
        }
    } else {
        score -= 25.0; // perfect fit is highly rewarded
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.1 * next_item_size as f64;
    }
    // Penalize if next item almost fits (near miss wastes the gap).
    if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 40.0 + 6.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / (total_items as f64).max(1.0));
    } else {
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near match: next item fits into post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to lookahead item
        score += 8.0;
    }

    // Tight fit reward (small post residual overall)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins with residual far above mean (fragmentation risk)
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: penalize unless current bins are mostly full / crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let fullness = 1.0 - (mean_residual / bin_capacity as f64);
        score += 12.0 - crowding * 0.5 - fullness * 10.0;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0; // nothing fits anyway, new bin good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tight fit reward: small post residual is good
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize small-but-nonzero dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward leaving room for the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 25.0;
        } else {
            // next item cannot fit here; mild penalty scaled by waste
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { (item_size as f64) / mean_residual } else { 1.0 };
        // open new bin only if existing residuals are mostly too small relative to item
        score += 40.0 + 60.0 * (1.0 - pressure.min(1.0));
        if fitting_bins_count == 0 {
            score -= 500.0; // must open new bin
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer bins with residual close to item size (best-fit shaping)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    // Spread bonus: using bins with above-mean residual balances load
    if (bin_residual as f64) > mean_residual {
        score -= 8.0;
    }

    // Many open bins: discourage fragmenting further
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create dead-space classes.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.35;

    // Integer-division thresholds: post_residual in "quarter" bands of capacity.
    let quarter = (bin_capacity / 4).max(1);
    let band = (post_residual / quarter) as f64;
    score += band * band * 0.8;

    // Reward near-perfect fits strongly.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Penalize leaving residual too small for next item (dead space).
            let waste = (next_item_size - post_residual) as f64;
            score += (waste / cap) * 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and there are many open bins (fragmentation pressure).
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let fit_quality = (post_residual as f64 / cap) * 60.0; // item in empty bin
        let crowd = (open_bins_count as f64).ln().max(0.0) * 4.0;
        score += base_penalty + fit_quality - crowd;
        // If no open bin other than this fits, opening new bin is fine.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Prefer filling bins with lower residual among open bins (best-fit bias).
    score += (mean_residual - post_residual as f64) * 0.25;

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for the
    // smallest plausible item are pure waste -> extra penalty.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64;
    } else if post_residual > 0 && post_residual < item_size.min(20) {
        // gap smaller than likely next demand: soft dead-space penalty
        score += 12.0;
    }

    // Reward tight fits (small relative slack)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).max(0.0) * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        score += 15.0 + 3.0 * open_bins_count as f64 + pressure;
        // But if the item is large and mean residual is low, new bin is fine
        score -= 10.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    } else {
        // Filling an existing bin is rewarded more when pressure is high
        score -= 5.0 + pressure.min(20.0);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item would leave this bin's post_residual dead anyway, slight penalty
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(min_useful) {
        score += 8.0;
    }

    // Early in the stream, be more permissive about opening bins; later, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits perfectly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let look_gap = post_residual - next_item_size;
        score -= 10.0 * (1.0 - look_gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize if next item cannot use the leftover space (dead space risk).
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Relative to mean residual: bins with residual far above mean are worth filling.
    let rel = bin_residual as f64 - mean_residual;
    score -= 0.08 * rel;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 50.0;
        score += if bad_fit { 2.0 } else { 15.0 };
        // Early in the stream, be more willing to open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 4.0;
        }
    }

    // Mild penalty for accumulating many open bins with large residuals.
    score += 0.01 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) - norm_pr * norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 40.0 * poly;

    // reward tight fits, stronger late in stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // penalize post_residual that cannot fit the lookahead item (dead space), smooth ramp
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        let wasted = if pr < next_item_size as f64 { 1.0 - (next_item_size as f64 - pr) / cap } else { 0.0 };
        score += 12.0 * (1.0 - (gap * std::f64::consts::PI).cos()) * 0.5;
        score += 20.0 * wasted * (0.4 + 0.6 * progress);
        // bonus if post_residual exactly accommodates next item
        let match_bonus = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 10.0 * match_bonus.max(0.0) * match_bonus.max(0.0);
    }

    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // prefer bins with below-mean residual (conserving large residuals)
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm);

    // slight preference for using existing bins over new bin, decayed as stream progresses
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // item-size interaction: large items prefer small residuals
    score += 6.0 * norm_item * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on fine-grained
    // modulo classes are more reusable, reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 -> aligns with typical item sizes
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    // Class B: post_residual divisible by 5 but not 10
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 1.5;
    }
    // Class C: dead space — too small for the smallest plausible item (<= 8)
    if post_residual < 8 && post_residual > 0 {
        score += 25.0;
    }
    // Small-but-usable leftover: prefer exact-ish fills
    if post_residual > 0 && post_residual <= 10 {
        score -= 6.0;
    }

    // Integer-division threshold: leftover in the "large chunk" band (>= half capacity)
    // is valuable; penalize creating mid-band awkward leftovers.
    if post_residual >= bin_capacity / 2 {
        score -= 5.0;
    } else if post_residual >= bin_capacity / 3 {
        score += 2.0;
    }

    // Coupling with lookahead item (k=2): reward leftover that can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 7.0;
            // extra harmony: leftover after hypothetically hosting next item
            let after_next = post_residual - next_item_size;
            if after_next % 10 == 0 { score -= 3.0; }
            if after_next < 8 && after_next > 0 { score += 5.0; }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // mild penalty per competing bin to spread load when many options exist
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling bins below current mean residual (tighter packing)
    score += 0.3 * (pr - mean_residual);

    // Late in the stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (pr / cap);

    // New-bin candidate: opening a fresh bin is only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let bad_existing = if next_item_size > 0 && post_residual_check(bin_residual, item_size, next_item_size) { 0.0 } else { 6.0 };
        score += 18.0 - bad_existing + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

// helper inlined logic (kept as fn for clarity, pure arithmetic)
fn post_residual_check(residual: u32, item: u32, next: u32) -> bool {
    residual.checked_sub(item).map(|r| r >= next).unwrap_or(false)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1, but practically tiny gaps) are waste.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(post_residual as f64);
        let deadness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += 30.0 * deadness * (1.0 - post_residual as f64 / 100.0);
        if (post_residual as f64) < dead_threshold * 2.0 {
            score += 20.0; // nearly unusable sliver
        }
    } else {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 50.0;
    }

    // Reward filling a bin deeply (high utilization).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; when few bins, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += 5.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; a large residual left behind is fine,
            // but a medium awkward residual is penalized.
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.1 * gap;
        }
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (keeps the fleet homogeneous and predictable for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate logic: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins would leave
        // bad dead space or nothing fits well.
        let existing_bad = (post_residual as f64 > 0.0
            && post_residual < 10)
            || fitting_bins_count == 0;
        if existing_bad {
            score -= 35.0; // open new bin rather than fragment
        } else {
            score += 20.0 + 3.0 * open_bins_count as f64; // prefer reuse
        }
        // Early in stream, opening bins is cheaper (spread risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), weighted by fill ratio
    score += 0.5 * (bin_residual as f64) - 0.5 * (item_size as f64);

    // Aggressive 2-step lookahead: reward if next item exactly fits the residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff < 1.0 {
            score -= 60.0; // perfect chaining: next item fills this bin exactly
        } else if post_residual as f64 >= next {
            // next item can also fit here: partial reward proportional to closeness
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize dead space relative to next size
            score += 0.3 * (next - post_residual as f64);
        }
    }

    // Coupling with mean residual: prefer bins deviating favorably from mean
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-ish but slightly discourage unless
    // current fit is terrible (large post_residual on an open bin).
    if bin_residual == bin_capacity {
        // Opening fresh: score = capacity residual; subtract small bonus so it
        // wins only when open-bin fits leave lots of dead space.
        score -= 5.0;
        // Early stream: slightly favor opening bins to build diversity
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // Penalize leaving tiny unusable slivers (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer minimal waste: quadratic penalty on dead space.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: slight penalty proportional to wasted pairing potential.
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more conservative about filling bins tightly;
    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: if many bins are open with large mean residual, prefer compacting
    // into existing bins rather than opening new ones.
    if open_bins_count > 2 {
        score -= 0.3 * mean_residual / bin_capacity as f64;
    }
    // Penalize leaving this bin with residual far from mean (fragmentation control).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev / bin_capacity as f64;

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere (large post_residual in every existing bin) or stream is early.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a bin early when few bins exist.
        score -= 5.0 * (open_bins_count as f64).min(10.0);
        // If item is large relative to capacity, a fresh bin is more justifiable.
        score -= 0.2 * item_size as f64;
        // If no other bin fits, new-bin call naturally wins via other bins' penalties;
        // add small tie-break so genuinely poor fits go to a fresh bin.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 8.0 * norm_item * (1.0 - norm_item) * (1.0 - prog3);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + 2.0 * prog2) * 6.0;

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - gap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * norm_next * (0.3 + progress);
    }

    // Penalize divergence from mean residual (fragmentation signal)
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * progress;

    // New-bin candidate: make it slightly less attractive than a decent fit
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic classes on post_residual: dead space that cannot host
    // small items (post_residual < 10) is pure waste.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score -= 25.0; // unusable dead space, acceptable as near-closure
    } else {
        // Modulo classes: residuals in harmonically "useful" bands
        // (multiples of 10, 25, 50) are more reusable by future items.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 12.0;
        }
        if r % 25 == 0 {
            score -= 8.0;
        }
        if r % 50 == 0 {
            score -= 6.0;
        }
        // Integer-division threshold: residuals above half capacity are
        // flexible; residuals in (0, 25) are fragile dead zones.
        if r / 25 == 0 {
            score += 18.0 * (1.0 - r as f64 / 25.0);
        }
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // extra reward for near-exact chaining
            let chain_gap = post_residual - next_item_size;
            if chain_gap <= 5 {
                score -= 10.0;
            }
        } else {
            // penalize leaving a residual that barely misses the next item
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 10.0 + miss as f64;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening
    // a new bin instead by rewarding this bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 55.0;
        // If many bins can fit, opening new is wasteful
        if fitting_bins_count > 0 {
            score += 25.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If mean residual is large, open bins are loose; new bin less needed
        score += (mean_residual / 10.0).min(15.0);
        // If next item is large and mean residual small, new bin attractive
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 12.0;
        }
        // Late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Perfect-fit potential for next item in a fresh bin
        if next_item_size == bin_capacity {
            score -= 40.0;
        }
    }

    // Mild pressure against proliferating many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward (subtract) when post_residual == 0.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a future item (min size 1 => any gap is usable, but tiny gaps
    // relative to typical items are nearly dead). Penalize gaps that cannot
    // hold the lookahead item, and gaps below a smallness threshold.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 60.0; // gap is dead for the next item
        } else {
            score -= 10.0; // gap can host the lookahead item
        }
    }

    // Tiny-gap dead-space penalty: quadratic blowup for very small residuals.
    let pr = post_residual as f64;
    if pr < 15.0 {
        score += (15.0 - pr) * (15.0 - pr) * 2.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 0.5 * (bin_capacity as f64 - pr);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize placements into already-crowded fleets,
    // but only mildly, so tight fits still win.
    score += 0.3 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (balanced packing), penalize outliers.
    score += 0.2 * (pr - mean_residual).abs();

    // New-bin candidate: keep it competitive only when open bins would leave
    // bad dead space. An empty new bin has residual == capacity; make it
    // attractive if current bins would waste a lot.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 25.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_score -= 5.0; // fresh bin can host the next item
        }
        // If the best we could do in existing bins is a large dead gap,
        // opening a new bin looks better: handled implicitly since existing
        // bins carry the dead-space penalties above.
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly prefer exact / near-exact fills.
    if post == 0 {
        score -= 1000.0;
    } else if post <= 3 {
        score -= 200.0;
    } else if post <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // next item nests perfectly or near-perfectly
            let slack_after_next = post - nxt;
            score -= 80.0 + 3.0 * nxt - 2.0 * slack_after_next;
            if slack_after_next == 0.0 {
                score -= 150.0; // perfect 2-item chain
            }
        } else {
            // next item won't fit here: penalize proportional to leftover dead space
            score += 0.5 * (post / cap) * (nxt - post);
        }
    }

    // Compare against mean residual: bins with residual far below mean are tighter fits.
    score -= 2.0 * (mean_residual - post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize creating many small unusable gaps relative to capacity.
    if post > 0 && post < 10.0 {
        score += 0.0; // already rewarded above
    } else if post >= 10.0 && post < 25.0 {
        score += 5.0;
    } else if post >= 25.0 {
        score += 0.3 * post; // large leftover is wasteful unless next item fits (handled above)
    }

    // New-bin candidate: make it attractive only when the stream is early
    // or open bins are all poor fits (high mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (mean_residual - item_size as f64) < 5.0 && fitting_bins_count <= 1;
        if poor_fits {
            score -= 90.0;
        } else {
            // discourage opening new bins when decent fits exist, more so late in stream
            score += 150.0 + 200.0 * progress;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tight).powi(6);

    // Penalize dead space that cannot host a plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable sliver
    }

    // Lookahead coupling: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for large post residual
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins can fit the item, prefer the fullest (smallest residual already in score),
    // but add mild pressure to consolidate when open bin count is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates favorably from the mean residual
    // (below-mean residual = fuller bin = better choice).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: default neutral-ish; allow it only when no open bin is a good fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score -= 5.0; // last chance: discourage opening new bin mildly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: waste from post-residual, amplified non-linearly with stream progress
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Penalize small unusable residuals (dead space) super-linearly
    if pr > 0.0 {
        let dead = (1.0 - pr / cap).max(0.0);
        score += 12.0 * dead * dead * (pr / cap) * (1.0 - dead);
    }

    // Reward perfect-ish fits
    if pr == 0 { score -= 50.0; }
    else if pr <= 10 { score -= 25.0; }

    // Lookahead coupling: reward residual that fits next item exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 18.0 * (1.0 - slack / cap);
            if slack == 0.0 { score -= 20.0; }
        } else {
            // next item won't fit here; mildly penalize large leftovers
            score += 6.0 * (pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Encourage balance of residuals across open bins
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening bins, more so early and when alternatives exist
    if is_new_bin {
        score += 45.0 + 25.0 * (1.0 - progress) + 4.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 { score += 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions / integer division) ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual into harmonic classes: quarters, thirds, eighths of capacity.
    // Residuals landing exactly on capacity fractions are highly reusable -> reward.
    let quarter = (bin_capacity / 4) as f64;
    let eighth = (bin_capacity / 8) as f64;
    let third = c / 3.0;

    let near = |x: f64, t: f64, tol: f64| (x - t).abs() <= tol;

    // Exact / near harmonic classes get strong rewards (subtracted from score).
    if near(pr, quarter, 2.0) {
        score -= 12.0; // residual ~25: pairs well with mid items
    } else if near(pr, third, 2.0) {
        score -= 9.0;
    } else if near(pr, 2.0 * quarter, 2.0) {
        score -= 7.0; // half-full remainder is very flexible
    } else if near(pr, eighth, 2.0) {
        score -= 5.0;
    } else if near(pr, 3.0 * eighth, 2.0) {
        score -= 4.0;
    } else if near(pr, 0.0, 1.0) {
        score -= 30.0; // perfect fit, always prefer
    }

    // Dead space penalty: tiny unusable residuals (modulo classes 1..8) are wasted.
    if pr > 0.0 && pr < 8.0 {
        score += 18.0 - 2.0 * pr; // smaller dead space penalized more
    }

    // Integer-division threshold: bucket the residual into coarse deciles of capacity.
    let decile = (post_residual * 10 / bin_capacity.max(1)) as f64;
    score -= 1.5 * decile; // coarser bins with more room are mildly favored

    // --- Lookahead coupling: does post_residual pair with next_item_size? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Next item fits exactly into this bin's remainder -> strong reward.
            let slack = pr - nxt;
            if slack < 3.0 {
                score -= 20.0; // near-perfect lookahead match
            } else {
                score -= 8.0 * (1.0 - slack / c).max(0.0);
            }
            // Harmonic match: next item size in same eighth-class as residual
            let cls = |x: f64| (x / eighth).round() as i64;
            if cls(nxt) == cls(pr) {
                score -= 6.0;
            }
        } else {
            // Next item will NOT fit here; if this bin is the only fitting one,
            // placing here is last-chance -> reward; otherwise mild penalty.
            if fitting_bins_count == 1 {
                score -= 15.0;
            } else {
                score += 5.0;
            }
        }
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // --- Stream progression: early on, keep bins flexible; late, pack tightly ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (pr / c); // late stream: favor larger residuals less strictly
    score += 3.0 * (1.0 - progress) * (1.0 - pr / c); // early: penalize consuming big space

    // --- Mean residual coupling: avoid fragmenting the fleet ---
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        if rel < 0.4 {
            score += 6.0; // creating much-below-average residual fragments capacity
        } else if rel > 1.2 {
            score -= 3.0; // keeping above-average room is good
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: baseline cost = one extra bin.
        // Reward it when no good fit exists (all fits would leave tiny dead space
        // or the item barely fits an open bin), penalize when a clean fit exists.
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual < 10.0 && post_residual > 0.0);
        if poor_fit {
            score -= 25.0; // open a fresh bin rather than wreck an open one
        } else {
            score += 14.0 + 0.1 * open_bins_count as f64; // prefer existing good fits
        }
        // Late in the stream, opening new bins is cheaper than fragmentation
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small to fit even the smallest plausible item.
    let dead_threshold = 12.0_f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0; // poisoned gap: almost certainly wasted space
    }

    // Non-linear penalty on post_residual: small positive residuals are worse
    // than moderate ones because they are hard to fill later.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Perfect fit reward: exact fill (post_residual == 0) is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the item size (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; mildly penalize leaving a gap it can't use.
        score += 8.0;
    } else if next_item_size > 0 {
        // Next item fits but leaves another gap: penalize remaining slack after it.
        let after_next = post_residual - next_item_size;
        score += 0.15 * after_next as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 45.0 + 6.0 * open_bins_count as f64 * (0.5 + progress);
        // If no open bin fits at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If only one fitting bin exists with poor fit, new bin may be better;
        // handled implicitly by the last-chance reward on that bin.
    } else {
        // Slight reward for using existing bins as they accumulate.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., tighter bins) to consolidate filling.
    if bin_residual != bin_capacity {
        let dev = mean_residual - pr;
        score += 0.10 * dev; // higher-than-average residual => worse score
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item could fit here later; the smaller the leftover gap, the better.
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin unless the item is large and would dominate it.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 100.0 * fill_frac;
        // If no open bin fits, new bin is the only option; soften penalty.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Lookahead: opening a fresh bin is good if next item pairs with leftover.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Early in the stream, be slightly more willing to spread items across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post-residual is good, but avoid leaving slivers that
    // nothing can use (dead space below the minimum plausible item).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver penalty
    }

    // Reward filling bins that are already quite full (consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this placement (chained fits).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here afterward; slight penalty scaled by wasted space
        score += 0.1 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // early in the stream or when open bins fit poorly.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = bin_capacity as f64 * 0.9;
        // early stream: fresh bins are cheaper
        score -= 200.0 * (1.0 - progress);
        // if many bins fit the item, opening new is wasteful
        score += 40.0 * fitting_bins_count as f64;
        // if current bin would leave a huge residual mismatch with next item,
        // a new bin may be better
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 60.0;
        }
        // many open bins with high mean residual: prefer reusing them
        score += 0.5 * mean_residual;
        if open_bins_count > 8 {
            score += 100.0;
        }
    }

    // Late in the stream, squeeze existing bins harder.
    score -= 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic in post_residual (waste grows super-linearly)
    let mut score = post * post / cap + post;

    // Reward tight fits: small post_residual relative to item size
    score -= (item_size as f64 / (post + 1.0)) * 8.0;

    // Smooth coupling of waste penalty with stream progress:
    // later in the stream, waste matters more (less room to compensate)
    let progress_coupling = progress * progress;
    score += post * progress_coupling * 2.0;
    score -= fit_ratio * fit_ratio * 12.0 * (1.0 - progress_coupling);

    // Penalize bins whose residual deviates from mean (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * dev / cap * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: smooth penalty that relaxes only when the item is large
    // and the next item would not fit well into a fresh residual anyway.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        let next_waste = if next_item_size > 0 {
            let r = post - next_item_size as f64;
            if r < 0.0 { -r } else { r * r / cap }
        } else { 0.0 };
        score += 30.0 + open_pressure * 3.0 + next_waste * 0.3
            - fit_ratio * 20.0 * (1.0 + progress);
    } else {
        // Lookahead: reward leaving residual that fits the next item
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= (post - next_item_size as f64).min(20.0) * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: capacity fractions ---
    let pr = post_residual;
    // Exact fit is perfect.
    if pr == 0 {
        score -= 1000.0;
    }
    // Fractional classes of capacity: post_residual near C/k is "harmonically useful".
    let k_fractions = [50u32, 33, 25, 20, 10];
    for (i, &f) in k_fractions.iter().enumerate() {
        if pr >= f.saturating_sub(2) && pr <= f + 2 {
            score -= 40.0 - (i as f64) * 6.0; // C/2 residual most valuable, then C/3, ...
        }
    }

    // --- Integer-division dead-space class: small unusable slivers ---
    if pr > 0 && pr < 10 {
        score += 60.0; // dead space below min item size
    }

    // --- Modulo arithmetic on post_residual: penalize odd/awkward classes ---
    let m = pr % 10;
    if m != 0 {
        score += m as f64 * 1.5; // non-multiple-of-10 residuals are harder to fill
    }

    // --- Lookahead coupling: does next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Perfect harmonic pairing: next item exactly fills the remainder
            if next_item_size == pr {
                score -= 300.0;
            } else {
                let pair_waste = pr - next_item_size;
                score -= 60.0 - pair_waste as f64 * 0.8;
            }
        } else {
            // Next item won't fit here: residual likely becomes dead space
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // --- Fit tightness relative to item size ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 50.0;

    // --- Last-chance bin: strongly favor using it before opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate handling: only attractive early or when no bin fits well ---
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        // New bins are cheap early, expensive late; also compare against mean residual clutter
        score += 70.0 + progress * 120.0 - scarcity * 30.0 + (mean_residual / cap) * 40.0;
    }

    // --- Mild pressure against hoarding many open bins ---
    score += (open_bins_count as f64) * 0.3;

    // --- Mean-residual alignment: prefer bins whose residual matches the fleet mean ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1, but small gaps < ~12 are nearly
    // unusable given typical distributions) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity (low waste ratio).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: discourage spreading into many bins when few are open;
    // encourage using existing bins as open_bins_count grows.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Penalize bins whose residual is far below the mean residual (they are
    // nearly full; prefer to concentrate fills there to close bins out).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins would leave a large dead gap.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; scales with how many bins are
        // already open (fragmentation pressure) and stream progress.
        score = 55.0 + open_bins_count as f64 * 1.5 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If lookahead item would fit into the fresh residual, slightly cheaper.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Lookahead coupling: bonus if next item fits the resulting gap.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 12.0;
            } else if post_residual < next_item_size && post_residual < 25 {
                // Gap likely dead relative to the known next item.
                score += 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
