pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post residuals (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize creating dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / next_item_size as f64).ln().max(0.0);
        } else {
            score += 5.0; // next item cannot follow here
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.15 * (bin_residual as f64 - post_residual as f64);
    }

    // New-bin candidate handling: opening a bin is costly when open bins exist
    // and item fits reasonably; cheaper early in the stream or when many bins
    // are open with fragmented residuals.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        let mut open_cost = 20.0 + 30.0 * fit_quality * fit_quality;
        open_cost += 10.0 * progress; // late in stream, prefer reusing bins
        if open_bins_count == 0 {
            open_cost = -50.0; // must open
        } else if fitting_bins_count == 0 {
            open_cost = -10.0; // nothing fits, must open
        }
        // If mean residual across open bins is small, reuse is hopeless anyway.
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            open_cost -= 15.0;
        }
        score += open_cost;
    } else {
        // Mild penalty for very full bins being consumed when alternatives exist.
        if fitting_bins_count > 2 && post_residual < 10 {
            score += 4.0;
        }
        // Encourage balancing: prefer bins with residual below mean (denser bins).
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Slight preference for filling bins with larger residual when many bins open.
    score -= 0.02 * bin_residual as f64 * (open_bins_count as f64).ln().max(1.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual (tight fit), with non-linear emphasis
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth interaction: as stream progresses, penalize larger residuals more
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 12.0 * progress_coupling * norm_post * norm_post;

    // Reward tight fits smoothly: quadratic decay of reward as post grows
    let tightness = (1.0 - norm_post).max(0.0);
    score -= 20.0 * tightness * tightness * tightness;

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = norm_next / (norm_post + 1e-6);
        score -= 8.0 * (1.0 - chain_fit.min(1.0));
    } else if next_item_size > 0 {
        // next item won't fit: penalize wasted residual that is close to next size
        let gap = (post - norm_next * cap) / cap;
        if gap.abs() < 0.15 {
            score += 10.0 * (1.0 - gap.abs() / 0.15);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // slight penalty to allow discrimination among many fits
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Penalize bins far from mean residual (keeps bin pool homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate handling: make fresh bins attractive early, costly late
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score = cap * (0.9 + 0.6 * progress) + 2.0 * open_f * progress;
        // early stream: fresh bin is fine (score near cap), late: heavily penalized
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on small residuals.
    // Residuals in {0} are perfect; tiny residuals (1..=5) are near-perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    } else {
        // Penalize mid-range dead space, worse in fine modulo classes.
        let class = post_residual % 10;
        score += class as f64 * 0.5;
        score += (post_residual as f64 - 10.0) * 0.3;
    }

    // Lookahead coupling: reward if next item fits exactly-ish, penalize if it cannot fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.2; // exact fit for next item is best
        } else {
            // next item won't fit here: residual becomes dead space
            score += post_residual as f64 * 0.4;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild penalty when many bins are open and this one is already crowded,
    // encouraging consolidation; mean_residual coupling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score += 3.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Make new-bin candidate (empty bin) unattractive unless residual would be tiny.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        if item_size >= 80 {
            score -= 20.0; // huge items better in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
