    // Mild early-stream openness: allow new bins early, consolidate later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Bonus decays with the gap between post_residual and next item size.
        score -= 35.0 * (-gap / 20.0).exp();
        // Extra reward for a perfect chain (next item fills bin exactly afterwards).
        if post_residual == next_item_size {
            score -= 45.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space that the next item cannot use.
        let waste_ratio = 1.0 - (next_item_size as f64 / post_residual as f64).min(1.0);
        score += 25.0 * waste_ratio;
    }

    // Relative to mean residual: prefer bins below-average residual (tighter bins),
    // penalize dumping items into already-loose bins.
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in the stream, be slightly conservative about opening new bins;
    // late in the stream, favor consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress;

    // Many open bins: encourage filling existing ones rather than opening more.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: penalize moderately so it's chosen only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
