        // Next item is small-ish; penalize leaving a gap that cannot host it.
        score += 4.0;
    }

    // Global state: penalize spreading across many open bins when residuals are high.
    let residual_spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * residual_spread;

    // Encourage using bins with below-average residual (keeps balance).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Time horizon: late in the stream, be more aggressive about filling existing
    // bins tightly and less willing to open new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate penalty: opening a bin should only win for large items
    // that would leave a very usable residual, or when no bin fits.
    if bin_residual == bin_capacity {
        let new_bin_bias = if item_size >= 50 { 8.0 } else { 20.0 };
        score += new_bin_bias + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // a fresh bin can chain the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
