    let norm_pr = pr / cap;
    let norm_it = it / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: residual usefulness decays quadratically with progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize large post-residuals that cannot fit a typical future item
    let fit_loss = (norm_pr - norm_it).abs();
