    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual
    let density = mean_residual / (cap * open_bins_count.max(1) as f64);
    score += 5.0 * density * (1.0 - norm_pr);

    // New-bin candidate: penalize gently so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
