        // Fractional capacity coupling: reward leaving residuals that are nice multiples.
        let cap_frac = post_residual as f64 / bin_capacity as f64;
        if (post_residual % 25 == 0) || (post_residual % 20 == 0) {
            score -= 6.0 * cap_frac * 10.0;
        }
        // Tight fit bonus: item fills bin almost exactly.
        if post_residual <= 5 {
            score -= 25.0;
        }
        // Reward using a bin whose residual was in the "awkward middle" band.
        if bin_residual >= 60 && item_size >= 50 && post_residual < 20 {
            score -= 8.0;
        }
        let _ = inv;
    }

    // Last-chance bin: strongly favor filling it before opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            score -= 10.0 - (rem as f64) * 0.15;
            // Harmonic pair check: post_residual splits into two halves for next item.
            if post_residual >= 2 * next_item_size && post_residual % (2 * next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; penalize mildly, scaled by stream progress.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 6.0 * (0.5 + progress);
        }
    }

    // Prefer denser bins when many bins are open (reduce fragmentation).
    let density = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= density * 5.0;

    // New-bin candidate: keep it competitive only when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0 - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 20.0; // big next item: fresh bin is attractive
        }
    }

    // Mean residual coupling: if this bin is below mean residual, it's a better target.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score += 40.0; // tiny dead gap, nearly unusable
    } else if post_residual <= 25 {
        score += 12.0; // awkward small gap
    } else {
        // Larger post-residuals are somewhat useful; mild reward for keeping room.
        score -= 5.0;
    }

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 3 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 10 {
            score -= 50.0;
        }
    }

    // New-bin candidate: opening a bin is attractive only when the current item is small
    // (keeps a big fresh residual) or when open-bin pressure is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for small items into fresh capacity; penalize when many bins open.
        score = 100.0 * fit_quality + 8.0 * open_bins_count as f64 - 20.0 * (1.0 - progress);
        if item_size <= 30 {
            score -= 25.0; // small items start new bins cheaply
        }
        if item_size >= 70 {
            score += 30.0; // big items should go into existing partial bins
        }
        // If the next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
        return score;
    }

    // Lookahead: if next item can use this bin's post-residual, reward the placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap just below the next item's size (frustrating near-miss).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size - 3 {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, tighten packing (favor tighter fits).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: when mean residual is high, prefer bins that reduce spread.
    score += 0.2 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 2.0;
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving residuals too small for any plausible item (dead space)
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if lookahead pairs well with a fresh bin, soften penalty
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() < 5 {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (bin_residual - item_size) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to fill ratio after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize small unusable post-residuals (dead space): residual < 10 is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Sweet spot: leaving space for a small item (10..30) is good.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly prefer this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            // next item just barely misses: mild penalty
            score += 5.0;
        }
        // If next item is large and this bin's residual is the only place it could go,
        // avoid consuming space that a better split could use.
        if next_item_size > post_residual && next_item_size > 50 && post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist with decent residual.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalize more when mean residual could still absorb items.
            score += 20.0 + mean_residual * 0.15;
            // Early in stream, prefer reusing bins more aggressively.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 15.0 * (1.0 - progress);
        } else {
            score -= 10.0; // must open a bin
        }
    }

    // Global pressure: many open bins with large mean residual -> favor consolidation.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 5.0;
    }

    // Mild time-horizon term: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Base: prefer small post-residual, with smooth non-linear penalty growth
    let mut score = pr + 30.0 * norm_pr * norm_pr;
    // Polynomial coupling of post-residual with stream progress:
    // late in the stream, dead space hurts more
    let coupling = (0.5 + 1.5 * progress) * norm_pr * (1.0 - norm_pr);
    score += 40.0 * coupling * (1.0 - progress);
    score -= 60.0 * progress * norm_pr * norm_pr;
    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 15.0 * snug * (1.0 - progress);
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            score += 8.0 * ((nx - pr) / cap);
        }
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }
    // Many open bins: encourage filling existing ones rather than spreading
    let open_norm = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    score += 10.0 * open_norm * norm_pr;
    // Prefer bins tighter than the mean residual (compact packing)
    score += 5.0 * (pr - mean_residual) / cap;
    // New-bin candidate: give it a moderate default so it wins only over poor fits
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.3 * progress) + 5.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class: how finely post_residual divides the capacity.
    // Small residuals that are "useless" (below min item size 1 -> dead space) get penalized.
    let dead = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += 40.0 * dead;

    // Modulo classes: residuals that are multiples of common item granularities
    // (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr % 10 == 0 { score -= 6.0; }
    if pr % 20 == 0 { score -= 4.0; }
    if pr % 25 == 0 { score -= 3.0; }
    if pr % 50 == 0 { score -= 5.0; }

    // Integer-division threshold: bucket post_residual into quarters of capacity.
    let quarter = bin_capacity / 4;
    let bucket = pr / quarter;
    score += match bucket {
        0 => 8.0,   // tiny leftover: nearly dead
        1 => 0.0,
        2 => -2.0,  // half-ish space: very reusable
        3 => -4.0,
        _ => -1.0,
    };

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // Harmonic bonus: next item leaves a multiple-of-10 residual too.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
        } else {
            score += 12.0; // next item won't fit here; this bin likely closes
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate handling: empty bin gets a mild default penalty so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If nothing currently fits, opening is better.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && item_size < bin_capacity / 4 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals in the "unusable gap" zone
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 40.0; // dead space: nothing can ever go here
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, zero waste
    }

    // Non-linear penalty on waste fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Reward tight fits relative to the item size.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open bins pressure: with many bins open, prefer consolidation
    // (favor bins with small residual, penalize spreading).
    score += (open_bins_count as f64) * 2.0 * (1.0 - waste_frac);

    // Deviation from mean residual: prefer bins that keep residuals uniform,
    // but when this bin is the last chance, override strongly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64).min(10.0) / 10.0;
        } else {
            // next item won't fit here; penalize leaving a large gap
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when
    // no open bin offers a decent fit. Make the empty bin moderately
    // attractive (its post_residual = capacity - item is maximal waste
    // potential but also maximal flexibility).
    if bin_residual == bin_capacity {
        // neutral-ish baseline, scaled by how crowded the open set is
        score += 10.0 + (open_bins_count as f64).min(20.0);
        // early in the stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // if next item is large, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item's size (perfect chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 40.0; // perfect two-step match: strongly favor
        } else if post_residual as f64 >= nxt {
            // next item fits here afterwards: mild reward scaled by tightness
            score -= 8.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item will NOT fit after this placement: penalize dead space
            score += 6.0 + diff * 0.15;
        }
    }

    // Prefer tight fits overall: reward small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * tightness;

    // Relative to mean residual: bins with residual far below mean are precious,
    // avoid wasting them on small items; bins above mean are good candidates.
    let rel = post_residual as f64 - mean_residual;
    score += 0.05 * rel;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when current fits are poor
    // (large post_residual waste in all open bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = mean_residual / bin_capacity as f64;
        // Penalize new bin mildly; less so when open bins are fragmented or early.
        score += 12.0 - 10.0 * waste_pressure - 5.0 * (1.0 - progress);
    }

    // Slight preference to fill older/more crowded bins to consolidate.
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
        // Chain fit: post residual can hold next item with reasonable slack left.
        let chain_residual = post_residual as f64 - next_item_size as f64;
        if chain_residual >= 0.0 {
            score -= 5.0 * (chain_residual / bin_capacity as f64);
        }
    }

    // Prefer using existing crowded bins over spreading load.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        // New-bin candidate: penalize unless current bin fits are very poor.
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 25.0 + 20.0 * progress - 0.5 * mean_gap;
        // Opening a new bin is fine when few bins are open or item is huge.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for bins with residual close to item size (best fit).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer leaving small post_residual (tight fit).
    let mut score = post;

    // Non-linear waste penalty: dead space that can't fit typical items is costly,
    // penalized quadratically and more severely as the stream progresses.
    let waste = post / cap;
    score += 12.0 * waste * waste * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item) with a smooth coupling.
    let tightness = item / (bin_residual as f64 + 1.0);
    score -= 8.0 * tightness * (1.0 - progress);

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; slight penalty for leaving unusable space.
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin (especially late in the stream).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.6 + 0.4 * progress);
    }

    // New-bin candidate handling: make an empty bin attractive only when existing
    // bins would be badly fragmented (high mean residual dispersion / large post).
    if bin_residual == bin_capacity {
        // Neutral-ish default; subtract more early (building capacity early is fine),
        // add penalty late to encourage closing out open bins.
        score = 0.35 * cap + 20.0 * progress - 5.0 * (1.0 - progress);
        // If open bins are nearly full on average, opening fresh is reasonable.
        if mean_residual < 0.25 * cap {
            score -= 6.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals divisible by common size classes
    // (multiples of 10, 25, 50) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "harmonic" (divisible by 10 or 25/50 classes)
    let harmonic_bonus = if post_residual % 50 == 0 {
        18.0
    } else if post_residual % 25 == 0 {
        12.0
    } else if post_residual % 10 == 0 {
        8.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize tiny dead space (unusable slivers) non-linearly
    if post_residual < 10 {
        score += (10.0 - pr) * 2.5;
    }

    // Reward tight fits: small post_residual relative to capacity
    score -= (1.0 - pr / cap) * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Brand-new empty bin candidate: neutral baseline, slightly penalized so we
    // only open new bins when existing bins look truly bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If current item is large and lookahead is large too, fresh bin is good
        if next_item_size > 0 && next_item_size as f64 / cap > 0.5 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot use this bin's remainder: penalize large leftover
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Prefer filling bins with low mean residual (consolidate waste)
    score -= (mean_residual / cap) * 5.0;

    // Late in the stream, be more aggressive about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.02 * (1.0 - progress);

    // Modulo-threshold coupling on item_size: odd-class items create awkward gaps
    if item_size % 10 != 0 && post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are penalized heavily,
    // while exact fills (post_residual == 0) are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // unusable sliver penalty
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0; // near-dead space
    }

    // Reward tight fits: low post_residual relative to item size.
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + tightness);

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) * 0.3).abs();

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave a tiny gap, slightly penalize.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && post_residual >= next_item_size {
        score += 6.0;
    }

    // Mean-residual coupling: placing into a bin below mean residual keeps
    // large gaps available for large future items.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: make the empty bin attractive only when no good
    // existing fit exists (its raw post_residual is large, so the dead-space
    // logic is neutral for it; add a mild fixed cost so it loses to tight fits).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: strongly reward leaving exactly next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 {
        // Penalize deviation from perfect lookahead match.
        let miss = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * miss;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize small unusable dead space relative to item scale.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.10 {
            score += 40.0 * (0.10 - dead) / 0.10;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // Opening a new bin is more attractive if mean residual is small (fragmented bins).
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
    } else {
        // Favor tight fits among open bins: compare residual to mean residual.
        score += 0.5 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits into the post residual, reward; penalize if it blocks it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Prefer bins with residuals close to the item size (minimal waste).
    let waste_gap = (bin_residual - item_size) as f64;
    score += 0.3 * waste_gap;

    // Global state coupling: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score += 12.0 + 10.0 * progress + 0.5 * open_pressure;
        // But allow new bin if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference for fuller bins among candidates.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer minimal post residual (tight fit), scaled non-linearly.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, waste matters more; early, flexibility matters.
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space that nothing typical can use (quadratic waste).
    score += 8.0 * norm_pr * norm_pr * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a bin, decaying if many items remain
        // (long horizon amortizes a fresh bin) but rising late.
        score = 40.0 * (1.0 - progress) + 20.0 * progress;
        // Encourage new bin if the item is large and residuals elsewhere are small.
        score -= 15.0 * norm_item * (mean_residual / cap);
    } else {
        // Discard bins whose post-residual can't hold a plausible next item.
        if next_item_size > 0 {
            let next = next_item_size as f64;
            if pr < next {
                score += 10.0 * (next - pr) / cap * (1.0 + progress);
            } else {
                score -= 3.0 * ((pr - next) / cap) * (1.0 - progress);
            }
        }
        // Prefer bins with residuals close to the mean (balance open bins).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 6.0 * dev * dev;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small dead space rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 15 {
        score -= 40.0;
    } else if pr <= 30 {
        score -= 10.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes are reusable.
    if pr >= 10 {
        if pr % 10 == 0 { score -= 30.0; }
        if pr % 5 == 0 { score -= 10.0; }
        if pr % 20 == 0 { score -= 15.0; }
        if pr % 25 == 0 { score -= 15.0; }
    }

    // Dead-space penalty grows superlinearly for mid-range residuals (hard to fill).
    if pr > 30 && pr < 60 {
        score += (pr as f64 - 30.0) * 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            score -= 60.0 - (leftover as f64) * 1.2;
        } else {
            // next item won't fit here; mild penalty for wasting a flexible bin
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 90.0 + (open_bins_count as f64) * 2.0;
    }

    // Prefer fuller bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.8;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Late-stream tightening: as stream progresses, discourage opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold even the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps are risky unless the next item fits exactly.
        if next_item_size > post_residual {
            score += 25.0;
        } else {
            score -= 15.0; // next item can use this gap
        }
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Pressure to close bins: prefer fuller bins when many bins are open.
    score += (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64) * 10.0;

    // Mean residual coupling: avoid leaving residual far above the mean (wasted space).
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score = 100.0 + (post_residual as f64);
        if fitting_bins_count == 0 {
            score -= 200.0; // forced open
        }
        // Late in stream, opening new bins is cheap since residual won't be reused much.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits but avoid tiny dead space
    if post_residual == 0 {
        score -= 50.0; // perfect fill is ideal
    } else if post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // penalize if next item won't fit here but would fit elsewhere
        if next_item_size > post_residual {
            score += 15.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless residuals of open bins are all poor
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - item_size as f64;
        score += 40.0;
        if avg_waste < 15.0 {
            score += 30.0; // open bins are tight; new bin acceptable
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    } else {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space below
    // the smallest plausible item is wasted — penalize unusable slivers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Tight fit reward (subtracted), stronger as stream progresses.
    score -= fit_ratio * (30.0 + 40.0 * progress);

    // Penalize dead space that nothing small can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1.0 {
            score -= 20.0;
        } else if post_residual as i64 - next_item_size as i64 >= 0 {
            score -= 6.0;
        } else if (bin_residual as f64 - nr).abs() < 1.0 {
            // Next item fits this bin perfectly only if we place here — mild reward.
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // New-bin candidate: opening a new bin is wasteful when the item fits
    // reasonably well in an existing bin; make the empty bin score high
    // (bad) unless the fit elsewhere is truly terrible.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream with many open bins, opening new bins is worse.
        score += 20.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item is large and mean residual is small, a new bin
        // may be the only sane option — soften the penalty.
        let slack = mean_residual - item_size as f64;
        if slack < 5.0 {
            score -= 55.0;
        }
    } else {
        // Prefer bins with residual close to item size (best-fit flavor),
        // modulated by global mean residual: pick below-mean-residual bins
        // to consolidate fragmentation.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Slight preference for bins with small residual overall (fill fuller bins first).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Base: penalize leftover space, with super-linear (quadratic) waste aversion.
    let pr = post_residual as f64;
    let mut score = pr + (pr * pr) / cap;

    // Smooth coupling: waste is more costly as the stream progresses.
    score *= 1.0 + 0.5 * progress;

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize if post_residual is too small to fit the next item
    // (dead space), reward if next item fits snugly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 6.0 * (ni - pr) / cap;
        } else {
            score -= 4.0 * (1.0 - (pr - ni) / cap);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins; encourage consolidation
    // when mean residual is high (bins are still roomy).
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // Slight preference for fuller bins overall.
    score -= 5.0 * (bin_residual as f64 / cap);

    // New-bin candidate: keep it neutral-to-slightly-high so it wins only
    // when open bins would create large waste.
    if bin_residual == bin_capacity {
        score += 3.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it falls into
    let item_class = (item_size * 4) / bin_capacity; // 0..3 harmonic class
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward tight fits: small post_residual is good (already base score), but
    // extra reward when post_residual lands in a "usable" harmonic class
    // (residuals that many future items can still fill).
    let usable = match post_residual {
        0 => 60.0,                    // perfect fill
        r if r >= 10 && r <= 30 => 25.0,   // small class items can fill
        r if r > 30 && r <= 50 => 12.0,
        r if r > 50 && r <= 70 => 5.0,
        _ => 0.0,
    };
    score -= usable;

    // Modulo logic: residuals divisible by common item sizes are more reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Dead-space penalty: very small unusable residue (1..9) is nearly dead
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses the leftover
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * fill_ratio;
        } else {
            // next item cannot use this bin's leftover; slight penalty
            score += 4.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are poorly loaded or item is huge (bad fragmentation risk).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // large items pack poorly later; opening fresh bin for them is fine
        if item_class >= 3 {
            score -= 40.0;
        }
        // early in stream, opening bins is cheaper (more future items to fill)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // many open bins with low mean residual => prefer reusing them
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 18.0;
        }
    }

    // Mild penalty for spreading load thin across many bins
    score += 0.05 * open_bins_count as f64;

    // Integer-division threshold on post_residual: prefer leaving >= 50
    // (half-capacity) leftovers that pair with medium items.
    if post_residual / (bin_capacity / 2) >= 1 && post_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically small gaps) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // Penalize if the leftover gap can't fit the next item but is nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin
    // only when fit is poor; few open bins -> discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if it avoids large dead space elsewhere.
        score -= 5.0 + 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        score += 10.0 * (1.0 - progress); // early on, opening bins is fine
    } else {
        // Existing bin: mild penalty scaled by how crowded the bin set is.
        score += (open_bins_count as f64) * 0.3;
    }

    // Prefer bins with residual close to item (tight fit) vs. wasteful large-bin use.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 5.0;

    // Align with mean residual: using bins below mean residual consolidates.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after the hypothetical next placement
            score += 0.35 * slack;
            if slack <= 10.0 {
                score -= 15.0; // near-perfect two-step chain
            }
        } else {
            // next item cannot go here; penalize dead space proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead.min(40.0);
        }
    }

    // Relative-to-mean coupling: prefer bins below mean residual (tighter than average).
    let dev = mean_residual - (bin_residual as f64);
    score += 0.25 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // open a new bin only if mean residual is small (open bins are nearly full)
        score += 30.0 + 40.0 * (1.0 - fragmentation) - 10.0 * progress;
        // don't open a new bin if next item could combine with current in a fresh bin
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 12.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Tightness reward: reward bins whose post-residual is small but not zero-waste ---
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - residual_frac) * (1.0 - residual_frac) * 40.0;

    // --- Lookahead coupling: reward bins where the NEXT item also fits the post-residual ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - leftover_after_next);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating dead space the lookahead item cannot use.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // --- Last-chance bonus: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // --- New-bin candidate logic: empty bin should usually score poorly ---
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 70.0;
        // Escalate penalty as more bins are already open (fragmentation cost).
        score += open_bins_count as f64 * 3.0;
        // But allow new-bin opening when existing residuals are poor fits:
        // if mean residual is small relative to item, existing bins are tight -> new bin OK.
        let fit_slack = (mean_residual - item_size as f64).abs();
        if fit_slack > 20.0 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 30.0;
    }

    // --- Global state coupling: when many bins are open with high mean residual,
    //     encourage filling the emptiest-matching bins to reduce fragmentation ---
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.3; // prefer bins with residual above the mean (large slack used well)
    }

    // --- Prefer placing large items early into roomy bins ---
    if item_size >= 50 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: small post-residuals are valuable, especially late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 14.0 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space quadratically, weighted by stream progress
    score += 10.0 * norm_pr * norm_pr * (0.4 + 0.6 * progress);

    // Reward perfect/near-perfect fits via cubic term
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward residual that could fit the next item smoothly
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap) * gap;
        } else {
            score += 4.0 * gap * gap;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open and residual is wasteful
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Nudge toward bins below mean residual (consolidation)
    score += 0.1 * (pr - mean_residual);

    // New-bin candidate: penalize opening a new bin unless residual would be small
    if bin_residual == bin_capacity {
        score += 6.0 + 12.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no future item (min size 1..100)
    // can plausibly fill is worse. Classify post_residual by residue classes.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space severity grows quadratically for small residuals (unusable slivers).
        if pr <= 10 {
            score += (11 - pr) as f64 * 12.0; // tiny slivers are nearly worthless
        } else if pr <= 20 {
            score += (21 - pr) as f64 * 4.0;
        } else if pr <= 50 {
            score += 8.0;
        } else {
            // Large residual left behind: bin still flexible, mild reward.
            score -= (pr as f64 - 50.0) * 0.3;
        }

        // Modulo-10 harmonic classes: residuals that match common item size
        // multiples of 10 (or 25/50) are more reusable.
        let m = pr % 10;
        if m == 0 {
            score -= 6.0;
        } else if m == 5 {
            score -= 2.0;
        } else {
            score += m as f64 * 0.8; // odd residues less reusable
        }
        if pr % 25 == 0 || pr % 50 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            // Reward if the pair leaves a clean harmonic residual.
            if nxt_post % 10 == 0 {
                score -= 20.0;
            }
            score -= (nxt_post as f64).sqrt() * 2.0;
        } else {
            // Next item won't fit here; penalize leaving residual the lookahead can't use.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin would
    // be left with a nasty sliver or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral base for a fresh bin; make it unattractive unless fits are bad.
        score = cap * 0.5 + 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin accommodates the lookahead well
        }
        // Late in the stream, prefer closing out open bins rather than spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Slight preference for bins with lower residual than the mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to reduce open bin count when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< min item size) are heavily penalized.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits (small but still usable residuals).
    if post_residual > 0 && post_residual <= 15 {
        score -= 12.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure: with many open bins, prefer filling existing ones over new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate baseline: make it unattractive unless open bins are truly bad fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a residual that wastes potential for the next item.
    if next_item_size > 0 && next_item_size > bin_residual {
        score += 5.0;
    }

    // Slight preference for bins tighter than average.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: if the next item exactly fills the post residual,
    // this is an ideal placement -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // If the next item also fits into the post residual, reward proportional closeness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize creating dead space that the next item cannot use.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        let dead = post_residual as f64;
        let rel_dead = dead / (next_item_size as f64);
        score += 20.0 * rel_dead.min(2.0);
    }

    // Penalize very small post residuals (unusable slivers) unless they perfectly match.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins whose residual is already small
    // (tight packing) relative to the fleet average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mildly discourage opening a new bin when other fitting bins exist.
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 20.0;
    }

    // Early in the stream, slightly favor opening bins (spread items) to build
    // flexible residuals; late in the stream, favor tight fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += 6.0 * (next_item_size as f64 - dead);
        }
        // Small unusable slivers are worse than medium gaps
        if dead < 10.0 {
            score += 8.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score += 22.0 + 10.0 * (1.0 - progress) + 3.0 * pressure;
        // If item is large relative to capacity and mean residual is low, new bin less bad
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Prefer bins with residual below the mean (consolidate fullness)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Time horizon: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate slack
    // to keep bins open for future items.
    let mut score = norm_pr * (1.0 + 0.8 * progress) + 1.6 * norm_pr * norm_pr * (1.0 - progress);

    // Reward near-perfect fills: smooth Gaussian-like bump around small residual.
    score -= 2.0 * (-((pr - 5.0) * (pr - 5.0)) / 60.0).exp();

    // Penalize dead space that cannot fit typical next item (smooth interaction).
    let nxt = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let gap = (norm_pr - nxt).max(0.0);
        score += 1.2 * gap * (1.0 - progress);
        // Reward when post_residual fits next item snugly.
        let snug = (norm_pr - nxt).abs();
        score -= 0.8 * (-snug * snug / 0.02).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless residual is huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 + 2.0 * (1.0 - norm_pr);
    }

    // Mild penalty when many bins are open and this placement leaves odd slack.
    let ob = open_bins_count as f64;
    score += 0.15 * (norm_pr * norm_pr) * (ob / (ob + 5.0));

    // Slight preference for filling bins below mean residual (consolidation).
    let mrn = mean_residual / cap;
    score += 0.5 * (norm_pr - mrn) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or current bins are quite full.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 2.5 - 2.0 * fill * fill - 0.5 * progress + 0.3 * (mrn - norm_pr);
        // If next item would fit in fresh bin's leftover, small bonus.
        if next_item_size as f64 + item_size as f64 <= cap {
            score -= 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual: waste quantized by capacity fractions
    // Residuals that are too small to host the smallest item (1) matter less,
    // but residuals below common item sizes are dead space.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead space in non-linear way: small leftovers are worse than moderate ones
    if post_residual > 0 {
        // dead-space penalty grows as leftover becomes "unusable"
        let dead = if post_residual < 20 {
            (20 - post_residual) as f64 * 2.0
        } else if post_residual < 35 {
            (35 - post_residual) as f64 * 0.8
        } else {
            0.0
        };
        score += dead;
    }

    // Modulo/harmonic class coupling: if next item fits exactly into post_residual,
    // strongly reward (chain packing)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: reward proportional to how snugly
        score -= 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // next item cannot fit here; leftover is final waste
        score += frac * 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin costs; make it unattractive unless current bin would leave big waste
        score += 120.0;
        // Early in stream, opening bins is cheaper (more items to come to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 60.0;
        // If many open bins already, discourage proliferation
        score += open_bins_count as f64 * 3.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Integer-division harmonic threshold on post_residual classes
    let class = post_residual / 25; // 0..=4 harmonic classes
    score += match class {
        0 => 0.0,          // 0..24: nearly full, great
        1 => 5.0,          // 25..49: moderate
        2 => 12.0,         // 50..74: half-empty
        3 => 20.0,         // 75..99: mostly empty
        _ => 0.0,          // full/new bin handled above
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure against opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Slight preference for fuller bins relative to mean residual.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to item size)
    score -= (item_size as f64) * 0.8;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - lookahead_gap / (bin_capacity as f64));
        // Perfect chaining: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: prefer minimal waste
        score += 5.0;
    }

    // Last chance: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Penalize the brand-new empty bin candidate unless open bins are bad fits
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the current item is small and next item is large, opening a fresh bin is fine
        if next_item_size > 60 && item_size < 40 {
            score -= 25.0;
        }
    }

    // Late in the stream, consolidate into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize creating small unusable dead space: residual below 10 is dead.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting space.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins are open
    // or when the item fits reasonably in existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 30.0 + 20.0 * progress + 10.0 * fit_pressure
            + (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Mild reward for consolidating into bins that are already emptier than average.
        if (bin_residual as f64) > mean_residual {
            score -= 2.0;
        }
    }

    // Slight preference for filling bins more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (item_size as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize large unusable dead space with a smooth cubic term
    score += 6.0 * norm_pr * norm_pr * norm_pr * cap;

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= 4.0 * (1.0 - norm_pr) * progress;

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 3.0 + 2.0 * progress;
    } else if next_item_size > 0 {
        score += 1.5 * (next_item_size as f64 - pr) / cap;
    }

    // Mild preference for bins deviating from mean residual (consolidation)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 8.0 * (1.0 - progress) - 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularities (10, 20, 25) are more reusable than odd remainders.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { class_bonus += 12.0; }
        if pr % 20 == 0 { class_bonus += 8.0; }
        if pr % 25 == 0 { class_bonus += 6.0; }
        if pr % 5 == 0 { class_bonus += 3.0; }
        // Dead-space penalty: tiny unusable slivers
        if pr < 10 { class_bonus -= 30.0; }
        else if pr < 20 { class_bonus -= 10.0; }
    } else {
        // Perfect fit is ideal
        class_bonus -= 60.0;
    }

    // Reward if the next item fits exactly into the post-residual (pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            class_bonus -= 45.0;
        } else if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            class_bonus -= 15.0;
        } else if next_item_size > pr {
            class_bonus += 5.0;
        }
    }

    // Last-chance bin: strongly prefer filling it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        class_bonus -= 25.0;
    }

    // Tightness reward: proportional waste relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 20.0;

    // New-bin candidate: only attractive when current bin would leave a
    // badly-shaped residual and many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins mildly; scale with open bins count.
        score += 55.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size >= 60 { score -= 20.0; }
    }

    // Mean-residual coupling: when average residual is small, preserve
    // well-fitting bins (they are scarce).
    if mean_residual < 30.0 && !is_new_bin && pr >= 10 {
        score -= 8.0;
    }

    score -= class_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: tiny leftover gaps are likely unusable.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): reward leaving room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // Penalize if next item would be blocked by this placement's dead space.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proliferation with open_bins_count pressure.
        score += 5.0 + open_bins_count as f64 * 1.5;
        // But if existing bins carry large mean residual (poor fits), opening fresh is fine.
        let waste = mean_residual - post_residual as f64;
        if waste > 0.0 {
            score -= waste * 0.2;
        }
    } else {
        // Mild pressure: with many open bins, slightly prefer filling existing ones.
        score += open_bins_count as f64 * 0.05;
        // Prefer using bins with smaller residual (tighter bins first).
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Late-stream consolidation: as the stream progresses, avoid leaving many half-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Chain fit: leftover usable by next item -> big reward scaled by tightness.
            let tightness = nxt / (post_residual as f64);
            score -= 40.0 + 60.0 * tightness;
        } else {
            // Dead space relative to next item: penalize unusable gap.
            let gap = nxt - post_residual as f64;
            score += 0.5 * gap;
        }
        // Bonus if the next item exactly fills the post residual.
        if next_item_size == post_residual {
            score -= 150.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor relative to mean).
    let resid_f = post_residual as f64;
    score += 0.3 * (resid_f - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - resid_f).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Early in the stream, be more willing to open fresh bins for good structure;
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only for large items or when no open bin fits well.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += 60.0 - large_item_bonus + 40.0 * progress;
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 50.0; // fresh bin can chain the next item too
        }
    }

    // Mild penalty for leaving highly fragmented residuals (hard-to-fill slivers).
    if resid_f > 0.0 && resid_f < 10.0 {
        score += 25.0 * (10.0 - resid_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual is already favored by the base term.
    // Penalize large dead space that can never be used again.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny leftover is nearly a perfect fit
    } else if post_residual >= 10 {
        // leftover still usable by typical item sizes: mild reward proportional to usability
        score += 0.5;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if the next item fits into post_residual,
    // reward this placement (good chaining); otherwise penalize slightly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
            // extra penalty if next item is large and would open a new bin anyway
            if next_item_size > bin_capacity / 2 {
                score += 2.0;
            }
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    score -= 0.05 * open_bins_count as f64;

    // Mean residual coupling: if this bin is far below mean residual,
    // it is a "straggler" bin — prefer to fill it down.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev; // negative dev (bin has less space than mean) lowers score

    // Early stream: slightly favor opening new bins to build diversity;
    // late stream: strongly favor filling existing bins.
    score += 10.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;
    score -= 5.0 * progress;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with smooth non-linear shaping
    let mut score = norm_pr.powf(1.6);

    // Polynomial coupling of post_residual with stream progress:
    // dead space matters more late in the stream
    let coupling = (norm_pr - progress).powi(2);
    score += 0.35 * coupling * (0.5 + progress);

    // Reward filling bins almost exactly
    let fill = 1.0 - norm_pr;
    score -= 0.4 * fill * fill;

    // Penalize leaving residual that no plausible item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 0.5 * ((nxt - pr) / cap);
        } else {
            score -= 0.3 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Mild pressure against proliferating bins when mean residual is high
    score += 0.1 * (open_bins_count as f64) * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: only attractive early or when residual would be tiny waste
    if bin_residual == bin_capacity {
        score = pr + 0.8 - 0.6 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class (multiples of 10) are preferred.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0 // reusable class
    } else if pr % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward dead space
    };
    score += harmonic_bonus;

    // Dead-space penalty: tiny leftovers (1..=5) are nearly unusable.
    if pr > 0 && pr < 6 {
        score += 18.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 8.0;
            // harmonic coupling: next item leaves a multiple-of-10 residue too
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0; // next item can't use this residue
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.05 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin should win only when no open bin
    // offers a good (harmonic) fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.35 * cap + 10.0 * (1.0 - progress);
        // empty bin has perfect "harmonic" residual; make it competitive only
        // if open bins are fragmented
        if mean_residual > 40.0 {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Mild preference for tighter (smaller-residual) bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (cap - bin_residual as f64) * 0.05;

    // Penalize bins far from the mean residual (fragmentation control).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are perfect, but small gaps that can't host typical future items are poison.
    // Penalize post_residual in the "unusable" band harshly.
    if post_residual > 0 {
        // dead space ratio relative to capacity
        let dead = post_residual as f64 / bin_capacity as f64;
        // Non-linear penalty: quadratic in dead space, amplified for tiny gaps
        score += 40.0 * dead * dead;
        if post_residual < 10 {
            score += 25.0; // near-wasted gap
        } else if post_residual <= 20 {
            score += 12.0; // likely dead space
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (a new empty bin candidate has bin_residual == bin_capacity and gets
    // penalized via post_residual == capacity, but add explicit pressure).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with number of open bins
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Early in stream, new bins are cheaper; late in stream they are costly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        // If no open bin fits at all, new bin is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Reward using existing bins more when many are open
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but not perfectly: mild reward scaled by fit quality
        let next_fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * next_fill;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't use the gap: penalize leaving it
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below mean residual = tighter bin = better choice)
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 0.5 {
            score -= 60.0; // perfect chain: this placement sets up the next item exactly
        } else if next <= post_residual as f64 {
            // next item fits, but how tightly? reward tight leftover after the chain
            let chain_left = post_residual as f64 - next;
            score -= 30.0 * (1.0 - chain_left / bin_capacity as f64);
            score += 0.15 * chain_left;
        } else {
            // next item won't fit here; penalize large post_residual that becomes dead space
            score += 0.25 * (post_residual as f64 - next).min(50.0);
        }
    }

    // Compare post_residual against mean residual across open bins.
    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.4 * (post_residual as f64 - mean).max(0.0);
    score -= 0.2 * (mean - post_residual as f64).max(0.0);

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += 0.1 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
        // Wasted residual relative to capacity.
        score += 0.15 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving large but unusable-for-next residual.
            score += 8.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more conservative (prefer filling existing bins);
    // later, allow more freedom to open bins for good structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_frac;

    // Global state: many open bins with high mean residual -> encourage consolidation into existing bins.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        if bin_residual as f64 >= mean_residual {
            score += 5.0 * (pressure - 0.5).max(0.0);
        }
    }

    // New-bin candidate: only attractive when current residual is a poor fit or no open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is chosen only when clearly better.
        score += 35.0;
        // If next item is large and won't combine well, opening fresh may help.
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in stream with many open bins, prefer consolidation over new bins.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear base: squared normalized post-residual wastage
    let waste = post_residual as f64 / cap;
    score += 40.0 * waste * waste * cap * 0.01;

    // Polynomial coupling of post_residual with progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late in the stream, penalize leftover space more strongly.
    let coupling = (post_residual as f64) * (post_residual as f64) / cap
        * (0.5 + 1.5 * progress * progress);
    score -= 0.0; // placeholder no-op to keep sign discipline explicit
    score += 0.35 * coupling;

    // Reward near-perfect fits via smooth saturating term (avoid hard thresholds)
    let tightness = 1.0 - waste;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead: penalize if next item no longer fits the post-residual
    // (smooth quadratic in the shortfall), reward if it fits snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let shortfall = nxt - post_residual as f64;
        if shortfall > 0.0 {
            let f = shortfall / cap;
            score += 18.0 * f * f * cap * 0.1;
        } else {
            let snug = (-shortfall) / cap;
            score -= 6.0 * (1.0 - snug) * (1.0 - snug);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, discourage opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // When many bins are open, mildly discourage scattering; when few, keep flexibility
    let openness = open_bins_count as f64;
    score += 0.02 * openness * (1.0 - progress);

    // Deviation of this bin's residual from the mean residual: prefer bins whose
    // residual is close to what the item consumes (smooth quadratic alignment)
    let align = (bin_residual as f64 - item_size as f64 - mean_residual) / cap;
    score += 5.0 * align * align;

    // New-bin candidate: neutral-ish baseline; only attractive when all open bins
    // would leave large dead space (smooth interaction with progress)
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * cap * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (large enough for typical small items), penalize dead zones.
    let pr = post_residual;
    let half = bin_capacity / 2;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score += 45.0; // tiny dead space
    } else if pr <= half {
        // small residual: mildly penalize unless next item fits
        if next_item_size > 0 && next_item_size <= pr {
            score -= 25.0;
        } else {
            score += 10.0;
        }
    } else {
        // large residual: generally good
        score -= 20.0;
        if next_item_size > 0 && next_item_size <= pr {
            score -= 15.0;
        }
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes
    // (10/20/25) leave re-usable gaps.
    if pr % 10 == 0 && pr > 0 { score -= 8.0; }
    if pr % 25 == 0 && pr > 0 { score -= 6.0; }
    if pr % 20 == 0 && pr > 0 { score -= 4.0; }

    // Integer-division thresholds: residual class by fifths of capacity.
    let fifth = bin_capacity / 5;
    let class = pr / fifth.max(1);
    score += match class {
        0 => 30.0,
        1 => 12.0,
        2 => 0.0,
        3 => -10.0,
        _ => -18.0,
    };

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or stream is early (build up bins when few are open).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual > 0 && post_residual < 10;
        let early = progress < 0.15 || open_bins_count < 2;
        if bad_fit {
            score -= 20.0;
        } else if early {
            score -= 5.0;
        } else {
            score += 55.0;
        }
        // lookahead: if next item is huge, a fresh bin is valuable
        if next_item_size > 0 && next_item_size as f64 > 0.7 * cap {
            score -= 30.0;
        }
    }

    // Coupling with mean residual: prefer bins tighter than the mean.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Slight preference for filling bins later in the stream.
    score -= 0.5 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: small post-residuals that can't fit typical items are useless.
    if post_residual > 0 {
        let unusable = post_residual < 10; // nothing smaller than min item can go in
        if unusable {
            score += 40.0 + 30.0 * progress;
        } else if post_residual < item_size {
            // gap smaller than current item: partially dead
            score += 0.5 * (item_size - post_residual) as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new one is cheaper.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate handling: neutral-ish baseline, but attractive when
    // existing residuals are large and fragmented.
    if bin_residual == bin_capacity {
        let base = 55.0 + 25.0 * progress;
        score = base
            + (mean_residual - post_residual as f64).abs() * 0.1
            - if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        // If next item fits nicely into the fresh bin's expected residual, slight bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Lookahead coupling: prefer leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 18.0 * match_quality;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted lookahead potential
        score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Relative residual coupling: prefer bins whose residual deviates favorably from mean
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.6 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless lookahead/fit is bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item is large and current item small, opening fresh bin can be OK
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize creating tiny dead space that nothing can use later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Penalize unusable dead space: residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many open bins
    // already have room, less when the stream is early (future items need bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 20.0; // next item could fill existing space; don't open new bin
        }
    }

    // Lookahead coupling: if the next item exactly matches post_residual,
    // this placement is perfect — reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item fits in post_residual, mildly reward keeping room.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item is large and this bin is nearly empty, keep big bins free.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 25 {
        score += 10.0;
    }

    // Global state: prefer filling bins when many bins are open (bin-count pressure).
    score -= (open_bins_count as f64).sqrt() * (1.0 - tightness) * 5.0;

    // Prefer bins whose residual deviates below the mean (consolidate space).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in stream, be pickier about waste; late, just fit.
    score += tightness * 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits: quadratic in fill ratio, stronger as stream progresses.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 22.0 * fill.powi(2) * (0.6 + 0.6 * progress);

    // Penalize small but nonzero post-residual (dead space), smooth coupling with progress.
    let dead = post / cap;
    if post > 0.0 {
        score += 18.0 * (1.0 - dead).powi(2) * dead * (0.5 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - gap / cap) * (0.7 + 0.5 * progress);
        } else {
            score += 6.0 * (1.0 - gap / cap);
        }
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // scaled by how fragmented open bins are.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        let n_open = (open_bins_count as f64).ln().max(0.0);
        score += 30.0 + 25.0 * frag + 8.0 * n_open * (1.0 - progress);
    } else {
        // Prefer bins whose residual is close to the item (best-fit smoothing).
        let diff = (bin_residual as f64 - item_size as f64) / cap;
        score += 8.0 * diff * (0.5 + 0.5 * progress);
    }

    // Mild preference for bins below mean residual (consolidate large holes).
    score += 3.0 * ((post - mean_residual) / cap).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space that cannot host
    // small items (classes below 10) is worthless in the classic regime,
    // but with unknown 1..100 sizes we grade it continuously.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Fractional class of post_residual relative to capacity (harmonic bands)
    let frac = post_f / cap_f; // in [0, 1]
    // Penalize "awkward" residuals: those just below half capacity waste the most
    let awkward = (frac - 0.5).abs();
    score += 12.0 * awkward;

    // Integer-division thresholds on post_residual (harmonic classes of size 10)
    let class = post_residual / 10;
    match class {
        0 => score += 30.0,          // unusable sliver
        1 => score += 18.0,          // very poor
        2 => score += 8.0,           // mediocre
        3 => score -= 6.0,           // can host a mid item
        _ => score -= 10.0,          // roomy residual, good
    }

    // Reward tight fits (small post_residual) strongly
    score -= 20.0 * (-post_f / 15.0).exp();

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: better if residual is well-used
            score -= 15.0 * (next_item_size as f64 / post_f.max(1.0));
        } else {
            // next item will NOT fit here: penalize more when residual was large
            score += 6.0 + 0.05 * post_f;
        }
    }

    // Last-chance bonus: sole fitting bin avoids opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this placement
    // would be terrible and open bins are numerous
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual / cap_f).max(0.05);
        let bad_here = if post_residual < 15 { 1.0 } else { 0.0 };
        score = 40.0 - 10.0 * bad_here - 5.0 * progress + 0.5 * pressure.min(10.0);
        // make new bin strictly worse than any decent existing placement
        score += 15.0;
    }

    // Mild preference to spread load when many bins are open and residuals are high
    score += 0.02 * (post_f - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are "dead".
    // Treat residual <= 10 (or < next item) as wasted space -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 20.0; // near-perfect, effectively dead space (good)
    } else {
        // Dead space: gap that no item can likely use
        score += (post_residual as f64) * 0.15;
        if post_residual < next_item_size && next_item_size > 0 {
            // gap unusable by the next arriving item -> extra dead-space penalty
            score += (post_residual as f64) * 0.35;
        }
    }

    // Reward exact or near-exact matches with next item (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 12.0 - gap; // leaves room exactly for the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, prefer tighter fills
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Prefer bins whose residual deviates below the mean (tighter bins first)
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.10;

    // New-bin candidate: only attractive when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && (bin_capacity as f64 - mean_residual) >= item_size as f64 * 0.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        } else if post_residual > 60 {
            // opening fresh bin only if all fits would leave large dead space
            score -= 5.0;
        } else {
            score += 25.0; // keep using open bins when fit is reasonable
        }
        let _ = decent_fit_exists;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when next item exactly fills the post-residual (perfect 2-step match)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 200.0;
        } else {
            // penalize mismatch, scaled by how large the leftover would be after next item
            let after_next = post_residual as i64 - next_item_size as i64;
            if after_next >= 0 {
                score += after_next as f64 * 0.9;
            } else {
                score += (-after_next) as f64 * 0.35;
            }
        }
    }

    // Reward tight fits (small post_residual)
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins already "broken in" (low residual relative to mean)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Penalize creating tiny dead space (< 10 unusable for items >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Early stream: be more conservative, prefer reusing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Many open bins: discourage opening new ones implicitly via new-bin candidate competition
    if bin_residual == bin_capacity {
        // brand-new bin candidate: penalize unless lookahead suggests perfect pairing
        let mut penalty = 12.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            penalty -= 8.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively at small residuals.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity - post_residual {
        // unreachable but kept safe
    } else if next_item_size > 0 {
        // Next item won't chain here; mild penalty scaled by how much it misses.
        let miss = (next_item_size.saturating_sub(post_residual)) as f64;
        score += miss * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins with high mean residual: prefer reusing existing space.
    if open_bins_count > 0 {
        let spread = mean_residual - (post_residual as f64);
        score += spread * 0.1;
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Time horizon: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, more so late in stream.
        score += 35.0 + 30.0 * progress;
        // But if item is huge and mean residual is small, opening new bin is fine.
        score -= (item_size as f64) * 0.2;
        if (mean_residual < item_size as f64) && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight discount late in stream.
        score -= progress * 5.0;
    }

    // Prefer bins whose residual is close to item size (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let t = progress;
    let coupling = norm_post * norm_post * (1.0 + 2.0 * t) - norm_post * (0.5 + t * t);
    score += 20.0 * coupling;

    // Perfect-fit reward, stronger late in the stream (smooth quadratic in progress).
    if post_residual == 0 {
        score -= 15.0 + 25.0 * t * t;
    }

    // Lookahead: reward residual that can host the next item, penalize near-miss dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else if post_residual > 0 && post_residual < (nxt as u32).min(10) {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // with penalty decaying as mean residual across open bins shrinks.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * mean_residual - 10.0 * t;
    }

    // Slight preference for tighter existing bins via residual-mean deviation.
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fraction classes of size 10
    let class = post_residual / 10;
    // Reward (subtract) tighter fits; dead space below 10 is unusable for min item size 1..100
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // dead space penalty
    } else {
        // prefer residual that matches coarse harmonic classes (small classes better)
        score -= (10 - class.min(10)) as f64 * 4.0;
    }

    // Exact-fit reward scaled by how tight the fit is
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Lookahead: penalize if next item cannot fit into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally, but only for moderately small next items
            score -= (post_residual - next_item_size) as f64 * 0.3;
            score -= 8.0;
        } else {
            // next item won't fit here: penalize more if this bin was the only fitting one
            score += 12.0 + if fitting_bins_count == 1 { 18.0 } else { 0.0 };
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are quite full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bins_pressure = mean_residual / bin_capacity as f64;
        // open new bin only if mean residual across open bins is low (bins nearly full)
        score += 30.0 + 40.0 * bins_pressure - 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild penalty for proliferating open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual in 1..=10 is waste)
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as f64) * 25.0;
    }

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // If next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 - gap * 0.5;
    }

    // Penalize leaving a gap that the next item cannot use at all
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: more open bins -> favor filling existing ones over new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins are open or stream is late
        score += open_bins_count as f64 * 5.0 + progress * 20.0;
        // But attractive if no open bin fits well (large mean residual mismatch)
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        score -= 5.0;
    }

    // Mild preference for bins below mean residual (balance loads)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact match leaves a completely full bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: mild reward proportional to how snugly.
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space, worse when large.
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize large unusable residual relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // tiny slivers are effectively full bins
    } else if post_residual >= 10 {
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins with residual below mean
    // (keeps large residuals available for large future items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Discourage opening a new bin when open bins exist that fit reasonably,
    // especially early/mid stream.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * (1.0 - progress);
    }

    // Mild preference for fewer open bins when near end of stream.
    if total_items > 0 && step_index + 1 >= total_items.saturating_sub(5) {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the next item exactly fits the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64 / bin_capacity as f64) * 12.0;
        } else {
            // Next item won't fit here; penalize wasting space if it's large dead space.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Penalize opening a new bin when open bins with reasonable residual exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_penalty = 25.0 + 20.0 * (1.0 - progress) + mean_residual * 0.3;
        score += new_bin_penalty;
        // But allow new bin if mean residual is low (open bins are nearly full).
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        // Slight preference for bins with residual close to item (perfect packing).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += fit_gap * 0.1;

        // Prefer bins whose residual is below half-capacity (hard-to-fill space gets used).
        if bin_residual < bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild global pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: post residual, with smooth non-linear decay for tiny residuals (dead space)
    let mut score = pr * (1.0 - 0.35 * fill * fill);

    // Smooth quadratic coupling of residual with stream progress:
    // late in the stream, tight fits matter more (prefer small post_residual)
    let tightness = (pr / cap).powi(2);
    score += tightness * (0.5 + 2.5 * progress) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: if next item fits smoothly in post_residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack).powi(2);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for deviating from mean residual (keeps bin pool balanced)
    score += 0.05 * (pr - mean_residual).abs();

    // Slight pressure against opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * open_bins_count as f64;
        // but late in stream, new bin can be fine for big items
        score -= 3.0 * progress * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 as a "dead space class"
    let post_mod = post_residual % 10;
    score += (post_mod as f64) * 0.9;

    // Penalize residuals that are too small to host any plausible item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect packing (harmonic class 0)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Integer-division threshold: post_residual bucketed by capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > half {
        score -= 12.0;
    } else if post_residual > quarter {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: does post_residual fit next item? Harmonic pairing bonus/penalty
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // how harmonically aligned is the leftover after the next item?
            let next_post = post_residual - next_item_size;
            score -= 8.0;
            score += (next_post % 10) as f64 * 0.5;
            if next_post == 0 {
                score -= 15.0;
            }
        } else {
            // leftover cannot host next item: penalize proportional to waste
            score += (next_item_size as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        if fitting_bins_count == 0 || mean_residual < (item_size as f64) * 0.5 {
            score -= 20.0 + pressure * 0.5;
        } else {
            score += 25.0 + pressure;
        }
    }

    // Early stream: be slightly conservative, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Tight-fit reward: item nearly fills the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio < 0.2 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        // Dead space is a gap too small for the smallest plausible item.
        let min_item = 1u32;
        if post_residual < 10 {
            score += 200.0; // unusable sliver -> strongly avoid
        } else {
            // Nonlinear penalty: small remaining gaps are worse than large ones.
            let r = post_residual as f64;
            score += 40.0 * (1.0 - (r / bin_capacity as f64)).powi(3);
        }
        let _ = min_item;
    } else {
        // Perfect fill: big reward.
        score -= 150.0;
    }

    // Reward exact/near-exact fits relative to the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        // This bin can still host the next item: mild reward, scaled by tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap blocks the next item: penalize proportionally.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via open_bins_count term).
    score += (open_bins_count as f64).sqrt() * 8.0;

    // Prefer bins tighter than the mean residual (good consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Early in the stream, be slightly more willing to open bins (future flexibility);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match bonus: post residual equals next item size (perfect 2-step fill).
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                // Partial credit for a decent second-step fit.
                let fit_ratio = next_item_size as f64 / post_residual as f64;
                score -= 40.0 * fit_ratio;
            }
        } else {
            // Next item cannot fit here; penalize dead space more strongly.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post residual relative to mean residual of open bins.
    let mr = mean_residual;
    if mr > 0.0 {
        let rel = post_residual as f64 / mr;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel); // tighter than average: good
        } else {
            score += 5.0 * (rel - 1.0); // looser than average: mild penalty
        }
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit (empty-bin candidate).
    if bin_residual == bin_capacity {
        score += 35.0;
        // But allow new bin if next item is large and would waste this bin's space.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Early in stream: slightly prefer keeping bins compact.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more than linearly.
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use (items >= 1, realistically >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins => less scarcity, mild penalty for wasting a big residual.
    if fitting_bins_count > 1 {
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
        } else {
            // Next item won't fit here; penalize leaving a medium gap.
            score += 5.0;
        }
    }

    // Empty (new-bin) candidate: penalize opening a new bin unless the item
    // is large or the current bin fit is poor.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score += 15.0 / scarcity;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, prefer packing into existing bins more strongly.
        score += 10.0 * (1.0 - progress);
        if item_size >= 70 {
            score -= 12.0; // large items open fresh bins more acceptably
        }
        if item_size <= 30 {
            score += 10.0; // small items should go into existing slack
        }
    }

    // Global state coupling: high mean residual means slack exists; reward
    // consuming bins with residual above the mean.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Prefer bins with more open bins competing (spread load mildly).
    score -= 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Time-horizon modulation: early stream, be picky about waste.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: late in stream, dead space matters more
    score += 25.0 * progress * norm_pr * norm_pr;

    // Perfect-fit reward (smooth polynomial term)
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 + 10.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent fits exist
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr).abs();
        score += 50.0 + 10.0 * open_bins_count as f64 + 20.0 * (1.0 - progress) - 5.0 * mean_gap / cap;
    }

    // Mild preference for tighter bins relative to current mean residual
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is best.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Harmonic class penalty: dead space in small residue classes is more usable.
        let pr = post_residual;
        let class = pr % 10;
        score += class as f64 * 1.5;
        // Large dead space (unusable for typical items) is heavily penalized.
        if pr > 50 {
            score += (pr - 50) as f64 * 2.0;
        }
        // Exact fractional thresholds of capacity.
        let frac = pr as f64 / bin_capacity as f64;
        if frac < 0.1 { score -= 20.0; }
        else if frac > 0.5 { score += 30.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // Cheaper to open a new bin early in the stream (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size > post_residual.max(1) {
            score -= 15.0;
        }
        // If many open bins already, discourage proliferation.
        score += open_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        if rem == 0 {
            score -= 60.0;
        } else if rem <= 10 {
            score -= 25.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use this residue: penalize leaving medium dead space.
        score += 10.0;
    }

    // Slight preference for fuller bins relative to fleet mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit reward
        score -= 30.0;
    }

    // Reward placements where post_residual can still fit the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that cannot serve the next item
        score += 6.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        // Mild reward for filling existing bins
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates from mean (consolidate space)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post_residual is better, but dead space below
    // the minimum item size is worthless. Penalize unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // tiny dead space penalty
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual as i64 >= next_item_size as i64 {
            let waste = post_residual as f64 - nxt;
            score -= (20.0 * (1.0 - waste / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit here; mild penalty scaled by gap
            let gap = nxt - post_residual as f64;
            score += (gap * 0.5).min(25.0);
        }
    }

    // Relative-to-mean residual coupling: prefer bins that are tighter than average
    // (fill nearly-full bins first, keep loose bins for future awkward items).
    let dev = (post_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 30.0 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when item is large relative
    // to capacity or no good existing fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // A fresh bin is good for big items, bad for small ones (wastes capacity).
        score = 100.0 * (1.0 - fill_ratio) - 20.0 * fill_ratio;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large item likely followed by another large one
        }
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for fewer open bins when many are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;
    } else if post_residual == 0 {
        // Perfect fit is excellent.
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Post-residual can't hold next item: mild penalty scaled by waste.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // If next item would fit better elsewhere, don't over-commit here.
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bonus: only one fitting bin; avoid opening a new bin if fit is decent.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 * 0.5 {
        score -= 20.0;
    } else if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Prefer fuller bins relative to the average residual of open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Penalize spreading across many open bins when mean residual is low (fragmentation risk).
    if open_bins_count > 3 && (bin_residual as f64) < mean_residual {
        score += 6.0;
    }

    // Time horizon: late in the stream, be more conservative about wasting space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // New-bin candidate handling: an empty bin should only win when the current fit
    // is poor (large post_residual) or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Cheaper to open a new bin early when many items remain.
        score -= (1.0 - progress) * 40.0;
        // If the item would leave a very awkward residual in any existing bin,
        // a fresh bin is attractive.
        if post_residual < 15 && post_residual > 0 {
            score -= 25.0;
        }
        // Large items relative to capacity prefer fresh bins.
        if (item_size as f64 / bin_capacity as f64) > 0.7 {
            score -= 20.0;
        }
        // If only one bin fits and it's a tight squeeze, new bin is competitive.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let next = next_item_size as f64;

    // Base: reward tight fits (small post_residual), with a quadratic penalty
    // on very small residuals (unusable dead space) — smooth U-shaped coupling.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = x * x * (3.0 - 2.0 * x) * cap; // smoothstep-shaped base on residual

    // Dead-space penalty grows quadratically as residual shrinks below usable size.
    score += 12.0 * (1.0 - x) * (1.0 - x) * (item_size as f64 / cap);

    // Lookahead coupling: if the next item fits the post residual, reward strongly;
    // smooth interaction with stream progress (early stream favors chaining).
    if next > 0.0 && next <= post {
        let chain = 1.0 - (post - next) / cap;
        score -= 10.0 * chain * (1.0 - 0.5 * progress);
    } else if next > post {
        // Next item won't fit here: penalize proportionally to how badly it misses.
        score += 4.0 * ((next - post) / cap) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.3 * progress);
    }

    // Mean-residual coupling: placing into a bin below mean residual helps balance.
    score += 2.0 * (post - mean_residual) / cap;

    // New-bin candidate: empty bin gets a smooth handicap that relaxes late in the
    // stream (when consolidation matters more) and with many open bins.
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.4 * progress) * (1.0 + open_bins_count as f64 / 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small" classes
    // (post_residual < 10) have nearly no dead space -> reward strongly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 25.0 + (post_residual as f64) * 0.5;
    } else {
        // dead-space penalty grows for unusable leftovers
        let dead = post_residual as f64;
        score += 0.15 * dead;
    }

    // Harmonic classes: leftover in multiples of 10 pairs well with typical item sizes
    let class = post_residual % 10;
    score += class as f64 * 1.2; // prefer round leftovers (class 0)

    // Integer-division thresholds: can a small follow-up item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // this bin can host the lookahead item too -> reward chaining
            score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 8.0 + 0.2 * post_residual as f64;
        }
        // exact chain: leftover equals next item exactly
        if post_residual == next_item_size && post_residual > 0 {
            score -= 18.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins (low residual) among fitting bins
    score += 0.3 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: opening a fresh bin should only win when current bins are bad fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // if few bins fit the item, opening new bin is attractive
        score -= (fitting_bins_count as f64) * 10.0;
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // if item fits snugly in an open bin (post_residual small), discourage new bin
        if post_residual < 15 {
            score += 40.0;
        }
    }

    // Mean-residual coupling: when open bins are already quite full on average,
    // filling this bin further is valuable.
    if (mean_residual as u32) < 30 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Mild open-bin pressure: many open bins -> favor compacting into existing bins
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual that can still hold a typical item.
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 10.0;
    }

    // Open-bin pressure: prefer spreading across fewer bins early,
    // but allow more bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 - 0.3 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference toward bins tighter than the mean residual (better fit).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let slack = pr - nr;
            // Perfect chain fit: post_residual == next_item_size
            if slack == 0.0 {
                score -= 30.0;
            } else {
                // Reward proportionally, decayed by how wasteful the leftover is.
                let chain = 1.0 - slack / (bin_capacity as f64);
                score -= 12.0 * chain;
            }
        } else {
            // Post-residual too small for next item: dead space penalty.
            score += 0.6 * (nr - pr);
        }
    } else {
        // Last item: pure tight-fit greedy.
        score -= 10.0 * tightness;
    }

    // Compare against mean residual: prefer filling bins that are emptier than average
    // only when the fit is good; penalize dumping into already-scattered bins.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) / (bin_capacity as f64);
        // Base handicap so open bins are preferred unless fit is poor.
        score += 14.0;
        // Large items and early stream favor opening fresh bins.
        score -= 20.0 * large_item * large_item;
        score -= 6.0 * (1.0 - progress);
        // If next item chains perfectly into a fresh bin after this one, boost new bin.
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 8.0;
        }
        // Many open bins with low mean residual => prefer existing bins.
        score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Penalize leaving residuals in the "unusable" band (1..10) where typical small items still waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (perfect fit => big bonus).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score -= 40.0 / (post_residual as f64 + 1.0);
    }

    // Penalize creating dead space that cannot hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: opening a new bin is a fallback; make it
    // attractive only when existing bins would waste a lot of space.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If the item is large relative to residual space in existing bins,
        // opening a new bin becomes more reasonable.
        let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
        score -= tightness * 20.0;
        // Later in the stream, slightly discourage proliferation of bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // If many bins are open and mean residual is high, prefer reusing bins.
        score += (open_bins_count as f64).ln().max(0.0) * 4.0 + mean_residual * 0.05;
    } else {
        // Reward using already-open bins, more so when mean residual is high.
        score -= mean_residual * 0.03;
    }

    // Mild preference for bins with smaller residuals among equals (best fit).
    score += (bin_residual as f64 - item_size as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.35 * progress) - 1.7 * (norm_post * (1.0 - norm_post)) * cap * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 12.0 * (0.4 + progress);

    // Penalize dead space: small but nonzero post-residual
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 + 4.0 * progress;
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Mild dispersion penalty: prefer bins near mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate handling: make fresh bins attractive early, costly late
    if bin_residual == bin_capacity {
        score = cap * (0.55 - 0.45 * progress) + 5.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors
    let r = post_residual;
    let class3 = r % 3;
    let class5 = r % 5;
    let class10 = r % 10;

    // Dead-space penalty: residuals that are awkward (small but nonzero)
    if r > 0 && r < 10 {
        score += 40.0; // nearly unusable sliver
    }
    // Harmonic bonus for residuals in "nice" classes (divisible by 5/10)
    if class10 == 0 && r > 0 {
        score -= 8.0;
    } else if class5 == 0 {
        score -= 4.0;
    } else {
        score += class3 as f64 * 1.5;
    }

    // Lookahead: reward if next item fits exactly or well in post_residual
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0; // perfect chained fit
        } else if next_item_size < r {
            let gap = r - next_item_size;
            score -= 12.0 - (gap as f64).min(12.0);
            if gap < 10 {
                score += 6.0; // leaves another sliver
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep neutral-to-slightly-high unless residuals are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin early or when open bins are fragmented
        score = 45.0 + 25.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.0;
        }
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 10.0; // open bins too fragmented, fresh bin is good
        }
    }

    // Mild preference to fill tighter bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that few items can fill.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else if post_residual < 20 { 1.5 } else { 0.0 };
        score += dead * (post_residual as f64);
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins / prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: make it costly unless residual would be perfect.
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * fill_ratio;
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 5.0; // big next item: fresh bin may be good
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Prefer bins below mean residual (keeps residuals balanced).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted space quadratically (dead space is doubly bad).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward near-perfect match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead fit (post_residual == next_item_size) gets a big bonus.
        if gap == 0.0 {
            score -= 40.0;
        } else {
            // Reward closeness of lookahead fit, scaled by item size.
            score += gap * 0.35 - (next_item_size as f64) * 0.10;
        }
        // If next item cannot fit here at all, penalize leaving residual that
        // is smaller than next_item_size (fragmentation risk).
        if (post_residual as u32) < next_item_size {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit, no lookahead concerns.
        score -= 5.0;
    }

    // Relative to mean residual: placing into a bin with residual far below the mean
    // (i.e., a nearly full bin) is good — reward that.
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to the mean residual of open bins (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = (item_size as f64) > mean_residual * 0.9;
        if poor_fit_elsewhere {
            score -= 15.0;
        } else {
            score += 25.0;
        }
        // Late in the stream, opening fresh bins is more acceptable (less time to waste them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    // Mild penalty per open bin to encourage consolidation when scores are close.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that no future item can plausibly use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 {
        // Small residuals are only valuable if a small item may come; sizes >= 1, so
        // residual < 10 is nearly dead space for streams with min size 10.
        if post_residual < 10 {
            score += 25.0;
        }
        // Waste relative to capacity, scaled up over time.
        score += (post_residual as f64 / bin_capacity as f64) * (20.0 + 40.0 * t);
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste; mild reward proportional to tightness
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; penalize leaving awkward gaps
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Prefer bins whose residual is below the mean (consolidate fullness),
    // but only mildly, to avoid collapsing diversity.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base reluctance grows with number of open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Large items in fresh bins are fine (they pair well with future small items).
        score -= 25.0 * item_frac;
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - t);
        // If next item is large too, a fresh bin can host both? no - fresh bin
        // takes current item; if next is small, fresh bin remains flexible.
        if next_item_size > 0 && next_item_size < 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: late in stream, penalize residual more strongly
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Dead-space penalty: residual too small to be useful for typical items
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0 * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item can fill the post-residual well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (gap / cap);
        }
    }

    // Slight penalty for spreading across many open bins vs mean residual
    score += 0.3 * (mean_residual - pr).abs();

    // Mild bonus for tight fits (small item_size relative to residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let r = (post_residual % 10) as f64;
    let q = (post_residual / 10) as f64;

    // Penalize dead space that cannot hold typical items (residual < 10 is pure waste)
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill reward
    } else {
        // fractional waste: residue class penalty, worst when r is small but nonzero
        score += r * 0.8;
        score -= q * 2.0;
    }

    // Lookahead: reward leaving room for the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            if rem < 10 { score += 20.0; } else { score -= rem as f64 * 0.3; }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    // Prefer tighter bins overall relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late-stream conservatism: consolidate into fewer bins as stream ends
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 5.0;

    // Modulo-class bonus: residuals in multiples of 10 (q*10) are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are unusable waste; penalize them super-linearly.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Penalize moderately small gaps that likely cannot fit typical future items.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open.
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: mildly favor bins with residuals close to the mean
    // (balanced packing), and add pressure proportional to open bin count.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.3 + open_bins_count as f64 * 0.2;

    // Late in the stream, be more tolerant of imperfect fits (fewer future items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fit (small post residual), but don't chase dead space below 10.
    let mut score = post;

    // Dead space penalty: unusable slivers are worse than moderate leftovers.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 3.0;
    }

    // 2-step lookahead: strong reward if the next item fits exactly into post residual.
    if next > 0.0 && next <= post {
        let slack = post - next;
        if slack == 0.0 {
            score -= 25.0; // perfect chain fit
        } else if slack < 10.0 {
            score -= 12.0; // near-perfect chain fit
        } else {
            score -= 6.0; // next item fits with room to spare
        }
    } else if next > 0.0 && next <= post + 10.0 {
        // next item nearly fits: mild penalty for blocking the chain
        score += 2.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post) * 0.5;

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer keeping open bins tight; open a new bin only if item is large
        // relative to mean residual (open bins are fragmented).
        let fragmentation = mean_residual / cap;
        if fragmentation > 0.5 && item_size as f64 > mean_residual * 0.8 {
            score -= 5.0;
        } else {
            score += 20.0;
        }
        // Early in the stream, opening fresh bins is cheap and flexible.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 8.0;
        }
    }

    // Slight penalty for leaving large open residual when many bins are open.
    score += post * (open_bins_count as f64 / (open_bins_count as f64 + 10.0)) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space that no realistic item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver (items >= 1 but typically larger)
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain bonus if next item leaves a small residual too
            let post2 = post_residual - next_item_size;
            if post2 < 15 {
                score -= 6.0;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here blocks next item from using this bin's full residual
            score += 8.0;
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; make it attractive only for large items
        // or when no open bin has a good fit.
        score = 100.0 - 2.0 * tightness;
        if item_size >= 60 {
            score -= 30.0; // big items are fine in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: must open
        }
        if mean_residual < item_size as f64 * 1.1 {
            score -= 20.0; // open bins are nearly full anyway
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, slightly prefer consolidating (leave big residuals usable);
    // late in stream, just fill tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Penalize placements far from the mean residual (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (small post residual) with quadratic shaping
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, prefer leaving moderately usable space (mild); late, strongly
    // penalize any residual since fewer chances remain to fill it.
    let poly = x * (1.0 - x) * (1.0 - progress); // hump-shaped usable-space term
    score -= 25.0 * poly;

    // Cubic dead-space penalty growing with progress
    score += 40.0 * x * x * x * progress;

    // Lookahead: if next item fits into the post residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to wasted potential
        score += 6.0 * x * (0.5 + progress);
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (item_size as f64 / cap);
    }

    // Mild penalty when this bin's residual deviates from mean residual
    // (encourages balanced residual distribution across open bins)
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Slight preference for filling already-open bins vs. opening new ones
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to host typical future
    // items (unknown distribution -> assume small items >= 1, but practically
    // gaps below ~15 are rarely reusable) are heavily penalized.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        // Quadratic penalty ramping up as the gap gets smaller.
        score += 60.0 * ((dead_threshold - post_residual + 1) as f64 / dead_threshold as f64).powi(2);
        // Extra penalty if the lookahead item cannot use this gap either.
        if next_item_size > post_residual {
            score += 25.0;
        }
    }

    // Perfect fit reward: filling the bin completely is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item would fit perfectly into the
    // post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Open-bin pressure: when many bins are already open, discourage opening
    // new ones (a new empty bin has bin_residual == bin_capacity and gains no
    // fit rewards, so adding pressure here biases consolidation).
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the mean residual (balanced
    // packing), mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Late in the stream, consolidate harder: penalize spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if nxt <= post {
            // next item fits: reward proximity to exact fill
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 400.0;
            }
        } else {
            // next item does not fit: penalize residual that is too small to be useful
            score += 0.5 * post * (post / bin_capacity as f64);
        }
    }

    // Penalize very small dead space (unusable waste), but only if next item can't use it
    if post_residual > 0 && post_residual < 10 && (next_item_size > post_residual || next_item_size == 0) {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 300.0 + 200.0 * (1.0 - progress);
        // but if next item is huge and this item is small, opening may be fine
        if next_item_size > 0 && next_item_size >= 50 && item_size <= 30 {
            score -= 150.0;
        }
    }

    // Slight preference for fewer open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, big bonus
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }
    // If next item almost fits (small gap), mild bonus
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins have poor fit potential
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        score = 90.0 + avg_fit_gap * 0.5;
        // Early in stream, slightly prefer new bins (builds flexibility)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // Many open bins: penalize opening more
        score += open_bins_count as f64 * 2.0;
        // Next item large: new empty bin helps
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Prefer bins below mean residual (more crowded bins absorb items)
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Late in stream: pack tightly, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.9 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth penalty for tight fits that create dead space, weighted by progress
    let dead = norm_pr * norm_pr;
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Reward near-perfect fits (post_residual small) with cubic discount
    score -= 30.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack * slack);
        } else {
            // next item won't fit: penalize wasted residual quadratically
            score += 10.0 * norm_pr * (nxt / cap);
        }
    }

    // Last-chance bin bonus: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Many open bins: prefer consolidating into fuller bins (small residual)
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // New empty bin candidate: penalize mildly unless residual of others is tiny
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * mean_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score -= (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Harmonic class: post_residual mod 10 classes. Residuals that are
    // "usable" (large or exactly matching common sizes) are penalized less.
    let pr = post_residual;
    let class = pr % 10;
    let dead_penalty: f64 = match class {
        0 => -15.0,                       // clean multiples of 10 are reusable
        1 | 2 | 3 => 10.0,                // sliver dead space
        4 | 5 | 6 => 4.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division threshold: how many "average" items still fit?
    let avg_item = 55u32;
    let slots = pr / avg_item;
    score += slots as f64 * 8.0; // keeping big residual for future is good -> lower score

    // Coupling with next item: reward if next_item_size fits into post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // perfect chaining
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            score -= 25.0;
            // harmonic class of the double-chain leftover
            score += (nxt_post % 10) as f64 * 1.5;
        } else {
            score += 12.0; // next item cannot use this bin's leftover
        }
    } else {
        // last item: minimize waste directly
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins
    score += (open_bins_count as f64) * 1.2;

    // Mean residual coupling: if this bin's residual is far below mean, it's tight -> good
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate handling: empty bin gets a moderate penalty so we only
    // open when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // late in stream, opening new bins is relatively cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        // if next item is large, a fresh bin preserves flexibility
        if next_item_size >= 60 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no item (min size 10) can use are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Moderately small gaps are also risky if the lookahead item cannot use them.
    if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into fresh bins,
    // but reward consolidating into bins with large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);
    score -= 0.05 * mean_residual;

    // Lookahead synergy: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; dead space becomes permanent — mild penalty.
        score += 5.0 + post_residual as f64 * 0.3;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive only
    // when this placement would create bad dead space or when few bins are open early.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress.
        score += 20.0 + 40.0 * progress;
        if post_residual == 0 {
            score -= 30.0; // never happens for empty bin, but keeps symmetry
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild non-linear penalty
    // on very small dead space that is hard to reuse later.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.15) * 0.05;
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Aggressive 2-step lookahead: reward when the next item exactly matches
    // the post-residual of this bin (chain packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as u32 >= next_item_size {
            // Next item fits exactly after this placement -> strong reward.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would not fit here; penalize more the bigger the overshoot.
            score += 0.10 * gap;
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // "nearly full" -> good to fill them now (waste less space overall).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when the current fit is bad or the item is huge.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        let bad_fit = if post_residual > 0 { (10.0 / post_residual as f64).min(1.0) } else { 0.0 };
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 35.0 + 40.0 * fit_quality - 20.0 * bad_fit
            - 10.0 * pressure - 8.0 * progress
            - if item_size > 60 { 12.0 } else { 0.0 };
    }

    // Slight preference for filling older/crowded bin sets early in the stream.
    score -= 0.02 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tightness * (post_residual as f64);

    // Penalize bins that leave dead space too small for typical future items.
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 6.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: penalize wasted space.
        score += 0.10 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Discourage opening new bins when many bins are open with room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // New bin more attractive if mean residual across open bins is low.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * fit_gap;
        // Slight preference for bins below mean residual (consolidating emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Early stream: be a bit more willing to consolidate; late stream: keep tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial deepening over stream progress.
    let mut score = pr * (1.0 + 0.5 * progress) + 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post-residual) more strongly as stream advances.
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the lookahead item (smooth quadratic coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += 30.0 * waste * waste * (1.0 + progress);
        // Bonus if post-residual exactly accommodates next item (smooth bump).
        let fit_gap = (pr - nx).abs() / cap;
        score -= 20.0 * (-fit_gap * fit_gap * 50.0).exp() * (0.4 + 0.6 * progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0 * (1.0 - pr_norm) * (1.0 + 0.5 * progress);
    }

    // New-bin candidate: penalize smoothly, but relax penalty late in stream
    // and when the fit into existing bins is loose (large post-residual elsewhere).
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
        let looseness = ((mean_residual - item_size as f64).max(0.0)) / cap;
        score += (60.0 - 25.0 * progress) * openness * (1.0 - 0.5 * looseness.min(1.0));
        // Perfect-fit incentive for the new bin (item exactly fills a fresh bin).
        score -= 30.0 * (-((pr_norm - 0.0).abs()) * 10.0).exp() * (1.0 - pr_norm);
        // If item is large, a fresh bin wastes little; soften penalty quadratically.
        let size_norm = (item_size as f64) / cap;
        score -= 40.0 * size_norm * size_norm;
    }

    // Mild penalty for spreading across many bins when residuals are fragmented.
    let frag = (mean_residual - pr).abs() / cap;
    score += 10.0 * frag * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Best-fit baseline: tighter fit wins
    score -= 8.0 * (item_size as f64 / cap_f);

    // Harmonic class of post_residual: penalize dead space in awkward residue classes
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10;
        // Residuals in {1..9} are nearly unusable for items >=10
        if pr < 10 {
            score -= 50.0; // perfect closure, strongly reward
        } else {
            match cls {
                0 => score -= 12.0,            // round residual: highly reusable
                1 | 9 => score += 6.0,          // awkward class
                2 | 8 => score += 3.0,
                3 | 7 => score -= 1.0,
                _ => {}
            }
        }
    } else {
        score -= 60.0; // exact fill
    }

    // Integer division thresholds on post_residual
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half { score -= 5.0; }
    else if pr >= quarter { score += 1.0; }
    else { score += 4.0; } // small leftover: risky unless it closes the bin

    // Lookahead coupling: if next item fits the post residual, reward heavily
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + 10.0 * (next_item_size as f64 / cap_f);
        } else if pr > 0 && next_item_size > pr {
            // next item can't use this residual: penalize proportionally to waste
            score += 3.0 * (1.0 - pr as f64 / cap_f);
        }
        // Harmonic pairing: next item complements to a round number
        if (item_size + next_item_size) % 10 == 0 && (item_size + next_item_size) <= bin_residual {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 25.0 + 2.0 * pressure;
        // but if no open bin fits well (mean residual small relative to item), allow new bin
        if mean_residual < item_size as f64 * 1.2 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_residual as f64 / cap_f);

    // Mean residual alignment: prefer bins whose residual is close to item size (tight packing)
    let diff = (mean_residual - item_size as f64).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits proportionally to fill ratio (non-linear).
        let fill = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill * fill;
    }

    // Penalize wasting a bin on an item that leaves a gap the next item can't use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0; // next item fits here, good chaining
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean.
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.5 * (res - mean_residual);
    } else {
        score -= 0.5 * (mean_residual - res);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: acceptable early or when current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 60.0; // item small relative to bin
        if progress < 0.15 || poor_fit || fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 20.0; // late stream: prefer filling open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how well it fits
            let next_fit = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * (1.0 - next_fit);
        } else {
            // next item won't fit here: penalize leaving a gap smaller than next item
            score += 10.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Compare post_residual against mean residual: avoid making bin much emptier than average
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening new bins when decent fits exist (new bin has residual == capacity)
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        // But early in stream, opening bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual -> 0 (perfect-fit bonus).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins where the next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.4 * (next_item_size as f64);
        } else {
            // Penalize wasting residual when next item can't follow.
            score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when fits are poor or many bins are open.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - (post_residual as f64);
        let pressure = open_bins_count as f64 / ((total_items as f64).max(1.0));
        let poor_fit = (item_size as f64) / (bin_capacity as f64);
        score = 35.0 + avg_waste * 0.3 - poor_fit * 20.0 - pressure * 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Time horizon: early in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 10.0 * (1.0 - progress) * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_next = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * t) - norm_pr * (1.0 + t * t);
    score += 10.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + t) * 5.0;

    // Penalize wasting space relative to mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 + 0.5 * t);

    // Lookahead: reward post_residual that fits the next item smoothly
    if next_item_size > 0 {
        let fit_next = if norm_pr >= norm_next && norm_next > 0.0 { 1.0 - (norm_pr - norm_next).abs() } else { 0.0 };
        score -= 8.0 * fit_next * (1.0 - t);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 2.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "harmonic" with common item sizes (multiples of 10, 5) are reusable
    let harmonic_bonus = match class {
        0 => 12.0,
        5 => 6.0,
        _ => {
            // awkward residual: penalize more if small dead space
            if pr < 10 { 25.0 } else { 0.0 }
        }
    };
    score -= harmonic_bonus;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize leaving residual smaller than the minimum item size (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward bins whose residual is divisible into useful classes for next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // exact lookahead fit
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 15.0; // next item won't fit here
        }
        // modulo harmony: residual % next_item_size small means near-perfect packing
        if next_item_size > 0 && post_residual >= next_item_size {
            let r = post_residual % next_item_size;
            score -= (10 - r.min(10)) as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score = cap * 1.5 + crowding * 5.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= cap; // no alternative, opening is fine
        }
    }

    // Mild preference for tighter bins overall
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small-but-maybe-usable gaps: quadratic penalty.
        score += (25.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 40.0;

    // Open-bins pressure: penalize placements that keep many bins open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 3.0;

    // Mean residual coupling: if this bin's post-residual deviates badly
    // from the mean residual across open bins, penalize.
    score += (post_residual as f64 - mean_residual).abs() * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // (alternative is opening a new bin).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot fit in the leftover: mild penalty for creating a gap.
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly when decent open bins exist; add pressure
        // that scales with how well the item would fit elsewhere (unknown), so
        // only allow new bins to win when open bins would leave very small gaps.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // If no open bin fits (this call is the only candidate), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Early stream: be slightly more tolerant of spreading out to build a good pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) already favored.

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        // Perfect chain: item fits now, next item fills the remainder exactly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Next item fits in the remainder: good chaining.
        if post_residual >= next_item_size {
            let after_next = post_residual as f64 - next_item_size as f64;
            score -= 2.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leftover dead space proportionally.
            score += 0.3 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post-residual sits near mean_residual
    // (keeps open bins balanced), but slightly prefer below-mean (denser bins).
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.4 * mean_gap.abs();
    if mean_gap > 0.0 {
        score += 0.2 * mean_gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 25.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when this item
    // would leave a large, hard-to-fill remainder in an existing bin.
    if bin_residual == bin_capacity {
        let waste_threshold = bin_capacity as f64 * 0.5;
        if post_residual as f64 > waste_threshold {
            score -= 15.0; // big item -> better in a fresh bin
        } else {
            score += 20.0; // small item -> keep using open bins
        }
    }

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for fragmenting across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual dominates, but give extra credit
    // when the fit is very tight (small dead space relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Penalize bins whose residual barely changes (item much smaller than
    // residual) -> wasteful placement.
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste * 10.0;

    // Lookahead: if next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the remaining space: penalize leaving
            // a small unusable gap.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make opening a fresh bin mildly attractive
    // only when no open bin offers a good fit (post_residual small).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows slightly with number of bins
        // to discourage bin proliferation, shrinks late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 2.0 * open_bins_count as f64 - 15.0 * progress;

        // If the new bin would fit the next item perfectly too, it's a decent choice.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 6.0;
        }
        // If an existing bin fits nearly perfectly, strongly prefer it.
        if post_residual <= 10 {
            score += 30.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer filling bins down harder (keep score as is); when mean residual
    // is low, slightly favor consolidating into already-sparse bins.
    if bin_residual != bin_capacity {
        let deviation = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += deviation * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 12.0 * (pr_norm * pr_norm) * cap * (0.5 + 0.5 * t);
    score -= 8.0 * (pr_norm * (1.0 - pr_norm)) * cap * (1.0 - t);

    // Penalize large post-residual late in the stream (dead space matters more)
    score += 6.0 * pr_norm * pr_norm * pr_norm * cap * t * t;

    // Reward tight fits: small post_residual strongly subtracted
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = (pr - ni) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - t);
        } else {
            score += 5.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when it creates fresh capacity
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - t) + (open_bins_count as f64).sqrt() * 3.0;
    }

    // Mean residual alignment: prefer bins near mean residual (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * (1.0 - t);

    // Prefer bins with more open bins being consolidated
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "friendly"
    // (divisible by small item classes) are rewarded.
    let cap = bin_capacity as f64;

    // Dead-space penalty: tiny post-residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: post_residual mod small integers.
    let pr = post_residual as i64;
    let nis = next_item_size as i64;
    if nis > 0 {
        if nis <= pr {
            // Next item could fit here: strong reward, scaled by snugness.
            score -= 30.0 + 20.0 * (nis as f64 / (pr as f64 + 1.0));
        } else {
            // Next item cannot follow into this bin: penalize leftover.
            score += 10.0 + 0.25 * (nis - pr) as f64;
        }
        // Harmonic divisibility bonus: post_residual divisible by next item class.
        if nis > 0 && pr % nis.max(1) == 0 && pr > 0 {
            score -= 15.0;
        }
    } else {
        // Last item: prefer perfect closure.
        score -= 50.0 * (1.0 - post_residual as f64 / cap);
    }

    // Integer-division thresholds on post_residual (capacity fractions).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score += 5.0; // small leftover, mild penalty
    } else if post_residual <= half {
        score -= 10.0; // sweet spot: room for mid-size items
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral-ish baseline, but attractive when current
    // bins fit poorly (many fitting bins means we can afford a new bin only
    // if item is large relative to residual).
    if bin_residual == bin_capacity {
        // New bin: score = capacity - item = post_residual, plus penalty
        // unless the item is large or no bin fits well.
        score = cap - item_size as f64;
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else if item_size >= 60 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Progress-aware regularization: late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Coupling with mean residual: prefer bins below mean residual (denser bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Exact fit is heavily rewarded
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Reward using bins with small residual (best-fit flavor)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Last chance: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 20.0 + open_bins_count as f64 * 3.0;
        // But if no open bin fits well, allow new bin late in stream
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is useful
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: item leaves exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead: next item still fits comfortably.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual as f64 / bin_capacity as f64) * 6.0;
    }
    // Lookahead almost fits (small miss): keep bin attractive if it's tight.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 10 {
        score -= 3.0;
    }
    // Penalize big dead space relative to mean residual of open bins.
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for filling bins more completely early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (item_size as f64) * 0.15;

    // Make the new-empty-bin candidate moderately expensive unless it enables
    // a perfect lookahead chain (already discounted above).
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fits are poor or the item is large relative to residuals.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins generally; discount when many bins are open
        // and mean residual is small (fragmented state) or item is big.
        let mut open_penalty = 45.0 - 0.15 * open_bins_count as f64;
        if mean_residual < item_size as f64 {
            open_penalty -= 12.0; // existing bins are too full anyway
        }
        if item_size > 60 {
            open_penalty -= 8.0;
        }
        // Late in the stream, prefer closing out existing bins.
        open_penalty += 20.0 * t;
        // If only one fitting bin exists, strongly discourage new bin.
        if fitting_bins_count <= 1 {
            open_penalty += 60.0;
        }
        // Lookahead: a fresh bin can host next item too.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            open_penalty -= 10.0;
        }
        return open_penalty + post_residual as f64 * 0.1;
    }

    // Tight-fit reward: square-root damping of post_residual.
    score = (post_residual as f64).sqrt() * 3.0;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual that likely can't host future items
    // (items are >= 1, but small residuals under 10 are often unusable).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 3 {
        // Many options: prefer the tightest, amplify discrimination.
        score *= 1.2;
    }

    // Global state: high mean residual means space is abundant; be pickier.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Time horizon: early on, keep bins flexible (penalize very small leftovers
    // less); late, maximize packing density aggressively.
    score *= 1.0 - 0.15 * t;
    if t > 0.8 && post_residual <= 15 {
        score -= 12.0;
    }

    // Small bonus for using bins that are already partially filled
    // (encourages closing bins rather than spreading load).
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear shaping (waste penalized quadratically)
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: early on, waste matters less; later, tighten
    let tighten = 1.0 + 1.5 * progress * progress;
    score *= tighten;

    // Interaction: small post-residual relative to next item is valuable
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = (n - pr).abs();
        let match_bonus = 25.0 * (-gap / (0.25 * cap)).exp();
        score -= match_bonus * (1.0 + progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean (better packing pressure)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many exist
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // (small, or exactly matchable by common item sizes via modulo classes).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Integer-division harmonic classes: residual in [1..10] is prime real estate
        if pr <= 10 { score -= 35.0; }
        else if pr <= 25 { score -= 15.0; }
        else if pr <= 50 { score += 5.0; }
        else { score += 15.0; }

        // Modulo-10 harmonic bonus: residuals divisible by 10 align with item grid
        if pr % 10 == 0 { score -= 8.0; }
        // Residual matching next item exactly is golden
        if next_item_size > 0 && pr == next_item_size { score -= 45.0; }
        // Residual that can host next item: reward proportionally
        if next_item_size > 0 && pr >= next_item_size {
            score -= 12.0 + 10.0 * (next_item_size as f64 / cap);
        } else if next_item_size > 0 {
            // next item cannot fit here; penalize more if residual is large dead space
            score += 6.0 + 10.0 * (pr as f64 / cap);
        }
    }

    // Last chance: only bin that fits -> strong reward to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's clearly better
    if bin_residual == bin_capacity {
        // Base penalty proportional to how many open bins exist
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If next item is huge, a fresh bin is more attractive
        if next_item_size >= 60 { score -= 20.0; }
        // Early in stream, fresh bins are cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer bins with residuals far below mean (tighten tight bins)
        score += 0.3 * (bin_residual as f64 - mean_residual);
        // Slight reward for using older/more populated bins
        score -= 0.5 * open_bins_count as f64;
    }

    // Fractional capacity coupling: favor post_residual near capacity fractions
    let frac = post_residual as f64 / cap;
    if (frac - 0.5).abs() < 0.05 { score += 4.0; } // half-empty is awkward
    if frac < 0.1 { score -= 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..10)
    // are pure waste; penalize heavily any post_residual in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }

    // Perfect fits are gold: subtract a large reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits: the smaller post_residual relative to item size, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Lookahead: if the next item can exactly use this bin's post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 20.0;
        } else if gap_after_next < 10 {
            score += 12.0; // would create dead space for next item
        } else {
            score -= 4.0;
        }
    }

    // If next item cannot fit here but could elsewhere, mild penalty for hogging space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 0.6;

    // New-bin candidate (empty bin): make it attractive only when existing bins
    // would leave bad dead space or mean residual is already low.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a decent existing fit.
        score = 55.0 + (open_bins_count as f64) * 0.3;
        // If item is large, opening fresh is less costly.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If mean residual across open bins is large, prefer reusing them.
        score += mean_residual * 0.35;
        // Last-chance override: never open a new bin when exactly one bin fits.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
        // Late in the stream, avoid proliferating bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 8.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit core).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += residual_gap * 0.2;

    // Mean-residual coupling: if this bin is far below mean residual, it's a poor fit.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: early in stream, prefer keeping bins tight; later, be more flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward exact match between post_residual and next item ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match -> strong bonus (subtracted from score).
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0) * (1.0 - progress * 0.3);

        // If next item cannot fit here after placement, penalize leaving a "dead" residual
        // that is smaller than the minimum useful size.
        if post_residual < next_item_size {
            // Dead space penalty grows as residual becomes unusably small.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 35.0 * dead * (1.0 - progress * 0.5);
        }

        // If the next item fits exactly after this placement, extra reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // --- Relative to mean residual: placing in a bin whose residual is near the mean
    // keeps the fleet balanced; bins with large residual are better "hosts". ---
    let resid_f = bin_residual as f64;
    let mean_gap = (resid_f - mean_residual).abs();
    score += 0.25 * mean_gap;

    // Penalize bins that are already loose (large residual) slightly more when many bins are open.
    score += 0.10 * resid_f * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // --- Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 50.0 * (0.5 + 0.5 * tightness);
    }

    // --- New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is attractive only when the resulting placement is very tight
    // (item fills most of a fresh bin) or when the current fit is poor. ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Reward opening a new bin for large items (tight initial fit).
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 70.0 * fill * fill;
        // If no other bin fits well (post_residual here would be small in an existing bin,
        // but for the new bin post_residual is large), compare against next item need:
        if next_item_size > 0 && post_residual >= next_item_size {
            // New bin can host the next item too -> mild bonus.
            score -= 10.0;
        }
    }

    // --- Tight fit reward: small post_residual means little waste, generally good,
    // unless it creates dead space handled above. ---
    score -= 0.15 * (bin_capacity - post_residual) as f64 * 0.0; // neutralized; waste already in base

    // Small tie-breaking noise-free coupling with step to diversify choices.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum plausible item size is pure waste.
    let dead = post_residual.min(10) as f64;
    score += dead * 3.0;

    // Lookahead: if the next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + (next_item_size as f64) * 0.4;
        } else {
            // Penalize leaving a residual that blocks the next item
            score += (post_residual as f64).min(next_item_size as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // But if mean residual is small (open bins nearly full), new bin is fine.
        score -= mean_residual * 0.15;
    } else {
        // Slight preference for fuller bins (small residual) among open bins.
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Waste ratio: penalize residuals that are a large fraction of capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = t.clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let rn = r / cap;
    let fit_n = (item_size as f64) / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - t) * (rn * rn) + t * (rn * rn * rn * rn);
    score += 4.0 * poly * cap * (0.5 + fit_n);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - rn;
    score -= (2.0 + 4.0 * t) * tightness * tightness * fit_n;

    // Penalize when this bin's residual deviates from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev * (1.0 + t);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 8.0 * t * tightness;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 && (next_item_size as u64) <= post_residual as u64 {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 2.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - t);
    } else if next_item_size > 0 {
        score += 1.5 * t;
    }

    // Mild penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * rn * (1.0 - t);

    // New-bin candidate: keep it slightly unattractive unless residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0).min(1.0);
        score += 1.0 + 3.0 * (1.0 - frag) - 2.0 * t * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: residues near multiples of 5/10 are
    // more reusable by future items (sizes 1..100 often cluster on round numbers)
    let r10 = post_residual % 10;
    let r5 = post_residual % 5;
    if r10 == 0 {
        score -= 12.0;
    } else if r5 == 0 {
        score -= 6.0;
    } else {
        // penalize awkward residues
        score += 4.0 + (r5 as f64);
    }

    // Lookahead coupling: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward small leftover relative to next item
            score -= 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Integer-division threshold on bin_residual: bins with residual in
    // (50, 100] are "half-full or less"; prefer filling those first
    let half = bin_capacity / 2;
    if bin_residual <= half {
        score -= 8.0;
    } else {
        score += (bin_residual - half) as f64 * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score += 10.0;
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference to balance against mean residual (avoid leaving
    // many bins with large residuals while others are nearly full)
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space that cannot hold the lookahead item is penalized.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward residuals that can accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.3 * next_item_size as f64;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Tight fit bonus relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin before opening a new one gets a reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if all open bins are nearly full.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * mean_residual.max(0.0);
        if mean_residual >= 35.0 {
            score -= 30.0;
        }
    }

    // Penalize leaving residuals far from mean (fragmentation risk).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted potential
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Reward tight fits relative to capacity (low post_residual waste)
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Penalize if post_residual is dead space (too small for any typical item)
    if post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins whose residual is above mean
    // (keeps tight bins tight, uses loose bins)
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual).min(50.0);
    } else {
        score += (mean_residual - post_residual as f64).min(50.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when
    // no open bin offers a good fit, but more so late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 150.0 + 100.0 * progress;
        // If next item is large and current item is small, new bin may be fine
        if next_item_size > 60 && item_size < 30 {
            score -= 80.0;
        }
    }

    // Slight penalty for many open bins (consolidate when possible)
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that is too small to ever hold a typical future item,
    // but leave residuals that can hold mid-size items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving post_residual that can pair with the
    // next item exactly; penalize residuals that just barely miss it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Global pressure: many open bins with small mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 0.0 {
        let consolidation = (mean_residual - post_residual as f64) / mean_residual;
        score += 10.0 * consolidation * (1.0 - progress);
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // bins are nearly full or none fit well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_fill = (bin_capacity as f64 - mean_residual).max(0.0);
        let pressure = avg_fill / bin_capacity as f64;
        score += 45.0 + 30.0 * (1.0 - pressure);
        // Late in the stream, prefer squeezing into existing bins even more.
        score += 20.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Mild reward for keeping the number of open bins stable when bins are sparse.
    if !is_new_bin && open_bins_count > 0 {
        score -= 2.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: waste left behind, with non-linear (quadratic/cubic) penalty on small residuals
    let mut score = pr
        - 18.0 * norm_pr * (1.0 - norm_pr) * cap          // reward mid-range residuals
        + 30.0 * norm_pr * norm_pr * norm_pr * cap;        // penalize tiny dead space cubically

    // Smooth coupling with stream progress: tolerate waste early, avoid it late
    score += 25.0 * progress * norm_pr * norm_pr * cap;
    score -= 12.0 * (1.0 - progress) * norm_item * norm_pr * cap;

    // Lookahead: reward residual that fits next item (smoothly)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit = if pr >= nx { 1.0 - (pr - nx) / cap } else { (nx - pr) / cap };
        score -= 15.0 * fit * fit;
        score += 10.0 * (1.0 - fit) * (1.0 - fit);
    }

    // Scarcity pressure: penalize when few fitting bins, smooth in fitting_bins_count
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score += 20.0 * scarcity * norm_item;

    // Mean residual alignment: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Congestion: many open bins -> prefer tighter packing
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "coarse" classes (large unusable gaps) are less valuable; prefer bins
    // whose post_residual belongs to fine-grained, reusable classes.
    let post = post_residual;
    let class = post / 10; // coarse class of leftover
    let residue = post % 10; // fine residue within class

    // Reward small leftovers strongly (best-fit core with harmonic shaping).
    score += (class as f64) * (class as f64) * 0.35;

    // Fine residue: leftovers just above common small-item sizes (10..=20)
    // are recoverable; leftovers in dead zones are penalized.
    if residue > 0 && residue < 5 {
        score -= 2.0; // near-miss gap, likely recoverable by small items
    } else if residue >= 5 {
        score += 1.5; // awkward dead zone
    }

    // Perfect or near-perfect fits are golden.
    if post == 0 {
        score -= 60.0;
    } else if post <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement creates a chainable bin — reward it.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size < post {
            let slack = post - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item won't fit here; residual becomes dead space unless small
            if post > 0 && post < 10 {
                score += 6.0; // stranded micro-gap
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and current bins fit poorly.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // Base cost of a fresh bin: proportional to how much space would remain.
        score = post_residual as f64 + 55.0;
        // Large items deserve fresh bins more often.
        score -= 45.0 * fill_frac * fill_frac;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Many open bins with slack: discourage another bin.
        score += (open_bins_count as f64).sqrt() * 3.0;
        score += (mean_residual / cap) * 20.0;
        // If lookahead item is huge, a fresh bin pairs well with it.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins when many are open (bin-count pressure).
    score += (open_bins_count as f64) * 0.15;

    // Tiny tie-breaker toward earlier-created (likely fuller) bins.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // are worthless — punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 120.0;
    } else {
        // Reward tight fits quadratically.
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 40.0 * tightness * tightness;
    }

    // If the next item can exactly use the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 70.0;
        } else {
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's leftover: mild penalty.
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate logic: only attractive when no open bin is a decent fit
    // (i.e., many fitting bins means reuse is fine; keep new bin expensive).
    if bin_residual == bin_capacity {
        let base = 35.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score = base + 25.0; // last chance exists; prefer it
        } else {
            score = base;
        }
    }

    // Progress-aware mean-residual coupling: late in the stream, prefer bins
    // whose residual is close to the mean (balanced packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact-ish fits: post_residual small relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let match_quality = 1.0 - ((post_residual as f64) - nxt) / (bin_capacity as f64);
            score -= 2.5 * match_quality * match_quality;
        } else {
            // Next item can't follow into this bin: penalize proportionally to wasted lookahead.
            score += 0.5 * (nxt - post_residual as f64) / 100.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (denser bins).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * (open_bins_count as f64);
    }

    // Late in the stream, consolidate: penalize spreading across many bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 0.05 * progress * (post_residual as f64) * (open_bins_count as f64).ln().max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit is better, but reward is nonlinear.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: leftover space that cannot hold the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Later in the stream, dead space matters less (fewer future chances to use it).
        score += waste * (0.6 + 1.4 * (1.0 - progress));
    }

    // Reward leaving exactly enough room for the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Slack for lookahead is mildly good, diminishing with excess.
        score -= 3.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one closest to mean residual (balance).
        score += 0.15 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Penalize opening new bins when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 10.0 + 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // Exception: if item is huge relative to capacity, opening fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 6.0;
        }
        // If no existing bin fits well (item nearly fills bin), new bin is attractive.
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Mild time-horizon term: early stream, be conservative with bin openings.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * progress; // later items may justify new bins more readily
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let p = progress;
    // Weight small residuals more heavily as stream progresses (tighten packing late).
    let tight = 1.0 + 2.0 * p * p;
    score += tight * pr_norm * pr_norm * cap * (0.5 + p);

    // Reward near-perfect fits smoothly.
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * fill * (1.0 + p);

    // Penalize dead space that no plausible next item could use.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 0.05 * gap * gap / cap;
        } else {
            // Bin can host the next item: smooth reward.
            score -= 3.0 * (1.0 - gap.abs() / cap);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + p);
    }

    // Mild pressure against hoarding many open bins early.
    score += 0.2 * open_bins_count as f64 * pr_norm * p;

    // New-bin candidate: prefer it only when it enables a much better future fit.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * p - (next_item_size as f64 / cap) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (min size 1, but practically small gaps waste capacity).
    // Penalize gaps in the "unusable zone" [1, 12] extra heavily.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 - (post_residual as f64) * 4.0; // tiny gaps are worst
    } else if post_residual == 0 {
        score -= 45.0; // perfect fit is the ideal outcome
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when the item fits poorly everywhere else or no bins exist.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual > 40);
        if poor_fit_elsewhere {
            score -= 25.0;
        } else {
            score += 40.0; // discourage opening a new bin when a decent fit exists
        }
    }

    // Lookahead: if the next item could exactly fill this bin's post_residual,
    // reward keeping this gap; if next item cannot fit the gap, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: bins far below mean residual are underfilled;
    // prefer bins whose residual is close to (or below) the mean.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev.max(0.0);

    // Late in the stream, tighten up: dead space matters more near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 25.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 200.0;
        } else {
            // Penalize mismatch, scaled by how far the next item is from fitting
            score += (diff as f64).powf(1.3) * 0.5;
        }
        // If next item can't fit anywhere after this placement, mild bonus for compacting
        if next_item_size > post_residual && post_residual < 10 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless item is large relative to capacity
    // (i.e., opening a new bin is only good for big items or very poor fits elsewhere)
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * big_item;
        // If no open bin fits well (post_residual large elsewhere), new bin is attractive
        if post_residual as f64 > mean_residual * 0.8 {
            score -= 20.0;
        }
    }

    // Penalize creating dead space below typical minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Late in stream: consolidate, avoid spreading across bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal wasted space, with diminishing returns on very small residuals.
    score = (score * (1.0 + 0.004 * post_residual as f64)).sqrt() * 4.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residuals too small for any plausible future item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.25 * next_item_size as f64;
        } else {
            score += 6.0;
        }
        // Chain fit: post residual exactly matches next item -> very desirable.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins
    // are heavily fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0 + 2.0 * open_bins_count as f64;
        // Attractive when existing residuals are large (wasteful state) but item is big.
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fit_quality > 0.7 {
            score -= 30.0 * fit_quality;
        }
        // Early in the stream, opening bins is cheaper (builds a diverse pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
        // If mean residual is high, spread load into a fresh bin.
        if mean_residual > item_size as f64 + 30.0 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (tight packing).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * tightness * tightness;
        // Slight preference for bins below mean residual (balance residuals).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Time horizon: late in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.15;

    // Mild stochastic-free tie-breaking via bin index proxy (residual parity).
    score += (bin_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
