    let pr = post_residual as f64 / cap; // in [0,1)
    let tightness = 1.0 - pr; // high when bin nearly filled

    // Polynomial coupling: reward tight fits super-linearly, scaled by progress
    // (tight packing becomes more valuable as the stream progresses)
    let fit_reward = (tightness * tightness * tightness) * (30.0 + 50.0 * progress);
    score -= fit_reward;

    // Penalize large dead space quadratically (unusable gap)
    let dead = pr * pr;
    score += dead * cap * 0.6;

    // Lookahead coupling: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = (post_residual as f64 - nxt) / cap;
            // good lookahead fit: small slack after next placement
            score -= (1.0 - slack) * 12.0 * (1.0 - progress * 0.5);
        } else {
            // next item won't fit here: penalize proportionally to overflow
            let over = (nxt - post_residual as f64) / cap;
            score += over * 18.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    // Prefer opening a new bin only when existing fits are poor (large post_residual)
    // and many bins are already open (encourage consolidation early on).
    if bin_residual == bin_capacity {
        let open_factor = (open_bins_count as f64).ln().max(1.0);
        // early stream: opening bins is fine; late stream: penalize new bins
        let base = cap * 0.55 + 20.0 * (1.0 - progress) - 8.0 * open_factor.min(3.0);
        score = score.max(0.0) + base;
    }

    // Mild consolidation pressure: prefer bins with residual close to mean residual
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets penalize "awkward" leftovers
    let pr = post_residual;
    let class = pr % 10;
    score += match class {
        0 => -6.0,                       // perfect multiple: highly reusable
        1 | 2 | 3 => 2.5,                // tiny slivers: near-dead space
        4 | 5 | 6 => 0.5,
        _ => -1.0,                       // mid-range leftovers still useful
    };

    // Lookahead harmony: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;               // perfect follow-up fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no
    // open bin offers a tight fit
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // base cost of a fresh bin, discounted when item is large
        score = cap as f64 * (1.0 - 0.6 * tightness);
        if fitting_bins_count == 0 {
            score -= 40.0;               // nothing fits anywhere: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;                // stacking similar/large items together
        }
    } else {
        // reward tight fits into existing bins
        let fill = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill;
    }

    // Mean-residual coupling: when open bins are already spacious,
    // discourage fragmenting them with loose fits
    if bin_residual != bin_capacity {
        let frag = (post_residual as f64 - mean_residual).abs();
        score += 0.1 * frag;
    }

    // Mild stream-position pressure: late in the stream, be greedier
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized,
    // since they can never host any realistic item.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }
    // Perfect fit: post_residual == 0 -> strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual >= 13 {
        // Usable residual: mild reward proportional to usefulness of the gap.
        score -= 10.0;
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * pressure * (1.0 - fill_ratio);

    // Lookahead: if next item fits in the post residual, reward; if not,
    // penalize leaving a gap that wastes space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is already "tight" -> favor completing it.
    let residual_dev = mean_residual - bin_residual as f64;
    score += residual_dev * 0.3;

    // New-bin candidate: default mild preference early, penalized when many
    // bins are open or the item fits well elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * pressure + 15.0 * fill_ratio;
    }

    // Stream progression: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect match for next item is highly desirable.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize large leftover after the imagined next placement (dead space).
            score += 0.35 * slack;
        } else {
            // Next item won't fit here after this placement: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // Last item: just prefer tightest fit.
        score += 0.1 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far above mean are attractive targets.
    score -= 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are already open (encourage consolidation).
    score += 0.15 * open_bins_count as f64;

    // Stream progression: later in the stream, be slightly more conservative
    // about leaving large residuals (fewer chances to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    // New-bin candidate: neutral baseline; only chosen if no decent fit exists.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 3.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here blocks a bin that could have fit the next item
            score += 2.0;
        }
        // exact pairing bonus
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item is large and fits nowhere well.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0;                       // base cost of opening a new bin
        score -= 4.0 * crowding.min(6.0);    // cheaper when existing bins are full-ish
        score -= 5.0 * progress;             // slightly cheaper late in the stream
        if item_size > 60 {
            score -= 6.0;                    // large items justify fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;                    // room to pair the next item in a fresh bin
        }
    }

    // Mild preference for bins below the mean residual (balance across bins).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Small penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_n = post / cap;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    let base = post * (0.5 + progress);

    // Non-linear interaction: squared normalized post residual scaled by progress
    let quad = post_n * post_n * cap * (0.25 + 0.75 * progress);

    // Tight-fit reward: strong bonus when post_residual is small relative to item
    let tight = -(item_size as f64 / cap) * (cap - post) * (0.5 + progress);

    // Lookahead coupling: reward if next item fits well into post_residual
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            -1.5 * (nx / cap) * (1.0 - (post - nx) / cap)
        } else {
            0.5 * ((nx - post) / cap) * (1.0 + progress)
        }
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    let last_chance = if fitting_bins_count == 1 { -8.0 } else { 0.0 };

    // New-bin candidate handling: only attractive when open bins are crowded/poor fits
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        let mean_n = mean_residual / cap;
        // cheaper to open a new bin when existing residuals are large relative to item
        let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
        6.0 + 10.0 * (1.0 - mean_n) + 4.0 * crowding - 12.0 * (item_size as f64 / cap)
    } else {
        0.0
    };

    // Mean residual alignment: penalize bins deviating from mean residual (fragmentation control)
    let dev = (post - mean_residual).abs() / cap;
    let dev_pen = 2.0 * dev * dev * cap * (0.3 + 0.7 * progress);

    base + quad + tight + lookahead + last_chance + new_bin_penalty + dev_pen
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    // Perfect-fit classes: residuals that are "friendly" sizes (multiples of 10/25/50)
    let harmonic_bonus: f64 = if pr == 0 {
        -80.0 // perfect fit is ideal
    } else if pr % 50 == 0 {
        -30.0
    } else if pr % 25 == 0 {
        -20.0
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward residual, penalize
    };
    score += harmonic_bonus;

    // Integer-division thresholds: large vs small residual buckets
    let class = pr / 25; // 0..4 harmonic class
    score += match class {
        0 => -15.0,           // tiny residual: excellent packing
        1 => -5.0,
        2 => 0.0,
        3 => 6.0,
        _ => 10.0,            // nearly empty bin left: wasteful
    };

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - 0.15 * slack; // next item fits: strong reward
            // harmonic match: next item leaves a friendly residual too
            let nr = pr - next_item_size;
            if nr % 10 == 0 { score -= 10.0; }
        } else {
            score += 5.0 + 0.1 * (next_item_size - pr) as f64;
        }
    } else {
        // Last item: only perfect fits matter
        score -= 10.0 * (pr == 0) as i32 as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: mild penalty for spreading too thin when residuals are large
    if fitting_bins_count > 2 && post_residual as f64 > 0.6 * cap {
        score += 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (residual after placement would be small) or
    // when the stream is young and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        let waste = post_residual as f64; // = cap - item_size
        score += 20.0                        // base cost of opening a bin
               - 30.0 * scarcity             // early stream: new bins cheap
               - 15.0 * (1.0 - progress)     // prefer fresh bins early
               + 0.3 * waste;                // penalize big leftover space
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0; // fresh bin can also host next item
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already "tight"; prefer filling tight bins first.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Small tie-breaking on tightness ratio
    score += 0.05 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are unusable for any item
    // (min item size 1 in this interface, but practically 10 in the base setting).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // heavy penalty for creating dead space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to capacity (low waste ratio)
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 20.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow opening new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 40.0 * progress);
    score += pressure * 3.0;

    // Mean residual coupling: penalize bins far below mean residual (fragmenting),
    // mildly reward bins near the mean (keeps residuals homogeneous).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * (diff * diff).sqrt().signum() * diff.abs().min(50.0);

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score += 20.0; // next item would leave dead space here
        }
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 2.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit: dead space penalty scaled by dead space size
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Penalize unusable dead space (below minimum plausible item size)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current fits are poor
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.15 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference for fuller bins relative to fleet mean residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild exploration pressure as stream progresses
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large post-residual relative to typical item sizes (dead space).
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 25.0 * dead * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * chain_quality;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many open bins have plenty of room.
    if bin_residual == bin_capacity {
        let avg_room = mean_residual / bin_capacity as f64;
        score += 5.0 + 30.0 * avg_room * avg_room + open_bins_count as f64;
        // But if nothing else fits well, allow new bin: handled by fitting count logic above.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Time horizon: early in the stream, be more conservative (keep bins open for future);
    // later, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balanced packing) slightly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post_residual). Late stream: waste hurts more,
    // so the polynomial steepens with progress.
    let p = 1.0 + 2.0 * progress;
    let mut score = (x.powf(1.0 + p) * cap * (1.0 + progress)) + x * 10.0;

    // Reward filling bins well (low post residual) with a smooth coupling to mean residual:
    // placing here is better if it brings this bin below the mean residual (consolidation).
    let mean_x = mean_residual / cap;
    score -= (1.0 - x).powi(2) * 20.0;
    score += (x - mean_x).abs() * 5.0;

    // Lookahead coupling: if the next item fits in the post residual, reward it smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 15.0 * fit_quality * (1.0 - progress * 0.5);
        } else {
            // penalize leaving a gap that blocks the next item, smoothly scaled by gap size
            score += ((pr - nxt) / cap) * 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are very poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
        // allow new bin if all existing fits would leave large dead space
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual by capacity fraction bands.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;

    // Dead-space penalty: residuals too small to hold the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Penalize residuals in "awkward" bands (just above common item sizes)
    for threshold in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
        if pr > threshold && pr <= threshold + 8 {
            score += 12.0;
        }
    }

    // Lookahead pairing: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item fits with small leftover
            let next_left = post_residual - next_item_size;
            score -= 30.0 - (next_left as f64) * 0.5;
        } else {
            // next item won't fit here; residual is likely dead space
            score += (next_item_size as f64 - pr) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: mild penalty so it's chosen only when open bins look bad
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
        // early stream: prefer filling bins, later: allow opening
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    // Prefer bins with residual close to item size (tight fit) — quadratic coupling
    let tightness = (bin_residual as f64 - item_size as f64) / c;
    score += tightness * tightness * 20.0;

    // Slight preference for bins below mean residual (consolidate fullness)
    score += (mean_residual - pr) * 0.05;

    // Modulo-class bonus: residuals that are multiples of 10 pair well with common sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Penalize opening many bins when open count is low relative to progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (open_bins_count as f64) < progress * 10.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Dead space relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Open bins pressure: discourage spreading when many bins are open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= post_residual.min(bin_residual) {
            score += 15.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // Prefer larger residual bins slightly when residuals are scarce
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    }

    // Stream progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward for near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 / post.sqrt();
    }

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 25.0 + 0.5 * next;
            // Bonus if next item fills the bin completely after placement.
            if (post - next).abs() < 1.0 {
                score -= 80.0;
            }
        } else {
            // Penalize leaving a residual that the next item cannot use
            // relative to mean residual (dead space).
            let waste = post - (mean_residual.min(post));
            score += 0.3 * waste;
        }
    }

    // Penalize creating unusable slivers: residual too small for typical items.
    if post > 0 && post < 10.0 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // (mean residual low relative to item size) or many bins already open.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded || open_bins_count > 20 {
            score += 5.0; // keep default preference low
        } else {
            score += 120.0; // discourage opening unnecessary bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // This placement destroys the ability to host next item; penalize mildly.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Fragmentation pressure: if open bins carry lots of residual, prefer filling them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 30.0 {
        score -= mean_residual * (0.3 + 0.4 * progress);
    }

    // Penalize opening new bins when many bins already exist (consolidate).
    if bin_residual == bin_capacity {
        let open_penalty = 30.0 + 6.0 * open_bins_count as f64;
        // But if no bin fits well, new bin becomes attractive.
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && fit_ratio < 0.55 && item_size >= 50);
        if poor_fit_elsewhere {
            score -= open_penalty * 0.9;
        } else {
            score += open_penalty;
        }
    }

    // Time horizon: early on, be picky (prefer near-perfect fits); later, just pack.
    score -= 20.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Base: penalize leftover space, with non-linear (quadratic) waste growth.
    let mut score = post + (post * post) / cap;

    // Smooth stream-progress coupling: waste becomes more costly as stream advances.
    let progress_coupling = 1.0 + 0.6 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: item filling most of the bin (post_residual small relative to capacity).
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Reward leaving a residual that exactly matches the next item (perfect lookahead fit).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when plenty of bins could fit the item.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild penalty for hoarding many open bins with large residuals vs mean.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // Small bonus for placing into bins with small current residual (consolidation).
    score += 0.3 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residual below the minimum item size is unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Coupling: penalize moderate leftovers that no small item may exploit.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: reward leaving space that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let base = 40.0 + 3.0 * open_bins_count as f64;
        // Penalize new bin if the item would leave a large gap anyway.
        score = base + (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
        if fitting_bins_count == 1 {
            score += 150.0; // keep the sole fitting bin for flexibility
        }
    }

    // Late-stream tightening: waste less as stream nears completion.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Mild preference for bins tighter than the mean residual.
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this bin is a great chain target.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            // Reward if next item fits, scaled by how compact the result stays.
            score -= 150.0 - (leftover_after_next as f64 * 1.5);
        } else {
            // Next item won't fit here: penalize leaving awkward medium gaps
            // that are hard to fill later.
            let gap = post_residual as f64;
            if gap < 20.0 {
                score += (20.0 - gap) * 8.0;
            }
        }
    } else {
        // Last item: pure waste minimization.
        score -= 300.0;
    }

    // Relative-to-mean adjustment: bins with residual already below the mean
    // are "tight" bins; prefer filling them to consolidate space.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.8;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and no open bin offers a good fit. Penalize opening new bins
    // for small items.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let best_open = if fitting_bins_count > 0 { 0.0 } else { 1.0 };
        score += 250.0 - size_ratio * 200.0 + best_open * 100.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 60.0;
    }

    // Mild preference for keeping the number of open bins bounded.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space (wasted capacity).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.35;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving residual too small to be useful.
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strong preference to use it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Crowding: with many open bins, prefer filling existing ones.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= 6.0 * crowding * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // New-bin candidate logic: only attractive early or when current bin fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = fit_ratio < 0.55;
        if bad_fit && (progress > 0.25 || post_residual as f64 > 0.0) {
            score -= 30.0;
        } else {
            score += 40.0;
        }
        // Opening a new bin wastes residual in others when many bins are open.
        score += open_bins_count as f64 * 2.0;
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let fit_ratio = (item_size as f64) / (bin_residual.max(1) as f64);

    // Base: minimize post residual (tight fit preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are less costly; late, they become increasingly penalized.
    let progress_coupling = pr * pr / cap * (0.5 + progress);
    score += 0.35 * progress_coupling;

    // Reward high fill ratio (item occupies most of the residual) with smooth saturating term
    score -= 12.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Penalize creating dead space: residual too small for typical future items
    let dead_zone = ((20.0 - pr) / 20.0).max(0.0);
    score += 15.0 * dead_zone * dead_zone * (0.4 + progress);

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin unless post residual is large enough
    // to plausibly host future items, with smooth logistic-like gate.
    if bin_residual == bin_capacity {
        let open_penalty = 8.0 + 6.0 * (1.0 - progress);
        let gate = 1.0 / (1.0 + (-(pr - 45.0) / 12.0).exp());
        score += open_penalty * (1.0 - gate);
        // If no open bin fits, opening is necessary: soften penalty
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Lookahead: bonus if post residual can still fit the next item
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
        } else {
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // Mild pressure against bin sprawl
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: prefer bins whose residual differs from mean
    // (balance load across bins) with smooth quadratic term
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Fraction of capacity wasted after placement.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Residuals that are very small (<10) are dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals in "useful" classes (>= next item's size, or mid-range) rewarded.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong reward.
            score -= 25.0 + (next_item_size as f64) * 0.2;
        } else {
            // Dead space relative to lookahead item.
            score += 15.0;
        }
        // Harmonic coupling: exact modular match between residual and next item.
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 20.0;
        }
    }

    // Reward filling bins tightly (large item relative to residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: prefer the one with the smallest residual (already via score base),
    // but mild extra pressure to consolidate.
    if fitting_bins_count > 1 {
        score -= 5.0;
    }

    // New-bin candidate: penalize unless current situation is desperate
    // (no good fits among open bins or many open bins with high mean residual).
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 1.2 && open_bins_count > 0);
        if desperate {
            score -= 45.0;
        } else {
            score += 50.0 + 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Slight early-stream preference to open bins and spread load.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are "dead". Penalize them super-linearly.
    if post_residual > 0 {
        let dead_threshold = 10u32;
        if post_residual < dead_threshold {
            // Unusable sliver: heavy penalty proportional to how close to zero.
            score += (dead_threshold - post_residual) as f64 * 12.0;
        } else {
            // Usable leftover: mild reward for larger usable gaps.
            score -= (post_residual as f64).sqrt() * 2.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Tightness reward: fraction of the residual consumed by this item.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins. Penalize proportional to open bins and mean residual, but
    // relax pressure as the stream progresses (end-game consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = open_bins_count as f64 * mean_residual * 0.15;
        score += waste * (1.0 - 0.5 * progress) + 30.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement (chain fit). Otherwise, if next item is large and
    // this placement strands a big residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing bins rather than spreading.
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on dead space (quadratic in fraction of capacity).
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * frac * frac;

        // 2-step lookahead: reward bins whose post_residual matches next item.
        if next_item_size > 0 {
            let gap = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 + 25.0 // can't fit next item: mild penalty
            };
            score += 0.8 * gap;

            // Exact lookahead match: big bonus.
            if post_residual == next_item_size {
                score -= 300.0;
            }
            // Next item fits snugly after this placement.
            if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
                score -= 120.0;
            }
        }
    }

    // Compare against mean residual: prefer bins that are more filled than average.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= 0.5 * mean_gap;
    } else {
        score += 0.3 * (-mean_gap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize slightly unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let base = 30.0;
        let crowding = if open_bins_count == 0 { 0.0 } else { 5.0 * (open_bins_count as f64).ln() };
        // If few fitting bins, opening new bin is more attractive (lower the penalty).
        let fit_relief = 12.0 * (fitting_bins_count as f64).min(4.0);
        score += base + crowding - fit_relief;
        // If lookahead item is large and this fresh bin can host both, encourage opening.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Early in stream: be slightly conservative (favor tight packing exploration).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}
